# ==========================================
# Semantic networks and Agents
# ==========================================
function create_network(n, m, utilities=ones(Float32, n))
    """
    Generates a Semantic network of 'n' words based on the Steyvers-Tenenbaum model A.
    # Arguments
    - `n`: Total number of nodes (words) in the network.
    - `m`: Number of connections each new node forms.
    - `utilities`: (Optional) Vector of Float32 representing the inherent utility of each node.
    # Returns
    - An n x n Float32 matrix representing the undirected adjacency network.
    """
    function get_word(degrees, size)
    """
    Selects a node ('word') from the existing network (1:size) with a probability
    proportional to its current degree (Preferential Attachment).
    
    # Arguments
    - `degrees`: Vector of current node degrees.
    - `size`: The current number of nodes in the network (i-1 in the main loop).
    
    # Returns
    - A randomly selected node index (Int).
    """
    return sample(1:size, Weights(degrees[1:size]))
    end
    function make_contact(network, utilities, word, size, m)
        """
        Selects 'm' neighboring nodes of a chosen 'word' node to form new connections.
        The selection probability for neighbors is based on their pre-defined 'utilities'.
            
        # Arguments
        - `network`: The current adjacency matrix.
        - `utilities`: Vector of inherent attractiveness scores for each node.
        - `word`: The central node (word) selected in the previous step.
        - `size`: The current number of nodes.
        - `m`: Number of connections to make.
            
        # Returns
        - A vector of 'm' unique node indices (Int) to connect to.
        """
        neighbors = findall(!iszero, view(network, 1:size, word))
        probabilities = utilities[neighbors]
        return sample(neighbors, Weights(probabilities), m, replace=false)
    end
    network = zeros(Float32, n, n)
    network[1:m, 1:m] .= 1f0
    degrees = fill(Float32(m - 1), n)
    for i in m+1:n
        word = get_word(degrees, i - 1)
        words = make_contact(network, utilities, word, i - 1, m)
        @inbounds for w in words
            network[w, i] = 1f0
            network[i, w] = 1f0
            degrees[w] += 1f0
        end
        network[i, i] = 1f0
        degrees[i] = Float32(m)
    end
    network[diagind(network)] .= 0f0
    return network
end
function make_agents_with_outliers(num, n, m, change;
    utilities=ones(Float32, n),
    outliers_count::Int=0,
    outlier_change::Union{Nothing,Float64}=nothing)

    """
    Generates a 3D array of 'num' participant networks. Each network is based on a shared
    'base_network' but randomized after a certain fixed point, introducing heterogeneity.

    # Arguments
    - `num`: Total number of participants to generate.
    - `n`: Total number of nodes (words) per network.
    - `m`: Number of connections each new node forms (used in network creation).
    - `change`: The proportion of words whose connections are randomized (1 - fixed_ratio).
    - `outliers_count`: (Optional) Number of outlier participants (taken from the last indices).
    - `outlier_change`: (Optional) Change value for outliers. Must be >= `change`.
    - `utilities`: (Optional) Node utilities passed to create_network.

    # Returns
    - An n x n x num Float32 array, where each slice is a participant's semantic network.
    """
    function check()
        if outliers_count < 0
            error("outliers_count must be >= 0")
        end
        if outliers_count > num
            error("outliers_count must be <= num")
        end
        if outliers_count > 0 && outlier_change === nothing
            error("outlier_change must be provided when outliers_count > 0")
        end
        if outliers_count > 0 && outlier_change < change
            error("outlier_change must be >= change")
        end
    end
    check()

    base_network = create_network(n, m, utilities)
    participants = Array{Float32,3}(undef, n, n, num)

    fixed_nodes = round(Int, n * (1 - change))
    outlier_fixed_nodes = outliers_count > 0 ? round(Int, n * (1 - outlier_change)) : fixed_nodes

    function build_partial_network(fixed_words::Int)
        new_net = zeros(Float32, n, n)
        new_net[1:fixed_words, 1:fixed_words] .= base_network[1:fixed_words, 1:fixed_words]
        degrees = zeros(Float32, n)

        degrees[1:fixed_words] .= vec(sum(
            new_net[1:fixed_words, 1:fixed_words],
            dims=2
        ))
        new_net[diagind(new_net)] .= 1f0
        for i in fixed_words+1:n
            word = sample(1:i-1, Weights(degrees[1:i-1]))
            neighbors = findall(!iszero, view(new_net, 1:i-1, word))
            probabilities = utilities[neighbors]
            contacts = sample(neighbors, Weights(probabilities), m, replace=false)
            for w in contacts
                new_net[w, i] = 1f0
                new_net[i, w] = 1f0
                degrees[w] += 1f0
            end
            new_net[i, i] = 1f0
            degrees[i] = Float32(m)
        end
        new_net[diagind(new_net)] .= 0f0
        return new_net
    end

    for j in 1:num
        if outliers_count > 0 && j > num - outliers_count
            participants[:, :, j] .= build_partial_network(outlier_fixed_nodes)
        else
            participants[:, :, j] .= build_partial_network(fixed_nodes)
        end
    end

    return participants
end
function differences(A::AbstractArray{Float32,3})::Matrix{Float64}
    """
    Calculates the Total Variation Distance (TVD), or Normalized Manhattan Distance, 
    between all pairs of semantic networks stored in the 3D array 'A'. 
    The calculation is performed in parallel.
    The formula computed is 0.5 * sum(|A_i_j/sum(A) - B_i_j/sum(B)|).
    
    # Arguments
    - `A`: A 3D array (n x n x num_participants) containing the semantic networks.
    # Returns
    - A symmetric matrix (num_participants x num_participants) of Float64 distances.
    """
    @assert ndims(A) == 3
    n, _, num = size(A)
    sums = [sum(Float64, @view A[:, :, k]) for k in 1:num]

    @assert all(sums .> 0)

    invs = 1.0 ./ sums
    D = Matrix{Float64}(undef, num, num)

    @inbounds for i in 1:num
        D[i, i] = 0.0
    end
    Threads.@threads for i in 1:num-1
        Ai = @view A[:, :, i]
        invA = invs[i]
        for j in i+1:num
            Aj = @view A[:, :, j]
            invB = invs[j]
            acc = mapreduce(k -> abs(invA * Ai[k] - invB * Aj[k]),
                +,
                eachindex(Ai))
            d = 0.5 * acc
            @inbounds begin
                D[i, j] = d
                D[j, i] = d
            end
        end
    end

    return D
end

# ==========================================
# The World
# ==========================================

mutable struct World
    W::Int
    H::Int
    N::Int

    # Positions
    x::Vector{Int}
    y::Vector{Int}
    occ::Matrix{Int}  # occ[row, col] = agent id, 0 if empty

    # Conversation state (pairwise only)
    talking_group::Vector{Int}  # 0 if none, else group id
    talk_left::Vector{Int}        # remaining turns in conversation (meaningful if talking_partner!=0)

    agent_seen_partners::Vector{Set{Int}}
    next_group_id::Int

    # Refractory: can be with multiple partners
    refr_partners::Vector{Vector{Int}}
    refr_left::Vector{Vector{Int}}

    # Time tracking
    time_since_last_talk::Vector{Int}  # turns since last conversation
    self_talk_left::Vector{Int}        # remaining turns in self-conversation (0 if not)

    #Agent properties
    agents::Array{Float32,3}  # n x n x N semantic networks
    perceived_distance::Matrix{Float32}  # N x N, perceived distance between agents

    γ::Float32           # attraction sharpness
    β::Float32           # how strongly score affects choice
    δ::Float32           # physical distance decay
    n::Int               # matrix size
    can_talk::Vector{Bool}  # whether agent can participate in conversations
    p0::Float32
    beta_for_consent::Float32
    isolated_agent::Union{Nothing,Int}
    isolated_agent_interaction_prob::Union{Nothing,Float32}

    # Social anxiety / silence
    silent::Vector{Bool}            # if true: can join conversations but never speaks
    abandonment_count::Vector{Int}  # number of early endings experienced (not due to reset)
    abandonment_threshold::Int      # once count >= threshold => silent=true permanently

    # Preallocated buffers (reused every step)
    x_des::Vector{Int}
    y_des::Vector{Int}
    cell_des::Vector{Int}   # desired cell key for each agent: (y-1)*W + x
    winners::BitVector      # winners[i] = true if agent i won its desired cell
    cell_count::Vector{Int} # length W*H: how many agents want each cell
    cell_pick::Vector{Int}  # length W*H: picked winner agent id for each cell

    # Analysis data
    current_distances::Matrix{Float32}  # current pairwise distances
    agent_sum::Vector{Float32}   # length N, sum of participants[:,:,i]
    # initial_agent_sum::Vector{Float32}
    colsum::Matrix{Float32}   # size n × N, column sums per participant
    # initial_colsum::Matrix{Float32}
    distances_history::Vector{Matrix{Float32}}  # history of distances per step
    perceived_distance_history::Vector{Matrix{Float32}}  # history of perceived distances per step
    talk_episode_count::Matrix{Int}   # N×N: how many shared-conversation EPISODES
    talk_episode_active::BitMatrix    # N×N: currently in same conversation (episode active)
    talk_episode_seen::BitMatrix      # N×N: helper per-step "currently together"
    adjacency_count::Matrix{Int}
    unique_partners_steps::Vector{Int}
    unique_partners_history::Vector{Vector{Int}}
    self_talk_count::Vector{Int}

    t::Int  # step counter

    # Logs
    attempt_events::Vector{Vector{NamedTuple}}
    conversation_events::Vector{NamedTuple}
end

function init_world(N::Int, W::Int, H::Int, n::Int, m::Int, change::Float64; gamma::Float64=0.0,
    beta::Float64=0.0, delta::Float64=0.0, p0::Float64=0.5, beta_for_consent::Float64=0.0, 
    abandonment_threshold=100, outliers_count::Int=0,
    outlier_change::Union{Nothing,Float64}=nothing,
    isolated_agent::Union{Nothing,Int}=nothing,
    isolated_agent_interaction_prob::Union{Nothing,Float64}=nothing)

    @assert N ≤ W * H "Too many agents for the grid size."

    # Helper function for initial random placement
    function random_place!()
        for i in 1:N
            while true
                cx = rand(1:W)
                cy = rand(1:H)
                if occ[cy, cx] == 0
                    x[i] = cx
                    y[i] = cy
                    occ[cy, cx] = i
                    break
                end
            end
        end
    end

    occ = zeros(Int, H, W)
    x = Vector{Int}(undef, N)
    y = Vector{Int}(undef, N)
    random_place!()

    agents = make_agents_with_outliers(N, n, m, change; outliers_count=outliers_count, outlier_change=outlier_change)

    current_distances = differences(agents)

    start_perceived_distance = mean_offdiag(current_distances)

    perceived_distance = fill(Float32(start_perceived_distance), N, N)
    for i in 1:N
        perceived_distance[i, i] = 0.0f0   # self-attraction disabled (or max distance)
    end

    perceived_distance_history = Matrix{Float32}[]
    push!(perceived_distance_history, copy(perceived_distance))

    γ = Float32(gamma)
    β = Float32(beta)
    δ = Float32(delta)
    can_talk = fill(true, N)
    p0 = Float32(p0)
    beta_for_consent = Float32(beta_for_consent)


    if isolated_agent === nothing
        @assert isolated_agent_interaction_prob === nothing "If isolated_agent is nothing, isolated_agent_interaction_prob must also be nothing."
    else
        @assert 1 ≤ isolated_agent ≤ N "isolated_agent must be between 1 and N."
        @assert isolated_agent_interaction_prob !== nothing "Must provide isolated_agent_interaction_prob when isolated_agent is set."
        @assert 0.0 ≤ isolated_agent_interaction_prob ≤ 1.0 "isolated_agent_interaction_prob must be between 0 and 1."
    end

    isolated_agent_interaction_prob_f32 =
        isolated_agent_interaction_prob === nothing ? nothing : Float32(isolated_agent_interaction_prob)


    silent = falses(N)
    abandonment_count = zeros(Int, N)
    abandonment_threshold = abandonment_threshold  # choose a default for now (you can pass it later)

    talking_group = zeros(Int, N)
    talk_left = zeros(Int, N)

    agent_seen_partners = [Set{Int}() for _ in 1:N]
    next_group_id = 1

    refr_partners = [Vector{Int}() for _ in 1:N]
    refr_left = [Vector{Int}() for _ in 1:N]

    # Time tracking
    time_since_last_talk = zeros(Int, N)
    self_talk_left = zeros(Int, N)

    # preallocate buffers
    x_des = similar(x)
    y_des = similar(y)
    cell_des = Vector{Int}(undef, N)
    winners = falses(N)

    cell_count = zeros(Int, W * H)
    cell_pick = zeros(Int, W * H)

    agent_sum = Vector{Float32}(undef, N)
    @inbounds for i in 1:N
        agent_sum[i] = sum(@view agents[:, :, i])  # Float32 sum
    end
    # initial_agent_sum = copy(agent_sum)

    colsum = Matrix{Float32}(undef, n, N)
    @inbounds for i in 1:N
        Ai = @view agents[:, :, i]
        colsum[:, i] .= vec(sum(Ai; dims=1))
    end
    # initial_colsum = copy(colsum)


    distances_history = Matrix{Float32}[]
    push!(distances_history, copy(current_distances))

    talk_episode_count = zeros(Int, N, N)
    talk_episode_active = falses(N, N)
    talk_episode_seen = falses(N, N)

    adjacency_count = zeros(Int, N, N)
    self_talk_count = zeros(Int, N)
    t = 0

    unique_partners_steps = Int[]
    unique_partners_history = Vector{Vector{Int}}()

    attempt_events = [NamedTuple[] for _ in 1:N]
    conversation_events = NamedTuple[]
    self_talk_count = zeros(Int, N)


    return World(W, H, N, x, y, occ, talking_group, talk_left, agent_seen_partners, next_group_id, refr_partners, refr_left,
        time_since_last_talk, self_talk_left, agents, perceived_distance, γ, β, δ, n, can_talk, p0, beta_for_consent, isolated_agent, isolated_agent_interaction_prob_f32,
        silent, abandonment_count, abandonment_threshold,
        x_des, y_des, cell_des, winners, cell_count, cell_pick, current_distances, agent_sum,
        # initial_agent_sum,
        colsum, 
        # initial_colsum, 
        distances_history, perceived_distance_history, talk_episode_count,
        talk_episode_active, talk_episode_seen, adjacency_count, unique_partners_steps, unique_partners_history,self_talk_count, t,
        attempt_events, conversation_events)
end

# ==========================================
# Movment
# ==========================================

const MOVES_9 = [(dx, dy) for dx in -1:1 for dy in -1:1]  # movement deltas (includes stay)

@inline function in_bounds(x::Int, y::Int, W::Int, H::Int)
    #=
    Checks if the given coordinates (x, y) are within the valid grid boundaries.
    
    Arguments:
    - x, y: The coordinates to check.
    - W, H: The width and height of the grid.
    
    Returns:
    - true if the coordinates are inside the grid, false otherwise.
    =#
    return 1 ≤ x ≤ W && 1 ≤ y ≤ H
end
@inline function cell_key(x::Int, y::Int, W::Int)
    return (y - 1) * W + x
end
@inline function dist2(x1::Int, y1::Int, x2::Int, y2::Int)::Int
    #=
    Calculates the squared Euclidean distance between two points on the grid.
    
    Arguments:
    - x1, y1: Coordinates of the first point.
    - x2, y2: Coordinates of the second point.
    
    Returns:
    - An integer representing the squared distance.
    =#
    dx = x1 - x2
    dy = y1 - y2
    return dx * dx + dy * dy
end
@inline function kernel(d2::Int, δ::Float32)::Float32
    #=
    Calculates the spatial decay of attraction based on squared physical distance.
    Uses a Lorentzian-like kernel: 1 / (1 + δ * d2).
    
    Arguments:
    - d2: Squared physical distance between two points (calculated by dist2).
    - δ (delta): The spatial decay parameter. Higher values mean steeper decay.
    
    Returns:
    - A Float32 weight representing the distance penalty/influence.
    =#
    return 1.0f0 / (1.0f0 + δ * d2)
end
@inline function attraction(world::World, i::Int, j::Int)::Float32
    #=
    Calculates the semantic attraction between agent i and agent j.
    Based on their perceived semantic distance and the attraction sharpness parameter γ.
    
    Arguments:
    - world: The World struct containing the simulation state.
    - i: Index of the focal agent.
    - j: Index of the target agent.
    
    Returns:
    - A Float32 representing the attraction score (0 to 1).
    =#
    return exp(-world.γ * world.perceived_distance[i, j])
end
@inline function attraction_mean_std(world::World, i::Int)
    #=
    Calculates the mean (μ) and standard deviation (σ) of the semantic attraction
    of agent i towards all other agents in the population.
    
    Arguments:
    - world: The World struct.
    - i: Index of the focal agent.
    
    Returns:
    - μ: Mean attraction (Float32).
    - σ: Standard deviation of attraction (Float32).
    =#
    N = world.N

    s = 0.0f0
    s2 = 0.0f0
    cnt = 0

    @inbounds for j in 1:N
        j == i && continue
        a = attraction(world, i, j)
        s += a
        s2 += a * a
        cnt += 1
    end

    μ = s / Float32(cnt)
    v = s2 / Float32(cnt) - μ * μ
    v = max(v, 0.0f0)
    σ = sqrt(v)
    return μ, σ
end

function move_score_z(world::World, i::Int, x2::Int, y2::Int)::Float32
    #=
    Calculates the total attractiveness score of a candidate cell (x2, y2) for agent i.
    The score is a spatially-discounted sum of the standardized semantic attractions 
    (Z-scores) towards all other eligible agents in the world.
    
    Arguments:
    - world: The World struct.
    - i: Index of the focal agent.
    - x2, y2: Coordinates of the candidate target cell.
    
    Returns:
    - A Float32 representing the total score of the cell.
    =#
    μa, σa = attraction_mean_std(world, i)
    s = 0.0f0
    @inbounds for j in 1:world.N
        if j != i
            if is_refractory(world.refr_partners, world.refr_left, i, j)
                continue
            end
            d2 = dist2(x2, y2, world.x[j], world.y[j])
            k = kernel(d2, world.δ)
            a = attraction(world, i, j)
            az = (σa == 0.0f0 || !isfinite(σa)) ? 0.0f0 : ((a - μa) / σa)
            s += az * k
        end
    end
    return s
end
function choose_attracted_move!(world::World, i::Int)
    #=
    Selects a desired target cell for agent i from its Moore neighborhood.
    Calculates scores for all legal neighboring cells, standardizes them,
    and samples a destination probabilistically using a softmax function controlled by β.
    
    Arguments:
    - world: The World struct.
    - i: Index of the moving agent.
    
    Result:
    - Updates world.x_des[i], world.y_des[i], and world.cell_des[i] with the chosen destination.
    =#
    xi = world.x[i]
    yi = world.y[i]
    β = world.β

    cand_x = Vector{Int}(undef, 9)
    cand_y = Vector{Int}(undef, 9)
    svals = Vector{Float32}(undef, 9)
    z = 0

    # 1) Find legal moves and calculate their raw scores
    @inbounds for (dx, dy) in MOVES_9
        x2 = xi + dx
        y2 = yi + dy
        if in_bounds(x2, y2, world.W , world.H)
            legal = (x2 == xi && y2 == yi) || (world.occ[y2, x2] == 0)
            if legal
                z += 1
                cand_x[z] = x2
                cand_y[z] = y2
                svals[z] = move_score_z(world, i, x2, y2)
            end
        end
    end
    # 2) Calculate mean and standard deviation of candidate scores
    μ = 0.0f0
    @inbounds for k in 1:z
        μ += svals[k]
    end
    μ /= Float32(z)

    v = 0.0f0
    @inbounds for k in 1:z
        d = svals[k] - μ
        v += d * d
    end
    v /= Float32(z)               # population var across candidates
    σ = sqrt(v)

    weights = Vector{Float32}(undef, z)
    total = 0.0f0

    # 3) Softmax with Log-Sum-Exp trick for stability
    if σ == 0.0f0 || !isfinite(σ)
        # all scores identical -> uniform choice
        @inbounds for k in 1:z
            weights[k] = 1.0f0
        end
        total = Float32(z)
    else
        invσ = 1.0f0 / σ

        # Find max log-weight to prevent overflow
        maxlogw = -Inf32
        @inbounds for k in 1:z
            zk = (svals[k] - μ) * invσ
            lw = β * zk
            if lw > maxlogw
                maxlogw = lw
            end
        end

        # Calculate exponential weights safely
        @inbounds for k in 1:z
            zk = (svals[k] - μ) * invσ
            lw = β * zk - maxlogw
            w = exp(lw)
            weights[k] = w
            total += w
        end
    end


    # 4) Roulette wheel selection (Sample)
    r = rand() * total
    acc = 0.0f0
    @inbounds for k in 1:z
        acc += weights[k]
        if acc >= r
            world.x_des[i] = cand_x[k]
            world.y_des[i] = cand_y[k]
            world.cell_des[i] = cell_key(cand_x[k], cand_y[k], world.W)
            return
        end
    end
    world.x_des[i] = cand_x[z]
    world.y_des[i] = cand_y[z]
    world.cell_des[i] = cell_key(cand_x[z], cand_y[z], world.W)
    return
end
function move_agents!(world::World)
    #=
    Executes the movement of all agents in the world.
    1. Determines the desired cell for each agent (talking agents stay put).
    2. Resolves spatial conflicts if multiple agents choose the same cell using reservoir sampling.
    3. Updates the physical positions and occupancy matrix for the winners.
    =#
    W, H, N = world.W, world.H, world.N
    num_cells = W * H

    # 1) Collect movement desires for all agents
    @inbounds for i in 1:N
        if world.talking_group[i] == 0 && world.self_talk_left[i] == 0
            choose_attracted_move!(world, i)   # fills x_des/y_des/cell_des
        else
            xi = world.x[i]
            yi = world.y[i]
            world.x_des[i] = xi
            world.y_des[i] = yi
            world.cell_des[i] = cell_key(xi, yi, W)
        end
    end

    fill!(world.cell_count, 0)
    fill!(world.cell_pick, 0)

    # 2) Resolve spatial conflicts using Reservoir Sampling
    @inbounds for i in 1:N
        c = world.cell_des[i]
        cnt = world.cell_count[c] + 1
        world.cell_count[c] = cnt

        if cnt == 1
            world.cell_pick[c] = i
        else
            if rand() < 1 / cnt
                world.cell_pick[c] = i
            end
        end
    end

    # 3) Mark the final winners
    fill!(world.winners, false)
    @inbounds for c in 1:num_cells
        w = world.cell_pick[c]
        if w != 0
            world.winners[w] = true
        end
    end

    # 4) Execute the actual movement
    @inbounds for i in 1:N
        if world.winners[i]
            x2 = world.x_des[i]
            y2 = world.y_des[i]
            x1 = world.x[i]
            y1 = world.y[i]
            if x2 != x1 || y2 != y1
                world.occ[y1, x1] = 0
                world.occ[y2, x2] = i
                world.x[i] = x2
                world.y[i] = y2
            end
        end
    end
    return nothing
end


# ==========================================
# Conversations
# ==========================================

# Formation

const NEIGHBOR_8 = [(dx, dy) for (dx, dy) in MOVES_9 if !(dx == 0 && dy == 0)]  # Moore neighborhood

function find_clusters(world::World, eligible_ids::Vector{Int})
    adj = Dict{Int,Vector{Int}}()
    for i in eligible_ids
        adj[i] = Int[]
        xi, yi = world.x[i], world.y[i]
        for (dx, dy) in NEIGHBOR_8
            nx, ny = xi + dx, yi + dy
            if in_bounds(nx, ny, world.W, world.H)
                j = world.occ[ny, nx]
                if j != 0 && j in eligible_ids
                    push!(adj[i], j)
                end
            end
        end
    end

    visited = Set{Int}()
    clusters = Vector{Vector{Int}}()
    for i in eligible_ids
        if !(i in visited)
            cluster = Int[]
            stack = [i]
            push!(visited, i)
            while !isempty(stack)
                curr = pop!(stack)
                push!(cluster, curr)
                for neighbor in adj[curr]
                    if !(neighbor in visited)
                        push!(visited, neighbor)
                        push!(stack, neighbor)
                    end
                end
            end
            if length(cluster) > 1
                push!(clusters, cluster)
            end
        end
    end
    return clusters
end

function form_conversations!(world::World;   #with isolated_agent
    talk_duration::Int=3,
    pmin::Real=0.05,
    pmax::Real=0.95,
    p0::Real=0.5,
    join_rule::Symbol=:neighbors_any)

    N = world.N

    # -----------------------------
    # Stage A: Try to join existing conversations
    # -----------------------------
    free_agents = [i for i in 1:N if world.talking_group[i] == 0 && world.self_talk_left[i] == 0 && world.can_talk[i]]
    shuffle!(free_agents)

    for i in free_agents
        xi, yi = world.x[i], world.y[i]

        # collect candidate neighbors j that are in an existing group
        neighbors_in_groups = Int[]
        for (dx, dy) in NEIGHBOR_8
            nx, ny = xi + dx, yi + dy
            if !in_bounds(nx, ny, world.W, world.H)
                continue
            end
            j = world.occ[ny, nx]
            if j != 0 && world.talking_group[j] != 0 && world.can_talk[j] && !is_refractory(world.refr_partners, world.refr_left, i, j)
                push!(neighbors_in_groups, j)
            end
        end

        isempty(neighbors_in_groups) && continue
        shuffle!(neighbors_in_groups)

        tried_gids = Set{Int}()

        for j in neighbors_in_groups
            gid = world.talking_group[j]
            if gid in tried_gids
                continue
            end
            push!(tried_gids, gid)

            ask = Int[]

            if join_rule == :neighbors_any
                for (dx, dy) in NEIGHBOR_8
                    nx, ny = xi + dx, yi + dy
                    in_bounds(nx, ny, world.W, world.H) || continue
                    k = world.occ[ny, nx]
                    if k != 0 &&
                       world.talking_group[k] == gid &&
                       world.can_talk[k] &&
                       !is_refractory(world.refr_partners, world.refr_left, i, k)
                        push!(ask, k)
                    end
                end
            elseif join_rule == :group_any || join_rule == :group_all
                for k in 1:world.N
                    if world.talking_group[k] == gid &&
                       world.can_talk[k] &&
                       !is_refractory(world.refr_partners, world.refr_left, i, k)
                        push!(ask, k)
                    end
                end

            else
                error("Unknown join_rule = $join_rule")
            end

            isempty(ask) && continue
            shuffle!(ask)

            asked_vec = copy(ask)
            accepted = Int[]
            rejected = Int[]


            joined = false

            if join_rule == :neighbors_any || join_rule == :group_any
                for k in ask
                    if world.isolated_agent !== nothing &&
                       (i == world.isolated_agent || k == world.isolated_agent)

                        success_ik = rand() < world.isolated_agent_interaction_prob

                        if !success_ik
                            push!(rejected, k)
                            continue
                        end

                        push!(accepted, k)
                        joined = true
                        break

                    else
                        ai = accepts(world, i, k; pmin=pmin, pmax=pmax, p0=p0)
                        ai || continue

                        if world.silent[i]
                            push!(accepted, k)
                            joined = true
                            break
                        end

                        ak = accepts(world, k, i; pmin=pmin, pmax=pmax, p0=p0)
                        if !ak
                            push!(rejected, k)
                            continue
                        end

                        push!(accepted, k)
                        joined = true
                        break
                    end
                end

            elseif join_rule == :group_all
                joined = true
                for k in ask
                    if world.isolated_agent !== nothing &&
                       (i == world.isolated_agent || k == world.isolated_agent)

                        success_ik = rand() < world.isolated_agent_interaction_prob

                        if !success_ik
                            push!(rejected, k)
                            joined = false
                            break
                        end

                        push!(accepted, k)

                    else
                        ai = accepts(world, i, k; pmin=pmin, pmax=pmax, p0=p0)
                        if !ai
                            joined = false
                            break
                        end

                        if world.silent[i]
                            push!(accepted, k)
                            continue
                        end

                        ak = accepts(world, k, i; pmin=pmin, pmax=pmax, p0=p0)
                        if !ak
                            push!(rejected, k)
                            joined = false
                            break
                        end

                        push!(accepted, k)
                    end
                end
            end

            log_attempt!(world, i;
                kind=:join,
                rule=join_rule,
                success=joined,
                asked=asked_vec,
                accepted=accepted,
                rejected=rejected,
                gid=gid
            )

            if joined
                world.talking_group[i] = gid
                world.talk_left[i] = talk_duration
                empty!(world.agent_seen_partners[i])
                for k in 1:world.N
                    if world.talking_group[k] == gid && k != i
                        push!(world.agent_seen_partners[i], k)
                        push!(world.agent_seen_partners[k], i)
                    end
                end
                break
            end
        end
    end

    # -----------------------------
    # Stage B: Create new conversations among still-free agents
    # -----------------------------
    still_free = [i for i in 1:N if world.talking_group[i] == 0 && world.self_talk_left[i] == 0 && world.can_talk[i]]
    clusters = find_clusters(world, still_free)  # your existing physical cluster finder (neighbors-touching)

    for cluster in clusters

        asked_new = Dict{Int,Vector{Int}}()
        accepted_new = Dict{Int,Vector{Int}}()
        rejected_new = Dict{Int,Vector{Int}}()

        for a in cluster
            asked_new[a] = Int[]
            accepted_new[a] = Int[]
            rejected_new[a] = Int[]
        end

        # Build adjacency list for consent graph (on physical neighbors only)
        adj = Dict{Int,Vector{Int}}()
        for i in cluster
            adj[i] = Int[]
        end

        # For each unordered adjacent physical pair, sample acceptances once
        # (We only consider edges if they are physical neighbors in the grid)
        in_cluster = Set(cluster)  # cluster sizes are typically small; ok
        for i in cluster
            xi, yi = world.x[i], world.y[i]
            for (dx, dy) in NEIGHBOR_8
                nx, ny = xi + dx, yi + dy
                in_bounds(nx, ny, world.W, world.H) || continue
                j = world.occ[ny, nx]
                if j == 0 || !(j in in_cluster) || j <= i
                    continue
                end
                if is_refractory(world.refr_partners, world.refr_left, i, j)
                    continue
                end

                # this pair was considered (so both "asked" about each other)
                push!(asked_new[i], j)
                push!(asked_new[j], i)

                if world.isolated_agent !== nothing &&
                   (i == world.isolated_agent || j == world.isolated_agent)

                    success_ij = rand() < world.isolated_agent_interaction_prob

                    if success_ij
                        push!(adj[i], j)
                        push!(adj[j], i)
                        push!(accepted_new[i], j)
                        push!(accepted_new[j], i)
                    else
                        push!(rejected_new[i], j)
                        push!(rejected_new[j], i)
                    end
                else
                    ai = accepts(world, i, j; pmin=pmin, pmax=pmax, p0=p0)
                    aj = accepts(world, j, i; pmin=pmin, pmax=pmax, p0=p0)

                    if ai && aj
                        push!(adj[i], j)
                        push!(adj[j], i)
                        push!(accepted_new[i], j)
                        push!(accepted_new[j], i)
                    else
                        if ai && !aj
                            push!(rejected_new[i], j)
                        end
                        if aj && !ai
                            push!(rejected_new[j], i)
                        end
                    end
                end
            end
        end

        # Connected components in consent graph
        visited = Set{Int}()
        components = Vector{Vector{Int}}()

        for i in cluster
            if i in visited
                continue
            end
            stack = [i]
            push!(visited, i)
            comp = Int[]
            while !isempty(stack)
                v = pop!(stack)
                push!(comp, v)
                for u in adj[v]
                    if !(u in visited)
                        push!(visited, u)
                        push!(stack, u)
                    end
                end
            end
            # isolates (degree 0) will produce comp of size 1
            if length(comp) > 1
                push!(components, comp)
            end
        end

        # Create a conversation for each component
        for comp in components
            gid = world.next_group_id
            world.next_group_id += 1
            for i in comp
                world.talking_group[i] = gid
                world.talk_left[i] = talk_duration
                empty!(world.agent_seen_partners[i])
            end
        end

        for a in cluster
            success = (world.talking_group[a] != 0)
            gid_a = world.talking_group[a]   # 0 אם לא נכנס לשום שיחה חדשה

            log_attempt!(world, a;
                kind=:new,
                rule=:new,
                success=success,
                asked=asked_new[a],
                accepted=accepted_new[a],
                rejected=rejected_new[a],
                gid=gid_a
            )
        end
    end

    return nothing
end

# Consent

@inline function row_mean_std_offdiag(D::AbstractMatrix{<:Real}, i::Int)
    N = size(D, 1)
    s = 0.0
    s2 = 0.0
    @inbounds for k in 1:N
        if k == i
            continue
        end
        x = Float64(D[i, k])
        s += x
        s2 += x * x
    end
    m = s / (N - 1)
    v = s2 / (N - 1) - m * m
    v = max(v, 0.0)
    return m, sqrt(v)
end

@inline function perceived_z(world::World, i::Int, j::Int)::Float64
    pd = world.perceived_distance
    μ, σ = row_mean_std_offdiag(pd, i)
    if σ == 0.0 || !isfinite(σ)
        return 0.0
    end
    return (Float64(pd[i, j]) - μ) / σ
end

@inline function consent_prob(z::Real;
    beta::Real,
    pmin::Real,
    pmax::Real,
    p0::Real)::Float64
    zf = Float64(z)
    bf = Float64(beta)
    pminf = Float64(pmin)
    pmaxf = Float64(pmax)
    p0f = Float64(p0)

    @assert pminf < pmaxf "Need pmin < pmax."
    @assert pminf < p0f < pmaxf "Need pmin < p0 < pmax."

    alpha = Base.log((p0f - pminf) / (pmaxf - p0f))
    t = alpha - bf * zf  # higher z => lower p

    s = if t ≥ 0
        e = exp(-t)
        1.0 / (1.0 + e)
    else
        e = exp(t)
        e / (1.0 + e)
    end

    return pminf + (pmaxf - pminf) * s
end

@inline function accepts(world::World, i::Int, j::Int;
    pmin::Real, pmax::Real, p0::Real)::Bool
    z = perceived_z(world, i, j)
    p = consent_prob(z; beta=world.beta_for_consent, pmin=pmin, pmax=pmax, p0=p0)
    return rand() < p
end

# Interaction

function conversation!(group, world, L::Int; social_impact=1,social_learning_prob=ones(Float32, world.N))
    n = world.n
    members = shuffle(group)
    speakers = Int[]
    sizehint!(speakers, length(members))

    @inbounds for m in members
        if !world.silent[m]
            push!(speakers, m)
        end
    end

    if length(speakers) < 2
        return true
    end

    speaker = 1
    cue = sample(1:n, Weights(@view world.colsum[:, speakers[1]]))
    for _ in 1:L
        if speaker == length(speakers)
            speaker = 1
        else
            speaker += 1
        end
        association = sample(1:n, Weights(@view world.agents[:, cue, speakers[speaker]]))
        @inbounds for member in members
            is_speaker = member == speakers[speaker]

            if is_speaker || rand() < social_learning_prob[member]
                world.agents[association, cue, member] += social_impact
                world.agents[cue, association, member] += social_impact

                world.agent_sum[member] += 2.0f0 * social_impact
                world.colsum[cue, member] += 1.0f0 * social_impact
                world.colsum[association, member] += 1.0f0 * social_impact
            end
        end
        cue = association
    end
    return false
end
function self_conversation!(i::Int, world::World, L::Int)
    n = world.n
    cue = sample(1:n, Weights(@view world.colsum[:, i]))
    for _ in 1:L
        association = sample(1:n, Weights(@view world.agents[:, cue, i]))

        world.agents[association, cue, i] += 1.0f0
        world.agents[cue, association, i] += 1.0f0

        world.agent_sum[i] += 2.0f0
        world.colsum[cue, i] += 1.0f0
        world.colsum[association, i] += 1.0f0
        cue = association
    end

end

