# Semantic Evaluation & Metrics

function update_perceived_group!(world::World, group::Vector{Int}; eta::Float32=0.5f0)
    A = world.agents
    asum = world.agent_sum
    pd = world.perceived_distance
    n_members = length(group)


    if n_members < 2
        return
    end

    @inbounds for a in 1:n_members-1
        i = group[a]
        sumAi = asum[i]
        
        for b in a+1:n_members
            j = group[b]
            sumAj = asum[j]

            real_dij = differences_between_2(A, sumAi, sumAj, i, j)

            pd[i, j] += eta * (real_dij - pd[i, j])
            pd[j, i] += eta * (real_dij - pd[j, i])
        end
    end
end

@inline function differences_between_2(A::AbstractArray{Float32,3}, sumA::Float32, sumB::Float32, i::Int, j::Int)::Float32
    @assert ndims(A) == 3
    n, _, num = size(A)
    @assert 1 ≤ i ≤ num && 1 ≤ j ≤ num

    Ai = @view A[:, :, i]
    Aj = @view A[:, :, j]

    @assert sumA > 0 && sumB > 0

    invA = 1.0f0 / sumA
    invB = 1.0f0 / sumB

    acc = 0.0f0
    @inbounds @simd for k in eachindex(Ai)
        acc += abs(invA * Ai[k] - invB * Aj[k])
    end
    d = 0.5f0 * acc

    return d
end


# Refractory

@inline function is_refractory(refr_partners::Vector{Vector{Int}}, refr_left::Vector{Vector{Int}},
    i::Int, j::Int)::Bool
    ps = refr_partners[i]
    ls = refr_left[i]
    @inbounds for k in eachindex(ps)
        if ps[k] == j && ls[k] > 0
            return true
        end
    end
    return false
end

function set_refractory!(refr_partners::Vector{Vector{Int}}, refr_left::Vector{Vector{Int}},
    i::Int, j::Int, dur::Int)
    ps = refr_partners[i]
    ls = refr_left[i]
    @inbounds for k in eachindex(ps)
        if ps[k] == j
            ls[k] = max(ls[k], dur)  # extend if already exists
            return
        end
    end
    push!(ps, j)
    push!(ls, dur)
end

function tick_refractory!(refr_partners::Vector{Vector{Int}}, refr_left::Vector{Vector{Int}}, i::Int)
    ps = refr_partners[i]
    ls = refr_left[i]
    # Decrement and compact in-place
    write_k = 1
    @inbounds for k in eachindex(ps)
        lk = ls[k] - 1
        if lk > 0
            ps[write_k] = ps[k]
            ls[write_k] = lk
            write_k += 1
        end
    end
    resize!(ps, write_k - 1)
    resize!(ls, write_k - 1)
end


# Logging & Analytics

const CTX_JOIN::UInt8 = 0x01
const CTX_NEW::UInt8 = 0x02

@inline function log_attempt!(world::World, i::Int;
    kind::Symbol,          # :join או :new
    rule::Symbol,          # :neighbors_any/:group_any/:group_all או :new
    success::Bool,
    asked::Vector{Int},
    accepted::Vector{Int},
    rejected::Vector{Int},
    gid::Int=0)

    push!(world.attempt_events[i], (
        t=world.t,
        kind=kind,
        gid=gid,
        rule=rule,
        success=success,
        asked=asked,
        accepted=accepted,
        rejected=rejected
    ))
end

@inline function log_conversation!(world::World;
    gid::Int,
    members::Vector{Int},
    speakers::Vector{Int})

    push!(world.conversation_events, (
        t=world.t,
        gid=gid,
        members=members,
        speakers=speakers
    ))
end


# ==========================================
# Developmental Trajectories of Homophily
# ==========================================

function gaussian_schedule(T::Int;
    center::Real=(T + 1) / 2,
    sigma::Real=T / 10,
    floor::Real=0.0,
    ceiling::Real=1.0,
    inverted::Bool=false,
    Tfloat::Type=Float64)

    @assert T ≥ 1
    @assert sigma > 0
    @assert ceiling ≥ floor

    c = Tfloat(center)
    s2 = Tfloat(sigma)^2
    inv2s2 = Tfloat(1) / (Tfloat(2) * s2)
    lo = Tfloat(floor)
    hi = Tfloat(ceiling)

    y = Vector{Tfloat}(undef, T)
    @inbounds for t in 1:T
        g = exp(-((Tfloat(t) - c)^2) * inv2s2)
        if inverted
            y[t] = hi - (hi - lo) * g
        else
            y[t] = lo + (hi - lo) * g
        end
    end
    return y
end

# ==========================================
# Social anxiety
# ==========================================

@inline function mark_abandonment!(world::World, i::Int)
    world.abandonment_count[i] += 1
    if !world.silent[i] && world.abandonment_count[i] >= world.abandonment_threshold
        world.silent[i] = true
    end
    return nothing
end

# ==========================================
# Main loop & Helpers
# ==========================================
@inline function mean_offdiag(D::AbstractMatrix{<:Real})::Float64
    N = size(D, 1)
    s = 0.0
    @inbounds for i in 1:N, j in 1:N
        i == j && continue
        s += Float64(D[i, j])
    end
    return s / (N * (N - 1))
end
function end_conversation_for_agent!(world::World, i::Int, refractory_duration::Int)
    # put agent i into refractory with everyone it has seen in this conversation episode
    for partner in world.agent_seen_partners[i]
        # Use +1 to ensure the agent remains refractory through the next step's 'form_conversations!' phase, as 'tick_refractory!' occurs later in the loop.
        set_refractory!(world.refr_partners, world.refr_left, i, partner, refractory_duration + 1)
    end
    world.talking_group[i] = 0
    world.talk_left[i] = 0
    empty!(world.agent_seen_partners[i])
    return nothing
end
function update_adjacency!(adj::Matrix{Int}, world::World)
    N, W, H = world.N, world.W, world.H
    occ = world.occ
    @inbounds for i in 1:N
        xi, yi = world.x[i], world.y[i]
        for (dx, dy) in NEIGHBOR_8
            nx, ny = xi + dx, yi + dy
            if in_bounds(nx, ny, W, H)
                j = occ[ny, nx]
                if j > i 
                    adj[i, j] += 1
                    adj[j, i] += 1
                end
            end
        end
    end
    return nothing
end
function update_talk_episodes!(world::World)
    N = world.N
    active = world.talk_episode_active
    seen = world.talk_episode_seen
    count = world.talk_episode_count
    tg = world.talking_group

    fill!(seen, false)

    # mark current co-memberships and open new episodes
    group_ids = unique(tg)
    for gid in group_ids
        gid == 0 && continue

        members = Int[]
        for i in 1:N
            if tg[i] == gid
                push!(members, i)
            end
        end

        Lm = length(members)
        if Lm < 2
            continue
        end

        @inbounds for a in 1:Lm-1
            i = members[a]
            for b in a+1:Lm
                j = members[b]

                seen[i, j] = true
                seen[j, i] = true

                if !active[i, j]
                    count[i, j] += 1
                    count[j, i] += 1
                    active[i, j] = true
                    active[j, i] = true
                end
            end
        end
    end

    # close episodes for pairs that are no longer together
    @inbounds for i in 1:N-1
        for j in i+1:N
            if active[i, j] && !seen[i, j]
                active[i, j] = false
                active[j, i] = false
            end
        end
    end

    return nothing
end
function reset_positions_and_interactions!(world::World)
    N, W, H = world.N, world.W, world.H

    # 1) Clear occupancy
    fill!(world.occ, 0)

    # 2) Randomly place all agents without collisions
    @inbounds for i in 1:N
        while true
            x = rand(1:W)
            y = rand(1:H)
            if world.occ[y, x] == 0
                world.x[i] = x
                world.y[i] = y
                world.occ[y, x] = i
                break
            end
        end
    end

    # 3) Cancel all conversations
    fill!(world.talking_group, 0)
    fill!(world.talk_left, 0)
    for i in 1:N
        empty!(world.agent_seen_partners[i])
    end
    world.next_group_id = 1

    fill!(world.talk_episode_active, false)
    fill!(world.talk_episode_seen, false)

    # 4) Clear refractory
    @inbounds for i in 1:N
        empty!(world.refr_partners[i])
        empty!(world.refr_left[i])
    end

    # 5) Reset self-talk timers
    fill!(world.time_since_last_talk, 0)
    fill!(world.self_talk_left, 0)

    return nothing
end

function step!(world::World;
    talk_duration::Int=5,
    refractory_duration::Int=10,
    self_talk_threshold::Int=10,
    L::Int=10,
    eta::Float32=0.5f0,
    beta_for_consent::Real=10.0,
    gamma::Union{Nothing,Real}=nothing,
    beta::Union{Nothing,Real}=nothing,
    delta::Union{Nothing,Real}=nothing,
    p0::Union{Nothing,Real}=nothing,
    pmin::Real=0.05,
    record_distances::Bool=true,
    record_every::Int=1,
    social_impact::Float64=1.0,
    join_rule::Symbol=:group_any,
    social_learning_prob=ones(Float32, world.N))

    # --- Update parameters if provided ---
    if gamma !== nothing world.γ = Float32(gamma) end
    if beta !== nothing world.β = Float32(beta) end
    if delta !== nothing world.δ = Float32(delta) end
    if p0 !== nothing world.p0 = Float32(p0) end
    if beta_for_consent !== nothing world.beta_for_consent = Float32(beta_for_consent) end

    world.t += 1

    # 1) Group Conversation Phase
    group_ids = unique(world.talking_group)
    talked_groups = Vector{Vector{Int}}()

    for gid in group_ids
        gid == 0 && continue

        # Identify current group members
        members = [i for i in 1:world.N if world.talking_group[i] == gid]
        Lm = length(members)

        # Handle fragmented groups (less than 2 agents)
        if Lm < 2
            if Lm == 1
                if world.talk_left[members[1]] > 0
                    mark_abandonment!(world, members[1])
                end
                end_conversation_for_agent!(world, members[1], refractory_duration)
            end
            continue
        end
        # Check for silence (no speakers)
        all_silent = true
        nspeakers = 0
        @inbounds for m in members
            if !world.silent[m]
                nspeakers += 1
                if nspeakers >= 2
                    all_silent = false
                    break
                end
            end
        end

        if all_silent
            # If no one talks, they experience abandonment and group dissolves
            @inbounds for m in members
                for other in members
                    if m != other push!(world.agent_seen_partners[m], other) end
                end
                if world.talk_left[m] > 0 mark_abandonment!(world, m) end
                end_conversation_for_agent!(world, m, refractory_duration)
            end
            continue
        end

        push!(talked_groups, members)
        speakers = Int[]
        @inbounds for m in members
            if !world.silent[m]
                push!(speakers, m)
            end
        end

        log_conversation!(world; gid=gid, members=copy(members), speakers=copy(speakers))

        conversation!(members, world, L; social_impact=social_impact,social_learning_prob=social_learning_prob)

        for i in members
            world.talk_left[i] -= 1
        end
    end

    # End Conversation & Refractory Check
    for i in 1:world.N
        if world.talking_group[i] != 0 && world.talk_left[i] <= 0
            end_conversation_for_agent!(world, i, refractory_duration)
        end
    end

    # 2) Self-conversation phase
    for i in 1:world.N
        if world.talking_group[i] == 0
            if world.self_talk_left[i] > 0
                self_conversation!(i, world, L)
                world.self_talk_count[i] += 1
                world.self_talk_left[i] -= 1
            else
                world.time_since_last_talk[i] += 1
                if world.time_since_last_talk[i] >= self_talk_threshold  # threshold
                    world.self_talk_left[i] = 3  # self-talk duration
                    self_conversation!(i, world, L)
                    world.self_talk_count[i] += 1
                    world.self_talk_left[i] -= 1  # decrement immediately after first call
                    world.time_since_last_talk[i] = 0
                end
            end
        else
            world.time_since_last_talk[i] = 0  # reset if talking
        end
    end

    # --- 3) Semantic Updates (Perception) ---
    if eta != 0.0f0
        for group in talked_groups
            # No need to pass current_distances anymore
            update_perceived_group!(world, group; eta=eta)
        end
    end

    if record_distances && (world.t % record_every == 0)
        world.current_distances .= Float32.(differences(world.agents))  # או פונקציה יעילה משלך
        push!(world.distances_history, copy(world.current_distances))
        push!(world.perceived_distance_history, copy(world.perceived_distance))
    end


    # 4) Movement and Adjacency Logging
    move_agents!(world)
    update_adjacency!(world.adjacency_count, world)

    # 5) Social Interaction Initiation
    form_conversations!(world; talk_duration=talk_duration, pmin=pmin,p0=p0, join_rule=join_rule)
    update_talk_episodes!(world)

    # 6) Refractory Period Update
    for i in 1:world.N
        if !isempty(world.refr_partners[i])
            tick_refractory!(world.refr_partners, world.refr_left, i)
        end
    end

    #7) Longitudinal Logging
    push!(world.unique_partners_steps, world.t)
    current_unique_counts = [count(>(0), view(world.talk_episode_count, i, :)) for i in 1:world.N]
    push!(world.unique_partners_history, current_unique_counts)

    return nothing
end



# ==========================================
# Visualization
# ==========================================

@inline function col_mean_offdiag(D::AbstractMatrix{<:Real}, i::Int)
    N = size(D, 1)
    s = 0.0
    @inbounds for j in 1:N
        if j != i
            s += Float64(D[j, i])
        end
    end
    return s / (N - 1)
end

function distance_z_now(world::World)
    D = world.current_distances
    N = world.N

    colmeans = Vector{Float64}(undef, N)
    @inbounds for i in 1:N
        colmeans[i] = col_mean_offdiag(D, i)
    end

    μ = mean(colmeans)
    σ = std(colmeans)

    z = Vector{Float32}(undef, N)
    if σ == 0.0 || !isfinite(σ)
        fill!(z, 0.0f0)
    else
        invσ = 1.0 / σ
        @inbounds for i in 1:N
            z[i] = Float32((colmeans[i] - μ) * invσ)
        end
    end
    return z
end

function plot_world(world::World; ms=6, zclip=3.0, step::Union{Nothing,Int}=nothing)
    z = distance_z_now(world)

    @inbounds for i in eachindex(z)
        if z[i] > zclip
            z[i] = zclip
        elseif z[i] < -zclip
            z[i] = -zclip
        end
    end

    plt = scatter(
        world.x, world.y;
        markersize=ms,
        xlim=(0.5, world.W + 0.5),
        ylim=(0.5, world.H + 0.5),
        aspect_ratio=:equal,
        yflip=true,
        legend=false,
        marker_z=z,
        color=cgrad(:RdBu, rev=true),
        colorbar=true,
        clim=(-zclip, zclip),

        # --- what you want ---
        axis=false,        # no ticks, labels, or axis lines
        grid=false,        # no internal grid lines
        framestyle=:box,   # only outer frame
    )

    if step !== nothing
        annotate!(
            plt,
            world.W / 2, world.H + 0.5,
            text("step = $(step)", 10, :black, :center)
        )
    end

    return plt
end
