# ==========================================
# Analysis
# ==========================================

function distance_z_trajectories(distances_history;
    record_every::Int=1,        # תדר ההקלטה
    to_display::Bool=true,
    agents=nothing,
    x=nothing,
    print_winner::Bool=true,    # שיניתי לברירת מחדל true כדי שתראה מי ה-Outlier
    schedule=nothing,
    schedule_inverted::Bool=false,
    schedule_band_frac::Float64=0.12,
    schedule_color=:gray,
    to_return=false)

    T = length(distances_history)
    D0 = distances_history[1]
    N = size(D0, 1)

    colmean_history = Matrix{Float64}(undef, T, N)
    z_history = Matrix{Float64}(undef, T, N)

    # --- 1) Calculation Phase ---
    for t in 1:T
        D = distances_history[t]

        @inbounds for i in 1:N
            # שימוש בפונקציית העזר הקיימת שלך
            colmean_history[t, i] = col_mean_offdiag(D, i)
        end
        
        current_means = view(colmean_history, t, :)
        μ = mean(current_means)
        σ = std(current_means)

        if σ == 0 || isnan(σ)
            z_history[t, :] .= 0.0
        else
            @inbounds for i in 1:N
                # נוסחת ציון התקן: $z = \frac{x - \mu}{\sigma}$
                z_history[t, i] = (colmean_history[t, i] - μ) / σ
            end
        end
    end

    # --- 2) Metadata and Logging ---
    if print_winner
        z_final = view(z_history, T, :)
        max_z, winner = findmax(z_final)
        println("--- Semantic Analysis Results ---")
        println("Most outlier agent (at T=$T): $winner with z = $(round(max_z, digits=3))")
    end

    # תיקון: הכפלת ציר ה-X בתדר ההקלטה
    xs = x === nothing ? (collect(0:(T-1)) .* record_every) : collect(x)
    agent_ids = agents === nothing ? collect(1:N) : collect(agents)
    
    # --- 3) Plotting Phase ---
    if to_display
        plt = Plots.plot(xformatter=:plain, title="Semantic Distance Trajectories")
        for i in agent_ids
            Plots.plot!(plt, xs, z_history[:, i], label="agent $i", legend=false, alpha=0.7)
        end

        # קווי ייחוס
        hline!(plt, [0.0], linestyle=:dash, color=:black, label="Average")
        hline!(plt, [2.5], linestyle=:dash, color=:gray, alpha=0.5, label=false)
        hline!(plt, [3.0], linestyle=:dash, color=:red, alpha=0.5, label="Outlier Threshold")

        Plots.xlabel!(plt, "Simulation Step")
        Plots.ylabel!(plt, "Distance Z-score")

        # --- 4) Schedule Band Overlay ---
        if schedule !== nothing
            # מיפוי חכם של ציר ה-X לאינדקסים של ה-Schedule
            s_len = length(schedule)
            idx = [clamp(Int(round(val)) + 1, 1, s_len) for val in xs]
            s = schedule[idx]

            # נרמול ה-Schedule לטווח [0,1] לצורך התצוגה בתחתית
            smin, smax = minimum(s), maximum(s)
            s01 = smax == smin ? fill(0.5, length(s)) : (Float64.(s) .- smin) ./ (smax - smin)
            if schedule_inverted s01 .= 1 .- s01 end

            # חישוב גובה הפס האפור בתחתית הגרף
            ylo, yhi = ylims(plt)
            yr = Float64(yhi) - Float64(ylo)
            band_top = Float64(ylo) + schedule_band_frac * yr

            y_sched = Float64(ylo) .+ s01 .* (band_top - Float64(ylo))

            plot!(plt, xs, y_sched; color=schedule_color, linewidth=2, label="Param Schedule")
            hline!(plt, [band_top], linestyle=:dash, color=schedule_color, alpha=0.3, label=false)
        end

        display(plt)
    end
    if to_return
        return z_history
    end
end
function plot_distance_conversation_poster_panel(w, distances_history;
    record_every::Int=1,
    x=nothing,
    agents=nothing,
    distance_threshold::Float64=2.5,
    make_distance_plot::Bool=true,
    make_conversation_plot::Bool=true,
    make_overlay_plot::Bool=true,
    title_distance::String="Trajectories of mean semantic distance",
    title_conversation::String="Trajectories of conversation participation",
    title_overlay::String="Mean semantic distance and conversation participation",
    xlabel_txt::String="Simulation step",
    ylabel_distance::String="Mean semantic distance (z-score)",
    ylabel_conversation = "Conversation participation (z-score)",
    ylabel_overlay::String="Z-score",
    highlight_color=:red,
    line_alpha::Float64=0.62,
    highlight_alpha::Float64=0.98,
    line_lw::Float64=1.8,
    highlight_lw::Float64=3.6,
    threshold_color=:red,
    meanline_color=:black,
    meanline_alpha::Float64=0.20,
    threshold_alpha::Float64=0.85,
    legend_on::Bool=false,
    size_px::Tuple{Int,Int}=(900, 600),
    legend_place=:topright,
    to_return=false)

    T = length(distances_history)
    D0 = distances_history[1]
    N = size(D0, 1)

    xs = x === nothing ? (collect(0:(T-1)) .* record_every) : collect(x)
    @assert length(xs) == T "Length of x must match length(distances_history)"

    agent_ids = agents === nothing ? collect(1:N) : collect(agents)
    @assert all(1 .<= agent_ids .<= N) "All agent indices must be between 1 and $N"

    function make_agent_colors(N::Int)
        base = distinguishable_colors(
            N + 2,
            [RGB(1,1,1), RGB(1,0,0)];
            dropseed=true
        )
        cols = base[1:N]
        return Dict(i => cols[i] for i in 1:N)
    end
    agent_colors = make_agent_colors(N)

    conversation_threshold = -distance_threshold

    # -----------------------------
    # Distance z-scores
    # -----------------------------
    colmean_history = Matrix{Float64}(undef, T, N)
    z_dist = Matrix{Float64}(undef, T, N)

    for t in 1:T
        D = distances_history[t]

        @inbounds for i in 1:N
            colmean_history[t, i] = col_mean_offdiag(D, i)
        end

        current_means = view(colmean_history, t, :)
        μ = mean(current_means)
        σ = std(current_means)

        if σ == 0 || isnan(σ)
            z_dist[t, :] .= 0.0
        else
            @inbounds for i in 1:N
                z_dist[t, i] = (colmean_history[t, i] - μ) / σ
            end
        end
    end

    z_final_dist = view(z_dist, T, :)
    _, highlighted_agent = findmax(z_final_dist)

    # -----------------------------
    # Conversation z-scores
    # -----------------------------
    conversation_events = w.conversation_events
    sorted_events = sort(conversation_events, by=ev -> ev.t)

    cumulative_counts = zeros(Float64, N)
    count_history = Matrix{Float64}(undef, T, N)
    z_conv = Matrix{Float64}(undef, T, N)

    ev_idx = 1
    n_events = length(sorted_events)

    for ti in 1:T
        current_time = xs[ti]

        while ev_idx <= n_events && sorted_events[ev_idx].t <= current_time
            ev = sorted_events[ev_idx]
            for i in ev.members
                if 1 <= i <= N
                    cumulative_counts[i] += 1
                end
            end
            ev_idx += 1
        end

        count_history[ti, :] .= cumulative_counts

        μ = mean(cumulative_counts)
        σ = std(cumulative_counts)

        if σ == 0 || isnan(σ)
            z_conv[ti, :] .= 0.0
        else
            @inbounds for i in 1:N
                z_conv[ti, i] = (cumulative_counts[i] - μ) / σ
            end
        end
    end

    function make_ylims_and_ticks(mat::AbstractMatrix, agent_ids, forced_ticks::Vector{Float64})
        ymin_data = minimum(mat[:, agent_ids])
        ymax_data = maximum(mat[:, agent_ids])
        ymin = min(ymin_data, 0.0, minimum(forced_ticks))
        ymax = max(ymax_data, 0.0, maximum(forced_ticks))
        pad = 0.06 * (ymax - ymin + eps())
        ylims_use = (ymin - pad, ymax + pad)

        yticks_vals = collect(round(floor(ylims_use[1])):1:round(ceil(ylims_use[2])))
        for v in forced_ticks
            if all(abs(y - v) > 1e-8 for y in yticks_vals)
                push!(yticks_vals, v)
            end
        end
        sort!(yticks_vals)

        return ylims_use, yticks_vals
    end

    ylims_dist, yticks_dist = make_ylims_and_ticks(z_dist, agent_ids, [distance_threshold])
    ylims_conv, yticks_conv = make_ylims_and_ticks(z_conv, agent_ids, [conversation_threshold])
    ylims_overlay, yticks_overlay = make_ylims_and_ticks(vcat(z_dist, z_conv), agent_ids, [conversation_threshold, distance_threshold])

    function init_plot(; title, ylabel, ylims_use, yticks_use, legend_setting=legend_on)
        plot(
            xformatter=:plain,
            title=title,
            xlabel=xlabel_txt,
            ylabel=ylabel,
            legend=legend_setting,
            grid=false,
            framestyle=:box,
            size=size_px,
            fontfamily="Calibri",
            titlefont=font(25, "Calibri", :bold),
            xguidefontsize=21,
            yguidefontsize=21,
            xtickfontsize=18,
            ytickfontsize=18,
            ylims=ylims_use,
            yticks=yticks_use,
            top_margin=6Plots.mm,
            bottom_margin=4Plots.mm,
            left_margin=4Plots.mm
        )
    end

    p_distance = nothing
    if make_distance_plot
        p_distance = init_plot(
            title=title_distance,
            ylabel=ylabel_distance,
            ylims_use=ylims_dist,
            yticks_use=yticks_dist
        )

        for i in agent_ids
            if i != highlighted_agent
                plot!(
                    p_distance, xs, z_dist[:, i];
                    color=agent_colors[i],
                    alpha=line_alpha,
                    linewidth=line_lw,
                    label=false
                )
            end
        end

        if highlighted_agent in agent_ids
            plot!(
                p_distance, xs, z_dist[:, highlighted_agent];
                color=highlight_color,
                alpha=highlight_alpha,
                linewidth=highlight_lw,
                label=false
            )
        end

        hline!(
            p_distance, [0.0];
            linestyle=:dash,
            color=meanline_color,
            alpha=meanline_alpha,
            linewidth=1.2,
            label=false
        )

        hline!(
            p_distance, [distance_threshold];
            linestyle=:dash,
            color=threshold_color,
            alpha=threshold_alpha,
            linewidth=1.8,
            label=false
        )

        display(p_distance)
    end

    p_conversation = nothing
    if make_conversation_plot
        p_conversation = init_plot(
            title=title_conversation,
            ylabel=ylabel_conversation,
            ylims_use=ylims_conv,
            yticks_use=yticks_conv
        )

        for i in agent_ids
            if i != highlighted_agent
                plot!(
                    p_conversation, xs, z_conv[:, i];
                    color=agent_colors[i],
                    alpha=line_alpha,
                    linewidth=line_lw,
                    label=false
                )
            end
        end

        if highlighted_agent in agent_ids
            plot!(
                p_conversation, xs, z_conv[:, highlighted_agent];
                color=highlight_color,
                alpha=highlight_alpha,
                linewidth=highlight_lw,
                label=false
            )
        end

        hline!(
            p_conversation, [0.0];
            linestyle=:dash,
            color=meanline_color,
            alpha=meanline_alpha,
            linewidth=1.2,
            label=false
        )

        hline!(
            p_conversation, [conversation_threshold];
            linestyle=:dash,
            color=threshold_color,
            alpha=threshold_alpha,
            linewidth=1.8,
            label=false
        )

        display(p_conversation)
    end

    p_overlay = nothing
    if make_overlay_plot
        p_overlay = init_plot(
            title=title_overlay,
            ylabel=ylabel_overlay,
            ylims_use=ylims_overlay,
            yticks_use=yticks_overlay,
            legend_setting=legend_place
        )

        for i in agent_ids
            col = i == highlighted_agent ? highlight_color : agent_colors[i]
            a = i == highlighted_agent ? highlight_alpha : line_alpha
            lw_use = i == highlighted_agent ? highlight_lw : line_lw

            plot!(
                p_overlay, xs, z_dist[:, i];
                color=col,
                alpha=a,
                linewidth=lw_use,
                linestyle=:solid,
                label=false
            )

            plot!(
                p_overlay, xs, z_conv[:, i];
                color=col,
                alpha=a,
                linewidth=lw_use,
                linestyle=:dash,
                label=false
            )
        end

        hline!(
            p_overlay, [0.0];
            linestyle=:dash,
            color=meanline_color,
            alpha=meanline_alpha,
            linewidth=1.2,
            label=false
        )

        hline!(
            p_overlay, [distance_threshold];
            linestyle=:dash,
            color=threshold_color,
            alpha=threshold_alpha,
            linewidth=1.8,
            label=false
        )

        hline!(
            p_overlay, [conversation_threshold];
            linestyle=:dash,
            color=threshold_color,
            alpha=threshold_alpha,
            linewidth=1.8,
            label=false
        )

        x_dummy = [xs[1], xs[1] + max(1, (xs[end] - xs[1]) / 100)]
        y_dummy = [ylims_overlay[1] - 10 * (ylims_overlay[2] - ylims_overlay[1]),
                ylims_overlay[1] - 10 * (ylims_overlay[2] - ylims_overlay[1])]

        plot!(
            p_overlay, x_dummy, y_dummy;
            color=:black,
            linestyle=:solid,
            linewidth=2,
            label="Semantic distance"
        )

        plot!(
            p_overlay, x_dummy, y_dummy;
            color=:black,
            linestyle=:dash,
            linewidth=2,
            label="Conversation participation"
        )

        display(p_overlay)
    end
    

    if to_return
        return (
        highlighted_agent=highlighted_agent,
        agent_colors=agent_colors,
        xs=xs,
        z_distance=z_dist,
        z_conversation=z_conv,
        conversation_count_history=count_history,
        plots=(
            distance=p_distance,
            conversation=p_conversation,
            overlay=p_overlay
        )
    )
    end
end

function plot_social_performance(world::World; alpha_val=0.6)
    N = world.N
    
    # מאגרי נתונים לכל שחקן
    attempts = zeros(Int, N)
    successes = zeros(Int, N)
    rejections = zeros(Int, N)

    for i in 1:N
        # עוברים על ה-Log המעודכן (NamedTuples)
        for event in world.attempt_events[i]
            attempts[i] += 1
            
            if event.success
                successes[i] += 1
            elseif !isempty(event.rejected)
                # נכשלו כי לפחות אדם אחד בקבוצה אמר "לא"
                rejections[i] += 1
            end
        end
    end

    x = 1:N
    
    # יצירת הגרף
    # אנחנו נשתמש ב-bar_position=:identity וצבעים שקופים כדי שהם "ירכבו" אחד על השני
    plt = bar(x, attempts, 
              label="Total Attempts", 
              color=:gray, 
              alpha=0.3, 
              bar_width=0.7)
    
    bar!(plt, x, successes, 
         label="Successes", 
         color=:green, 
         alpha=alpha_val, 
         bar_width=0.7)
    
    bar!(plt, x, rejections, 
         label="Failed (Rejection)", 
         color=:red, 
         alpha=alpha_val, 
         bar_width=0.7)

    xlabel!(plt, "Participant Index")
    ylabel!(plt, "Count")
    title!(plt, "Social Interaction Performance")
    plot!(plt, xticks=(x, string.(x)), legend=:topright)

    return plt
end
function plot_unique_partners_trajectory(world::World; agents=nothing)
    # Check if we have any data recorded
    if isempty(world.unique_partners_history)
        error("No unique partners history found. Did you run the simulation?")
    end

    xs = world.unique_partners_steps
    # הפיכת הוקטור של וקטורים למטריצה של זמן × סוכנים (T × N)
    history_matrix = reduce(hcat, world.unique_partners_history)' 
    
    N = world.N
    agent_ids = agents === nothing ? (1:N) : agents

    plt = plot(
        xlabel="Simulation Step",
        ylabel="Cumulative Unique Partners",
        title="Social Expansion Over Time",
        legend=false, # בדרך כלל יש יותר מדי סוכנים למקרא
        xformatter=:plain,
        background_color_legend = RGBA(1,1,1,0.5)
    )

    for i in agent_ids
        # הוספת קו לכל סוכן
        plot!(plt, xs, history_matrix[:, i], alpha=0.6)
    end

    # הוספת קו עזר שמראה את מקסימום השותפים האפשרי (N-1)
    hline!(plt, [N-1], linestyle=:dash, color=:black, alpha=0.3, label="Saturation (N-1)")

    return plt
end
### Helper
function mean_z_over_game_from_distances_history(world::World)::Vector{Float64}
    @assert !isempty(world.distances_history) "distances_history is empty."

    N = world.N
    T = length(world.distances_history)
    println(T)
    zsum = zeros(Float64, N)

    for t in 1:T
        D = world.distances_history[t]
        col_means = zeros(Float64, N)
        
        @inbounds for i in 1:N
            col_means[i] = col_mean_offdiag(D, i)
        end

        μ = mean(col_means)
        σ = std(col_means)

        if σ == 0.0 || !isfinite(σ)
            # אם אין שונות, כולם מקבלים 0 (אף אחד לא חריג)
            continue 
        else
            invσ = 1.0 / σ
            @inbounds for i in 1:N
                z_i = (col_means[i] - μ) * invσ
                zsum[i] += z_i
            end
        end
    end

    return zsum ./ T
end
