function plot_research_correlations(world::World)
    avg_z = mean_z_over_game_from_distances_history(world)
    N = world.N
    
    n_success = [count(e -> e.success, world.attempt_events[i]) for i in 1:N]
    n_self_talk = world.self_talk_count
    hover_labels = ["Agent $i" for i in 1:N]

    # גרף א: ללא צבע מיותר
    r_success = cor(avg_z, Float64.(n_success))
    p1 = scatter(avg_z, n_success,
        xlabel="Mean Semantic Outlier Score (Avg Z)",
        ylabel="Successful Interactions (Count)",
        title="Social Success vs. Typicality (r = $(round(r_success, digits=3)))",
        hover=hover_labels,
        color=:steelblue, # צבע אחיד ונקי
        markeralpha=0.7,
        legend=false)
    
    display(p1)

    # גרף ב: ללא צבע מיותר
    r_self = cor(avg_z, Float64.(n_self_talk))
    p2 = scatter(avg_z, n_self_talk,
        xlabel="Mean Semantic Outlier Score (Avg Z)",
        ylabel="Self-talk Count",
        title="Self-talk vs. Typicality (r = $(round(r_self, digits=3)))",
        hover=hover_labels,
        color=:indianred, # צבע אחיד ונקי
        markeralpha=0.7,
        legend=false)
    
    display(p2)

    return (r_success=r_success, r_self=r_self)
end
function mds(world::World, target_step; record_every::Int=1)
    history = world.distances_history
    if isempty(history)
        error("distances_history is empty.")
    end

    T = length(history)
    actual_target = (target_step == :end) ? (T - 1) * record_every : Int(target_step)

    # 1. מציאת האינדקס
    idx = (actual_target ÷ record_every) + 1
    idx = clamp(idx, 1, T)

    recorded_step = (idx - 1) * record_every
    dist_matrix = history[idx]
    delay = actual_target - recorded_step

    # 2. חישוב ה-MDS
    # המרת המטריצה ל-Float64 עבור יציבות חישובית
    D_double = Float64.(dist_matrix)
    mds_model = fit(MDS, D_double; maxoutdim=2, distances=true)
    
    # שימוש בשם משתנה חדש למניעת התנגשויות (mds_pos במקום coords)
    mds_pos = MultivariateStats.transform(mds_model) 

    # 3. יצירת הגרף
    N = world.N
    hover_labels = ["Agent $i" for i in 1:N]
    
    # כאן אנחנו ניגשים לשורות של המטריצה mds_pos
    plt = Plots.scatter(mds_pos[1, :], mds_pos[2, :],
        xlabel="Semantic Dimension 1",
        ylabel="Semantic Dimension 2",
        title="Semantic Landscape (Step: $actual_target)",
        hover=hover_labels,
        color=:steelblue,
        markeralpha=0.7,
        markersize=7,
        aspect_ratio=:equal,
        legend=false)

    # 4. הוספת הכיתוב האדום אם זה לא צעד מדויק
    if delay != 0
        xl = xlims(plt)
        yl = ylims(plt)
        annotate!(plt, xl[2], yl[2], 
            Plots.text(" OUTDATED: Step $recorded_step ($delay steps old) ", 
                 :red, :right, :top, 8))
    end

    display(plt)
end
function plot_perceptual_accuracy(world::World; record_every::Int=1, show_individual::Bool=false)
    T_true = length(world.distances_history)
    T_perc = length(world.perceived_distance_history)
    T = min(T_true, T_perc)
    
    if T == 0
        error("Missing history data.")
    end

    pearson_vals = Vector{Float64}(undef, T)
    spearman_vals = Vector{Float64}(undef, T)
    N = world.N
    num_off_diag = N * N - N

    # חישוב המתאמים (פירסון וספירמן)
    for t in 1:T
        D_true = world.distances_history[t]
        D_perc = world.perceived_distance_history[t]
        
        v_true = Vector{Float64}(undef, num_off_diag)
        v_perc = Vector{Float64}(undef, num_off_diag)
        
        count = 1
        for j in 1:N, i in 1:N
            if i != j
                v_true[count] = Float64(D_true[i, j])
                v_perc[count] = Float64(D_perc[i, j])
                count += 1
            end
        end
        
        pearson_vals[t] = cor(v_true, v_perc)
        spearman_vals[t] = corspearman(v_true, v_perc)
    end

    xs = (0:(T-1)) .* record_every

    # --- גרפים אינדיבידואליים (יוצגו רק אם התבקש) ---
    if show_individual
        p1 = plot(xs, pearson_vals,
            xlabel="Step", ylabel="r", title="Pearson Accuracy",
            lw=2, color=:blue, legend=false)
        display(p1)

        p2 = plot(xs, spearman_vals,
            xlabel="Step", ylabel="ρ", title="Spearman Accuracy",
            lw=2, color=:green, legend=false)
        display(p2)
    end

    # --- גרף 3: מאוחד עם מקרא באמצע מימין ---
    p3 = plot(xs, [pearson_vals spearman_vals],
        xlabel="Simulation Step",
        ylabel="Correlation Coefficient",
        title="Perceptual Accuracy: Comparison",
        label=["Pearson (Linear)" "Spearman (Rank)"],
        lw=2, 
        color=[:blue :green],
        ylim=(-0.3, 1.05),
        legend=:right) # מקרא באמצע מימין
        
    display(p3)

    return (pearson=pearson_vals, spearman=spearman_vals)
end
function plot_global_semantic_stats(world::World; record_every::Int=1)
    history = world.distances_history
    T = length(history)
    N = world.N
    
    if T == 0
        error("distances_history is empty.")
    end

    global_means = Vector{Float64}(undef, T)
    global_stds = Vector{Float64}(undef, T)

    # חישוב המדדים לכל נקודת זמן שתועדה
    for t in 1:T
        D = history[t]
        agent_means = Vector{Float64}(undef, N)
        
        @inbounds for i in 1:N
            # שימוש בפונקציית העזר לחישוב ממוצע המרחקים של סוכן i ללא האלכסון
            agent_means[i] = col_mean_offdiag(D, i)
        end
        
        # א. ממוצע של כל ממוצעי הסוכנים (מרחק קבוצתי ממוצע)
        global_means[t] = mean(agent_means)
        
        # ב. סטיית תקן של ממוצעי הסוכנים (עד כמה הם שונים זה מזה בחריגות שלהם)
        global_stds[t] = std(agent_means)
    end

    xs = (0:(T-1)) .* record_every

    # --- גרף א: מרחק ממוצע קבוצתי ---
    p1 = plot(xs, global_means,
        xlabel="Step",
        ylabel="Mean of average distances",
        title="Mean of average distances per Step",
        lw=2, color=:blue, legend=false)
    display(p1)

    # --- גרף ב: סטיית תקן של החריגות ---
    p2 = plot(xs, global_stds,
        xlabel="Step",
        ylabel="Standard Deviation",
        title="SD of average distances between players per Step",
        lw=2, color=:red, legend=false)
    display(p2)

    return (means=global_means, stds=global_stds)
end
function plot_conversation_size_history(world::World; alpha_val=0.45, show_table=true, relative=false, to_return=false)
    events = world.conversation_events
    N = world.N

    isempty(events) && error("world.conversation_events is empty.")

    sizes = [length(ev.members) for ev in events]
    max_size = maximum(sizes)

    # ----------------------------
    # Overall size distribution
    # ----------------------------
    overall_counts = zeros(Int, max_size)
    for s in sizes
        overall_counts[s] += 1
    end

    overall_total = sum(overall_counts)

    overall_values = if relative
        overall_total == 0 ? zeros(Float64, max_size) : overall_counts ./ overall_total
    else
        Float64.(overall_counts)
    end

    overall_df = DataFrame(
        conversation_size = collect(1:max_size),
        value = overall_values
    )

    overall_df = overall_df[overall_counts .> 0, :]

    if show_table
        display(overall_df)
    end

    p1 = bar(
        overall_df.conversation_size,
        overall_df.value;
        xlabel = "Conversation Size",
        ylabel = relative ? "Proportion of All Conversations" : "Count",
        title = relative ? "Relative Distribution of Conversation Sizes" : "Distribution of Conversation Sizes",
        legend = false,
        alpha = 0.8
    )
    display(p1)

    # ----------------------------
    # Per-player counts by conversation size
    # ----------------------------
    per_player_counts = zeros(Int, N, max_size)

    for ev in events
        s = length(ev.members)
        for player in ev.members
            per_player_counts[player, s] += 1
        end
    end

    per_player_values = zeros(Float64, N, max_size)

    if relative
        for i in 1:N
            row_total = sum(per_player_counts[i, :])
            if row_total > 0
                per_player_values[i, :] .= per_player_counts[i, :] ./ row_total
            end
        end
    else
        per_player_values .= Float64.(per_player_counts)
    end

    player_ids = collect(1:N)

    p2 = plot(
        xlabel = "Player",
        ylabel = relative ? "Proportion of Player's Conversations" : "Number of Conversations",
        title = relative ? "Relative Conversation Sizes by Player" : "Conversation Sizes by Player",
        legend = :outerright
    )

    for s in 1:max_size
        if any(per_player_counts[:, s] .> 0)
            bar!(
                p2,
                player_ids,
                per_player_values[:, s];
                label = "Size $s",
                alpha = alpha_val,
                bar_width = 0.75
            )
        end
    end

    display(p2)

    per_player_df = DataFrame(player = player_ids)
    for s in 1:max_size
        per_player_df[!, Symbol("size_$(s)")] = per_player_values[:, s]
    end
    if to_return
        return (
        overall_table = overall_df,
        per_player_table = per_player_df,
        overall_plot = p1,
        per_player_plot = p2,
        per_player_counts = per_player_counts,
        per_player_values = per_player_values
        )
    end
end
function plot_mean_distance_z_vs_talkcount(world;
    corr_method::Symbol = :pearson,   # :pearson, :spearman
    use_field::Symbol = :auto,        # :auto, :distances_history, :distance_history, :distance_matrices_record, :perceived_distance_history
    point_alpha::Float64 = 0.65,
    marker_size::Float64 = 6.0)

    @assert corr_method in (:pearson, :spearman) "corr_method must be :pearson or :spearman"

    # -----------------------------
    # choose distance-history field
    # -----------------------------
    hist_field = if use_field == :auto
        if hasproperty(world, :distances_history)
            :distances_history
        elseif hasproperty(world, :distance_history)
            :distance_history
        elseif hasproperty(world, :distance_matrices_record)
            :distance_matrices_record
        elseif hasproperty(world, :perceived_distance_history)
            :perceived_distance_history
        else
            error("Could not find a distance-history field in world")
        end
    else
        @assert hasproperty(world, use_field) "world has no field $(use_field)"
        use_field
    end

    D_hist = getproperty(world, hist_field)
    @assert !isempty(D_hist) "$(hist_field) is empty"

    N = hasproperty(world, :N) ? Int(world.N) : size(D_hist[1], 1)
    T = length(D_hist)

    # -----------------------------
    # helper: z-score vector
    # -----------------------------
    function zscore_vec(v::AbstractVector{<:Real})
        μ = mean(v)
        σ = std(v)
        if σ == 0
            return zeros(Float64, length(v))
        else
            return (collect(Float64, v) .- μ) ./ σ
        end
    end

    # -----------------------------
    # mean distance z over time
    # -----------------------------
    Z_time = zeros(Float64, T, N)

    for t in 1:T
        D = Float64.(D_hist[t])
        @assert size(D, 1) == N && size(D, 2) == N "Distance matrix at t=$t has wrong size"

        mean_dist = zeros(Float64, N)
        for i in 1:N
            s = 0.0
            c = 0
            for j in 1:N
                if i != j
                    s += D[i, j]
                    c += 1
                end
            end
            mean_dist[i] = s / c
        end

        Z_time[t, :] .= zscore_vec(mean_dist)
    end

    mean_distance_z = vec(mean(Z_time; dims=1))

    # -----------------------------
    # total talk counts from conversation_events
    # -----------------------------
    @assert hasproperty(world, :conversation_events) "world has no conversation_events"
    convs = world.conversation_events

    talk_counts = zeros(Float64, N)

    for ev in convs
        members =
            haskey(ev, :members) ? ev.members :
            haskey(ev, :group) ? ev.group :
            error("Conversation event has neither :members nor :group")

        for i in members
            if 1 <= i <= N
                talk_counts[i] += 1
            end
        end
    end

    talk_count_z = zscore_vec(talk_counts)

    # -----------------------------
    # correlation
    # -----------------------------
    x = mean_distance_z
    y = talk_count_z

    if corr_method == :pearson
        r = cor(x, y)
        tst = CorrelationTest(x, y)
        p = HypothesisTests.pvalue(tst)
    else
        rx = tiedrank(x)
        ry = tiedrank(y)
        r = cor(rx, ry)
        tst = CorrelationTest(rx, ry)
        p = HypothesisTests.pvalue(tst)
    end

    # -----------------------------
    # plot
    # -----------------------------
    hover_txt = [
        "player $i<br>mean distance z = $(round(x[i], digits=3))<br>talk-count z = $(round(y[i], digits=3))<br>talks = $(Int(round(talk_counts[i])))"
        for i in 1:N
    ]

    p1 = scatter(
        x, y;
        xlabel = "Mean distance Z-score",
        ylabel = "Talk-count Z-score",
        title = "Mean semantic distance vs. total talk count",
        legend = false,
        alpha = point_alpha,
        markersize = marker_size,
        fontfamily = "Calibri",
        titlefont = font(17, "Calibri", :bold),
        xguidefontsize = 13,
        yguidefontsize = 13,
        xtickfontsize = 11,
        ytickfontsize = 11,
        grid = false,
        framestyle = :axes,
        tick_direction = :out,
        size = (900, 620),
        hover = hover_txt
    )

    hline!(p1, [0.0], linestyle = :dash, color = :black, alpha = 0.4, label = false)
    vline!(p1, [0.0], linestyle = :dash, color = :black, alpha = 0.4, label = false)

    if length(x) >= 2 && var(x) > 0
        β = cov(x, y) / var(x)
        α0 = mean(y) - β * mean(x)
        xs = range(minimum(x), maximum(x), length = 200)
        ys = α0 .+ β .* xs
        plot!(p1, xs, ys; lw = 2.5, alpha = 0.9, label = false)
    end

    x_left = minimum(x) + 0.03 * (maximum(x) - minimum(x) + eps())
    y_top = maximum(y) - 0.05 * (maximum(y) - minimum(y) + eps())

    annotate!(
        p1,
        x_left,
        y_top,
        text(
            "r = $(round(r, digits=3))\np = $(round(p, sigdigits=3))",
            12,
            "Calibri",
            :left
        )
    )

    display(p1)

    return (
        plot = p1,
        r = r,
        p = p,
        mean_distance_z = mean_distance_z,
        talk_counts = talk_counts,
        talk_count_z = talk_count_z,
        Z_time = Z_time,
        hist_field = hist_field
    )
end

