function gaussian_learning_schedule(
    steps::Int;
    min_value::Real,
    max_value::Real,
    peak_step::Real,
    width::Real,
    to_display::Bool=false)
    @assert steps > 0 "steps must be positive"
    @assert width > 0 "width must be positive"
    @assert max_value >= min_value "max_value must be >= min_value"

    xs = collect(1:steps)

    values = Float32.(
        min_value .+
        (max_value - min_value) .* exp.(-0.5 .* ((xs .- peak_step) ./ width).^2)
    )

    if to_display
        plt = Plots.plot(
            xs,
            values;
            xlabel="Simulation Step",
            ylabel="Social Learning Value",
            title="Gaussian Social Learning Schedule",
            legend=false,
            xformatter=:plain
        )
        display(plt)
    end

    return values
end
