function mean_network_distance_zscores(
    agents::Array{Float32,3})

    N = size(agents, 3)

    @assert N >= 2 "At least two agents are required."

    D = differences(agents)

    mean_distances =
        zeros(Float64, N)

    for i in 1:N

        total_distance = 0.0

        for j in 1:N
            if i != j
                total_distance += Float64(D[i, j])
            end
        end

        mean_distances[i] =
            total_distance / (N - 1)
    end

    μ =
        Statistics.mean(mean_distances)

    σ =
        Statistics.std(mean_distances)

    if σ == 0 || !isfinite(σ)
        z =
            zeros(Float64, N)
    else
        z =
            (mean_distances .- μ) ./ σ
    end

    return (
        mean_distances = mean_distances,
        z = z
    )
end
function show_metadata(path::String)
    if !isfile(path)
        error("Metadata file not found at: $path")
    end

    # טעינת הנתונים (מחזירה Dict)
    meta = JLD2.load(path)
    
    println("\n" * "═"^45)
    println("        SIMULATION CONFIGURATION (META)")
    println("═"^45)

    # מיון המפתחות לפי סדר אלפביתי כדי שיהיה קל למצוא פרמטרים
    sorted_keys = sort(collect(keys(meta)))

    for k in sorted_keys
        # יצירת ריווח אחיד (Padding) כדי שהערכים יהיו מיושרים בטור
        padding = " " ^ max(0, 25 - length(string(k)))
        println("  $k:$padding $(meta[k])")
    end
    
    println("═"^45 * "\n")

    return meta
end
