function compare_initial_network_distances(;
    n_groups::Int = 50,
    N::Int = 20,
    n::Int = 300,
    m::Int = 4,
    change::Float64 = 0.7)

    results = DataFrames.DataFrame(
        condition = String[],
        group = Int[],
        mean_distance = Float64[],
        sd_distance = Float64[]
    )

    for condition in ("independent", "shared_base")

        println("\nCondition: $condition")

        for group in 1:n_groups

            println("Group $group / $n_groups")

            networks = if condition == "independent"

                A = Array{Float32,3}(undef, n, n, N)

                for agent in 1:N
                    A[:, :, agent] .= create_network(n, m)
                end

                A

            else

                make_agents_with_outliers(
                    N, n, m, change;
                    outliers_count = 0
                )

            end

            D = differences(networks)

            # Extract each unique pair exactly once
            distances = [
                D[i, j]
                for i in 1:N-1
                for j in i+1:N
            ]

            push!(results, (
                condition,
                group,
                mean(distances),
                std(distances)
            ))

        end
    end

    summary = DataFrames.combine(
        DataFrames.groupby(results, :condition),

        :mean_distance => mean => :mean_distance,
        :mean_distance => std => :sd_between_groups,
        :sd_distance => mean => :mean_within_group_sd
    )

    println("\n========== SUMMARY ==========")
    display(summary)

    return results, summary
end
