function summarize_persistent_outliers_nonzero_beta(
    path::String;
    threshold::Float64 = 2.5)

    # ============================================================
    # 1. LOAD DATA
    # ============================================================

    d = JLD2.load(path)

    Z_all = d["Z_all"]
    betas = Float64.(d["beta_value"])
    steps_axis = Int.(d["steps_axis"])

    n_runs_original, T, N = size(Z_all)

    @assert length(betas) == n_runs_original
    @assert length(steps_axis) == T

    # ============================================================
    # 2. REMOVE BETA = 0
    # ============================================================

    keep_runs = findall(!=(0.0), betas)

    Z_filtered = Z_all[keep_runs, :, :]
    betas_filtered = betas[keep_runs]

    n_runs = length(keep_runs)

    if n_runs == 0
        error("No runs remain after removing beta = 0.")
    end

    println()
    println("Original runs:       ", n_runs_original)
    println("Removed beta = 0:    ", n_runs_original - n_runs)
    println("Runs analyzed:       ", n_runs)

    # ============================================================
    # 3. RUN-LEVEL AND AGENT-LEVEL RESULTS
    # ============================================================

    run_results = DataFrames.DataFrame(
        beta = Float64[],
        original_run = Int[],
        n_outliers = Int[]
    )

    outlier_agents = DataFrames.DataFrame(
        beta = Float64[],
        original_run = Int[],
        agent = Int[],
        crossing_step = Int[],
        final_z = Float64[],
        initial_z = Float64[]
    )

    println()
    println("Analyzing persistent outliers...")

    # ============================================================
    # INITIAL-STATE SUMMARY (STEP 0)
    # ============================================================

    initial_outlier_count_by_run =
        zeros(Int, n_runs)

    initial_max_z_by_run =
        zeros(Float64, n_runs)

    for r in 1:n_runs

        original_run = keep_runs[r]
        n_outliers = 0

        # --------------------------------------------------------
        # Initial state (step 0)
        # --------------------------------------------------------

        initial_z =
            Float64.(
                vec(
                    Z_filtered[
                        r,
                        1,
                        :
                    ]
                )
            )

        initial_outlier_count_by_run[r] =
            count(
                >=(threshold),
                initial_z
            )

        initial_max_z_by_run[r] =
            maximum(initial_z)


        for agent in 1:N

            ztraj = @view Z_filtered[r, :, agent]

            # ----------------------------------------------------
            # Find first crossing that remains >= threshold
            # until the final recorded timepoint
            # ----------------------------------------------------

            t_persistent = nothing

            for t in 1:T

                if ztraj[t] >= threshold &&
                   all(ztraj[t:T] .>= threshold)

                    t_persistent = t
                    break
                end
            end

            # ----------------------------------------------------
            # Persistent outlier found
            # ----------------------------------------------------

            if t_persistent !== nothing

                n_outliers += 1

                push!(
                    outlier_agents,
                    (
                        betas_filtered[r],
                        original_run,
                        agent,
                        steps_axis[t_persistent],
                        Float64(ztraj[end]),
                        Float64(ztraj[1])
                    )
                )
            end
        end

        push!(
            run_results,
            (
                betas_filtered[r],
                original_run,
                n_outliers
            )
        )

        if r % 500 == 0 || r == n_runs
            println("Processed $r / $n_runs runs")
        end
    end

    # ============================================================
    # 4. PERCENTAGE OF RUNS WITH 1, 2, OR 3 OUTLIERS
    #
    # Denominator = ALL runs with beta != 0
    # ============================================================

    # ============================================================
    # INITIAL-STATE STATISTICS
    # ============================================================

    # ------------------------------------------------------------
    # A. Agents already above threshold at step 0
    # ------------------------------------------------------------

    n_initial_outlier_agents =
        sum(initial_outlier_count_by_run)

    n_runs_with_initial_outlier =
        count(
            >(0),
            initial_outlier_count_by_run
        )

    percentage_runs_with_initial_outlier =
        100.0 *
        n_runs_with_initial_outlier /
        n_runs


    # ------------------------------------------------------------
    # B. Highest Z at step 0 across all runs
    # ------------------------------------------------------------

    mean_initial_max_z =
        Statistics.mean(
            initial_max_z_by_run
        )

    sd_initial_max_z =
        length(initial_max_z_by_run) > 1 ?
        Statistics.std(initial_max_z_by_run) :
        NaN


    # ------------------------------------------------------------
    # C. Highest Z at step 0 only in runs that eventually contain
    #    at least one persistent outlier
    # ------------------------------------------------------------

    runs_with_persistent_outlier =
        run_results.n_outliers .> 0

    initial_max_z_persistent_runs =
        initial_max_z_by_run[
            runs_with_persistent_outlier
        ]

    n_runs_with_persistent_outlier =
        length(initial_max_z_persistent_runs)


    if n_runs_with_persistent_outlier > 0

        mean_initial_max_z_persistent_runs =
            Statistics.mean(
                initial_max_z_persistent_runs
            )

        sd_initial_max_z_persistent_runs =
            n_runs_with_persistent_outlier > 1 ?
            Statistics.std(
                initial_max_z_persistent_runs
            ) :
            NaN

    else

        mean_initial_max_z_persistent_runs =
            NaN

        sd_initial_max_z_persistent_runs =
            NaN
    end


    # ============================================================
    # INITIAL OUTLIERS THAT BECAME PERSISTENT OUTLIERS
    # ============================================================

    n_initial_outliers_became_persistent = 0

    for r in 1:n_runs

        original_run = keep_runs[r]

        initial_z =
            Float64.(
                vec(
                    Z_filtered[
                        r,
                        1,
                        :
                    ]
                )
            )

        initial_outlier_agents =
            findall(
                >=(threshold),
                initial_z
            )

        for agent in initial_outlier_agents

            became_persistent =
                any(
                    (outlier_agents.original_run .== original_run) .&
                    (outlier_agents.agent .== agent)
                )

            if became_persistent
                n_initial_outliers_became_persistent += 1
            end
        end
    end


    percentage_initial_outliers_became_persistent =
        n_initial_outlier_agents > 0 ?
        100.0 *
        n_initial_outliers_became_persistent /
        n_initial_outlier_agents :
        NaN

    initial_state_summary =
        DataFrames.DataFrame(

            n_initial_outlier_agents = [
                n_initial_outlier_agents
            ],

            n_runs_with_initial_outlier = [
                n_runs_with_initial_outlier
            ],

            percentage_runs_with_initial_outlier = [
                percentage_runs_with_initial_outlier
            ],

            mean_initial_max_z = [
                mean_initial_max_z
            ],

            sd_initial_max_z = [
                sd_initial_max_z
            ],

            n_runs_with_persistent_outlier = [
                n_runs_with_persistent_outlier
            ],

            mean_initial_max_z_persistent_runs = [
                mean_initial_max_z_persistent_runs
            ],

            sd_initial_max_z_persistent_runs = [
                sd_initial_max_z_persistent_runs
            ],

            n_initial_outliers_became_persistent = [
                n_initial_outliers_became_persistent
            ],

            percentage_initial_outliers_became_persistent = [
                percentage_initial_outliers_became_persistent
            ],
        )

    count_1 = count(==(1), run_results.n_outliers)
    count_2 = count(==(2), run_results.n_outliers)
    count_3 = count(==(3), run_results.n_outliers)

    percentage_1 = 100.0 * count_1 / n_runs
    percentage_2 = 100.0 * count_2 / n_runs
    percentage_3 = 100.0 * count_3 / n_runs

    outlier_count_summary = DataFrames.DataFrame(
        n_outliers = [1, 2, 3],
        n_runs = [count_1, count_2, count_3],
        percentage_of_all_runs = [
            percentage_1,
            percentage_2,
            percentage_3
        ]
    )

    # ============================================================
    # 5. SUMMARY ACROSS ALL PERSISTENT OUTLIER AGENTS
    # ============================================================

    n_outlier_agents = DataFrames.nrow(outlier_agents)

    if n_outlier_agents == 0

        agent_summary = DataFrames.DataFrame(
            n_outlier_agents = [0],
            mean_final_z = [NaN],
            sd_final_z = [NaN],
            mean_initial_z = [NaN],
            sd_initial_z = [NaN],
            mean_crossing_step = [NaN],
            sd_crossing_step = [NaN]
        )

    else

        initial_z_values =
            Float64.(outlier_agents.initial_z)

        final_z_values =
            Float64.(outlier_agents.final_z)

        crossing_values =
            Float64.(outlier_agents.crossing_step)

        agent_summary = DataFrames.DataFrame(
            n_outlier_agents = [
                n_outlier_agents
            ],

            mean_initial_z = [
                Statistics.mean(initial_z_values)
            ],

            sd_initial_z = [
                length(initial_z_values) > 1 ?
                Statistics.std(initial_z_values) :
                NaN
            ],

            mean_final_z = [
                Statistics.mean(final_z_values)
            ],

            sd_final_z = [
                length(final_z_values) > 1 ?
                Statistics.std(final_z_values) :
                NaN
            ],

            mean_crossing_step = [
                Statistics.mean(crossing_values)
            ],

            sd_crossing_step = [
                length(crossing_values) > 1 ?
                Statistics.std(crossing_values) :
                NaN
            ]
        )
    end

    # ============================================================
    # 6. CLEAR OUTPUT
    # ============================================================

    println()
    println("="^72)
    println("PERSISTENT OUTLIER SUMMARY — BETA > 0")
    println("="^72)

    println()
    println("RUNS")
    println("-"^72)
    println("Total runs analyzed:              ", n_runs)
    println("Beta = 0 runs excluded:           ", n_runs_original - n_runs)

    println()
    println("INITIAL STATE — STEP ", steps_axis[1])
    println("-"^72)

    println(
        "Agents already above threshold:   ",
        n_initial_outlier_agents
    )

    println(
        "Runs with >=1 agent above threshold: ",
        n_runs_with_initial_outlier,
        " / ",
        n_runs,
        " (",
        round(
            percentage_runs_with_initial_outlier;
            digits = 2
        ),
        "%)"
    )

    println(
        "Initial outliers becoming persistent: ",
        n_initial_outliers_became_persistent,
        " / ",
        n_initial_outlier_agents,
        " (",
        round(
            percentage_initial_outliers_became_persistent;
            digits = 2
        ),
        "%)"
    )

    println(
        "Highest initial Z — all runs:      ",
        round(
            mean_initial_max_z;
            digits = 3
        ),
        " ± ",
        round(
            sd_initial_max_z;
            digits = 3
        ),
        " SD"
    )

    println(
        "Highest initial Z — runs with",
        "\n",
        "eventual persistent outlier:       ",
        round(
            mean_initial_max_z_persistent_runs;
            digits = 3
        ),
        " ± ",
        round(
            sd_initial_max_z_persistent_runs;
            digits = 3
        ),
        " SD",
        "  (n = ",
        n_runs_with_persistent_outlier,
        ")"
    )


    println()
    println("PERSISTENT OUTLIERS PER RUN")
    println("-"^72)

    println(
        "Exactly 1 outlier:                ",
        count_1,
        " runs (",
        round(percentage_1; digits=2),
        "%)"
    )

    println(
        "Exactly 2 outliers:               ",
        count_2,
        " runs (",
        round(percentage_2; digits=2),
        "%)"
    )

    println(
        "Exactly 3 outliers:               ",
        count_3,
        " runs (",
        round(percentage_3; digits=2),
        "%)"
    )

    println()
    println("ALL PERSISTENT OUTLIER AGENTS")
    println("-"^72)

    println(
        "Number of outlier agents:         ",
        n_outlier_agents
    )

    if n_outlier_agents > 0

        println(
            "Initial Z (eventual outliers):    ",
            round(
                agent_summary.mean_initial_z[1];
                digits=3
            ),
            " ± ",
            round(
                agent_summary.sd_initial_z[1];
                digits=3
            ),
            " SD"
        )

        println(
            "Final Z:                          ",
            round(
                agent_summary.mean_final_z[1];
                digits=3
            ),
            " ± ",
            round(
                agent_summary.sd_final_z[1];
                digits=3
            ),
            " SD"
        )

        println(
            "Persistent crossing step:         ",
            round(
                agent_summary.mean_crossing_step[1];
                digits=1
            ),
            " ± ",
            round(
                agent_summary.sd_crossing_step[1];
                digits=1
            ),
            " SD"
        )

    else

        println("Initial Z (eventual outliers):    NA")
        println("Final Z:                          NA")
        println("Persistent crossing step:         NA")
    end

    println()
    println("="^72)

    # ============================================================
    # 7. RETURN
    # ============================================================

    return (
        outlier_count_summary = outlier_count_summary,
        agent_summary = agent_summary,
        initial_state_summary = initial_state_summary,
        outlier_agents = outlier_agents,
        runs = run_results
    )
end
