### Beta
function summarize_and_plot_persistent_outliers_by_beta(
    path::String;
    threshold::Float64 = 2.5,
    fontfamily::String = "Calibri")

    # ============================================================
    # 1. LOAD DATA
    # ============================================================

    d = JLD2.load(path)

    Z_all = d["Z_all"]
    betas = Float64.(d["beta_value"])
    steps_axis = Int.(d["steps_axis"])

    n_runs, T, N = size(Z_all)

    @assert length(betas) == n_runs
    @assert length(steps_axis) == T

    # Only beta = 0.5, 1.0, ..., 14.0
    beta_values = collect(0.5:0.5:14.0)

    # ============================================================
    # 2. RUN-LEVEL AND AGENT-LEVEL RESULTS
    # ============================================================

    run_results = DataFrames.DataFrame(
        beta = Float64[],
        run = Int[],
        n_outliers = Int[],
        has_outlier = Bool[]
    )

    outlier_agents = DataFrames.DataFrame(
        beta = Float64[],
        run = Int[],
        agent = Int[],
        crossing_step = Int[],
        final_z = Float64[]
    )

    println("Analyzing $n_runs runs...")

    for r in 1:n_runs

        beta = betas[r]

        # Ignore beta = 0 and anything outside the requested range
        if !(beta in beta_values)
            continue
        end

        n_outliers = 0

        for agent in 1:N

            ztraj = @view Z_all[r, :, agent]

            # ----------------------------------------------------
            # First crossing that remains above threshold
            # until the final recorded timepoint
            # ----------------------------------------------------

            t_persistent = nothing

            for t in 1:T

                if ztraj[t] >= threshold &&
                   all(ztraj[t:T] .>= threshold)

                    t_persistent = t
                    break
                end
            end

            if t_persistent !== nothing

                n_outliers += 1

                push!(
                    outlier_agents,
                    (
                        beta,
                        r,
                        agent,
                        steps_axis[t_persistent],
                        Float64(ztraj[end])
                    )
                )
            end
        end

        push!(
            run_results,
            (
                beta,
                r,
                n_outliers,
                n_outliers > 0
            )
        )

        if r % 500 == 0 || r == n_runs
            println("Processed $r / $n_runs runs")
        end
    end

    # ============================================================
    # 3. SUMMARY BY BETA
    # ============================================================

    beta_summary = DataFrames.DataFrame(
        beta = Float64[],
        n_runs = Int[],
        runs_with_outlier = Int[],
        percentage_with_outlier = Float64[],
        n_outlier_agents = Int[],
        mean_final_z = Float64[],
        sd_final_z = Float64[],
        mean_crossing_step = Float64[],
        sd_crossing_step = Float64[]
    )

    for beta in beta_values

        runs_beta =
            run_results[
                run_results.beta .== beta,
                :
            ]

        agents_beta =
            outlier_agents[
                outlier_agents.beta .== beta,
                :
            ]

        n_runs_beta =
            DataFrames.nrow(runs_beta)

        runs_with_outlier =
            n_runs_beta == 0 ?
            0 :
            sum(runs_beta.has_outlier)

        percentage_with_outlier =
            n_runs_beta == 0 ?
            NaN :
            100.0 *
            runs_with_outlier /
            n_runs_beta

        n_agents_beta =
            DataFrames.nrow(agents_beta)

        if n_agents_beta > 0

            final_z =
                Float64.(
                    agents_beta.final_z
                )

            crossing =
                Float64.(
                    agents_beta.crossing_step
                )

            mean_final_z =
                Statistics.mean(final_z)

            sd_final_z =
                length(final_z) > 1 ?
                Statistics.std(final_z) :
                NaN

            mean_crossing_step =
                Statistics.mean(crossing)

            sd_crossing_step =
                length(crossing) > 1 ?
                Statistics.std(crossing) :
                NaN

        else

            mean_final_z = NaN
            sd_final_z = NaN
            mean_crossing_step = NaN
            sd_crossing_step = NaN
        end

        push!(
            beta_summary,
            (
                beta,
                n_runs_beta,
                runs_with_outlier,
                percentage_with_outlier,
                n_agents_beta,
                mean_final_z,
                sd_final_z,
                mean_crossing_step,
                sd_crossing_step
            )
        )
    end

    # ============================================================
    # 4. PLOT 1 — % RUNS WITH PERSISTENT OUTLIER
    # ============================================================

    p_percentage = Plots.plot(
        beta_summary.beta,
        beta_summary.percentage_with_outlier;
        marker = :circle,
        markersize = 5,
        markerstrokewidth = 0,
        linewidth = 2.5,

        xlabel = "Homophily (β)",
        ylabel = "Simulations with Persistent Semantic Atypicality (%)",
        title = "Persistent Outlier Occurrence",

        xlims = (0.25, 14.25),
        ylims = (0, 100),

        xticks = 1:1:14,
        yticks = 0:20:100,

        legend = false,
        grid = false,
        framestyle = :box,

        fontfamily = fontfamily,
        guidefontsize = 12,
        tickfontsize = 10,
        titlefontsize = 13,

        left_margin = 7Plots.mm,
        bottom_margin = 6Plots.mm,
        top_margin = 4Plots.mm,

        size = (850, 500)
    )

    # ============================================================
    # 5. PLOT 2 — FINAL Z OF OUTLIER AGENTS
    # ============================================================

    p_final_z =
        Plots.plot(
            beta_summary.beta,
            beta_summary.mean_final_z;
            yerror = beta_summary.sd_final_z,
            marker = :circle,
            linewidth = 2,
            markersize = 5,
            xlabel = "Homophily (β)",
            ylabel = "Final Z",
            title = "Final Semantic Atypicality",
            legend = false,
            xticks = 0.5:0.5:14.0,
            xrotation = 45,
            fontfamily = fontfamily,
            grid = true,
            size = (900, 500)
        )

    Plots.hline!(
        p_final_z,
        [threshold];
        linestyle = :dash,
        linewidth = 1.5,
        label = false
    )

    # ============================================================
    # 6. PLOT 3 — PERSISTENT CROSSING STEP
    # ============================================================

    p_crossing =
        Plots.plot(
            beta_summary.beta,
            beta_summary.mean_crossing_step;
            yerror = beta_summary.sd_crossing_step,
            marker = :circle,
            linewidth = 2,
            markersize = 5,
            xlabel = "Homophily (β)",
            ylabel = "Persistent Crossing Step",
            title = "Onset of Persistent Semantic Atypicality",
            legend = false,
            xticks = 0.5:0.5:14.0,
            xrotation = 45,
            fontfamily = fontfamily,
            grid = true,
            size = (900, 500)
        )

    # ============================================================
    # 7. PRINT CLEAR RESULTS
    # ============================================================

    println()
    println("="^100)
    println("PERSISTENT OUTLIERS BY BETA")
    println("="^100)

    for row in DataFrames.eachrow(beta_summary)

        println()
        println("β = ", row.beta)
        println("-"^45)

        println(
            "Runs with persistent outlier:  ",
            row.runs_with_outlier,
            " / ",
            row.n_runs,
            " (",
            round(
                row.percentage_with_outlier;
                digits = 2
            ),
            "%)"
        )

        println(
            "Persistent outlier agents:     ",
            row.n_outlier_agents
        )

        if row.n_outlier_agents > 0

            println(
                "Final Z:                       ",
                round(
                    row.mean_final_z;
                    digits = 3
                ),
                " ± ",
                round(
                    row.sd_final_z;
                    digits = 3
                ),
                " SD"
            )

            println(
                "Persistent crossing step:      ",
                round(
                    row.mean_crossing_step;
                    digits = 1
                ),
                " ± ",
                round(
                    row.sd_crossing_step;
                    digits = 1
                ),
                " SD"
            )

        else

            println(
                "Final Z:                       NA"
            )

            println(
                "Persistent crossing step:      NA"
            )
        end
    end

    println()
    println("="^100)

    # ============================================================
    # 8. DISPLAY PLOTS
    # ============================================================

    display(p_percentage)
    display(p_final_z)
    display(p_crossing)

    # ============================================================
    # 9. RETURN
    # ============================================================

    return (
        summary = beta_summary,
        runs = run_results,
        outlier_agents = outlier_agents,
        percentage_plot = p_percentage,
        final_z_plot = p_final_z,
        crossing_plot = p_crossing
    )
end
