function analyze_beta_segmented_logistic_no_beta_0(
    path::String;
    threshold::Float64 = 2.5,
    min_beta_levels_per_segment::Int = 4,
    plot_criterion::Symbol = :AIC)

    # ============================================================
    # 1. Load data
    # ============================================================

    d = JLD2.load(path)

    Z_all = d["Z_all"]          # runs × T × N
    betas = Float64.(d["beta_value"])

    n_runs_original, T, N = size(Z_all)

    @assert length(betas) == n_runs_original

    # ============================================================
    # Remove beta = 0 completely
    # ============================================================

    keep_runs = betas .> 0.0

    Z_all = Z_all[keep_runs, :, :]
    betas = betas[keep_runs]

    n_runs, T, N = size(Z_all)

    uniq_betas = sort(unique(betas))
    n_beta = length(uniq_betas)

    expected_betas = collect(0.5:0.5:14.0)

    if uniq_betas != expected_betas
        error(
            "Expected beta values 0.5:0.5:14.0, but found:\n$uniq_betas"
        )
    end

    println()
    println("Beta = 0 excluded from the analysis.")
    println("Original runs: ", n_runs_original)
    println("Runs analyzed: ", n_runs)
    println("Beta range:    0.5–14.0")

    # ============================================================
    # 2. Identify whether each simulation contains at least one
    #    persistent semantic outlier.
    #
    #    This preserves the existing definition:
    #    SA >= threshold from some measurement point through
    #    the end of the simulation.
    # ============================================================

    run_emergence = falses(n_runs)

    println("Identifying persistent semantic atypicality...")

    for r in 1:n_runs

        found_in_run = false

        for agent in 1:N

            ztraj = @view Z_all[r, :, agent]

            for t in 1:T

                if ztraj[t] >= threshold &&
                   all(@view(ztraj[t:T]) .>= threshold)

                    found_in_run = true
                    break
                end
            end

            if found_in_run
                break
            end
        end

        run_emergence[r] = found_in_run

        if r == 1 || r % 500 == 0 || r == n_runs
            println("  Run $r / $n_runs")
        end
    end

    # ============================================================
    # 3. Aggregate success/failure counts by beta
    # ============================================================

    beta_summary = DataFrames.DataFrame(
        beta = Float64[],
        n_success = Int[],
        n_failure = Int[],
        n_total = Int[],
        proportion = Float64[]
    )

    for b in uniq_betas

        idx = findall(betas .== b)

        total = length(idx)
        success = count(run_emergence[idx])
        failure = total - success

        push!(
            beta_summary,
            (
                b,
                success,
                failure,
                total,
                success / total
            )
        )
    end

    # Verify 150 simulations per beta
    if any(beta_summary.n_total .!= 150)
        error(
            "Expected 150 simulations per beta. Found:\n" *
            string(beta_summary[:, [:beta, :n_total]])
        )
    end

    # ============================================================
    # 4. Construct run-level DataFrame for binomial logistic models
    # ============================================================

    model_df = DataFrames.DataFrame(
        beta = betas,
        emergence = Int.(run_emergence)
    )

    # ============================================================
    # 5. Helper: hinge-variable model
    #
    # eta =
    #   b0 +
    #   b1 * beta +
    #   b2 * max(0, beta - c1) +
    #   b3 * max(0, beta - c2) + ...
    #
    # This guarantees continuity at every breakpoint.
    # ============================================================

    function fit_hinge_model(
        df::DataFrames.DataFrame,
        breakpoints::Vector{Float64}
    )

        tmp = copy(df)

        for (j, bp) in enumerate(breakpoints)
            tmp[!, Symbol("hinge$j")] =
                max.(0.0, tmp.beta .- bp)
        end

        if isempty(breakpoints)

            model = GLM.glm(
                @formula(emergence ~ beta),
                tmp,
                GLM.Binomial(),
                GLM.LogitLink()
            )

        elseif length(breakpoints) == 1

            model = GLM.glm(
                @formula(emergence ~ beta + hinge1),
                tmp,
                GLM.Binomial(),
                GLM.LogitLink()
            )

        elseif length(breakpoints) == 2

            model = GLM.glm(
                @formula(emergence ~ beta + hinge1 + hinge2),
                tmp,
                GLM.Binomial(),
                GLM.LogitLink()
            )

        elseif length(breakpoints) == 3

            model = GLM.glm(
                @formula(emergence ~ beta + hinge1 + hinge2 + hinge3),
                tmp,
                GLM.Binomial(),
                GLM.LogitLink()
            )

        else
            error("Only 0–3 breakpoints are supported.")
        end

        return model
    end

    # ============================================================
    # 6. Candidate breakpoint locations
    #
    # Breakpoints are midpoints between adjacent observed beta
    # levels.
    #
    # Example:
    # observed beta: 3.0, 3.5
    # candidate breakpoint: 3.25
    #
    # Every resulting segment must contain at least
    # min_beta_levels_per_segment observed beta levels.
    # ============================================================

    candidate_breakpoints =
        (uniq_betas[1:end-1] .+ uniq_betas[2:end]) ./ 2

    println()
    println(
        "Minimum observed beta levels per segment = ",
        min_beta_levels_per_segment
    )

    # ============================================================
    # 7. Helper: validate segment sizes
    # ============================================================

    function valid_breakpoints(
        breakpoints::Vector{Float64}
    )

        bps = sort(breakpoints)

        boundaries =
            vcat(-Inf, bps, Inf)

        for s in 1:(length(boundaries) - 1)

            lo = boundaries[s]
            hi = boundaries[s + 1]

            if s == 1
                n_levels =
                    count(x -> x < hi, uniq_betas)

            elseif s == length(boundaries) - 1
                n_levels =
                    count(x -> x > lo, uniq_betas)

            else
                n_levels =
                    count(x -> lo < x < hi, uniq_betas)
            end

            if n_levels < min_beta_levels_per_segment
                return false
            end
        end

        return true
    end

    # ============================================================
    # 8. Fit 0-breakpoint model
    # ============================================================

    println()
    println("Fitting model with 0 breakpoints...")

    model0 = fit_hinge_model(
        model_df,
        Float64[]
    )

    # ============================================================
    # 9. Exhaustive breakpoint search
    #
    # For a fixed number of breakpoints, choose the combination
    # with the highest likelihood.
    # ============================================================

    function search_breakpoints(n_breakpoints::Int)

        println()
        println(
            "Searching model with ",
            n_breakpoints,
            " breakpoint",
            n_breakpoints == 1 ? "..." : "s..."
        )

        best_model = nothing
        best_breakpoints = Float64[]
        best_loglik = -Inf

        n_tested = 0
        n_valid = 0

        candidates = candidate_breakpoints

        if n_breakpoints == 1

            total_candidates = length(candidates)

            for (i, bp1) in enumerate(candidates)

                bps = [bp1]

                if !valid_breakpoints(bps)
                    continue
                end

                n_valid += 1

                model =
                    fit_hinge_model(model_df, bps)

                ll = GLM.loglikelihood(model)

                n_tested += 1

                if ll > best_loglik
                    best_loglik = ll
                    best_model = model
                    best_breakpoints = copy(bps)
                end

                if i == 1 ||
                   i % 5 == 0 ||
                   i == total_candidates

                    println(
                        "  Candidate position ",
                        i,
                        " / ",
                        total_candidates
                    )
                end
            end

        elseif n_breakpoints == 2

            total_outer =
                length(candidates) - 1

            for i in 1:(length(candidates) - 1)

                for j in (i + 1):length(candidates)

                    bps = [
                        candidates[i],
                        candidates[j]
                    ]

                    if !valid_breakpoints(bps)
                        continue
                    end

                    n_valid += 1

                    model =
                        fit_hinge_model(model_df, bps)

                    ll = GLM.loglikelihood(model)

                    n_tested += 1

                    if ll > best_loglik
                        best_loglik = ll
                        best_model = model
                        best_breakpoints = copy(bps)
                    end
                end

                if i == 1 ||
                   i % 5 == 0 ||
                   i == total_outer

                    println(
                        "  Outer search position ",
                        i,
                        " / ",
                        total_outer
                    )
                end
            end

        elseif n_breakpoints == 3

            total_outer =
                length(candidates) - 2

            for i in 1:(length(candidates) - 2)

                for j in (i + 1):(length(candidates) - 1)

                    for k in (j + 1):length(candidates)

                        bps = [
                            candidates[i],
                            candidates[j],
                            candidates[k]
                        ]

                        if !valid_breakpoints(bps)
                            continue
                        end

                        n_valid += 1

                        model =
                            fit_hinge_model(model_df, bps)

                        ll = GLM.loglikelihood(model)

                        n_tested += 1

                        if ll > best_loglik
                            best_loglik = ll
                            best_model = model
                            best_breakpoints = copy(bps)
                        end
                    end
                end

                if i == 1 ||
                   i % 3 == 0 ||
                   i == total_outer

                    println(
                        "  Outer search position ",
                        i,
                        " / ",
                        total_outer
                    )
                end
            end
        end

        if best_model === nothing
            error(
                "No valid model found for $n_breakpoints breakpoints."
            )
        end

        println(
            "  Valid combinations fitted: ",
            n_valid
        )

        println(
            "  Best breakpoints: ",
            best_breakpoints
        )

        return (
            model = best_model,
            breakpoints = best_breakpoints,
            loglik = best_loglik
        )
    end

    fit1 = search_breakpoints(1)
    fit2 = search_breakpoints(2)
    fit3 = search_breakpoints(3)

    fits = [
        (
            model = model0,
            breakpoints = Float64[],
            loglik = GLM.loglikelihood(model0)
        ),
        fit1,
        fit2,
        fit3
    ]

    # ============================================================
    # 10. Model comparison
    #
    # k for AIC/BIC:
    #
    # coefficient parameters:
    #   intercept + beta + one hinge coefficient per breakpoint
    #
    # PLUS:
    #   one estimated-location parameter per breakpoint.
    #
    # Therefore:
    #
    # 0 BP -> 2 parameters
    # 1 BP -> 4 parameters
    # 2 BP -> 6 parameters
    # 3 BP -> 8 parameters
    #
    # This explicitly counts breakpoint locations as estimated
    # parameters, as requested.
    # ============================================================

    comparison = DataFrames.DataFrame(
        Breakpoints = Int[],
        Locations = String[],
        k = Int[],
        LogLik = Float64[],
        Deviance = Float64[],
        AIC = Float64[],
        BIC = Float64[]
    )

    n_observations = DataFrames.nrow(model_df)

    for (n_bp, fit) in enumerate(fits)

        n_breakpoints = n_bp - 1

        model = fit.model
        bps = fit.breakpoints

        ll = GLM.loglikelihood(model)

        # Number of regression coefficients
        n_coefficients =
            length(GLM.coef(model))

        # Add one free parameter for each estimated breakpoint
        k_total =
            n_coefficients + n_breakpoints

        dev =
            GLM.deviance(model)

        aic =
            -2 * ll + 2 * k_total

        bic =
            -2 * ll +
            log(n_observations) * k_total

        locations_string =
            isempty(bps) ?
            "None" :
            join(
                string.(round.(bps, digits = 3)),
                ", "
            )

        push!(
            comparison,
            (
                n_breakpoints,
                locations_string,
                k_total,
                ll,
                dev,
                aic,
                bic
            )
        )
    end

    comparison[!, :ΔAIC] =
        comparison.AIC .- minimum(comparison.AIC)

    comparison[!, :ΔBIC] =
        comparison.BIC .- minimum(comparison.BIC)

    # ============================================================
    # 11. Segment-specific slopes
    #
    # Segment slopes:
    #
    # segment 1:
    #   beta
    #
    # segment 2:
    #   beta + hinge1
    #
    # segment 3:
    #   beta + hinge1 + hinge2
    #
    # etc.
    #
    # SE is calculated from the full covariance matrix:
    #
    # Var(a'b) = a' V a
    #
    # This correctly accounts for covariance among beta and
    # hinge coefficients.
    # ============================================================

    function segment_slope_table(
        model,
        breakpoints::Vector{Float64}
    )

        coef_values = GLM.coef(model)
        V = GLM.vcov(model)

        n_segments =
            length(breakpoints) + 1

        rows = DataFrames.DataFrame(
            Segment = Int[],
            Beta_range = String[],
            Slope_log_odds = Float64[],
            SE = Float64[],
            CI95 = String[],
            OR = Float64[],
            OR_CI95 = String[],
            p = Float64[]
        )

        normal_dist =
            Distributions.Normal()

        for segment in 1:n_segments

            # Contrast vector for the segment slope.
            #
            # coefficient order:
            # intercept, beta, hinge1, hinge2, ...
            a = zeros(Float64, length(coef_values))

            # beta coefficient
            a[2] = 1.0

            # Add all hinge coefficients activated before
            # this segment.
            if segment > 1
                for j in 1:(segment - 1)
                    a[2 + j] = 1.0
                end
            end

            slope =
                dot(a, coef_values)

            slope_var =
                dot(a, V * a)

            slope_se =
                sqrt(max(slope_var, 0.0))

            z =
                slope / slope_se

            p_value =
                2 * (
                    1 -
                    Distributions.cdf(
                        normal_dist,
                        abs(z)
                    )
                )

            ci_low =
                slope - 1.96 * slope_se

            ci_high =
                slope + 1.96 * slope_se

            odds_ratio =
                exp(slope)

            or_low =
                exp(ci_low)

            or_high =
                exp(ci_high)

            # --------------------------------------------
            # Segment range label
            # --------------------------------------------

            if isempty(breakpoints)

                range_string =
                    "$(minimum(uniq_betas))–$(maximum(uniq_betas))"

            elseif segment == 1

                range_string =
                    "$(minimum(uniq_betas))–$(breakpoints[1])"

            elseif segment == n_segments

                range_string =
                    "$(breakpoints[end])–$(maximum(uniq_betas))"

            else

                range_string =
                    "$(breakpoints[segment-1])–$(breakpoints[segment])"
            end

            ci_string =
                "[$(round(ci_low, digits=4)), " *
                "$(round(ci_high, digits=4))]"

            or_ci_string =
                "[$(round(or_low, digits=4)), " *
                "$(round(or_high, digits=4))]"

            push!(
                rows,
                (
                    segment,
                    range_string,
                    slope,
                    slope_se,
                    ci_string,
                    odds_ratio,
                    or_ci_string,
                    p_value
                )
            )
        end

        return rows
    end

    slope_tables = Dict{Int,DataFrames.DataFrame}()

    for i in 1:length(fits)

        n_breakpoints = i - 1

        slope_tables[n_breakpoints] =
            segment_slope_table(
                fits[i].model,
                fits[i].breakpoints
            )
    end

    # ============================================================
    # 12. Identify minimum AIC / BIC
    # ============================================================

    best_aic_row =
        argmin(comparison.AIC)

    best_bic_row =
        argmin(comparison.BIC)

    best_aic_bp =
        comparison.Breakpoints[best_aic_row]

    best_bic_bp =
        comparison.Breakpoints[best_bic_row]

    # ============================================================
    # 13. Predicted probability curves
    # ============================================================

    beta_grid =
        collect(
            range(
                minimum(uniq_betas),
                maximum(uniq_betas),
                length = 500
            )
        )

    function predict_curve(
        model,
        breakpoints::Vector{Float64}
    )

        pred_df =
            DataFrames.DataFrame(
                beta = beta_grid
            )

        for (j, bp) in enumerate(breakpoints)

            pred_df[!, Symbol("hinge$j")] =
                max.(0.0, beta_grid .- bp)
        end

        return GLM.predict(model, pred_df)
    end

    prediction_curves =
        [
            predict_curve(
                fit.model,
                fit.breakpoints
            )
            for fit in fits
        ]

        # ============================================================
        # 14. Plot
        # ============================================================

        best_plot_idx =
            plot_criterion == :AIC ?
            best_aic_row :
            best_bic_row

        best_plot_fit =
            fits[best_plot_idx]

        best_plot_curve =
            prediction_curves[best_plot_idx]

        best_plot_breakpoints =
            best_plot_fit.breakpoints


        # ------------------------------------------------------------
        # Observed proportions
        # ------------------------------------------------------------

        p = Plots.plot(
            beta_summary.beta,
            beta_summary.proportion;
            marker = :circle,
            markersize = 6,
            markerstrokewidth = 0,
            linewidth = 2,
            label = "Observed",

            xlabel = "Homophily (β)",
            ylabel = "Proportion of Simulations with Persistent Semantic Atypicality",

            xlims = (0.25, 14.25),
            ylims = (0.0, 1.0),

            xticks = 1:1:14,
            yticks = 0:0.2:1.0,

            grid = false,
            framestyle = :box,

            fontfamily = "Calibri",

            guidefontsize = 13,
            tickfontsize = 11,
            legendfontsize = 10,

            legend = (1.08, 0.5),

            left_margin = 8Plots.mm,
            right_margin = 4Plots.mm,
            bottom_margin = 7Plots.mm,
            top_margin = 4Plots.mm,

            size = (900, 560)
        )


        # ------------------------------------------------------------
        # Best-fitting segmented logistic model
        # ------------------------------------------------------------

        n_best_breakpoints =
            best_plot_idx - 1

        model_label =
            n_best_breakpoints == 0 ?
            "Logistic fit" :
            "Segmented logistic fit"

        Plots.plot!(
            p,
            beta_grid,
            best_plot_curve;
            linewidth = 3,
            label = model_label
        )


        # ------------------------------------------------------------
        # Breakpoints
        #
        # Mark each breakpoint directly on the fitted curve.
        # No legend entry.
        # ------------------------------------------------------------

        for bp in best_plot_breakpoints

            breakpoint_df =
                DataFrames.DataFrame(
                    beta = [bp]
                )

            for (j, model_bp) in enumerate(best_plot_breakpoints)

                breakpoint_df[
                    !,
                    Symbol("hinge$j")
                ] =
                    max.(
                        0.0,
                        breakpoint_df.beta .- model_bp
                    )
            end

            breakpoint_y =
                GLM.predict(
                    best_plot_fit.model,
                    breakpoint_df
                )[1]

            Plots.scatter!(
                p,
                [bp],
                [breakpoint_y];
                markersize = 6,
                markerstrokewidth = 0,
                color = Plots.palette(:auto)[2],
                label = false
            )
        end
    # ============================================================
    # 15. Print results
    # ============================================================

    println()
    println("="^100)
    println("PERSISTENT SEMANTIC ATYPICALITY BY HOMOPHILY LEVEL")
    println("="^100)

    show(
        stdout,
        beta_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )
    println()

    println()
    println("="^100)
    println("MODEL COMPARISON")
    println("="^100)

    show(
        stdout,
        comparison;
        allrows = true,
        allcols = true,
        truncate = 0
    )
    println()

    # Requested breakpoint-model slope tables
    for n_breakpoints in 1:3

        println()
        println("="^100)
        println(
            "SEGMENT SLOPES — ",
            n_breakpoints,
            " BREAKPOINT",
            n_breakpoints == 1 ? "" : "S"
        )

        println(
            "Breakpoints: ",
            fits[n_breakpoints + 1].breakpoints
        )

        println("="^100)

        show(
            stdout,
            slope_tables[n_breakpoints];
            allrows = true,
            allcols = true,
            truncate = 0
        )
        println()
    end

    println()
    println("="^100)
    println("AIC / BIC")
    println("="^100)

    println(
        "Lowest AIC: model with ",
        best_aic_bp,
        " breakpoint",
        best_aic_bp == 1 ? "" : "s",
        " (AIC = ",
        round(comparison.AIC[best_aic_row], digits = 3),
        ")"
    )

    println(
        "Lowest BIC: model with ",
        best_bic_bp,
        " breakpoint",
        best_bic_bp == 1 ? "" : "s",
        " (BIC = ",
        round(comparison.BIC[best_bic_row], digits = 3),
        ")"
    )

    if best_aic_bp != best_bic_bp

        println()
        println(
            "AIC and BIC select different models; " *
            "no single model is designated as the preferred model."
        )
    end

    display(p)

    # ============================================================
    # 16. Return
    # ============================================================

    return (
        beta_summary = beta_summary,
        model_comparison = comparison,

        models = Dict(
            0 => fits[1].model,
            1 => fits[2].model,
            2 => fits[3].model,
            3 => fits[4].model
        ),

        breakpoints = Dict(
            0 => fits[1].breakpoints,
            1 => fits[2].breakpoints,
            2 => fits[3].breakpoints,
            3 => fits[4].breakpoints
        ),

        segment_slopes = slope_tables,

        prediction_beta = beta_grid,
        prediction_curves = prediction_curves,

        plot = p
    )
end
# segmented_results =
#     analyze_beta_segmented_logistic_no_beta_0(
#         z_path;
#         threshold = 2.5,
#         min_beta_levels_per_segment = 4,
#         plot_criterion = :BIC
# )
function null_test_beta_segmented_logistic_one_breakpoint(
    path::String;
    threshold::Float64 = 2.5,
    min_beta_levels_per_segment::Int = 4,
    n_null::Int = 10_000,
    observed_slope_before::Float64 = 0.894469,
    observed_z_before::Float64 = 9.29,
    observed_slope_after::Float64 = -0.188184,
    progress_every::Int = 100)

    # ============================================================
    # 1. Load original data
    # ============================================================

    d = JLD2.load(path)

    Z_all = d["Z_all"]          # runs × T × N
    betas = Float64.(d["beta_value"])

    n_runs_original, T, N = size(Z_all)

    @assert length(betas) == n_runs_original


    # ============================================================
    # 2. Remove beta = 0
    # ============================================================

    keep_runs = betas .> 0.0

    Z_all = Z_all[keep_runs, :, :]
    betas = betas[keep_runs]

    n_runs, T, N = size(Z_all)

    uniq_betas = sort(unique(betas))

    expected_betas = collect(0.5:0.5:14.0)

    if uniq_betas != expected_betas
        error(
            "Expected beta values 0.5:0.5:14.0, but found:\n$uniq_betas"
        )
    end


    # ============================================================
    # 3. Identify persistent semantic atypicality in original data
    #
    # Same definition as existing analysis:
    # at least one agent whose z >= threshold from some
    # measurement point through the end.
    # ============================================================

    run_emergence = falses(n_runs)

    println()
    println("="^90)
    println("NULL SIMULATION TEST — ONE-BREAKPOINT SEGMENTED LOGISTIC MODEL")
    println("="^90)

    println()
    println("Identifying persistent semantic atypicality in original data...")

    for r in 1:n_runs

        found_in_run = false

        for agent in 1:N

            ztraj = @view Z_all[r, :, agent]

            for t in 1:T

                if ztraj[t] >= threshold &&
                   all(@view(ztraj[t:T]) .>= threshold)

                    found_in_run = true
                    break
                end
            end

            if found_in_run
                break
            end
        end

        run_emergence[r] = found_in_run

        if r == 1 || r % 500 == 0 || r == n_runs
            println("  Run $r / $n_runs")
        end
    end


    # ============================================================
    # 4. Null probability
    #
    # H0:
    #
    # P(emergence | beta) = p
    #
    # where p is the overall emergence proportion across
    # beta = 0.5–14 in the original data.
    # ============================================================

    p_null =
        Statistics.mean(run_emergence)

    n_original_emergence =
        count(run_emergence)

    println()
    println("Null model:")
    println("  P(emergence | beta) = p")
    println("  p = ", p_null)
    println("  Original emergence = ", n_original_emergence, " / ", n_runs)


    # ============================================================
    # 5. Verify original design
    # ============================================================

    for b in uniq_betas

        n_b =
            count(betas .== b)

        if n_b != 150
            error(
                "Expected 150 simulations for beta = $b, " *
                "but found $n_b."
            )
        end
    end

    if n_runs != 4200
        error(
            "Expected 4200 runs after excluding beta = 0, " *
            "but found $n_runs."
        )
    end


    # ============================================================
    # 6. Candidate breakpoint locations
    #
    # Same procedure as original analysis:
    # midpoints between adjacent observed beta levels.
    # ============================================================

    candidate_breakpoints =
        (uniq_betas[1:end-1] .+ uniq_betas[2:end]) ./ 2


    # ============================================================
    # 7. Same breakpoint validity rule as original analysis
    # ============================================================

    function valid_breakpoints(
        breakpoints::Vector{Float64}
    )

        bps = sort(breakpoints)

        boundaries =
            vcat(-Inf, bps, Inf)

        for s in 1:(length(boundaries) - 1)

            lo = boundaries[s]
            hi = boundaries[s + 1]

            if s == 1

                n_levels =
                    count(x -> x < hi, uniq_betas)

            elseif s == length(boundaries) - 1

                n_levels =
                    count(x -> x > lo, uniq_betas)

            else

                n_levels =
                    count(x -> lo < x < hi, uniq_betas)
            end

            if n_levels < min_beta_levels_per_segment
                return false
            end
        end

        return true
    end


    valid_candidates =
        [
            bp
            for bp in candidate_breakpoints
            if valid_breakpoints([bp])
        ]

    if isempty(valid_candidates)
        error("No valid one-breakpoint candidates.")
    end

    println()
    println("Valid breakpoint candidates:")
    println(valid_candidates)


    # ============================================================
    # 8. One-breakpoint hinge model
    #
    # EXACT SAME FORM:
    #
    # eta =
    #     b0 +
    #     b1 * beta +
    #     b2 * max(0, beta - breakpoint)
    #
    # Therefore:
    #
    # slope_before = b1
    # slope_after  = b1 + b2
    # ============================================================

    function fit_one_breakpoint_model(
        df::DataFrames.DataFrame,
        breakpoint::Float64
    )

        tmp = copy(df)

        tmp[!, :hinge1] =
            max.(0.0, tmp.beta .- breakpoint)

        model = GLM.glm(
            @formula(emergence ~ beta + hinge1),
            tmp,
            GLM.Binomial(),
            GLM.LogitLink()
        )

        return model
    end


    # ============================================================
    # 9. Exhaustive one-breakpoint search
    #
    # Same criterion as original analysis:
    # select the valid breakpoint giving maximum log-likelihood.
    # ============================================================

    function search_one_breakpoint(
        df::DataFrames.DataFrame
    )

        best_model = nothing
        best_breakpoint = NaN
        best_loglik = -Inf

        for bp in candidate_breakpoints

            bps = [bp]

            if !valid_breakpoints(bps)
                continue
            end

            model =
                fit_one_breakpoint_model(
                    df,
                    bp
                )

            ll =
                GLM.loglikelihood(model)

            if ll > best_loglik

                best_loglik = ll
                best_model = model
                best_breakpoint = bp
            end
        end

        if best_model === nothing
            error(
                "No valid one-breakpoint model could be fitted."
            )
        end

        return (
            model = best_model,
            breakpoint = best_breakpoint,
            loglik = best_loglik
        )
    end


    # ============================================================
    # 10. Storage
    # ============================================================

    null_results =
        DataFrames.DataFrame(
            iteration = Int[],
            breakpoint = Float64[],

            slope_before = Float64[],
            se_before = Float64[],
            z_before = Float64[],

            slope_after = Float64[],
            se_after = Float64[],
            z_after = Float64[]
        )

    failed_iterations = Int[]


    # ============================================================
    # 11. Null simulations
    #
    # Fixed design:
    #   beta = 0.5:0.5:14
    #   150 observations at every beta
    #
    # Null data-generating process:
    #   emergence ~ Bernoulli(p_null)
    #
    # independently of beta.
    #
    # The breakpoint is searched again in EVERY iteration.
    # ============================================================

    println()
    println("="^90)
    println("STARTING NULL SIMULATIONS")
    println("="^90)

    println("Iterations: ", n_null)
    println("Progress every: ", progress_every)

    for iteration in 1:n_null

        # --------------------------------------------------------
        # Generate null emergence
        # --------------------------------------------------------

        null_emergence =
            Int.(
                rand(n_runs) .< p_null
            )

        null_df =
            DataFrames.DataFrame(
                beta = betas,
                emergence = null_emergence
            )


        # --------------------------------------------------------
        # Search for optimal breakpoint
        # --------------------------------------------------------

        try

            fit =
                search_one_breakpoint(
                    null_df
                )

            coef_values =
                GLM.coef(fit.model)

            V =
                GLM.vcov(fit.model)


            # ====================================================
            # Segment BEFORE breakpoint
            #
            # slope_before = beta coefficient
            # ====================================================

            slope_before =
                Float64(
                    coef_values[2]
                )

            var_before =
                Float64(
                    V[2, 2]
                )

            se_before =
                sqrt(
                    max(
                        var_before,
                        0.0
                    )
                )

            z_before =
                slope_before / se_before


            # ====================================================
            # Segment AFTER breakpoint
            #
            # slope_after = beta + hinge1
            #
            # Var(beta + hinge1) =
            #     Var(beta) +
            #     Var(hinge1) +
            #     2Cov(beta, hinge1)
            #
            # This is the same contrast logic used in the
            # original segment-slope analysis.
            # ====================================================

            slope_after =
                Float64(
                    coef_values[2] +
                    coef_values[3]
                )

            a_after =
                zeros(
                    Float64,
                    length(coef_values)
                )

            a_after[2] = 1.0
            a_after[3] = 1.0

            var_after =
                Float64(
                    dot(
                        a_after,
                        V * a_after
                    )
                )

            se_after =
                sqrt(
                    max(
                        var_after,
                        0.0
                    )
                )

            z_after =
                slope_after / se_after


            # ====================================================
            # Save iteration
            # ====================================================

            push!(
                null_results,
                (
                    iteration,
                    fit.breakpoint,

                    slope_before,
                    se_before,
                    z_before,

                    slope_after,
                    se_after,
                    z_after
                )
            )

        catch err

            push!(
                failed_iterations,
                iteration
            )
        end


        # --------------------------------------------------------
        # Progress printing
        # --------------------------------------------------------

        if iteration == 1 ||
           iteration % progress_every == 0 ||
           iteration == n_null

            println(
                "  Null iteration ",
                iteration,
                " / ",
                n_null,
                " | successful = ",
                DataFrames.nrow(null_results),
                " | failed = ",
                length(failed_iterations)
            )
        end
    end


    # ============================================================
    # 12. Successful / failed iterations
    # ============================================================

    B =
        DataFrames.nrow(null_results)

    n_failed =
        length(failed_iterations)

    if B == 0
        error("All null simulations failed.")
    end


    # ============================================================
    # 13. Summary helper
    # ============================================================

    function null_summary(
        values::AbstractVector{<:Real}
    )

        x =
            Float64.(values)

        return (
            mean =
                Statistics.mean(x),

            sd =
                Statistics.std(x),

            median =
                Statistics.median(x),

            q025 =
                Statistics.quantile(
                    x,
                    0.025
                ),

            q975 =
                Statistics.quantile(
                    x,
                    0.975
                )
        )
    end


    # ============================================================
    # 14. Null distribution summaries
    # ============================================================

    slope_before_summary =
        null_summary(
            null_results.slope_before
        )

    z_before_summary =
        null_summary(
            null_results.z_before
        )

    slope_after_summary =
        null_summary(
            null_results.slope_after
        )

    z_after_summary =
        null_summary(
            null_results.z_after
        )


    # ============================================================
    # 15. Empirical one-sided test:
    #     positive slope BEFORE breakpoint
    #
    # Observed:
    #     b_before = +0.894469
    #
    # Extreme null values are >= observed.
    # ============================================================

    n_slope_before_extreme =
        count(
            null_results.slope_before .>=
            observed_slope_before
        )

    p_slope_before =
        (1 + n_slope_before_extreme) /
        (B + 1)


    # ============================================================
    # 16. Empirical one-sided test:
    #     z BEFORE breakpoint
    #
    # Extreme null values are >= observed.
    # ============================================================

    n_z_before_extreme =
        count(
            null_results.z_before .>=
            observed_z_before
        )

    p_z_before =
        (1 + n_z_before_extreme) /
        (B + 1)


    # ============================================================
    # 17. Empirical one-sided test:
    #     negative slope AFTER breakpoint
    #
    # Observed:
    #     b_after = -0.188184
    #
    # Extreme null values are <= observed.
    # ============================================================

    n_slope_after_extreme =
        count(
            null_results.slope_after .<=
            observed_slope_after
        )

    p_slope_after =
        (1 + n_slope_after_extreme) /
        (B + 1)


    # ============================================================
    # 18. Directional frequencies under null
    # ============================================================

    proportion_before_positive =
        Statistics.mean(
            null_results.slope_before .> 0
        )

    percentage_before_positive =
        100.0 *
        proportion_before_positive


    proportion_after_negative =
        Statistics.mean(
            null_results.slope_after .< 0
        )

    percentage_after_negative =
        100.0 *
        proportion_after_negative


    proportion_positive_then_negative =
        Statistics.mean(
            (null_results.slope_before .> 0) .&
            (null_results.slope_after .< 0)
        )

    percentage_positive_then_negative =
        100.0 *
        proportion_positive_then_negative


    # ============================================================
    # 19. Breakpoint distribution
    # ============================================================

    breakpoint_distribution =
        DataFrames.combine(
            DataFrames.groupby(
                null_results,
                :breakpoint
            ),
            DataFrames.nrow => :n
        )

    breakpoint_distribution[!, :percentage] =
        100.0 .*
        breakpoint_distribution.n ./
        B

    DataFrames.sort!(
        breakpoint_distribution,
        :breakpoint
    )


    # ============================================================
    # 20. Null-distribution summary table
    # ============================================================

    null_distribution_summary =
        DataFrames.DataFrame(
            statistic = [
                "slope_before",
                "z_before",
                "slope_after",
                "z_after"
            ],

            mean = [
                slope_before_summary.mean,
                z_before_summary.mean,
                slope_after_summary.mean,
                z_after_summary.mean
            ],

            sd = [
                slope_before_summary.sd,
                z_before_summary.sd,
                slope_after_summary.sd,
                z_after_summary.sd
            ],

            median = [
                slope_before_summary.median,
                z_before_summary.median,
                slope_after_summary.median,
                z_after_summary.median
            ],

            q025 = [
                slope_before_summary.q025,
                z_before_summary.q025,
                slope_after_summary.q025,
                z_after_summary.q025
            ],

            q975 = [
                slope_before_summary.q975,
                z_before_summary.q975,
                slope_after_summary.q975,
                z_after_summary.q975
            ]
        )


    # ============================================================
    # 21. Empirical-test table
    # ============================================================

    empirical_tests =
        DataFrames.DataFrame(
            statistic = [
                "slope_before",
                "z_before",
                "slope_after"
            ],

            direction = [
                ">=",
                ">=",
                "<="
            ],

            observed = [
                observed_slope_before,
                observed_z_before,
                observed_slope_after
            ],

            n_null_at_or_beyond_observed = [
                n_slope_before_extreme,
                n_z_before_extreme,
                n_slope_after_extreme
            ],

            B = [
                B,
                B,
                B
            ],

            empirical_p = [
                p_slope_before,
                p_z_before,
                p_slope_after
            ]
        )


    # ============================================================
    # 22. Direction summary
    # ============================================================

    directional_summary =
        DataFrames.DataFrame(
            measure = [
                "slope_before > 0",
                "slope_after < 0",
                "slope_before > 0 AND slope_after < 0"
            ],

            proportion = [
                proportion_before_positive,
                proportion_after_negative,
                proportion_positive_then_negative
            ],

            percentage = [
                percentage_before_positive,
                percentage_after_negative,
                percentage_positive_then_negative
            ]
        )


    # ============================================================
    # 23. Print results
    # ============================================================

    println()
    println("="^90)
    println("NULL SIMULATION TEST COMPLETED")
    println("="^90)

    println("Constant null p:       ", p_null)
    println("Requested iterations:  ", n_null)
    println("Successful iterations: ", B)
    println("Failed iterations:     ", n_failed)


    println()
    println("="^90)
    println("NULL DISTRIBUTION SUMMARY")
    println("="^90)

    show(
        stdout,
        null_distribution_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()


    println()
    println("="^90)
    println("EMPIRICAL ONE-SIDED TESTS")
    println("="^90)

    show(
        stdout,
        empirical_tests;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()


    println()
    println("="^90)
    println("DIRECTIONAL PATTERNS UNDER NULL")
    println("="^90)

    show(
        stdout,
        directional_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()


    println()
    println("="^90)
    println("SELECTED BREAKPOINT DISTRIBUTION UNDER NULL")
    println("="^90)

    show(
        stdout,
        breakpoint_distribution;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()


    # ============================================================
    # 24. Return
    # ============================================================

    return (
        p_null =
            p_null,

        null_results =
            null_results,

        null_distribution_summary =
            null_distribution_summary,

        empirical_tests =
            empirical_tests,

        directional_summary =
            directional_summary,

        breakpoint_distribution =
            breakpoint_distribution,

        failed_iterations =
            failed_iterations,

        n_successful =
            B,

        n_failed =
            n_failed
    )
end
# null_results =
#     null_test_beta_segmented_logistic_one_breakpoint(
#         z_path;
#         threshold = 2.5,
#         min_beta_levels_per_segment = 4,
#         n_null = 10_000,
#         observed_slope_before = 0.894469,
#         observed_z_before = 9.29,
#         observed_slope_after = -0.188184,
#         progress_every = 100
# )

function analyze_Q10_Q90_with_Q90_spearman_permutation(
    path::String;
    n_permutations::Int = 100_000,
    seed::Int = 12345,
    alternative::Symbol = :two_sided,
    progress_every::Int = 10_000,
    fontfamily::String = "Calibri",
    plot_size = (950, 600))

    @assert alternative in (:two_sided, :greater, :less)

    # ============================================================
    # 1. Load final semantic distance matrices
    # ============================================================

    d = JLD2.load(path)

    @assert haskey(d, "final_distances") "Missing key: final_distances"
    @assert haskey(d, "beta_value") "Missing key: beta_value"
    @assert haskey(d, "sim") "Missing key: sim"

    final_distances = d["final_distances"]
    betas_all = Float64.(d["beta_value"])
    sims_all = Int.(d["sim"])

    n_runs, N1, N2 = size(final_distances)

    @assert N1 == N2
    @assert length(betas_all) == n_runs
    @assert length(sims_all) == n_runs

    N = N1
    n_pairs = N * (N - 1) ÷ 2


    # ============================================================
    # 2. Calculate Q10 and Q90 for every simulation
    # ============================================================

    q10_all = Vector{Float64}(undef, n_runs)
    q90_all = Vector{Float64}(undef, n_runs)

    distances = Vector{Float64}(undef, n_pairs)

    println("Calculating Q10 and Q90 for each simulation...")

    for r in 1:n_runs

        if r == 1 || r % 250 == 0 || r == n_runs
            println("Run ", r, " / ", n_runs)
            flush(stdout)
        end

        M = @view final_distances[r, :, :]

        k = 0

        @inbounds for i in 1:(N - 1)
            for j in (i + 1):N
                k += 1
                distances[k] = Float64(M[i, j])
            end
        end

        @assert k == n_pairs

        q10_all[r] = Statistics.quantile(distances, 0.10)
        q90_all[r] = Statistics.quantile(distances, 0.90)
    end


    # ============================================================
    # 3. Keep beta > 0
    # ============================================================

    keep = betas_all .> 0.0

    betas = betas_all[keep]
    sims = sims_all[keep]
    q10 = q10_all[keep]
    q90 = q90_all[keep]

    n = length(q90)

    df = DataFrames.DataFrame(
        beta = betas,
        sim = sims,
        Q10 = q10,
        Q90 = q90
    )

    beta_levels = sort(unique(betas))
    n_beta = length(beta_levels)


    # ============================================================
    # 4. Runs belonging to each beta
    # ============================================================

    beta_indices = [
        findall(==(β), betas)
        for β in beta_levels
    ]

    n_per_beta = length.(beta_indices)

    @assert length(unique(n_per_beta)) == 1 """
    Different numbers of simulations across beta levels.
    """

    n_each = first(n_per_beta)

    @assert n == n_beta * n_each

    println("\nPositive beta levels: ", n_beta)
    println("Simulations per beta: ", n_each)
    println("Total simulations: ", n)


    # ============================================================
    # 5. Mean and SD of Q10/Q90 at each beta
    # ============================================================

    mean_q10 = [
        Statistics.mean(@view q10[idx])
        for idx in beta_indices
    ]

    sd_q10 = [
        Statistics.std(@view q10[idx])
        for idx in beta_indices
    ]

    mean_q90 = [
        Statistics.mean(@view q90[idx])
        for idx in beta_indices
    ]

    sd_q90 = [
        Statistics.std(@view q90[idx])
        for idx in beta_indices
    ]

    summary = DataFrames.DataFrame(
        beta = beta_levels,
        mean_Q10 = mean_q10,
        sd_Q10 = sd_q10,
        mean_Q90 = mean_q90,
        sd_Q90 = sd_q90,
        n_runs = n_per_beta
    )


    # ============================================================
    # 6. Observed Spearman:
    #    beta vs mean Q90 across beta levels
    # ============================================================

    beta_ranks = StatsBase.tiedrank(beta_levels)
    q90_mean_ranks = StatsBase.tiedrank(mean_q90)

    rho_observed = Statistics.cor(
        beta_ranks,
        q90_mean_ranks
    )


    # ============================================================
    # 7. Efficient permutation test
    #
    # Shuffle simulations across beta groups.
    # Each permuted beta group still contains exactly n_each runs.
    #
    # For every permutation:
    #   - shuffle Q90 values
    #   - divide into n_beta groups of n_each simulations
    #   - calculate mean Q90 for each group
    #   - calculate Spearman(beta, mean Q90)
    # ============================================================

    rng = Random.MersenneTwister(seed)

    rho_permuted = Vector{Float64}(undef, n_permutations)

    permuted_q90 = copy(q90)
    permuted_means = Vector{Float64}(undef, n_beta)

    println(
        "\nRunning ",
        n_permutations,
        " permutations..."
    )

    for b in 1:n_permutations

        # Equivalent to permuting beta labels while preserving
        # exactly n_each simulations in every beta group
        copyto!(permuted_q90, q90)
        Random.shuffle!(rng, permuted_q90)

        @inbounds for bi in 1:n_beta

            first_idx = (bi - 1) * n_each + 1
            last_idx = bi * n_each

            s = 0.0

            for r in first_idx:last_idx
                s += permuted_q90[r]
            end

            permuted_means[bi] = s / n_each
        end

        permuted_ranks = StatsBase.tiedrank(permuted_means)

        rho_permuted[b] = Statistics.cor(
            beta_ranks,
            permuted_ranks
        )

        if b == 1 ||
           b % progress_every == 0 ||
           b == n_permutations

            println(
                "Permutation ",
                b,
                " / ",
                n_permutations
            )
            flush(stdout)
        end
    end


    # ============================================================
    # 8. Permutation p-value
    # ============================================================

    if alternative == :two_sided

        n_extreme = count(
            abs.(rho_permuted) .>= abs(rho_observed)
        )

    elseif alternative == :greater

        n_extreme = count(
            rho_permuted .>= rho_observed
        )

    else  # :less

        n_extreme = count(
            rho_permuted .<= rho_observed
        )
    end

    permutation_p =
        (n_extreme + 1) /
        (n_permutations + 1)


    # ============================================================
    # 9. Paper-style Q10 + Q90 figure
    # ============================================================

    p = Plots.plot(
        xlabel = "Homophily (β)",
        ylabel = "Pairwise Semantic Distance",
        fontfamily = fontfamily,
        size = plot_size,
        legend = :topleft,
        grid = false,
        framestyle = :box,
        tickfontsize = 11,
        guidefontsize = 13,
        legendfontsize = 10,
        margin = 5Plots.mm
    )

    # Q10
    Plots.plot!(
        p,
        summary.beta,
        summary.mean_Q10;
        yerror = summary.sd_Q10,
        linewidth = 2.5,
        marker = :circle,
        markersize = 5,
        markerstrokewidth = 0.8,
        label = "10th percentile"
    )

    # Q90
    Plots.plot!(
        p,
        summary.beta,
        summary.mean_Q90;
        yerror = summary.sd_Q90,
        linewidth = 2.5,
        marker = :circle,
        markersize = 5,
        markerstrokewidth = 0.8,
        label = "90th percentile"
    )

    Plots.display(p)


    # ============================================================
    # 10. Print results
    # ============================================================

    println("\n" * "="^70)
    println("SPEARMAN: β × MEAN Q90")
    println("="^70)

    println("\nObserved Spearman ρ = ", rho_observed)

    println(
        "Permutation p-value (",
        alternative,
        ") = ",
        permutation_p
    )

    println("\nBeta levels = ", n_beta)
    println("Simulations per beta = ", n_each)
    println("Total simulations = ", n)
    println("Permutations = ", n_permutations)


    # ============================================================
    # 11. Return
    # ============================================================

    return (
        run_results = df,
        summary = summary,

        rho_Q90 = rho_observed,
        permutation_p_Q90 = permutation_p,
        alternative = alternative,

        n_beta_levels = n_beta,
        n_per_beta = n_each,
        n_simulations = n,

        n_permutations = n_permutations,
        rho_permuted = rho_permuted,

        plot = p
    )
end
# res_Q10_Q90_spearman =
#     analyze_Q10_Q90_with_Q90_spearman_permutation(
#         raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_FINAL_SEMANTIC_DISTANCES.jld2";
#         n_permutations = 1,
