#Null model 1 - ללא הומופיליה

function null_test_max_homophily_difference(
    path::String;
    threshold::Float64 = 2.5,
    observed_p0::Float64 = 0.18,
    p_grid = collect(0.001:0.001:0.999),
    n_null::Int = 10_000,
    n_per_beta::Int = 150,
    progress_every_p::Int = 25)

    # ============================================================
    # 1. Load existing simulation data
    # ============================================================

    d = JLD2.load(path)

    Z_all = d["Z_all"]              # runs × T × N
    betas = Float64.(d["beta_value"])

    n_runs, T, N = size(Z_all)

    @assert length(betas) == n_runs


    # ============================================================
    # 2. Verify beta structure
    # ============================================================

    expected_positive_betas =
        collect(0.5:0.5:14.0)

    positive_betas =
        sort(
            unique(
                betas[betas .> 0.0]
            )
        )

    if positive_betas != expected_positive_betas
        error(
            "Expected positive beta values 0.5:0.5:14.0, but found:\n" *
            string(positive_betas)
        )
    end

    for b in positive_betas

        n_b =
            count(betas .== b)

        if n_b != n_per_beta
            error(
                "Expected $n_per_beta simulations for beta = $b, " *
                "but found $n_b."
            )
        end
    end


    # ============================================================
    # 3. Identify persistent semantic atypicality
    #
    # EXACT SAME definition as in the existing analysis:
    #
    # A run has emergence if at least one agent reaches
    # z >= threshold at some sampled timepoint and remains
    # >= threshold at every subsequent sampled timepoint.
    #
    # We calculate this only for beta > 0 because beta = 0
    # is fixed to the supplied observed value 0.18.
    # ============================================================

    positive_run_indices =
        findall(betas .> 0.0)

    run_emergence =
        falses(n_runs)

    println()
    println("="^90)
    println("IDENTIFYING PERSISTENT SEMANTIC ATYPICALITY")
    println("="^90)

    n_positive_runs =
        length(positive_run_indices)

    for (counter, r) in enumerate(positive_run_indices)

        found_in_run = false

        for agent in 1:N

            ztraj =
                @view Z_all[r, :, agent]

            for t in 1:T

                if ztraj[t] >= threshold &&
                   all(@view(ztraj[t:T]) .>= threshold)

                    found_in_run = true
                    break
                end
            end

            if found_in_run
                break
            end
        end

        run_emergence[r] =
            found_in_run

        if counter == 1 ||
           counter % 500 == 0 ||
           counter == n_positive_runs

            println(
                "  Positive-beta run ",
                counter,
                " / ",
                n_positive_runs
            )
        end
    end


    # ============================================================
    # 4. Observed emergence proportions for beta > 0
    # ============================================================

    observed_by_beta =
        DataFrames.DataFrame(
            beta = Float64[],
            n_emergence = Int[],
            n_total = Int[],
            proportion = Float64[]
        )

    for b in positive_betas

        idx =
            findall(betas .== b)

        n_total =
            length(idx)

        n_emergence =
            count(run_emergence[idx])

        proportion =
            n_emergence / n_total

        push!(
            observed_by_beta,
            (
                b,
                n_emergence,
                n_total,
                proportion
            )
        )
    end


    # ============================================================
    # 5. Observed test statistic
    #
    # T_obs =
    # max_{beta > 0}(p_hat_beta - p_hat_0)
    #
    # Since p_hat_0 is fixed at 0.18, this is equivalent to
    # finding the positive beta with the largest observed rate.
    # ============================================================

    max_idx =
        argmax(
            observed_by_beta.proportion
        )

    beta_max_observed =
        observed_by_beta.beta[max_idx]

    p_max_observed =
        observed_by_beta.proportion[max_idx]

    T_obs =
        p_max_observed - observed_p0


    println()
    println("="^90)
    println("OBSERVED TEST STATISTIC")
    println("="^90)

    println(
        "Observed proportion at beta = 0: ",
        observed_p0
    )

    println(
        "Highest observed positive-beta proportion: ",
        p_max_observed
    )

    println(
        "Beta with highest observed proportion: ",
        beta_max_observed
    )

    println(
        "T_obs = ",
        T_obs
    )


    # ============================================================
    # 6. Prepare null simulation
    #
    # Under each null value p:
    #
    # X_beta ~ Binomial(n_per_beta, p)
    #
    # independently for all 29 beta groups.
    #
    # This is exactly equivalent to generating n_per_beta
    # independent Bernoulli(p) observations in each group and
    # summing them, but is much faster.
    # ============================================================

    p_values =
        Float64.(collect(p_grid))

    if any((p_values .<= 0.0) .| (p_values .>= 1.0))
        error(
            "All p_grid values must be strictly between 0 and 1."
        )
    end

    n_positive_beta =
        length(positive_betas)

    n_groups =
        n_positive_beta + 1

    @assert n_groups == 29


    # ============================================================
    # 7. Storage
    # ============================================================

    null_summary =
        DataFrames.DataFrame(
            p_null = Float64[],
            n_simulations = Int[],
            n_extreme = Int[],
            empirical_p = Float64[],
            mean_T_null = Float64[],
            sd_T_null = Float64[],
            q025_T_null = Float64[],
            median_T_null = Float64[],
            q975_T_null = Float64[]
        )


    # Reuse this vector rather than allocating a new vector
    # for T_null at every p.
    T_null_values =
        Vector{Float64}(undef, n_null)


    # ============================================================
    # 8. Null simulations across p
    # ============================================================

    println()
    println("="^90)
    println("STARTING NULL SIMULATIONS")
    println("="^90)

    println(
        "Number of p values: ",
        length(p_values)
    )

    println(
        "Null simulations per p: ",
        n_null
    )

    println(
        "Total null iterations: ",
        length(p_values) * n_null
    )

    println(
        "Groups per iteration: ",
        n_groups,
        " (beta = 0 plus 28 positive beta levels)"
    )

    println()

    for (p_index, p_null) in enumerate(p_values)

        binom =
            Distributions.Binomial(
                n_per_beta,
                p_null
            )

        for iteration in 1:n_null

            # ----------------------------------------------------
            # beta = 0
            # ----------------------------------------------------

            count_0 =
                rand(binom)

            proportion_0 =
                count_0 / n_per_beta


            # ----------------------------------------------------
            # beta > 0
            #
            # We only need the largest simulated positive-beta
            # proportion, so there is no need to store all 28.
            # ----------------------------------------------------

            max_positive_count =
                0

            for _ in 1:n_positive_beta

                positive_count =
                    rand(binom)

                if positive_count > max_positive_count
                    max_positive_count =
                        positive_count
                end
            end

            max_positive_proportion =
                max_positive_count / n_per_beta


            # ----------------------------------------------------
            # Test statistic
            # ----------------------------------------------------

            T_null_values[iteration] =
                max_positive_proportion -
                proportion_0
        end


        # ========================================================
        # 9. Summary for this p
        # ========================================================

        n_extreme =
            count(
                T_null_values .>= T_obs
            )

        empirical_p =
            (n_extreme + 1) /
            (n_null + 1)

        mean_T =
            Statistics.mean(
                T_null_values
            )

        sd_T =
            Statistics.std(
                T_null_values
            )

        q025_T =
            Statistics.quantile(
                T_null_values,
                0.025
            )

        median_T =
            Statistics.median(
                T_null_values
            )

        q975_T =
            Statistics.quantile(
                T_null_values,
                0.975
            )

        push!(
            null_summary,
            (
                p_null,
                n_null,
                n_extreme,
                empirical_p,
                mean_T,
                sd_T,
                q025_T,
                median_T,
                q975_T
            )
        )


        # ========================================================
        # 10. Coarse progress
        # ========================================================

        if p_index == 1 ||
           p_index % progress_every_p == 0 ||
           p_index == length(p_values)

            println(
                "  p = ",
                round(p_null, digits = 3),
                " | ",
                p_index,
                " / ",
                length(p_values),
                " | empirical p = ",
                round(empirical_p, digits = 5)
            )
        end
    end


    # ============================================================
    # 11. Largest empirical p-value across the null grid
    # ============================================================

    max_pvalue_idx =
        argmax(
            null_summary.empirical_p
        )

    worst_case_p =
        null_summary.p_null[max_pvalue_idx]

    worst_case_empirical_p =
        null_summary.empirical_p[max_pvalue_idx]

        # ============================================================
        # Sanity check:
        # null distributions with the largest upper tail / mean
        # ============================================================

        max_q975_idx =
            argmax(
                null_summary.q975_T_null
            )

        p_max_q975 =
            null_summary.p_null[max_q975_idx]

        max_q975_T_null =
            null_summary.q975_T_null[max_q975_idx]


        max_mean_idx =
            argmax(
                null_summary.mean_T_null
            )

        p_max_mean =
            null_summary.p_null[max_mean_idx]

        max_mean_T_null =
            null_summary.mean_T_null[max_mean_idx]


        T_obs_minus_max_q975 =
            T_obs - max_q975_T_null


    # ============================================================
    # 12. Find contiguous p ranges with empirical p < .05
    # ============================================================

    significant =
        null_summary.empirical_p .< 0.05

    significant_ranges =
        DataFrames.DataFrame(
            p_start = Float64[],
            p_end = Float64[]
        )

    range_start =
        nothing

    for i in eachindex(significant)

        if significant[i] && range_start === nothing

            range_start =
                null_summary.p_null[i]

        end

        is_last =
            i == length(significant)

        if range_start !== nothing &&
           (
               !significant[i] ||
               is_last
           )

            if significant[i] && is_last

                range_end =
                    null_summary.p_null[i]

            else

                range_end =
                    null_summary.p_null[i - 1]
            end

            push!(
                significant_ranges,
                (
                    Float64(range_start),
                    Float64(range_end)
                )
            )

            range_start =
                nothing
        end
    end


    # ============================================================
    # 13. Plot
    # ============================================================

    p_plot =
        Plots.plot(
            null_summary.p_null,
            null_summary.empirical_p;

            linewidth = 2.5,
            label = false,

            xlabel = "Null Emergence Probability (p)",
            ylabel = "Empirical p-value",

            xlims = (0.0, 1.0),
            ylims = (0.0, 1.0),

            xticks = 0.0:0.1:1.0,
            yticks = 0.0:0.1:1.0,

            grid = false,
            framestyle = :box,

            fontfamily = "Calibri",

            guidefontsize = 13,
            tickfontsize = 11,

            left_margin = 8Plots.mm,
            right_margin = 4Plots.mm,
            bottom_margin = 7Plots.mm,
            top_margin = 4Plots.mm,

            size = (900, 560)
        )

    Plots.hline!(
        p_plot,
        [0.05];
        linestyle = :dash,
        linewidth = 1.5,
        label = false
    )

    Plots.vline!(
        p_plot,
        [observed_p0];
        linestyle = :dash,
        linewidth = 1.5,
        label = false
    )


    # ============================================================
    # 14. Print results
    # ============================================================

    println()
    println("="^90)
    println("NULL SIMULATION RESULTS")
    println("="^90)

    println(
        "Observed beta=0 proportion: ",
        observed_p0
    )

    println(
        "Observed maximum positive-beta proportion: ",
        p_max_observed,
        " at beta = ",
        beta_max_observed
    )

    println(
        "T_obs = ",
        T_obs
    )

    println()

    println(
        "Largest empirical p-value = ",
        worst_case_empirical_p
    )

    println()
    println("="^90)
    println("SANITY CHECK — MOST EXTREME NULL DISTRIBUTIONS")
    println("="^90)

    println(
        "T_obs = ",
        T_obs
    )

    println(
        "Maximum 97.5th percentile of T_null = ",
        max_q975_T_null,
        " at null p = ",
        p_max_q975
    )

    println(
        "Maximum mean T_null = ",
        max_mean_T_null,
        " at null p = ",
        p_max_mean
    )

    println(
        "T_obs - maximum q97.5(T_null) = ",
        T_obs_minus_max_q975
    )

    println(
        "Obtained at null p = ",
        worst_case_p
    )


    println()
    println(
        "Ranges of null p with empirical p-value < .05:"
    )

    if DataFrames.nrow(significant_ranges) == 0

        println("  None")

    else

        for row in eachrow(significant_ranges)

            if row.p_start == row.p_end

                println(
                    "  p = ",
                    row.p_start
                )

            else

                println(
                    "  p = ",
                    row.p_start,
                    " – ",
                    row.p_end
                )
            end
        end
    end


    println()
    println("="^90)
    println("NULL SUMMARY")
    println("="^90)

    show(
        stdout,
        null_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()

    display(p_plot)


    # ============================================================
    # 15. Return
    # ============================================================

    return (
        observed_by_beta =
            observed_by_beta,

        observed_p0 =
            observed_p0,

        beta_max_observed =
            beta_max_observed,

        p_max_observed =
            p_max_observed,

        T_obs =
            T_obs,

        null_summary =
            null_summary,

        significant_ranges =
            significant_ranges,

        worst_case_p =
            worst_case_p,

        worst_case_empirical_p =
            worst_case_empirical_p,

        p_max_q975 =
            p_max_q975,

        max_q975_T_null =
            max_q975_T_null,

        p_max_mean =
            p_max_mean,

        max_mean_T_null =
            max_mean_T_null,

        T_obs_minus_max_q975 =
            T_obs_minus_max_q975,

        plot =
            p_plot
    )
end
