# Null model 2 - פיזור במרחב
function relocate_agent_randomly!(world::World, i::Int)
    W, H = world.W, world.H

    # Free the agent's current position
    world.occ[world.y[i], world.x[i]] = 0

    # Randomly place the agent in an unoccupied cell,
    # using the same placement mechanism as
    # reset_positions_and_interactions!
    while true
        x = rand(1:W)
        y = rand(1:H)

        if world.occ[y, x] == 0
            world.x[i] = x
            world.y[i] = y
            world.occ[y, x] = i
            break
        end
    end

    return nothing
end
function step_random_relocation!(world::World;
    talk_duration::Int=5,
    refractory_duration::Int=10,
    self_talk_threshold::Int=10,
    L::Int=10,
    eta::Float32=0.5f0,
    beta_for_consent::Real=10.0,
    gamma::Union{Nothing,Real}=nothing,
    beta::Union{Nothing,Real}=nothing,
    delta::Union{Nothing,Real}=nothing,
    p0::Union{Nothing,Real}=nothing,
    pmin::Real=0.05,
    record_distances::Bool=true,
    record_every::Int=1,
    social_impact::Float64=1.0,
    join_rule::Symbol=:group_any,
    social_learning_prob=ones(Float32, world.N))

    # --- Update parameters if provided ---
    if gamma !== nothing world.γ = Float32(gamma) end
    if beta !== nothing world.β = Float32(beta) end
    if delta !== nothing world.δ = Float32(delta) end
    if p0 !== nothing world.p0 = Float32(p0) end
    if beta_for_consent !== nothing world.beta_for_consent = Float32(beta_for_consent) end

    world.t += 1

    # 1) Group Conversation Phase
    group_ids = unique(world.talking_group)
    talked_groups = Vector{Vector{Int}}()

    for gid in group_ids
        gid == 0 && continue

        # Identify current group members
        members = [i for i in 1:world.N if world.talking_group[i] == gid]
        Lm = length(members)

        # Handle fragmented groups (less than 2 agents)
        if Lm < 2
            if Lm == 1
                if world.talk_left[members[1]] > 0
                    mark_abandonment!(world, members[1])
                end

                end_conversation_for_agent!(
                    world,
                    members[1],
                    refractory_duration
                )

                # NEW: relocate only the agent whose conversation ended
                relocate_agent_randomly!(world, members[1])
            end
            continue
        end

        # Check for silence (no speakers)
        all_silent = true
        nspeakers = 0

        @inbounds for m in members
            if !world.silent[m]
                nspeakers += 1
                if nspeakers >= 2
                    all_silent = false
                    break
                end
            end
        end

        if all_silent
            # If no one talks, they experience abandonment and group dissolves
            @inbounds for m in members
                for other in members
                    if m != other
                        push!(world.agent_seen_partners[m], other)
                    end
                end

                if world.talk_left[m] > 0
                    mark_abandonment!(world, m)
                end

                end_conversation_for_agent!(
                    world,
                    m,
                    refractory_duration
                )

                # NEW: relocate this agent after leaving the conversation
                relocate_agent_randomly!(world, m)
            end
            continue
        end

        push!(talked_groups, members)

        speakers = Int[]

        @inbounds for m in members
            if !world.silent[m]
                push!(speakers, m)
            end
        end

        log_conversation!(
            world;
            gid=gid,
            members=copy(members),
            speakers=copy(speakers)
        )

        conversation!(
            members,
            world,
            L;
            social_impact=social_impact,
            social_learning_prob=social_learning_prob
        )

        for i in members
            world.talk_left[i] -= 1
        end
    end

    # End Conversation & Refractory Check
    for i in 1:world.N
        if world.talking_group[i] != 0 && world.talk_left[i] <= 0

            end_conversation_for_agent!(
                world,
                i,
                refractory_duration
            )

            # NEW: relocate only this agent
            relocate_agent_randomly!(world, i)
        end
    end

    # 2) Self-conversation phase
    for i in 1:world.N
        if world.talking_group[i] == 0
            if world.self_talk_left[i] > 0
                self_conversation!(i, world, L)
                world.self_talk_count[i] += 1
                world.self_talk_left[i] -= 1
            else
                world.time_since_last_talk[i] += 1

                if world.time_since_last_talk[i] >= self_talk_threshold
                    world.self_talk_left[i] = 3
                    self_conversation!(i, world, L)
                    world.self_talk_count[i] += 1
                    world.self_talk_left[i] -= 1
                    world.time_since_last_talk[i] = 0
                end
            end
        else
            world.time_since_last_talk[i] = 0
        end
    end

    # --- 3) Semantic Updates (Perception) ---
    if eta != 0.0f0
        for group in talked_groups
            update_perceived_group!(world, group; eta=eta)
        end
    end

    if record_distances && (world.t % record_every == 0)
        world.current_distances .= Float32.(differences(world.agents))
        push!(
            world.distances_history,
            copy(world.current_distances)
        )
        push!(
            world.perceived_distance_history,
            copy(world.perceived_distance)
        )
    end

    # 4) Movement and Adjacency Logging
    move_agents!(world)
    update_adjacency!(world.adjacency_count, world)

    # 5) Social Interaction Initiation
    form_conversations!(
        world;
        talk_duration=talk_duration,
        pmin=pmin,
        p0=p0,
        join_rule=join_rule
    )

    update_talk_episodes!(world)

    # 6) Refractory Period Update
    for i in 1:world.N
        if !isempty(world.refr_partners[i])
            tick_refractory!(
                world.refr_partners,
                world.refr_left,
                i
            )
        end
    end

    # 7) Longitudinal Logging
    push!(world.unique_partners_steps, world.t)

    current_unique_counts = [
        count(>(0), view(world.talk_episode_count, i, :))
        for i in 1:world.N
    ]

    push!(
        world.unique_partners_history,
        current_unique_counts
    )

    return nothing
end

function run_original_vs_random_relocation_raw(
    n_sim::Int;
    save_path::String = joinpath(
        "sweep_beta_logs",
        "ORIGINAL_VS_RANDOM_RELOCATION_RAW.jld2"
    ),
    threshold::Real = 2.5,
    progress_every::Int = 10)

    # ============================================================
    # SETTINGS
    # ============================================================

    N = 20
    n = 300
    m = 4

    W = 30
    H = 30

    change = 0.7

    steps = 20_000
    record_every = 100
    reset_every = 100

    talk_duration = 10
    refractory_duration = 10
    self_talk_threshold = 10

    L = 25
    eta = 0.2f0

    gamma = 0.0
    beta = 1.0
    delta = 1.0
    p0 = 0.5
    pmin = 0.05

    # β = 0 in the semantic-homophily / consent mechanism.
    beta_for_consent = 0.0

    social_impact = 1.0
    join_rule = :group_any

    abandonment_threshold = 10_000_000
    outliers_count = 0
    outlier_change = nothing

    social_learning_prob =
        ones(Float32, N)

    model_names =
        ["original", "random_relocation"]

    n_models = length(model_names)

    steps_axis =
        collect(0:record_every:steps)

    n_timepoints =
        length(steps_axis)

    # ============================================================
    # PAIR MAP
    # ============================================================

    pair_map =
        Tuple{Int,Int}[]

    for i in 1:(N - 1)
        for j in (i + 1):N
            push!(pair_map, (i, j))
        end
    end

    n_pairs =
        length(pair_map)

    @assert n_pairs == 190

    # ============================================================
    # PREALLOCATE RAW RESULTS
    #
    # Dimensions:
    # model × simulation × timepoint × agent/pair
    # ============================================================

    Z_all =
        fill(
            Float32(NaN),
            n_models,
            n_sim,
            n_timepoints,
            N
        )

    pair_episode_counts =
        zeros(
            Int32,
            n_models,
            n_sim,
            n_timepoints,
            n_pairs
        )

    # Persistent-crossing results.
    crossed =
        falses(
            n_models,
            n_sim,
            N
        )

    # -1 means that the agent never had a persistent crossing.
    crossing_step =
        fill(
            -1,
            n_models,
            n_sim,
            N
        )

    n_crossing_agents =
        zeros(
            Int,
            n_models,
            n_sim
        )

    any_crossing =
        falses(
            n_models,
            n_sim
        )

    # ============================================================
    # HELPERS
    # ============================================================

    function record_state!(
        world::World,
        model_idx::Int,
        sim_idx::Int,
        time_idx::Int
    )

        # --------------------------------------------------------
        # Semantic Z
        # Same calculation used in the previous control analysis.
        # --------------------------------------------------------

        z_result =
            mean_network_distance_zscores(
                world.agents
            )

        Z_all[
            model_idx,
            sim_idx,
            time_idx,
            :
        ] .=
            Float32.(z_result.z)

        # --------------------------------------------------------
        # Cumulative DISTINCT pairwise conversation episodes
        # --------------------------------------------------------

        @inbounds for p in 1:n_pairs

            i, j =
                pair_map[p]

            pair_episode_counts[
                model_idx,
                sim_idx,
                time_idx,
                p
            ] =
                Int32(
                    world.talk_episode_count[i, j]
                )
        end

        return nothing
    end


    function find_persistent_crossings!(
        model_idx::Int,
        sim_idx::Int
    )

        n_crossed = 0

        @inbounds for agent in 1:N

            ztraj =
                @view Z_all[
                    model_idx,
                    sim_idx,
                    :,
                    agent
                ]

            first_crossing_idx = 0

            for t_idx in 1:n_timepoints

                if ztraj[t_idx] >= threshold

                    remains_above = true

                    for future_idx in t_idx:n_timepoints

                        if ztraj[future_idx] < threshold
                            remains_above = false
                            break
                        end
                    end

                    if remains_above
                        first_crossing_idx = t_idx
                        break
                    end
                end
            end

            if first_crossing_idx > 0

                crossed[
                    model_idx,
                    sim_idx,
                    agent
                ] = true

                crossing_step[
                    model_idx,
                    sim_idx,
                    agent
                ] =
                    steps_axis[first_crossing_idx]

                n_crossed += 1
            end
        end

        n_crossing_agents[
            model_idx,
            sim_idx
        ] =
            n_crossed

        any_crossing[
            model_idx,
            sim_idx
        ] =
            n_crossed > 0

        return nothing
    end


    function run_model!(
        world::World,
        model_idx::Int,
        sim_idx::Int;
        use_random_relocation::Bool
    )

        # --------------------------------------------------------
        # t = 0
        # --------------------------------------------------------

        record_state!(
            world,
            model_idx,
            sim_idx,
            1
        )

        time_idx = 1

        # --------------------------------------------------------
        # Simulation
        #
        # IMPORTANT:
        # preserve the original ordering:
        # reset BEFORE step! at every multiple of 100.
        # --------------------------------------------------------

        for step_i in 1:steps

            if step_i % reset_every == 0

                reset_positions_and_interactions!(
                    world
                )
            end

            if use_random_relocation

                step_random_relocation!(
                    world;
                    talk_duration =
                        talk_duration,

                    refractory_duration =
                        refractory_duration,

                    self_talk_threshold =
                        self_talk_threshold,

                    L =
                        L,

                    eta =
                        eta,

                    beta_for_consent =
                        beta_for_consent,

                    gamma =
                        gamma,

                    beta =
                        beta,

                    delta =
                        delta,

                    p0 =
                        p0,

                    pmin =
                        pmin,

                    record_distances =
                        true,

                    record_every =
                        record_every,

                    social_impact =
                        social_impact,

                    join_rule =
                        join_rule,

                    social_learning_prob =
                        social_learning_prob
                )

            else

                step!(
                    world;
                    talk_duration =
                        talk_duration,

                    refractory_duration =
                        refractory_duration,

                    self_talk_threshold =
                        self_talk_threshold,

                    L =
                        L,

                    eta =
                        eta,

                    beta_for_consent =
                        beta_for_consent,

                    gamma =
                        gamma,

                    beta =
                        beta,

                    delta =
                        delta,

                    p0 =
                        p0,

                    pmin =
                        pmin,

                    record_distances =
                        true,

                    record_every =
                        record_every,

                    social_impact =
                        social_impact,

                    join_rule =
                        join_rule,

                    social_learning_prob =
                        social_learning_prob
                )
            end

            # ----------------------------------------------------
            # Save every 100 steps
            # ----------------------------------------------------

            if step_i % record_every == 0

                time_idx += 1

                record_state!(
                    world,
                    model_idx,
                    sim_idx,
                    time_idx
                )
            end
        end

        @assert time_idx == n_timepoints

        # --------------------------------------------------------
        # Persistent semantic crossing
        # --------------------------------------------------------

        find_persistent_crossings!(
            model_idx,
            sim_idx
        )

        return nothing
    end

    # ============================================================
    # MAIN LOOP
    # ============================================================

    println()
    println("="^78)
    println("ORIGINAL VS RANDOM-RELOCATION CONTROL")
    println("="^78)
    println("Simulation pairs:          ", n_sim)
    println("Runs total:                ", 2 * n_sim)
    println("Steps per run:             ", steps)
    println("Semantic threshold:        ", threshold)
    println("Sampling interval:         ", record_every)
    println("Semantic homophily β:      ", beta_for_consent)
    println("Matched initial world:     YES")
    println("Matched random sequence:   NO")
    println("Random seed fixed:         NO")
    println("="^78)
    println()

    for sim_idx in 1:n_sim

        # --------------------------------------------------------
        # ONE fresh initial world for this simulation pair
        # --------------------------------------------------------

        initial_world =
            init_world(
                N,
                W,
                H,
                n,
                m,
                change;
                abandonment_threshold =
                    abandonment_threshold,

                outliers_count =
                    outliers_count,

                outlier_change =
                    outlier_change
            )

        # --------------------------------------------------------
        # Identical starting point for the two models
        # --------------------------------------------------------

        original_world =
            deepcopy(initial_world)

        relocation_world =
            deepcopy(initial_world)

        # initial_world is no longer needed.
        initial_world = nothing

        # --------------------------------------------------------
        # ORIGINAL
        #
        # No Random.seed! here.
        # --------------------------------------------------------

        run_model!(
            original_world,
            1,
            sim_idx;
            use_random_relocation = false
        )

        original_world = nothing

        # --------------------------------------------------------
        # RANDOM RELOCATION
        #
        # Again: no Random.seed!.
        # It starts from the same initial world, but not from the
        # same RNG state as the original run.
        # --------------------------------------------------------

        run_model!(
            relocation_world,
            2,
            sim_idx;
            use_random_relocation = true
        )

        relocation_world = nothing

        # --------------------------------------------------------
        # Progress
        # --------------------------------------------------------

        if sim_idx % progress_every == 0 ||
           sim_idx == n_sim

            original_n =
                count(
                    @view any_crossing[
                        1,
                        1:sim_idx
                    ]
                )

            relocation_n =
                count(
                    @view any_crossing[
                        2,
                        1:sim_idx
                    ]
                )

            println(
                "  ",
                sim_idx,
                "/",
                n_sim,
                " pairs | crossing runs: original=",
                original_n,
                ", relocation=",
                relocation_n
            )

            GC.gc()
        end
    end

    # ============================================================
    # RUN-LEVEL SUMMARY TABLE
    # ============================================================

    run_model_name =
        String[]

    run_simulation =
        Int[]

    run_any_crossing =
        Bool[]

    run_n_crossing_agents =
        Int[]

    for model_idx in 1:n_models
        for sim_idx in 1:n_sim

            push!(
                run_model_name,
                model_names[model_idx]
            )

            push!(
                run_simulation,
                sim_idx
            )

            push!(
                run_any_crossing,
                any_crossing[
                    model_idx,
                    sim_idx
                ]
            )

            push!(
                run_n_crossing_agents,
                n_crossing_agents[
                    model_idx,
                    sim_idx
                ]
            )
        end
    end

    run_summary =
        DataFrames.DataFrame(
            model =
                run_model_name,

            simulation =
                run_simulation,

            any_crossing =
                run_any_crossing,

            n_crossing_agents =
                run_n_crossing_agents
        )

    # ============================================================
    # AGENT-LEVEL CROSSING TABLE
    # ============================================================

    crossing_model =
        String[]

    crossing_simulation =
        Int[]

    crossing_agent =
        Int[]

    crossing_crossed =
        Bool[]

    crossing_crossing_step =
        Union{Missing,Int}[]

    for model_idx in 1:n_models
        for sim_idx in 1:n_sim
            for agent in 1:N

                did_cross =
                    crossed[
                        model_idx,
                        sim_idx,
                        agent
                    ]

                push!(
                    crossing_model,
                    model_names[model_idx]
                )

                push!(
                    crossing_simulation,
                    sim_idx
                )

                push!(
                    crossing_agent,
                    agent
                )

                push!(
                    crossing_crossed,
                    did_cross
                )

                if did_cross

                    push!(
                        crossing_crossing_step,
                        crossing_step[
                            model_idx,
                            sim_idx,
                            agent
                        ]
                    )

                else

                    push!(
                        crossing_crossing_step,
                        missing
                    )
                end
            end
        end
    end

    crossing_results =
        DataFrames.DataFrame(
            model =
                crossing_model,

            simulation =
                crossing_simulation,

            agent =
                crossing_agent,

            crossed =
                crossing_crossed,

            crossing_step =
                crossing_crossing_step
        )

    # ============================================================
    # OVERALL SUMMARY
    # ============================================================

    overall_summary =
        DataFrames.combine(
            DataFrames.groupby(
                run_summary,
                :model
            ),

            DataFrames.nrow =>
                :n_runs,

            :any_crossing =>
                sum =>
                :n_runs_with_crossing,

            :any_crossing =>
                (
                    x ->
                        100.0 * Statistics.mean(x)
                ) =>
                :percentage_runs_with_crossing,

            :n_crossing_agents =>
                Statistics.mean =>
                :mean_n_crossing_agents
        )

    # ============================================================
    # SAVE EVERYTHING
    # ============================================================

    println()
    println("Saving results...")

    JLD2.jldsave(
        save_path;

        # ------------------------
        # Raw trajectories
        # ------------------------

        Z_all =
            Z_all,

        pair_episode_counts =
            pair_episode_counts,

        # ------------------------
        # Crossing arrays
        # ------------------------

        crossed =
            crossed,

        crossing_step =
            crossing_step,

        n_crossing_agents =
            n_crossing_agents,

        any_crossing =
            any_crossing,

        # ------------------------
        # Convenient tables
        # ------------------------

        run_summary =
            run_summary,

        crossing_results =
            crossing_results,

        overall_summary =
            overall_summary,

        # ------------------------
        # Axes / metadata
        # ------------------------

        model_names =
            model_names,

        steps_axis =
            steps_axis,

        pair_map =
            pair_map,

        threshold =
            Float64(threshold),

        N =
            N,

        n_words =
            n,

        n_sim =
            n_sim,

        steps =
            steps,

        record_every =
            record_every,

        reset_every =
            reset_every,

        beta_for_consent =
            beta_for_consent,

        movement_beta =
            beta,

        talk_duration =
            talk_duration,

        refractory_duration =
            refractory_duration,

        self_talk_threshold =
            self_talk_threshold,

        L =
            L,

        eta =
            eta,

        gamma =
            gamma,

        delta =
            delta,

        p0 =
            p0,

        pmin =
            pmin,

        social_impact =
            social_impact,

        join_rule =
            String(join_rule),

        matched_initial_world =
            true,

        matched_random_sequence =
            false,

        fixed_random_seed =
            false
    )

    # ============================================================
    # PRINT FINAL RESULTS
    # ============================================================

    println()
    println("="^90)
    println("SIMULATION COMPLETE")
    println("="^90)

    show(
        stdout,
        overall_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()
    println()
    println("Saved to: ", save_path)

    # ============================================================
    # RETURN
    # ============================================================

    return (
        overall_summary =
            overall_summary,

        run_summary =
            run_summary,

        crossing_results =
            crossing_results,

        Z_all =
            Z_all,

        pair_episode_counts =
            pair_episode_counts,

        crossed =
            crossed,

        crossing_step =
            crossing_step,

        n_crossing_agents =
            n_crossing_agents,

        any_crossing =
            any_crossing,

        steps_axis =
            steps_axis,

        pair_map =
            pair_map,

        model_names =
            model_names,

        save_path =
            save_path
    )
end
# control_results =
#     run_original_vs_random_relocation_raw(
#         1000;
#         save_path = joinpath(
#             "sweep_beta_logs",
#             "ORIGINAL_VS_RANDOM_RELOCATION_RAW_1000.jld2"
#         ),
#         threshold = 2.5,
#         progress_every = 10
# )
function analyze_original_vs_relocation_control(
    path::String;
    threshold::Real = 2.5,
    n_sampled_windows::Int = 10,
    progress_every::Int = 100,
    save_path::Union{Nothing,String} = nothing)

    # ============================================================
    # 1. LOAD
    # ============================================================

    println("\nLoading control simulation file...")

    d = JLD2.load(path)

    Z_all =
        d["Z_all"]

    pair_episode_counts =
        d["pair_episode_counts"]

    steps_axis =
        Int.(d["steps_axis"])

    pair_map =
        Tuple{Int,Int}.(d["pair_map"])

    model_names =
        String.(d["model_names"])

    n_models =
        size(Z_all, 1)

    n_sim =
        size(Z_all, 2)

    n_timepoints =
        size(Z_all, 3)

    N =
        size(Z_all, 4)

    n_pairs =
        length(pair_map)

    @assert n_models == 2
    @assert n_pairs == 190
    @assert size(pair_episode_counts, 1) == n_models
    @assert size(pair_episode_counts, 2) == n_sim
    @assert size(pair_episode_counts, 3) == n_timepoints
    @assert size(pair_episode_counts, 4) == n_pairs
    @assert length(steps_axis) == n_timepoints

    println("Loaded successfully.")
    println("Models:       ", model_names)
    println("Simulations:  ", n_sim, " per model")
    println("Timepoints:   ", n_timepoints)
    println("Agents:       ", N)
    println("Pairs:        ", n_pairs)

    # ============================================================
    # 2. SEMANTIC OUTLIERS
    #
    # Earliest persistent crossing:
    # first sampled timepoint t such that
    # Z(t) >= threshold and remains >= threshold thereafter.
    # ============================================================

    println()
    println("="^80)
    println("SEMANTIC OUTLIER ANALYSIS")
    println("="^80)

    crossed =
        falses(
            n_models,
            n_sim,
            N
        )

    crossing_step =
        fill(
            -1,
            n_models,
            n_sim,
            N
        )

    any_crossing =
        falses(
            n_models,
            n_sim
        )

    n_crossing_agents =
        zeros(
            Int,
            n_models,
            n_sim
        )

    for model_idx in 1:n_models

        for sim_idx in 1:n_sim

            n_crossed =
                0

            for agent in 1:N

                ztraj =
                    @view Z_all[
                        model_idx,
                        sim_idx,
                        :,
                        agent
                    ]

                first_crossing_idx =
                    0

                for t_idx in 1:n_timepoints

                    if ztraj[t_idx] >= threshold

                        remains_above =
                            true

                        for future_idx in t_idx:n_timepoints

                            if ztraj[future_idx] < threshold

                                remains_above =
                                    false

                                break
                            end
                        end

                        if remains_above

                            first_crossing_idx =
                                t_idx

                            break
                        end
                    end
                end

                if first_crossing_idx > 0

                    crossed[
                        model_idx,
                        sim_idx,
                        agent
                    ] =
                        true

                    crossing_step[
                        model_idx,
                        sim_idx,
                        agent
                    ] =
                        steps_axis[
                            first_crossing_idx
                        ]

                    n_crossed += 1
                end
            end

            n_crossing_agents[
                model_idx,
                sim_idx
            ] =
                n_crossed

            any_crossing[
                model_idx,
                sim_idx
            ] =
                n_crossed > 0
        end
    end

    # ============================================================
    # 3. OUTLIER SUMMARY BY MODEL
    # ============================================================

    outlier_summary =
        DataFrames.DataFrame(
            model =
                model_names,

            n_runs =
                fill(n_sim, n_models),

            n_runs_with_outlier =
                [
                    count(
                        @view any_crossing[
                            model_idx,
                            :
                        ]
                    )
                    for model_idx in 1:n_models
                ]
        )

    outlier_summary[
        !,
        :percentage_runs_with_outlier
    ] =
        100.0 .*
        outlier_summary.n_runs_with_outlier ./
        outlier_summary.n_runs

    # ============================================================
    # 4. PAIRED OUTLIER COMPARISON
    #
    # Each original/relocation pair began from the same initial
    # world, so retain that pairing here.
    # ============================================================

    original_crossing =
        @view any_crossing[1, :]

    relocation_crossing =
        @view any_crossing[2, :]

    n_neither =
        count(
            (!original_crossing[i] &&
             !relocation_crossing[i])
            for i in 1:n_sim
        )

    n_both =
        count(
            (original_crossing[i] &&
             relocation_crossing[i])
            for i in 1:n_sim
        )

    n_original_only =
        count(
            (original_crossing[i] &&
             !relocation_crossing[i])
            for i in 1:n_sim
        )

    n_relocation_only =
        count(
            (!original_crossing[i] &&
             relocation_crossing[i])
            for i in 1:n_sim
        )

    original_percentage =
        100.0 *
        Statistics.mean(original_crossing)

    relocation_percentage =
        100.0 *
        Statistics.mean(relocation_crossing)

    percentage_point_difference =
        original_percentage -
        relocation_percentage
    # ============================================================
    # One-sided two-proportion Z-test (unpaired)
    #
    # H0: p_original <= p_relocation
    # H1: p_original > p_relocation
    # ============================================================

    n_original =
        count(original_crossing)

    n_relocation =
        count(relocation_crossing)

    # Pooled proportion under H0
    p_pooled =
        (n_original + n_relocation) /
        (2 * n_sim)

    # Standard error under H0
    se_pooled =
        sqrt(
            p_pooled *
            (1.0 - p_pooled) *
            (2.0 / n_sim)
        )

    # Z statistic and one-sided p-value
    if se_pooled > 0.0

        z_proportions =
            (
                original_percentage -
                relocation_percentage
            ) / (100.0 * se_pooled)

        p_proportions =
            Distributions.ccdf(
                Distributions.Normal(),
                z_proportions
            )

    else

        z_proportions = 0.0
        p_proportions = 1.0

    end
    # ============================================================
    # 95% CI for difference in persistent-outlier proportions
    #
    # Difference is defined consistently with the existing code:
    # Original - Random relocation
    # ============================================================

    p_original =
        Statistics.mean(original_crossing)

    p_relocation =
        Statistics.mean(relocation_crossing)

    proportion_difference =
        p_original -
        p_relocation

    se_proportion_difference =
        sqrt(
            p_original *
            (1.0 - p_original) /
            n_sim +
            p_relocation *
            (1.0 - p_relocation) /
            n_sim
        )

    ci95_low_proportion_difference =
        proportion_difference -
        1.96 * se_proportion_difference

    ci95_high_proportion_difference =
        proportion_difference +
        1.96 * se_proportion_difference

    paired_outlier_summary =
        DataFrames.DataFrame(
            outcome = [
                "Neither",
                "Both",
                "Original only",
                "Random relocation only"
            ],

            n_pairs = [
                n_neither,
                n_both,
                n_original_only,
                n_relocation_only
            ],

            percentage = [
                100.0 * n_neither / n_sim,
                100.0 * n_both / n_sim,
                100.0 * n_original_only / n_sim,
                100.0 * n_relocation_only / n_sim
            ]
        )

    # ============================================================
    # 5. SOCIAL REPETITION
    #
    # For each 100-step window:
    #
    # c[p] = cumulative episodes(end) -
    #        cumulative episodes(start)
    #
    # M = total distinct pairwise conversation episodes
    # U = number of different pairs used
    #
    # R = 1 - U/M
    #
    # NULL:
    # M pairwise episodes are independently allocated among
    # P=190 possible pairs with equal probability.
    # ============================================================

    println()
    println("="^80)
    println("SOCIAL REPETITION ANALYSIS")
    println("="^80)

    P =
        n_pairs

    n_windows =
        n_timepoints - 1

    social_model =
        String[]

    social_simulation =
        Int[]

    social_window =
        Int[]

    social_start_step =
        Int[]

    social_end_step =
        Int[]

    social_M =
        Int[]

    social_U =
        Int[]

    social_observed_R =
        Union{Missing,Float64}[]

    social_expected_R =
        Union{Missing,Float64}[]

    social_excess_R =
        Union{Missing,Float64}[]

    social_sd_null_R =
        Union{Missing,Float64}[]

    social_z_R =
        Union{Missing,Float64}[]

    total_windows =
        n_models * n_sim * n_windows

    processed_windows =
        0

    for model_idx in 1:n_models

        for sim_idx in 1:n_sim

            for window_idx in 1:n_windows

                # ------------------------------------------------
                # Number of DISTINCT pairwise conversation
                # episodes during this window.
                # ------------------------------------------------

                M =
                    0

                U =
                    0

                @inbounds for p in 1:P

                    c =
                        Int(
                            pair_episode_counts[
                                model_idx,
                                sim_idx,
                                window_idx + 1,
                                p
                            ]
                        ) -
                        Int(
                            pair_episode_counts[
                                model_idx,
                                sim_idx,
                                window_idx,
                                p
                            ]
                        )

                    if c < 0
                        error(
                            "Negative episode-count difference: " *
                            "model=$(model_names[model_idx]), " *
                            "simulation=$sim_idx, " *
                            "window=$window_idx, pair=$p."
                        )
                    end

                    M += c

                    if c > 0
                        U += 1
                    end
                end

                observed_R =
                    missing

                expected_R =
                    missing

                excess_R =
                    missing

                sd_null_R =
                    missing

                z_R =
                    missing

                if M > 0

                    # --------------------------------------------
                    # Observed repetition
                    # --------------------------------------------

                    R_obs =
                        1.0 -
                        U / M

                    observed_R =
                        R_obs

                    # --------------------------------------------
                    # Analytic random-pair null
                    # --------------------------------------------

                    q1 =
                        ((P - 1) / P)^M

                    expected_U =
                        P * (1.0 - q1)

                    R_null =
                        1.0 -
                        expected_U / M

                    expected_R =
                        R_null

                    excess_R =
                        R_obs - R_null

                    # --------------------------------------------
                    # Variance of number of occupied pairs U
                    # --------------------------------------------

                    p_occ =
                        1.0 - q1

                    q2 =
                        ((P - 2) / P)^M

                    p2 =
                        1.0 -
                        2.0 * q1 +
                        q2

                    var_U =
                        P *
                        p_occ *
                        (1.0 - p_occ) +
                        P *
                        (P - 1) *
                        (
                            p2 -
                            p_occ^2
                        )

                    # Numerical protection.
                    var_U =
                        max(
                            var_U,
                            0.0
                        )

                    var_R =
                        var_U /
                        M^2

                    sd_R =
                        sqrt(var_R)

                    sd_null_R =
                        sd_R

                    if sd_R > 0.0

                        z_R =
                            (
                                R_obs -
                                R_null
                            ) /
                            sd_R
                    end
                end

                push!(
                    social_model,
                    model_names[model_idx]
                )

                push!(
                    social_simulation,
                    sim_idx
                )

                push!(
                    social_window,
                    window_idx
                )

                push!(
                    social_start_step,
                    steps_axis[window_idx]
                )

                push!(
                    social_end_step,
                    steps_axis[window_idx + 1]
                )

                push!(
                    social_M,
                    M
                )

                push!(
                    social_U,
                    U
                )

                push!(
                    social_observed_R,
                    observed_R
                )

                push!(
                    social_expected_R,
                    expected_R
                )

                push!(
                    social_excess_R,
                    excess_R
                )

                push!(
                    social_sd_null_R,
                    sd_null_R
                )

                push!(
                    social_z_R,
                    z_R
                )

                processed_windows += 1

                if processed_windows % progress_every == 0 ||
                   processed_windows == total_windows

                    println(
                        "  ",
                        processed_windows,
                        "/",
                        total_windows,
                        " windows"
                    )
                end
            end
        end
    end

    social_window_results =
        DataFrames.DataFrame(
            model =
                social_model,

            simulation =
                social_simulation,

            window =
                social_window,

            start_step =
                social_start_step,

            end_step =
                social_end_step,

            M =
                social_M,

            U =
                social_U,

            observed_R =
                social_observed_R,

            expected_R =
                social_expected_R,

            excess_R =
                social_excess_R,

            null_sd_R =
                social_sd_null_R,

            z_R =
                social_z_R
        )

    # ============================================================
    # 6. SIMULATION-LEVEL SOCIAL SUMMARY
    #
    # First average the 200 windows within each simulation.
    # This prevents a simulation from contributing 200 independent
    # observations to the final model-level summary.
    # ============================================================

    valid_social =
        DataFrames.dropmissing(
            social_window_results,
            [
                :observed_R,
                :expected_R,
                :excess_R
            ]
        )

    social_simulation_summary =
        DataFrames.combine(
            DataFrames.groupby(
                valid_social,
                [:model, :simulation]
            ),

            DataFrames.nrow =>
                :n_valid_windows,

            :M =>
                Statistics.mean =>
                :mean_M,

            :U =>
                Statistics.mean =>
                :mean_U,

            :observed_R =>
                Statistics.mean =>
                :mean_observed_R,

            :expected_R =>
                Statistics.mean =>
                :mean_expected_R,

            :excess_R =>
                Statistics.mean =>
                :mean_excess_R,

            :z_R =>
                (
                    x -> begin
                        vals =
                            collect(
                                Base.skipmissing(x)
                            )

                        isempty(vals) ?
                            missing :
                            Statistics.mean(vals)
                    end
                ) =>
                :mean_z_R
        )

    # ============================================================
    # 7. MODEL-LEVEL SOCIAL SUMMARY
    # ============================================================

    social_model_summary =
        DataFrames.combine(
            DataFrames.groupby(
                social_simulation_summary,
                :model
            ),

            DataFrames.nrow =>
                :n_simulations,

            :mean_observed_R =>
                Statistics.mean =>
                :mean_observed_R,

            :mean_observed_R =>
                Statistics.std =>
                :sd_observed_R,

            :mean_expected_R =>
                Statistics.mean =>
                :mean_expected_R,

            :mean_expected_R =>
                Statistics.std =>
                :sd_expected_R,

            :mean_excess_R =>
                Statistics.mean =>
                :mean_excess_R,

            :mean_excess_R =>
                Statistics.std =>
                :sd_excess_R,

            :mean_z_R =>
                (
                    x -> begin
                        vals =
                            collect(
                                Base.skipmissing(x)
                            )

                        isempty(vals) ?
                            missing :
                            Statistics.mean(vals)
                    end
                ) =>
                :mean_z_R
        )

    # ============================================================
    # 8. 95% CI FOR MEAN EXCESS R
    # ============================================================

    social_model_summary[
        !,
        :se_excess_R
    ] =
        social_model_summary.sd_excess_R ./
        sqrt.(social_model_summary.n_simulations)

    social_model_summary[
        !,
        :ci95_low_excess_R
    ] =
        social_model_summary.mean_excess_R .-
        1.96 .*
        social_model_summary.se_excess_R

    social_model_summary[
        !,
        :ci95_high_excess_R
    ] =
        social_model_summary.mean_excess_R .+
        1.96 .*
        social_model_summary.se_excess_R

    # ============================================================
    # 8A. ADDITIONAL OBSERVED-R DISTRIBUTIONS
    #
    # The original all-window summaries above remain unchanged.
    # Each observation here is a simulation-level mean R.
    # ============================================================

    @assert 1 <= n_sampled_windows <= n_windows

    sampled_windows = [
        1 + fld(k * n_windows, n_sampled_windows)
        for k in 0:(n_sampled_windows - 1)
    ]

    sampled_social = social_window_results[
        in.(social_window_results.window, Ref(Set(sampled_windows))),
        :
    ]

    valid_sampled_social = DataFrames.dropmissing(
        sampled_social, :observed_R
    )

    sampled_simulation_summary = DataFrames.combine(
        DataFrames.groupby(
            valid_sampled_social, [:model, :simulation]
        ),
        DataFrames.nrow => :n_valid_windows,
        :observed_R => Statistics.mean => :mean_observed_R
    )

    # All-window distribution: the existing simulation-level means.
    # Sampled-window distribution: the new simulation-level means.
    function describe_observed_R_distribution(df, window_label)
        result = DataFrames.combine(
            DataFrames.groupby(df, :model),
            DataFrames.nrow => :n_simulations,
            :mean_observed_R => Statistics.mean => :mean_R,
            :mean_observed_R => Statistics.std => :sd_R,
            :mean_observed_R => Statistics.median => :median_R,
            :mean_observed_R =>
                (x -> Statistics.quantile(x, 0.025)) => :q025_R,
            :mean_observed_R =>
                (x -> Statistics.quantile(x, 0.975)) => :q975_R,
            :mean_observed_R => minimum => :min_R,
            :mean_observed_R => maximum => :max_R
        )
        DataFrames.insertcols!(result, 1, :window_selection =>
            fill(window_label, DataFrames.nrow(result)))
        return result
    end

    all_R_distribution_summary = describe_observed_R_distribution(
        social_simulation_summary, "all $(n_windows) windows"
    )

    sampled_R_distribution_summary = describe_observed_R_distribution(
        sampled_simulation_summary,
        "$(n_sampled_windows) spaced windows"
    )

    observed_R_distribution_summary = vcat(
        all_R_distribution_summary,
        sampled_R_distribution_summary
    )

    println("\nAdditional sampled windows: ", sampled_windows)

    # ============================================================
    # 9. PLOTS
    # ============================================================

    # ------------------------------------------------------------
    # Plot 1: semantic outlier percentages
    # ------------------------------------------------------------

    p_outliers =
        Plots.bar(
            outlier_summary.model,
            outlier_summary.percentage_runs_with_outlier;
            xlabel =
                "Model",
            ylabel =
                "Runs with persistent semantic outlier (%)",
            title =
                "Persistent semantic outliers",
            legend =
                false,
            ylim =
                (0, 100),
            framestyle =
                :box,
            grid =
                false,
            fontfamily =
                "Calibri",
            size =
                (800, 600)
        )

    # ------------------------------------------------------------
    # Plot 2: observed R vs analytic null
    # ------------------------------------------------------------

    model_plot_names =
        social_model_summary.model

    observed_values =
        social_model_summary.mean_observed_R

    expected_values =
        social_model_summary.mean_expected_R

    x =
        collect(
            1:length(model_plot_names)
        )

    p_repetition =
        Plots.scatter(
            x .- 0.08,
            observed_values;
            markersize =
                8,
            label =
                "Observed",
            xlabel =
                "Model",
            ylabel =
                "Repetition R",
            title =
                "Social repetition vs random-pair null",
            xticks =
                (
                    x,
                    model_plot_names
                ),
            framestyle =
                :box,
            grid =
                false,
            fontfamily =
                "Calibri",
            size =
                (850, 600)
        )

    Plots.scatter!(
        p_repetition,
        x .+ 0.08,
        expected_values;
        markersize =
            8,
        label =
            "Random-pair null"
    )

    # ------------------------------------------------------------
    # Plot 3: excess R
    # ------------------------------------------------------------

    excess_error =
        1.96 .*
        social_model_summary.se_excess_R

    p_excess =
        Plots.scatter(
            x,
            social_model_summary.mean_excess_R;
            yerror =
                excess_error,
            markersize =
                8,
            label =
                "Mean ± 95% CI",
            xlabel =
                "Model",
            ylabel =
                "Observed R − expected R",
            title =
                "Excess social repetition",
            xticks =
                (
                    x,
                    model_plot_names
                ),
            framestyle =
                :box,
            grid =
                false,
            fontfamily =
                "Calibri",
            size =
                (850, 600)
        )

    Plots.hline!(
        p_excess,
        [0.0];
        linestyle =
            :dash,
        linewidth =
            2,
        label =
            "Random-pair null"
    )

    # ------------------------------------------------------------
    # Plot 4 and 5: distributions of observed simulation-level R
    # (all windows versus regularly spaced sampled windows)
    # ------------------------------------------------------------

    function plot_observed_R_distributions(df, title_text)
        vals1 = Float64.(df[
            df.model .== model_names[1], :mean_observed_R
        ])
        vals2 = Float64.(df[
            df.model .== model_names[2], :mean_observed_R
        ])

        # Identical bin edges for the two models in each figure.
        both = vcat(vals1, vals2)
        lo, hi = extrema(both)
        if lo == hi
            lo -= 0.001
            hi += 0.001
        end
        bin_edges = collect(range(lo, hi; length = 31))

        p = Plots.histogram(
            vals1;
            bins = bin_edges,
            normalize = :pdf,
            alpha = 0.5,
            label = model_names[1],
            xlabel = "Mean observed R per simulation",
            ylabel = "Density",
            title = title_text,
            framestyle = :box,
            grid = false,
            fontfamily = "Calibri",
            size = (900, 600)
        )

        Plots.histogram!(
            p, vals2;
            bins = bin_edges,
            normalize = :pdf,
            alpha = 0.5,
            label = model_names[2]
        )

        return p
    end

    p_R_all_windows = plot_observed_R_distributions(
        social_simulation_summary,
        "Observed R distribution — all $(n_windows) windows"
    )

    p_R_sampled_windows = plot_observed_R_distributions(
        sampled_simulation_summary,
        "Observed R distribution — $(n_sampled_windows) spaced windows"
    )

    # ============================================================
    # 10. SAVE ANALYSIS
    # ============================================================

    if save_path !== nothing

        println()
        println("Saving analysis...")

        JLD2.jldsave(
            save_path;

            outlier_summary =
                outlier_summary,

            paired_outlier_summary =
                paired_outlier_summary,

            crossed =
                crossed,

            crossing_step =
                crossing_step,

            any_crossing =
                any_crossing,

            n_crossing_agents =
                n_crossing_agents,

            social_window_results =
                social_window_results,

            social_simulation_summary =
                social_simulation_summary,

            social_model_summary =
                social_model_summary,

            sampled_windows = sampled_windows,
            sampled_simulation_summary = sampled_simulation_summary,
            all_R_distribution_summary = all_R_distribution_summary,
            sampled_R_distribution_summary = sampled_R_distribution_summary,
            observed_R_distribution_summary = observed_R_distribution_summary,
            z_proportions = z_proportions,
            p_proportions = p_proportions,

            threshold =
                Float64(threshold),

            source_file =
                path,

            pair_map =
                pair_map,

            steps_axis =
                steps_axis,

            model_names =
                model_names
        )
    end

    # ============================================================
    # 11. PRINT RESULTS
    # ============================================================

    println()
    println("="^90)
    println("SEMANTIC OUTLIERS")
    println("="^90)

    show(
        stdout,
        outlier_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()
    println()

    println(
        "Percentage-point difference (original - relocation): ",
        round(
            percentage_point_difference;
            digits = 3
        )
    )
    println(
        "95% CI for proportion difference (original - relocation): [",
        round(
            ci95_low_proportion_difference;
            digits = 4
        ),
        ", ",
        round(
            ci95_high_proportion_difference;
            digits = 4
        ),
        "]"
    )
    println(
        "95% CI for percentage-point difference: [",
        round(
            100.0 * ci95_low_proportion_difference;
            digits = 3
        ),
        ", ",
        round(
            100.0 * ci95_high_proportion_difference;
            digits = 3
        ),
        "]"
    )

    println()
    println("ONE-SIDED TWO-PROPORTION Z-TEST (UNPAIRED)")
    println("H1: Original > Random relocation")

    println(
        "Z statistic: ",
        round(z_proportions; digits = 4)
    )

    println(
        "One-sided p-value: ",
        p_proportions
    )

    println()
    println("Paired outcomes:")

    show(
        stdout,
        paired_outlier_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()
    println()

    println("="^90)
    println("SOCIAL REPETITION VS RANDOM-PAIR NULL")
    println("="^90)

    show(
        stdout,
        social_model_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()
    println("="^90)
    println("OBSERVED R DISTRIBUTIONS — ALL AND SAMPLED WINDOWS")
    println("="^90)
    show(
        stdout, observed_R_distribution_summary;
        allrows = true, allcols = true, truncate = 0
    )
    println("\nSampled window indices: ", sampled_windows)
    println()

    if save_path !== nothing
        println()
        println("Saved analysis to: ", save_path)
    end

    display(p_outliers)
    display(p_repetition)
    display(p_excess)
    display(p_R_all_windows)
    display(p_R_sampled_windows)

    # ============================================================
    # 12. RETURN
    # ============================================================

    return (
        outlier_summary =
            outlier_summary,

        paired_outlier_summary =
            paired_outlier_summary,

        percentage_point_difference =
            percentage_point_difference,

        crossed =
            crossed,

        crossing_step =
            crossing_step,

        any_crossing =
            any_crossing,

        n_crossing_agents =
            n_crossing_agents,

        social_window_results =
            social_window_results,

        social_simulation_summary =
            social_simulation_summary,

        social_model_summary =
            social_model_summary,

        sampled_windows = sampled_windows,
        sampled_simulation_summary = sampled_simulation_summary,
        all_R_distribution_summary = all_R_distribution_summary,
        sampled_R_distribution_summary = sampled_R_distribution_summary,
        observed_R_distribution_summary = observed_R_distribution_summary,

        z_proportions = z_proportions,
        p_proportions = p_proportions,

        plot_outliers =
            p_outliers,

        plot_repetition =
            p_repetition,

        plot_excess_repetition =
            p_excess,

        plot_R_all_windows = p_R_all_windows,
        plot_R_sampled_windows = p_R_sampled_windows
    )
end
# control_analysis =
#     analyze_original_vs_relocation_control(
#         joinpath(
#             "sweep_beta_logs",
#             "ORIGINAL_VS_RANDOM_RELOCATION_RAW_1000.jld2"
#         );
#         threshold = 2.5,
#         n_sampled_windows = 20,
#         progress_every = 1000,
#         save_path = joinpath(
#             "sweep_beta_logs",
#             "ORIGINAL_VS_RANDOM_RELOCATION_ANALYSIS_1000.jld2"
#         )
# )

function monte_carlo_test_mean_R(
    path::String;
    n_null::Int = 10_000,
    progress_every::Int = 500)

    # ============================================================
    # 1. LOAD
    # ============================================================

    println("\nLoading control simulation file...")

    d = JLD2.load(path)

    pair_episode_counts =
        d["pair_episode_counts"]

    steps_axis =
        Int.(d["steps_axis"])

    pair_map =
        Tuple{Int,Int}.(d["pair_map"])

    model_names =
        String.(d["model_names"])


    n_models =
        size(pair_episode_counts, 1)

    n_sim =
        size(pair_episode_counts, 2)

    n_timepoints =
        size(pair_episode_counts, 3)

    n_pairs =
        size(pair_episode_counts, 4)

    n_windows =
        n_timepoints - 1
    sampled_windows =
        collect(1:10:n_windows)

    println(
        "Sampled windows: ",
        sampled_windows
    )

    println(
        "Number of sampled windows per simulation: ",
        length(sampled_windows)
    )


    @assert n_pairs == 190
    @assert length(pair_map) == n_pairs
    @assert length(steps_axis) == n_timepoints
    @assert length(model_names) == n_models


    println("Loaded successfully.")
    println("Models:       ", model_names)
    println("Simulations:  ", n_sim, " per model")
    println("Windows:      ", n_windows, " per simulation")
    println("Pairs:        ", n_pairs)
    println("Null runs:    ", n_null)


    # ============================================================
    # 2. EXTRACT OBSERVED M AND R
    #
    # M = number of pairwise conversation episodes in the window
    # U = number of unique pairs used
    #
    # R = 1 - U/M
    # ============================================================

    println()
    println("Calculating observed R and M...")

    M_observed =
        zeros(
            Int,
            n_models,
            n_sim,
            n_windows
        )

    R_observed =
        fill(
            NaN,
            n_models,
            n_sim,
            n_windows
        )


    for model_idx in 1:n_models

        for sim_idx in 1:n_sim

            for window_idx in sampled_windows

                M = 0
                U = 0

                @inbounds for p in 1:n_pairs

                    c =
                        Int(
                            pair_episode_counts[
                                model_idx,
                                sim_idx,
                                window_idx + 1,
                                p
                            ]
                        ) -
                        Int(
                            pair_episode_counts[
                                model_idx,
                                sim_idx,
                                window_idx,
                                p
                            ]
                        )

                    if c < 0
                        error(
                            "Negative episode-count difference: " *
                            "model=$(model_names[model_idx]), " *
                            "simulation=$sim_idx, " *
                            "window=$window_idx, " *
                            "pair=$p."
                        )
                    end

                    M += c

                    if c > 0
                        U += 1
                    end
                end


                M_observed[
                    model_idx,
                    sim_idx,
                    window_idx
                ] =
                    M


                if M > 0

                    R_observed[
                        model_idx,
                        sim_idx,
                        window_idx
                    ] =
                        1.0 -
                        U / M
                end
            end
        end
    end


    # ============================================================
    # 3. OBSERVED MEAN R
    #
    # Same aggregation as the original analysis:
    #
    #   1. mean across valid windows within each simulation
    #   2. mean across simulations
    # ============================================================

    observed_simulation_mean_R =
        fill(
            NaN,
            n_models,
            n_sim
        )


    for model_idx in 1:n_models

        for sim_idx in 1:n_sim

            vals =
                Float64[]

            for window_idx in sampled_windows

                r =
                    R_observed[
                        model_idx,
                        sim_idx,
                        window_idx
                    ]

                if isfinite(r)
                    push!(vals, r)
                end
            end


            if !isempty(vals)

                observed_simulation_mean_R[
                    model_idx,
                    sim_idx
                ] =
                    Statistics.mean(vals)
            end
        end
    end


    observed_mean_R =
        zeros(
            Float64,
            n_models
        )


    for model_idx in 1:n_models

        vals =
            Float64[]

        for sim_idx in 1:n_sim

            r =
                observed_simulation_mean_R[
                    model_idx,
                    sim_idx
                ]

            if isfinite(r)
                push!(vals, r)
            end
        end

        observed_mean_R[model_idx] =
            Statistics.mean(vals)
    end


    # ============================================================
    # 4. MONTE CARLO NULL
    #
    # For each null run:
    #
    # For every observed 100-step window:
    #   - preserve observed M
    #   - independently assign each of the M episodes
    #     to one of P possible pairs with equal probability
    #   - calculate U
    #   - calculate R = 1 - U/M
    #
    # Then:
    #   - average R across windows within simulation
    #   - average across simulations
    # ============================================================

    null_mean_R =
        zeros(
            Float64,
            n_models,
            n_null
        )


    println()
    println("="^80)
    println("MONTE CARLO NULL SIMULATION")
    println("="^80)


    # Reusable Boolean vector for recording which pairs
    # were selected in a given window.
    used_pairs =
        falses(n_pairs)


    for null_idx in 1:n_null

        for model_idx in 1:n_models

            sum_simulation_means =
                0.0

            n_valid_simulations =
                0


            for sim_idx in 1:n_sim

                sum_window_R =
                    0.0

                n_valid_windows =
                    0


                for window_idx in sampled_windows

                    M =
                        M_observed[
                            model_idx,
                            sim_idx,
                            window_idx
                        ]


                    if M == 0
                        continue
                    end


                    # --------------------------------------------
                    # Randomly allocate the M episodes among
                    # the P possible pairs.
                    # --------------------------------------------

                    fill!(
                        used_pairs,
                        false
                    )


                    @inbounds for episode in 1:M

                        p =
                            rand(
                                1:n_pairs
                            )

                        used_pairs[p] =
                            true
                    end


                    U_null =
                        count(used_pairs)


                    R_null =
                        1.0 -
                        U_null / M


                    sum_window_R +=
                        R_null

                    n_valid_windows +=
                        1
                end


                # --------------------------------------------
                # Mean within simulation
                # --------------------------------------------

                if n_valid_windows > 0

                    simulation_mean_R =
                        sum_window_R /
                        n_valid_windows


                    sum_simulation_means +=
                        simulation_mean_R

                    n_valid_simulations +=
                        1
                end
            end


            # --------------------------------------------
            # Mean across simulations
            # --------------------------------------------

            if n_valid_simulations == 0

                error(
                    "No valid simulations for model " *
                    model_names[model_idx]
                )
            end


            null_mean_R[
                model_idx,
                null_idx
            ] =
                sum_simulation_means /
                n_valid_simulations
        end


        if null_idx == 1 ||
           null_idx % progress_every == 0 ||
           null_idx == n_null

            println(
                "  Null run ",
                null_idx,
                " / ",
                n_null
            )
        end
    end


    # ============================================================
    # 5. TWO-SIDED MONTE CARLO TEST
    #
    # Center = mean of the simulated null distribution.
    #
    # T_obs =
    #     abs(observed mean R - null center)
    #
    # T_null =
    #     abs(null mean R - null center)
    #
    # p =
    #     (1 + number of T_null >= T_obs) /
    #     (n_null + 1)
    # ============================================================

    null_center =
        zeros(
            Float64,
            n_models
        )

    null_sd =
        zeros(
            Float64,
            n_models
        )

    null_q025 =
        zeros(
            Float64,
            n_models
        )

    null_median =
        zeros(
            Float64,
            n_models
        )

    null_q975 =
        zeros(
            Float64,
            n_models
        )

    observed_deviation =
        zeros(
            Float64,
            n_models
        )

    n_as_or_more_extreme =
        zeros(
            Int,
            n_models
        )

    p_two_sided =
        zeros(
            Float64,
            n_models
        )


    for model_idx in 1:n_models

        vals =
            @view null_mean_R[
                model_idx,
                :
            ]


        center =
            Statistics.mean(vals)


        null_center[model_idx] =
            center

        null_sd[model_idx] =
            Statistics.std(vals)

        null_q025[model_idx] =
            Statistics.quantile(
                vals,
                0.025
            )

        null_median[model_idx] =
            Statistics.median(vals)

        null_q975[model_idx] =
            Statistics.quantile(
                vals,
                0.975
            )


        T_obs =
            abs(
                observed_mean_R[model_idx] -
                center
            )


        observed_deviation[model_idx] =
            T_obs


        n_extreme =
            count(
                abs(x - center) >= T_obs
                for x in vals
            )


        n_as_or_more_extreme[model_idx] =
            n_extreme


        p_two_sided[model_idx] =
            (
                1.0 +
                n_extreme
            ) /
            (
                n_null +
                1.0
            )
    end


    # ============================================================
    # 6. SUMMARY
    # ============================================================

    summary =
        DataFrames.DataFrame(

            model =
                model_names,

            observed_mean_R =
                observed_mean_R,

            null_mean_R =
                null_center,

            null_sd_R =
                null_sd,

            null_q025 =
                null_q025,

            null_median =
                null_median,

            null_q975 =
                null_q975,

            observed_absolute_deviation =
                observed_deviation,

            n_as_or_more_extreme =
                n_as_or_more_extreme,

            n_null =
                fill(
                    n_null,
                    n_models
                ),

            p_two_sided =
                p_two_sided
        )


    # ============================================================
    # 7. PRINT
    # ============================================================

    println()
    println("="^90)
    println("TWO-SIDED MONTE CARLO TEST OF MEAN SOCIAL REPETITION R")
    println("="^90)


    for model_idx in 1:n_models

        println()
        println(
            "Model: ",
            model_names[model_idx]
        )

        println(
            "  Observed mean R: ",
            round(
                observed_mean_R[model_idx];
                digits = 6
            )
        )

        println(
            "  Null mean R:     ",
            round(
                null_center[model_idx];
                digits = 6
            )
        )

        println(
            "  Null SD:         ",
            round(
                null_sd[model_idx];
                digits = 6
            )
        )

        println(
            "  Null 95% range:  [",
            round(
                null_q025[model_idx];
                digits = 6
            ),
            ", ",
            round(
                null_q975[model_idx];
                digits = 6
            ),
            "]"
        )

        println(
            "  |Observed-null|: ",
            round(
                observed_deviation[model_idx];
                digits = 6
            )
        )

        println(
            "  Extreme nulls:   ",
            n_as_or_more_extreme[model_idx],
            " / ",
            n_null
        )

        println(
            "  Two-sided p:     ",
            round(
                p_two_sided[model_idx];
                digits = 6
            )
        )
    end


    println()
    println("="^90)


    # ============================================================
    # 8. RETURN
    # ============================================================

    return (

        summary =
            summary,

        observed_mean_R =
            observed_mean_R,

        observed_simulation_mean_R =
            observed_simulation_mean_R,

        R_observed =
            R_observed,

        M_observed =
            M_observed,

        null_mean_R =
            null_mean_R
    )
end
