# Null model 3 - פיזור במרחב + כל השינויים ממקור חיצוני חדש לגמרי

function create_network_from_existing_base(
    base_network::AbstractMatrix{Float32},
    n::Int,
    m::Int,
    change::Float64;
    utilities = ones(Float32, n))
    fixed_words =
        round(Int, n * (1 - change))

    new_net =
        zeros(Float32, n, n)

    new_net[
        1:fixed_words,
        1:fixed_words
    ] .=
        base_network[
            1:fixed_words,
            1:fixed_words
        ]

    degrees =
        zeros(Float32, n)

    degrees[1:fixed_words] .=
        vec(
            sum(
                new_net[
                    1:fixed_words,
                    1:fixed_words
                ];
                dims = 2
            )
        )

    for i in (fixed_words + 1):n

        word =
            sample(
                1:(i - 1),
                Weights(
                    degrees[1:(i - 1)]
                )
            )

        neighbors =
            findall(
                !iszero,
                view(
                    new_net,
                    1:(i - 1),
                    word
                )
            )

        probabilities =
            utilities[neighbors]

        contacts =
            sample(
                neighbors,
                Weights(probabilities),
                m;
                replace = false
            )

        for w in contacts

            new_net[w, i] =
                1f0

            new_net[i, w] =
                1f0

            degrees[w] +=
                1f0
        end

        new_net[i, i] =
            1f0

        degrees[i] =
            Float32(m)
    end

    new_net[
        LinearAlgebra.diagind(new_net)
    ] .=
        0f0

    return new_net
end
function init_world_model_3_1(
    N::Int,
    W::Int,
    H::Int,
    n::Int,
    m::Int,
    change::Float64;
    gamma::Float64 = 0.0,
    beta::Float64 = 0.0,
    delta::Float64 = 0.0,
    p0::Float64 = 0.5,
    beta_for_consent::Float64 = 0.0,
    abandonment_threshold = 100)

    # ============================================================
    # Shared base for THIS simulation
    # ============================================================

    base_network =
        create_network(
            n,
            m
        )

    # ============================================================
    # Build a normal World using the existing initializer
    # ============================================================

    world =
        init_world(
            N,
            W,
            H,
            n,
            m,
            change;
            gamma = gamma,
            beta = beta,
            delta = delta,
            p0 = p0,
            beta_for_consent = beta_for_consent,
            abandonment_threshold = abandonment_threshold,
            outliers_count = 0,
            outlier_change = nothing
        )

    # ============================================================
    # Replace semantic networks ONLY in this new World
    #
    # All agents share the same base_network.
    # ============================================================

    for agent in 1:N

        world.agents[:, :, agent] .=
            create_network_from_existing_base(
                base_network,
                n,
                m,
                change
            )
    end

    # ============================================================
    # Recalculate all dependent semantic quantities
    # ============================================================

    world.current_distances .=
        differences_serial(
            world.agents
        )

    start_perceived_distance =
        mean_offdiag(
            world.current_distances
        )

    world.perceived_distance .=
        Float32(start_perceived_distance)

    for i in 1:N
        world.perceived_distance[i, i] =
            0.0f0
    end

    empty!(
        world.perceived_distance_history
    )

    push!(
        world.perceived_distance_history,
        copy(world.perceived_distance)
    )

    @inbounds for i in 1:N

        world.agent_sum[i] =
            sum(
                @view world.agents[:, :, i]
            )

        Ai =
            @view world.agents[:, :, i]

        world.colsum[:, i] .=
            vec(
                sum(
                    Ai;
                    dims = 1
                )
            )
    end

    empty!(
        world.distances_history
    )

    push!(
        world.distances_history,
        copy(world.current_distances)
    )

    return (
        world = world,
        base_network = base_network
    )
end
# Every invocation creates an entirely independent external semantic network.
# The real agent and temporary partner both learn, exactly as in Model 3.
function external_interaction_3_1!(
    agent::Int,
    world,
    L::Int;
    m::Int = 4,
    social_impact::Float64 = 1.0)

    n = world.n
    partner = create_network(n, m)

    partner_colsum =
        vec(
            sum(
                partner;
                dims = 1
            )
        )

    # --------------------------------------------------------
    # Initial cue comes from the real agent, analogous to the
    # first participant supplying the initial cue in the
    # original conversation!.
    # --------------------------------------------------------

    cue =
        sample(
            1:n,
            Weights(
                @view world.colsum[:, agent]
            )
        )

    agent_can_speak =
        !world.silent[agent]

    # --------------------------------------------------------
    # If the real agent can speak:
    #     partner -> agent -> partner -> agent ...
    #
    # If silent:
    #     partner -> partner -> partner ...
    #
    # Both networks learn every produced association.
    # --------------------------------------------------------

    speaker_is_partner = true

    for _ in 1:L

        if speaker_is_partner || !agent_can_speak

            association =
                sample(
                    1:n,
                    Weights(
                        @view partner[:, cue]
                    )
                )

        else

            association =
                sample(
                    1:n,
                    Weights(
                        @view world.agents[:, cue, agent]
                    )
                )
        end

        # ====================================================
        # REAL AGENT LEARNS
        # ====================================================

        world.agents[
            association,
            cue,
            agent
        ] += social_impact

        world.agents[
            cue,
            association,
            agent
        ] += social_impact

        world.agent_sum[agent] +=
            2.0f0 * social_impact

        world.colsum[
            cue,
            agent
        ] +=
            1.0f0 * social_impact

        world.colsum[
            association,
            agent
        ] +=
            1.0f0 * social_impact

        # ====================================================
        # TEMPORARY PARTNER LEARNS
        # ====================================================

        partner[
            association,
            cue
        ] += social_impact

        partner[
            cue,
            association
        ] += social_impact

        partner_colsum[cue] +=
            1.0f0 * social_impact

        partner_colsum[association] +=
            1.0f0 * social_impact

        cue =
            association

        if agent_can_speak
            speaker_is_partner =
                !speaker_is_partner
        end
    end

    # The temporary partner is discarded after this invocation.
    return nothing
end

# Preserve Model 3's social-group eligibility and per-agent interactions.
function conversation_with_external_partners_3_1!(
    group,
    world,
    L::Int;
    m::Int = 4,
    social_impact::Float64 = 1.0)

    members = shuffle(group)
    nspeakers = count(agent -> !world.silent[agent], members)
    if nspeakers < 2
        return true
    end

    for agent in members
        external_interaction_3_1!(
            agent, world, L;
            m=m,
            social_impact=social_impact
        )
    end

    return false
end

function step_model_3_1!(
    world::World;
    talk_duration::Int=5,
    refractory_duration::Int=10,
    self_talk_threshold::Int=10,
    L::Int=10,
    eta::Float32=0.5f0,
    beta_for_consent::Real=10.0,
    gamma::Union{Nothing,Real}=nothing,
    beta::Union{Nothing,Real}=nothing,
    delta::Union{Nothing,Real}=nothing,
    p0::Union{Nothing,Real}=nothing,
    pmin::Real=0.05,
    record_distances::Bool=true,
    record_every::Int=1,
    social_impact::Float64=1.0,
    join_rule::Symbol=:group_any,
    social_learning_prob=ones(Float32, world.N),
    m::Int=4,
    change::Float64=0.7)

    # --- Update parameters if provided ---
    if gamma !== nothing world.γ = Float32(gamma) end
    if beta !== nothing world.β = Float32(beta) end
    if delta !== nothing world.δ = Float32(delta) end
    if p0 !== nothing world.p0 = Float32(p0) end
    if beta_for_consent !== nothing world.beta_for_consent = Float32(beta_for_consent) end

    world.t += 1

    # 1) Group Conversation Phase
    group_ids = unique(world.talking_group)
    talked_groups = Vector{Vector{Int}}()

    for gid in group_ids
        gid == 0 && continue

        # Identify current group members
        members = [i for i in 1:world.N if world.talking_group[i] == gid]
        Lm = length(members)

        # Handle fragmented groups (less than 2 agents)
        if Lm < 2
            if Lm == 1
                if world.talk_left[members[1]] > 0
                    mark_abandonment!(world, members[1])
                end

                end_conversation_for_agent!(
                    world,
                    members[1],
                    refractory_duration
                )

                relocate_agent_randomly!(
                    world,
                    members[1]
                )
            end

            continue
        end

        # Check for silence (fewer than 2 speakers)
        all_silent = true
        nspeakers = 0

        @inbounds for m in members
            if !world.silent[m]
                nspeakers += 1

                if nspeakers >= 2
                    all_silent = false
                    break
                end
            end
        end

        if all_silent
            # If fewer than 2 agents can talk, group dissolves
            @inbounds for m in members

                for other in members
                    if m != other
                        push!(
                            world.agent_seen_partners[m],
                            other
                        )
                    end
                end

                if world.talk_left[m] > 0
                    mark_abandonment!(
                        world,
                        m
                    )
                end

                end_conversation_for_agent!(
                    world,
                    m,
                    refractory_duration
                )

                relocate_agent_randomly!(
                    world,
                    m
                )
            end

            continue
        end

        push!(
            talked_groups,
            members
        )

        speakers = Int[]

        @inbounds for m in members
            if !world.silent[m]
                push!(
                    speakers,
                    m
                )
            end
        end

        # --------------------------------------------------------
        # Social conversation is still logged exactly as before.
        # Semantically, however, agents do NOT talk to each other.
        # --------------------------------------------------------

        # Historical conversation-event logging omitted.

        # --------------------------------------------------------
        # NEW:
        # Every speaking agent talks to its own freshly generated
        # temporary semantic network.
        #
        # No semantic information passes between real agents.
        # --------------------------------------------------------

        conversation_with_external_partners_3_1!(
            members,
            world,
            L;
            m=m,
            social_impact=social_impact
        )

        for i in members
            world.talk_left[i] -= 1
        end
    end

    # End Conversation & Refractory Check
    for i in 1:world.N

        if world.talking_group[i] != 0 &&
           world.talk_left[i] <= 0

            end_conversation_for_agent!(
                world,
                i,
                refractory_duration
            )

            relocate_agent_randomly!(
                world,
                i
            )
        end
    end

    # 2) Self-conversation phase
    for i in 1:world.N

        if world.talking_group[i] == 0

            if world.self_talk_left[i] > 0

                external_interaction_3_1!(
                    i, world, L;
                    m=m,
                    social_impact=social_impact
                )

                world.self_talk_count[i] += 1
                world.self_talk_left[i] -= 1

            else

                world.time_since_last_talk[i] += 1

                if world.time_since_last_talk[i] >= self_talk_threshold

                    world.self_talk_left[i] = 3

                    external_interaction_3_1!(
                        i, world, L;
                        m=m,
                        social_impact=social_impact
                    )

                    world.self_talk_count[i] += 1
                    world.self_talk_left[i] -= 1

                    world.time_since_last_talk[i] = 0
                end
            end

        else

            world.time_since_last_talk[i] = 0
        end
    end

    # --- 3) Semantic Updates (Perception) ---
    if eta != 0.0f0

        for group in talked_groups

            update_perceived_group!(
                world,
                group;
                eta=eta
            )
        end
    end

    if record_distances &&
       (world.t % record_every == 0)

        world.current_distances .=
            Float32.(
                differences_serial(
                    world.agents
                )
            )

        # Historical distance matrices are not stored in this runner.
    end

    # 4) Movement and Adjacency Logging
    move_agents!(
        world
    )

    # Historical adjacency logging omitted.

    # 5) Social Interaction Initiation
    form_conversations!(
        world;
        talk_duration=talk_duration,
        pmin=pmin,
        p0=p0,
        join_rule=join_rule
    )

    update_talk_episodes!(
        world
    )

    # 6) Refractory Period Update
    for i in 1:world.N

        if !isempty(
            world.refr_partners[i]
        )

            tick_refractory!(
                world.refr_partners,
                world.refr_left,
                i
            )
        end
    end

    # 7) Longitudinal Logging
    # Longitudinal partner-count history is not needed for this runner.

    return nothing
end

# ================================================================
# Parallel, resumable Model 3.1 runner
# Requires the original base-model functions, plus differences_serial.
# ================================================================

function run_model_3_1_one_parallel(;
    steps::Int=20_000,
    record_every::Int=100,
    reset_every::Int=100,
    threshold::Real=2.5)

    N=20; n=300; m=4; W=30; H=30; change=0.7
    talk_duration=10; refractory_duration=10; self_talk_threshold=10
    L=25; eta=0.2f0
    gamma=0.0; beta=1.0; delta=1.0; p0=0.5; pmin=0.05
    beta_for_consent=0.0; social_impact=1.0
    join_rule=:group_any; abandonment_threshold=10_000_000

    @assert steps > 0 && record_every > 0 && reset_every > 0
    @assert steps % record_every == 0

    steps_axis = collect(0:record_every:steps)
    distance_steps = collect(2000:2000:steps)
    pair_map = [(i,j) for i in 1:N-1 for j in i+1:N]
    T=length(steps_axis); P=length(pair_map)
    z = Matrix{Float32}(undef,T,N)
    means = Matrix{Float32}(undef,T,N)
    pairwise = Matrix{Float32}(undef,length(distance_steps),P)

    initial=init_world_model_3_1(N,W,H,n,m,change;
        gamma=gamma,beta=beta,delta=delta,p0=p0,
        beta_for_consent=beta_for_consent,
        abandonment_threshold=abandonment_threshold)
    world=initial.world
    # The initializer already computes the initial distances.
    empty!(world.distances_history)
    empty!(world.perceived_distance_history)
    empty!(world.unique_partners_steps)
    empty!(world.unique_partners_history)

    function record!(t_idx)
        D=world.current_distances
        @inbounds for i in 1:N
            acc=0.0
            for j in 1:N
                if i!=j
                    acc += D[i,j]
                end
            end
            means[t_idx,i]=Float32(acc/(N-1))
        end
        row=@view means[t_idx,:]
        μ=Statistics.mean(row)
        σ=Statistics.std(row)
        @inbounds for i in 1:N
            z[t_idx,i]=σ>0 ? Float32((row[i]-μ)/σ) : Float32(NaN)
        end
    end

    record!(1)
    time_idx=1
    for step_i in 1:steps
        if step_i % reset_every == 0
            reset_positions_and_interactions!(world)
        end
        step_model_3_1!(world;
            talk_duration=talk_duration,
            refractory_duration=refractory_duration,
            self_talk_threshold=self_talk_threshold,
            L=L,eta=eta,beta_for_consent=beta_for_consent,
            gamma=gamma,beta=beta,delta=delta,p0=p0,pmin=pmin,
            record_distances=true,record_every=record_every,
            social_impact=social_impact,join_rule=join_rule,
            m=m,change=change)
        if step_i % record_every == 0
            time_idx+=1
            record!(time_idx)
        end
        if step_i % 2000 == 0
            # Use the same post-step semantic network snapshot as original.
            D=world.current_distances
            snapshot_idx=step_i ÷ 2000
            @inbounds for p in 1:P
                i,j=pair_map[p]
                pairwise[snapshot_idx,p]=D[i,j]
            end
        end
    end
    @assert time_idx == T

    crossed=falses(N)
    crossing_step=fill(-1,N)
    for agent in 1:N
        # Earliest point in the final uninterrupted >= threshold suffix.
        start_idx=0
        for t_idx in T:-1:1
            if z[t_idx,agent] >= threshold
                start_idx=t_idx
            else
                break
            end
        end
        if start_idx>0
            crossed[agent]=true
            crossing_step[agent]=steps_axis[start_idx]
        end
    end
    return (z=z, means=means, pairwise=pairwise,
        crossed=crossed, crossing_step=crossing_step)
end

function run_model_3_1_raw_parallel(n_sim::Int;
    outdir::String=joinpath("sweep_beta_logs","MODEL_3_1_PARALLEL"),
    batch_size::Int=12,
    steps::Int=20_000,
    record_every::Int=100,
    reset_every::Int=100,
    threshold::Real=2.5)

    @assert n_sim>0 && batch_size>0
    @assert steps % record_every == 0
    mkpath(outdir)
    steps_axis=collect(0:record_every:steps)
    distance_steps=collect(2000:2000:steps)
    pair_map=[(i,j) for i in 1:19 for j in i+1:20]
    T=length(steps_axis); P=length(pair_map)
    batches=cld(n_sim,batch_size)

    println("MODEL 3.1 — PARALLEL SIMULATIONS")
    println("Simulations: $n_sim | Threads: $(Threads.nthreads()) | Batch size: $batch_size")
    println("Steps: $steps | Output: $outdir")

    for batch in 1:batches
        first_sim=(batch-1)*batch_size+1
        last_sim=min(batch*batch_size,n_sim)
        ids=collect(first_sim:last_sim)
        b=length(ids)
        path=joinpath(outdir,"batch_$(lpad(first_sim,5,'0'))_$(lpad(last_sim,5,'0')).jld2")

        if isfile(path)
            d=JLD2.load(path)
            @assert Int.(d["simulation_ids"]) == ids "Existing batch IDs mismatch: $path"
            @assert Int(d["steps"]) == steps && Int(d["record_every"]) == record_every &&
                    Int(d["reset_every"]) == reset_every && Float64(d["threshold"]) == Float64(threshold) "Existing batch settings mismatch: $path"
            @assert size(d["Z_all"]) == (1,b,T,20) "Existing batch shape mismatch: $path"
            println("Batch $batch/$batches: already saved ($(first_sim)–$(last_sim)), skipping")
            continue
        end

        println("Batch $batch/$batches: running simulations $(first_sim)–$(last_sim)")
        results=Vector{Any}(undef,b)
        completed_in_batch=Threads.Atomic{Int}(0)
        progress_lock=ReentrantLock()
        t=@elapsed begin
            Threads.@threads :static for k in 1:b
                sim_start=time()
                results[k]=run_model_3_1_one_parallel(;
                    steps=steps,record_every=record_every,
                    reset_every=reset_every,threshold=threshold)
                elapsed_sim=time()-sim_start
                finished=Threads.atomic_add!(completed_in_batch,1)+1
                # Serialize progress messages to prevent mixed output.
                lock(progress_lock) do
                    println("  Completed simulation $(ids[k]) | Batch: $finished/$b | Total: $((batch-1)*batch_size+finished)/$n_sim | $(round(elapsed_sim,digits=1)) sec")
                    flush(stdout)
                end
            end
        end

        Z_all=Array{Float32}(undef,1,b,T,20)
        mean_distances_all=similar(Z_all)
        pairwise_distances=Array{Float32}(undef,b,length(distance_steps),P)
        crossed=falses(1,b,20)
        crossing_step=fill(-1,1,b,20)
        n_crossing_agents=zeros(Int,1,b)
        any_crossing=falses(1,b)

        for k in 1:b
            r=results[k]
            Z_all[1,k,:,:]=r.z
            mean_distances_all[1,k,:,:]=r.means
            pairwise_distances[k,:,:]=r.pairwise
            crossed[1,k,:]=r.crossed
            crossing_step[1,k,:]=r.crossing_step
            n_crossing_agents[1,k]=count(r.crossed)
            any_crossing[1,k]=any(r.crossed)
        end
        results=nothing
        run_summary=DataFrames.DataFrame(model=fill("model_3_1",b),
            simulation=ids,any_crossing=vec(any_crossing),
            n_crossing_agents=vec(n_crossing_agents))
        crossing_results=DataFrames.DataFrame(
            model=fill("model_3_1",b*20),
            simulation=repeat(ids,inner=20),
            agent=repeat(collect(1:20),outer=b),
            crossed=[crossed[1,k,a] for k in 1:b for a in 1:20],
            crossing_step=Union{Missing,Int}[
                crossed[1,k,a] ? crossing_step[1,k,a] : missing
                for k in 1:b for a in 1:20])
        tmp=path*".tmp"
        JLD2.jldsave(tmp;
            simulation_ids=ids,Z_all=Z_all,
            mean_distances_all=mean_distances_all,
            pairwise_distances=pairwise_distances,
            crossed=crossed,crossing_step=crossing_step,
            n_crossing_agents=n_crossing_agents,any_crossing=any_crossing,
            run_summary=run_summary,crossing_results=crossing_results,
            model_names=["model_3_1"],steps_axis=steps_axis,
            distance_steps=distance_steps,pair_map=pair_map,
            threshold=Float64(threshold),N=20,n_words=300,m=4,
            change=0.7,n_sim=b,steps=steps,record_every=record_every,
            reset_every=reset_every,beta_for_consent=0.0,
            movement_beta=1.0,talk_duration=10,refractory_duration=10,
            self_talk_threshold=10,L=25,eta=0.2f0,gamma=0.0,
            delta=1.0,p0=0.5,pmin=0.05,social_impact=1.0,
            join_rule="group_any",random_relocation=true,
            real_agent_agent_learning=false,
            self_talk_replaced_by_external=true,
            external_network_independent=true,
            fresh_partner_each_conversation_call=true,
            temporary_partner_learning=true,
            raw_mean_distances_saved=true,fixed_random_seed=false)
        mv(tmp,path;force=true)
        println("  Saved $b simulations in $(round(t,digits=1)) seconds | crossing runs=$(count(any_crossing))")
    end
    println("Completed: $n_sim simulations. Files in: $outdir")
    return outdir
end

function analyze_model_3_1_parallel(outdir::String; threshold::Real=2.5)
    files=sort(filter(f->startswith(basename(f),"batch_") && endswith(f,".jld2"),
        readdir(outdir;join=true)))
    isempty(files) && error("No batch files found in $outdir")
    persistent=DataFrames.DataFrame(simulation=Int[],
        has_persistent_outlier=Bool[],n_persistent_outliers=Int[],
        first_crossing_step=Union{Missing,Int}[])
    pairwise=DataFrames.DataFrame(simulation=Int[],step=Int[],
        mean_pairwise_distance=Float64[],sd_pairwise_distance=Float64[])
    seen=Set{Int}()
    for (fidx,file) in enumerate(files)
        d=JLD2.load(file)
        @assert Float64(d["threshold"])==Float64(threshold) "Threshold mismatch in $file"
        ids=Int.(d["simulation_ids"])
        for id in ids
            id in seen && error("Duplicate simulation ID $id")
            push!(seen,id)
        end
        crossed=d["crossed"]
        crossing_step=d["crossing_step"]
        D=d["pairwise_distances"]
        for (k,id) in enumerate(ids)
            n_cross=count(@view crossed[1,k,:])
            earliest=n_cross==0 ? missing : minimum(crossing_step[1,k,a] for a in 1:20 if crossed[1,k,a])
            push!(persistent,(id,n_cross>0,n_cross,earliest))
            for (t,step) in enumerate(d["distance_steps"])
                vals=Float64.(@view D[k,t,:])
                push!(pairwise,(id,Int(step),Statistics.mean(vals),Statistics.std(vals)))
            end
        end
        println("Analyzed file $fidx / $(length(files))")
    end
    sort!(persistent,:simulation)
    sort!(pairwise,[:simulation,:step])
    summary=DataFrames.DataFrame(n_runs=[DataFrames.nrow(persistent)],
        n_runs_with_persistent_outlier=[sum(persistent.has_persistent_outlier)],
        percentage_runs_with_persistent_outlier=[100*Statistics.mean(persistent.has_persistent_outlier)],
        mean_n_persistent_outliers=[Statistics.mean(persistent.n_persistent_outliers)])
    pairwise_summary=DataFrames.combine(DataFrames.groupby(pairwise,:step),
        DataFrames.nrow=>:n_runs,
        :mean_pairwise_distance=>Statistics.mean=>:mean_distance,
        :mean_pairwise_distance=>Statistics.std=>:sd_between_runs)
    println("\nPERSISTENT OUTLIERS")
    show(stdout,summary;allrows=true,allcols=true,truncate=0)
    println("\n\nPAIRWISE DISTANCES")
    show(stdout,pairwise_summary;allrows=true,allcols=true,truncate=0)
    println()
    return (persistent_summary=summary,persistent_runs=persistent,
        pairwise_simulation_summary=pairwise,pairwise_step_summary=pairwise_summary)
end

# run_model_3_1_raw_parallel(1000;outdir=joinpath("sweep_beta_logs","MODEL_3_1_PARALLEL"))

# analysis_3_1=analyze_model_3_1_parallel(joinpath("sweep_beta_logs","MODEL_3_1_PARALLEL"))


# Null model 4 - פיזור במרחב + במקום שיחה יש שיחות עצמיות
function step_random_relocation_group_self_talk!(
    world::World;
    talk_duration::Int=5,
    refractory_duration::Int=10,
    self_talk_threshold::Int=10,
    L::Int=10,
    eta::Float32=0.5f0,
    beta_for_consent::Real=10.0,
    gamma::Union{Nothing,Real}=nothing,
    beta::Union{Nothing,Real}=nothing,
    delta::Union{Nothing,Real}=nothing,
    p0::Union{Nothing,Real}=nothing,
    pmin::Real=0.05,
    record_distances::Bool=true,
    record_every::Int=1,
    social_impact::Float64=1.0,
    join_rule::Symbol=:group_any,
    social_learning_prob=ones(Float32, world.N))

    # --- Update parameters if provided ---
    if gamma !== nothing world.γ = Float32(gamma) end
    if beta !== nothing world.β = Float32(beta) end
    if delta !== nothing world.δ = Float32(delta) end
    if p0 !== nothing world.p0 = Float32(p0) end
    if beta_for_consent !== nothing world.beta_for_consent = Float32(beta_for_consent) end

    world.t += 1

    # ============================================================
    # 1) Group Conversation Phase
    # ============================================================

    group_ids = unique(world.talking_group)
    talked_groups = Vector{Vector{Int}}()

    for gid in group_ids
        gid == 0 && continue

        # Identify current group members
        members = [
            i for i in 1:world.N
            if world.talking_group[i] == gid
        ]

        Lm = length(members)

        # --------------------------------------------------------
        # Handle fragmented groups (less than 2 agents)
        # --------------------------------------------------------

        if Lm < 2
            if Lm == 1

                if world.talk_left[members[1]] > 0
                    mark_abandonment!(
                        world,
                        members[1]
                    )
                end

                end_conversation_for_agent!(
                    world,
                    members[1],
                    refractory_duration
                )

                # Random relocation after conversation ends
                relocate_agent_randomly!(
                    world,
                    members[1]
                )
            end

            continue
        end

        # --------------------------------------------------------
        # Check for silence
        # --------------------------------------------------------

        all_silent = true
        nspeakers = 0

        @inbounds for m in members

            if !world.silent[m]

                nspeakers += 1

                if nspeakers >= 2
                    all_silent = false
                    break
                end
            end
        end

        if all_silent

            @inbounds for m in members

                for other in members
                    if m != other

                        push!(
                            world.agent_seen_partners[m],
                            other
                        )
                    end
                end

                if world.talk_left[m] > 0

                    mark_abandonment!(
                        world,
                        m
                    )
                end

                end_conversation_for_agent!(
                    world,
                    m,
                    refractory_duration
                )

                # Random relocation after leaving conversation
                relocate_agent_randomly!(
                    world,
                    m
                )
            end

            continue
        end

        # --------------------------------------------------------
        # Social group exists normally
        # --------------------------------------------------------

        push!(
            talked_groups,
            members
        )

        speakers = Int[]

        @inbounds for m in members

            if !world.silent[m]

                push!(
                    speakers,
                    m
                )
            end
        end

        # Social interaction is still logged normally
        log_conversation!(
            world;
            gid=gid,
            members=copy(members),
            speakers=copy(speakers)
        )

        # ========================================================
        # NEW SEMANTIC MECHANISM
        #
        # There is NO semantic interaction between agents.
        #
        # Every member who would have participated in the social
        # conversation instead performs a full self-conversation.
        #
        # Each agent therefore receives L semantic updates,
        # but all information comes exclusively from its own
        # semantic network.
        # ========================================================

        for agent in members

            self_conversation!(
                agent,
                world,
                L
            )
        end

        # Social conversation duration remains unchanged
        for i in members
            world.talk_left[i] -= 1
        end
    end

    # ============================================================
    # End Conversation & Refractory Check
    # ============================================================

    for i in 1:world.N

        if world.talking_group[i] != 0 &&
           world.talk_left[i] <= 0

            end_conversation_for_agent!(
                world,
                i,
                refractory_duration
            )

            # Random relocation after conversation ends
            relocate_agent_randomly!(
                world,
                i
            )
        end
    end

    # ============================================================
    # 2) Ordinary Self-conversation Phase
    #
    # This remains EXACTLY as in the existing model.
    # Agents currently in a social group do not enter this phase.
    # ============================================================

    for i in 1:world.N

        if world.talking_group[i] == 0

            if world.self_talk_left[i] > 0

                self_conversation!(
                    i,
                    world,
                    L
                )

                world.self_talk_count[i] += 1
                world.self_talk_left[i] -= 1

            else

                world.time_since_last_talk[i] += 1

                if world.time_since_last_talk[i] >= self_talk_threshold

                    world.self_talk_left[i] = 3

                    self_conversation!(
                        i,
                        world,
                        L
                    )

                    world.self_talk_count[i] += 1
                    world.self_talk_left[i] -= 1

                    world.time_since_last_talk[i] = 0
                end
            end

        else

            world.time_since_last_talk[i] = 0
        end
    end

    # ============================================================
    # 3) Semantic Updates (Perception)
    #
    # Social perception remains based on which agents were
    # socially grouped, even though their semantic networks
    # did not interact.
    # ============================================================

    if eta != 0.0f0

        for group in talked_groups

            update_perceived_group!(
                world,
                group;
                eta=eta
            )
        end
    end

    if record_distances &&
       (world.t % record_every == 0)

        world.current_distances .=
            Float32.(
                differences(
                    world.agents
                )
            )

        push!(
            world.distances_history,
            copy(world.current_distances)
        )

        push!(
            world.perceived_distance_history,
            copy(world.perceived_distance)
        )
    end

    # ============================================================
    # 4) Movement and Adjacency Logging
    # ============================================================

    move_agents!(
        world
    )

    update_adjacency!(
        world.adjacency_count,
        world
    )

    # ============================================================
    # 5) Social Interaction Initiation
    # ============================================================

    form_conversations!(
        world;
        talk_duration=talk_duration,
        pmin=pmin,
        p0=p0,
        join_rule=join_rule
    )

    update_talk_episodes!(
        world
    )

    # ============================================================
    # 6) Refractory Period Update
    # ============================================================

    for i in 1:world.N

        if !isempty(
            world.refr_partners[i]
        )

            tick_refractory!(
                world.refr_partners,
                world.refr_left,
                i
            )
        end
    end

    # ============================================================
    # 7) Longitudinal Logging
    # ============================================================

    push!(
        world.unique_partners_steps,
        world.t
    )

    current_unique_counts = [
        count(
            >(0),
            view(
                world.talk_episode_count,
                i,
                :
            )
        )
        for i in 1:world.N
    ]

    push!(
        world.unique_partners_history,
        current_unique_counts
    )

    return nothing
end
function run_random_relocation_group_self_talk_raw(
    n_sim::Int;
    save_path::String = joinpath(
        "sweep_beta_logs",
        "RANDOM_RELOCATION_GROUP_SELF_TALK_RAW.jld2"
    ),
    threshold::Real = 2.5,
    progress_every::Int = 10)

    # ============================================================
    # SETTINGS
    # ============================================================

    N = 20
    n = 300
    m = 4

    W = 30
    H = 30

    change = 0.7

    steps = 20_000
    record_every = 100
    reset_every = 100

    talk_duration = 10
    refractory_duration = 10
    self_talk_threshold = 10

    L = 25
    eta = 0.2f0

    gamma = 0.0
    beta = 1.0
    delta = 1.0
    p0 = 0.5
    pmin = 0.05

    beta_for_consent = 0.0

    social_impact = 1.0
    join_rule = :group_any

    abandonment_threshold = 10_000_000

    model_names =
        ["random_relocation_group_self_talk"]

    n_models = 1

    steps_axis =
        collect(0:record_every:steps)

    n_timepoints =
        length(steps_axis)

    # ============================================================
    # PAIR MAP
    # ============================================================

    pair_map =
        Tuple{Int,Int}[]

    for i in 1:(N - 1)
        for j in (i + 1):N
            push!(pair_map, (i, j))
        end
    end

    n_pairs =
        length(pair_map)

    @assert n_pairs == 190

    # ============================================================
    # PREALLOCATE
    # ============================================================

    # Standardized mean distance from other agents
    Z_all =
        fill(
            Float32(NaN),
            n_models,
            n_sim,
            n_timepoints,
            N
        )

    # Raw mean distance from other agents
    mean_distances_all =
        fill(
            Float32(NaN),
            n_models,
            n_sim,
            n_timepoints,
            N
        )

    # Cumulative distinct pairwise conversation episodes
    pair_episode_counts =
        zeros(
            Int32,
            n_models,
            n_sim,
            n_timepoints,
            n_pairs
        )

    # Persistent crossing information
    crossed =
        falses(
            n_models,
            n_sim,
            N
        )

    crossing_step =
        fill(
            -1,
            n_models,
            n_sim,
            N
        )

    n_crossing_agents =
        zeros(
            Int,
            n_models,
            n_sim
        )

    any_crossing =
        falses(
            n_models,
            n_sim
        )

    # ============================================================
    # RECORD STATE
    # ============================================================

    function record_state!(
        world::World,
        sim_idx::Int,
        time_idx::Int
    )

        distance_result =
            mean_network_distance_zscores(
                world.agents
            )

        # --------------------------------------------------------
        # Raw mean semantic distance
        # --------------------------------------------------------

        mean_distances_all[
            1,
            sim_idx,
            time_idx,
            :
        ] .=
            Float32.(
                distance_result.mean_distances
            )

        # --------------------------------------------------------
        # Standardized semantic distance
        # --------------------------------------------------------

        Z_all[
            1,
            sim_idx,
            time_idx,
            :
        ] .=
            Float32.(
                distance_result.z
            )

        # --------------------------------------------------------
        # Cumulative DISTINCT pairwise social episodes
        # --------------------------------------------------------

        @inbounds for p in 1:n_pairs

            i, j =
                pair_map[p]

            pair_episode_counts[
                1,
                sim_idx,
                time_idx,
                p
            ] =
                Int32(
                    world.talk_episode_count[i, j]
                )
        end

        return nothing
    end

    # ============================================================
    # PERSISTENT CROSSING
    # ============================================================

    function find_persistent_crossings!(
        sim_idx::Int
    )

        n_crossed = 0

        @inbounds for agent in 1:N

            ztraj =
                @view Z_all[
                    1,
                    sim_idx,
                    :,
                    agent
                ]

            first_crossing_idx = 0

            for t_idx in 1:n_timepoints

                if ztraj[t_idx] >= threshold

                    remains_above = true

                    for future_idx in t_idx:n_timepoints

                        if ztraj[future_idx] < threshold
                            remains_above = false
                            break
                        end
                    end

                    if remains_above
                        first_crossing_idx = t_idx
                        break
                    end
                end
            end

            if first_crossing_idx > 0

                crossed[
                    1,
                    sim_idx,
                    agent
                ] = true

                crossing_step[
                    1,
                    sim_idx,
                    agent
                ] =
                    steps_axis[first_crossing_idx]

                n_crossed += 1
            end
        end

        n_crossing_agents[
            1,
            sim_idx
        ] =
            n_crossed

        any_crossing[
            1,
            sim_idx
        ] =
            n_crossed > 0

        return nothing
    end

    # ============================================================
    # RUN ONE MODEL
    # ============================================================

    function run_model!(
        world::World,
        sim_idx::Int
    )

        # --------------------------------------------------------
        # t = 0
        # --------------------------------------------------------

        record_state!(
            world,
            sim_idx,
            1
        )

        time_idx = 1

        # --------------------------------------------------------
        # Simulation
        # --------------------------------------------------------

        for step_i in 1:steps

            # Same ordering as previous controls:
            # reset BEFORE the step at multiples of 100.
            if step_i % reset_every == 0

                reset_positions_and_interactions!(
                    world
                )
            end

            step_random_relocation_group_self_talk!(
                world;
                talk_duration =
                    talk_duration,

                refractory_duration =
                    refractory_duration,

                self_talk_threshold =
                    self_talk_threshold,

                L =
                    L,

                eta =
                    eta,

                beta_for_consent =
                    beta_for_consent,

                gamma =
                    gamma,

                beta =
                    beta,

                delta =
                    delta,

                p0 =
                    p0,

                pmin =
                    pmin,

                record_distances =
                    true,

                record_every =
                    record_every,

                social_impact =
                    social_impact,

                join_rule =
                    join_rule
            )

            # ----------------------------------------------------
            # Save every 100 steps
            # ----------------------------------------------------

            if step_i % record_every == 0

                time_idx += 1

                record_state!(
                    world,
                    sim_idx,
                    time_idx
                )
            end
        end

        @assert time_idx == n_timepoints

        # --------------------------------------------------------
        # Persistent semantic crossing
        # --------------------------------------------------------

        find_persistent_crossings!(
            sim_idx
        )

        return nothing
    end

    # ============================================================
    # MAIN LOOP
    # ============================================================

    println()
    println("="^82)
    println("RANDOM RELOCATION — GROUP SELF-TALK CONTROL")
    println("="^82)
    println("Simulations:                 ", n_sim)
    println("Steps per run:               ", steps)
    println("Semantic threshold:          ", threshold)
    println("Sampling interval:           ", record_every)
    println("Semantic homophily β:        ", beta_for_consent)
    println("Random relocation:           YES")
    println("Real agent-agent learning:   NO")
    println("Semantic interaction:        NONE")
    println("Group members self-talk:     YES")
    println("Raw distances saved:         YES")
    println("Random seed fixed:           NO")
    println("="^82)
    println()

    for sim_idx in 1:n_sim

        # --------------------------------------------------------
        # Fresh initial world
        # --------------------------------------------------------

        world =
            init_world(
                N,
                W,
                H,
                n,
                m,
                change;
                gamma =
                    gamma,

                beta =
                    beta,

                delta =
                    delta,

                p0 =
                    p0,

                beta_for_consent =
                    beta_for_consent,

                abandonment_threshold =
                    abandonment_threshold,

                outliers_count =
                    0,

                outlier_change =
                    nothing
            )

        # --------------------------------------------------------
        # Run
        # --------------------------------------------------------

        run_model!(
            world,
            sim_idx
        )

        world = nothing

        # --------------------------------------------------------
        # Progress
        # --------------------------------------------------------

        if sim_idx % progress_every == 0 ||
           sim_idx == n_sim

            crossing_n =
                count(
                    @view any_crossing[
                        1,
                        1:sim_idx
                    ]
                )

            println(
                "  ",
                sim_idx,
                "/",
                n_sim,
                " runs | crossing runs=",
                crossing_n
            )

            GC.gc()
        end
    end

    # ============================================================
    # RUN SUMMARY
    # ============================================================

    run_summary =
        DataFrames.DataFrame(
            model =
                fill(
                    model_names[1],
                    n_sim
                ),

            simulation =
                collect(1:n_sim),

            any_crossing =
                vec(
                    any_crossing[1, :]
                ),

            n_crossing_agents =
                vec(
                    n_crossing_agents[1, :]
                )
        )

    # ============================================================
    # AGENT-LEVEL CROSSING TABLE
    # ============================================================

    crossing_model =
        String[]

    crossing_simulation =
        Int[]

    crossing_agent =
        Int[]

    crossing_crossed =
        Bool[]

    crossing_crossing_step =
        Union{Missing,Int}[]

    for sim_idx in 1:n_sim
        for agent in 1:N

            did_cross =
                crossed[
                    1,
                    sim_idx,
                    agent
                ]

            push!(
                crossing_model,
                model_names[1]
            )

            push!(
                crossing_simulation,
                sim_idx
            )

            push!(
                crossing_agent,
                agent
            )

            push!(
                crossing_crossed,
                did_cross
            )

            if did_cross

                push!(
                    crossing_crossing_step,
                    crossing_step[
                        1,
                        sim_idx,
                        agent
                    ]
                )

            else

                push!(
                    crossing_crossing_step,
                    missing
                )
            end
        end
    end

    crossing_results =
        DataFrames.DataFrame(
            model =
                crossing_model,

            simulation =
                crossing_simulation,

            agent =
                crossing_agent,

            crossed =
                crossing_crossed,

            crossing_step =
                crossing_crossing_step
        )

    # ============================================================
    # OVERALL SUMMARY
    # ============================================================

    overall_summary =
        DataFrames.combine(
            DataFrames.groupby(
                run_summary,
                :model
            ),

            DataFrames.nrow =>
                :n_runs,

            :any_crossing =>
                sum =>
                :n_runs_with_crossing,

            :any_crossing =>
                (
                    x ->
                        100.0 *
                        Statistics.mean(x)
                ) =>
                :percentage_runs_with_crossing,

            :n_crossing_agents =>
                Statistics.mean =>
                :mean_n_crossing_agents
        )

    # ============================================================
    # SAVE
    # ============================================================

    println()
    println("Saving results...")

    mkpath(
        dirname(save_path)
    )

    JLD2.jldsave(
        save_path;

        # --------------------------------------------------------
        # Semantic trajectories
        # --------------------------------------------------------

        Z_all =
            Z_all,

        mean_distances_all =
            mean_distances_all,

        # --------------------------------------------------------
        # Social trajectories
        # --------------------------------------------------------

        pair_episode_counts =
            pair_episode_counts,

        # --------------------------------------------------------
        # Persistent crossings
        # --------------------------------------------------------

        crossed =
            crossed,

        crossing_step =
            crossing_step,

        n_crossing_agents =
            n_crossing_agents,

        any_crossing =
            any_crossing,

        # --------------------------------------------------------
        # Tables
        # --------------------------------------------------------

        run_summary =
            run_summary,

        crossing_results =
            crossing_results,

        overall_summary =
            overall_summary,

        # --------------------------------------------------------
        # Axes / metadata
        # --------------------------------------------------------

        model_names =
            model_names,

        steps_axis =
            steps_axis,

        pair_map =
            pair_map,

        threshold =
            Float64(threshold),

        N =
            N,

        n_words =
            n,

        m =
            m,

        change =
            change,

        n_sim =
            n_sim,

        steps =
            steps,

        record_every =
            record_every,

        reset_every =
            reset_every,

        beta_for_consent =
            beta_for_consent,

        movement_beta =
            beta,

        talk_duration =
            talk_duration,

        refractory_duration =
            refractory_duration,

        self_talk_threshold =
            self_talk_threshold,

        L =
            L,

        eta =
            eta,

        gamma =
            gamma,

        delta =
            delta,

        p0 =
            p0,

        pmin =
            pmin,

        social_impact =
            social_impact,

        join_rule =
            String(join_rule),

        # --------------------------------------------------------
        # Model description
        # --------------------------------------------------------

        random_relocation =
            true,

        real_agent_agent_learning =
            false,

        real_agent_agent_semantic_interaction =
            false,

        group_conversation_replaced_by_self_talk =
            true,

        raw_mean_distances_saved =
            true,

        fixed_random_seed =
            false
    )

    # ============================================================
    # FINAL OUTPUT
    # ============================================================

    println()
    println("="^90)
    println("SIMULATION COMPLETE")
    println("="^90)

    show(
        stdout,
        overall_summary;
        allrows=true,
        allcols=true,
        truncate=0
    )

    println()
    println()
    println("Saved to: ", save_path)

    # ============================================================
    # RETURN
    # ============================================================

    return (
        overall_summary =
            overall_summary,

        run_summary =
            run_summary,

        crossing_results =
            crossing_results,

        Z_all =
            Z_all,

        mean_distances_all =
            mean_distances_all,

        pair_episode_counts =
            pair_episode_counts,

        crossed =
            crossed,

        crossing_step =
            crossing_step,

        n_crossing_agents =
            n_crossing_agents,

        any_crossing =
            any_crossing,

        steps_axis =
            steps_axis,

        pair_map =
            pair_map,

        model_names =
            model_names,

        save_path =
            save_path
    )
end
# group_self_talk_results =
#     run_random_relocation_group_self_talk_raw(
#         1000;
#         save_path = joinpath(
#             "sweep_beta_logs",
#             "RANDOM_RELOCATION_GROUP_SELF_TALK_RAW_100.jld2"
#         ),
#         threshold = 2.5,
#         progress_every = 10
# )
function analyze_group_self_talk_control(
    path::String;
    threshold::Real = 2.5)

    # ============================================================
    # LOAD
    # ============================================================

    d = JLD2.load(path)

    Z_all =
        d["Z_all"]

    mean_distances_all =
        d["mean_distances_all"]

    pair_episode_counts =
        d["pair_episode_counts"]

    steps_axis =
        Int.(d["steps_axis"])

    pair_map =
        Tuple{Int,Int}.(d["pair_map"])

    model_names =
        String.(d["model_names"])

    N =
        Int(d["N"])

    n_sim =
        Int(d["n_sim"])

    n_models =
        length(model_names)

    n_timepoints =
        length(steps_axis)

    n_pairs =
        length(pair_map)

    @assert size(Z_all) ==
        (
            n_models,
            n_sim,
            n_timepoints,
            N
        )

    @assert size(mean_distances_all) ==
        (
            n_models,
            n_sim,
            n_timepoints,
            N
        )

    @assert size(pair_episode_counts) ==
        (
            n_models,
            n_sim,
            n_timepoints,
            n_pairs
        )

    # ============================================================
    # 1. PERSISTENT SEMANTIC OUTLIERS
    # ============================================================

    persistent_rows =
        DataFrames.DataFrame(
            model = String[],
            simulation = Int[],
            has_persistent_outlier = Bool[],
            n_persistent_outliers = Int[],
            first_crossing_step = Union{Missing,Int}[]
        )

    for model_idx in 1:n_models
        for sim_idx in 1:n_sim

            n_outliers = 0
            first_step = typemax(Int)

            for agent in 1:N

                ztraj =
                    @view Z_all[
                        model_idx,
                        sim_idx,
                        :,
                        agent
                    ]

                crossing_idx = 0

                for t_idx in 1:n_timepoints

                    if ztraj[t_idx] >= threshold

                        persistent = true

                        for future_idx in t_idx:n_timepoints

                            if ztraj[future_idx] < threshold
                                persistent = false
                                break
                            end
                        end

                        if persistent
                            crossing_idx = t_idx
                            break
                        end
                    end
                end

                if crossing_idx > 0

                    n_outliers += 1

                    step =
                        steps_axis[
                            crossing_idx
                        ]

                    first_step =
                        min(
                            first_step,
                            step
                        )
                end
            end

            has_outlier =
                n_outliers > 0

            push!(
                persistent_rows,
                (
                    model_names[model_idx],
                    sim_idx,
                    has_outlier,
                    n_outliers,
                    has_outlier ?
                        first_step :
                        missing
                )
            )
        end
    end

    persistent_summary =
        DataFrames.combine(
            DataFrames.groupby(
                persistent_rows,
                :model
            ),

            DataFrames.nrow =>
                :n_runs,

            :has_persistent_outlier =>
                sum =>
                :n_runs_with_persistent_outlier,

            :has_persistent_outlier =>
                (
                    x ->
                        100.0 *
                        Statistics.mean(x)
                ) =>
                :percentage_runs_with_persistent_outlier,

            :n_persistent_outliers =>
                Statistics.mean =>
                :mean_n_persistent_outliers
        )

    # ============================================================
    # 2. PARTNER REPETITION BY 100-STEP WINDOW
    #
    # R = 1 - U/M
    #
    # M = total pairwise conversation episodes in the window
    # U = number of unique pairs used in the window
    #
    # Random-pair null:
    #
    # q1 = ((P-1)/P)^M
    # E[U] = P(1-q1)
    # E[R] = 1-E[U]/M
    # ============================================================

    social_window_results =
        DataFrames.DataFrame(
            model = String[],
            simulation = Int[],
            window_index = Int[],
            window_start = Int[],
            window_end = Int[],
            M = Int[],
            U = Int[],
            observed_R = Float64[],
            expected_R = Float64[],
            excess_R = Float64[],
            sd_R = Float64[],
            z_R = Float64[]
        )

    P =
        n_pairs

    for model_idx in 1:n_models
        for sim_idx in 1:n_sim

            for window_idx in 1:(n_timepoints - 1)

                start_idx =
                    window_idx

                end_idx =
                    window_idx + 1

                counts =
                    Int.(
                        @view(
                            pair_episode_counts[
                                model_idx,
                                sim_idx,
                                end_idx,
                                :
                            ]
                        )
                    ) .-
                    Int.(
                        @view(
                            pair_episode_counts[
                                model_idx,
                                sim_idx,
                                start_idx,
                                :
                            ]
                        )
                    )

                M =
                    sum(counts)

                U =
                    count(
                        >(0),
                        counts
                    )

                if M > 0

                    # --------------------------------------------
                    # Observed repetition
                    # --------------------------------------------

                    observed_R =
                        1.0 -
                        U / M

                    # --------------------------------------------
                    # Random-pair null
                    # --------------------------------------------

                    q1 =
                        ((P - 1) / P)^M

                    expected_U =
                        P *
                        (1.0 - q1)

                    expected_R =
                        1.0 -
                        expected_U / M

                    excess_R =
                        observed_R -
                        expected_R

                    # --------------------------------------------
                    # Exact variance under random-pair null
                    # --------------------------------------------

                    p_occ =
                        1.0 - q1

                    q2 =
                        if P >= 2
                            ((P - 2) / P)^M
                        else
                            0.0
                        end

                    p2 =
                        1.0 -
                        2.0 * q1 +
                        q2

                    var_U =
                        P *
                        p_occ *
                        (1.0 - p_occ) +
                        P *
                        (P - 1) *
                        (
                            p2 -
                            p_occ^2
                        )

                    var_R =
                        max(
                            var_U,
                            0.0
                        ) /
                        M^2

                    sd_R =
                        sqrt(
                            var_R
                        )

                    z_R =
                        sd_R > 0 ?
                        excess_R / sd_R :
                        NaN

                else

                    observed_R = NaN
                    expected_R = NaN
                    excess_R = NaN
                    sd_R = NaN
                    z_R = NaN
                end

                push!(
                    social_window_results,
                    (
                        model_names[model_idx],
                        sim_idx,
                        window_idx,
                        steps_axis[start_idx],
                        steps_axis[end_idx],
                        M,
                        U,
                        observed_R,
                        expected_R,
                        excess_R,
                        sd_R,
                        z_R
                    )
                )
            end
        end
    end

    # ============================================================
    # 3. AVERAGE ACROSS WINDOWS WITHIN EACH SIMULATION FIRST
    # ============================================================

    function finite_mean(x)

        vals =
            Float64[
                Float64(v)
                for v in x
                if !ismissing(v) &&
                   isfinite(Float64(v))
            ]

        return isempty(vals) ?
            NaN :
            Statistics.mean(vals)
    end

    social_simulation_summary =
        DataFrames.combine(
            DataFrames.groupby(
                social_window_results,
                [:model, :simulation]
            ),

            :observed_R =>
                finite_mean =>
                :mean_observed_R,

            :expected_R =>
                finite_mean =>
                :mean_expected_R,

            :excess_R =>
                finite_mean =>
                :mean_excess_R,

            :z_R =>
                finite_mean =>
                :mean_z_R,

            :M =>
                Statistics.mean =>
                :mean_episodes_per_window,

            :U =>
                Statistics.mean =>
                :mean_unique_pairs_per_window
        )

    # ============================================================
    # 4. SUMMARY ACROSS SIMULATIONS
    # ============================================================

    social_model_summary =
        DataFrames.DataFrame(
            model = String[],
            n_runs = Int[],
            mean_observed_R = Float64[],
            mean_expected_R = Float64[],
            mean_excess_R = Float64[],
            sd_excess_R = Float64[],
            median_excess_R = Float64[],
            mean_excess_R_ci_low = Float64[],
            mean_excess_R_ci_high = Float64[],
            mean_z_R = Float64[]
        )

    for g in DataFrames.groupby(
        social_simulation_summary,
        :model
    )

        model =
            String(
                first(g.model)
            )

        observed =
            Float64[
                x
                for x in g.mean_observed_R
                if isfinite(x)
            ]

        expected =
            Float64[
                x
                for x in g.mean_expected_R
                if isfinite(x)
            ]

        excess =
            Float64[
                x
                for x in g.mean_excess_R
                if isfinite(x)
            ]

        zvals =
            Float64[
                x
                for x in g.mean_z_R
                if isfinite(x)
            ]

        n_valid =
            length(excess)

        mean_excess =
            n_valid > 0 ?
            Statistics.mean(excess) :
            NaN

        sd_excess =
            n_valid > 1 ?
            Statistics.std(excess) :
            NaN

        se_excess =
            n_valid > 1 ?
            sd_excess / sqrt(n_valid) :
            NaN

        ci_low =
            n_valid > 1 ?
            mean_excess -
            1.96 * se_excess :
            NaN

        ci_high =
            n_valid > 1 ?
            mean_excess +
            1.96 * se_excess :
            NaN

        push!(
            social_model_summary,
            (
                model,
                n_valid,

                isempty(observed) ?
                    NaN :
                    Statistics.mean(observed),

                isempty(expected) ?
                    NaN :
                    Statistics.mean(expected),

                mean_excess,

                sd_excess,

                isempty(excess) ?
                    NaN :
                    Statistics.median(excess),

                ci_low,

                ci_high,

                isempty(zvals) ?
                    NaN :
                    Statistics.mean(zvals)
            )
        )
    end

    # ============================================================
    # 5. CLEAR PRINTED SUMMARY
    # ============================================================

    println()
    println("="^78)
    println("GROUP SELF-TALK CONTROL — RESULTS")
    println("="^78)

    # ------------------------------------------------------------
    # Semantic outliers
    # ------------------------------------------------------------

    println()
    println("SEMANTIC OUTLIERS")
    println("-"^78)

    for row in eachrow(persistent_summary)

        println("Model:                         ", row.model)
        println("Runs:                          ", row.n_runs)
        println(
            "Runs with persistent outlier:  ",
            row.n_runs_with_persistent_outlier
        )

        println(
            "% with persistent outlier:     ",
            round(
                row.percentage_runs_with_persistent_outlier;
                digits=2
            ),
            "%"
        )

        println(
            "Mean # persistent outliers:     ",
            round(
                row.mean_n_persistent_outliers;
                digits=3
            )
        )
    end

    # ------------------------------------------------------------
    # Social repetition
    # ------------------------------------------------------------

    println()
    println("SOCIAL PARTNER REPETITION")
    println("-"^78)

    for row in eachrow(social_model_summary)

        println(
            "Observed R:                     ",
            round(
                row.mean_observed_R;
                digits=4
            )
        )

        println(
            "Expected R (random null):       ",
            round(
                row.mean_expected_R;
                digits=4
            )
        )

        println(
            "Excess R:                       ",
            round(
                row.mean_excess_R;
                digits=4
            )
        )

        println(
            "95% CI for excess R:            [",
            round(
                row.mean_excess_R_ci_low;
                digits=4
            ),
            ", ",
            round(
                row.mean_excess_R_ci_high;
                digits=4
            ),
            "]"
        )

        println(
            "Mean repetition Z:              ",
            round(
                row.mean_z_R;
                digits=3
            )
        )
    end

    println()
    println("="^78)

    # ============================================================
    # RETURN
    # ============================================================

    return (
        persistent_summary =
            persistent_summary,

        persistent_runs =
            persistent_rows,

        social_window_results =
            social_window_results,

        social_simulation_summary =
            social_simulation_summary,

        social_model_summary =
            social_model_summary,

        mean_distances_all =
            mean_distances_all
    )
end
# group_self_talk_analysis =
#     analyze_group_self_talk_control(
#         joinpath(
#             "sweep_beta_logs",
#             "RANDOM_RELOCATION_GROUP_SELF_TALK_RAW_1000.jld2"
#         );
#         threshold = 2.5
# )

function summarize_initial_vs_persistent_outliers(
    path::String;
    threshold::Real = 2.5)

    # ============================================================
    # LOAD
    # ============================================================

    d = JLD2.load(path)

    Z_all = d["Z_all"]
    any_crossing = d["any_crossing"]
    crossed = d["crossed"]
    steps_axis = Int.(d["steps_axis"])

    n_models, n_sim, n_timepoints, N = size(Z_all)

    @assert n_models == 1
    @assert size(any_crossing) == (n_models, n_sim)
    @assert size(crossed) == (n_models, n_sim, N)
    @assert steps_axis[1] == 0


    # ============================================================
    # RUN-LEVEL AND AGENT-LEVEL INDICATORS
    # ============================================================

    initial_outlier_run = falses(n_sim)
    persistent_outlier_run = falses(n_sim)

    # For each simulation × agent:
    initial_outlier_agent =
        falses(n_sim, N)

    persistent_outlier_agent =
        falses(n_sim, N)


    for sim_idx in 1:n_sim

        for agent in 1:N

            # ----------------------------------------------------
            # Initial outlier:
            # agent is already >= threshold at step 0
            # ----------------------------------------------------

            initial_outlier_agent[
                sim_idx,
                agent
            ] =
                Z_all[
                    1,
                    sim_idx,
                    1,
                    agent
                ] >= threshold


            # ----------------------------------------------------
            # Persistent outlier:
            # same agent satisfies persistent crossing criterion
            # ----------------------------------------------------

            persistent_outlier_agent[
                sim_idx,
                agent
            ] =
                crossed[
                    1,
                    sim_idx,
                    agent
                ]
        end


        # --------------------------------------------------------
        # Run-level indicators
        # --------------------------------------------------------

        initial_outlier_run[sim_idx] =
            any(
                @view initial_outlier_agent[
                    sim_idx,
                    :
                ]
            )

        persistent_outlier_run[sim_idx] =
            any_crossing[
                1,
                sim_idx
            ]
    end


    # ============================================================
    # RUN-LEVEL COUNTS
    # ============================================================

    n_initial_runs =
        count(initial_outlier_run)

    n_persistent_runs =
        count(persistent_outlier_run)


    run_overlap =
        initial_outlier_run .&
        persistent_outlier_run

    n_run_overlap =
        count(run_overlap)


    n_initial_only_runs =
        count(
            initial_outlier_run .&
            .!persistent_outlier_run
        )

    n_persistent_only_runs =
        count(
            persistent_outlier_run .&
            .!initial_outlier_run
        )

    n_neither_runs =
        count(
            .!initial_outlier_run .&
            .!persistent_outlier_run
        )


    # ============================================================
    # SAME-AGENT OVERLAP
    # ============================================================

    same_agent_overlap =
        initial_outlier_agent .&
        persistent_outlier_agent


    # A run counts here if at least one agent was BOTH:
    # 1. >= threshold initially
    # 2. a persistent outlier later

    same_agent_overlap_run =
        falses(n_sim)

    for sim_idx in 1:n_sim

        same_agent_overlap_run[sim_idx] =
            any(
                @view same_agent_overlap[
                    sim_idx,
                    :
                ]
            )
    end


    n_same_agent_overlap_runs =
        count(same_agent_overlap_run)


    # ============================================================
    # CONDITIONAL RUN-LEVEL PERCENTAGES
    # ============================================================

    # ------------------------------------------------------------
    # RUN overlap:
    # Of persistent-outlier runs, how many had ANY initial outlier?
    # ------------------------------------------------------------

    pct_persistent_runs_with_initial =
        n_persistent_runs > 0 ?
        100.0 *
        n_run_overlap /
        n_persistent_runs :
        NaN


    # ------------------------------------------------------------
    # RUN overlap:
    # Of initial-outlier runs, how many later had ANY persistent
    # outlier?
    # ------------------------------------------------------------

    pct_initial_runs_with_persistent =
        n_initial_runs > 0 ?
        100.0 *
        n_run_overlap /
        n_initial_runs :
        NaN


    # ============================================================
    # CONDITIONAL SAME-AGENT PERCENTAGES
    # ============================================================

    # ------------------------------------------------------------
    # Of persistent-outlier runs:
    # in how many was at least one of the persistent agents
    # already >= threshold initially?
    # ------------------------------------------------------------

    pct_persistent_runs_same_agent_initial =
        n_persistent_runs > 0 ?
        100.0 *
        n_same_agent_overlap_runs /
        n_persistent_runs :
        NaN


    # ------------------------------------------------------------
    # Of initial-outlier runs:
    # in how many did at least one of those initially-outlying
    # agents itself become persistent?
    # ------------------------------------------------------------

    pct_initial_runs_same_agent_persistent =
        n_initial_runs > 0 ?
        100.0 *
        n_same_agent_overlap_runs /
        n_initial_runs :
        NaN


    # ============================================================
    # AGENT COUNTS
    # ============================================================

    n_initial_agents =
        count(initial_outlier_agent)

    n_persistent_agents =
        count(persistent_outlier_agent)

    n_same_agents =
        count(same_agent_overlap)


    pct_persistent_agents_already_initial =
        n_persistent_agents > 0 ?
        100.0 *
        n_same_agents /
        n_persistent_agents :
        NaN


    pct_initial_agents_became_persistent =
        n_initial_agents > 0 ?
        100.0 *
        n_same_agents /
        n_initial_agents :
        NaN


    # ============================================================
    # SUMMARY TABLE
    # ============================================================

    summary =
        DataFrames.DataFrame(

            n_runs = [
                n_sim
            ],

            initial_outlier_runs = [
                n_initial_runs
            ],

            persistent_outlier_runs = [
                n_persistent_runs
            ],

            run_overlap = [
                n_run_overlap
            ],

            same_agent_overlap_runs = [
                n_same_agent_overlap_runs
            ],

            pct_persistent_runs_with_initial = [
                pct_persistent_runs_with_initial
            ],

            pct_initial_runs_with_persistent = [
                pct_initial_runs_with_persistent
            ],

            pct_persistent_runs_same_agent_initial = [
                pct_persistent_runs_same_agent_initial
            ],

            pct_initial_runs_same_agent_persistent = [
                pct_initial_runs_same_agent_persistent
            ],

            initial_outlier_agents = [
                n_initial_agents
            ],

            persistent_outlier_agents = [
                n_persistent_agents
            ],

            same_outlier_agents = [
                n_same_agents
            ],

            pct_persistent_agents_already_initial = [
                pct_persistent_agents_already_initial
            ],

            pct_initial_agents_became_persistent = [
                pct_initial_agents_became_persistent
            ]
        )


    # ============================================================
    # RUN-LEVEL TABLE
    # ============================================================

    run_results =
        DataFrames.DataFrame(

            simulation =
                collect(1:n_sim),

            initial_outlier =
                initial_outlier_run,

            persistent_outlier =
                persistent_outlier_run,

            run_overlap =
                run_overlap,

            same_agent_overlap =
                same_agent_overlap_run
        )


    # ============================================================
    # PRINT
    # ============================================================

    println()
    println("="^78)
    println("INITIAL VS. PERSISTENT SEMANTIC OUTLIERS")
    println("="^78)

    println()
    println("Total runs: ", n_sim)
    println("Threshold:  ", threshold)


    println()
    println("RUN LEVEL")
    println("-"^78)

    println(
        "Runs with initial outlier:          ",
        n_initial_runs,
        " / ",
        n_sim,
        " (",
        round(
            100.0 * n_initial_runs / n_sim;
            digits = 2
        ),
        "%)"
    )

    println(
        "Runs with persistent outlier:       ",
        n_persistent_runs,
        " / ",
        n_sim,
        " (",
        round(
            100.0 * n_persistent_runs / n_sim;
            digits = 2
        ),
        "%)"
    )

    println(
        "Runs with both:                     ",
        n_run_overlap
    )

    println(
        "Initial only:                       ",
        n_initial_only_runs
    )

    println(
        "Persistent only:                    ",
        n_persistent_only_runs
    )

    println(
        "Neither:                            ",
        n_neither_runs
    )


    println()
    println("RUN-LEVEL CONDITIONAL OVERLAP")
    println("-"^78)

    println(
        "Of persistent runs, had ANY initial outlier: ",
        n_run_overlap,
        " / ",
        n_persistent_runs,
        " (",
        round(
            pct_persistent_runs_with_initial;
            digits = 2
        ),
        "%)"
    )

    println(
        "Of initial runs, later had ANY persistent:    ",
        n_run_overlap,
        " / ",
        n_initial_runs,
        " (",
        round(
            pct_initial_runs_with_persistent;
            digits = 2
        ),
        "%)"
    )


    println()
    println("SAME-AGENT OVERLAP WITHIN RUN")
    println("-"^78)

    println(
        "Persistent runs where SAME agent was initial: ",
        n_same_agent_overlap_runs,
        " / ",
        n_persistent_runs,
        " (",
        round(
            pct_persistent_runs_same_agent_initial;
            digits = 2
        ),
        "%)"
    )

    println(
        "Initial runs where SAME agent became persistent: ",
        n_same_agent_overlap_runs,
        " / ",
        n_initial_runs,
        " (",
        round(
            pct_initial_runs_same_agent_persistent;
            digits = 2
        ),
        "%)"
    )


    println()
    println("AGENT LEVEL")
    println("-"^78)

    println(
        "Initial outlier agents:             ",
        n_initial_agents
    )

    println(
        "Persistent outlier agents:          ",
        n_persistent_agents
    )

    println(
        "Same agents in both:                ",
        n_same_agents
    )

    println(
        "Of persistent agents, already initial: ",
        n_same_agents,
        " / ",
        n_persistent_agents,
        " (",
        round(
            pct_persistent_agents_already_initial;
            digits = 2
        ),
        "%)"
    )

    println(
        "Of initial agents, became persistent:  ",
        n_same_agents,
        " / ",
        n_initial_agents,
        " (",
        round(
            pct_initial_agents_became_persistent;
            digits = 2
        ),
        "%)"
    )

    println()
    println("="^78)


    return (
        summary = summary,
        runs = run_results,
        initial_outlier_agent = initial_outlier_agent,
        persistent_outlier_agent = persistent_outlier_agent,
        same_agent_overlap = same_agent_overlap
    )
end
# result =
#     summarize_initial_vs_persistent_outliers(
#         joinpath(
#             "sweep_beta_logs",
#             "RANDOM_RELOCATION_GROUP_SELF_TALK_RAW_1000.jld2"
#         )
# )

function compare_initial_vs_persistent_outlier_rates(
    path::String;
    threshold::Real = 2.5)

    # ============================================================
    # 1. LOAD DATA
    # ============================================================

    if !isfile(path)
        error("File not found: $path")
    end

    d = JLD2.load(path)

    if !haskey(d, "Z_all")
        error("Z_all not found in file.")
    end

    if !haskey(d, "any_crossing")
        error("any_crossing not found in file.")
    end

    if !haskey(d, "steps_axis")
        error("steps_axis not found in file.")
    end

    Z_all =
        d["Z_all"]

    any_crossing =
        d["any_crossing"]

    steps_axis =
        Int.(d["steps_axis"])


    # ============================================================
    # 2. CHECK DIMENSIONS
    # ============================================================

    n_models, n_sim, n_timepoints, N =
        size(Z_all)

    @assert n_models == 1
    @assert size(any_crossing) == (1, n_sim)
    @assert length(steps_axis) == n_timepoints
    @assert steps_axis[1] == 0


    # ============================================================
    # 3. RUN-LEVEL INDICATORS
    #
    # Initial:
    #   at least one agent has Z >= threshold at step 0
    #
    # Persistent:
    #   at least one agent becomes a persistent outlier
    # ============================================================

    initial_outlier =
        falses(n_sim)

    persistent_outlier =
        Bool.(
            vec(
                any_crossing[
                    1,
                    :
                ]
            )
        )


    for sim_idx in 1:n_sim

        initial_z =
            @view Z_all[
                1,
                sim_idx,
                1,
                :
            ]

        initial_outlier[sim_idx] =
            any(
                initial_z .>= threshold
            )
    end


    # ============================================================
    # 4. BASIC COUNTS
    # ============================================================

    n_initial =
        count(initial_outlier)

    n_persistent =
        count(persistent_outlier)

    p_initial =
        n_initial / n_sim

    p_persistent =
        n_persistent / n_sim


    # Difference is always:
    #
    # persistent - initial
    # ============================================================

    difference =
        p_persistent -
        p_initial


    # ============================================================
    # 5. 2 × 2 PAIRED TABLE
    # ============================================================
    #
    #                       Persistent
    #                    No          Yes
    #
    # Initial No       neither    persistent only
    # Initial Yes    initial only      both
    #
    # ============================================================

    both =
        count(
            initial_outlier .&
            persistent_outlier
        )

    initial_only =
        count(
            initial_outlier .&
            .!persistent_outlier
        )

    persistent_only =
        count(
            .!initial_outlier .&
            persistent_outlier
        )

    neither =
        count(
            .!initial_outlier .&
            .!persistent_outlier
        )

    @assert (
        both +
        initial_only +
        persistent_only +
        neither
    ) == n_sim


    # ============================================================
    # 6. INDEPENDENT TWO-PROPORTION Z-TEST
    #
    # This intentionally treats initial and persistent proportions
    # as if they were independent, matching the test used in the
    # previous between-model comparison.
    # ============================================================

    pooled_p =
        (
            n_initial +
            n_persistent
        ) /
        (
            2 * n_sim
        )


    se_independent_null =
        sqrt(
            pooled_p *
            (1.0 - pooled_p) *
            (
                1.0 / n_sim +
                1.0 / n_sim
            )
        )


    if se_independent_null == 0.0

        z_independent =
            difference == 0.0 ?
            0.0 :
            sign(difference) * Inf

        p_independent =
            difference == 0.0 ?
            1.0 :
            0.0

    else

        z_independent =
            difference /
            se_independent_null

        p_independent =
            2.0 *
            Distributions.ccdf(
                Distributions.Normal(),
                abs(z_independent)
            )
    end


    # ------------------------------------------------------------
    # Independent 95% CI
    #
    # Same unpooled Wald CI as in previous model comparison.
    # ------------------------------------------------------------

    se_independent_difference =
        sqrt(
            p_initial *
            (1.0 - p_initial) /
            n_sim +

            p_persistent *
            (1.0 - p_persistent) /
            n_sim
        )


    independent_ci95_low =
        difference -
        1.96 *
        se_independent_difference

    independent_ci95_high =
        difference +
        1.96 *
        se_independent_difference


    # ============================================================
    # 7. PAIRED McNEMAR TEST
    # ============================================================
    #
    # Only discordant pairs matter:
    #
    # initial_only    = 1 -> 0
    # persistent_only = 0 -> 1
    #
    # ============================================================

    n_discordant =
        initial_only +
        persistent_only


    # ------------------------------------------------------------
    # Asymptotic McNemar test
    # without continuity correction
    # ------------------------------------------------------------

    if n_discordant == 0

        mcnemar_chisq =
            0.0

        p_mcnemar_asymptotic =
            1.0

    else

        mcnemar_chisq =
            (
                initial_only -
                persistent_only
            )^2 /
            n_discordant

        p_mcnemar_asymptotic =
            Distributions.ccdf(
                Distributions.Chisq(1),
                mcnemar_chisq
            )
    end


    # ------------------------------------------------------------
    # Exact two-sided McNemar test
    #
    # Conditional on the number of discordant pairs,
    # under H0 either direction has probability 0.5.
    # ------------------------------------------------------------

    if n_discordant == 0

        p_mcnemar_exact =
            1.0

    else

        smaller_discordant =
            min(
                initial_only,
                persistent_only
            )

        p_mcnemar_exact =
            min(
                1.0,

                2.0 *
                Distributions.cdf(
                    Distributions.Binomial(
                        n_discordant,
                        0.5
                    ),
                    smaller_discordant
                )
            )
    end


    # ============================================================
    # 8. PAIRED 95% CI FOR DIFFERENCE
    #
    # Difference = persistent - initial
    #
    # For paired binary observations:
    #
    # Var(d) =
    # [p01 + p10 - (p01 - p10)^2] / n
    #
    # ============================================================

    p_initial_only =
        initial_only /
        n_sim

    p_persistent_only =
        persistent_only /
        n_sim


    se_paired_difference =
        sqrt(
            (
                p_initial_only +
                p_persistent_only -
                difference^2
            ) /
            n_sim
        )


    paired_ci95_low =
        difference -
        1.96 *
        se_paired_difference

    paired_ci95_high =
        difference +
        1.96 *
        se_paired_difference


    # ============================================================
    # 9. RESULTS DATAFRAME
    # ============================================================

    results =
        DataFrames.DataFrame(

            n_runs = [
                n_sim
            ],

            initial_outliers = [
                n_initial
            ],

            initial_proportion = [
                p_initial
            ],

            persistent_outliers = [
                n_persistent
            ],

            persistent_proportion = [
                p_persistent
            ],

            difference = [
                difference
            ],

            both = [
                both
            ],

            initial_only = [
                initial_only
            ],

            persistent_only = [
                persistent_only
            ],

            neither = [
                neither
            ],

            # Independent test

            independent_z = [
                z_independent
            ],

            independent_p_two_sided = [
                p_independent
            ],

            independent_ci95_low = [
                independent_ci95_low
            ],

            independent_ci95_high = [
                independent_ci95_high
            ],

            # Paired test

            mcnemar_chisq = [
                mcnemar_chisq
            ],

            mcnemar_asymptotic_p = [
                p_mcnemar_asymptotic
            ],

            mcnemar_exact_p = [
                p_mcnemar_exact
            ],

            paired_ci95_low = [
                paired_ci95_low
            ],

            paired_ci95_high = [
                paired_ci95_high
            ]
        )


    # Percentage-point versions

    results[!, :initial_percentage] =
        100.0 .*
        results.initial_proportion

    results[!, :persistent_percentage] =
        100.0 .*
        results.persistent_proportion

    results[!, :difference_percentage_points] =
        100.0 .*
        results.difference

    results[!, :independent_ci95_low_percentage_points] =
        100.0 .*
        results.independent_ci95_low

    results[!, :independent_ci95_high_percentage_points] =
        100.0 .*
        results.independent_ci95_high

    results[!, :paired_ci95_low_percentage_points] =
        100.0 .*
        results.paired_ci95_low

    results[!, :paired_ci95_high_percentage_points] =
        100.0 .*
        results.paired_ci95_high


    # ============================================================
    # 10. RUN-LEVEL DATAFRAME
    # ============================================================

    run_results =
        DataFrames.DataFrame(

            simulation =
                collect(1:n_sim),

            initial_outlier =
                initial_outlier,

            persistent_outlier =
                persistent_outlier,

            category = [
                initial_outlier[i] &&
                persistent_outlier[i] ?

                "both" :

                initial_outlier[i] ?

                "initial_only" :

                persistent_outlier[i] ?

                "persistent_only" :

                "neither"

                for i in 1:n_sim
            ]
        )


    # ============================================================
    # 11. PRINT
    # ============================================================

    println()
    println("="^82)
    println("INITIAL VS. PERSISTENT OUTLIER RATE")
    println("GROUP SELF-TALK MODEL")
    println("="^82)

    println()
    println("File:      ", path)
    println("Runs:      ", n_sim)
    println("Threshold: ", threshold)


    println()
    println("OUTLIER RATES")
    println("-"^82)

    println(
        "Initial:       ",
        n_initial,
        "/",
        n_sim,
        " = ",
        round(
            100.0 * p_initial;
            digits = 3
        ),
        "%"
    )

    println(
        "Persistent:    ",
        n_persistent,
        "/",
        n_sim,
        " = ",
        round(
            100.0 * p_persistent;
            digits = 3
        ),
        "%"
    )

    println(
        "Difference (persistent - initial): ",
        round(
            100.0 * difference;
            digits = 3
        ),
        " percentage points"
    )


    println()
    println("PAIRED 2 × 2 TABLE")
    println("-"^82)

    println(
        "Both:             ",
        both
    )

    println(
        "Initial only:     ",
        initial_only
    )

    println(
        "Persistent only:  ",
        persistent_only
    )

    println(
        "Neither:          ",
        neither
    )

    println(
        "Discordant:       ",
        n_discordant
    )


    # ============================================================
    # Independent
    # ============================================================

    println()
    println("INDEPENDENT TWO-PROPORTION Z-TEST")
    println("-"^82)

    println(
        "Difference: ",
        round(
            100.0 * difference;
            digits = 3
        ),
        " percentage points"
    )

    println(
        "95% CI: [",
        round(
            100.0 * independent_ci95_low;
            digits = 3
        ),
        ", ",
        round(
            100.0 * independent_ci95_high;
            digits = 3
        ),
        "] percentage points"
    )

    println(
        "z = ",
        round(
            z_independent;
            digits = 4
        )
    )

    println(
        "Two-sided p = ",
        round(
            p_independent;
            digits = 6
        )
    )


    # ============================================================
    # Paired
    # ============================================================

    println()
    println("PAIRED McNEMAR TEST")
    println("-"^82)

    println(
        "Difference: ",
        round(
            100.0 * difference;
            digits = 3
        ),
        " percentage points"
    )

    println(
        "Paired 95% CI: [",
        round(
            100.0 * paired_ci95_low;
            digits = 3
        ),
        ", ",
        round(
            100.0 * paired_ci95_high;
            digits = 3
        ),
        "] percentage points"
    )

    println(
        "McNemar chi-square = ",
        round(
            mcnemar_chisq;
            digits = 4
        )
    )

    println(
        "Asymptotic two-sided p = ",
        round(
            p_mcnemar_asymptotic;
            digits = 6
        )
    )

    println(
        "Exact two-sided p = ",
        round(
            p_mcnemar_exact;
            digits = 6
        )
    )

    println()
    println("="^82)


    # ============================================================
    # 12. RETURN
    # ============================================================

    return (
        results = results,
        runs = run_results,

        independent_test = (
            difference = difference,
            ci95_low = independent_ci95_low,
            ci95_high = independent_ci95_high,
            z = z_independent,
            p_value = p_independent
        ),

        paired_test = (
            difference = difference,
            ci95_low = paired_ci95_low,
            ci95_high = paired_ci95_high,
            chi_square = mcnemar_chisq,
            asymptotic_p = p_mcnemar_asymptotic,
            exact_p = p_mcnemar_exact
        )
    )
end
# result =
#     compare_initial_vs_persistent_outlier_rates(
#         joinpath(
#             "sweep_beta_logs",
#             "RANDOM_RELOCATION_GROUP_SELF_TALK_RAW_1000.jld2"
#         )
# )


function compare_persistent_outlier_proportions(
    original_vs_relocation_path::String,
    model_3_1_dir::String,
    group_self_talk_path::String;
    confidence_level::Real = 0.95,
    test_sidedness::Symbol = :one_sided)

    @assert 0.0 < confidence_level < 1.0
    @assert test_sidedness in (:one_sided, :two_sided)

    # ============================================================
    # 1. EXTRACT PERSISTENT-OUTLIER RESULTS
    # ============================================================

    function extract_from_file(
        path::String;
        selected_model::Union{Nothing,String} = nothing
    )

        isfile(path) || error("File not found: $path")

        d = JLD2.load(path)

        if haskey(d, "any_crossing")

            x = d["any_crossing"]

            if x isa AbstractVector

                values = Bool.(x)

            elseif x isa AbstractMatrix

                if selected_model !== nothing

                    haskey(d, "model_names") ||
                        error("model_names not found in $path")

                    model_names = String.(d["model_names"])

                    idx = findfirst(
                        ==(selected_model),
                        model_names
                    )

                    idx === nothing &&
                        error(
                            "Model $selected_model not found. " *
                            "Available: $model_names"
                        )

                    if length(model_names) == size(x, 1)

                        values = Bool.(vec(x[idx, :]))

                    elseif length(model_names) == size(x, 2)

                        values = Bool.(vec(x[:, idx]))

                    else

                        error("Model dimensions mismatch in $path")

                    end

                elseif size(x, 1) == 1

                    values = Bool.(vec(x[1, :]))

                elseif size(x, 2) == 1

                    values = Bool.(vec(x[:, 1]))

                else

                    error(
                        "Multiple models found, but no model selected: $path"
                    )

                end

            else

                error("Unsupported any_crossing type in $path")

            end

        elseif haskey(d, "run_summary")

            rs = d["run_summary"]

            if selected_model !== nothing

                :model in propertynames(rs) ||
                    error("Model column missing in $path")

                rs = rs[
                    String.(rs.model) .== selected_model,
                    :
                ]

                DataFrames.nrow(rs) > 0 ||
                    error("Model $selected_model not found in $path")

            end

            candidate_columns = [
                :any_crossing,
                :persistent_outlier,
                :has_persistent_outlier
            ]

            col = findfirst(
                c -> c in propertynames(rs),
                candidate_columns
            )

            col === nothing &&
                error("No persistent-outlier column in $path")

            values = Bool.(rs[!, candidate_columns[col]])

        else

            error(
                "Neither any_crossing nor run_summary found in $path"
            )

        end

        length(values) > 0 ||
            error("No simulations found in $path")

        return (
            n = length(values),
            k = count(values)
        )
    end


    # ============================================================
    # 2. EXTRACT MODEL 3.1 FROM BATCH FILES
    # ============================================================

    function extract_model_3_1(dir::String)

        isdir(dir) || error("Directory not found: $dir")

        files = sort(
            filter(
                f -> startswith(basename(f), "batch_") &&
                     endswith(f, ".jld2"),
                readdir(dir; join = true)
            )
        )

        isempty(files) &&
            error("No batch files found in $dir")

        seen = Set{Int}()

        n_total = 0
        k_total = 0

        for (file_idx, file) in enumerate(files)

            d = JLD2.load(file)

            ids = Int.(d["simulation_ids"])

            # Model 3.1 batches store persistent flags per agent.
            # Derive a run-level flag from crossed when necessary.
            if haskey(d, "any_crossing")
                x = d["any_crossing"]
                @assert size(x) == (1, length(ids))
                run_flags = Bool.(vec(x[1, :]))
            elseif haskey(d, "crossed")
                x = d["crossed"]
                @assert size(x, 2) == length(ids)
                run_flags = [any(@view x[1, j, :]) for j in eachindex(ids)]
            else
                error("No persistent-outlier flags in $file")
            end

            for (j, id) in enumerate(ids)

                id in seen &&
                    error("Duplicate simulation ID $id")

                push!(seen, id)

                n_total += 1

                if run_flags[j]
                    k_total += 1
                end

            end

            println(
                "Model 3.1: analyzed file ",
                file_idx,
                " / ",
                length(files)
            )

        end

        return (
            n = n_total,
            k = k_total
        )
    end


    # ============================================================
    # 3. LOAD FOUR MODELS
    # ============================================================

    println()
    println("="^90)
    println("LOADING FOUR MODELS")
    println("="^90)

    original = extract_from_file(
        original_vs_relocation_path;
        selected_model = "original"
    )

    enhanced = extract_from_file(
        original_vs_relocation_path;
        selected_model = "random_relocation"
    )

    model_3_1 = extract_model_3_1(
        model_3_1_dir
    )

    group_self_talk = extract_from_file(
        group_self_talk_path
    )


    models = [
        (
            id = 1,
            name = "Original",
            n = original.n,
            k = original.k
        ),
        (
            id = 2,
            name = "Enhanced randomization",
            n = enhanced.n,
            k = enhanced.k
        ),
        (
            id = 3,
            name = "Model 3.1",
            n = model_3_1.n,
            k = model_3_1.k
        ),
        (
            id = 4,
            name = "Group self-talk",
            n = group_self_talk.n,
            k = group_self_talk.k
        )
    ]


    # ============================================================
    # 4. INDIVIDUAL PROPORTIONS AND WILSON CONFIDENCE INTERVALS
    # ============================================================

    alpha = 1.0 - confidence_level

    z_critical = Distributions.quantile(
        Distributions.Normal(),
        1.0 - alpha / 2.0
    )

    function wilson_ci(k::Int, n::Int)

        p = k / n

        z2 = z_critical^2

        denominator = 1.0 + z2 / n

        center = (
            p + z2 / (2.0 * n)
        ) / denominator

        half_width = (
            z_critical / denominator
        ) * sqrt(
            p * (1.0 - p) / n +
            z2 / (4.0 * n^2)
        )

        return (
            center - half_width,
            center + half_width
        )
    end


    model_results = DataFrames.DataFrame(
        model = String[],
        n_runs = Int[],
        n_persistent = Int[],
        percentage = Float64[],
        ci_low = Float64[],
        ci_high = Float64[]
    )

    for model in models

        ci_low, ci_high = wilson_ci(
            model.k,
            model.n
        )

        push!(
            model_results,
            (
                model.name,
                model.n,
                model.k,
                100.0 * model.k / model.n,
                100.0 * ci_low,
                100.0 * ci_high
            )
        )

    end


    # ============================================================
    # 5. TWO-PROPORTION Z TEST
    #
    # Pooled proportion for hypothesis test.
    # Unpooled variance for confidence interval.
    # ============================================================

    function compare_models(
        model_a,
        model_b;
        alternative::Symbol = :two_sided
    )

        @assert alternative in (
            :two_sided,
            :greater,
            :less
        )

        p_a = model_a.k / model_a.n
        p_b = model_b.k / model_b.n

        # Difference = A - B
        difference = p_a - p_b

        # --------------------------------------------------------
        # Pooled Z-test
        # --------------------------------------------------------

        pooled_p = (
            model_a.k + model_b.k
        ) / (
            model_a.n + model_b.n
        )

        se_pooled = sqrt(
            pooled_p *
            (1.0 - pooled_p) *
            (
                1.0 / model_a.n +
                1.0 / model_b.n
            )
        )

        if se_pooled == 0.0

            z_stat = 0.0
            p_value = 1.0

        else

            z_stat = difference / se_pooled

            if alternative == :two_sided

                p_value = 2.0 *
                    Distributions.ccdf(
                        Distributions.Normal(),
                        abs(z_stat)
                    )

            elseif alternative == :greater

                p_value = Distributions.ccdf(
                    Distributions.Normal(),
                    z_stat
                )

            else

                p_value = Distributions.cdf(
                    Distributions.Normal(),
                    z_stat
                )

            end

        end

        # --------------------------------------------------------
        # Newcombe confidence interval for difference
        # Based on Wilson score intervals
        # --------------------------------------------------------

        a_low, a_high = wilson_ci(
            model_a.k,
            model_a.n
        )

        b_low, b_high = wilson_ci(
            model_b.k,
            model_b.n
        )

        ci_low = difference - sqrt(
            (p_a - a_low)^2 +
            (b_high - p_b)^2
        )

        ci_high = difference + sqrt(
            (a_high - p_a)^2 +
            (p_b - b_low)^2
        )

        return (
            comparison = "$(model_a.name) - $(model_b.name)",
            alternative = String(alternative),
            difference = 100.0 * difference,
            ci_low = 100.0 * ci_low,
            ci_high = 100.0 * ci_high,
            z = z_stat,
            p_value = p_value
        )
    end


    # ============================================================
    # 6. FIVE PLANNED COMPARISONS
    # ============================================================

    alternative = test_sidedness == :one_sided ?
        :greater : :two_sided

    comparisons = [
        compare_models(
            models[1],
            models[2];
            alternative = alternative
        ),

        compare_models(
            models[1],
            models[3];
            alternative = alternative
        ),

        compare_models(
            models[1],
            models[4];
            alternative = alternative
        ),

        compare_models(
            models[2],
            models[3];
            alternative = alternative
        ),

        compare_models(
            models[2],
            models[4];
            alternative = alternative
        )
    ]


    comparison_results = DataFrames.DataFrame(
        comparison = String[],
        alternative = String[],
        difference_percentage_points = Float64[],
        ci95_low = Float64[],
        ci95_high = Float64[],
        z = Float64[],
        p_value = Float64[]
    )

    for r in comparisons
        push!(comparison_results, (
            r.comparison,
            r.alternative,
            r.difference,
            r.ci_low,
            r.ci_high,
            r.z,
            r.p_value
        ))
    end

    # ============================================================
    # 7. PRINT MODEL PROPORTIONS
    # ============================================================

    println()
    println("="^90)
    println("PERSISTENT OUTLIER RATES")
    println("="^90)

    for row in eachrow(model_results)

        println()
        println(row.model)
        println("-"^60)

        println(
            "Persistent outliers: ",
            row.n_persistent,
            " / ",
            row.n_runs
        )

        println(
            "Percentage: ",
            round(row.percentage; digits = 3),
            "%"
        )

        println(
            "$(round(100 * confidence_level; digits = 1))% CI: [",
            round(row.ci_low; digits = 3),
            ", ",
            round(row.ci_high; digits = 3),
            "]%"
        )

    end


    # ============================================================
    # 8. PRINT STATISTICAL COMPARISONS
    # ============================================================

    println()
    println("="^90)
    println("STATISTICAL COMPARISONS")
    println("="^90)

    for row in eachrow(comparison_results)

        println()
        println(row.comparison)
        println("-"^70)

        println(
            "Alternative: ",
            row.alternative
        )

        println(
            "Difference: ",
            round(
                row.difference_percentage_points;
                digits = 3
            ),
            " percentage points"
        )

        println(
            "$(round(100 * confidence_level; digits = 1))% CI: [",
            round(row.ci95_low; digits = 3),
            ", ",
            round(row.ci95_high; digits = 3),
            "] percentage points"
        )

        println(
            "z = ",
            round(row.z; digits = 4)
        )

        println(
            "p = ",
            round(row.p_value; digits = 6)
        )

    end

    println()
    println("="^90)

    # ============================================================
    # 9. RETURN
    # ============================================================

    return (
        models = model_results,
        comparisons = comparison_results,
        raw_models = models
    )
end
# comparison_results = compare_persistent_outlier_proportions(
#     joinpath("sweep_beta_logs", "ORIGINAL_VS_RANDOM_RELOCATION_RAW_1000.jld2"),
#     joinpath("sweep_beta_logs", "MODEL_3_1_PARALLEL"),
#     joinpath("sweep_beta_logs", "RANDOM_RELOCATION_GROUP_SELF_TALK_RAW_1000.jld2");
