# Social
function analyze_semantic_social_agent_level(
    z_path::String,
    social_path::String;
    semantic_threshold::Real = 2.5,
    social_threshold::Real = -2.5,
    B::Int = 100_000,
    seed::Int = 12345,
    progress_every::Int = 10_000)

    rng = Random.MersenneTwister(seed)

    # ============================================================
    # 1. Load data
    # ============================================================

    dz = JLD2.load(z_path)
    ds = JLD2.load(social_path)

    Z_all = dz["Z_all"]
    beta_z = Float64.(dz["beta_value"])
    sim_z = Int.(dz["sim"])

    pair_counts_all = ds["pair_counts_all"]
    pair_map = Tuple{Int,Int}.(ds["pair_map"])
    beta_s = Float64.(ds["beta_value"])
    sim_s = Int.(ds["sim_ids"])

    N = Int(ds["N"])

    # ============================================================
    # Exclude beta = 0 runs from the model analysis
    # ============================================================

    keep_z = beta_z .!= 0.0
    keep_s = beta_s .!= 0.0

    println("Excluding beta = 0 runs...")
    println("  Semantic runs removed: ", count(.!keep_z))
    println("  Social runs removed:   ", count(.!keep_s))

    Z_all = Z_all[keep_z, :, :]
    beta_z = beta_z[keep_z]
    sim_z = sim_z[keep_z]

    pair_counts_all = pair_counts_all[keep_s, :, :]
    beta_s = beta_s[keep_s]
    sim_s = sim_s[keep_s]

    println("  Runs retained:         ", size(Z_all, 1))

    n_runs = size(Z_all, 1)
    T = size(Z_all, 2)

    @assert size(Z_all, 3) == N
    @assert size(pair_counts_all, 1) == length(beta_s)
    @assert size(pair_counts_all, 3) == length(pair_map)

    # ============================================================
    # 2. Match semantic and social runs by (beta, sim)
    # ============================================================

    social_lookup = Dict{Tuple{Float64,Int},Int}()

    for r in eachindex(beta_s)

        key = (beta_s[r], sim_s[r])

        if haskey(social_lookup, key)
            error("Duplicate social run key: $key")
        end

        social_lookup[key] = r
    end

    # ============================================================
    # 3. Storage
    # ============================================================

    n_semantic_by_run = zeros(Int, n_runs)

    isolated_agents_by_run =
        Vector{Vector{Int}}(undef, n_runs)

    interactions_by_run =
        Vector{Vector{Float64}}(undef, n_runs)

    # For the permutation we only need to know the social ordering
    # and tie boundaries.
    rank1_by_run = zeros(Int, n_runs)
    rank2_by_run = zeros(Int, n_runs)
    rank3_by_run = zeros(Int, n_runs)

    rank1_unique_by_run = falses(n_runs)
    rank2_boundary_unique_by_run = falses(n_runs)

    # Agent-level results for persistent semantic outliers
    agent_beta = Float64[]
    agent_sim = Int[]
    agent_id = Int[]
    agent_final_SA = Float64[]
    agent_final_SP = Float64[]
    agent_socially_isolated = Bool[]
    agent_lowest_social = Bool[]

    # Temporary true semantic identities, needed to determine
    # observed lowest-social status.
    true_semantic_by_run =
        Vector{Vector{Int}}(undef, n_runs)

    total_socially_isolated = 0
    total_semantic_outliers = 0
    observed_overlap = 0
    observed_lowest_social = 0

    println("Reconstructing observed agent-level data...")

    # ============================================================
    # 4. Reconstruct observed data
    # ============================================================

    for r in 1:n_runs

        # --------------------------------------------------------
        # Match social run
        # --------------------------------------------------------

        key = (beta_z[r], sim_z[r])

        if !haskey(social_lookup, key)
            error("No matching social run for semantic run: $key")
        end

        sr = social_lookup[key]

        # --------------------------------------------------------
        # Persistent semantic outliers
        #
        # Existing criterion:
        # SA >= 2.5 at some recorded point and remains >= 2.5
        # through the end of the simulation.
        # --------------------------------------------------------

        semantic_outliers = Int[]

        for agent in 1:N

            ztraj = @view Z_all[r, :, agent]

            persistent = false

            for t in 1:T

                if ztraj[t] >= semantic_threshold &&
                   all(@view(ztraj[t:T]) .>= semantic_threshold)

                    persistent = true
                    break
                end
            end

            if persistent
                push!(semantic_outliers, agent)
            end
        end

        k = length(semantic_outliers)

        # The existing rank analysis was defined for exactly
        # one or exactly two semantic outliers.
        if k > 2
            error(
                "Simulation (beta=$(beta_z[r]), sim=$(sim_z[r])) " *
                "contains $k persistent semantic outliers. " *
                "The existing lowest-social criterion was defined " *
                "only for k = 1 or k = 2."
            )
        end

        n_semantic_by_run[r] = k
        true_semantic_by_run[r] = semantic_outliers

        # --------------------------------------------------------
        # Final cumulative social participation
        #
        # Same calculation as existing analysis:
        # pairwise cumulative counts are added to both agents.
        # --------------------------------------------------------

        interactions = zeros(Float64, N)

        for p in eachindex(pair_map)

            a, b = pair_map[p]

            c = Float64(
                pair_counts_all[sr, end, p]
            )

            interactions[a] += c
            interactions[b] += c
        end

        interactions_by_run[r] = interactions

        # --------------------------------------------------------
        # Final SP:
        # z-standardization within simulation
        # using the same Statistics.std definition.
        # --------------------------------------------------------

        μ = Statistics.mean(interactions)
        σ = Statistics.std(interactions)

        if σ == 0 || !isfinite(σ)

            social_z = zeros(Float64, N)

        else

            social_z =
                (interactions .- μ) ./ σ
        end

        # --------------------------------------------------------
        # Social isolation: SP < -2.5
        # --------------------------------------------------------

        socially_isolated =
            Int.(findall(social_z .<= social_threshold))

        isolated_agents_by_run[r] =
            socially_isolated

        total_socially_isolated +=
            length(socially_isolated)

        # --------------------------------------------------------
        # Social ranking + exact tie handling
        # --------------------------------------------------------

        order = sortperm(interactions)

        rank1 = order[1]
        rank2 = order[2]
        rank3 = order[3]

        rank1_by_run[r] = rank1
        rank2_by_run[r] = rank2
        rank3_by_run[r] = rank3

        # Needed when only rank 1 is counted.
        rank1_unique_by_run[r] =
            interactions[rank1] < interactions[rank2]

        # Needed when ranks 1 AND 2 are both counted.
        # Notice: no requirement that rank1 < rank2.
        rank2_boundary_unique_by_run[r] =
            interactions[rank2] < interactions[rank3]

        # --------------------------------------------------------
        # Determine observed lowest-social semantic agents
        # --------------------------------------------------------

        lowest_semantic_agents = Int[]

        if k == 1

            sem1 = semantic_outliers[1]

            if sem1 == rank1 &&
               rank1_unique_by_run[r]

                push!(lowest_semantic_agents, sem1)
            end

        elseif k == 2

            sem1 = semantic_outliers[1]
            sem2 = semantic_outliers[2]

            rank1_is_semantic =
                rank1 == sem1 || rank1 == sem2

            rank2_is_semantic =
                rank2 == sem1 || rank2 == sem2

            if rank1_is_semantic

                # Case A:
                # rank1 is strictly below rank2.
                #
                # rank1 counts.
                # rank2 additionally counts only if it is semantic
                # AND strictly below rank3.
                if interactions[rank1] < interactions[rank2]

                    push!(lowest_semantic_agents, rank1)

                    if rank2_is_semantic &&
                    interactions[rank2] < interactions[rank3]

                        push!(lowest_semantic_agents, rank2)
                    end

                # Case B:
                # rank1 and rank2 are tied.
                #
                # rank1 cannot count alone.
                # Both count only if rank2 is also semantic and the
                # tied pair is strictly below rank3.
                elseif interactions[rank1] == interactions[rank2]

                    if rank2_is_semantic &&
                    interactions[rank2] < interactions[rank3]

                        push!(lowest_semantic_agents, rank1)
                        push!(lowest_semantic_agents, rank2)
                    end
                end
            end
        end

        # --------------------------------------------------------
        # Agent-level output
        # --------------------------------------------------------

        for agent in semantic_outliers

            is_isolated =
                social_z[agent] <= social_threshold

            is_lowest =
                agent in lowest_semantic_agents

            push!(agent_beta, beta_z[r])
            push!(agent_sim, sim_z[r])
            push!(agent_id, agent)

            push!(
                agent_final_SA,
                Float64(Z_all[r, end, agent])
            )

            push!(
                agent_final_SP,
                social_z[agent]
            )

            push!(
                agent_socially_isolated,
                is_isolated
            )

            push!(
                agent_lowest_social,
                is_lowest
            )

            total_semantic_outliers += 1

            if is_isolated
                observed_overlap += 1
            end

            if is_lowest
                observed_lowest_social += 1
            end
        end

        # --------------------------------------------------------
        # Coarse reconstruction progress
        # --------------------------------------------------------

        if r == 1 ||
           r % 500 == 0 ||
           r == n_runs

            println("  Run $r / $n_runs")
        end
    end

    # ============================================================
    # 5. Build agent-level DataFrame
    # ============================================================

    agents = DataFrames.DataFrame(
        beta = agent_beta,
        simulation = agent_sim,
        agent = agent_id,
        final_SA = agent_final_SA,
        final_SP = agent_final_SP,
        socially_isolated = agent_socially_isolated,
        lowest_social = agent_lowest_social
    )

    # ============================================================
    # 6. Overall persistent-semantic summary
    # ============================================================

    n_persistent_semantic =
        DataFrames.nrow(agents)

    mean_final_SP =
        Statistics.mean(agents.final_SP)

    sd_final_SP =
        Statistics.std(agents.final_SP)

    n_socially_isolated =
        total_socially_isolated

    # Sanity: the two ways of counting semantic agents
    # must agree.
    @assert n_persistent_semantic ==
            total_semantic_outliers

    # ============================================================
    # 7. Observed agent-level proportions
    # ============================================================

    # Semantic -> SP < -2.5
    observed_semantic_to_isolation =
        observed_overlap / n_persistent_semantic

    # Semantic -> lowest social participation
    observed_semantic_to_lowest =
        observed_lowest_social / n_persistent_semantic

    # SP < -2.5 -> Semantic
    observed_isolation_to_semantic =
        observed_overlap / n_socially_isolated

    # ============================================================
    # 8. Sanity checks against existing results
    #
    # These are checks only, not values used in the analysis.
    # ============================================================

    println()
    println("="^75)
    println("RECONSTRUCTED OBSERVED DATA")
    println("="^75)

    println("Simulations:                       ", n_runs)
    println("Persistent semantic outliers:      ", n_persistent_semantic)
    println("Socially isolated agents:          ", n_socially_isolated)
    println("Semantic/social overlap:            ", observed_overlap)
    println("Semantic outliers lowest-social:    ", observed_lowest_social)

    # ============================================================
    # 9. Null distributions
    #
    # One permutation procedure.
    #
    # In every simulation:
    # - social participation stays fixed
    # - socially isolated identities stay fixed
    # - k = number of observed semantic outliers stays fixed
    # - only semantic-outlier identity is randomized
    # ============================================================

    null_overlap_counts =
        Vector{Int}(undef, B)

    null_lowest_counts =
        Vector{Int}(undef, B)

    println()
    println("Running $B permutations...")

    for perm in 1:B

        permuted_overlap = 0
        permuted_lowest = 0

        for r in 1:n_runs

            k = n_semantic_by_run[r]

            # No semantic outliers in this simulation:
            # contributes nothing to either statistic.
            if k == 0
                continue
            end

            # ====================================================
            # k = 1
            # ====================================================

            if k == 1

                random_sem =
                    Random.rand(rng, 1:N)

                # -----------------------------------------------
                # Threshold social isolation overlap
                # -----------------------------------------------

                if random_sem in isolated_agents_by_run[r]
                    permuted_overlap += 1
                end

                # -----------------------------------------------
                # Lowest-social criterion
                # -----------------------------------------------

                if random_sem == rank1_by_run[r] &&
                   rank1_unique_by_run[r]

                    permuted_lowest += 1
                end

            # ====================================================
            # k = 2
            # ====================================================

            elseif k == 2

                # Uniformly sample two distinct agents.
                random_a =
                    Random.rand(rng, 1:N)

                random_b =
                    Random.rand(rng, 1:(N - 1))

                if random_b >= random_a
                    random_b += 1
                end

                # -----------------------------------------------
                # Threshold social isolation overlap
                # -----------------------------------------------

                if random_a in isolated_agents_by_run[r]
                    permuted_overlap += 1
                end

                if random_b in isolated_agents_by_run[r]
                    permuted_overlap += 1
                end

                # -----------------------------------------------
                # Lowest-social criterion
                # Exact same tie logic as observed data
                # -----------------------------------------------

                rank1 = rank1_by_run[r]
                rank2 = rank2_by_run[r]
                rank3 = rank3_by_run[r]

                rank1_is_semantic =
                    rank1 == random_a ||
                    rank1 == random_b

                rank2_is_semantic =
                    rank2 == random_a ||
                    rank2 == random_b

                if rank1_is_semantic

                    # Case A:
                    # rank1 is strictly below rank2.
                    if interactions_by_run[r][rank1] <
                    interactions_by_run[r][rank2]

                        permuted_lowest += 1

                        # rank2 additionally counts only if it is semantic
                        # and strictly below rank3.
                        if rank2_is_semantic &&
                        interactions_by_run[r][rank2] <
                        interactions_by_run[r][rank3]

                            permuted_lowest += 1
                        end

                    # Case B:
                    # rank1 and rank2 are tied.
                    elseif interactions_by_run[r][rank1] ==
                        interactions_by_run[r][rank2]

                        # Neither counts individually.
                        # Both count only if both are semantic and the tied
                        # pair is strictly below rank3.
                        if rank2_is_semantic &&
                        interactions_by_run[r][rank2] <
                        interactions_by_run[r][rank3]

                            permuted_lowest += 2
                        end
                    end
                end
            end
        end

        null_overlap_counts[perm] =
            permuted_overlap

        null_lowest_counts[perm] =
            permuted_lowest

        if perm == 1 ||
           perm % progress_every == 0 ||
           perm == B

            println("  Permutation $perm / $B")
        end
    end

    # ============================================================
    # 10. Convert counts to agent-level proportions
    # ============================================================

    # Same overlap count, denominator = semantic outliers
    null_semantic_to_isolation =
        null_overlap_counts ./ n_persistent_semantic

    # Lowest-social count, denominator = semantic outliers
    null_semantic_to_lowest =
        null_lowest_counts ./ n_persistent_semantic

    # Same overlap count, denominator = socially isolated agents
    null_isolation_to_semantic =
        null_overlap_counts ./ n_socially_isolated

    # ============================================================
    # 11. Permutation p-values
    # ============================================================

    b_semantic_to_isolation =
        count(
            x -> x >= observed_semantic_to_isolation,
            null_semantic_to_isolation
        )

    b_semantic_to_lowest =
        count(
            x -> x >= observed_semantic_to_lowest,
            null_semantic_to_lowest
        )

    b_isolation_to_semantic =
        count(
            x -> x >= observed_isolation_to_semantic,
            null_isolation_to_semantic
        )

    p_semantic_to_isolation =
        (b_semantic_to_isolation + 1) / (B + 1)

    p_semantic_to_lowest =
        (b_semantic_to_lowest + 1) / (B + 1)

    p_isolation_to_semantic =
        (b_isolation_to_semantic + 1) / (B + 1)

    # The two threshold-overlap tests are monotonic
    # transformations of exactly the same overlap counts.
    @assert b_semantic_to_isolation ==
            b_isolation_to_semantic

    @assert p_semantic_to_isolation ==
            p_isolation_to_semantic

    # ============================================================
    # 12. Null summaries
    # ============================================================

    q_semantic_to_isolation =
        Statistics.quantile(
            null_semantic_to_isolation,
            [0.025, 0.975]
        )

    q_semantic_to_lowest =
        Statistics.quantile(
            null_semantic_to_lowest,
            [0.025, 0.975]
        )

    q_isolation_to_semantic =
        Statistics.quantile(
            null_isolation_to_semantic,
            [0.025, 0.975]
        )

    # ============================================================
    # 13. Overall semantic summary
    # ============================================================

    semantic_summary = DataFrames.DataFrame(
        n_persistent_semantic =
            [n_persistent_semantic],

        mean_final_SP =
            [mean_final_SP],

        sd_final_SP =
            [sd_final_SP],

        n_socially_isolated =
            [n_socially_isolated],

        n_overlap =
            [observed_overlap],

        n_lowest_social =
            [observed_lowest_social],

        pct_semantic_socially_isolated =
            [100 * observed_semantic_to_isolation],

        pct_semantic_lowest_social =
            [100 * observed_semantic_to_lowest],

        pct_isolated_semantic =
            [100 * observed_isolation_to_semantic]
    )

    # ============================================================
    # 14. Permutation-test summary
    # ============================================================

    permutation_summary = DataFrames.DataFrame(

        test = [
            "Semantic → SP < -2.5",
            "Semantic → lowest social participation",
            "SP < -2.5 → Semantic"
        ],

        observed_count = [
            observed_overlap,
            observed_lowest_social,
            observed_overlap
        ],

        denominator = [
            n_persistent_semantic,
            n_persistent_semantic,
            n_socially_isolated
        ],

        observed_proportion = [
            observed_semantic_to_isolation,
            observed_semantic_to_lowest,
            observed_isolation_to_semantic
        ],

        null_mean = [
            Statistics.mean(null_semantic_to_isolation),
            Statistics.mean(null_semantic_to_lowest),
            Statistics.mean(null_isolation_to_semantic)
        ],

        null_sd = [
            Statistics.std(null_semantic_to_isolation),
            Statistics.std(null_semantic_to_lowest),
            Statistics.std(null_isolation_to_semantic)
        ],

        null_q025 = [
            q_semantic_to_isolation[1],
            q_semantic_to_lowest[1],
            q_isolation_to_semantic[1]
        ],

        null_q975 = [
            q_semantic_to_isolation[2],
            q_semantic_to_lowest[2],
            q_isolation_to_semantic[2]
        ],

        b_ge_observed = [
            b_semantic_to_isolation,
            b_semantic_to_lowest,
            b_isolation_to_semantic
        ],

        B = [
            B,
            B,
            B
        ],

        permutation_p = [
            p_semantic_to_isolation,
            p_semantic_to_lowest,
            p_isolation_to_semantic
        ]
    )

    # ============================================================
    # 15. Print results
    # ============================================================

    println()
    println("="^85)
    println("PERSISTENT SEMANTIC ATYPICALITY AND SOCIAL ISOLATION")
    println("AGENT-LEVEL ANALYSIS")
    println("="^85)

    println()
    println("GENERAL")
    println("-"^85)
    println("Number of simulations:              ", n_runs)
    println("Persistent semantic outliers:       ", n_persistent_semantic)
    println("Socially isolated agents:           ", n_socially_isolated)
    println("Observed overlap:                   ", observed_overlap)

    println()
    println("FINAL SOCIAL PARTICIPATION OF PERSISTENT SEMANTIC OUTLIERS")
    println("-"^85)
    println(
        "Mean final SP:                      ",
        round(mean_final_SP, digits = 6)
    )
    println(
        "SD final SP:                        ",
        round(sd_final_SP, digits = 6)
    )

    println()
    println("SEMANTIC → SP < -2.5")
    println("-"^85)
    println(
        "Observed:                           ",
        observed_overlap,
        " / ",
        n_persistent_semantic,
        " (",
        round(100 * observed_semantic_to_isolation, digits = 3),
        "%)"
    )

    println()
    println("SEMANTIC → LOWEST SOCIAL PARTICIPATION")
    println("-"^85)
    println(
        "Observed:                           ",
        observed_lowest_social,
        " / ",
        n_persistent_semantic,
        " (",
        round(100 * observed_semantic_to_lowest, digits = 3),
        "%)"
    )

    println()
    println("SP < -2.5 → SEMANTIC")
    println("-"^85)
    println(
        "Observed:                           ",
        observed_overlap,
        " / ",
        n_socially_isolated,
        " (",
        round(100 * observed_isolation_to_semantic, digits = 3),
        "%)"
    )

    println()
    println("="^85)
    println("SEMANTIC SUMMARY")
    println("="^85)

    show(
        stdout,
        semantic_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )
    println()

    println()
    println("="^85)
    println("PERMUTATION TESTS")
    println("="^85)

    # Print vertically so nothing is truncated.
    for row in DataFrames.eachrow(permutation_summary)

        println()
        println(row.test)
        println("-"^85)

        println(
            "Observed count:                    ",
            row.observed_count
        )

        println(
            "Denominator:                       ",
            row.denominator
        )

        println(
            "Observed proportion:               ",
            round(row.observed_proportion, digits = 6),
            " (",
            round(100 * row.observed_proportion, digits = 3),
            "%)"
        )

        println(
            "Null mean:                         ",
            round(row.null_mean, digits = 6),
            " (",
            round(100 * row.null_mean, digits = 3),
            "%)"
        )

        println(
            "Null SD:                           ",
            round(row.null_sd, digits = 6)
        )

        println(
            "Null 2.5th percentile:             ",
            round(row.null_q025, digits = 6)
        )

        println(
            "Null 97.5th percentile:            ",
            round(row.null_q975, digits = 6)
        )

        println(
            "Permutations >= observed:          ",
            row.b_ge_observed,
            " / ",
            row.B
        )

        println(
            "One-sided permutation p-value:     ",
            row.permutation_p
        )
    end

    println()
    println("="^85)
    println("PERMUTATION SUMMARY DATAFRAME")
    println("="^85)

    show(
        stdout,
        permutation_summary;
        allrows = true,
        allcols = true,
        truncate = 0
    )
    println()

    println()
    println("="^85)
    println("AGENT-LEVEL DATAFRAME")
    println("="^85)

    show(
        stdout,
        agents;
        allrows = true,
        allcols = true,
        truncate = 0
    )
    println()

    # ============================================================
    # 16. Return everything useful for later analysis
    # ============================================================

    return (
        semantic_summary = semantic_summary,
        permutation_summary = permutation_summary,
        agents = agents,

        null_semantic_to_isolation =
            null_semantic_to_isolation,

        null_semantic_to_lowest =
            null_semantic_to_lowest,

        null_isolation_to_semantic =
            null_isolation_to_semantic,

        null_overlap_counts =
            null_overlap_counts,

        null_lowest_counts =
            null_lowest_counts
    )
end
# semantic_social_results =
#     analyze_semantic_social_agent_level(
#         z_path,
#         social_path;
#         semantic_threshold = 2.5,
#         social_threshold = -2.5,
#         B = 100_000,
#         seed = 12345,
#         progress_every = 10_000
# )
function analyze_agent_level_venn(
    z_path::String,
    social_path::String;
    semantic_threshold::Float64 = 2.5,
    social_threshold::Float64 = -2.5)

    # ============================================================
    # 1. Load data
    # ============================================================

    dz = JLD2.load(z_path)
    ds = JLD2.load(social_path)

    Z_all = dz["Z_all"]

    z_betas = Float64.(dz["beta_value"])
    z_sims = Int.(dz["sim"])
    z_steps = Int.(dz["steps_axis"])

    pair_counts_all = ds["pair_counts_all"]

    social_betas = Float64.(ds["beta_value"])
    social_sims = Int.(ds["sim_ids"])
    social_steps = Int.(ds["steps_axis"])

    pair_map = ds["pair_map"]

    # ============================================================
    # Exclude beta = 0 runs from the model analysis
    # ============================================================

    keep_z = z_betas .!= 0.0
    keep_social = social_betas .!= 0.0

    println("Excluding beta = 0 runs...")
    println("  Semantic runs removed: ", count(.!keep_z))
    println("  Social runs removed:   ", count(.!keep_social))

    Z_all = Z_all[keep_z, :, :]
    z_betas = z_betas[keep_z]
    z_sims = z_sims[keep_z]

    pair_counts_all = pair_counts_all[keep_social, :, :]
    social_betas = social_betas[keep_social]
    social_sims = social_sims[keep_social]

    n_runs, T, N = size(Z_all)

    println("  Runs retained:         ", n_runs)

    @assert z_steps == social_steps
    @assert size(pair_counts_all, 2) == T
    @assert size(pair_counts_all, 1) == length(social_sims)
    @assert length(z_sims) == n_runs
    @assert Int(ds["N"]) == N
    @assert length(pair_map) == div(N * (N - 1), 2)

    # ============================================================
    # 2. Match semantic and social files by beta + simulation ID
    # ============================================================

    social_lookup = Dict{Tuple{Float64,Int},Int}()

    for r in eachindex(social_betas)

        key = (social_betas[r], social_sims[r])

        @assert !haskey(social_lookup, key) """
        Duplicate social run: $key
        """

        social_lookup[key] = r
    end

    @assert length(unique(zip(z_betas, z_sims))) == n_runs

    # ============================================================
    # 3. Agent-level results
    # ============================================================

    agent_results = DataFrames.DataFrame(
        beta = Float64[],
        sim = Int[],
        agent = Int[],
        persistent_semantic = Bool[],
        socially_isolated = Bool[],
        lowest_social_participation = Bool[],
        final_semantic_z = Float64[],
        cumulative_interactions = Int64[],
        social_z = Float64[]
    )

    println("Analyzing $n_runs runs × $N agents = $(n_runs * N) agent-runs...")

    # ============================================================
    # 4. Analyze every agent in every run
    # ============================================================

    for r in 1:n_runs

        key = (z_betas[r], z_sims[r])

        @assert haskey(social_lookup, key) """
        Social data not found for run $key
        """

        sr = social_lookup[key]

        # --------------------------------------------------------
        # A. Cumulative interactions at end of simulation
        # --------------------------------------------------------

        interactions = zeros(Int64, N)

        final_pair_counts = @view pair_counts_all[sr, end, :]

        for p in eachindex(pair_map)

            i, j = pair_map[p]

            count_pair = Int64(final_pair_counts[p])

            interactions[i] += count_pair
            interactions[j] += count_pair
        end

        # --------------------------------------------------------
        # B. Social participation Z-score
        #    Same calculation as previous analyses
        # --------------------------------------------------------

        μ = Statistics.mean(interactions)
        σ = Statistics.std(interactions)

        social_z = if σ == 0 || !isfinite(σ)

            zeros(Float64, N)

        else

            (Float64.(interactions) .- μ) ./ σ

        end

        socially_isolated = social_z .< social_threshold

        # --------------------------------------------------------
        # C. Lowest social participation
        #    Include ALL ties at the minimum
        # --------------------------------------------------------

        minimum_interactions = minimum(interactions)

        lowest_social = interactions .== minimum_interactions

        # --------------------------------------------------------
        # D. Persistent semantic atypicality
        # --------------------------------------------------------

        persistent_semantic = falses(N)

        for agent in 1:N

            ztraj = @view Z_all[r, :, agent]

            for t in 1:T

                if ztraj[t] >= semantic_threshold &&
                   all(ztraj[t:T] .>= semantic_threshold)

                    persistent_semantic[agent] = true
                    break
                end
            end
        end

        # --------------------------------------------------------
        # E. Store ALL agents
        # --------------------------------------------------------

        for agent in 1:N

            push!(agent_results, (
                z_betas[r],
                z_sims[r],
                agent,
                persistent_semantic[agent],
                socially_isolated[agent],
                lowest_social[agent],
                Float64(Z_all[r, end, agent]),
                interactions[agent],
                social_z[agent]
            ))
        end

        if r % 250 == 0 || r == n_runs
            println("Processed $r / $n_runs runs")
        end
    end

    # ============================================================
    # 5. Sanity check
    # ============================================================

    total_agents = n_runs * N

    @assert DataFrames.nrow(agent_results) == total_agents

    println("\nTotal agent-runs: ", total_agents)

    # ============================================================
    # 6. Eight mutually exclusive Venn regions
    # ============================================================

    S = agent_results.persistent_semantic
    I = agent_results.socially_isolated
    L = agent_results.lowest_social_participation

    venn_masks = [
        S .& .!I .& .!L,       # Semantic only
        .!S .& I .& .!L,       # Social isolation only
        .!S .& .!I .& L,       # Lowest only
        S .& I .& .!L,         # Semantic + Social, not Lowest
        S .& .!I .& L,         # Semantic + Lowest, not Social
        .!S .& I .& L,         # Social + Lowest, not Semantic
        S .& I .& L,           # All three
        .!S .& .!I .& .!L      # None
    ]

    region_names = [
        "Semantic only",
        "Social isolation only",
        "Lowest participation only",
        "Semantic + Social isolation, not Lowest",
        "Semantic + Lowest, not Social isolation",
        "Social isolation + Lowest, not Semantic",
        "Semantic + Social isolation + Lowest",
        "None of the three"
    ]

    region_counts = Int[
        sum(mask) for mask in venn_masks
    ]

    @assert sum(region_counts) == total_agents

    venn_regions = DataFrames.DataFrame(
        region = region_names,
        n_agents = region_counts,
        percentage = 100 .* region_counts ./ total_agents
    )

    # ============================================================
    # 7. Group sizes and intersections
    # ============================================================

    n_semantic = sum(S)
    n_social = sum(I)
    n_lowest = sum(L)

    n_semantic_social = sum(S .& I)
    n_semantic_lowest = sum(S .& L)
    n_social_lowest = sum(I .& L)

    n_all_three = sum(S .& I .& L)

    summary = DataFrames.DataFrame(
        measure = [
            "Total agents",
            "Persistent semantic outliers",
            "Socially isolated agents (SP < -2.5)",
            "Lowest-social-participation agents",
            "Semantic ∩ Social isolation",
            "Semantic ∩ Lowest",
            "Social isolation ∩ Lowest",
            "Semantic ∩ Social isolation ∩ Lowest"
        ],

        n_agents = [
            total_agents,
            n_semantic,
            n_social,
            n_lowest,
            n_semantic_social,
            n_semantic_lowest,
            n_social_lowest,
            n_all_three
        ],

        percentage_of_all_agents = 100 .* [
            total_agents,
            n_semantic,
            n_social,
            n_lowest,
            n_semantic_social,
            n_semantic_lowest,
            n_social_lowest,
            n_all_three
        ] ./ total_agents
    )

    # ============================================================
    # 8. Output
    # ============================================================

    println("\n========== 8 MUTUALLY EXCLUSIVE VENN REGIONS ==========")
    display(venn_regions)

    println("\n========== GROUP SIZES AND INTERSECTIONS ==========")
    display(summary)

    return (
        venn_regions = venn_regions,
        summary = summary,
        agents = agent_results
    )

end
# venn_results = analyze_agent_level_venn(
#     joinpath(
#         "sweep_beta_logs",
#         "ALL_ZSCORES_OVER_TIME.jld2"
#     ),
#     joinpath(
#         "sweep_beta_logs",
#         "ALL_CUMPAIR_TALKS_SAMPLED.jld2"
#     )
# )
# venn_results.summary
function plot_semantic_social_venn(
    venn_results;
    title::String = "Semantic Atypicality and Social Isolation",
    size = (950, 650))

    df = venn_results.agents
    format_n(x) = replace(string(x), r"(?<=\d)(?=(\d{3})+$)" => ",")

    # ============================================================
    # 1. Existing classifications
    # ============================================================

    S = df.persistent_semantic
    I = df.socially_isolated

    semantic_total = sum(S)
    social_total = sum(I)

    both = sum(S .& I)
    semantic_only = sum(S .& .!I)
    social_only = sum(.!S .& I)

    total_agents = DataFrames.nrow(df)
    neither = sum(.!S .& .!I)

    @assert semantic_only + social_only + both + neither == total_agents
    @assert semantic_only + both == semantic_total
    @assert social_only + both == social_total

    # ============================================================
    # 2. Area-proportional radii
    # ============================================================

    r_semantic = sqrt(semantic_total / π)
    r_social = sqrt(social_total / π)

    # ============================================================
    # 3. Circle-overlap area
    # ============================================================

    function overlap_area(r1, r2, d)

        if d >= r1 + r2
            return 0.0
        end

        if d <= abs(r1 - r2)
            return π * min(r1, r2)^2
        end

        term1 = r1^2 * acos(
            clamp(
                (d^2 + r1^2 - r2^2) / (2 * d * r1),
                -1.0,
                1.0
            )
        )

        term2 = r2^2 * acos(
            clamp(
                (d^2 + r2^2 - r1^2) / (2 * d * r2),
                -1.0,
                1.0
            )
        )

        term3 = 0.5 * sqrt(
            max(
                0.0,
                (-d + r1 + r2) *
                ( d + r1 - r2) *
                ( d - r1 + r2) *
                ( d + r1 + r2)
            )
        )

        return term1 + term2 - term3
    end

    # ============================================================
    # 4. Find center distance
    # ============================================================

    target_overlap = Float64(both)

    min_d = abs(r_semantic - r_social)
    max_d = r_semantic + r_social

    if target_overlap >= π * min(r_semantic, r_social)^2

        d = min_d

    elseif target_overlap <= 0

        d = max_d

    else

        lo = min_d
        hi = max_d

        for _ in 1:100

            mid = (lo + hi) / 2

            current_overlap = overlap_area(
                r_semantic,
                r_social,
                mid
            )

            if current_overlap > target_overlap
                lo = mid
            else
                hi = mid
            end
        end

        d = (lo + hi) / 2
    end

    # ============================================================
    # 5. Circle positions
    # ============================================================

    x_semantic = 0.0
    y_semantic = 0.0

    x_social = d
    y_social = 0.0

    θ = range(0, 2π, length = 800)

    semantic_x =
        x_semantic .+ r_semantic .* cos.(θ)

    semantic_y =
        y_semantic .+ r_semantic .* sin.(θ)

    social_x =
        x_social .+ r_social .* cos.(θ)

    social_y =
        y_social .+ r_social .* sin.(θ)

    # ============================================================
    # 6. Plot limits
    # ============================================================

    xmin = x_semantic - r_semantic
    xmax_circles = x_social + r_social

    ymax = max(r_semantic, r_social)

    plot_width = xmax_circles - xmin

    x_right = xmax_circles + 0.68 * plot_width

    # ============================================================
    # 7. Colors
    # ============================================================

    semantic_color = "#4A90D9"
    social_color = "#E67E22"

    # ============================================================
    # 8. Base plot
    # ============================================================

    p = Plots.plot(
        xlim = (
            xmin - 0.10 * plot_width,
            x_right
        ),
        ylim = (
            -1.20 * ymax,
            1.20 * ymax
        ),
        aspect_ratio = :equal,
        axis = false,
        grid = false,
        framestyle = :none,
        legend = :bottomright,
        legendfontsize = 11,
        size = size,
        title = title,
        titlefontsize = 17,
        fontfamily = "Calibri",
        margin = 5Plots.mm
    )

    # ============================================================
    # 9. Semantic circle
    # ============================================================

    Plots.plot!(
        p,
        semantic_x,
        semantic_y,
        seriestype = :shape,
        fillcolor = semantic_color,
        fillalpha = 0.45,
        linecolor = semantic_color,
        linewidth = 2,
        label = "Persistent semantic atypicality (N = $(format_n(semantic_total)))"
    )
    # ============================================================
    # 10. Social-isolation circle
    # ============================================================

    Plots.plot!(
        p,
        social_x,
        social_y,
        seriestype = :shape,
        fillcolor = social_color,
        fillalpha = 0.45,
        linecolor = social_color,
        linewidth = 2,
        label = "Social isolation (N = $(format_n(social_total)))"
    )

    # ============================================================
    # 11. Semantic-only count
    # ============================================================

    semantic_only_x =
        x_semantic - 0.43 * r_semantic

    Plots.annotate!(
        p,
        semantic_only_x,
        0.0,
        Plots.text(
            format_n(semantic_only),
            18,
            :black,
            :center
        )
    )

    # ============================================================
    # 12. Overlap count
    # ============================================================

    overlap_left =
        max(
            x_semantic - r_semantic,
            x_social - r_social
        )

    overlap_right =
        min(
            x_semantic + r_semantic,
            x_social + r_social
        )

    overlap_x =
        (overlap_left + overlap_right) / 2

    Plots.annotate!(
        p,
        overlap_x,
        0.0,
        Plots.text(
            format_n(both),
            18,
            :black,
            :center
        )
    )

    # ============================================================
    # Social-only callout
    # ============================================================

    # Point inside the very small social-only region
    target_x =
        x_social + 0.97 * r_social

    target_y = 0.0

    # External label — slightly to the right
    label_x =
        x_social + 1.75 * r_social

    label_y =
        0.24 * r_social

    # Subtle callout line
    Plots.plot!(
        p,
        [target_x, label_x - 0.14 * r_social],
        [target_y, label_y],
        color = :black,
        alpha = 0.55,
        linewidth = 0.9,
        label = ""
    )

    # Number only — no marker
    Plots.annotate!(
        p,
        label_x,
        label_y,
        Plots.text(
            format_n(social_only),
            16,
            :black,
            :center
        )
    )
    # ============================================================
    # 14. Print exact values
    # ============================================================

    println("\n========== TWO-SET AGENT-LEVEL VENN ==========")
    println("Total agent-runs:              ", total_agents)
    println("Persistent semantic total:     ", semantic_total)
    println("Social isolation total:        ", social_total)
    println("Semantic only:                 ", semantic_only)
    println("Social isolation only:         ", social_only)
    println("Both:                          ", both)
    println("Neither:                       ", neither)

    return p
end
