# Prediction
z_path=raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_ZSCORES_OVER_TIME.jld2"

function plot_future_persistent_outlier_paper(
    z_path::String;
    threshold::Real = 2.5,
    by_beta::Bool = false,
    fontfamily::String = "Calibri",
    plot_size::Tuple{Int,Int} = (950, 650))

    # ============================================================
    # 1. LOAD
    # ============================================================

    println("\nLoading Z-score file...")

    d = JLD2.load(z_path)

    Z_all = d["Z_all"]
    steps_axis = Int.(d["steps_axis"])

    @assert ndims(Z_all) == 3

    n_runs = size(Z_all, 1)
    n_timepoints = size(Z_all, 2)
    N = size(Z_all, 3)

    @assert length(steps_axis) == n_timepoints

    chance_probability = 1.0 / N

    println("Runs:        ", n_runs)
    println("Timepoints:  ", n_timepoints)
    println("Agents:      ", N)
    println("Threshold:   ", threshold)
    println(
        "Top-1 chance level: ",
        round(100.0 * chance_probability; digits = 2),
        "%"
    )


    # ============================================================
    # 2. EXCLUDE BETA <= 0
    # ============================================================

    haskey(d, "beta_value") ||
        error("The file does not contain beta_value.")

    beta_value = Float64.(vec(d["beta_value"]))

    @assert length(beta_value) == n_runs

    keep_mask_beta = beta_value .> 0.0

    println()
    println("Excluding beta <= 0 runs...")
    println("  Runs removed:  ", count(.!keep_mask_beta))

    Z_all = Z_all[keep_mask_beta, :, :]
    beta_value = beta_value[keep_mask_beta]

    n_runs = size(Z_all, 1)

    println("  Runs retained: ", n_runs)

    n_runs > 0 ||
        error("No runs remain after excluding beta <= 0.")

    if by_beta
        println(
            "Beta values: ",
            sort(unique(beta_value))
        )
    end


    # ============================================================
    # 3. FIND RUNS WITH EXACTLY ONE PERSISTENT OUTLIER
    # ============================================================

    println()
    println("Finding runs with exactly one persistent outlier...")

    persistent_runs = Int[]
    persistent_agents = Int[]
    persistent_crossing_steps = Int[]


    for run_idx in 1:n_runs

        run_persistent_agents = Int[]
        run_crossing_indices = Int[]

        for agent in 1:N

            ztraj =
                @view Z_all[
                    run_idx,
                    :,
                    agent
                ]

            first_crossing_idx = 0

            for t_idx in 1:n_timepoints

                if ztraj[t_idx] >= threshold

                    remains_above = true

                    for future_idx in t_idx:n_timepoints

                        if ztraj[future_idx] < threshold

                            remains_above = false
                            break
                        end
                    end

                    if remains_above

                        first_crossing_idx = t_idx
                        break
                    end
                end
            end

            if first_crossing_idx > 0

                push!(
                    run_persistent_agents,
                    agent
                )

                push!(
                    run_crossing_indices,
                    first_crossing_idx
                )
            end
        end


        # --------------------------------------------------------
        # Keep only runs with EXACTLY one persistent outlier
        # --------------------------------------------------------

        if length(run_persistent_agents) == 1

            push!(
                persistent_runs,
                run_idx
            )

            push!(
                persistent_agents,
                run_persistent_agents[1]
            )

            push!(
                persistent_crossing_steps,
                steps_axis[
                    run_crossing_indices[1]
                ]
            )
        end
    end


    n_persistent =
        length(persistent_runs)


    if n_persistent == 0

        error(
            "No runs with exactly one persistent outlier were found."
        )
    end


    println(
        "Runs with exactly one persistent outlier: ",
        n_persistent,
        " / ",
        n_runs,
        " (",
        round(
            100.0 * n_persistent / n_runs;
            digits = 2
        ),
        "%)"
    )


    # ============================================================
    # 4. IDENTIFY AND EXCLUDE STEP-0 FIRST-PLACE TIES
    #
    # Any run with more than one agent sharing the maximum Z
    # at step 0 is removed from ALL subsequent analyses.
    # ============================================================

    println()
    println("Checking first-place ties at step ", steps_axis[1], "...")


    step0_tie_size =
        zeros(
            Int,
            n_persistent
        )


    for selected_idx in 1:n_persistent

        run_idx =
            persistent_runs[selected_idx]

        z0 =
            Float64.(
                vec(
                    Z_all[
                        run_idx,
                        1,
                        :
                    ]
                )
            )

        max_z =
            maximum(z0)

        step0_tie_size[selected_idx] =
            count(
                z -> z == max_z,
                z0
            )
    end


    tie_mask =
        step0_tie_size .> 1

    n_tied_runs =
        count(tie_mask)


    println()
    println("="^80)
    println("STEP-0 FIRST-PLACE TIES")
    println("="^80)

    println(
        "Runs with a first-place tie at step ",
        steps_axis[1],
        ": ",
        n_tied_runs,
        " / ",
        n_persistent,
        " (",
        round(
            100.0 * n_tied_runs / n_persistent;
            digits = 2
        ),
        "%)"
    )


    # ------------------------------------------------------------
    # Print tie-size distribution
    # ------------------------------------------------------------

    if n_tied_runs > 0

        tie_sizes =
            sort(
                unique(
                    step0_tie_size[
                        tie_mask
                    ]
                )
            )

        println()
        println("Tie-size breakdown:")

        for tie_size in tie_sizes

            n_this_size =
                count(
                    step0_tie_size .== tie_size
                )

            println(
                "  ",
                tie_size,
                " agents tied for first: ",
                n_this_size,
                " runs"
            )
        end
    else

        println("No first-place ties at step 0.")
    end


    # ============================================================
    # 5. REMOVE STEP-0 TIE RUNS
    # ============================================================

    keep_mask =
        .!tie_mask


    selected_runs =
        persistent_runs[
            keep_mask
        ]

    target_agents =
        persistent_agents[
            keep_mask
        ]

    target_crossing_steps =
        persistent_crossing_steps[
            keep_mask
        ]


    n_selected =
        length(selected_runs)


    if n_selected == 0

        error(
            "No runs remain after excluding step-0 ties."
        )
    end


    println()
    println("="^80)
    println("FINAL ANALYSIS SAMPLE")
    println("="^80)

    println(
        "Included runs: ",
        n_selected,
        " / ",
        n_persistent,
        " eligible persistent-outlier runs"
    )

    println(
        "Excluded because of step-0 tie: ",
        n_tied_runs
    )


    # ============================================================
    # 6. TOP-1 STATUS ACROSS TIME
    #
    # Later ties ARE allowed.
    #
    # If the future persistent outlier shares the maximum Z
    # with one or more other agents, it counts as Top 1.
    # ============================================================

    println()
    println("Calculating Top-1 probability across time...")


    target_is_top1 =
        falses(
            n_selected,
            n_timepoints
        )


    for selected_idx in 1:n_selected

        run_idx =
            selected_runs[selected_idx]

        target_agent =
            target_agents[selected_idx]


        for t_idx in 1:n_timepoints

            z_now =
                @view Z_all[
                    run_idx,
                    t_idx,
                    :
                ]

            max_z =
                maximum(z_now)

            target_is_top1[
                selected_idx,
                t_idx
            ] =
                z_now[target_agent] == max_z
        end
    end


    # ============================================================
    # 7. STEP-0 EXACT BINOMIAL TEST
    # ============================================================

    function exact_binomial_ci(
        x::Int,
        n::Int;
        alpha::Float64 = 0.05
    )

        lower =
            x == 0 ?
            0.0 :
            Distributions.quantile(
                Distributions.Beta(
                    x,
                    n - x + 1
                ),
                alpha / 2
            )

        upper =
            x == n ?
            1.0 :
            Distributions.quantile(
                Distributions.Beta(
                    x + 1,
                    n - x
                ),
                1.0 - alpha / 2
            )

        return (
            lower = lower,
            upper = upper
        )
    end

    function exact_step0_test(
        top1_matrix::AbstractMatrix{Bool},
        label::String
    )

        n =
            size(
                top1_matrix,
                1
            )

        if n == 0

            return (
                label = label,
                n = 0,
                observed = 0,
                probability = NaN,
                chance = chance_probability,
                p_value = NaN
            )
        end


        observed =
            count(
                top1_matrix[:, 1]
            )

        observed_probability =
            observed / n
        
        ci95 =
            exact_binomial_ci(
                observed,
                n;
                alpha = 0.05
            )


        binom =
            Distributions.Binomial(
                n,
                chance_probability
            )


        # One-sided:
        #
        # H0: p = 1/N
        # H1: p > 1/N
        #
        # P(K >= observed)

        p_value =
            Distributions.ccdf(
                binom,
                observed - 1
            )


        return (
            label = label,
            n = n,
            observed = observed,
            probability = observed_probability,
            chance = chance_probability,
            ci95_low = ci95.lower,
            ci95_high = ci95.upper,
            p_value = p_value
        )
    end


    # ============================================================
    # 8. ANALYSIS WITHOUT BETA SPLIT
    # ============================================================

    if !by_beta

        probability_by_step =
            vec(
                Statistics.mean(
                    target_is_top1;
                    dims = 1
                )
            )


        step0_test =
            exact_step0_test(
                target_is_top1,
                "All runs"
            )


        println()
        println("="^80)
        println("EXACT ONE-SIDED BINOMIAL TEST AT STEP ", steps_axis[1])
        println("H1: probability > chance")
        println("="^80)

        println(
            "Observed: ",
            step0_test.observed,
            " / ",
            step0_test.n,
            " (",
            round(
                100.0 * step0_test.probability;
                digits = 2
            ),
            "%)"
        )

        println(
            "95% exact binomial CI: [",
            round(
                100.0 * step0_test.ci95_low;
                digits = 2
            ),
            "%, ",
            round(
                100.0 * step0_test.ci95_high;
                digits = 2
            ),
            "%]"
        )

        println(
            "Chance:   ",
            round(
                100.0 * chance_probability;
                digits = 2
            ),
            "%"
        )

        println(
            "Exact one-sided p = ",
            round(
                step0_test.p_value;
                digits = 6
            )
        )


        # --------------------------------------------------------
        # Results table
        # --------------------------------------------------------

        results =
            DataFrames.DataFrame(
                step =
                    steps_axis,

                probability =
                    probability_by_step,

                n_runs =
                    fill(
                        n_selected,
                        n_timepoints
                    )
            )


        step0_tests =
            DataFrames.DataFrame(
                beta =
                    Union{Missing,Float64}[
                        missing
                    ],

                n_runs =
                    [
                        step0_test.n
                    ],

                n_top1 =
                    [
                        step0_test.observed
                    ],

                observed_probability =
                    [
                        step0_test.probability
                    ],

                chance_probability =
                    [
                        chance_probability
                    ],

                p_value_one_sided =
                    [
                        step0_test.p_value
                    ]
            )


        # --------------------------------------------------------
        # Plot
        # --------------------------------------------------------

        tick_positions =
            collect(
                0:2000:maximum(steps_axis)
            )

        tick_labels =
            string.(
                tick_positions
            )


        current_color =
            Plots.palette(
                :auto,
                1
            )[1]


        p =
            Plots.plot(
                ;
                xlabel =
                    "Simulation Step",

                ylabel =
                    "Probability that the Future Persistent Outlier is Most Semantically Atypical",

                title =
                    "Early Identification of the Future Persistent Outlier",

                xticks =
                    (
                        tick_positions,
                        tick_labels
                    ),

                ylim =
                    (0.0, 1.0),

                framestyle =
                    :box,

                grid =
                    false,

                fontfamily =
                    fontfamily,

                size =
                    plot_size,

                legend = (0.08, 0.90),

                top_margin =
                    8Plots.mm
            )


        # Chance first so observed line remains visually prominent
        Plots.hline!(
            p,
            [
                chance_probability
            ];

            color =
                current_color,

            linestyle =
                :dash,

            linewidth =
                2.0,

            alpha =
                0.8,

            label =
                "Chance level ($(round(Int, 100 * chance_probability))%)"
        )


        Plots.plot!(
            p,
            steps_axis,
            probability_by_step;

            color =
                current_color,

            linewidth =
                2.5,

            label =
                "Observed probability"
        )


        display(p)


        return (
            plot =
                p,

            results =
                results,

            step0_tests =
                step0_tests,

            selected_runs =
                selected_runs,

            target_agents =
                target_agents,

            target_crossing_steps =
                target_crossing_steps,

            target_is_top1 =
                target_is_top1,

            excluded_tie_runs =
                persistent_runs[
                    tie_mask
                ],

            excluded_tie_sizes =
                step0_tie_size[
                    tie_mask
                ],

            n_persistent =
                n_persistent,

            n_excluded_ties =
                n_tied_runs,

            n_selected =
                n_selected
        )
    end


    # ============================================================
    # 9. ANALYSIS SPLIT BY BETA
    # ============================================================

    selected_beta =
        beta_value[
            selected_runs
        ]


    beta_levels =
        sort(
            unique(
                selected_beta
            )
        )


    println()
    println("="^80)
    println("ANALYSIS BY BETA")
    println("="^80)


    # ------------------------------------------------------------
    # Long-form trajectory table
    # ------------------------------------------------------------

    result_beta =
        Float64[]

    result_step =
        Int[]

    result_probability =
        Float64[]

    result_n =
        Int[]


    # ------------------------------------------------------------
    # Step-0 test table
    # ------------------------------------------------------------

    test_beta =
        Float64[]

    test_n =
        Int[]

    test_top1 =
        Int[]

    test_probability =
        Float64[]

    test_chance =
        Float64[]

    test_p =
        Float64[]


    probability_by_beta =
        Dict{Float64,Vector{Float64}}()


    for beta in beta_levels

        beta_mask =
            selected_beta .== beta

        beta_matrix =
            target_is_top1[
                beta_mask,
                :
            ]

        n_beta =
            size(
                beta_matrix,
                1
            )


        probability_beta =
            vec(
                Statistics.mean(
                    beta_matrix;
                    dims = 1
                )
            )


        probability_by_beta[beta] =
            probability_beta


        for t_idx in 1:n_timepoints

            push!(
                result_beta,
                beta
            )

            push!(
                result_step,
                steps_axis[t_idx]
            )

            push!(
                result_probability,
                probability_beta[t_idx]
            )

            push!(
                result_n,
                n_beta
            )
        end


        test =
            exact_step0_test(
                beta_matrix,
                "β = $beta"
            )


        push!(
            test_beta,
            beta
        )

        push!(
            test_n,
            test.n
        )

        push!(
            test_top1,
            test.observed
        )

        push!(
            test_probability,
            test.probability
        )

        push!(
            test_chance,
            test.chance
        )

        push!(
            test_p,
            test.p_value
        )


        println()
        println("β = ", beta)

        println(
            "  Included runs: ",
            test.n
        )

        println(
            "  Step-0 Top 1:  ",
            test.observed,
            " / ",
            test.n,
            " (",
            round(
                100.0 * test.probability;
                digits = 2
            ),
            "%)"
        )

        println(
            "  Chance:        ",
            round(
                100.0 * chance_probability;
                digits = 2
            ),
            "%"
        )

        println(
            "  One-sided p:   ",
            round(
                test.p_value;
                digits = 6
            )
        )
    end


    results =
        DataFrames.DataFrame(
            beta =
                result_beta,

            step =
                result_step,

            probability =
                result_probability,

            n_runs =
                result_n
        )


    step0_tests =
        DataFrames.DataFrame(
            beta =
                test_beta,

            n_runs =
                test_n,

            n_top1 =
                test_top1,

            observed_probability =
                test_probability,

            chance_probability =
                test_chance,

            p_value_one_sided =
                test_p
        )


    # ============================================================
    # 10. BETA-SPLIT PLOT
    # ============================================================

    tick_positions =
        collect(
            0:2000:maximum(steps_axis)
        )

    tick_labels =
        string.(
            tick_positions
        )


    beta_colors =
        Plots.palette(
            :auto,
            length(beta_levels)
        )


    p =
        Plots.plot(
            ;
            xlabel =
                "Simulation Step",

            ylabel =
                "Probability that the Future Persistent Outlier is Most Semantically Atypical",

            title =
                "Early Identification of the Future Persistent Outlier",

            xticks =
                (
                    tick_positions,
                    tick_labels
                ),

            ylim =
                (0.0, 1.0),

            framestyle =
                :box,

            grid =
                false,

            fontfamily =
                fontfamily,

            size =
                plot_size,

            legend =
                (0.05, 0.93),

            top_margin =
                8Plots.mm
        )


    # ------------------------------------------------------------
    # Chance level
    # ------------------------------------------------------------

    Plots.hline!(
        p,
        [
            chance_probability
        ];

        color =
            :black,

        linestyle =
            :dash,

        linewidth =
            2.0,

        alpha =
            0.7,

        label =
            "Chance level ($(round(Int, 100 * chance_probability))%)"
    )


    # ------------------------------------------------------------
    # One trajectory per beta
    # ------------------------------------------------------------

    for (beta_idx, beta) in enumerate(beta_levels)

        Plots.plot!(
            p,
            steps_axis,
            probability_by_beta[beta];

            color =
                beta_colors[beta_idx],

            linewidth =
                2.5,

            label =
                "β = $beta"
        )
    end


    display(p)


    # ============================================================
    # 11. RETURN
    # ============================================================

    return (
        plot =
            p,

        results =
            results,

        step0_tests =
            step0_tests,

        probability_by_beta =
            probability_by_beta,

        beta_levels =
            beta_levels,

        selected_runs =
            selected_runs,

        selected_beta =
            selected_beta,

        target_agents =
            target_agents,

        target_crossing_steps =
            target_crossing_steps,

        target_is_top1 =
            target_is_top1,

        excluded_tie_runs =
            persistent_runs[
                tie_mask
            ],

        excluded_tie_sizes =
            step0_tie_size[
                tie_mask
            ],

        n_persistent =
            n_persistent,

        n_excluded_ties =
            n_tied_runs,

        n_selected =
            n_selected
    )
end
