function analyze_top1_ties(
    z_path::String;
    progress_every::Int = 500)

    # ============================================================
    # 1. LOAD DATA
    # ============================================================

    println("\nLoading Z-score data...")

    d = JLD2.load(z_path)

    Z_all = d["Z_all"]
    steps_axis = Int.(d["steps_axis"])
    beta_value = Float64.(vec(d["beta_value"]))

    @assert ndims(Z_all) == 3

    n_runs = size(Z_all, 1)
    n_timepoints = size(Z_all, 2)
    N = size(Z_all, 3)

    @assert length(steps_axis) == n_timepoints
    @assert length(beta_value) == n_runs
    @assert progress_every > 0

    # ============================================================
    # 2. EXCLUDE BETA <= 0
    # ============================================================

    keep_mask = beta_value .> 0.0

    original_run_indices = findall(keep_mask)

    println()
    println("Excluding beta <= 0 runs...")
    println("  Runs removed:  ", count(.!keep_mask))

    Z_all = Z_all[keep_mask, :, :]
    beta_value = beta_value[keep_mask]

    n_runs = size(Z_all, 1)

    println("  Runs retained: ", n_runs)

    n_runs > 0 ||
        error("No runs remain after excluding beta <= 0.")

    # Use actual simulation IDs if available
    if haskey(d, "sim")

        simulation_ids =
            Int.(vec(d["sim"]))[keep_mask]

    else

        simulation_ids =
            original_run_indices

    end

    # ============================================================
    # 3. FIND RUNS WITH EXACTLY ONE PERSISTENT OUTLIER
    # ============================================================

    println()
    println("Finding runs with exactly one persistent outlier...")

    selected_indices = Int[]

    for r in 1:n_runs

        n_persistent = 0

        for agent in 1:N

            ztraj = @view Z_all[r, :, agent]

            if ztraj[end] >= 2.5
                n_persistent += 1
            end

        end

        if n_persistent == 1
            push!(selected_indices, r)
        end
    end

    println("Runs with exactly one persistent outlier: ",
            length(selected_indices), " / ", n_runs)

    # ============================================================
    # 4. CHECK TOP-1 TIES IN SELECTED RUNS
    # ============================================================

    tie_beta = Float64[]
    tie_simulation = Int[]
    tie_run_index = Int[]
    tie_step = Int[]
    tie_max_z = Float64[]
    tie_size = Int[]
    tie_agents = Vector{Int}[]

    ties_per_step = zeros(Int, n_timepoints)

    n_selected = length(selected_indices)

    println()
    println("Checking Top-1 ties...")

    for (i, r) in enumerate(selected_indices)

        for t in 1:n_timepoints

            z_now = @view Z_all[r, t, :]

            max_z = maximum(z_now)

            tied_agents = findall(==(max_z), z_now)

            if length(tied_agents) > 1

                push!(tie_beta, beta_value[r])
                push!(tie_simulation, simulation_ids[r])
                push!(tie_run_index, original_run_indices[r])
                push!(tie_step, steps_axis[t])
                push!(tie_max_z, Float64(max_z))
                push!(tie_size, length(tied_agents))
                push!(tie_agents, Int.(tied_agents))

                ties_per_step[t] += 1
            end
        end

        if i == 1 ||
           i % progress_every == 0 ||
           i == n_selected

            println("  Run $i / $n_selected")
        end
    end

    # ============================================================
    # 5. DETAILED TABLE
    # ============================================================

    tie_details = DataFrames.DataFrame(
        beta = tie_beta,
        simulation = tie_simulation,
        run_index = tie_run_index,
        step = tie_step,
        max_z = tie_max_z,
        n_tied_agents = tie_size,
        tied_agents = tie_agents
    )

    DataFrames.sort!(
        tie_details,
        [:beta, :simulation, :step]
    )

    # ============================================================
    # 6. SUMMARY BY TIMEPOINT
    # ============================================================

    step_summary = DataFrames.DataFrame(
        step = steps_axis,
        n_runs_with_tie = ties_per_step,
        pct_runs_with_tie =
            100.0 .* ties_per_step ./ n_selected
    )

    # Keep only steps where at least one tie occurred
    step_summary = step_summary[
        step_summary.n_runs_with_tie .> 0,
        :
    ]

    # ============================================================
    # 7. OVERALL SUMMARY
    # ============================================================

    runs_with_ties =
        unique(tie_details.run_index)

    n_runs_with_ties =
        length(runs_with_ties)

    n_tie_events =
        DataFrames.nrow(tie_details)

    println()
    println("="^80)
    println("TOP-1 SEMANTIC ATYPICALITY TIES")
    println("="^80)

    println("Runs analyzed:                ", n_runs)
    println("Agents per run:               ", N)
    println("Timepoints per run:           ", n_timepoints)
    println("Total tie events:             ", n_tie_events)
    println("Runs with at least one tie:   ", n_runs_with_ties)
    println(
        "Percentage of runs with ties: ",
        round(100.0 * n_runs_with_ties / n_runs; digits = 3),
        "%"
    )

    # ============================================================
    # 8. PRINT DETAILED RESULTS
    # ============================================================

    println()
    println("="^80)
    println("DETAILED TIE EVENTS")
    println("="^80)

    if n_tie_events == 0

        println("No Top-1 ties were found.")

    else

        show(
            stdout,
            tie_details;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    # ============================================================
    # 9. PRINT SUMMARY BY STEP
    # ============================================================

    println()
    println("="^80)
    println("TIES BY SIMULATION STEP")
    println("="^80)

    if DataFrames.nrow(step_summary) == 0

        println("No timepoints with Top-1 ties.")

    else

        show(
            stdout,
            step_summary;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    # ============================================================
    # 10. RETURN
    # ============================================================

    return (
        tie_details = tie_details,
        step_summary = step_summary,
        n_runs = n_runs,
        n_runs_with_ties = n_runs_with_ties,
        n_tie_events = n_tie_events
    )
end
# top1_tie_results = analyze_top1_ties(z_path)

# Trajectory 
function plot_ranked_z_trajectories_by_crossing_no_beta0(
    z_path::String;
    threshold::Float64 = 3.0,
    ranks_to_plot = nothing,
    ribbon_alpha::Float64 = 0.18,
    lw::Float64 = 2.5)

    d = JLD2.load(z_path)

    @assert haskey(d, "Z_all") "Missing key: Z_all"
    @assert haskey(d, "steps_axis") "Missing key: steps_axis"
    @assert haskey(d, "beta_value") "Missing key: beta_value"

    Z_all_full = d["Z_all"]                    # runs × T × N
    steps_axis = Int.(d["steps_axis"])         # length = T
    beta_value_full = Float64.(d["beta_value"])

    @assert size(Z_all_full, 1) == length(beta_value_full) "beta_value length does not match number of runs"

    # ============================================================
    # Remove beta = 0 runs
    # ============================================================

    keep_runs = findall(!=(0.0), beta_value_full)

    Z_all = Z_all_full[keep_runs, :, :]
    beta_value = beta_value_full[keep_runs]

    n_removed = length(beta_value_full) - length(keep_runs)

    println("Removing beta = 0 runs...")
    println("  Total runs before filtering: ", length(beta_value_full))
    println("  Beta = 0 runs removed:       ", n_removed)
    println("  Runs retained:               ", length(keep_runs))

    n_runs, T, N = size(Z_all)

    if ranks_to_plot === nothing
        ranks_to_plot = collect(1:N)
    else
        ranks_to_plot = collect(ranks_to_plot)
        @assert all(1 .<= ranks_to_plot .<= N) "All ranks_to_plot values must be between 1 and $N"
    end

    function persistent_crossing_info_for_run(
        z_run::AbstractMatrix{<:Real},
        threshold::Float64)

        T, N = size(z_run)

        best_t = typemax(Int)
        best_agent = 0

        for i in 1:N
            ztraj = @view z_run[:, i]

            t0 = 0
            sustained = true

            for t in T:-1:1
                sustained &= (ztraj[t] >= threshold)

                if sustained
                    t0 = t
                end
            end

            if t0 != 0 && t0 < best_t
                best_t = t0
                best_agent = i
            end
        end

        return (
            crossed = best_agent != 0,
            first_cross_t_index = best_agent == 0 ? missing : best_t,
            first_cross_agent = best_agent == 0 ? missing : best_agent
        )
    end

    crossed_mask = falses(n_runs)

    for r in 1:n_runs
        z_run = Array{Float64}(Z_all[r, :, :])   # T × N

        info =
            persistent_crossing_info_for_run(
                z_run,
                threshold
            )

        crossed_mask[r] = info.crossed
    end

    crossed_runs = findall(crossed_mask)
    noncrossed_runs = findall(.!crossed_mask)
    all_runs = collect(1:n_runs)

    function compute_rank_summary(run_inds::Vector{Int})

        n_sel = length(run_inds)

        if n_sel == 0
            return (
                mean_ranked = fill(NaN, T, N),
                sd_ranked = fill(NaN, T, N),
                n_runs = 0
            )
        end

        ranked_vals =
            Array{Float64}(undef, n_sel, T, N)

        for (k, r) in enumerate(run_inds)

            z_run =
                Array{Float64}(Z_all[r, :, :])   # T × N

            for t in 1:T
                vals = vec(z_run[t, :])

                ranked_vals[k, t, :] =
                    sort(vals; rev = true)
            end
        end

        mean_ranked =
            dropdims(
                Statistics.mean(
                    ranked_vals;
                    dims = 1
                ),
                dims = 1
            )

        sd_ranked =
            if n_sel > 1

                dropdims(
                    Statistics.std(
                        ranked_vals;
                        dims = 1
                    ),
                    dims = 1
                )

            else
                fill(0.0, T, N)
            end

        return (
            mean_ranked = mean_ranked,
            sd_ranked = sd_ranked,
            n_runs = n_sel
        )
    end

    crossed_summary =
        compute_rank_summary(crossed_runs)

    noncrossed_summary =
        compute_rank_summary(noncrossed_runs)

    all_summary =
        compute_rank_summary(all_runs)

    # Gradient: visible, but not too bright
    grad_positions =
        collect(
            range(
                0.22,
                0.88;
                length = N
            )
        )

    colors =
        [
            get(
                Plots.cgrad(:viridis),
                x
            )
            for x in grad_positions
        ]

    function make_rank_plot(
        summary,
        group_label::String;
        total_runs::Int)

        p = Plots.plot(
            xlabel = "Simulation step",
            ylabel = "Mean semantic distance by rank (z-score)",
            title = "Trajectories of mean semantic distance by rank across runs",
            xformatter = :plain,
            legend = false,
            fontfamily = "Calibri",
            titlefont = Plots.font(17, "Calibri", :bold),
            xguidefontsize = 13,
            yguidefontsize = 13,
            xtickfontsize = 11,
            ytickfontsize = 11,
            grid = false,
            framestyle = :axes,
            tick_direction = :out,
            size = (1050, 650)
        )

        if summary.n_runs == 0

            Plots.annotate!(
                p,
                steps_axis[1] +
                0.015 *
                (steps_axis[end] - steps_axis[1]),
                0.0,
                Plots.text(
                    "$(group_label)\nn = 0 / $total_runs",
                    12,
                    "Calibri",
                    :left
                )
            )

            return p
        end

        for rank in ranks_to_plot

            μ =
                summary.mean_ranked[:, rank]

            σ =
                summary.sd_ranked[:, rank]

            Plots.plot!(
                p,
                steps_axis,
                μ;
                ribbon = σ,
                fillalpha = ribbon_alpha,
                lw = lw,
                color = colors[rank],
                alpha = 0.95,
                label = false
            )
        end

        Plots.hline!(
            p,
            [0.0];
            linestyle = :dash,
            color = :black,
            alpha = 0.5,
            label = false
        )

        Plots.hline!(
            p,
            [threshold];
            linestyle = :dash,
            color = :red,
            alpha = 0.5,
            label = false
        )

        finite_vals =
            vcat(
                vec(
                    summary.mean_ranked[
                        :,
                        ranks_to_plot
                    ]
                ),
                vec(
                    summary.mean_ranked[
                        :,
                        ranks_to_plot
                    ] .+
                    summary.sd_ranked[
                        :,
                        ranks_to_plot
                    ]
                ),
                vec(
                    summary.mean_ranked[
                        :,
                        ranks_to_plot
                    ] .-
                    summary.sd_ranked[
                        :,
                        ranks_to_plot
                    ]
                )
            )

        finite_vals =
            finite_vals[
                isfinite.(finite_vals)
            ]

        y_top =
            isempty(finite_vals) ?
            threshold + 1.0 :
            maximum(finite_vals)

        y_bottom =
            isempty(finite_vals) ?
            -1.0 :
            minimum(finite_vals)

        y_pos =
            y_top -
            0.03 *
            (
                y_top -
                y_bottom +
                eps()
            )

        x_left =
            steps_axis[1] +
            0.005 *
            (
                steps_axis[end] -
                steps_axis[1]
            )

        Plots.annotate!(
            p,
            x_left,
            y_pos,
            Plots.text(
                "$(group_label)\nn = $(summary.n_runs) / $total_runs",
                12,
                "Calibri",
                :left
            )
        )

        return p
    end

    p_crossed =
        make_rank_plot(
            crossed_summary,
            "runs with persistent atypicality";
            total_runs = n_runs
        )

    p_noncrossed =
        make_rank_plot(
            noncrossed_summary,
            "runs with no persistent atypicality";
            total_runs = n_runs
        )

    p_all =
        make_rank_plot(
            all_summary,
            "all runs";
            total_runs = n_runs
        )

    display(p_crossed)
    display(p_noncrossed)
    display(p_all)

    return (
        keep_runs_original = keep_runs,
        beta_value = beta_value,
        crossed_runs = crossed_runs,
        noncrossed_runs = noncrossed_runs,
        all_runs = all_runs,
        crossed_summary = crossed_summary,
        noncrossed_summary = noncrossed_summary,
        all_summary = all_summary,
        plots = (
            crossed = p_crossed,
            noncrossed = p_noncrossed,
            all = p_all
        )
    )
end
