function _cumtalk_time_by_agent(
    pair_counts_run::AbstractMatrix{<:Real},   # T × P
    pair_map::AbstractVector{<:Tuple},
    N::Int;
    value_mode::Symbol = :zscore)              # :raw, :zscore)
    T, P = size(pair_counts_run)
    @assert length(pair_map) == P "pair_map length does not match number of pair columns"
    @assert value_mode in (:raw, :zscore) "value_mode must be :raw or :zscore"

    talks = zeros(Float64, T, N)

    @inbounds for p in 1:P
        i, j = pair_map[p]
        talks[:, i] .+= Float64.(pair_counts_run[:, p])
        talks[:, j] .+= Float64.(pair_counts_run[:, p])
    end

    if value_mode == :raw
        return talks
    end

    talks_z = Matrix{Float64}(undef, T, N)

    @inbounds for t in 1:T
        row = view(talks, t, :)
        μ = mean(row)
        σ = std(row)

        if σ == 0.0 || !isfinite(σ)
            talks_z[t, :] .= 0.0
        else
            for i in 1:N
                talks_z[t, i] = (talks[t, i] - μ) / σ
            end
        end
    end

    return talks_z
end
function _persistent_crossing_from_zrun(z_run::AbstractMatrix{<:Real}, threshold::Float64)
    T, N = size(z_run)

    best_t = typemax(Int)
    best_agent = 0

    for i in 1:N
        ztraj = @view z_run[:, i]

        t0 = 0
        sustained = true
        for t in T:-1:1
            sustained &= (ztraj[t] >= threshold)
            if sustained
                t0 = t
            end
        end

        if t0 != 0 && t0 < best_t
            best_t = t0
            best_agent = i
        end
    end

    return (
        crossed = best_agent != 0,
        first_cross_t_index = best_agent == 0 ? missing : best_t,
        first_cross_agent = best_agent == 0 ? missing : best_agent
    )
end
function _aligned_pair_indices_to_z(dz, dp)
    @assert haskey(dz, "sim") "Missing key: sim in z file"
    @assert haskey(dz, "beta_value") "Missing key: beta_value in z file"
    @assert haskey(dp, "sim_ids") "Missing key: sim_ids in pair file"
    @assert haskey(dp, "beta_value") "Missing key: beta_value in pair file"

    sim_z = Int.(dz["sim"])
    beta_z = Float64.(dz["beta_value"])

    sim_p = Int.(dp["sim_ids"])
    beta_p = Float64.(dp["beta_value"])

    z_keys = [(beta_z[i], sim_z[i]) for i in eachindex(sim_z)]
    p_keys = [(beta_p[i], sim_p[i]) for i in eachindex(sim_p)]

    @assert length(Set(z_keys)) == length(z_keys) "Duplicate (beta, sim) rows in z file"
    @assert length(Set(p_keys)) == length(p_keys) "Duplicate (beta, sim) rows in pair file"
    @assert Set(z_keys) == Set(p_keys) "The two files do not contain the same set of runs"

    p_index = Dict(k => i for (i, k) in enumerate(p_keys))
    return [p_index[k] for k in z_keys]
end
function plot_ranked_cumtalk_trajectories_by_crossing_no_beta0(
    z_path::String,
    pairtalk_path::String;
    threshold::Float64 = 2.5,
    ranks_to_plot = nothing,
    value_mode::Symbol = :zscore,           # :raw, :zscore
    ribbon_alpha::Float64 = 0.18,
    lw::Float64 = 2.5)

    dz = JLD2.load(z_path)
    dp = JLD2.load(pairtalk_path)

    @assert haskey(dz, "Z_all") "Missing key: Z_all"
    @assert haskey(dz, "steps_axis") "Missing key: steps_axis"
    @assert haskey(dz, "beta_value") "Missing key: beta_value"

    @assert haskey(dp, "pair_counts_all") "Missing key: pair_counts_all"
    @assert haskey(dp, "pair_map") "Missing key: pair_map"
    @assert haskey(dp, "N") "Missing key: N"
    @assert haskey(dp, "steps_axis") "Missing key: steps_axis"

    Z_all_full =
        dz["Z_all"]                         # runs × T × N

    steps_axis_z =
        Int.(dz["steps_axis"])

    beta_value_full =
        Float64.(dz["beta_value"])

    # ============================================================
    # Match social data to semantic-run order
    # ============================================================

    perm =
        _aligned_pair_indices_to_z(
            dz,
            dp
        )

    pair_counts_all_full =
        dp["pair_counts_all"][
            perm,
            :,
            :
        ]

    steps_axis_p =
        Int.(dp["steps_axis"])

    pair_map =
        Tuple{Int,Int}.(
            dp["pair_map"]
        )

    N =
        Int(dp["N"])

    @assert steps_axis_z == steps_axis_p "steps_axis mismatch between files"

    n_runs_full, T, Nz =
        size(Z_all_full)

    n_runs_p_full, Tp, P =
        size(pair_counts_all_full)

    @assert n_runs_full == n_runs_p_full
    @assert T == Tp
    @assert Nz == N
    @assert length(beta_value_full) == n_runs_full


    # ============================================================
    # Remove beta = 0 runs
    #
    # Important:
    # pair_counts_all_full is already aligned to Z_all_full,
    # so the exact same indices are applied to both arrays.
    # ============================================================

    keep_runs =
        findall(
            !=(0.0),
            beta_value_full
        )

    Z_all =
        Z_all_full[
            keep_runs,
            :,
            :
        ]

    pair_counts_all =
        pair_counts_all_full[
            keep_runs,
            :,
            :
        ]

    beta_value =
        beta_value_full[
            keep_runs
        ]

    n_removed =
        n_runs_full -
        length(keep_runs)

    println("Removing beta = 0 runs...")
    println("  Total runs before filtering: ", n_runs_full)
    println("  Beta = 0 runs removed:       ", n_removed)
    println("  Runs retained:               ", length(keep_runs))


    # ============================================================
    # Dimensions after filtering
    # ============================================================

    n_runs, T_filtered, Nz_filtered =
        size(Z_all)

    n_runs_p, Tp_filtered, P_filtered =
        size(pair_counts_all)

    @assert n_runs == n_runs_p
    @assert T_filtered == T
    @assert Tp_filtered == T
    @assert Nz_filtered == N
    @assert P_filtered == P


    # ============================================================
    # Rank settings
    # ============================================================

    if ranks_to_plot === nothing

        ranks_to_plot =
            collect(1:N)

    else

        ranks_to_plot =
            collect(ranks_to_plot)

        @assert all(
            1 .<= ranks_to_plot .<= N
        ) "All ranks_to_plot values must be between 1 and $N"
    end

    @assert value_mode in (:raw, :zscore) "value_mode must be :raw or :zscore"


    # ============================================================
    # Semantic persistent crossing
    # ============================================================

    crossed_mask =
        falses(n_runs)

    for r in 1:n_runs

        z_run =
            Array{Float64}(
                Z_all[
                    r,
                    :,
                    :
                ]
            )

        info =
            _persistent_crossing_from_zrun(
                z_run,
                threshold
            )

        crossed_mask[r] =
            info.crossed
    end

    crossed_runs =
        findall(crossed_mask)

    noncrossed_runs =
        findall(.!crossed_mask)

    all_runs =
        collect(1:n_runs)


    # ============================================================
    # Rank summary
    # ============================================================

    function compute_rank_summary(
        run_inds::Vector{Int})

        n_sel =
            length(run_inds)

        if n_sel == 0

            return (
                mean_ranked =
                    fill(
                        NaN,
                        T,
                        N
                    ),

                sd_ranked =
                    fill(
                        NaN,
                        T,
                        N
                    ),

                n_runs = 0
            )
        end

        ranked_vals =
            Array{Float64}(
                undef,
                n_sel,
                T,
                N
            )

        for (k, r) in enumerate(run_inds)

            x_run =
                _cumtalk_time_by_agent(
                    Array{Float64}(
                        pair_counts_all[
                            r,
                            :,
                            :
                        ]
                    ),
                    pair_map,
                    N;
                    value_mode = value_mode
                )   # T × N

            for t in 1:T

                vals =
                    vec(
                        x_run[
                            t,
                            :
                        ]
                    )

                ranked_vals[
                    k,
                    t,
                    :
                ] =
                    sort(
                        vals;
                        rev = true
                    )
            end
        end

        mean_ranked =
            dropdims(
                Statistics.mean(
                    ranked_vals;
                    dims = 1
                ),
                dims = 1
            )

        sd_ranked =
            if n_sel > 1

                dropdims(
                    Statistics.std(
                        ranked_vals;
                        dims = 1
                    ),
                    dims = 1
                )

            else

                fill(
                    0.0,
                    T,
                    N
                )
            end

        return (
            mean_ranked = mean_ranked,
            sd_ranked = sd_ranked,
            n_runs = n_sel
        )
    end


    crossed_summary =
        compute_rank_summary(
            crossed_runs
        )

    noncrossed_summary =
        compute_rank_summary(
            noncrossed_runs
        )

    all_summary =
        compute_rank_summary(
            all_runs
        )


    # ============================================================
    # Colors
    # ============================================================

    grad_positions =
        collect(
            range(
                0.22,
                0.88;
                length = N
            )
        )

    colors =
        [
            get(
                Plots.cgrad(:viridis),
                x
            )
            for x in grad_positions
        ]


    # ============================================================
    # Labels
    # ============================================================

    y_label =
        value_mode == :raw ?

        "Average cumulative conversation count (by rank)" :

        "Average cumulative-talk Z-score (by rank)"


    title_txt =
        value_mode == :raw ?

        "Average cumulative conversations over time" :

        "Average cumulative-talk Z-score over time"


    # ============================================================
    # Plotting
    # ============================================================

    function make_rank_plot(
        summary,
        group_label::String;
        total_runs::Int)

        p =
            Plots.plot(
                xlabel = "Simulation step",
                ylabel = y_label,
                title = title_txt,
                xformatter = :plain,
                legend = false,
                fontfamily = "Calibri",
                titlefont =
                    Plots.font(
                        17,
                        "Calibri",
                        :bold
                    ),
                xguidefontsize = 13,
                yguidefontsize = 13,
                xtickfontsize = 11,
                ytickfontsize = 11,
                grid = false,
                framestyle = :axes,
                tick_direction = :out,
                size = (1050, 650)
            )

        if summary.n_runs == 0

            Plots.annotate!(
                p,
                steps_axis_z[1] +
                0.015 *
                (
                    steps_axis_z[end] -
                    steps_axis_z[1]
                ),
                0.0,
                Plots.text(
                    "$(group_label)\nn = 0 / $total_runs",
                    12,
                    "Calibri",
                    :left
                )
            )

            return p
        end


        for rank in ranks_to_plot

            μ =
                summary.mean_ranked[
                    :,
                    rank
                ]

            σ =
                summary.sd_ranked[
                    :,
                    rank
                ]

            Plots.plot!(
                p,
                steps_axis_z,
                μ;
                ribbon = σ,
                fillalpha = ribbon_alpha,
                lw = lw,
                color = colors[rank],
                alpha = 0.95,
                label = false
            )
        end


        Plots.hline!(
            p,
            [0.0];
            linestyle = :dash,
            color = :black,
            alpha = 0.5,
            label = false
        )

        Plots.hline!(
            p,
            [-threshold];
            linestyle = :dash,
            color = :red,
            alpha = 0.5,
            label = false
        )


        finite_vals =
            vcat(
                vec(
                    summary.mean_ranked[
                        :,
                        ranks_to_plot
                    ]
                ),

                vec(
                    summary.mean_ranked[
                        :,
                        ranks_to_plot
                    ] .+
                    summary.sd_ranked[
                        :,
                        ranks_to_plot
                    ]
                ),

                vec(
                    summary.mean_ranked[
                        :,
                        ranks_to_plot
                    ] .-
                    summary.sd_ranked[
                        :,
                        ranks_to_plot
                    ]
                )
            )

        finite_vals =
            finite_vals[
                isfinite.(finite_vals)
            ]


        y_top =
            isempty(finite_vals) ?
            threshold + 1.0 :
            maximum(finite_vals)

        y_bottom =
            isempty(finite_vals) ?
            -1.0 :
            minimum(finite_vals)

        y_pos =
            y_top -
            0.03 *
            (
                y_top -
                y_bottom +
                eps()
            )


        x_left =
            steps_axis_z[1] +
            0.005 *
            (
                steps_axis_z[end] -
                steps_axis_z[1]
            )


        Plots.annotate!(
            p,
            x_left,
            y_pos,
            Plots.text(
                "$(group_label)\nn = $(summary.n_runs) / $total_runs",
                12,
                "Calibri",
                :left
            )
        )

        return p
    end


    # ============================================================
    # Create plots
    # ============================================================

    p_crossed =
        make_rank_plot(
            crossed_summary,
            "runs with persistent semantic atypicality";
            total_runs = n_runs
        )

    p_noncrossed =
        make_rank_plot(
            noncrossed_summary,
            "runs with no persistent semantic atypicality";
            total_runs = n_runs
        )

    p_all =
        make_rank_plot(
            all_summary,
            "all runs";
            total_runs = n_runs
        )


    display(p_crossed)
    display(p_noncrossed)
    display(p_all)


    # ============================================================
    # Return
    # ============================================================

    return (
        keep_runs_original = keep_runs,
        beta_value = beta_value,
        crossed_runs = crossed_runs,
        noncrossed_runs = noncrossed_runs,
        all_runs = all_runs,
        crossed_summary = crossed_summary,
        noncrossed_summary = noncrossed_summary,
        all_summary = all_summary,
        plots = (
            crossed = p_crossed,
            noncrossed = p_noncrossed,
            all = p_all
        )
    )
end
# res_ranked_social_no_beta0 =
#     plot_ranked_cumtalk_trajectories_by_crossing_no_beta0(
#         "sweep_beta_logs/ALL_ZSCORES_OVER_TIME.jld2",
#         "sweep_beta_logs/ALL_CUMPAIR_TALKS_SAMPLED.jld2";
#         threshold = 2.5,
#         ranks_to_plot = 1:20,
#         value_mode = :zscore,
#         ribbon_alpha = 0.18,
#         lw = 2.5
# )

function plot_semantic_social_rank_panel(
    res_ranked_semantic_no_beta0,
    res_ranked_social_no_beta0;
    semantic_cmap = :viridis,
    social_cmap = :plasma,
    ribbon_alpha::Float64 = 0.18,
    lw::Float64 = 2.5,
    semantic_threshold::Float64 = 2.5,
    social_threshold::Float64 = -2.5,
    size = (1400, 900),
    fontfamily::String = "Calibri")

    # ============================================================
    # 1. Extract summaries
    # ============================================================

    sem_cross =
        res_ranked_semantic_no_beta0.crossed_summary

    sem_non =
        res_ranked_semantic_no_beta0.noncrossed_summary

    soc_cross =
        res_ranked_social_no_beta0.crossed_summary

    soc_non =
        res_ranked_social_no_beta0.noncrossed_summary


    # ============================================================
    # 2. Basic dimensions
    # ============================================================

    T_sem, N_sem =
        Base.size(sem_cross.mean_ranked)

    T_soc, N_soc =
        Base.size(soc_cross.mean_ranked)

    @assert N_sem == N_soc
    @assert T_sem == T_soc

    N = N_sem
    T = T_sem
    # Recover simulation steps from number of recorded timepoints.
    # Assumes the existing results are 0:100:20000.
    steps_axis =
        collect(
            range(
                0,
                20_000;
                length = T
            )
        )


    # ============================================================
    # 3. Colors
    #
    # Rank 1 = first color
    # Rank N = last color
    # ============================================================

    color_positions =
        collect(
            range(
                0.08,
                0.92;
                length = N
            )
        )

    semantic_gradient =
        Plots.cgrad(semantic_cmap)

    social_gradient =
        Plots.cgrad(social_cmap)

    semantic_colors =
        [
            get(
                semantic_gradient,
                x
            )
            for x in color_positions
        ]

    social_colors =
        [
            get(
                social_gradient,
                x
            )
            for x in color_positions
        ]


    # ============================================================
    # 4. Shared Y limits within each row
    #
    # Include mean ± SD ribbons from BOTH columns.
    # ============================================================

    function shared_ylims(
        summary1,
        summary2;
        extra_values = Float64[]
    )

        vals = Float64[]

        for summary in (summary1, summary2)

            μ = summary.mean_ranked
            σ = summary.sd_ranked

            append!(
                vals,
                vec(μ .- σ)
            )

            append!(
                vals,
                vec(μ .+ σ)
            )
        end

        append!(
            vals,
            extra_values
        )

        vals =
            vals[
                isfinite.(vals)
            ]

        ymin = minimum(vals)
        ymax = maximum(vals)

        yrange = ymax - ymin

        pad =
            yrange > 0 ?
            0.05 * yrange :
            0.5

        return (
            ymin - pad,
            ymax + pad
        )
    end


    semantic_ylims =
        shared_ylims(
            sem_cross,
            sem_non;
            extra_values = [
                0.0,
                semantic_threshold
            ]
        )

    social_ylims =
        shared_ylims(
            soc_cross,
            soc_non;
            extra_values = [
                0.0,
                social_threshold
            ]
        )


    # ============================================================
    # 5. Individual panel function
    # ============================================================

    function make_panel(
        summary;
        colors,
        ylims,
        ylabel::String,
        column_title::String = "",
        threshold = nothing,
        show_xlabel::Bool = false
    )

        p =
            Plots.plot(
                xlabel =
                    show_xlabel ?
                    "Simulation step" :
                    "",

                ylabel = ylabel,

                title = column_title,

                ylims = ylims,

                xformatter = :plain,

                legend = false,

                fontfamily = fontfamily,

                titlefont =
                    Plots.font(
                        15,
                        fontfamily,
                        :bold
                    ),

                xguidefontsize = 12,
                yguidefontsize = 12,
                xtickfontsize = 10,
                ytickfontsize = 10,

                grid = false,
                framestyle = :axes,
                tick_direction = :out
            )


        # --------------------------------------------------------
        # Ranked trajectories
        # --------------------------------------------------------

        for rank in 1:N

            μ =
                summary.mean_ranked[
                    :,
                    rank
                ]

            σ =
                summary.sd_ranked[
                    :,
                    rank
                ]

            Plots.plot!(
                p,
                steps_axis,
                μ;

                ribbon = σ,
                fillalpha = ribbon_alpha,

                color = colors[rank],
                lw = lw,
                alpha = 0.95,

                label = false
            )
        end


        # --------------------------------------------------------
        # Zero line
        # --------------------------------------------------------

        Plots.hline!(
            p,
            [0.0];

            linestyle = :dash,
            color = :black,
            alpha = 0.45,
            linewidth = 1.2,

            label = false
        )


        # --------------------------------------------------------
        # Threshold
        # --------------------------------------------------------

        if threshold !== nothing

            Plots.hline!(
                p,
                [threshold];

                linestyle = :dash,
                color = :red,
                alpha = 0.60,
                linewidth = 1.4,

                label = false
            )
        end


        return p
    end


    # ============================================================
    # 6. Semantic row
    # ============================================================

    p_sem_cross =
        make_panel(
            sem_cross;

            colors = semantic_colors,
            ylims = semantic_ylims,

            ylabel =
                "Semantic atypicality by rank (SA z-score)",

            column_title =
                "Persistent semantic atypicality",

            threshold =
                semantic_threshold,

            show_xlabel = false
        )


    p_sem_non =
        make_panel(
            sem_non;

            colors = semantic_colors,
            ylims = semantic_ylims,

            ylabel = "",

            column_title =
                "No persistent semantic atypicality",

            threshold =
                semantic_threshold,

            show_xlabel = false
        )


    # ============================================================
    # 7. Social row
    # ============================================================

    p_soc_cross =
        make_panel(
            soc_cross;

            colors = social_colors,
            ylims = social_ylims,

            ylabel =
                "Social participation by rank (SP z-score)",

            column_title = "",

            threshold =
                social_threshold,

            show_xlabel = true
        )


    p_soc_non =
        make_panel(
            soc_non;

            colors = social_colors,
            ylims = social_ylims,

            ylabel = "",

            column_title = "",

            threshold =
                social_threshold,

            show_xlabel = true
        )


    # ============================================================
    # 8. Rank colorbars
    # ============================================================

    rank_ticks =
        unique(
            Int.(
                round.(
                    range(
                        1,
                        N;
                        length = min(N, 5)
                    )
                )
            )
        )


    # ------------------------------------------------------------
    # Semantic rank colorbar
    # ------------------------------------------------------------

    p_sem_colorbar =
        Plots.heatmap(
            [0.0, 1.0],
            collect(1:N),
            reshape(
                Float64.(collect(1:N)),
                N,
                1
            );

            c = semantic_gradient,
            clims = (1, N),

            colorbar = true,
            colorbar_title = "Rank",
            colorbar_ticks = rank_ticks,

            # Hide the dummy heatmap itself by covering its
            # plotting area with a white shape
            xticks = false,
            yticks = false,
            axis = false,
            framestyle = :none,
            grid = false,

            legend = false,
            fontfamily = fontfamily
        )

    # ------------------------------------------------------------
    # Social rank colorbar
    # ------------------------------------------------------------

    p_soc_colorbar =
        Plots.heatmap(
            [0.0, 1.0],
            collect(1:N),
            reshape(
                Float64.(collect(1:N)),
                N,
                1
            );

            c = social_gradient,
            clims = (1, N),

            colorbar = true,
            colorbar_title = "Rank",
            colorbar_ticks = rank_ticks,

            xticks = false,
            yticks = false,
            axis = false,
            framestyle = :none,
            grid = false,

            legend = false,
            fontfamily = fontfamily
        )

    # ============================================================
    # 9. Final layout
    # ============================================================

    panel_layout =
        Plots.@layout [
            a{0.47w} b{0.47w} c{0.06w}
            d{0.47w} e{0.47w} f{0.06w}
        ]


    panel =
        Plots.plot(
            p_sem_cross,
            p_sem_non,
            p_sem_colorbar,

            p_soc_cross,
            p_soc_non,
            p_soc_colorbar;

            layout = panel_layout,
            size = size,
            margin = 5Plots.mm
        )


    display(panel)

    return (
        plot = panel,

        semantic_ylims = semantic_ylims,
        social_ylims = social_ylims,

        semantic_colors = semantic_colors,
        social_colors = social_colors
    )

end
