#         res_ranked_semantic_no_beta0,
#         res_ranked_social_no_beta0
# )


# Simulations and aggregation

#region Extending existing CONSTANT HOMOPHILY with additional simulations
# ==========================================
#הוספה של עוד הרצות קבועות

# הוספה של הרצות ע"פ קובץ המטא ועדכון קובץ המטא
function extend_beta_sweep_with_meta(outdir::String, n::Int)
    meta_path = joinpath(outdir, "META.jld2")
    @assert isfile(meta_path) "META.jld2 not found in $outdir"

    meta = load(meta_path)

    # ----------------------------
    # Read parameters from META
    # ----------------------------
    N = Int(meta["N"])
    W = Int(meta["W"])
    H = Int(meta["H"])
    n_words = Int(meta["n"])
    m = Int(meta["m"])
    change = Float64(meta["change"])

    outliers_count = Int(meta["outliers_count"])
    outlier_change = meta["outlier_change"] === nothing ? nothing : Float64(meta["outlier_change"])
    abandonment_threshold = Int(meta["abandonment_threshold"])

    talk_duration = Int(meta["talk_duration"])
    refractory_duration = Int(meta["refractory_duration"])
    self_talk_threshold = Int(meta["self_talk_threshold"])
    L = Int(meta["L"])
    eta = Float32(meta["eta"])

    gamma = Float64(meta["gamma"])
    beta_move = Float64(meta["beta_move"])   # fixed movement beta
    delta = Float64(meta["delta"])
    p0 = Float64(meta["p0"])
    pmin = Float64(meta["pmin"])

    steps = Int(meta["steps"])
    record_distances = Bool(meta["record_distances"])
    record_every = Int(meta["record_every"])
    social_impact = Float64(meta["social_impact"])
    join_rule = meta["join_rule"]
    reset_every = Int(meta["reset_every"])

    seed = meta["seed"]

    old_n_sim = Int(meta["n_sim"])
    target_total = old_n_sim + n

    # Final beta grid requested by user
    target_betas = collect(0.0:0.5:14.0)

    # ----------------------------
    # Helpers
    # ----------------------------
    beta_tag(beta::Real) = replace(@sprintf("%.1f", Float64(beta)), "." => "_")

    function run_filename(beta::Real, sim::Int)
        return "beta$(beta_tag(beta))_sim$(sim).jld2"
    end

    function count_existing_runs_for_beta(beta::Real)
        prefix = "beta$(beta_tag(beta))_sim"
        files = readdir(outdir)
        count = 0
        maxsim = 0

        for f in files
            startswith(f, prefix) || continue
            endswith(f, ".jld2") || continue
            count += 1
            mtch = match(r"_sim(\d+)\.jld2$", f)
            if mtch !== nothing
                maxsim = max(maxsim, parse(Int, mtch.captures[1]))
            end
        end

        return count, maxsim
    end

    function make_world()
        if outlier_change === nothing
            return init_world(
                N, W, H, n_words, m, change;
                abandonment_threshold = abandonment_threshold,
                outliers_count = outliers_count
            )
        else
            return init_world(
                N, W, H, n_words, m, change;
                abandonment_threshold = abandonment_threshold,
                outliers_count = outliers_count,
                outlier_change = outlier_change
            )
        end
    end

    function run_one_sim(beta_value::Float64, bi::Int, sim::Int)
        if seed !== nothing
            Random.seed!(Int(seed) + 10_000 * bi + sim)
        end

        w = make_world()

        for t in 1:steps
            if t % reset_every == 0
                reset_positions_and_interactions!(w)
            end

            step!(w;
                talk_duration = talk_duration,
                refractory_duration = refractory_duration,
                self_talk_threshold = self_talk_threshold,
                L = L,
                eta = eta,
                beta_for_consent = beta_value,   # varied parameter
                gamma = gamma,
                beta = beta_move,                # fixed movement beta from META
                delta = delta,
                p0 = p0,
                pmin = pmin,
                record_every = record_every,
                social_impact = social_impact,
                join_rule = join_rule
            )
        end

        snap = (
            distances_history = w.distances_history,
            perceived_distance_history = w.perceived_distance_history,
            attempt_events = w.attempt_events,
            conversation_events = w.conversation_events
        )

        save_path = joinpath(outdir, run_filename(beta_value, sim))

        jldsave(save_path;
            beta_value = beta_value,
            bi = bi,
            sim = sim,
            snap = snap
        )

        return save_path
    end

    # ----------------------------
    # Run missing simulations
    # ----------------------------
    println("Target total runs per beta: $target_total")
    println("Output directory: $outdir\n")

    for (bi, beta_value) in enumerate(target_betas)
        existing_count, maxsim = count_existing_runs_for_beta(beta_value)
        missing = max(0, target_total - existing_count)

        @printf("beta = %.1f | existing = %d | target = %d | to run = %d\n",
            beta_value, existing_count, target_total, missing)

        for k in 1:missing
            sim = maxsim + k
            @printf("  -> running sim %d for beta %.1f\n", sim, beta_value)
            run_one_sim(beta_value, bi, sim)
        end
    end

    # # ----------------------------
    # # Update META
    # # ----------------------------
    # new_meta = Dict{String,Any}()

    # for k in keys(meta)
    #     new_meta[string(k)] = meta[k]
    # end

    # new_meta["betas"] = target_betas
    # new_meta["n_sim"] = target_total

    # jldsave(meta_path; new_meta...)

    # println("\nMETA updated:")
    # println("  betas = 0.0:0.5:12.0")
    # println("  n_sim = $target_total")

    # return (
    #     outdir = outdir,
    #     target_betas = target_betas,
    #     target_total = target_total,
    #     meta_path = meta_path
    # )

    println("\nFinished running missing simulations.")
    println("META was not updated.")

    return (
        outdir = outdir,
        target_betas = target_betas,
        target_total = target_total
    )
end
