# update_meta_file(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\META.jld2"
# )
# עדכון קובץ ציוני התקן של המרחקים
function _z_from_distance_matrix(dist::AbstractMatrix{<:Real})
    n = size(dist, 1)
    vals = Vector{Float64}(undef, n)

    for j in 1:n
        s = 0.0
        for i in 1:n
            i == j && continue
            s += Float64(dist[i, j])
        end
        vals[j] = s / (n - 1)
    end

    μ = mean(vals)
    σ = std(vals)

    if σ == 0 || !isfinite(σ)
        return zeros(Float64, n)
    else
        return (vals .- μ) ./ σ
    end
end
function _z_history_from_snap(snap)
    dh = snap.distances_history
    T = length(dh)
    N = size(dh[1], 1)

    zhist = Matrix{Float64}(undef, T, N)
    for t in 1:T
        zhist[t, :] = _z_from_distance_matrix(dh[t])
    end
    return zhist
end
function update_zscore_aggregate_from_runs(
    z_path::String;
    runs_dir::Union{Nothing,String}=nothing,
    out_path::Union{Nothing,String}=nothing,
    make_backup::Bool=true,
    sort_rows::Bool=true,
    verbose::Bool=true)
    runs_dir === nothing && (runs_dir = dirname(z_path))
    out_path === nothing && (out_path = z_path)

    @assert isfile(z_path) "Aggregate z-score file not found: $z_path"
    @assert isdir(runs_dir) "Runs directory not found: $runs_dir"

    d = load(z_path)

    @assert haskey(d, "Z_all") "Missing key: Z_all"
    @assert haskey(d, "beta_value") "Missing key: beta_value"
    @assert haskey(d, "steps_axis") "Missing key: steps_axis"

    Z_all = Array{Float64}(d["Z_all"])              # runs × T × N
    beta_value = Float64.(d["beta_value"])
    steps_axis = Int.(d["steps_axis"])

    sims_existing = haskey(d, "sim") ? Int.(d["sim"]) : collect(1:size(Z_all, 1))
    bi_existing = haskey(d, "bi") ? Int.(d["bi"]) : nothing

    n_runs_old, T_expected, N_expected = size(Z_all)

    if verbose
        println("Loaded aggregate file:")
        println("  runs = $n_runs_old")
        println("  T = $T_expected")
        println("  N = $N_expected")
    end

    existing_pairs = Set{Tuple{Float64,Int}}()
    for r in 1:n_runs_old
        push!(existing_pairs, (beta_value[r], sims_existing[r]))
    end

    all_files = sort(readdir(runs_dir))
    run_files = filter(f -> occursin(r"^beta\d+_\d+_sim\d+\.jld2$", f), all_files)

    if verbose
        println("Found $(length(run_files)) candidate run files.")
    end

    new_z_blocks = Matrix{Float64}[]
    new_betas = Float64[]
    new_sims = Int[]
    new_bis = Int[]

    skipped_existing = 0
    skipped_badshape = 0
    added = 0

    for f in run_files
        fp = joinpath(runs_dir, f)
        rd = load(fp)

        @assert haskey(rd, "beta_value") "Missing beta_value in $f"
        @assert haskey(rd, "sim") "Missing sim in $f"
        @assert haskey(rd, "snap") "Missing snap in $f"

        b = Float64(rd["beta_value"])
        s = Int(rd["sim"])
        pair = (b, s)

        if pair in existing_pairs
            skipped_existing += 1
            continue
        end

        snap = rd["snap"]
        zhist = _z_history_from_snap(snap)   # T × N

        if size(zhist, 1) != T_expected || size(zhist, 2) != N_expected
            skipped_badshape += 1
            verbose && @printf("Skipping %s בגלל shape לא תואם: got (%d,%d), expected (%d,%d)\n",
                               f, size(zhist,1), size(zhist,2), T_expected, N_expected)
            continue
        end

        push!(new_z_blocks, zhist)
        push!(new_betas, b)
        push!(new_sims, s)

        if haskey(rd, "bi")
            push!(new_bis, Int(rd["bi"]))
        elseif bi_existing !== nothing
            push!(new_bis, 0)
        end

        push!(existing_pairs, pair)
        added += 1

        if verbose && added % 25 == 0
            println("Added $added new runs so far...")
        end
    end

    if added == 0
        if verbose
            println("No new runs were added.")
            println("Skipped existing: $skipped_existing")
            println("Skipped bad shape: $skipped_badshape")
        end
        return (
            added = 0,
            skipped_existing = skipped_existing,
            skipped_badshape = skipped_badshape,
            out_path = out_path
        )
    end

    Z_new = Array{Float64}(undef, added, T_expected, N_expected)
    for i in 1:added
        Z_new[i, :, :] = new_z_blocks[i]
    end

    Z_combined = cat(Z_all, Z_new; dims=1)
    beta_combined = vcat(beta_value, new_betas)
    sim_combined = vcat(sims_existing, new_sims)

    bi_combined = nothing
    if bi_existing !== nothing
        bi_combined = vcat(bi_existing, new_bis)
    end

    if sort_rows
        ord = sortperm(collect(1:length(beta_combined));
            by = i -> (beta_combined[i], sim_combined[i]))

        Z_combined = Z_combined[ord, :, :]
        beta_combined = beta_combined[ord]
        sim_combined = sim_combined[ord]
        if bi_combined !== nothing
            bi_combined = bi_combined[ord]
        end
    end

    if make_backup && out_path == z_path
        backup_path = replace(z_path, ".jld2" => "_backup_before_update.jld2")
        cp(z_path, backup_path; force=true)
        verbose && println("Backup saved to: $backup_path")
    end

    if bi_combined === nothing
        jldsave(out_path;
            Z_all = Z_combined,
            beta_value = beta_combined,
            steps_axis = steps_axis,
            sim = sim_combined
        )
    else
        jldsave(out_path;
            Z_all = Z_combined,
            beta_value = beta_combined,
            steps_axis = steps_axis,
            sim = sim_combined,
            bi = bi_combined
        )
    end

    if verbose
        println("Done.")
        println("Added runs: $added")
        println("Skipped existing: $skipped_existing")
        println("Skipped bad shape: $skipped_badshape")
        println("New total runs in aggregate: $(size(Z_combined, 1))")
        println("Saved to: $out_path")
    end

    return (
        added = added,
        skipped_existing = skipped_existing,
        skipped_badshape = skipped_badshape,
        out_path = out_path,
        total_runs = size(Z_combined, 1)
    )
end
# res_update = update_zscore_aggregate_from_runs(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_ZSCORES_OVER_TIME.jld2";
#     out_path = raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_ZSCORES_OVER_TIME_UPDATED.jld2",
#     make_backup = false
# )
function update_all_means_and_std_over_time(
    agg_path::String;
    runs_dir::Union{Nothing,String}=nothing,
    out_path::Union{Nothing,String}=nothing,
    verbose::Bool=true)
    runs_dir === nothing && (runs_dir = dirname(agg_path))
    out_path === nothing && (out_path = replace(agg_path, ".jld2" => "_UPDATED.jld2"))

    d = JLD2.load(agg_path)

    metrics_all = Array{Float64}(d["metrics_all"])   # runs × T × 3
    beta_value = Float64.(d["beta_value"])
    sim = Int.(d["sim"])
    bi = Int.(d["bi"])
    files = String.(d["files"])
    metric_names = String.(d["metric_names"])
    meta = d["meta"]

    n_old, T_expected, K = size(metrics_all)
    @assert K == 3
    @assert metric_names == ["mean_offdiag", "std_offdiag", "std_colmeans"]

    existing_pairs = Set((beta_value[i], sim[i]) for i in eachindex(beta_value))

    all_files = sort(readdir(runs_dir))
    run_files = filter(f -> occursin(r"^beta\d+_\d+_sim\d+\.jld2$", f), all_files)

    new_metrics = Matrix{Float64}[]
    new_betas = Float64[]
    new_sims = Int[]
    new_bis = Int[]
    new_files = String[]

    added = 0
    skipped_existing = 0
    skipped_badshape = 0

    function metrics_from_distances_history(dh)
        T = length(dh)
        out = Matrix{Float64}(undef, T, 3)

        for t in 1:T
            M = dh[t]
            n = size(M, 1)

            offdiag = Float64[]
            sizehint!(offdiag, n * (n - 1))
            colmeans = Vector{Float64}(undef, n)

            for j in 1:n
                s = 0.0
                for i in 1:n
                    if i != j
                        v = Float64(M[i, j])
                        push!(offdiag, v)
                        s += v
                    end
                end
                colmeans[j] = s / (n - 1)
            end

            out[t, 1] = mean(offdiag)
            out[t, 2] = std(offdiag)
            out[t, 3] = std(colmeans)
        end

        return out
    end

    for f in run_files
        fp = joinpath(runs_dir, f)
        rd = JLD2.load(fp)

        b = Float64(rd["beta_value"])
        s = Int(rd["sim"])
        pair = (b, s)

        if pair in existing_pairs
            skipped_existing += 1
            continue
        end

        snap = rd["snap"]
        m = metrics_from_distances_history(snap.distances_history)

        if size(m, 1) != T_expected || size(m, 2) != 3
            skipped_badshape += 1
            verbose && @printf("Skipping %s בגלל shape לא תואם\n", f)
            continue
        end

        push!(new_metrics, m)
        push!(new_betas, b)
        push!(new_sims, s)
        push!(new_bis, haskey(rd, "bi") ? Int(rd["bi"]) : 0)
        push!(new_files, f)
        push!(existing_pairs, pair)

        added += 1
        if verbose && added % 25 == 0
            println("Added $added new runs to ALL_MEANS_AND_STD_OVER_TIME...")
        end
    end

    if added == 0
        verbose && println("No new runs added.")
        return (added=0, out_path=out_path)
    end

    M_new = Array{Float64}(undef, added, T_expected, 3)
    for i in 1:added
        M_new[i, :, :] = new_metrics[i]
    end

    metrics_combined = cat(metrics_all, M_new; dims=1)
    beta_combined = vcat(beta_value, new_betas)
    sim_combined = vcat(sim, new_sims)
    bi_combined = vcat(bi, new_bis)
    files_combined = vcat(files, new_files)

    ord = sortperm(collect(1:length(beta_combined)); by=i -> (beta_combined[i], sim_combined[i]))
    metrics_combined = metrics_combined[ord, :, :]
    beta_combined = beta_combined[ord]
    sim_combined = sim_combined[ord]
    bi_combined = bi_combined[ord]
    files_combined = files_combined[ord]

    jldsave(out_path;
        metrics_all = metrics_combined,
        beta_value = beta_combined,
        sim = sim_combined,
        bi = bi_combined,
        files = files_combined,
        metric_names = metric_names,
        meta = meta
    )

    verbose && println("Saved updated means/std file to: $out_path")
    return (added=added, skipped_existing=skipped_existing, skipped_badshape=skipped_badshape, out_path=out_path)
end
# update_all_means_and_std_over_time(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_MEANS_AND_STD_OVER_TIME.jld2"
# )
function update_all_step_counts(
    agg_path::String;
    runs_dir::Union{Nothing,String}=nothing,
    out_path::Union{Nothing,String}=nothing,
    verbose::Bool=true)
    runs_dir === nothing && (runs_dir = dirname(agg_path))
    out_path === nothing && (out_path = replace(agg_path, ".jld2" => "_UPDATED.jld2"))

    d = load(agg_path)

    counts_all = Array{Int64}(d["counts_all"])   # runs × steps × 3
    beta_value = Float64.(d["beta_value"])
    sim = Int.(d["sim"])
    bi = Int.(d["bi"])
    run_files = String.(d["run_files"])
    col_names = String.(d["col_names"])
    meta = d["meta"]

    n_old, T_expected, K = size(counts_all)
    @assert K == 3
    @assert col_names == ["n_conversations", "n_attempts", "n_failures"]

    existing_pairs = Set((beta_value[i], sim[i]) for i in eachindex(beta_value))

    all_files = sort(readdir(runs_dir))
    files = filter(f -> occursin(r"^beta\d+_\d+_sim\d+\.jld2$", f), all_files)

    new_counts = Matrix{Int64}[]
    new_betas = Float64[]
    new_sims = Int[]
    new_bis = Int[]
    new_runfiles = String[]

    added = 0
    skipped_existing = 0
    skipped_badshape = 0

    function counts_from_snap(snap, T_expected)
        conv = zeros(Int64, T_expected)
        att = zeros(Int64, T_expected)
        fail = zeros(Int64, T_expected)

        for ev in snap.conversation_events
            t = Int(ev.t)
            if 1 <= t <= T_expected
                conv[t] += 1
            end
        end

        for agent_events in snap.attempt_events
            for ev in agent_events
                t = Int(ev.t)
                if 1 <= t <= T_expected
                    att[t] += 1
                    if hasproperty(ev, :success)
                        fail[t] += (!ev.success)
                    elseif hasproperty(ev, :accepted)
                        fail[t] += (!ev.accepted)
                    elseif hasproperty(ev, :joined)
                        fail[t] += (!ev.joined)
                    end
                end
            end
        end

        out = Matrix{Int64}(undef, T_expected, 3)
        out[:, 1] = conv
        out[:, 2] = att
        out[:, 3] = fail
        return out
    end

    for f in files
        fp = joinpath(runs_dir, f)
        rd = load(fp)

        b = Float64(rd["beta_value"])
        s = Int(rd["sim"])
        pair = (b, s)

        if pair in existing_pairs
            skipped_existing += 1
            continue
        end

        snap = rd["snap"]
        c = counts_from_snap(snap, T_expected)

        if size(c, 1) != T_expected || size(c, 2) != 3
            skipped_badshape += 1
            verbose && @printf("Skipping %s בגלל shape לא תואם\n", f)
            continue
        end

        push!(new_counts, c)
        push!(new_betas, b)
        push!(new_sims, s)
        push!(new_bis, haskey(rd, "bi") ? Int(rd["bi"]) : 0)
        push!(new_runfiles, f)
        push!(existing_pairs, pair)

        added += 1
        if verbose && added % 25 == 0
            println("Added $added new runs to ALL_STEP_COUNTS...")
        end
    end

    if added == 0
        verbose && println("No new runs added.")
        return (added=0, out_path=out_path)
    end

    C_new = Array{Int64}(undef, added, T_expected, 3)
    for i in 1:added
        C_new[i, :, :] = new_counts[i]
    end

    counts_combined = cat(counts_all, C_new; dims=1)
    beta_combined = vcat(beta_value, new_betas)
    sim_combined = vcat(sim, new_sims)
    bi_combined = vcat(bi, new_bis)
    runfiles_combined = vcat(run_files, new_runfiles)

    ord = sortperm(collect(1:length(beta_combined)); by=i -> (beta_combined[i], sim_combined[i]))
    counts_combined = counts_combined[ord, :, :]
    beta_combined = beta_combined[ord]
    sim_combined = sim_combined[ord]
    bi_combined = bi_combined[ord]
    runfiles_combined = runfiles_combined[ord]

    jldsave(out_path;
        counts_all = counts_combined,
        beta_value = beta_combined,
        sim = sim_combined,
        bi = bi_combined,
        run_files = runfiles_combined,
        col_names = col_names,
        meta = meta
    )

    verbose && println("Saved updated step-counts file to: $out_path")
    return (added=added, skipped_existing=skipped_existing, skipped_badshape=skipped_badshape, out_path=out_path)
end
# update_all_step_counts(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_STEP_COUNTS.jld2"
# )
function update_sampled_cumulative_successes(outdir::AbstractString;
    outfile::AbstractString = "ALL_PLAYER_CUMSUCCESS_SAMPLED.jld2",
    steps::Int = 20000,
    sample_every::Int = 100,
    sort_files::Bool = true,
    verbose_every::Int = 20)

    isdir(outdir) || error("Directory does not exist: $outdir")

    files = filter(f ->
        startswith(f, "beta") &&
        endswith(f, ".jld2") &&
        f != outfile &&
        f != "ALL_ZSCORES_OVER_TIME.jld2" &&
        f != "ALL_MEANS_AND_STD_OVER_TIME.jld2" &&
        f != "ALL_STEP_COUNTS.jld2" &&
        f != "PERCEIVED_DIST_SAMPLED.jld2" &&
        f != "ALL_PLAYER_STEP_ACTIVITY.jld2",
        readdir(outdir)
    )

    @assert !isempty(files) "No valid simulation files found in $outdir"

    if sort_files
        sort!(files)
    end

    steps_axis = collect(0:sample_every:steps)
    T_sample = length(steps_axis)

    save_path = joinpath(outdir, outfile)

    old_C = nothing
    old_beta = Float64[]
    old_bi = Int[]
    old_sim = Int[]
    old_run_files = String[]
    old_N = nothing

    if isfile(save_path)
        d_old = load(save_path)

        @assert haskey(d_old, "C_sampled") "Existing file missing C_sampled"
        @assert haskey(d_old, "steps_axis") "Existing file missing steps_axis"
        @assert Int.(d_old["steps_axis"]) == steps_axis "Existing steps_axis does not match requested sampling"

        old_C = d_old["C_sampled"]
        old_beta = haskey(d_old, "beta_value") ? Float64.(d_old["beta_value"]) : Float64[]
        old_bi   = haskey(d_old, "bi") ? Int.(d_old["bi"]) : Int[]
        old_sim  = haskey(d_old, "sim_ids") ? Int.(d_old["sim_ids"]) : Int[]
        old_run_files = haskey(d_old, "run_files") ? String.(d_old["run_files"]) : String[]
        old_N = haskey(d_old, "N") ? Int(d_old["N"]) : size(old_C, 3)
    end

    existing_set = Set(old_run_files)
    new_files = [f for f in files if !(f in existing_set)]

    if isempty(new_files)
        println("No new run files found. Existing sampled cumulative-success file is already up to date.")
        return save_path
    end

    if sort_files
        sort!(new_files)
    end

    first_path = joinpath(outdir, new_files[1])
    first_d = load(first_path)

    @assert haskey(first_d, "snap") "First new file has no 'snap': $(new_files[1])"
    snap0 = first_d["snap"]
    @assert hasproperty(snap0, :attempt_events) "First new file has no attempt_events: $(new_files[1])"

    N = length(snap0.attempt_events)

    if old_N !== nothing
        @assert old_N == N "Mismatch in N between existing file ($old_N) and new files ($N)"
    end

    n_new = length(new_files)

    C_new = zeros(Int32, n_new, T_sample, N)
    beta_new = fill(NaN, n_new)
    bi_new   = zeros(Int, n_new)
    sim_new  = zeros(Int, n_new)
    run_files_new = Vector{String}(undef, n_new)

    println("Updating sampled cumulative successes...")
    println("Existing runs: $(length(old_run_files))")
    println("New runs to process: $n_new")
    println("Sampling steps: 0:$sample_every:$steps")
    t_start = time()

    @inbounds for (r, f) in enumerate(new_files)
        path = joinpath(outdir, f)
        d = load(path)

        @assert haskey(d, "snap") "Missing 'snap' in file: $f"
        snap = d["snap"]
        @assert hasproperty(snap, :attempt_events) "Missing attempt_events in file: $f"

        logs = snap.attempt_events
        @assert length(logs) == N "Mismatch in number of players in file: $f"

        beta_new[r] = haskey(d, "beta_value") ? Float64(d["beta_value"]) : NaN
        bi_new[r]   = haskey(d, "bi") ? Int(d["bi"]) : 0
        sim_new[r]  = haskey(d, "sim") ? Int(d["sim"]) : 0
        run_files_new[r] = f

        M = @view C_new[r, :, :]

        for i in 1:N
            player_log = logs[i]

            succ_per_step = zeros(Int32, steps)

            for ev in player_log
                if get(ev, :success, false)
                    t = Int(ev.t)
                    if 1 <= t <= steps
                        succ_per_step[t] += 1
                    end
                end
            end

            cum = Int32(0)
            M[1, i] = 0  # step 0

            sidx = 2
            next_sample = sample_every

            for t in 1:steps
                cum += succ_per_step[t]

                if t == next_sample
                    M[sidx, i] = cum
                    sidx += 1
                    next_sample += sample_every
                    if sidx > T_sample
                        break
                    end
                end
            end
        end

        if (r % verbose_every == 0) || (r == n_new)
            elapsed = round(time() - t_start, digits=1)
            @printf("Progress: %d/%d new files processed (%.1fs)\n", r, n_new, elapsed)
        end
    end

    if old_C === nothing
        C_all = C_new
        beta_all = beta_new
        bi_all = bi_new
        sim_all = sim_new
        run_files_all = run_files_new
    else
        C_all = cat(old_C, C_new; dims=1)
        beta_all = vcat(old_beta, beta_new)
        bi_all = vcat(old_bi, bi_new)
        sim_all = vcat(old_sim, sim_new)
        run_files_all = vcat(old_run_files, run_files_new)
    end

    @save save_path C_all steps_axis beta_all bi_all sim_all run_files_all N

    println("\nDone! Saved to: $save_path")
    println("C_all size = ", size(C_all))

    return save_path
end
# update_sampled_cumulative_successes(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs";
#     outfile = "ALL_PLAYER_CUMSUCCESS_SAMPLED.jld2",
#     steps = 20000,
