# )
function update_sampled_cumulative_failures(outdir::AbstractString;
    outfile::AbstractString = "ALL_PLAYER_CUMFAIL_SAMPLED.jld2",
    steps::Int = 20000,
    sample_every::Int = 100,
    sort_files::Bool = true,
    verbose_every::Int = 20)

    isdir(outdir) || error("Directory does not exist: $outdir")

    files = filter(f ->
        startswith(f, "beta") &&
        endswith(f, ".jld2") &&
        f != outfile &&
        f != "ALL_ZSCORES_OVER_TIME.jld2" &&
        f != "ALL_MEANS_AND_STD_OVER_TIME.jld2" &&
        f != "ALL_STEP_COUNTS.jld2" &&
        f != "PERCEIVED_DIST_SAMPLED.jld2" &&
        f != "ALL_PLAYER_STEP_ACTIVITY.jld2" &&
        f != "ALL_PLAYER_CUMSUCCESS_SAMPLED.jld2",
        readdir(outdir)
    )

    @assert !isempty(files) "No valid simulation files found in $outdir"

    if sort_files
        sort!(files)
    end

    steps_axis = collect(0:sample_every:steps)
    T_sample = length(steps_axis)

    save_path = joinpath(outdir, outfile)

    old_C = nothing
    old_beta = Float64[]
    old_bi = Int[]
    old_sim = Int[]
    old_run_files = String[]
    old_N = nothing

    if isfile(save_path)
        d_old = load(save_path)

        @assert haskey(d_old, "C_all") "Existing file missing C_all"
        @assert haskey(d_old, "steps_axis") "Existing file missing steps_axis"
        @assert Int.(d_old["steps_axis"]) == steps_axis "Existing steps_axis does not match requested sampling"

        old_C = d_old["C_all"]
        old_beta = haskey(d_old, "beta_all") ? Float64.(d_old["beta_all"]) :
                   haskey(d_old, "beta_value") ? Float64.(d_old["beta_value"]) : Float64[]
        old_bi   = haskey(d_old, "bi_all") ? Int.(d_old["bi_all"]) :
                   haskey(d_old, "bi") ? Int.(d_old["bi"]) : Int[]
        old_sim  = haskey(d_old, "sim_all") ? Int.(d_old["sim_all"]) :
                   haskey(d_old, "sim_ids") ? Int.(d_old["sim_ids"]) :
                   haskey(d_old, "sim") ? Int.(d_old["sim"]) : Int[]
        old_run_files = haskey(d_old, "run_files_all") ? String.(d_old["run_files_all"]) :
                        haskey(d_old, "run_files") ? String.(d_old["run_files"]) : String[]
        old_N = haskey(d_old, "N") ? Int(d_old["N"]) : size(old_C, 3)
    end

    existing_set = Set(old_run_files)
    new_files = [f for f in files if !(f in existing_set)]

    if isempty(new_files)
        println("No new run files found. Existing sampled cumulative-failure file is already up to date.")
        return save_path
    end

    if sort_files
        sort!(new_files)
    end

    first_path = joinpath(outdir, new_files[1])
    first_d = load(first_path)

    @assert haskey(first_d, "snap") "First new file has no 'snap': $(new_files[1])"
    snap0 = first_d["snap"]
    @assert hasproperty(snap0, :attempt_events) "First new file has no attempt_events: $(new_files[1])"

    N = length(snap0.attempt_events)

    if old_N !== nothing
        @assert old_N == N "Mismatch in N between existing file ($old_N) and new files ($N)"
    end

    n_new = length(new_files)

    C_new = zeros(Int32, n_new, T_sample, N)
    beta_new = fill(NaN, n_new)
    bi_new   = zeros(Int, n_new)
    sim_new  = zeros(Int, n_new)
    run_files_new = Vector{String}(undef, n_new)

    println("Updating sampled cumulative failures...")
    println("Existing runs: $(length(old_run_files))")
    println("New runs to process: $n_new")
    println("Sampling steps: 0:$sample_every:$steps")
    t_start = time()

    @inbounds for (r, f) in enumerate(new_files)
        path = joinpath(outdir, f)
        d = load(path)

        @assert haskey(d, "snap") "Missing 'snap' in file: $f"
        snap = d["snap"]
        @assert hasproperty(snap, :attempt_events) "Missing attempt_events in file: $f"

        logs = snap.attempt_events
        @assert length(logs) == N "Mismatch in number of players in file: $f"

        beta_new[r] = haskey(d, "beta_value") ? Float64(d["beta_value"]) : NaN
        bi_new[r]   = haskey(d, "bi") ? Int(d["bi"]) : 0
        sim_new[r]  = haskey(d, "sim") ? Int(d["sim"]) : 0
        run_files_new[r] = f

        M = @view C_new[r, :, :]

        for i in 1:N
            player_log = logs[i]

            fail_per_step = zeros(Int32, steps)

            for ev in player_log
                if !get(ev, :success, false)
                    t = Int(ev.t)
                    if 1 <= t <= steps
                        fail_per_step[t] += 1
                    end
                end
            end

            cum = Int32(0)
            M[1, i] = 0   # step 0

            sidx = 2
            next_sample = sample_every

            for t in 1:steps
                cum += fail_per_step[t]

                if t == next_sample
                    M[sidx, i] = cum
                    sidx += 1
                    next_sample += sample_every
                    if sidx > T_sample
                        break
                    end
                end
            end
        end

        if (r % verbose_every == 0) || (r == n_new)
            elapsed = round(time() - t_start, digits=1)
            @printf("Progress: %d/%d new files processed (%.1fs)\n", r, n_new, elapsed)
        end
    end

    if old_C === nothing
        C_all = C_new
        beta_all = beta_new
        bi_all = bi_new
        sim_all = sim_new
        run_files_all = run_files_new
    else
        C_all = cat(old_C, C_new; dims=1)
        beta_all = vcat(old_beta, beta_new)
        bi_all = vcat(old_bi, bi_new)
        sim_all = vcat(old_sim, sim_new)
        run_files_all = vcat(old_run_files, run_files_new)
    end

    @save save_path C_all steps_axis beta_all bi_all sim_all run_files_all N

    println("\nDone! Saved to: $save_path")
    println("C_all size = ", size(C_all))

    return save_path
end
# update_sampled_cumulative_failures(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs";
#     outfile = "ALL_PLAYER_CUMFAIL_SAMPLED.jld2",
#     steps = 20000,
#     sample_every = 100,
#     verbose_every = 50
# )
function update_sampled_cumulative_rejections(outdir::AbstractString;
    outfile::AbstractString = "ALL_PLAYER_CUMREJECT_SAMPLED.jld2",
    steps::Int = 20000,
    sample_every::Int = 100,
    sort_files::Bool = true,
    verbose_every::Int = 20)

    isdir(outdir) || error("Directory does not exist: $outdir")

    files = filter(f ->
        startswith(f, "beta") &&
        endswith(f, ".jld2") &&
        f != outfile &&
        f != "ALL_ZSCORES_OVER_TIME.jld2" &&
        f != "ALL_MEANS_AND_STD_OVER_TIME.jld2" &&
        f != "ALL_STEP_COUNTS.jld2" &&
        f != "PERCEIVED_DIST_SAMPLED.jld2" &&
        f != "ALL_PLAYER_STEP_ACTIVITY.jld2" &&
        f != "ALL_PLAYER_CUMSUCCESS_SAMPLED.jld2" &&
        f != "ALL_PLAYER_CUMFAIL_SAMPLED.jld2" &&
        f != "ALL_PLAYER_CUMREJECT_SAMPLED.jld2" &&
        f != "ALL_CUMPAIR_TALKS_SAMPLED.jld2",
        readdir(outdir)
    )

    @assert !isempty(files) "No valid simulation files found in $outdir"

    if sort_files
        sort!(files)
    end

    steps_axis = collect(0:sample_every:steps)
    T_sample = length(steps_axis)

    save_path = joinpath(outdir, outfile)

    old_C = nothing
    old_beta = Float64[]
    old_bi = Int[]
    old_sim = Int[]
    old_run_files = String[]
    old_N = nothing

    if isfile(save_path)
        d_old = load(save_path)

        @assert haskey(d_old, "C_all") "Existing file missing C_all"
        @assert haskey(d_old, "steps_axis") "Existing file missing steps_axis"
        @assert Int.(d_old["steps_axis"]) == steps_axis "Existing steps_axis does not match requested sampling"

        old_C = d_old["C_all"]
        old_beta = haskey(d_old, "beta_all") ? Float64.(d_old["beta_all"]) :
                   haskey(d_old, "beta_value") ? Float64.(d_old["beta_value"]) : Float64[]
        old_bi   = haskey(d_old, "bi_all") ? Int.(d_old["bi_all"]) :
                   haskey(d_old, "bi") ? Int.(d_old["bi"]) : Int[]
        old_sim  = haskey(d_old, "sim_all") ? Int.(d_old["sim_all"]) :
                   haskey(d_old, "sim_ids") ? Int.(d_old["sim_ids"]) :
                   haskey(d_old, "sim") ? Int.(d_old["sim"]) : Int[]
        old_run_files = haskey(d_old, "run_files_all") ? String.(d_old["run_files_all"]) :
                        haskey(d_old, "run_files") ? String.(d_old["run_files"]) : String[]
        old_N = haskey(d_old, "N") ? Int(d_old["N"]) : size(old_C, 3)
    end

    existing_set = Set(old_run_files)
    new_files = [f for f in files if !(f in existing_set)]

    if isempty(new_files)
        println("No new run files found. Existing sampled cumulative-rejection file is already up to date.")
        return save_path
    end

    if sort_files
        sort!(new_files)
    end

    first_path = joinpath(outdir, new_files[1])
    first_d = load(first_path)

    @assert haskey(first_d, "snap") "First new file has no 'snap': $(new_files[1])"
    snap0 = first_d["snap"]
    @assert hasproperty(snap0, :attempt_events) "First new file has no attempt_events: $(new_files[1])"

    N = length(snap0.attempt_events)

    if old_N !== nothing
        @assert old_N == N "Mismatch in N between existing file ($old_N) and new files ($N)"
    end

    n_new = length(new_files)

    C_new = zeros(Int32, n_new, T_sample, N)
    beta_new = fill(NaN, n_new)
    bi_new   = zeros(Int, n_new)
    sim_new  = zeros(Int, n_new)
    run_files_new = Vector{String}(undef, n_new)

    println("Updating sampled cumulative rejections...")
    println("Existing runs: $(length(old_run_files))")
    println("New runs to process: $n_new")
    println("Sampling steps: 0:$sample_every:$steps")
    t_start = time()

    @inbounds for (r, f) in enumerate(new_files)
        path = joinpath(outdir, f)
        d = load(path)

        @assert haskey(d, "snap") "Missing 'snap' in file: $f"
        snap = d["snap"]
        @assert hasproperty(snap, :attempt_events) "Missing attempt_events in file: $f"

        logs = snap.attempt_events
        @assert length(logs) == N "Mismatch in number of players in file: $f"

        beta_new[r] = haskey(d, "beta_value") ? Float64(d["beta_value"]) : NaN
        bi_new[r]   = haskey(d, "bi") ? Int(d["bi"]) : 0
        sim_new[r]  = haskey(d, "sim") ? Int(d["sim"]) : 0
        run_files_new[r] = f

        M = @view C_new[r, :, :]

        for i in 1:N
            player_log = logs[i]

            rej_per_step = zeros(Int32, steps)

            for ev in player_log
                if !get(ev, :success, false) && !isempty(get(ev, :rejected, Int[]))
                    t = Int(ev.t)
                    if 1 <= t <= steps
                        rej_per_step[t] += 1
                    end
                end
            end

            cum = Int32(0)
            M[1, i] = 0   # step 0

            sidx = 2
            next_sample = sample_every

            for t in 1:steps
                cum += rej_per_step[t]

                if t == next_sample
                    M[sidx, i] = cum
                    sidx += 1
                    next_sample += sample_every
                    if sidx > T_sample
                        break
                    end
                end
            end
        end

        if (r % verbose_every == 0) || (r == n_new)
            elapsed = round(time() - t_start, digits=1)
            @printf("Progress: %d/%d new files processed (%.1fs)\n", r, n_new, elapsed)
        end
    end

    if old_C === nothing
        C_all = C_new
        beta_all = beta_new
        bi_all = bi_new
        sim_all = sim_new
        run_files_all = run_files_new
    else
        C_all = cat(old_C, C_new; dims=1)
        beta_all = vcat(old_beta, beta_new)
        bi_all = vcat(old_bi, bi_new)
        sim_all = vcat(old_sim, sim_new)
        run_files_all = vcat(old_run_files, run_files_new)
    end

    @save save_path C_all steps_axis beta_all bi_all sim_all run_files_all N

    println("\nDone! Saved to: $save_path")
    println("C_all size = ", size(C_all))

    return save_path
end
# update_sampled_cumulative_rejections(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs";
#     outfile = "ALL_PLAYER_CUMREJECT_SAMPLED.jld2",
#     steps = 20000,
#     sample_every = 100,
#     verbose_every = 20
# )
function update_sampled_cumulative_pair_talks(outdir::AbstractString;
    outfile::AbstractString = "ALL_CUMPAIR_TALKS_SAMPLED.jld2",
    steps::Int = 20000,
    sample_every::Int = 100,
    sort_files::Bool = true,
    verbose_every::Int = 20)

    isdir(outdir) || error("Directory does not exist: $outdir")

    files = filter(f ->
        startswith(f, "beta") &&
        endswith(f, ".jld2") &&
        f != outfile &&
        f != "ALL_ZSCORES_OVER_TIME.jld2" &&
        f != "ALL_MEANS_AND_STD_OVER_TIME.jld2" &&
        f != "ALL_STEP_COUNTS.jld2" &&
        f != "PERCEIVED_DIST_SAMPLED.jld2" &&
        f != "ALL_PLAYER_STEP_ACTIVITY.jld2" &&
        f != "ALL_PLAYER_CUMSUCCESS_SAMPLED.jld2" &&
        f != "ALL_PLAYER_CUMFAIL_SAMPLED.jld2" &&
        f != "ALL_PAIR_CONVERSATION_PROBABILITIES.jld2",
        readdir(outdir)
    )

    @assert !isempty(files) "No valid simulation files found in $outdir"

    if sort_files
        sort!(files)
    end

    steps_axis = collect(0:sample_every:steps)
    T_sample = length(steps_axis)

    save_path = joinpath(outdir, outfile)

    old_pair_counts = nothing
    old_beta = Float64[]
    old_bi = Int[]
    old_sim = Int[]
    old_run_files = String[]
    old_pair_map = Tuple{Int,Int}[]
    old_N = nothing

    if isfile(save_path)
        d_old = load(save_path)

        @assert haskey(d_old, "pair_counts_all") "Existing file missing pair_counts_all"
        @assert haskey(d_old, "steps_axis") "Existing file missing steps_axis"
        @assert haskey(d_old, "pair_map") "Existing file missing pair_map"

        @assert Int.(d_old["steps_axis"]) == steps_axis "Existing steps_axis does not match requested sampling"

        old_pair_counts = d_old["pair_counts_all"]
        old_beta = haskey(d_old, "beta_value") ? Float64.(d_old["beta_value"]) :
                   haskey(d_old, "beta_all") ? Float64.(d_old["beta_all"]) : Float64[]
        old_bi   = haskey(d_old, "bi") ? Int.(d_old["bi"]) :
                   haskey(d_old, "bi_all") ? Int.(d_old["bi_all"]) : Int[]
        old_sim  = haskey(d_old, "sim_ids") ? Int.(d_old["sim_ids"]) :
                   haskey(d_old, "sim") ? Int.(d_old["sim"]) :
                   haskey(d_old, "sim_all") ? Int.(d_old["sim_all"]) : Int[]
        old_run_files = haskey(d_old, "run_files") ? String.(d_old["run_files"]) :
                        haskey(d_old, "run_files_all") ? String.(d_old["run_files_all"]) : String[]

        old_pair_map = Tuple{Int,Int}.(d_old["pair_map"])
        old_N = haskey(d_old, "N") ? Int(d_old["N"]) : begin
            pm = old_pair_map
            isempty(pm) ? nothing : maximum(max(i, j) for (i, j) in pm)
        end
    end

    existing_set = Set(old_run_files)
    new_files = [f for f in files if !(f in existing_set)]

    if isempty(new_files)
        println("No new run files found. Existing cumulative pair-talk file is already up to date.")
        return save_path
    end

    if sort_files
        sort!(new_files)
    end

    first_path = joinpath(outdir, new_files[1])
    first_d = load(first_path)

    @assert haskey(first_d, "snap") "First new file has no 'snap': $(new_files[1])"
    snap0 = first_d["snap"]
    @assert hasproperty(snap0, :attempt_events) "First new file has no attempt_events: $(new_files[1])"
    @assert hasproperty(snap0, :conversation_events) "First new file has no conversation_events: $(new_files[1])"

    N = length(snap0.attempt_events)

    if old_N !== nothing
        @assert old_N == N "Mismatch in N between existing file ($old_N) and new files ($N)"
    end

    pair_map = Tuple{Int,Int}[]
    for i in 1:N-1
        for j in i+1:N
            push!(pair_map, (i, j))
        end
    end
    n_pairs = length(pair_map)

    if !isempty(old_pair_map)
        @assert old_pair_map == pair_map "Existing pair_map does not match current N/pair ordering"
    end

    pair_to_idx = Dict{Tuple{Int,Int},Int}()
    for (k, p) in enumerate(pair_map)
        pair_to_idx[p] = k
    end

    n_new = length(new_files)

    pair_counts_new = zeros(Int32, n_new, T_sample, n_pairs)
    beta_new = fill(NaN, n_new)
    bi_new   = zeros(Int, n_new)
    sim_new  = zeros(Int, n_new)
    run_files_new = Vector{String}(undef, n_new)

    println("Updating sampled cumulative pair-talk counts...")
    println("Existing runs: $(length(old_run_files))")
    println("New runs to process: $n_new")
    println("Sampling steps: 0:$sample_every:$steps")
    println("Pairs per run: $n_pairs")
    t_start = time()

    @inbounds for (r, f) in enumerate(new_files)
        path = joinpath(outdir, f)
        d = load(path)

        @assert haskey(d, "snap") "Missing 'snap' in file: $f"
        snap = d["snap"]
        @assert hasproperty(snap, :conversation_events) "Missing conversation_events in file: $f"

        convs = snap.conversation_events

        beta_new[r] = haskey(d, "beta_value") ? Float64(d["beta_value"]) : NaN
        bi_new[r]   = haskey(d, "bi") ? Int(d["bi"]) : 0
        sim_new[r]  = haskey(d, "sim") ? Int(d["sim"]) : 0
        run_files_new[r] = f

        counts_by_step = zeros(Int32, steps, n_pairs)

        for ev in convs
            t = Int(ev.t)
            if !(1 <= t <= steps)
                continue
            end

            members = collect(Int, ev.members)
            m = length(members)

            if m >= 2
                for a in 1:m-1
                    i = members[a]
                    if !(1 <= i <= N)
                        continue
                    end
                    for b in a+1:m
                        j = members[b]
                        if !(1 <= j <= N)
                            continue
                        end
                        p = i < j ? (i, j) : (j, i)
                        idx = pair_to_idx[p]
                        counts_by_step[t, idx] += 1
                    end
                end
            end
        end

        M = @view pair_counts_new[r, :, :]

        M[1, :] .= 0  # step 0

        cum = zeros(Int32, n_pairs)
        sidx = 2
        next_sample = sample_every

        for t in 1:steps
            @inbounds cum .+= counts_by_step[t, :]

            if t == next_sample
                M[sidx, :] .= cum
                sidx += 1
                next_sample += sample_every
                if sidx > T_sample
                    break
                end
            end
        end

        if (r % verbose_every == 0) || (r == n_new)
            elapsed = round(time() - t_start, digits=1)
            @printf("Progress: %d/%d new files processed (%.1fs)\n", r, n_new, elapsed)
        end
    end

    if old_pair_counts === nothing
        pair_counts_all = pair_counts_new
        beta_value = beta_new
        bi = bi_new
        sim_ids = sim_new
        run_files = run_files_new
    else
        pair_counts_all = cat(old_pair_counts, pair_counts_new; dims=1)
        beta_value = vcat(old_beta, beta_new)
        bi = vcat(old_bi, bi_new)
        sim_ids = vcat(old_sim, sim_new)
        run_files = vcat(old_run_files, run_files_new)
    end

    @save save_path pair_counts_all pair_map steps_axis beta_value bi sim_ids run_files N

    println("\nDone! Saved to: $save_path")
    println("pair_counts_all size = ", size(pair_counts_all))

    return save_path
end
# update_sampled_cumulative_pair_talks(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs";
#     outfile = "ALL_CUMPAIR_TALKS_SAMPLED.jld2",
#     steps = 20000,
#     sample_every = 100,
#     verbose_every = 50
# )
function build_all_perceived_pair_distances(raw_dir::String, pairtalk_path::String; out_path::Union{Nothing,String} = nothing, print_every::Int = 25)  # nothing/String, any Int
    @assert isdir(raw_dir) "raw_dir not found: $raw_dir"
    @assert isfile(pairtalk_path) "pairtalk file not found: $pairtalk_path"
    @assert print_every ≥ 1 "print_every must be >= 1"

    dp = load(pairtalk_path)

    @assert haskey(dp, "pair_map") "Missing key: pair_map in pairtalk file"
    @assert haskey(dp, "sim_ids") "Missing key: sim_ids in pairtalk file"
    @assert haskey(dp, "bi") "Missing key: bi in pairtalk file"
    @assert haskey(dp, "beta_value") "Missing key: beta_value in pairtalk file"
    @assert haskey(dp, "steps_axis") "Missing key: steps_axis in pairtalk file"
    @assert haskey(dp, "run_files") "Missing key: run_files in pairtalk file"
    @assert haskey(dp, "N") "Missing key: N in pairtalk file"

    pair_map = Tuple{Int,Int}.(dp["pair_map"])
    sim_ids = Int.(dp["sim_ids"])
    bi = Int.(dp["bi"])
    beta_value = Float64.(dp["beta_value"])
    steps_axis = Int.(dp["steps_axis"])
    run_files = String.(dp["run_files"])
    N = Int(dp["N"])

    n_runs = length(run_files)
    T = length(steps_axis)
    n_pairs = length(pair_map)

    @assert length(sim_ids) == n_runs
    @assert length(bi) == n_runs
    @assert length(beta_value) == n_runs
    @assert n_pairs == N * (N - 1) ÷ 2 "pair_map length does not match N"

    if out_path === nothing
        out_path = joinpath(raw_dir, "ALL_PERCEIVED_PAIR_DISTANCES.jld2")
    end

    PD_pairs_all = Array{Float32}(undef, n_runs, T, n_pairs)

    println("Building perceived pair-distance file")
    println("raw_dir: $raw_dir")
    println("out_path: $out_path")
    @printf("runs = %d | time points = %d | pairs = %d | N = %d\n", n_runs, T, n_pairs, N)

    for r in 1:n_runs
        f = run_files[r]
        fullpath = joinpath(raw_dir, f)
        @assert isfile(fullpath) "Missing raw run file: $fullpath"

        d = load(fullpath)

        @assert haskey(d, "snap") "Missing key: snap in $fullpath"
        snap = d["snap"]

        @assert hasproperty(snap, :perceived_distance_history) "Missing perceived_distance_history in snap of $fullpath"
        pdhist = snap.perceived_distance_history

        @assert length(pdhist) == T "Unexpected perceived_distance_history length in $fullpath"

        firstD = pdhist[1]
        @assert size(firstD) == (N, N) "Unexpected perceived matrix size in $fullpath"

        for t in 1:T
            D = pdhist[t]
            @assert size(D) == (N, N) "Unexpected perceived matrix size at t=$t in $fullpath"

            @inbounds for p in 1:n_pairs
                i, j = pair_map[p]
                PD_pairs_all[r, t, p] = Float32(D[i, j])
            end
        end

        if r == 1 || r % print_every == 0 || r == n_runs
            @printf("Processed %d / %d runs (%.1f%%)\n", r, n_runs, 100r / n_runs)
        end
    end

    jldsave(out_path;
        PD_pairs_all = PD_pairs_all,
        sim = sim_ids,
        bi = bi,
        beta_value = beta_value,
        steps_axis = steps_axis,
        pair_map = pair_map,
        N = N
    )

    bytes_est = n_runs * T * n_pairs * sizeof(Float32)
    gib_est = bytes_est / 1024^3
    gb_est = bytes_est / 10^9

    println("Done.")
    @printf("Estimated raw array size: %.3f GiB (%.3f GB)\n", gib_est, gb_est)

    return (
        out_path = out_path,
        n_runs = n_runs,
        T = T,
        n_pairs = n_pairs,
        N = N
    )
end
# build_all_perceived_pair_distances(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs",
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_CUMPAIR_TALKS_SAMPLED.jld2";
#     out_path = raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_PERCEIVED_PAIR_DISTANCES.jld2",  # nothing/String
#     print_every = 25  # any Int
# )
function build_all_consent_probabilities_from_perceived_pairs(perceived_pairs_path::String; pmin::Float64 = 0.05, pmax::Float64 = 0.95, p0::Float64 = 0.5, out_path::Union{Nothing,String} = nothing, print_every::Int = 25)  # any String, any Float64, any Float64, any Float64, nothing/String, any Int
    @assert isfile(perceived_pairs_path) "File not found: $perceived_pairs_path"
    @assert pmin < pmax "Need pmin < pmax."
    @assert pmin < p0 < pmax "Need pmin < p0 < pmax."
    @assert print_every >= 1 "print_every must be >= 1"

    d = load(perceived_pairs_path)

    @assert haskey(d, "PD_pairs_all") "Missing key: PD_pairs_all"
    @assert haskey(d, "pair_map") "Missing key: pair_map"
    @assert haskey(d, "sim") "Missing key: sim"
    @assert haskey(d, "bi") "Missing key: bi"
    @assert haskey(d, "beta_value") "Missing key: beta_value"
    @assert haskey(d, "steps_axis") "Missing key: steps_axis"
    @assert haskey(d, "N") "Missing key: N"

    PD_pairs_all = d["PD_pairs_all"]                       # runs × T × n_pairs
    pair_map = Tuple{Int,Int}.(d["pair_map"])
    sim = Int.(d["sim"])
    bi = Int.(d["bi"])
    beta_value = Float64.(d["beta_value"])
    steps_axis = Int.(d["steps_axis"])
    N = Int(d["N"])

    n_runs, T, n_pairs = size(PD_pairs_all)

    @assert length(sim) == n_runs
    @assert length(bi) == n_runs
    @assert length(beta_value) == n_runs
    @assert length(pair_map) == n_pairs
    @assert n_pairs == N * (N - 1) ÷ 2 "pair_map length does not match N"

    if out_path === nothing
        dir = dirname(perceived_pairs_path)
        out_path = joinpath(dir, "ALL_CONSENT_PROBABILITIES.jld2")
    end

    P_all = Array{Float32}(undef, n_runs, T, N, N)

    D = zeros(Float64, N, N)
    row_means = zeros(Float64, N)
    row_stds = zeros(Float64, N)

    println("Building consent-probability file")
    println("input:  $perceived_pairs_path")
    println("output: $out_path")
    @printf("runs = %d | time points = %d | N = %d | pairs = %d\n", n_runs, T, N, n_pairs)

    for r in 1:n_runs
        β = beta_value[r]

        for t in 1:T
            fill!(D, 0.0)

            @inbounds for p in 1:n_pairs
                i, j = pair_map[p]
                v = Float64(PD_pairs_all[r, t, p])
                D[i, j] = v
                D[j, i] = v
            end

            @inbounds for i in 1:N
                s = 0.0
                s2 = 0.0
                for k in 1:N
                    if k != i
                        x = D[i, k]
                        s += x
                        s2 += x * x
                    end
                end
                μ = s / (N - 1)
                v = s2 / (N - 1) - μ * μ
                v = max(v, 0.0)
                row_means[i] = μ
                row_stds[i] = sqrt(v)
            end

            @inbounds for i in 1:N
                P_all[r, t, i, i] = 0.0f0
                μ = row_means[i]
                σ = row_stds[i]

                for j in 1:N
                    if j == i
                        continue
                    end

                    z = (σ == 0.0 || !isfinite(σ)) ? 0.0 : ((D[i, j] - μ) / σ)
                    P_all[r, t, i, j] = Float32(consent_prob(z; beta = β, pmin = pmin, pmax = pmax, p0 = p0))
                end
            end
        end

        if r == 1 || r % print_every == 0 || r == n_runs
            @printf("Processed %d / %d runs (%.1f%%)\n", r, n_runs, 100 * r / n_runs)
        end
    end

    jldsave(out_path;
        P_all = P_all,
        sim = sim,
        bi = bi,
        beta_value = beta_value,
        steps_axis = steps_axis,
        N = N
    )

    bytes_est = n_runs * T * N * N * sizeof(Float32)
    gib_est = bytes_est / 1024^3
    gb_est = bytes_est / 10^9

    println("Done.")
    @printf("Estimated raw array size: %.3f GiB (%.3f GB)\n", gib_est, gb_est)

    return (
        out_path = out_path,
        n_runs = n_runs,
        T = T,
        N = N
    )
end
# build_all_consent_probabilities_from_perceived_pairs(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_PERCEIVED_PAIR_DISTANCES.jld2";
#     pmin = 0.05,  # any Float64
#     pmax = 0.95,  # any Float64
#     p0 = 0.5,  # any Float64
#     out_path = raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_CONSENT_PROBABILITIES.jld2",  # nothing/String
#     print_every = 25  # any Int
# )
function build_all_mean_interaction_metrics(consent_path::String; out_path::Union{Nothing,String} = nothing, print_every::Int = 25)  # nothing/String, any Int
    @assert isfile(consent_path) "File not found: $consent_path"
    @assert print_every >= 1 "print_every must be >= 1"

    d = load(consent_path)

    @assert haskey(d, "P_all") "Missing key: P_all"
    @assert haskey(d, "sim") "Missing key: sim"
    @assert haskey(d, "bi") "Missing key: bi"
    @assert haskey(d, "beta_value") "Missing key: beta_value"
    @assert haskey(d, "steps_axis") "Missing key: steps_axis"
    @assert haskey(d, "N") "Missing key: N"

    P_all = d["P_all"]                         # runs × T × N × N
    sim = Int.(d["sim"])
    bi = Int.(d["bi"])
    beta_value = Float64.(d["beta_value"])
    steps_axis = Int.(d["steps_axis"])
    N = Int(d["N"])

    n_runs, T, N1, N2 = size(P_all)

    @assert N1 == N "P_all third dimension does not match N"
    @assert N2 == N "P_all fourth dimension does not match N"
    @assert length(sim) == n_runs
    @assert length(bi) == n_runs
    @assert length(beta_value) == n_runs

    if out_path === nothing
        dir = dirname(consent_path)
        out_path = joinpath(dir, "ALL_MEAN_INTERACTION_METRICS.jld2")
    end

    interaction_mean_all = Array{Float32}(undef, n_runs, T, N)
    agree_out_mean_all = Array{Float32}(undef, n_runs, T, N)
    agree_in_mean_all = Array{Float32}(undef, n_runs, T, N)

    println("Building mean interaction metrics file")
    println("input:  $consent_path")
    println("output: $out_path")
    @printf("runs = %d | time points = %d | N = %d\n", n_runs, T, N)

    @inbounds for r in 1:n_runs
        for t in 1:T
            for i in 1:N
                s_interaction = 0.0
                s_out = 0.0
                s_in = 0.0

                for j in 1:N
                    if j == i
                        continue
                    end

                    pij = Float64(P_all[r, t, i, j])
                    pji = Float64(P_all[r, t, j, i])

                    s_interaction += pij * pji
                    s_out += pij
                    s_in += pji
                end

                interaction_mean_all[r, t, i] = Float32(s_interaction / (N - 1))
                agree_out_mean_all[r, t, i] = Float32(s_out / (N - 1))
                agree_in_mean_all[r, t, i] = Float32(s_in / (N - 1))
            end
        end

        if r == 1 || r % print_every == 0 || r == n_runs
            @printf("Processed %d / %d runs (%.1f%%)\n", r, n_runs, 100 * r / n_runs)
        end
    end

    jldsave(out_path;
        interaction_mean_all = interaction_mean_all,
        agree_out_mean_all = agree_out_mean_all,
        agree_in_mean_all = agree_in_mean_all,
        sim = sim,
        bi = bi,
        beta_value = beta_value,
        steps_axis = steps_axis,
        N = N
    )

    bytes_est = 3 * n_runs * T * N * sizeof(Float32)
    gib_est = bytes_est / 1024^3
    gb_est = bytes_est / 10^9

    println("Done.")
    @printf("Estimated raw array size: %.3f GiB (%.3f GB)\n", gib_est, gb_est)

    return (
        out_path = out_path,
        n_runs = n_runs,
        T = T,
        N = N
    )
end
# build_all_mean_interaction_metrics(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_CONSENT_PROBABILITIES.jld2";
#     out_path = raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\sweep_beta_logs\ALL_MEAN_INTERACTION_METRICS.jld2",  # nothing/String
#     print_every = 25  # any Int
# )
function build_consent_correlation_file(
    consent_path::String;
    out_path::Union{Nothing,String}=nothing,
    print_every::Int=50)
    d = load(consent_path)

    P = d["P_all"]   # runs × T × N × N
    betas = Float64.(d["beta_value"])
    steps_axis = Int.(d["steps_axis"])
    N = Int(d["N"])

    sim = haskey(d, "sim") ? Int.(d["sim"]) : collect(1:size(P, 1))
    bi = haskey(d, "bi") ? Int.(d["bi"]) : zeros(Int, size(P, 1))

    n_runs, T, _, _ = size(P)

    if out_path === nothing
        out_path = joinpath(dirname(consent_path), "ALL_CONSENT_CORRELATIONS.jld2")
    end

    pairs = [(i, j) for i in 1:N-1 for j in i+1:N]
    n_pairs = length(pairs)

    corr_results = Matrix{Float32}(undef, n_runs, T)

    v_ij = Vector{Float64}(undef, n_pairs)
    v_ji = Vector{Float64}(undef, n_pairs)

    println("Building consent-correlation file...")
    println("runs = $n_runs | T = $T | N = $N | pairs = $n_pairs")

    for r in 1:n_runs
        for t in 1:T
            @inbounds for p in 1:n_pairs
                i, j = pairs[p]
                v_ij[p] = Float64(P[r, t, i, j])
                v_ji[p] = Float64(P[r, t, j, i])
            end

            if std(v_ij) > 0 && std(v_ji) > 0
                corr_results[r, t] = Float32(cor(v_ij, v_ji))
            else
                corr_results[r, t] = 1.0f0
            end
        end

        if r == 1 || r % print_every == 0 || r == n_runs
            @printf("Processed %d / %d runs\n", r, n_runs)
        end
    end

    jldsave(out_path;
        corr_results=corr_results,
        beta_value=betas,
        steps_axis=steps_axis,
        sim=sim,
        bi=bi,
        N=N
    )

    println("Saved to: $out_path")

    return out_path
end
# build_consent_correlation_file("sweep_beta_logs/ALL_CONSENT_PROBABILITIES.jld2";out_path="sweep_beta_logs/ALL_CONSENT_CORRELATIONS.jld2")

#some more
function build_or_update_all_means_and_std_over_time(
    agg_path::String;
    runs_dir::Union{Nothing,String} = nothing,
    verbose::Bool = true)

    runs_dir === nothing && (runs_dir = dirname(agg_path))

    # ============================================================
    # 1. Helper: calculate the three metrics for one run
    # ============================================================

    function metrics_from_distances_history(dh)

        T = length(dh)
        out = Matrix{Float64}(undef, T, 3)

        for t in 1:T

            M = dh[t]
            n = size(M, 1)

            offdiag = Float64[]
            sizehint!(offdiag, n * (n - 1))

            colmeans = Vector{Float64}(undef, n)

            for j in 1:n

                s = 0.0

                for i in 1:n

                    if i != j

                        v = Float64(M[i, j])

                        push!(offdiag, v)

                        s += v
                    end
                end

                colmeans[j] =
                    s / (n - 1)
            end

            out[t, 1] =
                Statistics.mean(offdiag)

            out[t, 2] =
                Statistics.std(offdiag)

            out[t, 3] =
                Statistics.std(colmeans)
        end

        return out
    end


    # ============================================================
    # 2. Find all simulation files
    # ============================================================

    all_files =
        sort(readdir(runs_dir))

    run_files =
        filter(
            f -> occursin(
                r"^beta\d+_\d+_sim\d+\.jld2$",
                f
            ),
            all_files
        )

    isempty(run_files) &&
        error("No simulation files found in: $runs_dir")

    verbose && println(
        "Found $(length(run_files)) simulation files."
    )


    # ============================================================
    # 3. Load existing aggregate if it exists
    # ============================================================

    metric_names =
        [
            "mean_offdiag",
            "std_offdiag",
            "std_colmeans"
        ]

    if isfile(agg_path)

        verbose && println(
            "Existing aggregate found: $agg_path"
        )

        d =
            JLD2.load(agg_path)

        metrics_all =
            Array{Float64}(d["metrics_all"])

        beta_value =
            Float64.(d["beta_value"])

        sim =
            Int.(d["sim"])

        bi =
            Int.(d["bi"])

        files =
            String.(d["files"])

        old_metric_names =
            String.(d["metric_names"])

        meta =
            d["meta"]

        @assert old_metric_names == metric_names

        n_old, T_expected, K =
            size(metrics_all)

        @assert K == 3

        existing_pairs =
            Set(
                (beta_value[i], sim[i])
                for i in eachindex(beta_value)
            )

        verbose && println(
            "Existing aggregate contains $n_old runs."
        )

        creating_new =
            false

    else

        verbose && println(
            "No existing aggregate found."
        )

        verbose && println(
            "Creating new aggregate from scratch..."
        )

        metrics_all =
            Array{Float64}(undef, 0, 0, 3)

        beta_value =
            Float64[]

        sim =
            Int[]

        bi =
            Int[]

        files =
            String[]

        existing_pairs =
            Set{Tuple{Float64,Int}}()

        T_expected =
            nothing

        meta =
            nothing

        creating_new =
            true
    end


    # ============================================================
    # 4. Process missing runs
    # ============================================================

    new_metrics =
        Matrix{Float64}[]

    new_betas =
        Float64[]

    new_sims =
        Int[]

    new_bis =
        Int[]

    new_files =
        String[]

    added = 0
    skipped_existing = 0
    skipped_badshape = 0


    for (file_idx, f) in enumerate(run_files)

        fp =
            joinpath(
                runs_dir,
                f
            )

        rd =
            JLD2.load(fp)

        b =
            Float64(rd["beta_value"])

        s =
            Int(rd["sim"])

        pair =
            (b, s)


        # --------------------------------------------------------
        # Already present
        # --------------------------------------------------------

        if pair in existing_pairs

            skipped_existing += 1

            continue
        end


        # --------------------------------------------------------
        # Calculate metrics
        # --------------------------------------------------------

        snap =
            rd["snap"]

        m =
            metrics_from_distances_history(
                snap.distances_history
            )


        # --------------------------------------------------------
        # First run determines expected number of timepoints
        # when creating a new aggregate
        # --------------------------------------------------------

        if T_expected === nothing

            T_expected =
                size(m, 1)

            verbose && println(
                "Detected $T_expected timepoints per run."
            )
        end


        # --------------------------------------------------------
        # Shape check
        # --------------------------------------------------------

        if size(m, 1) != T_expected ||
           size(m, 2) != 3

            skipped_badshape += 1

            if verbose
                println(
                    "Skipping $f because shape does not match."
                )
            end

            continue
        end


        # --------------------------------------------------------
        # Store new run
        # --------------------------------------------------------

        push!(
            new_metrics,
            m
        )

        push!(
            new_betas,
            b
        )

        push!(
            new_sims,
            s
        )

        push!(
            new_bis,
            haskey(rd, "bi") ?
            Int(rd["bi"]) :
            0
        )

        push!(
            new_files,
            f
        )

        push!(
            existing_pairs,
            pair
        )

        added += 1


        # --------------------------------------------------------
        # Metadata when building from scratch
        # --------------------------------------------------------

        if creating_new &&
           meta === nothing

            if haskey(rd, "meta")

                meta =
                    rd["meta"]

            else

                meta =
                    Dict{String,Any}()
            end
        end


        # --------------------------------------------------------
        # Progress
        # --------------------------------------------------------

        if verbose &&
           (
               added == 1 ||
               added % 25 == 0
           )

            println(
                "Added $added new runs " *
                "(scanned $file_idx / $(length(run_files)))..."
            )
        end
    end


    # ============================================================
    # 5. Nothing new
    # ============================================================

    if added == 0

        verbose && println()
        verbose && println("No new runs added.")
        verbose && println(
            "Existing runs skipped: $skipped_existing"
        )
        verbose && println(
            "Bad-shape runs skipped: $skipped_badshape"
        )

        return (
            added = 0,
            skipped_existing = skipped_existing,
            skipped_badshape = skipped_badshape,
            out_path = agg_path
        )
    end


    # ============================================================
    # 6. Convert new metrics to 3D array
    # ============================================================

    M_new =
        Array{Float64}(
            undef,
            added,
            T_expected,
            3
        )

    for i in 1:added

        M_new[i, :, :] =
            new_metrics[i]
    end


    # ============================================================
    # 7. Combine old and new data
    # ============================================================

    if creating_new

        metrics_combined =
            M_new

    else

        metrics_combined =
            cat(
                metrics_all,
                M_new;
                dims = 1
            )
    end


    beta_combined =
        vcat(
            beta_value,
            new_betas
        )

    sim_combined =
        vcat(
            sim,
            new_sims
        )

    bi_combined =
        vcat(
            bi,
            new_bis
        )

    files_combined =
        vcat(
            files,
            new_files
        )


    # ============================================================
    # 8. Sort by beta and simulation number
    # ============================================================

    ord =
        sortperm(
            collect(
                1:length(beta_combined)
            );
            by = i -> (
                beta_combined[i],
                sim_combined[i]
            )
        )

    metrics_combined =
        metrics_combined[
            ord,
            :,
            :
        ]

    beta_combined =
        beta_combined[ord]

    sim_combined =
        sim_combined[ord]

    bi_combined =
        bi_combined[ord]

    files_combined =
        files_combined[ord]


    # ============================================================
    # 9. Save
    # ============================================================

    JLD2.jldsave(
        agg_path;

        metrics_all =
            metrics_combined,

        beta_value =
            beta_combined,

        sim =
            sim_combined,

        bi =
            bi_combined,

        files =
            files_combined,

        metric_names =
            metric_names,

        meta =
            meta
    )


    # ============================================================
    # 10. Summary
    # ============================================================

    verbose && println()
    verbose && println(
        "Saved aggregate to: $agg_path"
    )

    verbose && println(
        "New runs added: $added"
    )

    verbose && println(
        "Existing runs skipped: $skipped_existing"
    )

    verbose && println(
        "Bad-shape runs skipped: $skipped_badshape"
    )

    verbose && println(
        "Total runs in aggregate: $(length(beta_combined))"
    )


    return (
        added = added,
        skipped_existing = skipped_existing,
        skipped_badshape = skipped_badshape,
        total_runs = length(beta_combined),
        out_path = agg_path
    )
end
# build_or_update_all_means_and_std_over_time(
#     "sweep_beta_logs/ALL_MEANS_AND_STD_OVER_TIME.jld2";
#     runs_dir = "sweep_beta_logs"
# )
function build_consent_probability_aggregate(
    runs_dir::String,
    out_path::String;
    p0::Float64 = 0.5,
    pmin::Float64 = 0.05,
    pmax::Float64 = 0.95,
    verbose::Bool = true)

    # ============================================================
    # 1. Read META
    # ============================================================

    meta_path = joinpath(runs_dir, "META.jld2")
    @assert isfile(meta_path) "META.jld2 not found in $runs_dir"

    meta = JLD2.load(meta_path)

    N = Int(meta["N"])
    steps = Int(meta["steps"])
    record_every = Int(meta["record_every"])

    @assert pmin < p0 < pmax

    steps_axis = collect(0:record_every:steps)
    T_expected = length(steps_axis)


    # ============================================================
    # 2. Find simulation files
    # ============================================================

    all_files = readdir(runs_dir)

    run_files = String[]

    for f in all_files

        m = match(
            r"^beta\d+_\d+_sim\d+\.jld2$",
            f
        )

        m === nothing && continue

        push!(run_files, f)
    end

    isempty(run_files) &&
        error("No simulation files found in $runs_dir")


    # ============================================================
    # 3. Sort files by beta and simulation number
    # ============================================================

    function file_beta_sim(f::String)

        m = match(
            r"^beta(\d+)_(\d+)_sim(\d+)\.jld2$",
            f
        )

        @assert m !== nothing

        beta =
            parse(Float64, m.captures[1]) +
            parse(Float64, m.captures[2]) / 10.0

        sim =
            parse(Int, m.captures[3])

        return beta, sim
    end


    sort!(
        run_files;
        by = f -> file_beta_sim(f)
    )


    # ============================================================
    # 4. Directed pair map
    #
    # (i,j) means:
    # probability that agent i accepts agent j
    # ============================================================

    directed_pair_map =
        Tuple{Int,Int}[]

    for i in 1:N
        for j in 1:N

            i == j && continue

            push!(
                directed_pair_map,
                (i, j)
            )
        end
    end

    P =
        length(directed_pair_map)

    @assert P == N * (N - 1)


    # ============================================================
    # 5. Storage
    # ============================================================

    n_files =
        length(run_files)

    consent_prob_all =
        Array{Float64}(
            undef,
            n_files,
            T_expected,
            P
        )

    perceived_z_all =
        Array{Float64}(
            undef,
            n_files,
            T_expected,
            P
        )

    beta_value_all =
        Vector{Float64}(
            undef,
            n_files
        )

    sim_all =
        Vector{Int}(
            undef,
            n_files
        )

    bi_all =
        Vector{Int}(
            undef,
            n_files
        )

    kept_files =
        Vector{String}(
            undef,
            n_files
        )


    # ============================================================
    # 6. Process each simulation
    # ============================================================

    for (r, filename) in enumerate(run_files)

        if verbose
            println(
                "Processing run ",
                r,
                " / ",
                n_files,
                ": ",
                filename
            )
        end


        path =
            joinpath(
                runs_dir,
                filename
            )

        d =
            JLD2.load(path)


        # --------------------------------------------------------
        # Run metadata
        # --------------------------------------------------------

        beta_value =
            Float64(d["beta_value"])

        sim =
            Int(d["sim"])

        bi =
            Int(d["bi"])

        snap =
            d["snap"]


        beta_value_all[r] =
            beta_value

        sim_all[r] =
            sim

        bi_all[r] =
            bi

        kept_files[r] =
            filename


        # --------------------------------------------------------
        # Perceived-distance history
        # --------------------------------------------------------

        pd_history =
            snap.perceived_distance_history


        @assert length(pd_history) == T_expected """
        Unexpected perceived_distance_history length in:
        $filename

        Expected: $T_expected
        Found: $(length(pd_history))
        """


        # ========================================================
        # 7. Every recorded timepoint
        # ========================================================

        for t in 1:T_expected

            D =
                pd_history[t]

            @assert size(D, 1) == N
            @assert size(D, 2) == N


            # ----------------------------------------------------
            # Compute row mean and SD once per agent
            # ----------------------------------------------------

            row_mean =
                Vector{Float64}(undef, N)

            row_sd =
                Vector{Float64}(undef, N)


            for i in 1:N

                μ, σ =
                    row_mean_std_offdiag(
                        D,
                        i
                    )

                row_mean[i] =
                    μ

                row_sd[i] =
                    σ
            end


            # ----------------------------------------------------
            # Every directed pair i -> j
            # ----------------------------------------------------

            for p in 1:P

                i, j =
                    directed_pair_map[p]

                μ =
                    row_mean[i]

                σ =
                    row_sd[i]


                z =
                    if σ == 0.0 ||
                       !isfinite(σ)

                        0.0

                    else

                        (
                            Float64(D[i, j]) -
                            μ
                        ) / σ
                    end


                prob =
                    consent_prob(
                        z;
                        beta = beta_value,
                        pmin = pmin,
                        pmax = pmax,
                        p0 = p0
                    )


                perceived_z_all[
                    r,
                    t,
                    p
                ] = z


                consent_prob_all[
                    r,
                    t,
                    p
                ] = prob
            end
        end
    end


    # ============================================================
    # 8. Sanity checks
    # ============================================================

    @assert all(
        isfinite,
        consent_prob_all
    )

    @assert all(
        pmin .<= consent_prob_all .<= pmax
    )

    @assert all(
        isfinite,
        perceived_z_all
    )


    # ============================================================
    # 9. Save aggregate
    # ============================================================

    JLD2.jldsave(
        out_path;

        consent_prob_all =
            consent_prob_all,

        perceived_z_all =
            perceived_z_all,

        directed_pair_map =
            directed_pair_map,

        steps_axis =
            steps_axis,

        beta_value =
            beta_value_all,

        sim =
            sim_all,

        bi =
            bi_all,

        files =
            kept_files,

        N =
            N,

        p0 =
            p0,

        pmin =
            pmin,

        pmax =
            pmax
    )


    # ============================================================
    # 10. Summary
    # ============================================================

    println()
    println("Finished.")
    println("Saved to: $out_path")
    println()
    println("Runs: $n_files")
    println("Timepoints per run: $T_expected")
    println("Directed pairs per timepoint: $P")
    println(
        "consent_prob_all size: ",
        size(consent_prob_all)
    )
    println(
        "perceived_z_all size: ",
        size(perceived_z_all)
    )


    return (
        out_path =
            out_path,

        n_runs =
            n_files,

        n_timepoints =
            T_expected,

        n_directed_pairs =
            P,

        steps_axis =
            steps_axis,

        directed_pair_map =
            directed_pair_map
    )
end
# consent_summary =
#     build_consent_probability_aggregate(
#         "sweep_beta_logs",
#         "ALL_CONSENT_PROBABILITIES.jld2"
# )
function build_mutual_consent_probability_aggregate(
    consent_path::String,
    out_path::String;
    verbose::Bool = true)

    # ----------------------------
    # Load
    # ----------------------------
    d = JLD2.load(consent_path)

    consent_prob_all = d["consent_prob_all"]
    directed_pair_map = Tuple{Int,Int}.(d["directed_pair_map"])

    steps_axis = Int.(d["steps_axis"])
    beta_value = Float64.(d["beta_value"])
    sim = Int.(d["sim"])
    bi = Int.(d["bi"])
    files = d["files"]

    N = Int(d["N"])

    p0 = Float64(d["p0"])
    pmin = Float64(d["pmin"])
    pmax = Float64(d["pmax"])

    n_runs, T, n_directed_pairs = size(consent_prob_all)

    @assert n_directed_pairs == N * (N - 1)
    @assert length(steps_axis) == T
    @assert length(beta_value) == n_runs
    @assert length(sim) == n_runs


    # ----------------------------
    # Undirected pair map
    # ----------------------------
    pair_map = Tuple{Int,Int}[]

    for i in 1:(N - 1)
        for j in (i + 1):N
            push!(pair_map, (i, j))
        end
    end

    n_pairs = length(pair_map)

    @assert n_pairs == N * (N - 1) ÷ 2


    # ----------------------------
    # Map directed pairs to indices
    # ----------------------------
    directed_lookup = Dict{Tuple{Int,Int},Int}()

    for (p, pair) in enumerate(directed_pair_map)
        directed_lookup[pair] = p
    end


    # ----------------------------
    # Allocate
    #
    # run × timepoint × pair
    # ----------------------------
    mutual_consent_prob_all =
        Array{Float64}(undef, n_runs, T, n_pairs)


    # ----------------------------
    # Calculate mutual consent
    # ----------------------------
    for (p, (i, j)) in enumerate(pair_map)

        if verbose && (p == 1 || p % 25 == 0 || p == n_pairs)
            println("Processing pair $p / $n_pairs")
        end

        p_ij = directed_lookup[(i, j)]
        p_ji = directed_lookup[(j, i)]

        @views mutual_consent_prob_all[:, :, p] .=
            consent_prob_all[:, :, p_ij] .*
            consent_prob_all[:, :, p_ji]
    end


    # ----------------------------
    # Sanity checks
    # ----------------------------
    @assert all(isfinite, mutual_consent_prob_all)
    @assert all(0.0 .<= mutual_consent_prob_all .<= 1.0)


    # ----------------------------
    # Save
    # ----------------------------
    JLD2.jldsave(
        out_path;
        mutual_consent_prob_all = mutual_consent_prob_all,
        pair_map = pair_map,
        steps_axis = steps_axis,
        beta_value = beta_value,
        sim = sim,
        bi = bi,
        files = files,
        N = N,
        p0 = p0,
        pmin = pmin,
        pmax = pmax
    )


    println("\nFinished.")
    println("Saved to: $out_path")
    println("Runs: $n_runs")
    println("Timepoints: $T")
    println("Pairs: $n_pairs")
    println("Size: $(size(mutual_consent_prob_all))")


    return (
        out_path = out_path,
        n_runs = n_runs,
        n_timepoints = T,
        n_pairs = n_pairs,
        steps_axis = steps_axis,
        pair_map = pair_map
    )
end
# build_mutual_consent_probability_aggregate(
#     "ALL_CONSENT_PROBABILITIES.jld2",
#     "ALL_MUTUAL_CONSENT_PROBABILITIES.jld2"
# )
function build_social_and_self_talk_summary(
    runs_dir::String,
    out_path::String;
    steps::Int = 20_000,
    window_size::Int = 100,
    reset_every::Int = 100,
    self_talk_threshold::Int = 10,
    self_talk_duration::Int = 3,
    N::Int = 20,
    verbose::Bool = true)

    @assert steps % window_size == 0
    @assert window_size > 0
    @assert reset_every > 0

    # ============================================================
    # 1. Find simulation files
    #
    # IMPORTANT:
    # beta and sim are extracted ONLY from the filename.
    # No JLD2 files are loaded at this stage.
    #
    # Expected filenames:
    # beta0_0_sim1.jld2
    # beta0_5_sim1.jld2
    # beta14_0_sim150.jld2
    # ============================================================

    file_regex = r"^beta(\d+)_(\d+)_sim(\d+)\.jld2$"

    file_info = NamedTuple[]

    for file in readdir(runs_dir)
        m = match(file_regex, file)
        m === nothing && continue

        beta_integer = parse(Int, m.captures[1])
        beta_decimal = parse(Int, m.captures[2])
        sim = parse(Int, m.captures[3])

        # For the current sweep filenames, the decimal component
        # represents one decimal place: 0_5 -> 0.5, 10_0 -> 10.0.
        beta_value = beta_integer + beta_decimal / 10

        push!(
            file_info,
            (
                file = file,
                beta_value = Float64(beta_value),
                sim = sim
            )
        )
    end

    @assert !isempty(file_info) "No simulation files found in $runs_dir"

    sort!(file_info, by = x -> (x.beta_value, x.sim))

    n_runs = length(file_info)
    n_windows = steps ÷ window_size
    total_rows = n_runs * N * n_windows

    if verbose
        println("Found $n_runs simulation files.")
        println(
            "β range: ",
            minimum(x.beta_value for x in file_info),
            " to ",
            maximum(x.beta_value for x in file_info)
        )
        println("Agents per simulation: $N")
        println("Windows per simulation: $n_windows")
        println("Expected output rows: $total_rows")
        println()
        flush(stdout)
    end


    # ============================================================
    # 2. Allocate final summary columns
    # ============================================================

    beta_col = Vector{Float64}(undef, total_rows)
    sim_col = Vector{Int}(undef, total_rows)
    agent_col = Vector{Int}(undef, total_rows)

    window_col = Vector{Int}(undef, total_rows)
    window_start_col = Vector{Int}(undef, total_rows)
    window_end_col = Vector{Int}(undef, total_rows)

    social_col = Vector{Int}(undef, total_rows)
    self_col = Vector{Int}(undef, total_rows)
    neither_col = Vector{Int}(undef, total_rows)

    row_idx = 0


    # ============================================================
    # 3. Process each simulation
    # ============================================================

    for (run_idx, info) in enumerate(file_info)

        if verbose
            println(
                "Run $run_idx / $n_runs | ",
                "β = $(info.beta_value) | ",
                "sim = $(info.sim)"
            )
            flush(stdout)
        end

        # Each simulation file is loaded exactly ONCE.
        path = joinpath(runs_dir, info.file)
        d = JLD2.load(path)

        snap = d["snap"]
        conversation_events = snap.conversation_events


        # ========================================================
        # 4. Reconstruct social conversation at every step
        #
        # social_talk[i,t] == true iff agent i actually executed
        # the social conversation phase at step t.
        #
        # conversation_events is logged immediately before
        # conversation!(...) in step!.
        # ========================================================

        social_talk = falses(N, steps)

        for event in conversation_events

            t = Int(event.t)

            if 1 <= t <= steps
                for agent in event.members
                    i = Int(agent)

                    @assert 1 <= i <= N

                    social_talk[i, t] = true
                end
            end
        end


        # ========================================================
        # 5. Reconstruct self-talk exactly according to step!
        #
        # We do NOT infer self-talk simply from stretches of
        # inactivity. We replay the actual timer logic:
        #
        #   time_since_last_talk
        #   self_talk_left
        #
        # including reset_positions_and_interactions! before
        # step! at t = 100, 200, ...
        # ========================================================

        self_talk = falses(N, steps)

        time_since_last_talk = zeros(Int, N)
        self_talk_left = zeros(Int, N)

        for t in 1:steps

            # ----------------------------------------------------
            # This reproduces the runner:
            #
            # if step_i % reset_every == 0
            #     reset_positions_and_interactions!(world)
            # end
            #
            # reset_positions_and_interactions! does:
            #
            # fill!(world.time_since_last_talk, 0)
            # fill!(world.self_talk_left, 0)
            #
            # BEFORE step! is called.
            # ----------------------------------------------------

            if t % reset_every == 0
                fill!(time_since_last_talk, 0)
                fill!(self_talk_left, 0)
            end


            # ----------------------------------------------------
            # Reproduce section 2 of step!:
            # Self-conversation phase
            # ----------------------------------------------------

            @inbounds for i in 1:N

                if social_talk[i, t]

                    # In step!:
                    #
                    # else
                    #     world.time_since_last_talk[i] = 0
                    # end

                    time_since_last_talk[i] = 0

                else

                    if self_talk_left[i] > 0

                        # Existing self-talk episode
                        self_talk[i, t] = true

                        self_talk_left[i] -= 1

                    else

                        # Not socially talking and not currently
                        # in an existing self-talk episode.
                        time_since_last_talk[i] += 1

                        if time_since_last_talk[i] >= self_talk_threshold

                            # Exact equivalent of:
                            #
                            # world.self_talk_left[i] = 3
                            # self_conversation!(...)
                            # world.self_talk_count[i] += 1
                            # world.self_talk_left[i] -= 1
                            # world.time_since_last_talk[i] = 0

                            self_talk_left[i] = self_talk_duration

                            self_talk[i, t] = true

                            self_talk_left[i] -= 1

                            time_since_last_talk[i] = 0
                        end
                    end
                end
            end
        end


        # ========================================================
        # 6. Aggregate reconstructed trajectories into windows
        #
        # Window 1   = steps 1:100
        # Window 2   = steps 101:200
        # ...
        # Window 200 = steps 19901:20000
        #
        # The reset timing has ALREADY been handled above exactly
        # as in the simulation. Windowing here is only aggregation.
        # ========================================================

        for w in 1:n_windows

            first_step = (w - 1) * window_size + 1
            last_step = w * window_size

            for i in 1:N

                social_steps = count(
                    @view social_talk[i, first_step:last_step]
                )

                self_steps = count(
                    @view self_talk[i, first_step:last_step]
                )

                # A social conversation and self-talk cannot occur
                # for the same agent during the same step.
                @assert !any(
                    (@view social_talk[i, first_step:last_step]) .&
                    (@view self_talk[i, first_step:last_step])
                )

                neither_steps =
                    window_size - social_steps - self_steps

                @assert neither_steps >= 0
                @assert social_steps + self_steps + neither_steps == window_size

                row_idx += 1

                beta_col[row_idx] = info.beta_value
                sim_col[row_idx] = info.sim
                agent_col[row_idx] = i

                window_col[row_idx] = w
                window_start_col[row_idx] = first_step
                window_end_col[row_idx] = last_step

                social_col[row_idx] = social_steps
                self_col[row_idx] = self_steps
                neither_col[row_idx] = neither_steps
            end
        end

        # Explicitly release the large loaded objects before
        # moving to the next simulation.
        d = nothing
        snap = nothing
        conversation_events = nothing
    end


    # ============================================================
    # 7. Final checks
    # ============================================================

    @assert row_idx == total_rows


    # ============================================================
    # 8. Build summary DataFrame
    # ============================================================

    summary = DataFrames.DataFrame(
        beta_value = beta_col,
        sim = sim_col,
        agent = agent_col,

        window = window_col,
        window_start = window_start_col,
        window_end = window_end_col,

        social_talk_steps = social_col,
        self_talk_steps = self_col,
        neither_steps = neither_col
    )


    # ============================================================
    # 9. Global sanity checks
    # ============================================================

    @assert all(
        summary.social_talk_steps .+
        summary.self_talk_steps .+
        summary.neither_steps
        .== window_size
    )

    @assert all(summary.social_talk_steps .>= 0)
    @assert all(summary.self_talk_steps .>= 0)
    @assert all(summary.neither_steps .>= 0)

    @assert minimum(summary.beta_value) == 0.0


    # ============================================================
    # 10. Save
    # ============================================================

    JLD2.jldsave(
        out_path;
        summary = summary,
        steps = steps,
        window_size = window_size,
        reset_every = reset_every,
        N = N,
        self_talk_threshold = self_talk_threshold,
        self_talk_duration = self_talk_duration
    )

    if verbose
        println()
        println("========================================")
        println("Finished")
        println("========================================")
        println("Runs processed: $n_runs")
        println("Rows saved: ", DataFrames.nrow(summary))
        println(
            "β values: ",
            sort(unique(summary.beta_value))
        )
        println("Saved to: $out_path")
        flush(stdout)
    end

    return summary
end
# talk_summary = build_social_and_self_talk_summary(
#     "sweep_beta_logs",
#     "SOCIAL_SELF_TALK_BY_100_STEPS.jld2"
# )
function build_semantic_change_by_source_summary(
    runs_dir::String,
    out_path::String;
    initial_matrix_sum::Real,
    steps::Int = 20_000,
    window_size::Int = 100,
    reset_every::Int = 100,
    self_talk_threshold::Int = 10,
    self_talk_duration::Int = 3,
    L::Int = 25,
    social_impact::Real = 1.0,
    N::Int = 20,
    verbose::Bool = true)

    @assert steps % window_size == 0
    @assert initial_matrix_sum > 0
    @assert social_impact > 0

    # ============================================================
    # 1. Find simulation files
    #
    # beta and sim are extracted ONLY from filenames.
    # No files are loaded here.
    # ============================================================

    file_regex = r"^beta(\d+)_(\d+)_sim(\d+)\.jld2$"

    file_info = NamedTuple[]

    for file in readdir(runs_dir)

        m = match(file_regex, file)
        m === nothing && continue

        beta_integer = parse(Int, m.captures[1])
        beta_decimal = parse(Int, m.captures[2])
        sim = parse(Int, m.captures[3])

        beta_value = beta_integer + beta_decimal / 10

        push!(
            file_info,
            (
                file = file,
                beta_value = Float64(beta_value),
                sim = sim
            )
        )
    end

    @assert !isempty(file_info) "No simulation files found in $runs_dir"

    sort!(file_info, by = x -> (x.beta_value, x.sim))

    n_runs = length(file_info)
    n_windows = steps ÷ window_size
    total_rows = n_runs * N * n_windows

    if verbose
        println("Found $n_runs simulation files.")
        println(
            "β range: ",
            minimum(x.beta_value for x in file_info),
            " to ",
            maximum(x.beta_value for x in file_info)
        )
        println("Agents per simulation: $N")
        println("Windows per simulation: $n_windows")
        println("Initial matrix sum: $(Float64(initial_matrix_sum))")
        println("L: $L")
        println("Expected output rows: $total_rows")
        println()
        flush(stdout)
    end


    # ============================================================
    # 2. Allocate output
    # ============================================================

    beta_col = Vector{Float64}(undef, total_rows)
    sim_col = Vector{Int}(undef, total_rows)
    agent_col = Vector{Int}(undef, total_rows)

    window_col = Vector{Int}(undef, total_rows)
    window_start_col = Vector{Int}(undef, total_rows)
    window_end_col = Vector{Int}(undef, total_rows)

    social_steps_col = Vector{Int}(undef, total_rows)
    self_steps_col = Vector{Int}(undef, total_rows)
    neither_steps_col = Vector{Int}(undef, total_rows)

    matrix_sum_start_col = Vector{Float64}(undef, total_rows)
    matrix_sum_end_col = Vector{Float64}(undef, total_rows)

    social_change_col = Vector{Float64}(undef, total_rows)
    self_change_col = Vector{Float64}(undef, total_rows)
    total_change_col = Vector{Float64}(undef, total_rows)

    row_idx = 0


    # ============================================================
    # 3. Precompute constants
    # ============================================================

    # Each association adds social_impact to two symmetric cells.
    association_sum_increase = 2.0 * Float64(social_impact)

    # Total absolute matrix-sum increase from one complete
    # conversation/self-conversation step.
    event_sum_increase =
        association_sum_increase * L


    # ============================================================
    # 4. Process simulations
    # ============================================================

    for (run_idx, info) in enumerate(file_info)

        if verbose
            println(
                "Run $run_idx / $n_runs | ",
                "β = $(info.beta_value) | ",
                "sim = $(info.sim)"
            )
            flush(stdout)
        end

        # Load this simulation exactly once.
        path = joinpath(runs_dir, info.file)
        d = JLD2.load(path)

        snap = d["snap"]
        conversation_events = snap.conversation_events


        # ========================================================
        # 5. Reconstruct actual social conversation steps
        # ========================================================

        social_talk = falses(N, steps)

        for event in conversation_events

            t = Int(event.t)

            if 1 <= t <= steps
                for agent in event.members

                    i = Int(agent)

                    @assert 1 <= i <= N

                    social_talk[i, t] = true
                end
            end
        end


        # ========================================================
        # 6. State variables
        # ========================================================

        time_since_last_talk = zeros(Int, N)
        self_talk_left = zeros(Int, N)

        # Matrix sum for every agent.
        matrix_sum = fill(
            Float64(initial_matrix_sum),
            N
        )

        # Current 100-step-window accumulators
        social_steps_window = zeros(Int, N)
        self_steps_window = zeros(Int, N)

        social_change_window = zeros(Float64, N)
        self_change_window = zeros(Float64, N)

        matrix_sum_window_start = copy(matrix_sum)


        # ========================================================
        # 7. Replay the simulation step by step
        # ========================================================

        for t in 1:steps

            # ----------------------------------------------------
            # Reset occurs BEFORE step! at 100, 200, ...
            #
            # It resets the self-talk timers, but DOES NOT reset
            # the semantic networks or their matrix sums.
            # ----------------------------------------------------

            if t % reset_every == 0
                fill!(time_since_last_talk, 0)
                fill!(self_talk_left, 0)
            end


            # ----------------------------------------------------
            # Process every agent exactly according to whether
            # this step contains social conversation or self-talk.
            # ----------------------------------------------------

            @inbounds for i in 1:N

                if social_talk[i, t]

                    # =================================================
                    # SOCIAL CONVERSATION
                    # =================================================

                    social_steps_window[i] += 1

                    S = matrix_sum[i]

                    # L semantic associations.
                    #
                    # Association 1:
                    #       2 / S
                    #
                    # Association 2:
                    #       2 / (S + 2)
                    #
                    # ...
                    #
                    # with social_impact incorporated explicitly.
                    change_this_step = 0.0

                    for k in 0:(L - 1)

                        denominator =
                            S + association_sum_increase * k

                        change_this_step +=
                            association_sum_increase / denominator
                    end

                    social_change_window[i] += change_this_step

                    # Exact increase in agent_sum after L updates.
                    matrix_sum[i] += event_sum_increase

                    # Same logic as step!:
                    # talking resets the inactivity timer.
                    time_since_last_talk[i] = 0


                else

                    # =================================================
                    # NOT IN SOCIAL CONVERSATION
                    # =================================================

                    if self_talk_left[i] > 0

                        # ---------------------------------------------
                        # Existing self-talk episode
                        # ---------------------------------------------

                        self_steps_window[i] += 1

                        S = matrix_sum[i]

                        change_this_step = 0.0

                        for k in 0:(L - 1)

                            denominator =
                                S + association_sum_increase * k

                            change_this_step +=
                                association_sum_increase / denominator
                        end

                        self_change_window[i] += change_this_step

                        matrix_sum[i] += event_sum_increase

                        self_talk_left[i] -= 1


                    else

                        # ---------------------------------------------
                        # No social talk and no active self-talk
                        # ---------------------------------------------

                        time_since_last_talk[i] += 1

                        if time_since_last_talk[i] >= self_talk_threshold

                            # Self-talk starts immediately on this step.
                            self_talk_left[i] = self_talk_duration

                            self_steps_window[i] += 1

                            S = matrix_sum[i]

                            change_this_step = 0.0

                            for k in 0:(L - 1)

                                denominator =
                                    S + association_sum_increase * k

                                change_this_step +=
                                    association_sum_increase / denominator
                            end

                            self_change_window[i] += change_this_step

                            matrix_sum[i] += event_sum_increase

                            # First self-talk step already occurred.
                            self_talk_left[i] -= 1

                            time_since_last_talk[i] = 0
                        end
                    end
                end
            end


            # ====================================================
            # 8. End of a 100-step analysis window
            # ====================================================

            if t % window_size == 0

                w = t ÷ window_size

                first_step =
                    (w - 1) * window_size + 1

                last_step = t

                for i in 1:N

                    row_idx += 1

                    social_steps =
                        social_steps_window[i]

                    self_steps =
                        self_steps_window[i]

                    neither_steps =
                        window_size -
                        social_steps -
                        self_steps

                    @assert neither_steps >= 0

                    social_change =
                        social_change_window[i]

                    self_change =
                        self_change_window[i]

                    total_change =
                        social_change + self_change


                    beta_col[row_idx] = info.beta_value
                    sim_col[row_idx] = info.sim
                    agent_col[row_idx] = i

                    window_col[row_idx] = w
                    window_start_col[row_idx] = first_step
                    window_end_col[row_idx] = last_step

                    social_steps_col[row_idx] = social_steps
                    self_steps_col[row_idx] = self_steps
                    neither_steps_col[row_idx] = neither_steps

                    matrix_sum_start_col[row_idx] =
                        matrix_sum_window_start[i]

                    matrix_sum_end_col[row_idx] =
                        matrix_sum[i]

                    social_change_col[row_idx] =
                        social_change

                    self_change_col[row_idx] =
                        self_change

                    total_change_col[row_idx] =
                        total_change
                end


                # -----------------------------------------------
                # Prepare accumulators for next 100-step window
                # -----------------------------------------------

                fill!(social_steps_window, 0)
                fill!(self_steps_window, 0)

                fill!(social_change_window, 0.0)
                fill!(self_change_window, 0.0)

                matrix_sum_window_start .= matrix_sum
            end
        end

        d = nothing
        snap = nothing
        conversation_events = nothing
    end


    # ============================================================
    # 9. Sanity checks
    # ============================================================

    @assert row_idx == total_rows

    @assert all(
        matrix_sum_end_col .>= matrix_sum_start_col
    )

    @assert all(social_change_col .>= 0.0)
    @assert all(self_change_col .>= 0.0)


    # ============================================================
    # 10. Build DataFrame
    # ============================================================

    summary = DataFrames.DataFrame(
        beta_value = beta_col,
        sim = sim_col,
        agent = agent_col,

        window = window_col,
        window_start = window_start_col,
        window_end = window_end_col,

        social_talk_steps = social_steps_col,
        self_talk_steps = self_steps_col,
        neither_steps = neither_steps_col,

        matrix_sum_start = matrix_sum_start_col,
        matrix_sum_end = matrix_sum_end_col,

        social_semantic_change = social_change_col,
        self_semantic_change = self_change_col,
        total_semantic_change = total_change_col
    )


    # ============================================================
    # 11. Strong consistency check
    #
    # Every social/self step must increase matrix sum by exactly
    # 2 * social_impact * L.
    # ============================================================

    expected_absolute_increase =
        (
            summary.social_talk_steps .+
            summary.self_talk_steps
        ) .* event_sum_increase

    actual_absolute_increase =
        summary.matrix_sum_end .-
        summary.matrix_sum_start

    @assert all(
        isapprox.(
            actual_absolute_increase,
            expected_absolute_increase;
            atol = 1e-8,
            rtol = 1e-10
        )
    )

    @assert all(
        summary.social_talk_steps .+
        summary.self_talk_steps .+
        summary.neither_steps
        .== window_size
    )

    @assert minimum(summary.beta_value) == 0.0


    # ============================================================
    # 12. Save
    # ============================================================

    JLD2.jldsave(
        out_path;
        summary = summary,

        initial_matrix_sum = Float64(initial_matrix_sum),

        steps = steps,
        window_size = window_size,
        reset_every = reset_every,

        N = N,
        L = L,

        self_talk_threshold = self_talk_threshold,
        self_talk_duration = self_talk_duration,

        social_impact = Float64(social_impact),
        association_sum_increase = association_sum_increase,
        event_sum_increase = event_sum_increase
    )


    if verbose
        println()
        println("========================================")
        println("Finished")
        println("========================================")
        println("Runs processed: $n_runs")
        println("Rows saved: ", DataFrames.nrow(summary))
        println("Initial matrix sum: ", Float64(initial_matrix_sum))
        println("Increase per semantic step: ", event_sum_increase)
        println("Saved to: $out_path")
        flush(stdout)
    end

    return summary
end
