#region Part B
function short_form_conversations!(world::World;   #with isolated_agent
    talk_duration::Int=3,
    pmin::Real=0.05,
    pmax::Real=0.95,
    p0::Real=0.5,
    join_rule::Symbol=:neighbors_any)

    N = world.N

    # -----------------------------
    # Stage A: Try to join existing conversations
    # -----------------------------
    free_agents = [i for i in 1:N if world.talking_group[i] == 0 && world.self_talk_left[i] == 0 && world.can_talk[i]]
    shuffle!(free_agents)

    for i in free_agents
        xi, yi = world.x[i], world.y[i]

        # collect candidate neighbors j that are in an existing group
        neighbors_in_groups = Int[]
        for (dx, dy) in NEIGHBOR_8
            nx, ny = xi + dx, yi + dy
            if !in_bounds(nx, ny, world.W, world.H)
                continue
            end
            j = world.occ[ny, nx]
            if j != 0 && world.talking_group[j] != 0 && world.can_talk[j] && !is_refractory(world.refr_partners, world.refr_left, i, j)
                push!(neighbors_in_groups, j)
            end
        end

        isempty(neighbors_in_groups) && continue
        shuffle!(neighbors_in_groups)

        tried_gids = Set{Int}()

        for j in neighbors_in_groups
            gid = world.talking_group[j]
            if gid in tried_gids
                continue
            end
            push!(tried_gids, gid)

            ask = Int[]

            if join_rule == :neighbors_any
                for (dx, dy) in NEIGHBOR_8
                    nx, ny = xi + dx, yi + dy
                    in_bounds(nx, ny, world.W, world.H) || continue
                    k = world.occ[ny, nx]
                    if k != 0 &&
                       world.talking_group[k] == gid &&
                       world.can_talk[k] &&
                       !is_refractory(world.refr_partners, world.refr_left, i, k)
                        push!(ask, k)
                    end
                end
            elseif join_rule == :group_any || join_rule == :group_all
                for k in 1:world.N
                    if world.talking_group[k] == gid &&
                       world.can_talk[k] &&
                       !is_refractory(world.refr_partners, world.refr_left, i, k)
                        push!(ask, k)
                    end
                end

            else
                error("Unknown join_rule = $join_rule")
            end

            isempty(ask) && continue
            shuffle!(ask)


            joined = false

            if join_rule == :neighbors_any || join_rule == :group_any
                for k in ask
                    if world.isolated_agent !== nothing &&
                       (i == world.isolated_agent || k == world.isolated_agent)

                        success_ik = rand() < world.isolated_agent_interaction_prob

                        if !success_ik
        
                            continue
                        end

                        joined = true
                        break

                    else
                        ai = accepts(world, i, k; pmin=pmin, pmax=pmax, p0=p0)
                        ai || continue

                        if world.silent[i]
                    
                            joined = true
                            break
                        end

                        ak = accepts(world, k, i; pmin=pmin, pmax=pmax, p0=p0)
                        if !ak
        
                            continue
                        end

                        joined = true
                        break
                    end
                end

            elseif join_rule == :group_all
                joined = true
                for k in ask
                    if world.isolated_agent !== nothing &&
                       (i == world.isolated_agent || k == world.isolated_agent)

                        success_ik = rand() < world.isolated_agent_interaction_prob

                        if !success_ik
                
                            joined = false
                            break
                        end

             

                    else
                        ai = accepts(world, i, k; pmin=pmin, pmax=pmax, p0=p0)
                        if !ai
                            joined = false
                            break
                        end

                        if world.silent[i]
                            continue
                        end

                        ak = accepts(world, k, i; pmin=pmin, pmax=pmax, p0=p0)
                        if !ak
                            
                            joined = false
                            break
                        end

                        
                    end
                end
            end

            

            if joined
                world.talking_group[i] = gid
                world.talk_left[i] = talk_duration
                empty!(world.agent_seen_partners[i])
                for k in 1:world.N
                    if world.talking_group[k] == gid && k != i
                        push!(world.agent_seen_partners[i], k)
                        push!(world.agent_seen_partners[k], i)
                    end
                end
                break
            end
        end
    end

    # -----------------------------
    # Stage B: Create new conversations among still-free agents
    # -----------------------------
    still_free = [i for i in 1:N if world.talking_group[i] == 0 && world.self_talk_left[i] == 0 && world.can_talk[i]]
    clusters = find_clusters(world, still_free)  # your existing physical cluster finder (neighbors-touching)

    for cluster in clusters

        
        # Build adjacency list for consent graph (on physical neighbors only)
        adj = Dict{Int,Vector{Int}}()
        for i in cluster
            adj[i] = Int[]
        end

        # For each unordered adjacent physical pair, sample acceptances once
        # (We only consider edges if they are physical neighbors in the grid)
        in_cluster = Set(cluster)  # cluster sizes are typically small; ok
        for i in cluster
            xi, yi = world.x[i], world.y[i]
            for (dx, dy) in NEIGHBOR_8
                nx, ny = xi + dx, yi + dy
                in_bounds(nx, ny, world.W, world.H) || continue
                j = world.occ[ny, nx]
                if j == 0 || !(j in in_cluster) || j <= i
                    continue
                end
                if is_refractory(world.refr_partners, world.refr_left, i, j)
                    continue
                end

                # this pair was considered (so both "asked" about each other)

                if world.isolated_agent !== nothing &&
                   (i == world.isolated_agent || j == world.isolated_agent)

                    success_ij = rand() < world.isolated_agent_interaction_prob

                    if success_ij
                        push!(adj[i], j)
                        push!(adj[j], i)   
                    end
                else
                    ai = accepts(world, i, j; pmin=pmin, pmax=pmax, p0=p0)
                    aj = accepts(world, j, i; pmin=pmin, pmax=pmax, p0=p0)

                    if ai && aj
                        push!(adj[i], j)
                        push!(adj[j], i)
                    end
                end
            end
        end

        # Connected components in consent graph
        visited = Set{Int}()
        components = Vector{Vector{Int}}()

        for i in cluster
            if i in visited
                continue
            end
            stack = [i]
            push!(visited, i)
            comp = Int[]
            while !isempty(stack)
                v = pop!(stack)
                push!(comp, v)
                for u in adj[v]
                    if !(u in visited)
                        push!(visited, u)
                        push!(stack, u)
                    end
                end
            end
            # isolates (degree 0) will produce comp of size 1
            if length(comp) > 1
                push!(components, comp)
            end
        end

        # Create a conversation for each component
        for comp in components
            gid = world.next_group_id
            world.next_group_id += 1
            for i in comp
                world.talking_group[i] = gid
                world.talk_left[i] = talk_duration
                empty!(world.agent_seen_partners[i])
            end
        end

    end

    return nothing
end
function short_step!(world::World;
    talk_duration::Int=5,
    refractory_duration::Int=10,
    self_talk_threshold::Int=10,
    L::Int=10,
    eta::Float32=0.5f0,
    beta_for_consent::Real=10.0,
    gamma::Union{Nothing,Real}=nothing,
    beta::Union{Nothing,Real}=nothing,
    delta::Union{Nothing,Real}=nothing,
    p0::Union{Nothing,Real}=nothing,
    pmin::Real=0.05,
    record_distances::Bool=true,
    record_every::Int=1,
    social_impact::Float64=1.0,
    join_rule::Symbol=:group_any,
    social_learning_prob=ones(Float32, world.N))

    # --- Update parameters if provided ---
    if gamma !== nothing world.γ = Float32(gamma) end
    if beta !== nothing world.β = Float32(beta) end
    if delta !== nothing world.δ = Float32(delta) end
    if p0 !== nothing world.p0 = Float32(p0) end
    if beta_for_consent !== nothing world.beta_for_consent = Float32(beta_for_consent) end

    world.t += 1

    # 1) Group Conversation Phase
    group_ids = unique(world.talking_group)
    talked_groups = Vector{Vector{Int}}()

    for gid in group_ids
        gid == 0 && continue

        # Identify current group members
        members = [i for i in 1:world.N if world.talking_group[i] == gid]
        Lm = length(members)

        # Handle fragmented groups (less than 2 agents)
        if Lm < 2
            if Lm == 1
                if world.talk_left[members[1]] > 0
                    mark_abandonment!(world, members[1])
                end
                end_conversation_for_agent!(world, members[1], refractory_duration)
            end
            continue
        end
        # Check for silence (no speakers)
        all_silent = true
        nspeakers = 0
        @inbounds for m in members
            if !world.silent[m]
                nspeakers += 1
                if nspeakers >= 2
                    all_silent = false
                    break
                end
            end
        end

        if all_silent
            # If no one talks, they experience abandonment and group dissolves
            @inbounds for m in members
                for other in members
                    if m != other push!(world.agent_seen_partners[m], other) end
                end
                if world.talk_left[m] > 0 mark_abandonment!(world, m) end
                end_conversation_for_agent!(world, m, refractory_duration)
            end
            continue
        end

        push!(talked_groups, members)
        speakers = Int[]
        @inbounds for m in members
            if !world.silent[m]
                push!(speakers, m)
            end
        end

        conversation!(members, world, L; social_impact=social_impact,social_learning_prob=social_learning_prob)

        for i in members
            world.talk_left[i] -= 1
        end
    end

    # End Conversation & Refractory Check
    for i in 1:world.N
        if world.talking_group[i] != 0 && world.talk_left[i] <= 0
            end_conversation_for_agent!(world, i, refractory_duration)
        end
    end

    # 2) Self-conversation phase
    for i in 1:world.N
        if world.talking_group[i] == 0
            if world.self_talk_left[i] > 0
                self_conversation!(i, world, L)
                world.self_talk_count[i] += 1
                world.self_talk_left[i] -= 1
            else
                world.time_since_last_talk[i] += 1
                if world.time_since_last_talk[i] >= self_talk_threshold  # threshold
                    world.self_talk_left[i] = 3  # self-talk duration
                    self_conversation!(i, world, L)
                    world.self_talk_count[i] += 1
                    world.self_talk_left[i] -= 1  # decrement immediately after first call
                    world.time_since_last_talk[i] = 0
                end
            end
        else
            world.time_since_last_talk[i] = 0  # reset if talking
        end
    end

    # --- 3) Semantic Updates (Perception) ---
    if eta != 0.0f0
        for group in talked_groups
            # No need to pass current_distances anymore
            update_perceived_group!(world, group; eta=eta)
        end
    end

    if record_distances && (world.t % record_every == 0)
        world.current_distances .= Float32.(differences(world.agents))  # או פונקציה יעילה משלך
        push!(world.distances_history, copy(world.current_distances))
    end


    # 4) Movement and Adjacency Logging
    move_agents!(world)

    # 5) Social Interaction Initiation
    short_form_conversations!(world; talk_duration=talk_duration, pmin=pmin,p0=p0, join_rule=join_rule)

    # 6) Refractory Period Update
    for i in 1:world.N
        if !isempty(world.refr_partners[i])
            tick_refractory!(world.refr_partners, world.refr_left, i)
        end
    end

    return nothing
end

# ============================================================
# Helpers
# ============================================================
@inline function schedule_beta(
    t::Real,
    center::Real,
    sigma::Real,
    floor::Real,
    ceiling::Real)
    if floor == ceiling
        return Float64(floor)
    end

    return Float64(
        floor +
        (ceiling - floor) *
        exp(-0.5 * ((t - center) / sigma)^2)
    )
end
@inline function schedule_run_filename(
    pi::Int,
    center::Real,
    sigma::Real,
    floor::Real,
    ceiling::Real,
    sim::Int)
    c_str  = replace(string(center), "." => "_")
    s_str  = replace(string(sigma), "." => "_")
    f_str  = replace(string(floor), "." => "_")
    ce_str = replace(string(ceiling), "." => "_")

    return "ps$(pi)_c$(c_str)_s$(s_str)_f$(f_str)_ce$(ce_str)_sim$(sim).jld2"
end
# ============================================================
# Existing simulations — FILENAMES ONLY
# ============================================================
function existing_schedule_sims(
    outdir::AbstractString,
    pi::Int,
    center::Real,
    sigma::Real,
    floor::Real,
    ceiling::Real)
    isdir(outdir) || return Int[]

    c_str  = replace(string(center), "." => "_")
    s_str  = replace(string(sigma), "." => "_")
    f_str  = replace(string(floor), "." => "_")
    ce_str = replace(string(ceiling), "." => "_")

    prefix = "ps$(pi)_c$(c_str)_s$(s_str)_f$(f_str)_ce$(ce_str)_sim"

    sims = Int[]

    for f in readdir(outdir)
        startswith(f, prefix) || continue
        endswith(f, ".jld2") || continue

        mtch = match(r"_sim(\d+)\.jld2$", f)
        mtch === nothing && continue

        push!(sims, parse(Int, mtch.captures[1]))
    end

    sort!(unique!(sims))
    return sims
end
# ============================================================
# META comparison
# ============================================================
function values_match(a, b)
    if a === nothing || b === nothing
        return a === b
    elseif a isa AbstractFloat || b isa AbstractFloat
        return isapprox(Float64(a), Float64(b); atol=1e-8, rtol=1e-8)
    else
        return a == b
    end
end
function check_existing_meta!(
    meta_path::AbstractString,
    expected_meta::Dict{String,Any})
    existing = JLD2.load(meta_path)

    # n_sim may increase.
    # param_sets may be extended at the end.
    keys_to_check = setdiff(
        collect(keys(expected_meta)),
        ["n_sim", "param_sets"]
    )

    mismatches = String[]

    # --------------------------------------------------------
    # Check all ordinary META fields
    # --------------------------------------------------------

    for key in keys_to_check
        if !haskey(existing, key)
            push!(mismatches, "$key: missing from existing META")
            continue
        end

        old = existing[key]
        new = expected_meta[key]

        if !values_match(old, new)
            push!(
                mismatches,
                "$key: existing = $(repr(old)), requested = $(repr(new))"
            )
        end
    end


    # --------------------------------------------------------
    # Check param_sets separately
    #
    # Existing paramsets must remain exactly the same.
    # New paramsets may only be appended at the end.
    # --------------------------------------------------------

    if !haskey(existing, "param_sets")

        push!(
            mismatches,
            "param_sets: missing from existing META"
        )

    else

        old_param_sets = existing["param_sets"]
        new_param_sets = expected_meta["param_sets"]

        if length(new_param_sets) < length(old_param_sets)

            push!(
                mismatches,
                "param_sets: requested list has fewer parameter sets " *
                "than existing META " *
                "($(length(new_param_sets)) vs $(length(old_param_sets)))"
            )

        else

            for i in eachindex(old_param_sets)

                old_ps = old_param_sets[i]
                new_ps = new_param_sets[i]

                for field in (:center, :sigma, :floor, :ceiling)

                    old_value = getproperty(old_ps, field)
                    new_value = getproperty(new_ps, field)

                    if !values_match(old_value, new_value)

                        push!(
                            mismatches,
                            "param_sets[$i].$field: " *
                            "existing = $(repr(old_value)), " *
                            "requested = $(repr(new_value))"
                        )
                    end
                end
            end
        end
    end


    # --------------------------------------------------------
    # Stop if anything is incompatible
    # --------------------------------------------------------

    if !isempty(mismatches)

        msg = join(mismatches, "\n  ")

        error(
            "Existing META does not match requested " *
            "simulation settings:\n  " *
            msg
        )
    end

    return existing
end
# ============================================================
# Main function
# ============================================================
function run_developmental_homophily_sweep!(
    param_sets::AbstractVector{<:NamedTuple};
    outdir::AbstractString,
    n_sim::Int = 200,

    # -------------------------
    # World parameters
    # -------------------------
    N::Int = 20,
    W::Int = 30,
    H::Int = 30,
    n::Int = 300,
    m::Int = 4,
    change::Float64 = 0.7,

    abandonment_threshold::Int = 10_000_000,
    outliers_count::Int = 0,
    outlier_change::Union{Nothing,Float64} = nothing,

    # -------------------------
    # Simulation parameters
    # -------------------------
    steps::Int = 40_000,
    reset_every::Int = 100,

    talk_duration::Int = 10,
    refractory_duration::Int = 10,
    self_talk_threshold::Int = 10,

    L::Int = 25,
    eta::Float32 = 0.2f0,

    gamma::Float64 = 0.0,
    beta_move::Float64 = 1.0,
    delta::Float64 = 1.0,

    p0::Float64 = 0.5,
    pmin::Float64 = 0.05,

    record_distances::Bool = true,
    record_every::Int = 100,

    social_impact::Float64 = 1.0,
    join_rule::Symbol = :group_any,

    seed::Union{Nothing,Int} = nothing)

    n_sim >= 1 || error("n_sim must be >= 1")
    steps >= 1 || error("steps must be >= 1")
    record_every >= 1 || error("record_every must be >= 1")
    isempty(param_sets) && error("param_sets cannot be empty")

    # ========================================================
    # Validate parameter sets
    # ========================================================

    required_fields = (:center, :sigma, :floor, :ceiling)

    for (pi, ps) in enumerate(param_sets)

        for field in required_fields
            hasproperty(ps, field) ||
                error("Paramset $pi is missing field: $field")
        end

        if ps.floor != ps.ceiling && ps.sigma <= 0
            error(
                "Paramset $pi has a developmental schedule but sigma <= 0."
            )
        end
    end


    # ========================================================
    # META
    # ========================================================

    expected_meta = Dict{String,Any}(
        "N" => N,
        "W" => W,
        "H" => H,
        "n" => n,
        "m" => m,
        "change" => change,

        "abandonment_threshold" => abandonment_threshold,
        "outliers_count" => outliers_count,
        "outlier_change" => outlier_change,

        "steps" => steps,
        "reset_every" => reset_every,

        "talk_duration" => talk_duration,
        "refractory_duration" => refractory_duration,
        "self_talk_threshold" => self_talk_threshold,

        "L" => L,
        "eta" => eta,

        "gamma" => gamma,
        "beta_move" => beta_move,
        "delta" => delta,

        "p0" => p0,
        "pmin" => pmin,

        "record_distances" => record_distances,
        "record_every" => record_every,

        "social_impact" => social_impact,
        "join_rule" => join_rule,

        "seed" => seed,

        "param_sets" => collect(param_sets),

        "n_sim" => n_sim,

        # Explicitly document that step 0 is included
        "record_initial_distances" => true
    )


    # ========================================================
    # Directory / META
    # ========================================================

    if !isdir(outdir)
        mkpath(outdir)
        println("Created directory: $outdir")
    end

    meta_path = joinpath(outdir, "META.jld2")

    if isfile(meta_path)

        existing_meta = check_existing_meta!(
            meta_path,
            expected_meta
        )

        old_n_sim = haskey(existing_meta, "n_sim") ?
                    Int(existing_meta["n_sim"]) : 0

        old_n_paramsets = haskey(existing_meta, "param_sets") ?
                        length(existing_meta["param_sets"]) : 0

        new_n_paramsets = length(param_sets)

        update_meta =
            n_sim > old_n_sim ||
            new_n_paramsets > old_n_paramsets

        if update_meta

            # Never decrease the target stored in META
            expected_meta["n_sim"] = max(n_sim, old_n_sim)

            JLD2.jldopen(meta_path, "w") do f
                for (key, value) in expected_meta
                    f[key] = value
                end
            end

            println(
                "META verified and updated: " *
                "$old_n_paramsets → $new_n_paramsets paramsets, " *
                "target n_sim=$(expected_meta["n_sim"])"
            )

        else
            println("META verified.")
        end

    else

        existing_jld2 = filter(
            f -> endswith(f, ".jld2"),
            readdir(outdir)
        )

        if !isempty(existing_jld2)
            error(
                "Directory contains .jld2 files but no META.jld2. " *
                "Refusing to mix simulations."
            )
        end

        JLD2.jldopen(meta_path, "w") do f
            for (key, value) in expected_meta
                f[key] = value
            end
        end
        println("Created META.jld2")
    end


    # ========================================================
    # Seed
    # ========================================================

    if seed !== nothing
        Random.seed!(seed)
    end


    # ========================================================
    # Run parameter sets
    # ========================================================

    total_paramsets = length(param_sets)

    for (pi, ps) in enumerate(param_sets)

        center  = Float64(ps.center)
        sigma   = Float64(ps.sigma)
        floor   = Float64(ps.floor)
        ceiling = Float64(ps.ceiling)

        # ----------------------------------------------------
        # Detect existing simulations by FILENAMES ONLY
        # ----------------------------------------------------

        existing = existing_schedule_sims(
            outdir,
            pi,
            center,
            sigma,
            floor,
            ceiling
        )

        existing_set = Set(existing)

        missing_sims = [
            sim for sim in 1:n_sim
            if !(sim in existing_set)
        ]

        n_existing_target = count(sim -> sim in existing_set, 1:n_sim)

        println()
        println(
            "Paramset $pi/$total_paramsets: " *
            "$n_existing_target/$n_sim existing" *
            (isempty(missing_sims) ?
                " — complete" :
                " → $(length(missing_sims)) to run")
        )

        isempty(missing_sims) && continue


        # ----------------------------------------------------
        # Precompute β schedule
        # ----------------------------------------------------

        consent_homophily = Vector{Float64}(undef, steps)

        if floor == ceiling
            fill!(consent_homophily, floor)
        else
            @inbounds for t in 1:steps
                consent_homophily[t] = schedule_beta(
                    t,
                    center,
                    sigma,
                    floor,
                    ceiling
                )
            end
        end


        # ----------------------------------------------------
        # Simulations
        # ----------------------------------------------------

        for sim in missing_sims

            println("  Running $sim/$n_sim")

            filename = schedule_run_filename(
                pi,
                center,
                sigma,
                floor,
                ceiling,
                sim
            )

            fpath = joinpath(outdir, filename)

            isfile(fpath) && continue


            # =================================================
            # Initialize world
            # =================================================

            if outlier_change === nothing
                w = init_world(
                    N,
                    W,
                    H,
                    n,
                    m,
                    change;
                    abandonment_threshold = abandonment_threshold,
                    outliers_count = outliers_count
                )
            else
                w = init_world(
                    N,
                    W,
                    H,
                    n,
                    m,
                    change;
                    abandonment_threshold = abandonment_threshold,
                    outliers_count = outliers_count,
                    outlier_change = outlier_change
                )
            end

            # =================================================
            # Run simulation
            # =================================================

            for t in 1:steps

                if reset_every > 0 && (t % reset_every == 0)
                    reset_positions_and_interactions!(w)
                end

                short_step!(
                    w;
                    talk_duration = talk_duration,
                    refractory_duration = refractory_duration,
                    self_talk_threshold = self_talk_threshold,

                    L = L,
                    eta = eta,

                    beta_for_consent = consent_homophily[t],

                    gamma = gamma,
                    beta = beta_move,
                    delta = delta,

                    p0 = p0,
                    pmin = pmin,

                    record_distances = record_distances,
                    record_every = record_every,

                    social_impact = social_impact,
                    join_rule = join_rule
                )
            end


            # =================================================
            # Save
            # =================================================

            distances_history = w.distances_history

            # Sanity check
            if record_distances && steps % record_every == 0
                expected_records = 1 + div(steps, record_every)

                length(distances_history) == expected_records ||
                    error(
                        "Unexpected number of distance records in " *
                        "paramset=$pi, sim=$sim: " *
                        "$(length(distances_history)) found, " *
                        "$expected_records expected."
                    )
            end

            paramset_idx = pi

            center_value  = center
            sigma_value   = sigma
            floor_value   = floor
            ceiling_value = ceiling

            JLD2.jldsave(
                fpath;
                distances_history = distances_history,
                paramset_idx = paramset_idx,
                sim = sim,
                center_value = center_value,
                sigma_value = sigma_value,
                floor_value = floor_value,
                ceiling_value = ceiling_value
            )
        end
    end


    println()
    println("Sweep complete.")
    println("Directory: $outdir")

    return nothing
end
