# ============================================================
# Convert one N×N distance matrix to N z-scores
# ============================================================
@inline function z_from_distance_matrix!(
    z::Vector{Float32},
    tmp_rowmeans::Vector{Float64},
    D::AbstractMatrix{<:Real})
    N = size(D, 1)

    @assert size(D, 2) == N "Distance matrix must be square."
    @assert length(z) == N
    @assert length(tmp_rowmeans) == N

    # Mean distance of each agent from all OTHER agents
    @inbounds for i in 1:N
        s = 0.0

        for j in 1:N
            j == i && continue
            s += Float64(D[i, j])
        end

        tmp_rowmeans[i] = s / (N - 1)
    end

    μ = Statistics.mean(tmp_rowmeans)
    σ = Statistics.std(tmp_rowmeans)

    if σ == 0.0 || !isfinite(σ)
        fill!(z, 0.0f0)
    else
        invσ = 1.0 / σ

        @inbounds for i in 1:N
            z[i] = Float32(
                (tmp_rowmeans[i] - μ) * invσ
            )
        end
    end

    return z
end
# ============================================================
# Incrementally create/update aggregate Z-score file
# ============================================================
function update_developmental_homophily_zscores!(
    outdir::AbstractString;
    outfile::AbstractString = "ALL_ZSCORES_AND_RUNINFO.jld2",
    verbose_every::Int = 25)

    isdir(outdir) ||
        error("Directory does not exist: $outdir")

    meta_path = joinpath(outdir, "META.jld2")

    isfile(meta_path) ||
        error("META.jld2 not found in: $outdir")


    # ========================================================
    # 1. Read META
    # ========================================================

    meta = JLD2.load(meta_path)

    N = Int(meta["N"])
    steps = Int(meta["steps"])
    record_every = Int(meta["record_every"])

    record_initial_distances =
        haskey(meta, "record_initial_distances") ?
        Bool(meta["record_initial_distances"]) :
        true

    record_initial_distances ||
        error(
            "META says record_initial_distances=false. " *
            "This aggregate function expects step 0 to be recorded."
        )

    steps % record_every == 0 ||
        error(
            "steps=$steps is not divisible by " *
            "record_every=$record_every."
        )

    steps_axis = collect(0:record_every:steps)
    T = length(steps_axis)


    # ========================================================
    # 2. Find run files
    #
    # IMPORTANT:
    # only filenames are inspected here.
    # Run files are NOT opened yet.
    # ========================================================

    run_files_in_dir = filter(
        f ->
            startswith(f, "ps") &&
            endswith(f, ".jld2") &&
            occursin(r"_sim\d+\.jld2$", f),
        readdir(outdir)
    )

    isempty(run_files_in_dir) &&
        error("No simulation run files found in: $outdir")


    # Helper for sorting:
    # ps1 ... sim1
    # ps1 ... sim2
    # ...
    # ps2 ... sim1
    function file_indices(filename::AbstractString)

        mtch = match(
            r"^ps(\d+).*_sim(\d+)\.jld2$",
            filename
        )

        mtch === nothing &&
            error("Could not parse filename: $filename")

        return (
            parse(Int, mtch.captures[1]),
            parse(Int, mtch.captures[2])
        )
    end

    sort!(
        run_files_in_dir;
        by = file_indices
    )


    # ========================================================
    # 3. Check whether aggregate already exists
    # ========================================================

    aggregate_path = joinpath(outdir, outfile)

    if isfile(aggregate_path)

        println("Loading existing aggregate...")

        old = JLD2.load(aggregate_path)

        required_keys = [
            "Z_all",
            "steps_axis",
            "paramset_idx",
            "sim",
            "center_value",
            "sigma_value",
            "floor_value",
            "ceiling_value",
            "run_files",
            "N",
            "steps",
            "record_every"
        ]

        for key in required_keys
            haskey(old, key) ||
                error(
                    "Existing aggregate is missing key: $key"
                )
        end


        # ----------------------------------------------------
        # Validate aggregate against META
        # ----------------------------------------------------

        Int(old["N"]) == N ||
            error(
                "N mismatch: aggregate=$(old["N"]), META=$N"
            )

        Int(old["steps"]) == steps ||
            error(
                "steps mismatch: aggregate=$(old["steps"]), META=$steps"
            )

        Int(old["record_every"]) == record_every ||
            error(
                "record_every mismatch: " *
                "aggregate=$(old["record_every"]), " *
                "META=$record_every"
            )

        old_steps_axis = Int.(old["steps_axis"])

        old_steps_axis == steps_axis ||
            error(
                "steps_axis in existing aggregate does not " *
                "match META."
            )


        # ----------------------------------------------------
        # Load existing aggregate
        # ----------------------------------------------------

        Z_old = old["Z_all"]

        ndims(Z_old) == 3 ||
            error("Existing Z_all must be 3-dimensional.")

        size(Z_old, 2) == T ||
            error(
                "Existing Z_all has $(size(Z_old, 2)) " *
                "timepoints; expected $T."
            )

        size(Z_old, 3) == N ||
            error(
                "Existing Z_all has $(size(Z_old, 3)) " *
                "agents; expected $N."
            )

        old_paramset_idx = Int.(old["paramset_idx"])
        old_sim = Int.(old["sim"])

        old_center_value = Float64.(old["center_value"])
        old_sigma_value = Float64.(old["sigma_value"])
        old_floor_value = Float64.(old["floor_value"])
        old_ceiling_value = Float64.(old["ceiling_value"])

        old_run_files = String.(old["run_files"])


        # Basic internal consistency
        R_old = size(Z_old, 1)

        length(old_paramset_idx) == R_old ||
            error("paramset_idx length mismatch.")

        length(old_sim) == R_old ||
            error("sim length mismatch.")

        length(old_center_value) == R_old ||
            error("center_value length mismatch.")

        length(old_sigma_value) == R_old ||
            error("sigma_value length mismatch.")

        length(old_floor_value) == R_old ||
            error("floor_value length mismatch.")

        length(old_ceiling_value) == R_old ||
            error("ceiling_value length mismatch.")

        length(old_run_files) == R_old ||
            error("run_files length mismatch.")


        # ----------------------------------------------------
        # Find NEW files using filenames only
        # ----------------------------------------------------

        old_file_set = Set(old_run_files)

        new_files = [
            f for f in run_files_in_dir
            if !(f in old_file_set)
        ]

        println("Existing aggregate: $R_old runs")
        println("Run files in directory: $(length(run_files_in_dir))")
        println("New runs to process: $(length(new_files))")

        if isempty(new_files)
            println("Aggregate is already up to date.")

            return (
                path = aggregate_path,
                n_runs = R_old,
                n_new = 0,
                size = size(Z_old)
            )
        end


    else

        # ====================================================
        # No aggregate yet
        # ====================================================

        println("No existing aggregate found.")
        println("Creating new aggregate.")

        Z_old = Array{Float32}(undef, 0, T, N)

        old_paramset_idx = Int[]
        old_sim = Int[]

        old_center_value = Float64[]
        old_sigma_value = Float64[]
        old_floor_value = Float64[]
        old_ceiling_value = Float64[]

        old_run_files = String[]

        new_files = copy(run_files_in_dir)

        R_old = 0

        println("Run files to process: $(length(new_files))")
    end


    # ========================================================
    # 4. Allocate ONLY for new runs
    # ========================================================

    R_new = length(new_files)

    Z_new = Array{Float32}(undef, R_new, T, N)

    new_paramset_idx = Vector{Int}(undef, R_new)
    new_sim = Vector{Int}(undef, R_new)

    new_center_value = Vector{Float64}(undef, R_new)
    new_sigma_value = Vector{Float64}(undef, R_new)
    new_floor_value = Vector{Float64}(undef, R_new)
    new_ceiling_value = Vector{Float64}(undef, R_new)

    new_run_files = Vector{String}(undef, R_new)

    tmp_rowmeans = Vector{Float64}(undef, N)
    z = Vector{Float32}(undef, N)


    # ========================================================
    # 5. Process ONLY new run files
    # ========================================================

    for (r, filename) in enumerate(new_files)

        if r == 1 ||
           r % verbose_every == 0 ||
           r == R_new

            println("Processing new run $r/$R_new")
        end

        path = joinpath(outdir, filename)

        d = JLD2.load(path)


        # ----------------------------------------------------
        # Required run information
        # ----------------------------------------------------

        required_run_keys = [
            "distances_history",
            "paramset_idx",
            "sim",
            "center_value",
            "sigma_value",
            "floor_value",
            "ceiling_value"
        ]

        for key in required_run_keys
            haskey(d, key) ||
                error(
                    "Run file $filename is missing key: $key"
                )
        end


        # ----------------------------------------------------
        # Metadata
        # ----------------------------------------------------

        new_paramset_idx[r] = Int(d["paramset_idx"])
        new_sim[r] = Int(d["sim"])

        new_center_value[r] =
            Float64(d["center_value"])

        new_sigma_value[r] =
            Float64(d["sigma_value"])

        new_floor_value[r] =
            Float64(d["floor_value"])

        new_ceiling_value[r] =
            Float64(d["ceiling_value"])

        new_run_files[r] = filename


        # ----------------------------------------------------
        # Validate filename against stored pi/sim
        # ----------------------------------------------------

        filename_pi, filename_sim =
            file_indices(filename)

        filename_pi == new_paramset_idx[r] ||
            error(
                "Paramset mismatch in $filename: " *
                "filename=$filename_pi, " *
                "file contents=$(new_paramset_idx[r])"
            )

        filename_sim == new_sim[r] ||
            error(
                "Simulation number mismatch in $filename: " *
                "filename=$filename_sim, " *
                "file contents=$(new_sim[r])"
            )


        # ----------------------------------------------------
        # Distance history
        # ----------------------------------------------------

        distances_history =
            d["distances_history"]

        length(distances_history) == T ||
            error(
                "Wrong number of timepoints in $filename: " *
                "$(length(distances_history)) found, " *
                "$T expected."
            )


        # ----------------------------------------------------
        # Calculate z-scores
        # ----------------------------------------------------

        for t in 1:T

            D = distances_history[t]

            size(D) == (N, N) ||
                error(
                    "Wrong distance matrix size in $filename " *
                    "at timepoint $t: " *
                    "$(size(D)), expected ($N, $N)."
                )

            z_from_distance_matrix!(
                z,
                tmp_rowmeans,
                D
            )

            @inbounds for agent in 1:N
                Z_new[r, t, agent] = z[agent]
            end
        end
    end


    # ========================================================
    # 6. Append old + new
    # ========================================================

    Z_all = cat(
        Z_old,
        Z_new;
        dims = 1
    )

    paramset_idx = vcat(
        old_paramset_idx,
        new_paramset_idx
    )

    sim = vcat(
        old_sim,
        new_sim
    )

    center_value = vcat(
        old_center_value,
        new_center_value
    )

    sigma_value = vcat(
        old_sigma_value,
        new_sigma_value
    )

    floor_value = vcat(
        old_floor_value,
        new_floor_value
    )

    ceiling_value = vcat(
        old_ceiling_value,
        new_ceiling_value
    )

    run_files = vcat(
        old_run_files,
        new_run_files
    )


    # ========================================================
    # 7. Sort complete aggregate by paramset and sim
    # ========================================================

    order = sortperm(
        eachindex(paramset_idx);
        by = i -> (
            paramset_idx[i],
            sim[i]
        )
    )

    Z_all = Z_all[order, :, :]

    paramset_idx = paramset_idx[order]
    sim = sim[order]

    center_value = center_value[order]
    sigma_value = sigma_value[order]
    floor_value = floor_value[order]
    ceiling_value = ceiling_value[order]

    run_files = run_files[order]


    # ========================================================
    # 8. Check for duplicate paramset/sim combinations
    # ========================================================

    run_ids = collect(zip(paramset_idx, sim))

    length(unique(run_ids)) == length(run_ids) ||
        error(
            "Duplicate (paramset_idx, sim) combinations " *
            "found in aggregate."
        )


    # ========================================================
    # 9. Save updated aggregate
    # ========================================================

    JLD2.jldsave(
        aggregate_path;

        Z_all = Z_all,
        steps_axis = steps_axis,

        paramset_idx = paramset_idx,
        sim = sim,

        center_value = center_value,
        sigma_value = sigma_value,
        floor_value = floor_value,
        ceiling_value = ceiling_value,

        run_files = run_files,

        N = N,
        steps = steps,
        record_every = record_every,
        record_initial_distances = true
    )


    # ========================================================
    # 10. Summary
    # ========================================================

    println()
    println("Aggregate updated.")
    println("Added: $R_new runs")
    println("Total: $(size(Z_all, 1)) runs")
    println("Z_all size: $(size(Z_all))")
    println("Saved: $aggregate_path")

    println()

    for pi in sort(unique(paramset_idx))

        inds = findall(==(pi), paramset_idx)

        first_r = first(inds)

        println(
            "Paramset $pi: $(length(inds)) runs | " *
            "floor=$(floor_value[first_r]), " *
            "ceiling=$(ceiling_value[first_r]), " *
            "center=$(center_value[first_r]), " *
            "sigma=$(sigma_value[first_r])"
        )
    end


    return (
        path = aggregate_path,
        n_runs = size(Z_all, 1),
        n_new = R_new,
        size = size(Z_all)
    )
end
# res = update_developmental_homophily_zscores!(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\developmental_homophily_40000"
# )
function extract_persistent_outliers(
    z_path::AbstractString;
    threshold::Real = 2.5,
    max_step::Union{Nothing,Int} = nothing)

    d = JLD2.load(z_path)

    Z_all = d["Z_all"]
    steps_axis_full = Int.(d["steps_axis"])
    paramset_idx = Int.(d["paramset_idx"])
    sim = Int.(d["sim"])

    center_value = Float64.(d["center_value"])
    sigma_value = Float64.(d["sigma_value"])
    floor_value = Float64.(d["floor_value"])
    ceiling_value = Float64.(d["ceiling_value"])

    R, T_full, N = size(Z_all)

    # ------------------------------------------------------------
    # Determine final analyzed timepoint
    # ------------------------------------------------------------

    if max_step === nothing
        final_t = T_full
    else
        final_t = findfirst(==(max_step), steps_axis_full)

        final_t === nothing &&
            error(
                "max_step=$max_step is not a recorded timepoint."
            )
    end

    steps_axis = steps_axis_full[1:final_t]
    analysis_end_step = steps_axis[end]

    # ------------------------------------------------------------
    # One row per RUN
    # ------------------------------------------------------------

    runs = DataFrames.DataFrame(
        paramset_idx = Int[],
        sim = Int[],
        has_persistent_outlier = Bool[],
        n_persistent_outliers = Int[]
    )

    # ------------------------------------------------------------
    # One row per persistent OUTLIER AGENT
    # ------------------------------------------------------------

    outliers = DataFrames.DataFrame(
        paramset_idx = Int[],
        sim = Int[],
        agent = Int[],
        crossing_t = Int[],
        crossing_step = Int[],
        final_z = Float64[]
    )

    println(
        "Finding persistent outliers in $R runs " *
        "through step $analysis_end_step..."
    )

    # ------------------------------------------------------------
    # Analyze
    # ------------------------------------------------------------

    for r in 1:R

        n_outliers = 0

        for agent in 1:N

            ztraj = @view Z_all[r, 1:final_t, agent]

            crossing_t = nothing

            # Search backwards:
            # find the beginning of the final continuous period
            # during which this SAME agent remains >= threshold.
            if ztraj[end] >= threshold

                t = final_t

                while t > 1 && ztraj[t - 1] >= threshold
                    t -= 1
                end

                crossing_t = t
            end

            if crossing_t !== nothing

                n_outliers += 1

                push!(
                    outliers,
                    (
                        paramset_idx[r],
                        sim[r],
                        agent,
                        crossing_t,
                        steps_axis[crossing_t],
                        Float64(ztraj[end])
                    )
                )
            end
        end

        push!(
            runs,
            (
                paramset_idx[r],
                sim[r],
                n_outliers > 0,
                n_outliers
            )
        )

        if r % 100 == 0 || r == R
            println("Processed $r / $R runs")
        end
    end

    # ------------------------------------------------------------
    # Parameter-set information
    # ------------------------------------------------------------

    param_info = DataFrames.DataFrame(
        paramset_idx = Int[],
        center = Float64[],
        sigma = Float64[],
        floor = Float64[],
        ceiling = Float64[]
    )

    for pi in sort(unique(paramset_idx))

        r = findfirst(==(pi), paramset_idx)

        push!(
            param_info,
            (
                pi,
                center_value[r],
                sigma_value[r],
                floor_value[r],
                ceiling_value[r]
            )
        )
    end

    println()
    println("Finished.")
    println("Runs:                ", DataFrames.nrow(runs))
    println("Runs with outlier:   ", count(runs.has_persistent_outlier))
    println("Persistent outliers: ", DataFrames.nrow(outliers))

    return (
        runs = runs,
        outliers = outliers,
        param_info = param_info,
        threshold = Float64(threshold),
        analysis_end_step = analysis_end_step,
        first_step = first(steps_axis_full),
        full_last_step = last(steps_axis_full)
    )
end
# persistent_outliers = extract_persistent_outliers(
#     raw"C:\Users\1arie\OneDrive\שולחן העבודה\julia\new_project\developmental_homophily_40000\ALL_ZSCORES_AND_RUNINFO.jld2";
#     threshold = 2.5,
#     max_step = 40000
# )


function plot_developmental_homophily(
    centers::AbstractVector{<:Real};
    steps::Int = 40000,
    floor::Real = 0.5,
    ceiling::Real = 5.0,
    sigmas::AbstractVector{<:Real} = [2000, 3000],
    fontfamily::String = "Calibri")

    steps > 0 || error("steps must be positive.")
    isempty(centers) && error("centers cannot be empty.")
    isempty(sigmas) && error("sigmas cannot be empty.")
    all(isfinite, centers) || error("All centers must be finite.")
    all(s -> isfinite(s) && s > 0, sigmas) ||
        error("All sigmas must be positive.")
    ceiling > floor || error("ceiling must be greater than floor.")

    centers_sorted = sort(unique(centers))
    sigmas_sorted = sort(unique(sigmas))

    t = collect(0:steps)
    range_y = ceiling - floor

    colors = [
        :steelblue, :darkorange, :seagreen, :purple,
        :firebrick, :darkcyan, :goldenrod, :deeppink
    ]

    narrow_styles = [:dash, :dot, :dashdot, :dashdotdot]

    sigma_styles = [
        j == length(sigmas_sorted) ? :solid :
        narrow_styles[mod1(j, length(narrow_styles))]
        for j in eachindex(sigmas_sorted)
    ]

    fmt(x) = replace(
        string(isinteger(x) ? Int(x) : x),
        r"(?<=\d)(?=(\d{3})+(?!\d))" => ","
    )
    p = Plots.plot(
        xlabel = "Simulation Step",
        ylabel = "Homophily (β)",
        fontfamily = fontfamily,
        framestyle = :box,
        grid = false,
        legend = false,
        size = (1100, 550),
        xlims = (0, steps + 0.02 * steps),
        ylims = (
            floor - 0.08 * range_y,
            ceiling + 0.08 * range_y
        ),
        xticks = collect(0:5000:steps),
        xformatter = x -> fmt(x),
        yticks = sort(unique(vcat(
            [Float64(floor), Float64(ceiling)],
            collect(1.0:1.0:Base.floor(ceiling))
        )))
    )

    # Horizontal reference lines
    for value in (floor, ceiling)
        Plots.hline!(
            p, [value];
            color = :gray75,
            linestyle = :dash,
            linewidth = 1.0,
            label = ""
        )
    end

    # Homophily curves
    for (i, center) in enumerate(centers_sorted)
        for (j, sigma) in enumerate(sigmas_sorted)

            beta = floor .+ range_y .*
                exp.(-0.5 .* ((t .- center) ./ sigma).^2)

            Plots.plot!(
                p, t, beta;
                color = colors[mod1(i, length(colors))],
                linestyle = sigma_styles[j],
                linewidth = 2.5,
                label = ""
            )
        end
    end

    # Floor / ceiling labels — shifted right
    label_x = 0.86 * steps

    Plots.annotate!(
        p, label_x, ceiling + 0.025 * range_y,
        Plots.text("β<sub>max</sub> = $(fmt(ceiling))", 9, :gray45)
    )

    Plots.annotate!(
        p, label_x, floor + 0.025 * range_y,
        Plots.text("β<sub>min</sub> = $(fmt(floor))", 9, :gray45)
    )

    # --------------------------------------------------
    # Manual legend — compact, framed, right aligned
    # --------------------------------------------------

    # Legend position and dimensions
    legend_left  = 0.825 * steps
    legend_right = 0.975 * steps

    legend_text_x = 0.84 * steps
    legend_x1     = 0.92 * steps
    legend_x2     = 0.96 * steps

    spacing     = 0.043 * range_y
    section_gap = 0.025 * range_y
    pad_top = 0.035 * range_y
    pad_bottom = 0.008 * range_y

    n_centers = length(centers_sorted)
    n_sigmas  = length(sigmas_sorted)

    # Total height
    total_height = (
        (n_centers + n_sigmas + 2) * spacing +
        section_gap
    )

    legend_top = floor + range_y / 2 + total_height / 2
    legend_bottom = legend_top - total_height

    # Legend frame
    frame_top = legend_top + 0.055 * range_y
    frame_bottom = legend_bottom + 0.008 * range_y

    Plots.plot!(
        p,
        Plots.Shape(
            [legend_left, legend_right, legend_right, legend_left],
            [frame_bottom, frame_bottom, frame_top, frame_top]
        );
        fillcolor = :white,
        fillalpha = 1.0,
        linecolor = :black,
        linewidth = 1.0,
        label = ""
    )

    # Explicit left border
    Plots.plot!(
        p,
        [legend_left, legend_left],
        [frame_bottom, frame_top];
        color = :black,
        linewidth = 1.0,
        label = ""
    )

    current_y = legend_top

    # --------------------------------------------------
    # Peak step section
    # --------------------------------------------------

    Plots.annotate!(
        p,
        legend_text_x,
        current_y,
        Plots.text("Peak step (μ)", 9, :black, :left)
    )

    current_y -= spacing

    for (i, center) in enumerate(centers_sorted)

        Plots.plot!(
            p,
            [legend_x1, legend_x2],
            [current_y, current_y];
            color = colors[mod1(i, length(colors))],
            linestyle = :solid,
            linewidth = 2.0,
            label = ""
        )

        Plots.annotate!(
            p,
            legend_text_x,
            current_y,
            Plots.text(fmt(center), 8, :black, :left)
        )

        current_y -= spacing
    end

    # --------------------------------------------------
    # Separator
    # --------------------------------------------------

    current_y -= section_gap / 2

    Plots.plot!(
        p,
        [legend_left + 0.012 * steps, legend_right - 0.012 * steps],
        [current_y, current_y];
        color = :gray75,
        linewidth = 0.8,
        label = ""
    )

    current_y -= section_gap

    # --------------------------------------------------
    # Width section
    # --------------------------------------------------

    Plots.annotate!(
        p,
        legend_text_x,
        current_y,
        Plots.text("Width (σ)", 9, :black, :left)
    )

    current_y -= spacing

    for j in reverse(eachindex(sigmas_sorted))

        Plots.plot!(
            p,
            [legend_x1, legend_x2],
            [current_y, current_y];
            color = :black,
            linestyle = sigma_styles[j],
            linewidth = 2.0,
            label = ""
        )

        Plots.annotate!(
            p,
            legend_text_x,
            current_y,
            Plots.text(fmt(sigmas_sorted[j]), 8, :black, :left)
        )

        current_y -= spacing
    end

    display(p)
    return p
end
