#     )
# end
# results = plot_persistent_outliers_by_peak_step(
#     persistent_outliers;
#     padding = 1000
# )

function plot_onset_regression_by_sigma(
    persistent_outliers;
    sigma::Real = 3000,
    metric::Symbol = :mean,
    x_padding::Real = 2000,
    y_padding::Real = 2000,
    n_permutations::Int = 10000,
    seed::Int = 1234,
    fontfamily::String = "Calibri")

    metric in (:mean, :median) ||
        error("metric must be :mean or :median.")

    sigma > 0 || error("sigma must be positive.")
    x_padding >= 0 || error("x_padding must be nonnegative.")
    y_padding >= 0 || error("y_padding must be nonnegative.")
    n_permutations > 0 ||
        error("n_permutations must be positive.")

    runs = persistent_outliers.runs
    outliers = persistent_outliers.outliers
    param_info = persistent_outliers.param_info

    rng = Random.MersenneTwister(seed)

    fmt(x) = replace(
        string(round(Int, x)),
        r"(?<=\d)(?=(\d{3})+(?!\d))" => ","
    )

    # ============================================================
    # 1. SELECT DEVELOPMENTAL CONDITIONS
    # ============================================================

    selected = param_info[
        (param_info.floor .!= param_info.ceiling) .&
        isapprox.(param_info.sigma, sigma),
        :
    ]

    DataFrames.nrow(selected) >= 3 ||
        error("At least 3 developmental conditions are required.")

    DataFrames.sort!(selected, :center)

    paramsets = Int.(selected.paramset_idx)
    centers = Float64.(selected.center)

    length(unique(centers)) == length(centers) ||
        error("Peak steps must be unique.")

    # ============================================================
    # 2. BUILD RUN-LEVEL DATA
    # ============================================================

    onset_lookup = Dict{Tuple{Int, Int}, Vector{Float64}}()

    for row in eachrow(outliers)

        key = (Int(row.paramset_idx), Int(row.sim))

        if !haskey(onset_lookup, key)
            onset_lookup[key] = Float64[]
        end

        push!(
            onset_lookup[key],
            Float64(row.crossing_step)
        )
    end

    run_onsets = Vector{Vector{Float64}}()
    group_sizes = Int[]
    outlier_group_sizes = Int[]

    for pi in paramsets

        subruns = runs[runs.paramset_idx .== pi, :]

        n_runs = DataFrames.nrow(subruns)

        n_runs > 0 ||
            error("No runs found for paramset $pi.")

        push!(group_sizes, n_runs)

        n_outlier_runs = 0

        for run in eachrow(subruns)

            key = (pi, Int(run.sim))

            steps = copy(
                get(onset_lookup, key, Float64[])
            )

            push!(run_onsets, steps)

            if !isempty(steps)
                n_outlier_runs += 1
            end
        end

        push!(outlier_group_sizes, n_outlier_runs)
    end

    # ============================================================
    # 3. HELPER FUNCTIONS
    # ============================================================

    function calculate_statistic(values)

        isempty(values) && return NaN

        return metric == :mean ?
            Statistics.mean(values) :
            Statistics.median(values)
    end

    function collect_onsets(run_indices, source)

        values = Float64[]

        for idx in run_indices
            append!(values, source[idx])
        end

        return values
    end

    function calculate_permuted_statistics(
        shuffled_indices,
        sizes,
        source
    )

        result = Vector{Float64}(undef, length(sizes))

        offset = 0

        for j in eachindex(sizes)

            indices = @view shuffled_indices[
                (offset + 1):(offset + sizes[j])
            ]

            offset += sizes[j]

            values = collect_onsets(indices, source)

            result[j] = calculate_statistic(values)
        end

        return result
    end

    # ============================================================
    # 4. OBSERVED CONDITION STATISTICS
    # ============================================================

    df = DataFrames.DataFrame(
        paramset_idx = Int[],
        peak_step = Float64[],
        onset_step = Float64[],
        error_lower = Float64[],
        error_upper = Float64[],
        n_runs = Int[],
        n_outlier_runs = Int[],
        n_outlier_agents = Int[]
    )

    offset = 0

    for (j, pi) in enumerate(paramsets)

        indices = (offset + 1):(offset + group_sizes[j])
        offset += group_sizes[j]

        onset_steps = collect_onsets(indices, run_onsets)

        n_agents = length(onset_steps)

        n_agents > 0 ||
            error(
                "No persistent outliers for peak step " *
                "$(fmt(centers[j]))."
            )

        if metric == :mean

            estimate = Statistics.mean(onset_steps)

            sd = n_agents > 1 ?
                Statistics.std(onset_steps) : 0.0

            error_lower = sd
            error_upper = sd

        else

            estimate = Statistics.median(onset_steps)

            q1 = Statistics.quantile(onset_steps, 0.25)
            q3 = Statistics.quantile(onset_steps, 0.75)

            error_lower = estimate - q1
            error_upper = q3 - estimate
        end

        push!(
            df,
            (
                pi,
                centers[j],
                estimate,
                error_lower,
                error_upper,
                group_sizes[j],
                outlier_group_sizes[j],
                n_agents
            )
        )
    end

    # ============================================================
    # 5. PEARSON CORRELATION AND LINEAR REGRESSION
    # ============================================================

    x = df.peak_step
    y = df.onset_step

    r = Statistics.cor(x, y)

    isfinite(r) ||
        error("Observed Pearson correlation is undefined.")

    x_mean = Statistics.mean(x)
    y_mean = Statistics.mean(y)

    slope = sum(
        (x .- x_mean) .* (y .- y_mean)
    ) / sum(
        (x .- x_mean).^2
    )

    intercept = y_mean - slope * x_mean

    predicted = intercept .+ slope .* x

    residuals = y .- predicted

    ss_res = sum(residuals .^ 2)
    ss_tot = sum((y .- y_mean).^2)

    r_squared = 1.0 - ss_res / ss_tot
    rmse = sqrt(Statistics.mean(residuals .^ 2))

    # ============================================================
    # 6. PREPARE PERMUTATION TESTS
    # ============================================================

    # Test 1: all runs, including runs without outliers
    all_run_source = run_onsets

    # Test 2: only runs containing persistent outliers
    outlier_run_source = filter(
        steps -> !isempty(steps),
        run_onsets
    )

    length(outlier_run_source) == sum(outlier_group_sizes) ||
        error("Mismatch in number of outlier runs.")

    # ============================================================
    # 7. PERMUTATION TEST
    # ============================================================

    function run_permutation_test(
        source,
        sizes,
        test_name
    )

        n_total = length(source)

        n_total == sum(sizes) ||
            error("Group sizes do not match source length.")

        permutation_rs = Float64[]
        sizehint!(permutation_rs, n_permutations)

        n_extreme = 0
        n_invalid = 0

        print_every = max(1, n_permutations ÷ 20)

        println()
        println("="^65)
        println(test_name)
        println("="^65)
        println("Total runs shuffled: $n_total")
        println("Runs per condition: $(join(sizes, ", "))")

        for perm in 1:n_permutations

            shuffled = Random.randperm(rng, n_total)

            permuted_y = calculate_permuted_statistics(
                shuffled,
                sizes,
                source
            )

            if all(isfinite, permuted_y) &&
               Statistics.std(permuted_y) > 0

                r_perm = Statistics.cor(x, permuted_y)

                if isfinite(r_perm)

                    push!(permutation_rs, r_perm)

                    if abs(r_perm) >= abs(r)
                        n_extreme += 1
                    end

                else
                    n_invalid += 1
                end

            else
                n_invalid += 1
            end

            if perm % print_every == 0 ||
               perm == n_permutations

                println(
                    "Progress: $perm / $n_permutations"
                )
            end
        end

        n_valid = length(permutation_rs)

        n_valid > 0 ||
            error("No valid permutations in $test_name.")

        p_value = (n_extreme + 1) / (n_valid + 1)

        return (
            p_value = p_value,
            permutation_rs = permutation_rs,
            n_valid = n_valid,
            n_invalid = n_invalid,
            n_extreme = n_extreme,
            group_sizes = copy(sizes)
        )
    end

    # ============================================================
    # 8. RUN BOTH TESTS
    # ============================================================

    test_all = run_permutation_test(
        all_run_source,
        group_sizes,
        "PERMUTATION TEST 1 — ALL RUNS"
    )

    test_outliers = run_permutation_test(
        outlier_run_source,
        outlier_group_sizes,
        "PERMUTATION TEST 2 — OUTLIER RUNS ONLY"
    )

    # ============================================================
    # 9. PRINT RESULTS
    # ============================================================

    println()
    println("="^75)
    println("ONSET STEP REGRESSION — FINAL RESULTS")
    println("="^75)

    println("Sigma:             $(fmt(sigma))")
    println("Metric:            $metric")
    println("Conditions:        $(length(x))")
    println()

    println("OBSERVED STATISTICS")
    println("-"^75)

    println("Pearson r:         ", round(r; digits=5))
    println("R²:                ", round(r_squared; digits=5))
    println("RMSE:              ", round(rmse; digits=2), " steps")
    println("Intercept:         ", round(intercept; digits=3))
    println("Slope:             ", round(slope; digits=5))

    println()
    println("PERMUTATION TEST RESULTS")
    println("-"^75)

    println(
        rpad("Statistic", 30),
        lpad("All runs", 18),
        lpad("Outlier runs", 18)
    )

    println("-"^75)

    println(
        rpad("Observed Pearson r", 30),
        lpad(round(r; digits=5), 18),
        lpad(round(r; digits=5), 18)
    )

    println(
        rpad("Permutation p (two-sided)", 30),
        lpad(round(test_all.p_value; digits=6), 18),
        lpad(round(test_outliers.p_value; digits=6), 18)
    )

    println(
        rpad("Valid permutations", 30),
        lpad(test_all.n_valid, 18),
        lpad(test_outliers.n_valid, 18)
    )

    println(
        rpad("Invalid permutations", 30),
        lpad(test_all.n_invalid, 18),
        lpad(test_outliers.n_invalid, 18)
    )

    println(
        rpad("Extreme correlations", 30),
        lpad(test_all.n_extreme, 18),
        lpad(test_outliers.n_extreme, 18)
    )

    println("="^75)
    println()

    # ============================================================
    # 10. AXIS LIMITS
    # ============================================================

    x_min = minimum(x) - x_padding
    x_max = maximum(x) + x_padding

    y_values = vcat(
        y .- df.error_lower,
        y .+ df.error_upper,
        predicted
    )

    y_min = minimum(y_values) - y_padding
    y_max = maximum(y_values) + y_padding

    axis_min = min(x_min, y_min)
    axis_max = max(x_max, y_max)

    # ============================================================
    # 11. PLOT — PUBLICATION STYLE
    # ============================================================

    p = Plots.plot(
        xlabel = "Peak Homophily Step",
        ylabel = "Persistent Atypicality Onset Step",

        xlims = (axis_min, axis_max),
        ylims = (axis_min, axis_max),
        aspect_ratio = :equal,

        fontfamily = fontfamily,
        guidefontsize = 13,
        tickfontsize = 10,
        legendfontsize = 10,

        framestyle = :box,
        grid = false,

        legend = :outertopright,
        legend_background_color = :white,
        legend_foreground_color = :black,

        size = (1050, 760),
        margin = 7 * Plots.mm,

        xformatter = fmt,
        yformatter = fmt
    )

    # Identity line
    Plots.plot!(
        p,
        [axis_min, axis_max],
        [axis_min, axis_max];
        color = :gray65,
        linestyle = :dash,
        linewidth = 1.6,
        label = "y = x"
    )

    # Regression line
    x_line = collect(range(x_min, x_max; length = 200))

    Plots.plot!(
        p,
        x_line,
        intercept .+ slope .* x_line;
        color = :firebrick,
        linewidth = 2.8,
        label = "Linear regression"
    )

    # ============================================================
    # Observed statistics with visible SD / IQR
    # ============================================================

    error_color = :steelblue

    # Draw error bars explicitly
    for i in eachindex(x)

        lower = y[i] - df.error_lower[i]
        upper = y[i] + df.error_upper[i]

        # Vertical error bar
        Plots.plot!(
            p,
            [x[i], x[i]],
            [lower, upper];
            color = error_color,
            linewidth = 2.0,
            alpha = 0.75,
            label = ""
        )

        # Horizontal caps
        cap_width = 140.0

        Plots.plot!(
            p,
            [x[i] - cap_width, x[i] + cap_width],
            [lower, lower];
            color = error_color,
            linewidth = 2.0,
            alpha = 0.75,
            label = ""
        )

        Plots.plot!(
            p,
            [x[i] - cap_width, x[i] + cap_width],
            [upper, upper];
            color = error_color,
            linewidth = 2.0,
            alpha = 0.75,
            label = ""
        )
    end

    # Draw points on top of error bars
    Plots.scatter!(
        p,
        x,
        y;
        marker = metric == :mean ? :circle : :diamond,
        markersize = 7,
        markercolor = :steelblue,
        markerstrokecolor = :white,
        markerstrokewidth = 1.2,
        label = metric == :mean ?
            "Mean ± SD" : "Median (Q1–Q3)"
    )

    display(p)

    # ============================================================
    # 12. RETURN
    # ============================================================

    return (
        data = df,
        pearson_r = r,
        r_squared = r_squared,
        rmse = rmse,
        intercept = intercept,
        slope = slope,
        test_all_runs = test_all,
        test_outlier_runs = test_outliers,
        plot = p
    )
end
# reg_median = plot_onset_regression_by_sigma(
#     persistent_outliers;
#     sigma = 3000,
#     metric = :median,
#     x_padding = 1000,
#     n_permutations = 1,
#     seed = 1234
# )

function analyze_outlier_distance_from_peak(
    persistent_outliers;
    sigma::Real = 3000,
    n_permutations::Int = 10000,
    seed::Int = 1234,
    progress_every::Int = 1000)

    sigma > 0 || error("sigma must be positive.")
    n_permutations > 0 || error("n_permutations must be positive.")
    progress_every > 0 || error("progress_every must be positive.")

    runs = persistent_outliers.runs
    outliers = persistent_outliers.outliers
    param_info = persistent_outliers.param_info

    rng = Random.MersenneTwister(seed)

    # ============================================================
    # 1. SELECT DEVELOPMENTAL CONDITIONS
    # ============================================================

    selected = param_info[
        (param_info.floor .!= param_info.ceiling) .&
        isapprox.(param_info.sigma, sigma),
        [:paramset_idx, :center]
    ]

    DataFrames.nrow(selected) > 0 ||
        error("No developmental conditions found for sigma = $sigma.")

    DataFrames.sort!(selected, :center)

    paramsets = Int.(selected.paramset_idx)
    centers = Float64.(selected.center)

    # ============================================================
    # 2. BUILD RUN-LEVEL DATA
    # ============================================================

    onset_lookup = Dict{Tuple{Int, Int}, Vector{Float64}}()

    for row in eachrow(outliers)

        key = (Int(row.paramset_idx), Int(row.sim))

        push!(
            get!(onset_lookup, key, Float64[]),
            Float64(row.crossing_step)
        )
    end

    run_onsets = Vector{Vector{Float64}}()
    run_centers = Float64[]
    run_paramsets = Int[]
    run_sims = Int[]
    group_sizes = Int[]

    for (j, pi) in enumerate(paramsets)

        subruns = runs[runs.paramset_idx .== pi, :]

        n = DataFrames.nrow(subruns)
        n > 0 || error("No runs found for paramset $pi.")

        push!(group_sizes, n)

        for row in eachrow(subruns)

            sim = Int(row.sim)

            steps = copy(
                get(onset_lookup, (pi, sim), Float64[])
            )

            push!(run_onsets, steps)
            push!(run_centers, centers[j])
            push!(run_paramsets, pi)
            push!(run_sims, sim)
        end
    end

    n_runs = length(run_onsets)
    n_outlier_runs = count(x -> !isempty(x), run_onsets)
    n_outliers = sum(length, run_onsets)

    n_outliers > 0 ||
        error("No persistent outliers found.")

    # ============================================================
    # 3. OBSERVED DISTANCES
    # ============================================================

    observed = DataFrames.DataFrame(
        paramset_idx = Int[],
        sim = Int[],
        peak_step = Float64[],
        crossing_step = Float64[],
        signed_distance = Float64[],
        absolute_distance = Float64[],
        side = String[]
    )

    for i in eachindex(run_onsets)

        center = run_centers[i]

        for crossing in run_onsets[i]

            signed = crossing - center
            absolute = abs(signed)

            side = if signed < 0
                "Before peak"
            elseif signed > 0
                "After peak"
            else
                "At peak"
            end

            push!(
                observed,
                (
                    run_paramsets[i],
                    run_sims[i],
                    center,
                    crossing,
                    signed,
                    absolute,
                    side
                )
            )
        end
    end

    observed_distances = observed.absolute_distance

    observed_mean = Statistics.mean(observed_distances)
    observed_median = Statistics.median(observed_distances)

    # ============================================================
    # 4. OBSERVED STATISTICS BY SIDE
    # ============================================================

    side_summary = DataFrames.DataFrame(
        side = String[],
        n_outliers = Int[],
        percent = Float64[],
        mean_distance = Union{Missing, Float64}[],
        median_distance = Union{Missing, Float64}[]
    )

    for side in ("Before peak", "After peak", "At peak")

        values = observed.absolute_distance[
            observed.side .== side
        ]

        n = length(values)

        push!(
            side_summary,
            (
                side,
                n,
                100.0 * n / n_outliers,
                n > 0 ? Statistics.mean(values) : missing,
                n > 0 ? Statistics.median(values) : missing
            )
        )
    end

    # ============================================================
    # 5. PREPARE PERMUTATIONS
    # ============================================================

    # Each condition label appears once per original run.
    # All agents from the same run remain together.

    condition_labels = Float64[]

    for (center, n) in zip(centers, group_sizes)
        append!(condition_labels, fill(center, n))
    end

    permutation_means =
        Vector{Float64}(undef, n_permutations)

    permutation_medians =
        Vector{Float64}(undef, n_permutations)

    permuted_distances = Vector{Float64}(undef, n_outliers)

    # ============================================================
    # 6. RUN PERMUTATION TEST
    # ============================================================

    println()
    println("Running $n_permutations run-level permutations...")

    for perm in 1:n_permutations

        shuffled_labels = Random.shuffle(rng, condition_labels)

        k = 1

        for i in eachindex(run_onsets)

            assigned_center = shuffled_labels[i]

            for crossing in run_onsets[i]

                permuted_distances[k] =
                    abs(crossing - assigned_center)

                k += 1
            end
        end

        permutation_means[perm] =
            Statistics.mean(permuted_distances)

        permutation_medians[perm] =
            Statistics.median(permuted_distances)

        if perm % progress_every == 0 ||
           perm == n_permutations

            println("Permutations: $perm / $n_permutations")
        end
    end

    # ============================================================
    # 7. PERMUTATION P-VALUES
    # ============================================================

    # Primary hypothesis:
    # Observed distances are SMALLER than expected under
    # random assignment of homophily peak steps.

    function permutation_test(observed_stat, null_distribution)

        n = length(null_distribution)

        p_lower = (
            count(x -> x <= observed_stat, null_distribution) + 1
        ) / (n + 1)

        p_upper = (
            count(x -> x >= observed_stat, null_distribution) + 1
        ) / (n + 1)

        null_center = Statistics.mean(null_distribution)

        observed_deviation = abs(observed_stat - null_center)

        p_two_sided = (
            count(
                x -> abs(x - null_center) >= observed_deviation,
                null_distribution
            ) + 1
        ) / (n + 1)

        return (
            observed = observed_stat,
            null_mean = null_center,
            null_median = Statistics.median(null_distribution),
            null_sd = Statistics.std(null_distribution),
            p_lower = p_lower,
            p_upper = p_upper,
            p_two_sided = p_two_sided
        )
    end

    mean_test = permutation_test(
        observed_mean,
        permutation_means
    )

    median_test = permutation_test(
        observed_median,
        permutation_medians
    )

    # ============================================================
    # 8. PRINT RESULTS
    # ============================================================

    println()
    println("="^75)
    println("ABSOLUTE DISTANCE BETWEEN OUTLIER ONSET AND HOMOPHILY PEAK")
    println("="^75)

    println("Sigma:                  $sigma")
    println("Developmental conditions: $(length(paramsets))")
    println("Total runs:             $n_runs")
    println("Runs with outliers:     $n_outlier_runs")
    println("Outlier agents:         $n_outliers")

    println()
    println("OBSERVED ABSOLUTE DISTANCES")
    println("-"^75)

    println(
        "Mean distance:          ",
        round(observed_mean; digits=2)
    )

    println(
        "Median distance:        ",
        round(observed_median; digits=2)
    )

    println()
    println("OBSERVED DISTANCES BY SIDE")
    println("-"^75)

    show(
        stdout,
        MIME("text/plain"),
        side_summary;
        allrows = true,
        allcols = true
    )

    println()
    println()
    println("PERMUTATION TEST — ABSOLUTE DISTANCES")
    println("-"^75)

    println(
        rpad("Statistic", 24),
        lpad("Mean", 18),
        lpad("Median", 18)
    )

    println("-"^60)

    println(
        rpad("Observed", 24),
        lpad(round(observed_mean; digits=2), 18),
        lpad(round(observed_median; digits=2), 18)
    )

    println(
        rpad("Permutation null mean", 24),
        lpad(round(mean_test.null_mean; digits=2), 18),
        lpad(round(median_test.null_mean; digits=2), 18)
    )

    println(
        rpad("Permutation null SD", 24),
        lpad(round(mean_test.null_sd; digits=2), 18),
        lpad(round(median_test.null_sd; digits=2), 18)
    )

    println(
        rpad("p (smaller distance)", 24),
        lpad(round(mean_test.p_lower; digits=6), 18),
        lpad(round(median_test.p_lower; digits=6), 18)
    )

    println(
        rpad("p (larger distance)", 24),
        lpad(round(mean_test.p_upper; digits=6), 18),
        lpad(round(median_test.p_upper; digits=6), 18)
    )

    println(
        rpad("p (two-sided)", 24),
        lpad(round(mean_test.p_two_sided; digits=6), 18),
        lpad(round(median_test.p_two_sided; digits=6), 18)
    )

    println("="^75)
    println()

    # ============================================================
    # 9. RETURN
    # ============================================================

    return (
        observed = observed,

        summary = (
            mean = observed_mean,
            median = observed_median,
            n_outliers = n_outliers,
            n_outlier_runs = n_outlier_runs,
            n_runs = n_runs
        ),

        side_summary = side_summary,

        tests = (
            mean = mean_test,
            median = median_test
        ),

        permutations = (
            means = permutation_means,
            medians = permutation_medians
        ),

        condition_info = selected
    )
end
