# function permutation_onsets_near_homophily_peak(
#     persistent_outliers,
#     K_values::AbstractVector{<:Real};
#     n_permutations::Int = 5000,
#     sigma_filter::Union{Nothing,Real} = nothing,
#     seed::Int = 1234,
