function analyze_onset_windows_own_vs_other_peaks(
    persistent_outliers,
    K_values::AbstractVector{<:Real};
    sigma_target::Real = 3000,
    other_method::Symbol = :mean,
    n_permutations::Int = 10000,
    seed::Int = 1234,
    fontfamily::String = "Calibri",
    line_width::Real = 2.5,
    marker_size::Real = 4.0,
    progress_every::Int = 500,
    plot1_ymax::Real = 102,
    plot1_legend_x::Real = 0.97,
    plot1_legend_y::Real = 0.97,
    plot2_legend_x::Real = 1.15,
    plot2_legend_y::Real = 0.95)

    # ============================================================
    # 0. VALIDATION
    # ============================================================

    other_method in (:pooled, :mean) ||
        error("other_method must be :pooled or :mean.")

    isempty(K_values) &&
        error("K_values cannot be empty.")

    all(k -> isfinite(k) && k >= 0, K_values) ||
        error("All K values must be finite and nonnegative.")

    n_permutations > 0 ||
        error("n_permutations must be positive.")

    progress_every > 0 ||
        error("progress_every must be positive.")

    plot1_ymax > 0 ||
        error("plot1_ymax must be positive.")

    0 <= plot1_legend_x <= 1 ||
        error("plot1_legend_x must be between 0 and 1.")

    0 <= plot1_legend_y <= 1 ||
        error("plot1_legend_y must be between 0 and 1.")

    K_values = sort(unique(Float64.(K_values)))

    runs = persistent_outliers.runs
    outliers = persistent_outliers.outliers
    info = persistent_outliers.param_info

    rng = Random.MersenneTwister(seed)

    # ============================================================
    # 1. SELECT DEVELOPMENTAL CONDITIONS
    # ============================================================

    selected_info = info[
        isapprox.(info.sigma, sigma_target) .&
        (info.ceiling .> info.floor),
        [:paramset_idx, :center, :sigma]
    ]

    DataFrames.sort!(selected_info, :center)

    C = DataFrames.nrow(selected_info)

    C >= 2 ||
        error("At least two developmental conditions are required.")

    peaks = Float64.(selected_info.center)
    paramsets = Int.(selected_info.paramset_idx)

    length(unique(peaks)) == C ||
        error("Peak steps must be unique.")

    # ============================================================
    # 2. ALL RUNS, INCLUDING RUNS WITHOUT OUTLIERS
    # ============================================================

    run_df = DataFrames.innerjoin(
        runs[:, [:paramset_idx, :sim]],
        selected_info;
        on = :paramset_idx
    )

    n_runs = DataFrames.nrow(run_df)

    n_runs > 0 ||
        error("No eligible runs found.")

    condition_lookup = Dict(
        pi => j
        for (j, pi) in enumerate(paramsets)
    )

    run_condition = [
        condition_lookup[Int(pi)]
        for pi in run_df.paramset_idx
    ]

    run_lookup = Dict(
        (Int(row.paramset_idx), Int(row.sim)) => i
        for (i, row) in enumerate(eachrow(run_df))
    )

    # ============================================================
    # 3. OUTLIER AGENTS
    # ============================================================

    df = DataFrames.innerjoin(
        outliers,
        selected_info;
        on = :paramset_idx
    )

    n_agents = DataFrames.nrow(df)

    n_agents > 0 ||
        error("No persistent outlier agents found.")

    crossing = Float64.(df.crossing_step)

    agent_run_idx = [
        run_lookup[(Int(row.paramset_idx), Int(row.sim))]
        for row in eachrow(df)
    ]

    observed_condition = run_condition[agent_run_idx]

    # ============================================================
    # 4. PRECOMPUTE WINDOW MEMBERSHIP
    # ============================================================

    nK = length(K_values)

    inside = Array{Bool}(undef, n_agents, C, nK)

    for c in 1:C

        distances = abs.(crossing .- peaks[c])

        for k in 1:nK
            inside[:, c, k] .=
                distances .<= K_values[k]
        end
    end

    # ============================================================
    # 5. CONDITION-LEVEL STATISTICS
    # ============================================================

    function calculate_window_statistics(agent_condition)

        n_by_condition = zeros(Int, C)

        for c in agent_condition
            n_by_condition[c] += 1
        end

        counts = zeros(Int, C, C, nK)

        for i in 1:n_agents

            g = agent_condition[i]

            for c in 1:C
                for k in 1:nK

                    if inside[i, c, k]
                        counts[c, g, k] += 1
                    end
                end
            end
        end

        own_percent = fill(NaN, C, nK)
        other_percent = fill(NaN, C, nK)
        differences = fill(NaN, C, nK)

        for c in 1:C

            n_own = n_by_condition[c]
            n_other = n_agents - n_own

            for k in 1:nK

                if n_own > 0
                    own_percent[c, k] =
                        100 * counts[c, c, k] / n_own
                end

                if other_method == :pooled

                    if n_other > 0

                        other_count =
                            sum(counts[c, :, k]) -
                            counts[c, c, k]

                        other_percent[c, k] =
                            100 * other_count / n_other
                    end

                else

                    percentages = Float64[]

                    for g in 1:C

                        if g != c && n_by_condition[g] > 0

                            push!(
                                percentages,
                                100 * counts[c, g, k] /
                                n_by_condition[g]
                            )
                        end
                    end

                    if !isempty(percentages)
                        other_percent[c, k] =
                            Statistics.mean(percentages)
                    end
                end

                differences[c, k] =
                    own_percent[c, k] -
                    other_percent[c, k]
            end
        end

        statistic = Vector{Float64}(undef, nK)

        for k in 1:nK

            values = differences[:, k]

            statistic[k] = all(isfinite, values) ?
                Statistics.mean(values) : NaN
        end

        return (
            own = own_percent,
            other = other_percent,
            differences = differences,
            statistic = statistic,
            n_by_condition = n_by_condition,
            counts = counts
        )
    end

    # ============================================================
    # 6. OBSERVED STATISTICS
    # ============================================================

    observed = calculate_window_statistics(
        observed_condition
    )

    all(isfinite, observed.statistic) ||
        error("Observed statistic is undefined for at least one K.")

    results = DataFrames.DataFrame(
        peak_step = Float64[],
        K = Float64[],
        own_percent = Float64[],
        other_percent = Float64[],
        difference = Float64[],
        n_own = Int[],
        n_other = Int[],
        n_own_in_window = Int[],
        n_other_in_window = Int[]
    )

    for c in 1:C

        n_own = observed.n_by_condition[c]
        n_other = n_agents - n_own

        for k in 1:nK

            own_count = observed.counts[c, c, k]

            other_count =
                sum(observed.counts[c, :, k]) -
                own_count

            push!(
                results,
                (
                    peaks[c],
                    K_values[k],
                    observed.own[c, k],
                    observed.other[c, k],
                    observed.differences[c, k],
                    n_own,
                    n_other,
                    own_count,
                    other_count
                )
            )
        end
    end

    # ============================================================
    # 6A. DESCRIPTIVE OWN / OTHER RATIOS
    # ============================================================

    results.ratio = [
        other > 0 ? own / other : NaN
        for (own, other) in zip(
            results.own_percent,
            results.other_percent
        )
    ]

    ratio_summary = DataFrames.DataFrame(
        K = Float64[],
        mean_ratio = Float64[],
        median_ratio = Float64[],
        n_valid_conditions = Int[]
    )

    for K in K_values

        subset = results[results.K .== K, :]

        valid_ratios = filter(
            isfinite,
            subset.ratio
        )

        push!(
            ratio_summary,
            (
                K,
                isempty(valid_ratios) ?
                    NaN : Statistics.mean(valid_ratios),
                isempty(valid_ratios) ?
                    NaN : Statistics.median(valid_ratios),
                length(valid_ratios)
            )
        )
    end

    # ============================================================
    # 7. RUN-LEVEL PERMUTATIONS
    # ============================================================

    permutation_statistics = Matrix{Float64}(
        undef,
        n_permutations,
        nK
    )

    println()
    println("="^75)
    println("RUN-LEVEL PERMUTATION TEST")
    println("="^75)
    println("Sigma: $sigma_target")
    println("Conditions: $C")
    println("Total runs: $n_runs")
    println("Persistent outlier agents: $n_agents")
    println("Permutations: $n_permutations")
    println("Other method: $other_method")
    println()

    for b in 1:n_permutations

        permuted_run_condition =
            Random.shuffle(rng, run_condition)

        permuted_agent_condition =
            permuted_run_condition[agent_run_idx]

        permuted = calculate_window_statistics(
            permuted_agent_condition
        )

        permutation_statistics[b, :] .=
            permuted.statistic

        if b % progress_every == 0 ||
           b == n_permutations

            println(
                "Permutations: $b / $n_permutations"
            )
        end
    end

    # ============================================================
    # 8. PERMUTATION P-VALUES
    # ============================================================

    observed_T = observed.statistic

    p_values = Vector{Float64}(undef, nK)
    permutation_means = Vector{Float64}(undef, nK)
    permutation_sds = Vector{Float64}(undef, nK)
    n_valid = Vector{Int}(undef, nK)

    for k in 1:nK

        null_values = filter(
            isfinite,
            permutation_statistics[:, k]
        )

        n_valid[k] = length(null_values)

        if isempty(null_values)

            p_values[k] = NaN
            permutation_means[k] = NaN
            permutation_sds[k] = NaN

            continue
        end

        permutation_means[k] =
            Statistics.mean(null_values)

        permutation_sds[k] =
            length(null_values) > 1 ?
                Statistics.std(null_values) : 0.0

        p_values[k] = (
            1 + count(
                x -> x >= observed_T[k],
                null_values
            )
        ) / (length(null_values) + 1)
    end

    # ============================================================
    # 9. HOLM-BONFERRONI CORRECTION
    # ============================================================

    p_holm = fill(NaN, nK)

    valid_indices = findall(isfinite, p_values)

    m = length(valid_indices)

    if m > 0

        ordered = sort(
            valid_indices;
            by = i -> p_values[i]
        )

        running_max = 0.0

        for (rank, idx) in enumerate(ordered)

            adjusted = min(
                1.0,
                (m - rank + 1) * p_values[idx]
            )

            running_max = max(
                running_max,
                adjusted
            )

            p_holm[idx] = running_max
        end
    end

    permutation_results = DataFrames.DataFrame(
        K = K_values,
        observed_statistic = observed_T,
        permutation_mean = permutation_means,
        permutation_sd = permutation_sds,
        p_value = p_values,
        p_holm = p_holm,
        n_valid_permutations = n_valid
    )

    # ============================================================
    # 10. PLOT SETTINGS
    # ============================================================

    colors = [
        :steelblue,
        :darkorange,
        :seagreen,
        :purple,
        :firebrick,
        :darkcyan,
        :goldenrod,
        :deeppink
    ]

    fmt(x) = replace(
        string(round(Int, x)),
        r"(?<=\d)(?=(\d{3})+(?!\d))" => ","
    )

    # ============================================================
    # 11. PLOT 1 — OWN VS OTHER
    # ============================================================

    p1 = Plots.plot(
        xlabel = "Peak Homophily Step",
        ylabel = "Persistent Outliers Within Window (%)",
        fontfamily = fontfamily,
        framestyle = :box,
        grid = false,

        legend = (plot1_legend_x, plot1_legend_y),
        legendtitle = "Window size",
        legend_background_color = :white,
        legend_foreground_color = :black,
        legendfontsize = 9,

        ylims = (0, plot1_ymax),
        xlims = (
            minimum(peaks) - 1000,
            maximum(peaks) + 1000
        ),

        size = (1050, 600),
        xformatter = fmt
    )

    # Actual curves
    for (j, K) in enumerate(K_values)

        subset = results[results.K .== K, :]
        DataFrames.sort!(subset, :peak_step)

        color = colors[mod1(j, length(colors))]

        Plots.plot!(
            p1,
            subset.peak_step,
            subset.own_percent;
            color = color,
            linestyle = :solid,
            marker = :circle,
            markersize = marker_size,
            linewidth = line_width,
            label = false
        )

        Plots.plot!(
            p1,
            subset.peak_step,
            subset.other_percent;
            color = color,
            linestyle = :dash,
            marker = :none,
            linewidth = line_width,
            label = false
        )
    end

    # Legend entries: window sizes
    legend_xdata = [
        maximum(peaks) + 10000,
        maximum(peaks) + 11000
    ]

    for (j, K) in enumerate(K_values)

        color = colors[mod1(j, length(colors))]

        Plots.plot!(
            p1,
            legend_xdata,
            [-10.0, -10.0];
            color = color,
            linestyle = :solid,
            linewidth = line_width,
            label = "±$(fmt(K)) steps"
        )
    end

    # Separator / second section
    Plots.plot!(
        p1,
        legend_xdata,
        [-10.0, -10.0];
        color = :transparent,
        linewidth = 0,
        label = "Condition"
    )

    Plots.plot!(
        p1,
        legend_xdata,
        [-10.0, -10.0];
        color = :black,
        linestyle = :solid,
        linewidth = line_width,
        label = "Own-peak condition"
    )

    Plots.plot!(
        p1,
        legend_xdata,
        [-10.0, -10.0];
        color = :black,
        linestyle = :dash,
        linewidth = line_width,
        label = "Other conditions"
    )

    # ============================================================
    # 12. PLOT 2 — DIFFERENCES
    # ============================================================

    p2 = Plots.plot(
        xlabel = "Peak Homophily Step",
        ylabel = "Own-Peak Advantage (Percentage Points)",
        fontfamily = fontfamily,
        framestyle = :box,
        grid = false,
        legend = (plot2_legend_x, plot2_legend_y),
        legend_background_color = :white,
        legend_foreground_color = :black,
        size = (1050, 600),
        xformatter = fmt,
        xlims = (
            minimum(peaks) - 1000,
            maximum(peaks) + 1000
        )
    )

    Plots.hline!(
        p2,
        [0.0];
        color = :black,
        linestyle = :dash,
        linewidth = 1.5,
        label = ""
    )

    for (j, K) in enumerate(K_values)

        subset = results[results.K .== K, :]
        DataFrames.sort!(subset, :peak_step)

        color = colors[mod1(j, length(colors))]

        Plots.plot!(
            p2,
            subset.peak_step,
            subset.difference;
            color = color,
            linewidth = line_width,
            marker = :circle,
            markersize = marker_size,
            label = "±$(fmt(K)) steps"
        )
    end

    # ============================================================
    # STANDALONE LEGEND FIGURE
    # ============================================================

    legend_fontsize = 12
    legend_title_fontsize = 15
    legend_row_spacing = 0.75

    n_rows = length(K_values) + 4
    legend_height = (n_rows + 1) * legend_row_spacing

    p1_legend = Plots.plot(
        xlims = (0, 10),
        ylims = (0, legend_height),
        size = (430, Int(65 + n_rows * 37)),
        legend = false,
        framestyle = :none,
        grid = false,
        ticks = false,
        fontfamily = fontfamily,
        left_margin = 5Plots.mm,
        right_margin = 5Plots.mm,
        top_margin = 5Plots.mm,
        bottom_margin = 5Plots.mm
    )

    line_x1 = 0.5
    line_x2 = 2.2
    text_x = 2.7

    y = legend_height - 0.6

    # Window size title
    Plots.annotate!(
        p1_legend,
        0.5,
        y,
        Plots.text(
            "Window size",
            legend_title_fontsize,
            :black,
            :left
        )
    )

    y -= legend_row_spacing

    # Window size entries
    for (j, K) in enumerate(K_values)

        color = colors[mod1(j, length(colors))]

        Plots.plot!(
            p1_legend,
            [line_x1, line_x2],
            [y, y];
            color = color,
            linewidth = line_width,
            label = false
        )

        Plots.annotate!(
            p1_legend,
            text_x,
            y,
            Plots.text(
                "±$(fmt(K)) steps",
                legend_fontsize,
                :black,
                :left
            )
        )

        y -= legend_row_spacing
    end

    y -= 0.25

    # Condition title
    Plots.annotate!(
        p1_legend,
        0.5,
        y,
        Plots.text(
            "Condition",
            legend_title_fontsize,
            :black,
            :left
        )
    )

    y -= legend_row_spacing

    # Condition entries
    for (style, label) in [
        (:solid, "Own-peak condition"),
        (:dash, "Other conditions")
    ]

        Plots.plot!(
            p1_legend,
            [line_x1, line_x2],
            [y, y];
            color = :black,
            linestyle = style,
            linewidth = line_width,
            label = false
        )

        Plots.annotate!(
            p1_legend,
            text_x,
            y,
            Plots.text(
                label,
                legend_fontsize,
                :black,
                :left
            )
        )

        y -= legend_row_spacing
    end

    display(p1)
    display(p2)
    display(p1_legend)

    # ============================================================
    # 13. PRINT RESULTS
    # ============================================================

    println()
    println("="^85)
    println("PERMUTATION RESULTS — MEAN OWN MINUS OTHER")
    println("="^85)

    show(
        stdout,
        MIME("text/plain"),
        permutation_results;
        allrows = true,
        allcols = true
    )

    println()
    println()

    println("="^75)
    println("DESCRIPTIVE OWN / OTHER RATIOS")
    println("="^75)

    show(
        stdout,
        MIME("text/plain"),
        ratio_summary;
        allrows = true,
        allcols = true
    )

    println()
    println()

    # ============================================================
    # 14. RETURN
    # ============================================================

    return (
        data = results,
        outliers = df,
        runs = run_df,
        other_method = other_method,
        permutation_results = permutation_results,
        permutation_statistics = permutation_statistics,
        ratio_summary = ratio_summary,
        plot_own_vs_other = p1,
        plot_differences = p2,
        plot_legend = p1_legend,
    )
end
