function summarize_onset_window_ratios(window_res)

    df = window_res.data

    K_values = sort(unique(df.K))

    summary = DataFrames.DataFrame(
        K = Float64[],
        mean_own_percent = Float64[],
        mean_other_percent = Float64[],
        ratio_of_means = Float64[],
        mean_ratio = Float64[],
        median_ratio = Float64[],
        n_conditions = Int[],
        n_valid_ratios = Int[]
    )

    for K in K_values

        subset = df[df.K .== K, :]

        own = Float64.(subset.own_percent)
        other = Float64.(subset.other_percent)

        # Equal weight for every condition
        mean_own = Statistics.mean(own)
        mean_other = Statistics.mean(other)

        # New statistic: ratio of means
        ratio_of_means = mean_other > 0 ?
            mean_own / mean_other : NaN

        # Previous statistic: mean of condition-level ratios
        ratios = [
            own[i] / other[i]
            for i in eachindex(own)
            if isfinite(own[i]) &&
               isfinite(other[i]) &&
               other[i] > 0
        ]

        mean_ratio = isempty(ratios) ?
            NaN : Statistics.mean(ratios)

        median_ratio = isempty(ratios) ?
            NaN : Statistics.median(ratios)

        push!(
            summary,
            (
                K,
                mean_own,
                mean_other,
                ratio_of_means,
                mean_ratio,
                median_ratio,
                DataFrames.nrow(subset),
                length(ratios)
            )
        )
    end

    println()
    println("="^85)
    println("DESCRIPTIVE RATIOS — RATIO OF MEANS VS. MEAN OF RATIOS")
    println("="^85)

    show(
        stdout,
        MIME("text/plain"),
        summary;
        allrows = true,
        allcols = true
    )

    println()
    println()

    return summary
end
# ratio_summary = summarize_onset_window_ratios(window_res)
function detailed_onset_window_table(window_res)

    df = DataFrames.select(
        window_res.data,
        :K,
        :peak_step,
        :own_percent,
        :other_percent,
        :n_own,
        :n_other,
        :n_own_in_window,
        :n_other_in_window
    )

    df.difference = df.own_percent .- df.other_percent

    df.ratio = [
        other > 0 ? own / other : NaN
        for (own, other) in zip(
            df.own_percent,
            df.other_percent
        )
    ]

    DataFrames.sort!(df, [:K, :peak_step])

    println()
    println("DETAILED ONSET WINDOW PERCENTAGES")
    println("="^85)

    show(
        stdout,
        MIME("text/plain"),
        df;
        allrows = true,
        allcols = true
    )

    println()
    println()

    return df
end
