# ============================================================
# SEMANTIC NETWORK BANK GENERATION
# ============================================================
function parameter_string(x::Real)
    s = string(Float64(x))

    if endswith(s, ".0")
        s = s[1:end-2]
    end

    return replace(s, "." => "_")
end
function make_condition_name(
    homophily::Real,
    agent1_learning::Real)

    return string(
        "homophily_",
        parameter_string(homophily),
        "_learning1_",
        parameter_string(agent1_learning)
    )
end
function make_social_learning_prob(
    N::Int,
    agent1_learning::Real;
    other_agents_learning::Real = 0.9)

    @assert 0.0 <= agent1_learning <= 1.0
    @assert 0.0 <= other_agents_learning <= 1.0

    probs =
        fill(
            Float32(other_agents_learning),
            N
        )

    probs[1] =
        Float32(agent1_learning)

    return probs
end
function mean_network_distance_zscores(
    agents::Array{Float32,3})

    N = size(agents, 3)

    @assert N >= 2 "At least two agents are required."

    D = differences(agents)

    mean_distances =
        zeros(Float64, N)

    for i in 1:N

        total_distance = 0.0

        for j in 1:N
            if i != j
                total_distance += Float64(D[i, j])
            end
        end

        mean_distances[i] =
            total_distance / (N - 1)
    end

    μ =
        Statistics.mean(mean_distances)

    σ =
        Statistics.std(mean_distances)

    if σ == 0 || !isfinite(σ)
        z =
            zeros(Float64, N)
    else
        z =
            (mean_distances .- μ) ./ σ
    end

    return (
        mean_distances = mean_distances,
        z = z
    )
end
function run_crossing_detection_pass(;
    seed::Int,

    N::Int,
    W::Int,
    H::Int,
    n::Int,
    m::Int,
    change::Float64,

    steps::Int,

    reset_every::Int,
    record_every::Int,

    abandonment_threshold::Int,
    outliers_count::Int,
    outlier_change,

    isolated_agent,
    isolated_agent_interaction_prob,

    talk_duration::Int,
    refractory_duration::Int,
    self_talk_threshold::Int,
    L::Int,
    eta::Float32,

    beta_for_consent::Real,
    gamma::Real,
    beta::Real,
    delta::Real,
    p0::Real,
    pmin::Real,

    social_impact::Real,
    join_rule::Symbol,

    social_learning_prob::Vector{Float32})

    # --------------------------------------------------------
    # The seed makes it possible to reproduce exactly the same
    # simulation later during the saving pass.
    # --------------------------------------------------------

    Random.seed!(seed)


    # --------------------------------------------------------
    # Initialize the model
    # --------------------------------------------------------

    w =
        init_world(
            N,
            W,
            H,
            n,
            m,
            change;

            abandonment_threshold =
                abandonment_threshold,

            outliers_count =
                outliers_count,

            outlier_change =
                outlier_change,

            isolated_agent =
                isolated_agent,

            isolated_agent_interaction_prob =
                isolated_agent_interaction_prob
        )


    # --------------------------------------------------------
    # We include the INITIAL state as step 0.
    # --------------------------------------------------------

    recorded_steps =
        Int[0]

    initial_result =
        mean_network_distance_zscores(
            w.agents
        )

    z_history =
        Vector{Vector{Float64}}()

    push!(
        z_history,
        copy(initial_result.z)
    )


    # --------------------------------------------------------
    # Run simulation
    # --------------------------------------------------------

    for t in 1:steps

        # Same reset rule as in the original simulation
        if t % reset_every == 0
            reset_positions_and_interactions!(w)
        end


        step!(
            w;

            talk_duration =
                talk_duration,

            refractory_duration =
                refractory_duration,

            self_talk_threshold =
                self_talk_threshold,

            L = L,
            eta = eta,

            beta_for_consent =
                beta_for_consent,

            gamma = gamma,
            beta = beta,
            delta = delta,

            p0 = p0,
            pmin = pmin,

            # We handle distance recording ourselves.
            # Turning this off only prevents the model from filling
            # its own history arrays.
            record_distances = false,

            record_every =
                record_every,

            social_impact =
                Float64(social_impact),

            join_rule =
                join_rule,

            social_learning_prob =
                social_learning_prob
        )


        # ----------------------------------------------------
        # Measure outlier status only at recorded timepoints
        # ----------------------------------------------------

        if t % record_every == 0

            result =
                mean_network_distance_zscores(
                    w.agents
                )

            push!(
                recorded_steps,
                t
            )

            push!(
                z_history,
                copy(result.z)
            )
        end
    end


    # Convert:
    #
    # Vector of length T,
    # each containing N z-scores
    #
    # into:
    #
    # N × T matrix
    # --------------------------------------------------------

    Z =
        hcat(z_history...)


    return (
        steps = recorded_steps,
        z = Z
    )
end
function find_valid_stable_crossing(
    Z::Matrix{Float64},
    recorded_steps::Vector{Int};

    threshold::Real = 2.5,

    agent1_learning::Real,
    other_agents_learning::Real)

    N, T =
        size(Z)

    @assert T ==
        length(recorded_steps)


    # --------------------------------------------------------
    # Does agent 1 have a social-learning impairment?
    # --------------------------------------------------------

    has_impairment =
        agent1_learning <
        other_agents_learning


    # --------------------------------------------------------
    # Which agents are allowed to make the run valid?
    # --------------------------------------------------------

    candidate_agents =
        if has_impairment

            Int[1]

        else

            collect(1:N)

        end


    valid_crossings =
        NamedTuple[]


    for agent in candidate_agents

        # Must be above threshold at the final recorded point
        if Z[agent, end] < threshold
            continue
        end


        # ----------------------------------------------------
        # Walk backward to find the start of the continuous
        # above-threshold period that reaches the end.
        # ----------------------------------------------------

        start_idx =
            T

        while start_idx > 1 &&
              Z[agent, start_idx - 1] >= threshold

            start_idx -= 1
        end


        # ----------------------------------------------------
        # If start_idx == 1, the agent was already above the
        # threshold at step 0.
        #
        # There was therefore no observed crossing during the
        # simulation, so we reject it.
        # ----------------------------------------------------

        if start_idx == 1
            continue
        end


        push!(
            valid_crossings,
            (
                agent = agent,
                index = start_idx,
                step = recorded_steps[start_idx],
                z = Z[agent, start_idx]
            )
        )
    end


    # --------------------------------------------------------
    # No valid stable crossing
    # --------------------------------------------------------

    if isempty(valid_crossings)
        return nothing
    end


    # --------------------------------------------------------
    # If several agents qualify in the no-impairment condition,
    # use the one whose stable crossing began earliest.
    #
    # If two began at exactly the same recorded step, choose the
    # one with the higher z-score at that crossing.
    # --------------------------------------------------------

    sort!(
        valid_crossings;
        by =
            x -> (
                x.index,
                -x.z,
                x.agent
            )
    )


    return first(valid_crossings)
end
function select_period_snapshot_indices(
    indices::Vector{Int};
    snapshot_stride::Int = 10)

    @assert snapshot_stride >= 1

    isempty(indices) &&
        return Int[]


    L =
        length(indices)


    selected =
        Set{Int}()


    # --------------------------------------------------------
    # Basic thinning
    # --------------------------------------------------------

    for local_idx in 1:snapshot_stride:L
        push!(
            selected,
            indices[local_idx]
        )
    end


    # --------------------------------------------------------
    # Required relative anchors:
    # 0%, 25%, 50%, 75%, 100%
    # --------------------------------------------------------

    for fraction in (
        0.0,
        0.25,
        0.50,
        0.75,
        1.0
    )

        local_idx =
            round(
                Int,
                1 +
                fraction * (L - 1)
            )

        local_idx =
            clamp(
                local_idx,
                1,
                L
            )

        push!(
            selected,
            indices[local_idx]
        )
    end


    return sort!(
        collect(selected)
    )
end
function select_pre_and_post_crossing_indices(
    T::Int,
    crossing_idx::Int;
    snapshot_stride::Int = 10)

    @assert 2 <= crossing_idx <= T


    # --------------------------------------------------------
    # PRE-CROSSING:
    # everything strictly before the stable crossing
    # --------------------------------------------------------

    pre_indices =
        collect(
            1:(crossing_idx - 1)
        )


    # --------------------------------------------------------
    # CROSSING + POST-CROSSING
    # --------------------------------------------------------

    post_indices =
        collect(
            crossing_idx:T
        )


    selected_pre =
        select_period_snapshot_indices(
            pre_indices;
            snapshot_stride =
                snapshot_stride
        )


    selected_post =
        select_period_snapshot_indices(
            post_indices;
            snapshot_stride =
                snapshot_stride
        )


    # Combine without duplicates
    selected_all =
        sort!(
            unique(
                vcat(
                    selected_pre,
                    selected_post
                )
            )
        )


    return (
        all = selected_all,
        pre = selected_pre,
        post = selected_post
    )
end
function run_snapshot_saving_pass(
    selected_steps::Vector{Int};

    seed::Int,

    N::Int,
    W::Int,
    H::Int,
    n::Int,
    m::Int,
    change::Float64,

    steps::Int,

    reset_every::Int,
    record_every::Int,

    abandonment_threshold::Int,
    outliers_count::Int,
    outlier_change,

    isolated_agent,
    isolated_agent_interaction_prob,

    talk_duration::Int,
    refractory_duration::Int,
    self_talk_threshold::Int,
    L::Int,
    eta::Float32,

    beta_for_consent::Real,
    gamma::Real,
    beta::Real,
    delta::Real,
    p0::Real,
    pmin::Real,

    social_impact::Real,
    join_rule::Symbol,

    social_learning_prob::Vector{Float32})

    Random.seed!(seed)


    # --------------------------------------------------------
    # Initialize same world
    # --------------------------------------------------------

    w =
        init_world(
            N,
            W,
            H,
            n,
            m,
            change;

            abandonment_threshold =
                abandonment_threshold,

            outliers_count =
                outliers_count,

            outlier_change =
                outlier_change,

            isolated_agent =
                isolated_agent,

            isolated_agent_interaction_prob =
                isolated_agent_interaction_prob
        )


    # --------------------------------------------------------
    # Fast lookup:
    # "Should this step be saved?"
    # --------------------------------------------------------

    selected_set =
        Set(selected_steps)


    saved_steps =
        Int[]

    network_snapshots =
        Array{Float32,3}[]

    conversation_snapshots =
        Matrix{Int}[]


    # --------------------------------------------------------
    # Helper for saving current state
    # --------------------------------------------------------

    function save_current_state!(
        current_step::Int)

        push!(
            saved_steps,
            current_step
        )

        push!(
            network_snapshots,
            copy(w.agents)
        )

        push!(
            conversation_snapshots,
            copy(w.talk_episode_count)
        )

        return nothing
    end


    # --------------------------------------------------------
    # Save initial state if requested
    # --------------------------------------------------------

    if 0 in selected_set
        save_current_state!(0)
    end


    # --------------------------------------------------------
    # Run exact same simulation
    # --------------------------------------------------------

    for t in 1:steps

        if t % reset_every == 0
            reset_positions_and_interactions!(w)
        end


        step!(
            w;

            talk_duration =
                talk_duration,

            refractory_duration =
                refractory_duration,

            self_talk_threshold =
                self_talk_threshold,

            L = L,
            eta = eta,

            beta_for_consent =
                beta_for_consent,

            gamma = gamma,
            beta = beta,
            delta = delta,

            p0 = p0,
            pmin = pmin,

            record_distances = false,
            record_every = record_every,

            social_impact =
                Float64(social_impact),

            join_rule =
                join_rule,

            social_learning_prob =
                social_learning_prob
        )


        if t in selected_set
            save_current_state!(t)
        end
    end


    # --------------------------------------------------------
    # Convert vectors of snapshots into arrays
    #
    # networks:
    #     n × n × N × T_saved
    #
    # cumulative_conversations:
    #     N × N × T_saved
    #
    # z_scores:
    #     N × T_saved
    # --------------------------------------------------------

    networks =
        cat(
            network_snapshots...;
            dims = 4
        )

    cumulative_conversations =
        cat(
            conversation_snapshots...;
            dims = 3
        )


    return (
        networks =
            networks,

        saved_steps =
            saved_steps,

        cumulative_conversations =
            cumulative_conversations,

    )
end
function run_one_new_bank_attempt(;
    seed::Int,

    homophily::Real,
    agent1_learning::Real,
    other_agents_learning::Real,

    threshold::Real,
    snapshot_stride::Int,

    N::Int,
    W::Int,
    H::Int,
    n::Int,
    m::Int,
    change::Float64,

    steps::Int,
    reset_every::Int,
    record_every::Int,

    abandonment_threshold::Int,
    outliers_count::Int,
    outlier_change,

    isolated_agent,
    isolated_agent_interaction_prob,

    talk_duration::Int,
    refractory_duration::Int,
    self_talk_threshold::Int,
    L::Int,
    eta::Float32,

    gamma::Real,
    beta::Real,
    delta::Real,
    p0::Real,
    pmin::Real,

    social_impact::Real,
    join_rule::Symbol)


    # --------------------------------------------------------
    # Condition-specific learning vector
    # --------------------------------------------------------

    social_learning_prob =
        make_social_learning_prob(
            N,
            agent1_learning;
            other_agents_learning =
                other_agents_learning
        )


    # ========================================================
    # PASS 1 — detect crossing
    # ========================================================

    detection =
        run_crossing_detection_pass(

            seed = seed,

            N = N,
            W = W,
            H = H,
            n = n,
            m = m,
            change = change,

            steps = steps,

            reset_every =
                reset_every,

            record_every =
                record_every,

            abandonment_threshold =
                abandonment_threshold,

            outliers_count =
                outliers_count,

            outlier_change =
                outlier_change,

            isolated_agent =
                isolated_agent,

            isolated_agent_interaction_prob =
                isolated_agent_interaction_prob,

            talk_duration =
                talk_duration,

            refractory_duration =
                refractory_duration,

            self_talk_threshold =
                self_talk_threshold,

            L = L,
            eta = eta,

            beta_for_consent =
                homophily,

            gamma = gamma,
            beta = beta,
            delta = delta,

            p0 = p0,
            pmin = pmin,

            social_impact =
                social_impact,

            join_rule =
                join_rule,

            social_learning_prob =
                social_learning_prob
        )


    # --------------------------------------------------------
    # Stable crossing
    # --------------------------------------------------------

    crossing =
        find_valid_stable_crossing(
            detection.z,
            detection.steps;

            threshold =
                threshold,

            agent1_learning =
                agent1_learning,

            other_agents_learning =
                other_agents_learning
        )


    if crossing === nothing
        return nothing
    end


    # --------------------------------------------------------
    # Which recorded points should actually be saved?
    # --------------------------------------------------------

    selection =
        select_pre_and_post_crossing_indices(
            length(detection.steps),
            crossing.index;

            snapshot_stride =
                snapshot_stride
        )


    selected_steps =
        detection.steps[
            selection.all
        ]

    selected_z_scores =
    detection.z[:, selection.all]


    # ========================================================
    # PASS 2 — reproduce and save selected states
    # ========================================================

    saved =
        run_snapshot_saving_pass(
            selected_steps;

            seed = seed,

            N = N,
            W = W,
            H = H,
            n = n,
            m = m,
            change = change,

            steps = steps,

            reset_every =
                reset_every,

            record_every =
                record_every,

            abandonment_threshold =
                abandonment_threshold,

            outliers_count =
                outliers_count,

            outlier_change =
                outlier_change,

            isolated_agent =
                isolated_agent,

            isolated_agent_interaction_prob =
                isolated_agent_interaction_prob,

            talk_duration =
                talk_duration,

            refractory_duration =
                refractory_duration,

            self_talk_threshold =
                self_talk_threshold,

            L = L,
            eta = eta,

            beta_for_consent =
                homophily,

            gamma = gamma,
            beta = beta,
            delta = delta,

            p0 = p0,
            pmin = pmin,

            social_impact =
                social_impact,

            join_rule =
                join_rule,

            social_learning_prob =
                social_learning_prob
        )



    return (
        saved =
            saved,

        z_scores =
            selected_z_scores,

        crossing =
            crossing,

        social_learning_prob =
            social_learning_prob,

        selected_pre_steps =
            detection.steps[
                selection.pre
            ],

        selected_post_steps =
            detection.steps[
                selection.post
            ]
    )
end
function existing_condition_files(
    bank_dir::String,
    condition_name::String)

    if !isdir(bank_dir)
        return String[]
    end

    prefix =
        condition_name * "_run_"

    files =
        filter(
            f ->
                startswith(f, prefix) &&
                endswith(
                    lowercase(f),
                    ".jld2"
                ),
            readdir(bank_dir)
        )

    return sort(files)
end
function highest_existing_run_number(
    bank_dir::String,
    condition_name::String)

    files =
        existing_condition_files(
            bank_dir,
            condition_name
        )

    isempty(files) &&
        return 0


    prefix =
        condition_name * "_run_"

    run_numbers =
        Int[]


    for file in files

        number_part =
            replace(
                file,
                prefix => "",
                ".jld2" => ""
            )

        parsed =
            tryparse(
                Int,
                number_part
            )

        if parsed !== nothing
            push!(
                run_numbers,
                parsed
            )
        end
    end


    return isempty(run_numbers) ?
        0 :
        maximum(run_numbers)
end
function load_bank_log(bank_dir::String)

    log_path = joinpath(bank_dir, "bank_log.jld2")

    if isfile(log_path)
        return JLD2.load(log_path, "log")
    else
        return Dict{String,NamedTuple}()
    end
end
function save_bank_log(
    bank_dir::String,
    log::Dict)

    log_path = joinpath(bank_dir, "bank_log.jld2")

    JLD2.jldsave(
        log_path;
        log = log
    )

    return nothing
end
function build_new_semantic_network_bank(
    conditions;
    target_runs::Int,

    bank_dir::String =
        "new_semantic_network_bank",

    # --------------------------------------------------------
    # Crossing / saving
    # --------------------------------------------------------

    threshold::Real =
        2.5,

    snapshot_stride::Int =
        10,

    # --------------------------------------------------------
    # Normal social-learning probability
    # --------------------------------------------------------

    other_agents_learning::Real =
        0.9,

    # --------------------------------------------------------
    # Core model parameters
    # --------------------------------------------------------

    N::Int = 20,
    W::Int = 30,
    H::Int = 30,

    n::Int = 300,
    m::Int = 4,

    change::Float64 =
        0.7,

    outliers_count::Int =
        0,

    outlier_change =
        0.71,

    abandonment_threshold::Int =
        2_000_000,

    isolated_agent =
        nothing,

    isolated_agent_interaction_prob =
        nothing,

    # --------------------------------------------------------
    # Simulation timing
    # --------------------------------------------------------

    steps::Int =
        20_000,

    reset_every::Int =
        100,

    record_every::Int =
        100,

    # --------------------------------------------------------
    # Conversation parameters
    # --------------------------------------------------------

    talk_duration::Int =
        10,

    refractory_duration::Int =
        10,

    self_talk_threshold::Int =
        10,

    L::Int =
        25,

    eta::Float32 =
        0.2f0,

    # --------------------------------------------------------
    # Other social/model parameters
    # --------------------------------------------------------

    gamma::Real =
        0.0,

    beta::Real =
        1.0,

    delta::Real =
        1.0,

    p0::Real =
        0.5,

    pmin::Real =
        0.05,

    social_impact::Real =
        1.0,

    join_rule::Symbol =
        :group_any,

    # --------------------------------------------------------
    # Safety
    # --------------------------------------------------------

    max_attempts_per_condition::Int =
        100_000,

    verbose::Bool =
        true)


    # ========================================================
    # Validate
    # ========================================================

    @assert target_runs >= 1
    @assert record_every >= 1
    @assert reset_every >= 1
    @assert snapshot_stride >= 1


    # --------------------------------------------------------
    # Create new bank folder if needed
    # --------------------------------------------------------

    mkpath(bank_dir)

    bank_log =
        load_bank_log(bank_dir)


    # --------------------------------------------------------
    # Prevent accidental duplicate conditions
    # --------------------------------------------------------

    condition_names =
        String[]


    for condition in conditions

        condition_name =
            make_condition_name(
                condition.homophily,
                condition.agent1_learning
            )

        push!(
            condition_names,
            condition_name
        )
    end


    @assert length(unique(condition_names)) ==
            length(condition_names) """
    Duplicate conditions were supplied.
    """


    # ========================================================
    # Run each condition
    # ========================================================

    for condition in conditions

        homophily =
            Float64(
                condition.homophily
            )

        agent1_learning =
            Float64(
                condition.agent1_learning
            )


        condition_name =
            make_condition_name(
                homophily,
                agent1_learning
            )


        # ----------------------------------------------------
        # Count already existing valid runs
        # ----------------------------------------------------

        existing =
            existing_condition_files(
                bank_dir,
                condition_name
            )

        n_saved =
            length(existing)

        # All run numbers currently present for this condition
        existing_numbers = Set(
            parse(Int, match(r"_run_(\d+)\.jld2$", filename).captures[1])
            for filename in existing
        )

        # Missing run numbers within the requested range
        missing_numbers = [
            i for i in 1:target_runs
            if !(i in existing_numbers)
        ]

        # Continue beyond the highest existing number only if needed
        next_run_number = highest_existing_run_number(
            bank_dir,
            condition_name
        ) + 1

        if haskey(bank_log, condition_name)

            # The condition was already run in the past.
            # Keep the historical number of attempts,
            # but synchronize valid_runs with the files
            # that actually exist in the folder.

            old_log =
                bank_log[condition_name]

            bank_log[condition_name] = (
                attempts = old_log.attempts,
                valid_runs = n_saved
            )

        else

            # First time this condition is encountered.
            # Existing files, if any, are counted as valid runs,
            # but previous attempts are unknown.

            bank_log[condition_name] = (
                attempts = 0,
                valid_runs = n_saved
            )

        end

        save_bank_log(
            bank_dir,
            bank_log
        )


        if verbose

            println()
            println(
                "============================================================"
            )

            println(
                "Condition: ",
                condition_name
            )

            println(
                "Homophily: ",
                homophily
            )

            println(
                "Agent 1 social learning: ",
                agent1_learning
            )

            println(
                "Other agents social learning: ",
                other_agents_learning
            )

            println(
                "Existing valid runs: ",
                n_saved,
                " / ",
                target_runs
            )

            println(
                "============================================================"
            )
        end


        # ----------------------------------------------------
        # Condition already complete
        # ----------------------------------------------------

        if n_saved >= target_runs

            verbose &&
                println(
                    "Condition already complete."
                )

            continue
        end


        attempts =
            0


        # ====================================================
        # Continue until target VALID runs is reached
        # ====================================================

        while n_saved < target_runs

            attempts += 1

            old_log =
                bank_log[condition_name]

            bank_log[condition_name] = (
                attempts = old_log.attempts + 1,
                valid_runs = old_log.valid_runs
            )

            save_bank_log(
                bank_dir,
                bank_log
            )


            if attempts >
               max_attempts_per_condition

                error(
                    "Maximum number of attempts reached for condition: ",
                    condition_name
                )
            end


            # ------------------------------------------------
            # New random seed for this attempt
            #
            # It is stored later in metadata and reused for
            # the second pass of this same attempt.
            # ------------------------------------------------

            seed =
                rand(
                    1:typemax(Int32)
                )


            if verbose

                println(
                    "Attempt ",
                    attempts,
                    " | valid runs ",
                    n_saved,
                    " / ",
                    target_runs
                )
            end


            # ------------------------------------------------
            # Run one attempt
            # ------------------------------------------------

            result =
                run_one_new_bank_attempt(

                    seed = seed,

                    homophily =
                        homophily,

                    agent1_learning =
                        agent1_learning,

                    other_agents_learning =
                        other_agents_learning,

                    threshold =
                        threshold,

                    snapshot_stride =
                        snapshot_stride,

                    N = N,
                    W = W,
                    H = H,

                    n = n,
                    m = m,
                    change = change,

                    steps = steps,

                    reset_every =
                        reset_every,

                    record_every =
                        record_every,

                    abandonment_threshold =
                        abandonment_threshold,

                    outliers_count =
                        outliers_count,

                    outlier_change =
                        outlier_change,

                    isolated_agent =
                        isolated_agent,

                    isolated_agent_interaction_prob =
                        isolated_agent_interaction_prob,

                    talk_duration =
                        talk_duration,

                    refractory_duration =
                        refractory_duration,

                    self_talk_threshold =
                        self_talk_threshold,

                    L = L,
                    eta = eta,

                    gamma = gamma,
                    beta = beta,
                    delta = delta,

                    p0 = p0,
                    pmin = pmin,

                    social_impact =
                        social_impact,

                    join_rule =
                        join_rule
                )


            # ------------------------------------------------
            # No valid stable crossing
            # ------------------------------------------------

            if result === nothing

                verbose &&
                    println(
                        "  -> No valid stable crossing. Not saved."
                    )

                continue
            end


            # =================================================
            # Valid run
            # =================================================

            run_number = if !isempty(missing_numbers)
                popfirst!(missing_numbers)
            else
                next_run_number
            end


            filename =
                string(
                    condition_name,
                    "_run_",
                    lpad(
                        string(run_number),
                        3,
                        '0'
                    ),
                    ".jld2"
                )


            path =
                joinpath(
                    bank_dir,
                    filename
                )


            @assert !isfile(path) """
            Refusing to overwrite existing file:
            $path
            """


            # =================================================
            # Metadata
            # =================================================

            metadata =
                (
                    # -----------------------------------------
                    # Identity
                    # -----------------------------------------

                    condition =
                        condition_name,

                    run_number =
                        run_number,

                    seed =
                        seed,

                    # -----------------------------------------
                    # Experimental condition
                    # -----------------------------------------

                    homophily =
                        homophily,

                    agent1_learning =
                        agent1_learning,

                    other_agents_learning =
                        Float64(
                            other_agents_learning
                        ),

                    social_learning_prob =
                        copy(
                            result.social_learning_prob
                        ),

                    # -----------------------------------------
                    # Crossing
                    # -----------------------------------------

                    threshold =
                        Float64(threshold),

                    crossing_agent =
                        result.crossing.agent,

                    crossing_step =
                        result.crossing.step,

                    crossing_z =
                        result.crossing.z,

                    # -----------------------------------------
                    # Snapshot rules
                    # -----------------------------------------

                    snapshot_stride =
                        snapshot_stride,

                    record_every =
                        record_every,

                    reset_every =
                        reset_every,

                    selected_pre_steps =
                        copy(
                            result.selected_pre_steps
                        ),

                    selected_post_steps =
                        copy(
                            result.selected_post_steps
                        ),

                    # -----------------------------------------
                    # Model dimensions
                    # -----------------------------------------

                    N = N,
                    W = W,
                    H = H,
                    n = n,
                    m = m,

                    # -----------------------------------------
                    # Semantic-network generation
                    # -----------------------------------------

                    change =
                        change,

                    outliers_count =
                        outliers_count,

                    outlier_change =
                        outlier_change,

                    # -----------------------------------------
                    # Simulation
                    # -----------------------------------------

                    steps =
                        steps,

                    talk_duration =
                        talk_duration,

                    refractory_duration =
                        refractory_duration,

                    self_talk_threshold =
                        self_talk_threshold,

                    L = L,

                    eta =
                        eta,

                    gamma =
                        Float64(gamma),

                    beta =
                        Float64(beta),

                    delta =
                        Float64(delta),

                    p0 =
                        Float64(p0),

                    pmin =
                        Float64(pmin),

                    social_impact =
                        Float64(social_impact),

                    join_rule =
                        join_rule,

                    abandonment_threshold =
                        abandonment_threshold,

                    isolated_agent =
                        isolated_agent,

                    isolated_agent_interaction_prob =
                        isolated_agent_interaction_prob
                )


            # =================================================
            # Save file
            # =================================================

            JLD2.jldopen(
                path,
                "w";
                iotype = IOStream
            ) do f

                # ---------------------------------------------
                # Core semantic data
                # n × n × N × T_saved
                # ---------------------------------------------

                f["networks"] =
                    result.saved.networks


                # ---------------------------------------------
                # Original simulation step of every snapshot
                # ---------------------------------------------

                f["saved_steps"] =
                    result.saved.saved_steps


                # ---------------------------------------------
                # Social state at each snapshot
                #
                # N × N × T_saved
                #
                # [i,j,t] =
                # number of conversation episodes agents i and j
                # have shared from the start of the simulation
                # through saved_steps[t].
                # ---------------------------------------------

                f["cumulative_conversations"] =
                    result.saved.cumulative_conversations


                # ---------------------------------------------
                # Outlier z-score for every agent at each saved
                # snapshot.
                #
                # N × T_saved
                # ---------------------------------------------

                f["z_scores"] =
                    result.z_scores

                # ---------------------------------------------
                # Full description of the run
                # ---------------------------------------------

                f["metadata"] =
                    metadata
            end


            # ------------------------------------------------
            # Update counters only AFTER successful save
            # ------------------------------------------------

            n_saved += 1

            push!(existing_numbers, run_number)

            next_run_number = max(
                next_run_number,
                run_number + 1
            )

            old_log =
                bank_log[condition_name]

            bank_log[condition_name] = (
                attempts = old_log.attempts,
                valid_runs = n_saved
            )

            save_bank_log(
                bank_dir,
                bank_log
            )


            if verbose

                println(
                    "  -> SAVED: ",
                    filename
                )

                println(
                    "     crossing agent = ",
                    result.crossing.agent,
                    ", crossing step = ",
                    result.crossing.step
                )

                println(
                    "     snapshots saved = ",
                    length(
                        result.saved.saved_steps
                    )
                )
            end
        end


        if verbose

            println()
            println(
                "Condition complete: ",
                condition_name,
                " (",
                n_saved,
                " valid runs)"
            )
        end
    end


    println()
    println(
        "All requested conditions are complete."
    )

    println(
        "Bank folder: ",
        bank_dir
    )


    return nothing
end

conditions = [
    (homophily = 0.0, agent1_learning = 0.9),
    (homophily = 3.0, agent1_learning = 0.9),
    (homophily = 0.0, agent1_learning = 0.5),
    (homophily = 3.0, agent1_learning = 0.5)
]
# build_new_semantic_network_bank(
#     conditions;
#     target_runs = 150,
#     bank_dir = "new_semantic_network_bank"
# )

# ============================================================
# EXTREME AGENT METRICS DATASET
# ============================================================
function tvd_counts(
    x::AbstractVector,
    y::AbstractVector)

    sx = sum(x)
    sy = sum(y)

    if sx == 0 && sy == 0
        return 0.0
    elseif sx == 0 || sy == 0
        return 1.0
    end

    px = x ./ sx
    py = y ./ sy

    return 0.5 * sum(abs.(px .- py))
end
function tvd_matrix(
    A::AbstractMatrix,
    B::AbstractMatrix)

    return tvd_counts(
        vec(A),
        vec(B)
    )
end
function column_normalized_tvd(
    A::AbstractMatrix,
    B::AbstractMatrix)

    @assert size(A) == size(B)

    n_columns = size(A, 2)

    total_distance = 0.0
    valid_columns = 0

    for col in 1:n_columns

        a = @view A[:, col]
        b = @view B[:, col]

        sa = sum(a)
        sb = sum(b)

        if sa == 0 && sb == 0

            continue

        elseif sa == 0 || sb == 0

            total_distance += 1.0
            valid_columns += 1

        else

            total_distance +=
                0.5 *
                sum(
                    abs.(
                        a ./ sa .-
                        b ./ sb
                    )
                )

            valid_columns += 1
        end
    end

    return valid_columns == 0 ?
        NaN :
        total_distance / valid_columns
end

function zscore_across_agents(
    values::AbstractVector)

    values_f64 =
        Float64.(values)

    μ =
        Statistics.mean(values_f64)

    σ =
        Statistics.std(values_f64)

    if σ == 0 || !isfinite(σ)
        return zeros(Float64, length(values_f64))
    end

    return (values_f64 .- μ) ./ σ
end


function metric_mean_distance_from_others(
    agents::Array{Float32,3})

    N =
        size(agents, 3)

    @assert N >= 2

    D =
        differences(agents)

    values =
        zeros(Float64, N)

    for i in 1:N

        total =
            0.0

        for j in 1:N

            if i != j
                total += Float64(D[i, j])
            end
        end

        values[i] =
            total / (N - 1)
    end

    return values
end
function metric_distance_from_mean_network(
    agents::Array{Float32,3})

    N =
        size(agents, 3)

    mean_network =
        dropdims(
            Statistics.mean(
                agents;
                dims = 3
            );
            dims = 3
        )

    values =
        zeros(Float64, N)

    for agent in 1:N

        A =
            @view agents[:, :, agent]

        values[agent] =
            tvd_matrix(
                A,
                mean_network
            )
    end

    return values
end
function metric_column_normalized_distance_from_mean(
    agents::Array{Float32,3})

    N =
        size(agents, 3)

    mean_network =
        dropdims(
            Statistics.mean(
                agents;
                dims = 3
            );
            dims = 3
        )

    values =
        zeros(Float64, N)

    for agent in 1:N

        A =
            @view agents[:, :, agent]

        values[agent] =
            column_normalized_tvd(
                A,
                mean_network
            )
    end

    return values
end
function metric_word_degree_distance_from_mean(
    agents::Array{Float32,3})

    n =
        size(agents, 1)

    N =
        size(agents, 3)

    degrees =
        zeros(Float64, n, N)

    for agent in 1:N

        A =
            @view agents[:, :, agent]

        degrees[:, agent] .=
            vec(
                Statistics.sum(
                    A;
                    dims = 1
                )
            )
    end

    mean_degrees =
        vec(
            Statistics.mean(
                degrees;
                dims = 2
            )
        )

    values =
        zeros(Float64, N)

    for agent in 1:N

        values[agent] =
            tvd_counts(
                @view(degrees[:, agent]),
                mean_degrees
            )
    end

    return values
end

function calculate_all_semantic_metrics(
    agents::Array{Float32,3})

    metric_a =
        metric_mean_distance_from_others(
            agents
        )

    metric_b =
        metric_distance_from_mean_network(
            agents
        )

    metric_c =
        metric_column_normalized_distance_from_mean(
            agents
        )

    metric_d =
        metric_word_degree_distance_from_mean(
            agents
        )


    return (
        mean_distance_from_others =
            metric_a,

        mean_distance_from_others_z =
            zscore_across_agents(metric_a),


        distance_from_mean_network =
            metric_b,

        distance_from_mean_network_z =
            zscore_across_agents(metric_b),


        column_normalized_distance_from_mean =
            metric_c,

        column_normalized_distance_from_mean_z =
            zscore_across_agents(metric_c),


        word_degree_distance_from_mean =
            metric_d,

        word_degree_distance_from_mean_z =
            zscore_across_agents(metric_d)
    )
end

function requested_crossing_timepoints(
    crossing_step::Int,
    final_step::Int,
    record_every::Int)

    @assert crossing_step >= record_every
    @assert final_step >= crossing_step


    # --------------------------------------------------------
    # All original recorded points before crossing
    # --------------------------------------------------------

    pre_steps =
        collect(
            0:
            record_every:
            (crossing_step - record_every)
        )


    # --------------------------------------------------------
    # Crossing and everything after it
    # --------------------------------------------------------

    post_steps =
        collect(
            crossing_step:
            record_every:
            final_step
        )


    @assert !isempty(pre_steps)
    @assert !isempty(post_steps)


    function five_anchor_steps(
        steps_vector::Vector{Int})

        L =
            length(steps_vector)

        fractions =
            (
                0.0,
                0.25,
                0.50,
                0.75,
                1.0
            )

        return [
            steps_vector[
                clamp(
                    round(
                        Int,
                        1 +
                        fraction * (L - 1)
                    ),
                    1,
                    L
                )
            ]
            for fraction in fractions
        ]
    end


    selected_pre =
        five_anchor_steps(
            pre_steps
        )

    selected_post =
        five_anchor_steps(
            post_steps
        )


    return (
        labels = [
            "pre_0",
            "pre_25",
            "pre_50",
            "pre_75",
            "pre_100",
            "post_0",
            "post_25",
            "post_50",
            "post_75",
            "post_100"
        ],

        phases = [
            "pre",
            "pre",
            "pre",
            "pre",
            "pre",
            "post",
            "post",
            "post",
            "post",
            "post"
        ],

        percentages = [
            0,
            25,
            50,
            75,
            100,
            0,
            25,
            50,
            75,
            100
        ],

        steps =
            vcat(
                selected_pre,
                selected_post
            )
    )
end

function analyze_one_run_semantic_metrics(
    path::String)

    d =
        JLD2.load(path)


    networks =
        d["networks"]

    saved_steps =
        Int.(d["saved_steps"])

    metadata =
        d["metadata"]


    condition =
        String(metadata.condition)

    run_number =
        Int(metadata.run_number)

    crossing_step =
        Int(metadata.crossing_step)

    final_step =
        Int(metadata.steps)

    record_every =
        Int(metadata.record_every)


    # --------------------------------------------------------
    # 1. Identify the FINAL snapshot
    # --------------------------------------------------------

    final_saved_idx =
        findfirst(
            ==(final_step),
            saved_steps
        )

    final_saved_idx === nothing &&
        error(
            "Final step $final_step was not found in $path"
        )


    final_agents =
        networks[
            :,
            :,
            :,
            final_saved_idx
        ]


    # --------------------------------------------------------
    # 2. Identify the focal agent according to Metric A
    #    AT THE END OF THE SIMULATION
    # --------------------------------------------------------

    final_mean_distances =
        metric_mean_distance_from_others(
            final_agents
        )

    focal_agent = metadata.crossing_agent


    # --------------------------------------------------------
    # 3. Determine the exact 10 requested points
    # --------------------------------------------------------

    requested =
        requested_crossing_timepoints(
            crossing_step,
            final_step,
            record_every
        )


    # --------------------------------------------------------
    # 4. Prepare output DataFrame
    # --------------------------------------------------------

    results =
        DataFrames.DataFrame(

            condition =
                String[],

            file =
                String[],

            run_number =
                Int[],

            focal_agent =
                Int[],

            crossing_agent =
                Int[],

            crossing_step =
                Int[],

            timepoint =
                String[],

            phase =
                String[],

            percentage =
                Int[],

            saved_step =
                Int[],

            mean_distance_from_others =
                Float64[],

            mean_distance_from_others_z =
                Float64[],

            distance_from_mean_network =
                Float64[],

            distance_from_mean_network_z =
                Float64[],

            column_normalized_distance_from_mean =
                Float64[],

            column_normalized_distance_from_mean_z =
                Float64[],

            word_degree_distance_from_mean =
                Float64[],

            word_degree_distance_from_mean_z =
                Float64[]
        )


    # --------------------------------------------------------
    # 5. Analyze each requested snapshot
    # --------------------------------------------------------

    for k in eachindex(requested.steps)

        target_step =
            requested.steps[k]


        saved_idx =
            findfirst(
                ==(target_step),
                saved_steps
            )


        if saved_idx === nothing

            error(
                """
                Required snapshot was not found.

                File: $path
                Required step: $target_step
                Available saved steps:
                $(saved_steps)
                """
            )
        end


        agents =
            networks[
                :,
                :,
                :,
                saved_idx
            ]


        metrics =
            calculate_all_semantic_metrics(
                agents
            )


        push!(
            results,
            (
                condition =
                    condition,

                file =
                    basename(path),

                run_number =
                    run_number,

                focal_agent =
                    focal_agent,

                crossing_agent =
                    Int(metadata.crossing_agent),

                crossing_step =
                    crossing_step,

                timepoint =
                    requested.labels[k],

                phase =
                    requested.phases[k],

                percentage =
                    requested.percentages[k],

                saved_step =
                    target_step,

                mean_distance_from_others =
                    metrics.mean_distance_from_others[
                        focal_agent
                    ],

                mean_distance_from_others_z =
                    metrics.mean_distance_from_others_z[
                        focal_agent
                    ],

                distance_from_mean_network =
                    metrics.distance_from_mean_network[
                        focal_agent
                    ],

                distance_from_mean_network_z =
                    metrics.distance_from_mean_network_z[
                        focal_agent
                    ],

                column_normalized_distance_from_mean =
                    metrics.column_normalized_distance_from_mean[
                        focal_agent
                    ],

                column_normalized_distance_from_mean_z =
                    metrics.column_normalized_distance_from_mean_z[
                        focal_agent
                    ],

                word_degree_distance_from_mean =
                    metrics.word_degree_distance_from_mean[
                        focal_agent
                    ],

                word_degree_distance_from_mean_z =
                    metrics.word_degree_distance_from_mean_z[
                        focal_agent
                    ]
            )
        )
    end


    return results
end
function build_or_update_extreme_agent_metrics(
    bank_dir::String =
        "new_semantic_network_bank";

    output_filename::String =
        "extreme_agent_time_metrics.jld2",

    verbose::Bool =
        true)


    output_path =
        joinpath(
            bank_dir,
            output_filename
        )


    # ========================================================
    # 1. Load existing results if present
    # ========================================================

    if isfile(output_path)

        existing_results =
            JLD2.load(
                output_path,
                "results"
            )

        existing_results =
            DataFrames.DataFrame(
                existing_results
            )

        verbose &&
            println(
                "Existing analysis file loaded: ",
                output_filename
            )

    else

        existing_results =
            DataFrames.DataFrame()

        verbose &&
            println(
                "No existing analysis file found. Creating a new one."
            )
    end


    # ========================================================
    # 2. Find simulation files
    # ========================================================

    simulation_files =
        filter(
            f -> occursin(r"_run_\d+\.jld2$", f),
            readdir(bank_dir)
        )

    sort!(
        simulation_files
    )


    verbose &&
        println(
            "Simulation files found: ",
            length(simulation_files)
        )


    # ========================================================
    # 3. Determine which files are already COMPLETE
    # ========================================================

    complete_files =
        Set{String}()


    if nrow(existing_results) > 0

        grouped =
            DataFrames.groupby(
                existing_results,
                :file
            )


        for group in grouped

            labels =
                Set(
                    String.(
                        group.timepoint
                    )
                )

            required_labels =
                Set([
                    "pre_0",
                    "pre_25",
                    "pre_50",
                    "pre_75",
                    "pre_100",
                    "post_0",
                    "post_25",
                    "post_50",
                    "post_75",
                    "post_100"
                ])


            if labels == required_labels &&
               nrow(group) == 10

                push!(
                    complete_files,
                    String(group.file[1])
                )
            end
        end
    end


    verbose &&
        println(
            "Already completely documented: ",
            length(complete_files)
        )


    # ========================================================
    # 4. Analyze missing / incomplete files
    # ========================================================

    for (
        file_index,
        filename
    ) in enumerate(simulation_files)


        # ----------------------------------------------------
        # Already complete -> skip
        # ----------------------------------------------------

        if filename in complete_files

            verbose &&
                println(
                    "[",
                    file_index,
                    "/",
                    length(simulation_files),
                    "] SKIP: ",
                    filename
                )

            continue
        end


        verbose &&
            println(
                "[",
                file_index,
                "/",
                length(simulation_files),
                "] ANALYZE: ",
                filename
            )


        # ----------------------------------------------------
        # If this run exists partially, remove its old rows
        # before recalculating it.
        # ----------------------------------------------------

        if nrow(existing_results) > 0 &&
           :file in DataFrames.names(
               existing_results
           )

            keep_rows =
                existing_results.file .!=
                filename

            existing_results =
                existing_results[
                    keep_rows,
                    :
                ]
        end


        # ----------------------------------------------------
        # Analyze run
        # ----------------------------------------------------

        path =
            joinpath(
                bank_dir,
                filename
            )

        new_rows =
            analyze_one_run_semantic_metrics(
                path
            )


        # ----------------------------------------------------
        # Append
        # ----------------------------------------------------

        if nrow(existing_results) == 0

            existing_results =
                new_rows

        else

            DataFrames.append!(
                existing_results,
                new_rows
            )
        end


        # ----------------------------------------------------
        # Save after EVERY completed run.
        #
        # This means that if the analysis is interrupted,
        # already completed work is retained.
        # ----------------------------------------------------

        JLD2.jldsave(
            output_path;
            results =
                existing_results
        )


        verbose &&
            println(
                "    saved 10 timepoints | focal agent = ",
                new_rows.focal_agent[1]
            )
    end


    # ========================================================
    # 5. Final summary
    # ========================================================

    n_runs =
        nrow(existing_results) == 0 ?
        0 :
        length(
            unique(
                existing_results.file
            )
        )


    println()
    println(
        "Analysis complete."
    )

    println(
        "Documented runs: ",
        n_runs
    )

    println(
        "Rows: ",
        nrow(existing_results)
    )

    println(
        "Saved to: ",
        output_path
    )


    return existing_results
end


