function build_social_metrics_file(
    semantic_path::String,
    bank_dir::String,
    output_path::String;
    show_progress::Bool = true)

    semantic = JLD2.load(semantic_path, "results")

    required_columns = [
        :condition,
        :file,
        :run_number,
        :focal_agent,
        :timepoint,
        :saved_step
    ]

    missing_columns = setdiff(
        required_columns,
        propertynames(semantic)
    )

    isempty(missing_columns) ||
        error("Missing semantic columns: $missing_columns")

    social = DataFrames.DataFrame(
        condition = String[],
        file = String[],
        run_number = Int[],
        focal_agent = Int[],
        timepoint = String[],
        saved_step = Int[],
        total_conversations = Int[],
        conversations_z = Float64[],
        conversations_rank = Int[]
    )

    # Each simulation file is loaded only once.
    runs = DataFrames.groupby(
        semantic,
        [:condition, :run_number]
    )

    total_runs = length(runs)

    for (run_idx, run_data) in enumerate(runs)

        condition = string(run_data.condition[1])
        run_number = Int(run_data.run_number[1])
        filename = string(run_data.file[1])

        path = isabspath(filename) ?
            filename :
            joinpath(bank_dir, filename)

        isfile(path) ||
            error("Simulation file not found: $path")

        d = JLD2.load(path)

        haskey(d, "saved_steps") ||
            error("Missing saved_steps in $filename")

        haskey(d, "cumulative_conversations") ||
            error("Missing cumulative_conversations in $filename")

        saved_steps = Int.(d["saved_steps"])
        C = d["cumulative_conversations"]

        N = size(C, 1)

        size(C, 2) == N ||
            error("Conversation matrix is not square: $filename")

        size(C, 3) == length(saved_steps) ||
            error("Snapshot count mismatch: $filename")

        length(unique(saved_steps)) == length(saved_steps) ||
            error("Duplicate saved steps: $filename")

        step_lookup = Dict(
            step => idx
            for (idx, step) in enumerate(saved_steps)
        )

        for row in eachrow(run_data)

            agent = Int(row.focal_agent)
            step = Int(row.saved_step)

            1 <= agent <= N ||
                error("Invalid focal agent in $filename")

            haskey(step_lookup, step) ||
                error(
                    "Step $step not found in $filename"
                )

            snapshot_idx = step_lookup[step]

            # Number of conversation episodes per agent.
            # Each agent's total is the sum of its
            # conversations with all other agents.

            conversations = Vector{Int}(undef, N)

            for i in 1:N

                conversations[i] = sum(
                    Int(C[i, j, snapshot_idx])
                    for j in 1:N
                    if j != i
                )
            end

            focal_count = conversations[agent]

            # Z-score relative to all N agents
            μ = Statistics.mean(conversations)
            σ = Statistics.std(conversations)

            focal_z = if σ == 0
                0.0
            else
                (focal_count - μ) / σ
            end

            # Competition ranking:
            # 1 = highest conversation count.
            # Ties receive the same rank.

            focal_rank =
                1 + count(>(focal_count), conversations)

            push!(social, (
                condition,
                filename,
                run_number,
                agent,
                string(row.timepoint),
                step,
                focal_count,
                focal_z,
                focal_rank
            ))
        end

        if show_progress &&
           (run_idx == 1 ||
            run_idx % 10 == 0 ||
            run_idx == total_runs)

            println(
                "Processed ",
                run_idx,
                " / ",
                total_runs,
                " runs | ",
                condition,
                " | run ",
                run_number
            )
        end
    end

    # Verify that each semantic row has exactly
    # one corresponding social row.

    DataFrames.nrow(social) == DataFrames.nrow(semantic) ||
        error("Social and semantic row counts differ.")

    keys = [
        :condition,
        :run_number,
        :focal_agent,
        :timepoint,
        :saved_step
    ]

    DataFrames.nrow(unique(social[:, keys])) ==
        DataFrames.nrow(social) ||
        error("Duplicate social observations detected.")

    mkpath(dirname(output_path))

    JLD2.jldsave(
        output_path;
        results = social
    )

    println("\nSocial metrics file created successfully.")
    println("Path: ", output_path)
    println("Runs: ", total_runs)
    println("Rows: ", DataFrames.nrow(social))

    return social
end
