# ============================================================
# EXTREME AGENT METRICS PLOTS
# ============================================================
const SEMANTIC_METRICS_RAW = [
    :mean_distance_from_others,
    :distance_from_mean_network,
    :column_normalized_distance_from_mean,
    :word_degree_distance_from_mean
]
const SEMANTIC_METRICS_Z = [
    :mean_distance_from_others_z,
    :distance_from_mean_network_z,
    :column_normalized_distance_from_mean_z,
    :word_degree_distance_from_mean_z
]
const SEMANTIC_METRIC_LABELS = Dict(

    :mean_distance_from_others =>
        "Mean distance from others",

    :mean_distance_from_others_z =>
        "Mean distance from others",

    :distance_from_mean_network =>
        "Distance from mean network",

    :distance_from_mean_network_z =>
        "Distance from mean network",

    :column_normalized_distance_from_mean =>
        "Column-normalized TVD",

    :column_normalized_distance_from_mean_z =>
        "Column-normalized TVD",

    :word_degree_distance_from_mean =>
        "Word-frequency TVD",

    :word_degree_distance_from_mean_z =>
        "Word-frequency TVD"
)
const SEMANTIC_TIMEPOINT_ORDER = [
    "pre_0",
    "pre_25",
    "pre_50",
    "pre_75",
    "pre_100",
    "post_0",
    "post_25",
    "post_50",
    "post_75",
    "post_100"
]
const SEMANTIC_TIMEPOINT_LABELS = Dict(

    "pre_0" =>
        "Pre 0%",

    "pre_25" =>
        "Pre 25%",

    "pre_50" =>
        "Pre 50%",

    "pre_75" =>
        "Pre 75%",

    "pre_100" =>
        "Pre-crossing",

    "post_0" =>
        "Crossing",

    "post_25" =>
        "Post 25%",

    "post_50" =>
        "Post 50%",

    "post_75" =>
        "Post 75%",

    "post_100" =>
        "Post 100%"
)
function parse_semantic_timepoint(timepoint)

    if timepoint isa AbstractString

        tp =
            String(timepoint)

        if !(tp in SEMANTIC_TIMEPOINT_ORDER)

            Base.error(
                "Invalid timepoint: $tp"
            )
        end

        return tp
    end


    if timepoint isa Tuple &&
       length(timepoint) == 2

        phase =
            Symbol(timepoint[1])

        percentage =
            Int(timepoint[2])


        if !(phase in (:pre, :post))

            Base.error(
                "Phase must be :pre or :post."
            )
        end


        if !(percentage in (0, 25, 50, 75, 100))

            Base.error(
                "Percentage must be 0, 25, 50, 75, or 100."
            )
        end


        return string(
            phase,
            "_",
            percentage
        )
    end


    Base.error(
        """
        Invalid timepoint.

        Examples:
            (:pre, 50)
            (:post, 0)
            (:post, 75)
        """
    )
end
function pretty_condition_label(
    condition::AbstractString)

    m =
        match(
            r"homophily_([0-9]+(?:_[0-9]+)?)_learning1_([0-9]+(?:_[0-9]+)?)",
            condition
        )


    if m === nothing
        return String(condition)
    end


    h =
        replace(
            m.captures[1],
            "_" => "."
        )

    l =
        replace(
            m.captures[2],
            "_" => "."
        )


    return "H = $h, L = $l"
end
function mean_and_error(
    values;
    error_type::Symbol = :sd)


    values =
        Float64.(collect(values))


    if isempty(values)

        Base.error(
            "No observations were found for one of the requested groups."
        )
    end


    μ =
        Statistics.mean(values)


    if error_type == :none ||
       length(values) == 1

        return μ, 0.0
    end


    σ =
        Statistics.std(values)


    if error_type == :sd

        return μ, σ

    elseif error_type == :sem

        return μ, σ / sqrt(length(values))

    else

        Base.error(
            "error_type must be :sd, :sem, or :none."
        )
    end
end
function plot_grouped_bars_plotly(
    means::AbstractMatrix,
    errors::AbstractMatrix,
    x_labels::Vector{String},
    group_labels::Vector{String};

    xlabel::String,
    ylabel::String,
    title::String,

    error_type::Symbol = :sd,

    fontfamily::String = "Calibri",

    size = (1100, 650),

    xrotation::Real = 0)


    means =
        Matrix{Float64}(means)

    errors =
        Matrix{Float64}(errors)


    n_x =
        Base.size(means, 1)

    n_groups =
        Base.size(means, 2)


    @assert Base.size(errors) == Base.size(means)

    @assert length(x_labels) == n_x

    @assert length(group_labels) == n_groups


    # Width allocated to the full cluster of bars
    cluster_width =
        0.78

    individual_width =
        cluster_width / n_groups


    p =
        Plots.plot(
            ;

            xlabel =
                xlabel,

            ylabel =
                ylabel,

            title =
                title,

            xticks = (
                1:n_x,
                x_labels
            ),

            xrotation =
                xrotation,

            legend =
                :outertopright,

            grid =
                false,

            framestyle =
                :box,

            fontfamily =
                fontfamily,

            size =
                size,

            tickfontsize =
                12,

            guidefontsize =
                14,

            titlefontsize =
                17,

            legendfontsize =
                11,

            linewidth =
                2
        )

    palette =
    Plots.palette(
        :default,
        n_groups
    )


    for group_i in 1:n_groups

        offset =
            (
                group_i -
                (n_groups + 1) / 2
            ) *
            individual_width


        x_positions =
            Float64.(1:n_x) .+
            offset


        # ----------------------------------------------------
        # Bars
        # ----------------------------------------------------

        Plots.bar!(
            p,
            x_positions,
            means[:, group_i];

            bar_width =
                individual_width * 0.88,

            label =
                group_labels[group_i],

            color =
                palette[group_i],

            linecolor =
                palette[group_i],

            linealpha =
                0.9
        )


        # ----------------------------------------------------
        # Manual error bars
        # ----------------------------------------------------

        if error_type != :none

            cap_half_width =
                individual_width * 0.18


            for i in 1:n_x

                x =
                    x_positions[i]

                μ =
                    means[i, group_i]

                err =
                    errors[i, group_i]


                lower =
                    μ - err

                upper =
                    μ + err


                # Vertical line
                Plots.plot!(
                    p,
                    [x, x],
                    [lower, upper];

                    color =
                        :black,

                    linewidth =
                        1.6,

                    label =
                        false
                )


                # Bottom cap
                Plots.plot!(
                    p,
                    [
                        x - cap_half_width,
                        x + cap_half_width
                    ],
                    [
                        lower,
                        lower
                    ];

                    color =
                        :black,

                    linewidth =
                        1.6,

                    label =
                        false
                )


                # Top cap
                Plots.plot!(
                    p,
                    [
                        x - cap_half_width,
                        x + cap_half_width
                    ],
                    [
                        upper,
                        upper
                    ];

                    color =
                        :black,

                    linewidth =
                        1.6,

                    label =
                        false
                )
            end
        end
    end


    return p
end
function plot_extreme_agent_metrics(
    results::DataFrames.DataFrame;

    mode::Symbol,
    timepoint = nothing,
    selected_conditions = nothing,
    selected_metrics = nothing,
    use_z::Bool = true,
    error_type::Symbol = :sd,
    fontfamily::String = "Calibri",
    size = (1100, 650))


    if !(mode in (
        :timepoint,
        :metric,
        :condition
    ))

        Base.error(
            "mode must be :timepoint, :metric, or :condition."
        )
    end


    if !(error_type in (
        :sd,
        :sem,
        :none
    ))

        Base.error(
            "error_type must be :sd, :sem, or :none."
        )
    end


    all_metrics =
        use_z ?
        SEMANTIC_METRICS_Z :
        SEMANTIC_METRICS_RAW


    metrics =
        if selected_metrics === nothing

            all_metrics

        else

            requested =
                Symbol.(selected_metrics)

            # Allow specifying either raw or z-score metric names.
            # The function automatically uses the appropriate version
            # according to use_z.
            requested_base =
                [
                    Symbol(
                        replace(
                            String(m),
                            r"_z$" => ""
                        )
                    )
                    for m in requested
                ]

            available_base =
                [
                    Symbol(
                        replace(
                            String(m),
                            r"_z$" => ""
                        )
                    )
                    for m in all_metrics
                ]

            missing_metrics =
                setdiff(
                    requested_base,
                    available_base
                )

            if !isempty(missing_metrics)

                Base.error(
                    "These metrics were not found: " *
                    join(
                        String.(missing_metrics),
                        ", "
                    )
                )
            end

            [
                all_metrics[
                    findfirst(
                        ==(m),
                        available_base
                    )
                ]
                for m in requested_base
            ]
        end

    y_label =
        use_z ?
        "Distance (z)" :
        "Distance"


    all_conditions =
        sort(
            unique(
                String.(
                    results.condition
                )
            )
        )


    conditions =
        if selected_conditions === nothing

            all_conditions

        else

            requested =
                String.(selected_conditions)

            missing_conditions =
                setdiff(
                    requested,
                    all_conditions
                )

            if !isempty(missing_conditions)

                Base.error(
                    "These conditions were not found in results: " *
                    join(missing_conditions, ", ")
                )
            end

            requested
        end


    condition_labels =
        pretty_condition_label.(
            conditions
        )


    metric_labels =
        [
            SEMANTIC_METRIC_LABELS[m]
            for m in metrics
        ]


    time_labels =
        [
            SEMANTIC_TIMEPOINT_LABELS[t]
            for t in SEMANTIC_TIMEPOINT_ORDER
        ]


    # ========================================================
    # A. TIMEPOINT
    # ========================================================

    if mode == :timepoint

        if timepoint === nothing

            Base.error(
                """
                mode = :timepoint requires timepoint.

                Example:
                    timepoint = (:pre, 50)

                or:
                    timepoint = (:post, 0)
                """
            )
        end


        tp =
            parse_semantic_timepoint(
                timepoint
            )


        df =
            results[
                results.timepoint .== tp,
                :
            ]


        if DataFrames.nrow(df) == 0

            Base.error(
                "No observations found for timepoint $tp."
            )
        end


        # rows    = conditions
        # columns = metrics

        means =
            zeros(
                Float64,
                length(conditions),
                length(metrics)
            )


        errors =
            zeros(
                Float64,
                length(conditions),
                length(metrics)
            )


        for (
            condition_i,
            condition
        ) in enumerate(conditions)


            condition_df =
                df[
                    df.condition .== condition,
                    :
                ]


            for (
                metric_i,
                metric
            ) in enumerate(metrics)


                values =
                    condition_df[
                        !,
                        metric
                    ]


                μ, err =
                    mean_and_error(
                        values;
                        error_type =
                            error_type
                    )


                means[
                    condition_i,
                    metric_i
                ] =
                    μ


                errors[
                    condition_i,
                    metric_i
                ] =
                    err
            end
        end


        # ----------------------------------------------------
        # Plot A1
        #
        # X = condition
        # Color = metric
        # ----------------------------------------------------

        p_condition =
            plot_grouped_bars_plotly(
                means,
                errors,
                condition_labels,
                metric_labels;

                xlabel =
                    "Condition",

                ylabel =
                    y_label,

                title =
                    SEMANTIC_TIMEPOINT_LABELS[tp],

                error_type =
                    error_type,

                fontfamily =
                    fontfamily,

                size =
                    size,

                xrotation =
                    15
            )
            
            # ----------------------------------------------------
            # Add individual observations
            # ----------------------------------------------------

            n_metrics =
                length(metrics)

            bar_width =
                0.8

            offsets =
                range(
                    -bar_width / 2,
                    bar_width / 2;
                    length = n_metrics + 2
                )[2:end-1]


            for (
                metric_i,
                metric
            ) in enumerate(metrics)

                for (
                    condition_i,
                    condition
                ) in enumerate(conditions)

                    condition_df =
                        df[
                            df.condition .== condition,
                            :
                        ]


                    values =
                        Float64.(
                            condition_df[
                                !,
                                metric
                            ]
                        )


                    valid =
                        isfinite.(values)

                    values =
                        values[valid]


                    x_values =
                        fill(
                            condition_i + offsets[metric_i],
                            length(values)
                        )


                    Plots.scatter!(
                        p_condition,
                        x_values,
                        values;

                        markersize =
                            4,

                        markerstrokewidth =
                            0,

                        alpha =
                            0.55,

                        label =
                            ""
                    )
                end
            end


        # ----------------------------------------------------
        # Plot A2
        #
        # X = metric
        # Color = condition
        # ----------------------------------------------------

        p_metric =
            plot_grouped_bars_plotly(
                permutedims(means),
                permutedims(errors),
                metric_labels,
                condition_labels;

                xlabel =
                    "Metric",

                ylabel =
                    y_label,

                title =
                    SEMANTIC_TIMEPOINT_LABELS[tp],

                error_type =
                    error_type,

                fontfamily =
                    fontfamily,

                size =
                    size,

                xrotation =
                    15
            )

            # ----------------------------------------------------
            # Add individual observations
            # ----------------------------------------------------

            n_conditions =
                length(conditions)

            bar_width =
                0.8

            offsets =
                range(
                    -bar_width / 2,
                    bar_width / 2;
                    length = n_conditions + 2
                )[2:end-1]


            for (
                condition_i,
                condition
            ) in enumerate(conditions)

                condition_df =
                    df[
                        df.condition .== condition,
                        :
                    ]


                for (
                    metric_i,
                    metric
                ) in enumerate(metrics)

                    values =
                        Float64.(
                            condition_df[
                                !,
                                metric
                            ]
                        )


                    valid =
                        isfinite.(values)

                    values =
                        values[valid]


                    x_values =
                        fill(
                            metric_i + offsets[condition_i],
                            length(values)
                        )


                    Plots.scatter!(
                        p_metric,
                        x_values,
                        values;

                        markersize =
                            4,

                        markerstrokewidth =
                            0,

                        alpha =
                            0.55,

                        label =
                            ""
                    )
                end
            end


        display(
            p_condition
        )

        display(
            p_metric
        )


        summary_table = DataFrames.DataFrame(
            condition = String[],
            metric = String[],
            mean = Float64[],
            error = Float64[],
            n = Int[]
        )

        for (i, condition) in enumerate(conditions)
            n = count(==(condition), df.condition)

            for (j, metric) in enumerate(metrics)
                push!(summary_table, (
                    condition,
                    String(metric),
                    means[i, j],
                    errors[i, j],
                    n
                ))
            end
        end


        return (
            condition_x = p_condition,
            metric_x = p_metric,
            summary_table = summary_table
        )
    end


    # ========================================================
    # B. METRIC
    #
    # One graph per metric
    #
    # X = time
    # Color = condition
    # ========================================================

    if mode == :metric

        plots =
            Dict{Symbol,Any}()


        for metric in metrics

            p =
                Plots.plot(
                    ;

                    xlabel =
                        "Time",

                    ylabel =
                        y_label,

                    title =
                        SEMANTIC_METRIC_LABELS[
                            metric
                        ],

                    xticks = (
                        1:10,
                        time_labels
                    ),

                    xrotation =
                        20,

                    legend =
                        :outertopright,

                    grid =
                        false,

                    framestyle =
                        :box,

                    fontfamily =
                        fontfamily,

                    size =
                        size,

                    tickfontsize =
                        12,

                    guidefontsize =
                        14,

                    titlefontsize =
                        17,

                    legendfontsize =
                        11
                )


            for (
                condition_i,
                condition
            ) in enumerate(conditions)


                means =
                    Float64[]

                errors =
                    Float64[]


                for tp in SEMANTIC_TIMEPOINT_ORDER

                    rows =
                        results[
                            (results.condition .== condition) .&
                            (results.timepoint .== tp),
                            :
                        ]


                    values =
                        rows[
                            !,
                            metric
                        ]


                    μ, err =
                        mean_and_error(
                            values;
                            error_type =
                                error_type
                        )


                    push!(
                        means,
                        μ
                    )


                    push!(
                        errors,
                        err
                    )
                end


                if error_type == :none

                    Plots.plot!(
                        p,
                        1:10,
                        means;

                        linewidth =
                            3,

                        marker =
                            :none,

                        label =
                            condition_labels[
                                condition_i
                            ]
                    )

                else

                    Plots.plot!(
                        p,
                        1:10,
                        means;

                        linewidth =
                            3,

                        marker =
                            :none,

                        ribbon =
                            errors,

                        fillalpha =
                            0.18,

                        label =
                            condition_labels[
                                condition_i
                            ]
                    )
                end
            end


            plots[
                metric
            ] =
                p


            display(
                p
            )
        end


        return plots
    end


    # ========================================================
    # C. CONDITION
    #
    # One graph per condition
    #
    # X = time
    # Color = metric
    # ========================================================

    if mode == :condition

        plots =
            Dict{String,Any}()


        for (
            condition_i,
            condition
        ) in enumerate(conditions)


            condition_df =
                results[
                    results.condition .== condition,
                    :
                ]


            p =
                Plots.plot(
                    ;

                    xlabel =
                        "Time",

                    ylabel =
                        y_label,

                    title =
                        condition_labels[
                            condition_i
                        ],

                    xticks = (
                        1:10,
                        time_labels
                    ),

                    xrotation =
                        20,

                    legend =
                        :outertopright,

                    grid =
                        false,

                    framestyle =
                        :box,

                    fontfamily =
                        fontfamily,

                    size =
                        size,

                    tickfontsize =
                        12,

                    guidefontsize =
                        14,

                    titlefontsize =
                        17,

                    legendfontsize =
                        11
                )


            for metric in metrics

                means =
                    Float64[]

                errors =
                    Float64[]


                for tp in SEMANTIC_TIMEPOINT_ORDER

                    rows =
                        condition_df[
                            condition_df.timepoint .== tp,
                            :
                        ]


                    values =
                        rows[
                            !,
                            metric
                        ]


                    μ, err =
                        mean_and_error(
                            values;
                            error_type =
                                error_type
                        )


                    push!(
                        means,
                        μ
                    )


                    push!(
                        errors,
                        err
                    )
                end


                if error_type == :none

                    Plots.plot!(
                        p,
                        1:10,
                        means;

                        linewidth =
                            3,

                        marker =
                            :none,

                        label =
                            SEMANTIC_METRIC_LABELS[
                                metric
                            ]
                    )

                else

                    Plots.plot!(
                        p,
                        1:10,
                        means;

                        linewidth =
                            3,

                        marker =
                            :none,

                        ribbon =
                            errors,

                        fillalpha =
                            0.18,

                        label =
                            SEMANTIC_METRIC_LABELS[
                                metric
                            ]
                    )
                end
            end


            plots[
                condition
            ] =
                p


            display(
                p
            )
        end


        return plots
    end
end
function plot_paired_metric_differences(
    results::DataFrames.DataFrame;

    timepoint,
    selected_conditions = nothing,
    use_z::Bool = true,
    error_type::Symbol = :sd,
    fontfamily::String = "Calibri",
    size = (1100, 650),
    jitter_width::Real = 0.08,
    point_alpha::Real = 0.55,
    point_size::Real = 4)

    if !(error_type in (
        :sd,
        :sem,
        :none
    ))

        Base.error(
            "error_type must be :sd, :sem, or :none."
        )
    end


    # ============================================================
    # SELECT METRICS
    # ============================================================

    comparison_metrics =
        if use_z

            [
                :mean_distance_from_others_z,
                :distance_from_mean_network_z,
                :column_normalized_distance_from_mean_z
            ]

        else

            [
                :mean_distance_from_others,
                :distance_from_mean_network,
                :column_normalized_distance_from_mean
            ]
        end

   reference_metric =
        use_z ?
        :word_degree_distance_from_mean_z :
        :word_degree_distance_from_mean

    metric_labels =
        [
            SEMANTIC_METRIC_LABELS[metric]
            for metric in comparison_metrics
        ]


    # ============================================================
    # TIMEPOINT
    # ============================================================

    tp =
        parse_semantic_timepoint(
            timepoint
        )


    df =
        results[
            results.timepoint .== tp,
            :
        ]


    if DataFrames.nrow(df) == 0

        Base.error(
            "No observations found for timepoint $tp."
        )
    end


    # ============================================================
    # CONDITIONS
    # ============================================================

    all_conditions =
        sort(
            unique(
                String.(
                    df.condition
                )
            )
        )


    conditions =
        if selected_conditions === nothing

            all_conditions

        else

            requested =
                String.(
                    selected_conditions
                )


            missing_conditions =
                setdiff(
                    requested,
                    all_conditions
                )


            if !isempty(missing_conditions)

                Base.error(
                    "These conditions were not found in results: " *
                    join(
                        missing_conditions,
                        ", "
                    )
                )
            end


            requested
        end


    condition_labels =
        pretty_condition_label.(
            conditions
        )


    # ============================================================
    # CALCULATE PAIRED DIFFERENCES
    #
    # For every observation:
    #
    # comparison metric - response-degree metric
    # ============================================================

    n_conditions =
        length(
            conditions
        )

    n_metrics =
        length(
            comparison_metrics
        )


    means =
        fill(
            NaN,
            n_conditions,
            n_metrics
        )


    errors =
        fill(
            NaN,
            n_conditions,
            n_metrics
        )


    paired_values =
        Dict{
            Tuple{Int,Int},
            Vector{Float64}
        }()


    for (
        condition_i,
        condition
    ) in enumerate(conditions)


        condition_df =
            df[
                df.condition .== condition,
                :
            ]


        reference_values =
            Float64.(
                condition_df[
                    !,
                    reference_metric
                ]
            )


        for (
            metric_i,
            metric
        ) in enumerate(comparison_metrics)


            metric_values =
                Float64.(
                    condition_df[
                        !,
                        metric
                    ]
                )


            valid =
                isfinite.(metric_values) .&
                isfinite.(reference_values)


            differences =
                metric_values[valid] .-
                reference_values[valid]


            paired_values[
                (
                    condition_i,
                    metric_i
                )
            ] =
                differences


            if isempty(differences)

                continue
            end


            means[
                condition_i,
                metric_i
            ] =
                Statistics.mean(
                    differences
                )


            if error_type == :sd

                errors[
                    condition_i,
                    metric_i
                ] =
                    length(differences) > 1 ?
                    Statistics.std(
                        differences
                    ) :
                    0.0


            elseif error_type == :sem

                errors[
                    condition_i,
                    metric_i
                ] =
                    length(differences) > 1 ?
                    Statistics.std(
                        differences
                    ) /
                    sqrt(
                        length(differences)
                    ) :
                    0.0


            else

                errors[
                    condition_i,
                    metric_i
                ] =
                    0.0
            end
        end
    end


    # ============================================================
    # GROUPED BAR PLOT
    # ============================================================

    p =
        plot_grouped_bars_plotly(
            means,
            errors,
            condition_labels,
            metric_labels;

            xlabel =
                "Condition",

            ylabel =
                use_z ?
                "Paired Difference in Distance (z)" :
                "Paired Difference in Distance",

            title =
                SEMANTIC_TIMEPOINT_LABELS[
                    tp
                ],

            error_type =
                error_type,

            fontfamily =
                fontfamily,

            size =
                size,

            xrotation =
                15
        )


    # ============================================================
    # ADD INDIVIDUAL PAIRED-DIFFERENCE POINTS
    # ============================================================

    bar_width =
        0.8


    offsets =
        range(
            -bar_width / 2,
            bar_width / 2;
            length =
                n_metrics + 2
        )[2:end-1]


    for condition_i in 1:n_conditions

        for metric_i in 1:n_metrics

            values =
                paired_values[
                    (
                        condition_i,
                        metric_i
                    )
                ]


            isempty(values) &&
                continue


            base_x =
                condition_i +
                offsets[
                    metric_i
                ]


            jitter =
                (
                    Random.rand(
                        length(values)
                    ) .-
                    0.5
                ) .*
                2 *
                jitter_width


            x_values =
                base_x .+
                jitter


            Plots.scatter!(
                p,
                x_values,
                values;

                markersize =
                    point_size,

                markerstrokewidth =
                    0,

                alpha =
                    point_alpha,

                label =
                    ""
            )
        end
    end


    # ============================================================
    # ZERO LINE
    # ============================================================

    Plots.hline!(
        p,
        [0.0];

        linestyle =
            :dash,

        linewidth =
            1.5,

        label =
            ""
    )


    Plots.display(
        p
    )


    return p
end

