function build_or_update_all_agents_semantic_metrics_crossing_final(
    bank_dir::String = "new_semantic_network_bank";
    output_filename::String = "all_agents_semantic_metrics.jld2",
    selected_conditions = [
        "homophily_0_learning1_0_9",
        "homophily_3_learning1_0_9",
        "homophily_0_learning1_0_5",
        "homophily_3_learning1_0_5"
    ],
    expected_runs::Int = 150,
    expected_agents::Int = 20,
    verbose::Bool = true)

    conditions = String.(selected_conditions)
    timepoints = ("crossing", "final")

    metric_names = [
        :mean_distance_from_others,
        :distance_from_mean_network,
        :column_normalized_distance_from_mean,
        :word_degree_distance_from_mean
    ]

    metric_columns = vcat(
        metric_names,
        Symbol.(string.(metric_names) .* "_z")
    )

    id_columns = [
        :condition,
        :run_number,
        :agent,
        :timepoint
    ]

    required_columns = vcat(id_columns, metric_columns)

    output_path = joinpath(bank_dir, output_filename)

    # --------------------------------------------------------
    # 1. Load existing file or initialize an empty DataFrame
    # --------------------------------------------------------

    if isfile(output_path)

        data = DataFrames.DataFrame(
            JLD2.load(output_path, "data")
        )

        verbose && println(
            "Existing file loaded: ", output_path
        )

    else

        data = DataFrames.DataFrame(
            condition = String[],
            run_number = Int[],
            agent = Int[],
            timepoint = String[]
        )

        for col in metric_columns
            data[!, col] = Float64[]
        end

        verbose && println(
            "No existing file found. Creating: ", output_path
        )
    end

    # Add missing metric columns to older files.
    for col in metric_columns

        if !(col in propertynames(data))
            data[!, col] = fill(NaN, DataFrames.nrow(data))
        else
            data[!, col] = [
                ismissing(x) ? NaN : Float64(x)
                for x in data[!, col]
            ]
        end
    end

    for col in id_columns
        col in propertynames(data) ||
            error("Missing identifier column: $col")
    end

    # Preserve unrelated existing columns.
    extra_columns = setdiff(
        propertynames(data),
        required_columns
    )

    for col in extra_columns
        DataFrames.allowmissing!(data, col)
    end

    # --------------------------------------------------------
    # 2. Find simulation files
    # --------------------------------------------------------

    simulation_files = sort(filter(
        f -> occursin(r"_run_\d+\.jld2$", f) &&
             any(c -> startswith(f, c * "_run_"), conditions),
        readdir(bank_dir)
    ))

    for condition in conditions

        condition_files = filter(
            f -> startswith(f, condition * "_run_"),
            simulation_files
        )

        run_numbers = Int[]

        for f in condition_files

            m = match(r"_run_(\d+)\.jld2$", f)

            push!(
                run_numbers,
                parse(Int, m.captures[1])
            )
        end

        length(run_numbers) == expected_runs ||
            error(
                "$condition: expected $expected_runs runs, " *
                "found $(length(run_numbers))."
            )

        length(unique(run_numbers)) == expected_runs ||
            error("Duplicate run numbers for $condition")
    end

    # --------------------------------------------------------
    # 3. Check existing identifiers
    # --------------------------------------------------------

    keys = [
        (
            String(row.condition),
            Int(row.run_number),
            String(row.timepoint),
            Int(row.agent)
        )
        for row in eachrow(data)
    ]

    length(keys) == length(unique(keys)) ||
        error("Duplicate condition/run/timepoint/agent rows found.")

    # --------------------------------------------------------
    # 4. Process missing or incomplete simulations
    # --------------------------------------------------------

    updated = 0
    skipped = 0

    total_files = length(simulation_files)

    for (file_i, simulation_file) in enumerate(simulation_files)

        m = match(
            r"^(.*)_run_(\d+)\.jld2$",
            simulation_file
        )

        condition = String(m.captures[1])
        run_number = parse(Int, m.captures[2])

        run_mask =
            (data.condition .== condition) .&
            (data.run_number .== run_number)

        existing = data[run_mask, :]

        complete =
            DataFrames.nrow(existing) ==
            expected_agents * length(timepoints)

        if complete

            for tp in timepoints

                subset = existing[
                    existing.timepoint .== tp,
                    :
                ]

                if sort(Int.(subset.agent)) !=
                   collect(1:expected_agents)

                    complete = false
                    break
                end

                for col in metric_columns

                    if !all(isfinite, subset[!, col])
                        complete = false
                        break
                    end
                end

                complete || break
            end
        end

        if complete

            skipped += 1

            verbose && println(
                "[$file_i/$total_files] SKIP: ",
                simulation_file
            )

            continue
        end

        verbose && println(
            "[$file_i/$total_files] ANALYZE: ",
            simulation_file
        )

        simulation_path = joinpath(
            bank_dir,
            simulation_file
        )

        d = JLD2.load(simulation_path)

        metadata = d["metadata"]
        networks = d["networks"]
        saved_steps = Int.(d["saved_steps"])

        String(metadata.condition) == condition ||
            error("Condition mismatch in $simulation_file")

        Int(metadata.run_number) == run_number ||
            error("Run number mismatch in $simulation_file")

        target_steps = (
            ("crossing", Int(metadata.crossing_step)),
            ("final", Int(metadata.steps))
        )

        new_rows = DataFrames.DataFrame(
            condition = String[],
            run_number = Int[],
            agent = Int[],
            timepoint = String[]
        )

        for col in metric_columns
            new_rows[!, col] = Float64[]
        end

        for (tp, target_step) in target_steps

            idx = findfirst(
                ==(target_step),
                saved_steps
            )

            idx === nothing &&
                error(
                    "Step $target_step missing in $simulation_file"
                )

            agents = networks[:, :, :, idx]

            size(agents, 3) == expected_agents ||
                error(
                    "Unexpected agent count in $simulation_file"
                )

            # Uses the four existing metric definitions.
            metrics = calculate_all_semantic_metrics(agents)

            for agent in 1:expected_agents

                row = Dict{Symbol,Any}(
                    :condition => condition,
                    :run_number => run_number,
                    :agent => agent,
                    :timepoint => tp
                )

                for col in metric_columns
                    row[col] = Float64(
                        getproperty(metrics, col)[agent]
                    )
                end

                push!(new_rows, row)
            end
        end

        for col in metric_columns

            all(isfinite, new_rows[!, col]) ||
                error(
                    "Non-finite values for $col in $simulation_file"
                )
        end

        # Preserve unrelated columns for existing rows.
        old_lookup = Dict(
            (String(row.timepoint), Int(row.agent)) => row
            for row in eachrow(existing)
        )

        for col in extra_columns

            T = eltype(data[!, col])

            new_rows[!, col] = Vector{T}(
                missing,
                DataFrames.nrow(new_rows)
            )

            for row in eachrow(new_rows)

                key = (
                    String(row.timepoint),
                    Int(row.agent)
                )

                if haskey(old_lookup, key)
                    row[col] = old_lookup[key][col]
                end
            end
        end

        # Replace this run's existing rows.
        data = data[.!run_mask, :]

        DataFrames.append!(
            data,
            new_rows[:, propertynames(data)];
            cols = :setequal
        )

        # Save progress after every completed run.
        temp_path = output_path * ".tmp"

        JLD2.jldsave(
            temp_path;
            data = data
        )

        Base.mv(
            temp_path,
            output_path;
            force = true
        )

        updated += 1
    end

    # --------------------------------------------------------
    # 5. Final validation
    # --------------------------------------------------------

    expected_rows =
        length(conditions) *
        expected_runs *
        length(timepoints) *
        expected_agents

    selected_data = data[
        in.(data.condition, Ref(Set(conditions))),
        :
    ]

    DataFrames.nrow(selected_data) == expected_rows ||
        error(
            "Expected $expected_rows rows, " *
            "found $(DataFrames.nrow(selected_data))."
        )

    for condition in conditions

        condition_data = selected_data[
            selected_data.condition .== condition,
            :
        ]

        runs = unique(condition_data.run_number)

        length(runs) == expected_runs ||
            error("Incomplete condition: $condition")

        for run_number in runs

            run_data = condition_data[
                condition_data.run_number .== run_number,
                :
            ]

            for tp in timepoints

                subset = run_data[
                    run_data.timepoint .== tp,
                    :
                ]

                sort(Int.(subset.agent)) ==
                    collect(1:expected_agents) ||
                    error(
                        "Incomplete agents: $condition, " *
                        "run $run_number, $tp"
                    )

                for col in metric_columns

                    all(isfinite, subset[!, col]) ||
                        error(
                            "Invalid $col: $condition, " *
                            "run $run_number, $tp"
                        )
                end
            end
        end
    end

    DataFrames.sort!(
        data,
        [:condition, :run_number, :timepoint, :agent]
    )

    temp_path = output_path * ".tmp"

    JLD2.jldsave(
        temp_path;
        data = data
    )

    Base.mv(
        temp_path,
        output_path;
        force = true
    )

    println()
    println("Analysis complete.")
    println("Updated runs: ", updated)
    println("Already complete: ", skipped)
    println("Total rows: ", DataFrames.nrow(selected_data))
    println("Saved to: ", output_path)

    return data
end
# all_agents_data = build_or_update_all_agents_semantic_metrics(
#     "new_semantic_network_bank";
#     output_filename = "all_agents_semantic_metrics_crossing_final.jld2"
# )


function analyze_semantic_metric_pairs(
    data_path::String,
    metric_pairs::AbstractVector;
    selected_conditions = [
        "homophily_0_learning1_0_9",
        "homophily_3_learning1_0_9",
        "homophily_0_learning1_0_5",
        "homophily_3_learning1_0_5"
    ],
    scale::Symbol = :both,
    difference_type::Symbol = :both,
    correlation_method::Symbol = :both,
    fontfamily::String = "Calibri",
    plot_size = (1600, 650),
    point_alpha::Real = 0.25,
    point_size::Real = 3,
    show_plots::Bool = true,
    verbose::Bool = true)

    scale in (:raw, :z, :both) ||
        error("scale must be :raw, :z or :both")

    difference_type in (:signed, :absolute, :both) ||
        error("difference_type must be :signed, :absolute or :both")

    correlation_method in (:pooled, :fisher, :both) ||
        error("correlation_method must be :pooled, :fisher or :both")

    data = DataFrames.DataFrame(
        JLD2.load(data_path, "data")
    )

    function validate_semantic_metrics_data(
        data::DataFrames.DataFrame;
        selected_conditions,
        expected_runs::Int = 150,
        expected_agents::Int = 20)

        conditions = String.(selected_conditions)

        metrics = [
            :mean_distance_from_others,
            :distance_from_mean_network,
            :column_normalized_distance_from_mean,
            :word_degree_distance_from_mean
        ]

        metric_columns = vcat(
            metrics,
            Symbol.(string.(metrics) .* "_z")
        )

        required_columns = vcat(
            [:condition, :run_number, :agent, :timepoint],
            metric_columns
        )

        for col in required_columns
            col in propertynames(data) ||
                error("Missing column: $col")
        end

        expected_timepoints = Set(["crossing", "final"])
        expected_agent_ids = collect(1:expected_agents)

        # Check that there are no unexpected conditions.
        actual_conditions = Set(String.(data.condition))

        actual_conditions == Set(conditions) ||
            error(
                "Condition mismatch. Expected: $(conditions), " *
                "found: $(collect(actual_conditions))"
            )

        for condition in conditions

            condition_data = data[
                String.(data.condition) .== condition,
                :
            ]

            runs = unique(Int.(condition_data.run_number))

            length(runs) == expected_runs ||
                error(
                    "$condition: expected $expected_runs runs, " *
                    "found $(length(runs))"
                )

            for run_number in sort(runs)

                run_data = condition_data[
                    condition_data.run_number .== run_number,
                    :
                ]

                # Exactly 20 agents × 2 timepoints.
                DataFrames.nrow(run_data) == 2 * expected_agents ||
                    error(
                        "$condition, run $run_number: " *
                        "expected $(2 * expected_agents) rows, " *
                        "found $(DataFrames.nrow(run_data))"
                    )

                for tp in expected_timepoints

                    tp_data = run_data[
                        String.(run_data.timepoint) .== tp,
                        :
                    ]

                    agents = Int.(tp_data.agent)

                    sort(agents) == expected_agent_ids ||
                        error(
                            "$condition, run $run_number, $tp: " *
                            "expected agents 1:$expected_agents " *
                            "exactly once"
                        )

                    for col in metric_columns

                        values = tp_data[!, col]

                        all(
                            x -> !ismissing(x) &&
                                x isa Real &&
                                isfinite(x),
                            values
                        ) ||
                            error(
                                "$condition, run $run_number, $tp: " *
                                "missing or invalid values in $col"
                            )
                    end
                end

                actual_timepoints = Set(
                    String.(run_data.timepoint)
                )

                actual_timepoints == expected_timepoints ||
                    error(
                        "$condition, run $run_number: " *
                        "unexpected timepoints: $actual_timepoints"
                    )
            end
        end

        println(
            "Data validation passed: ",
            length(conditions), " conditions × ",
            expected_runs, " runs × ",
            expected_agents, " agents × 2 timepoints."
        )

        return true
    end

    conditions = String.(selected_conditions)

    available_metrics = Set([
        :mean_distance_from_others,
        :distance_from_mean_network,
        :column_normalized_distance_from_mean,
        :word_degree_distance_from_mean
    ])

    for col in (:condition, :run_number, :agent, :timepoint)
        col in propertynames(data) ||
            error("Missing column: $col")
    end

    missing_conditions = setdiff(
        conditions,
        unique(String.(data.condition))
    )

    isempty(missing_conditions) ||
        error("Missing conditions: $missing_conditions")

    data = data[
        in.(String.(data.condition), Ref(Set(conditions))),
        :
    ]

    validate_semantic_metrics_data(
        data;
        selected_conditions = conditions,
        expected_runs = 150,
        expected_agents = 20
    )

    comparisons = NamedTuple[]

    for pair in metric_pairs

        length(pair) == 2 ||
            error("Each pair must contain exactly two metrics.")

        x = Symbol(pair[1])
        y = Symbol(pair[2])

        x in available_metrics || error("Unknown metric: $x")
        y in available_metrics || error("Unknown metric: $y")
        x != y || error("Cannot compare a metric with itself.")

        x_z = Symbol("$(x)_z")
        y_z = Symbol("$(y)_z")

        for col in (x, y, x_z, y_z)
            col in propertynames(data) ||
                error("Missing column: $col")
        end

        push!(comparisons, (
            name = "$(y) vs. $(x)",
            x = x,
            y = y,
            x_z = x_z,
            y_z = y_z
        ))
    end

    scales = scale == :both ? (:raw, :z) : (scale,)

    difference_types = difference_type == :both ?
        (:signed, :absolute) : (difference_type,)

    correlation_methods = correlation_method == :both ?
        (:pooled, :fisher) : (correlation_method,)

    # ========================================================
    # Helpers
    # ========================================================

    function describe_values(values)

        v = filter(isfinite, Float64.(values))
        n = length(v)

        n > 0 || error("No finite observations.")

        μ = Statistics.mean(v)
        med = Statistics.median(v)

        sd = n > 1 ? Statistics.std(v) : NaN
        sem = n > 1 ? sd / sqrt(n) : NaN

        tcrit = n > 1 ?
            Distributions.quantile(
                Distributions.TDist(n - 1), 0.975
            ) : NaN

        return (
            n = n,
            mean = μ,
            median = med,
            sd = sd,
            sem = sem,
            ci_low = μ - tcrit * sem,
            ci_high = μ + tcrit * sem,
            minimum = minimum(v),
            maximum = maximum(v),
            iqr = Statistics.quantile(v, 0.75) -
                  Statistics.quantile(v, 0.25)
        )
    end

    function pearson_r(x, y)

        length(x) >= 3 || return NaN

        sx = Statistics.std(x)
        sy = Statistics.std(y)

        (isfinite(sx) && isfinite(sy) &&
         sx > 0 && sy > 0) || return NaN

        return Statistics.cor(x, y)
    end

    function pooled_regression(x, y)

        r = pearson_r(x, y)
        n = length(x)

        if !isfinite(r)
            return (
                r = NaN,
                p = NaN,
                intercept = NaN,
                slope = NaN,
                r_squared = NaN
            )
        end

        model = GLM.lm(
            hcat(ones(n), Float64.(x)),
            Float64.(y)
        )

        coefficients = GLM.coef(model)

        t = abs(r) * sqrt(
            (n - 2) / max(1 - r^2, eps())
        )

        p = 2 * Distributions.ccdf(
            Distributions.TDist(n - 2),
            t
        )

        return (
            r = r,
            p = p,
            intercept = coefficients[1],
            slope = coefficients[2],
            r_squared = r^2
        )
    end

    function run_correlations(df, x_col, y_col)

        grouped = DataFrames.groupby(
            df,
            [:condition, :run_number]
        )

        rows = DataFrames.DataFrame(
            condition = String[],
            run_number = Int[],
            n_agents = Int[],
            r = Float64[],
            fisher_z = Float64[]
        )

        for g in grouped

            x = Float64.(g[!, x_col])
            y = Float64.(g[!, y_col])

            valid = isfinite.(x) .& isfinite.(y)

            x = x[valid]
            y = y[valid]

            r = pearson_r(x, y)

            z = isfinite(r) ?
                atanh(clamp(r, -1 + 1e-12, 1 - 1e-12)) :
                NaN

            push!(rows, (
                String(g.condition[1]),
                Int(g.run_number[1]),
                length(x),
                r,
                z
            ))
        end

        return rows
    end

    function pretty_label(condition)

        h = occursin("homophily_3_", condition) ?
            "H = 3" : "H = 0"

        l = occursin("learning1_0_9", condition) ?
            "L = 0.9" : "L = 0.5"

        return "$h, $l"
    end

    # ========================================================
    # Output tables
    # ========================================================

    correlations = DataFrames.DataFrame(
        comparison = String[],
        timepoint = String[],
        scale = String[],
        method = String[],
        condition = String[],
        n_agents = Int[],
        n_runs = Int[],
        r = Float64[],
        p = Float64[],
        ci_low = Float64[],
        ci_high = Float64[],
        sd_r = Float64[],
        sem_r = Float64[],
        sd_fisher_z = Float64[],
        sem_fisher_z = Float64[],
        mean_fisher_z = Float64[],
        mean_run_r = Float64[],
        median_run_r = Float64[],
        min_run_r = Float64[],
        max_run_r = Float64[],
        iqr_run_r = Float64[],
        x_mean = Float64[],
        x_sd = Float64[],
        y_mean = Float64[],
        y_sd = Float64[],
        intercept = Float64[],
        slope = Float64[],
        r_squared = Float64[]
    )

    differences = DataFrames.DataFrame(
        comparison = String[],
        timepoint = String[],
        scale = String[],
        condition = String[],
        difference_type = String[],
        n_agents = Int[],
        n_runs = Int[],
        mean = Float64[],
        median = Float64[],
        sd = Float64[],
        sem = Float64[],
        ci_low = Float64[],
        ci_high = Float64[],
        minimum = Float64[],
        maximum = Float64[],
        iqr = Float64[],
        mean_of_run_means = Float64[],
        sd_of_run_means = Float64[],
        sem_of_run_means = Float64[],
        run_mean_ci_low = Float64[],
        run_mean_ci_high = Float64[],
        mean_within_run_sd = Float64[],
        sd_within_run_sd = Float64[],
        sem_within_run_sd = Float64[]
    )

    extreme_agreement = DataFrames.DataFrame(
        comparison = String[],
        timepoint = String[],
        condition = String[],
        matching_runs = Int[],
        total_runs = Int[],
        percentage = Float64[],
        x_tie_runs = Int[],
        x_tie_percentage = Float64[],
        y_tie_runs = Int[],
        y_tie_percentage = Float64[],
        either_tie_runs = Int[],
        either_tie_percentage = Float64[],
        both_tie_runs = Int[],
        both_tie_percentage = Float64[]
    )

    run_correlation_details = DataFrames.DataFrame(
        comparison = String[],
        timepoint = String[],
        scale = String[],
        condition = String[],
        run_number = Int[],
        n_agents = Int[],
        r = Float64[],
        fisher_z = Float64[]
    )

    run_correlation_summary = DataFrames.DataFrame(
        comparison = String[],
        timepoint = String[],
        scale = String[],
        condition = String[],
        n_runs = Int[],
        mean_r_arithmetic = Float64[],
        median_r = Float64[],
        sd_r = Float64[],
        sem_r = Float64[],
        arithmetic_ci_low = Float64[],
        arithmetic_ci_high = Float64[],
        mean_r_fisher = Float64[],
        mean_fisher_z = Float64[],
        sd_fisher_z = Float64[],
        sem_fisher_z = Float64[],
        fisher_ci_low = Float64[],
        fisher_ci_high = Float64[]
    )

    plots = Dict{Tuple{String,String},Any}()

    palette = Plots.palette(
        :default,
        length(conditions)
    )

    # ========================================================
    # Main analysis
    # ========================================================

    for (comparison_i, comparison) in enumerate(comparisons)

        verbose && println(
            "\n[$comparison_i/$(length(comparisons))] ",
            comparison.name
        )

        for tp in ("crossing", "final")

            df_time = data[
                String.(data.timepoint) .== tp,
                :
            ]

            panels = []

            for current_scale in scales

                x_col = current_scale == :raw ?
                    comparison.x : comparison.x_z

                y_col = current_scale == :raw ?
                    comparison.y : comparison.y_z

                # --------------------------------------------
                # Numerical analyses
                # --------------------------------------------

                for condition in vcat(["ALL"], conditions)

                    df = condition == "ALL" ?
                        df_time :
                        df_time[
                            df_time.condition .== condition,
                            :
                        ]

                    x = Float64.(df[!, x_col])
                    y = Float64.(df[!, y_col])

                    valid = isfinite.(x) .& isfinite.(y)

                    all(valid) ||
                        error(
                            "Non-finite values in $(comparison.name), " *
                            "$tp, $current_scale, $condition"
                        )

                    x_stats = describe_values(x)
                    y_stats = describe_values(y)

                    run_df = run_correlations(
                        df, x_col, y_col
                    )

                    for row in eachrow(run_df)

                        push!(run_correlation_details, (
                            comparison.name,
                            tp,
                            string(current_scale),
                            String(row.condition),
                            Int(row.run_number),
                            Int(row.n_agents),
                            Float64(row.r),
                            Float64(row.fisher_z)
                        ))
                    end

                    valid_runs = run_df[
                        isfinite.(run_df.fisher_z),
                        :
                    ]

                    DataFrames.nrow(valid_runs) >= 2 ||
                        error(
                            "Too few valid run correlations: " *
                            "$(comparison.name), $tp, $condition"
                        )

                    r_stats = describe_values(valid_runs.r)
                    z_stats = describe_values(valid_runs.fisher_z)

                    mean_r_fisher = tanh(z_stats.mean)

                    fisher_ci_low = tanh(z_stats.ci_low)
                    fisher_ci_high = tanh(z_stats.ci_high)

                    push!(run_correlation_summary, (
                        comparison.name,
                        tp,
                        string(current_scale),
                        condition,
                        r_stats.n,
                        r_stats.mean,
                        r_stats.median,
                        r_stats.sd,
                        r_stats.sem,
                        r_stats.ci_low,
                        r_stats.ci_high,
                        mean_r_fisher,
                        z_stats.mean,
                        z_stats.sd,
                        z_stats.sem,
                        fisher_ci_low,
                        fisher_ci_high
                    ))

                    reg = pooled_regression(x, y)

                    for method in correlation_methods

                        if method == :pooled

                            n = length(x)

                            z = atanh(clamp(
                                reg.r,
                                -1 + 1e-12,
                                1 - 1e-12
                            ))

                            ci_low = tanh(
                                z - 1.96 / sqrt(n - 3)
                            )

                            ci_high = tanh(
                                z + 1.96 / sqrt(n - 3)
                            )

                            push!(correlations, (
                                comparison.name,
                                tp,
                                string(current_scale),
                                "pooled",
                                condition,
                                n,
                                DataFrames.nrow(run_df),
                                reg.r,
                                reg.p,
                                ci_low,
                                ci_high,
                                r_stats.sd,
                                r_stats.sem,
                                z_stats.sd,
                                z_stats.sem,
                                z_stats.mean,
                                r_stats.mean,
                                r_stats.median,
                                r_stats.minimum,
                                r_stats.maximum,
                                r_stats.iqr,
                                x_stats.mean,
                                x_stats.sd,
                                y_stats.mean,
                                y_stats.sd,
                                reg.intercept,
                                reg.slope,
                                reg.r_squared
                            ))

                        else

                            t = z_stats.mean / z_stats.sem

                            p = z_stats.sem > 0 ?
                                2 * Distributions.ccdf(
                                    Distributions.TDist(z_stats.n - 1),
                                    abs(t)
                                ) :
                                (z_stats.mean == 0 ? 1.0 : 0.0)

                            push!(correlations, (
                                comparison.name,
                                tp,
                                string(current_scale),
                                "fisher",
                                condition,
                                length(x),
                                z_stats.n,
                                mean_r_fisher,
                                p,
                                fisher_ci_low,
                                fisher_ci_high,
                                r_stats.sd,
                                r_stats.sem,
                                z_stats.sd,
                                z_stats.sem,
                                z_stats.mean,
                                r_stats.mean,
                                r_stats.median,
                                r_stats.minimum,
                                r_stats.maximum,
                                r_stats.iqr,
                                x_stats.mean,
                                x_stats.sd,
                                y_stats.mean,
                                y_stats.sd,
                                NaN,
                                NaN,
                                NaN
                            ))
                        end
                    end

                    # ----------------------------------------
                    # Differences
                    # ----------------------------------------

                    for dt in difference_types

                        values = dt == :signed ?
                            y .- x :
                            abs.(y .- x)

                        stats = describe_values(values)

                        df_diff = DataFrames.DataFrame(
                            condition = String.(df.condition),
                            run_number = Int.(df.run_number),
                            difference = values
                        )

                        grouped = DataFrames.groupby(
                            df_diff,
                            [:condition, :run_number]
                        )

                        run_means = [
                            Statistics.mean(g.difference)
                            for g in grouped
                        ]

                        run_sds = [
                            Statistics.std(g.difference)
                            for g in grouped
                        ]

                        run_stats = describe_values(run_means)
                        within_sd_stats = describe_values(run_sds)

                        push!(differences, (
                            comparison.name,
                            tp,
                            string(current_scale),
                            condition,
                            string(dt),
                            stats.n,
                            run_stats.n,
                            stats.mean,
                            stats.median,
                            stats.sd,
                            stats.sem,
                            stats.ci_low,
                            stats.ci_high,
                            stats.minimum,
                            stats.maximum,
                            stats.iqr,
                            run_stats.mean,
                            run_stats.sd,
                            run_stats.sem,
                            run_stats.ci_low,
                            run_stats.ci_high,
                            within_sd_stats.mean,
                            within_sd_stats.sd,
                            within_sd_stats.sem
                        ))
                    end
                end

                # --------------------------------------------
                # Scatter plot
                # --------------------------------------------

                p = Plots.plot(
                    xlabel = replace(string(x_col), "_" => " "),
                    ylabel = replace(string(y_col), "_" => " "),
                    title = current_scale == :raw ?
                        "Raw values" : "Z-scores",
                    fontfamily = fontfamily,
                    legend = :outertopright,
                    framestyle = :box,
                    grid = false,
                    tickfontsize = 11,
                    guidefontsize = 13,
                    titlefontsize = 15
                )

                for (i, condition) in enumerate(conditions)

                    df = df_time[
                        df_time.condition .== condition,
                        :
                    ]

                    x = Float64.(df[!, x_col])
                    y = Float64.(df[!, y_col])

                    color = palette[i]

                    Plots.scatter!(
                        p,
                        x,
                        y;
                        color = color,
                        alpha = point_alpha,
                        markersize = point_size,
                        markerstrokewidth = 0,
                        label = pretty_label(condition)
                    )

                    reg = pooled_regression(x, y)

                    if isfinite(reg.slope)

                        xx = range(
                            minimum(x),
                            maximum(x);
                            length = 100
                        )

                        Plots.plot!(
                            p,
                            xx,
                            reg.intercept .+ reg.slope .* xx;
                            color = color,
                            linewidth = 2.5,
                            label = ""
                        )
                    end
                end

                x_all = Float64.(df_time[!, x_col])
                y_all = Float64.(df_time[!, y_col])

                reg_all = pooled_regression(x_all, y_all)

                if isfinite(reg_all.slope)

                    xx = range(
                        minimum(x_all),
                        maximum(x_all);
                        length = 100
                    )

                    Plots.plot!(
                        p,
                        xx,
                        reg_all.intercept .+ reg_all.slope .* xx;
                        color = :black,
                        linewidth = 3.5,
                        linestyle = :dash,
                        label = "Overall regression"
                    )
                end

                push!(panels, p)
            end

            # --------------------------------------------
            # Extreme-agent agreement and ties
            # --------------------------------------------

            for condition in vcat(["ALL"], conditions)

                df = condition == "ALL" ?
                    df_time :
                    df_time[
                        df_time.condition .== condition,
                        :
                    ]

                grouped = DataFrames.groupby(
                    df,
                    [:condition, :run_number]
                )

                matching = 0
                x_ties = 0
                y_ties = 0
                either_ties = 0
                both_ties = 0

                for g in grouped

                    x = Float64.(g[!, comparison.x])
                    y = Float64.(g[!, comparison.y])

                    x_max = maximum(x)
                    y_max = maximum(y)

                    x_is_max = x .== x_max
                    y_is_max = y .== y_max

                    x_tie = count(x_is_max) > 1
                    y_tie = count(y_is_max) > 1

                    matching += Int(any(x_is_max .& y_is_max))
                    x_ties += Int(x_tie)
                    y_ties += Int(y_tie)
                    either_ties += Int(x_tie || y_tie)
                    both_ties += Int(x_tie && y_tie)
                end

                total = length(grouped)

                push!(extreme_agreement, (
                    comparison.name,
                    tp,
                    condition,
                    matching,
                    total,
                    100 * matching / total,
                    x_ties,
                    100 * x_ties / total,
                    y_ties,
                    100 * y_ties / total,
                    either_ties,
                    100 * either_ties / total,
                    both_ties,
                    100 * both_ties / total
                ))
            end

            # --------------------------------------------
            # Combined plot
            # --------------------------------------------

            combined = Plots.plot(
                panels...;
                layout = (1, length(panels)),
                size = length(panels) == 1 ?
                    (plot_size[1] ÷ 2, plot_size[2]) :
                    plot_size,
                plot_title = tp == "crossing" ?
                    "Crossing step" : "Final step"
            )

            plots[(comparison.name, tp)] = combined

            show_plots && display(combined)

            # --------------------------------------------
            # Print results
            # --------------------------------------------

            if verbose

                println("\n", "="^100)
                println(comparison.name, " — ", uppercase(tp))
                println("="^100)

                for current_scale in scales

                    println("\nSCALE: ", uppercase(string(current_scale)))

                    for method in correlation_methods

                        println(
                            "\nCORRELATIONS — ",
                            uppercase(string(method))
                        )

                        t = correlations[
                            (correlations.comparison .== comparison.name) .&
                            (correlations.timepoint .== tp) .&
                            (correlations.scale .== string(current_scale)) .&
                            (correlations.method .== string(method)),
                            :
                        ]

                        Base.show(
                            stdout,
                            MIME("text/plain"),
                            t;
                            allrows = true,
                            allcols = true,
                            truncate = 0
                        )

                        println()
                    end

                    println("\nRUN-LEVEL CORRELATION SUMMARY")

                    t = run_correlation_summary[
                        (run_correlation_summary.comparison .== comparison.name) .&
                        (run_correlation_summary.timepoint .== tp) .&
                        (run_correlation_summary.scale .== string(current_scale)),
                        :
                    ]

                    Base.show(
                        stdout,
                        MIME("text/plain"),
                        t;
                        allrows = true,
                        allcols = true,
                        truncate = 0
                    )

                    println()

                    for dt in difference_types

                        println(
                            "\nDIFFERENCES — ",
                            uppercase(string(dt))
                        )

                        t = differences[
                            (differences.comparison .== comparison.name) .&
                            (differences.timepoint .== tp) .&
                            (differences.scale .== string(current_scale)) .&
                            (differences.difference_type .== string(dt)),
                            :
                        ]

                        Base.show(
                            stdout,
                            MIME("text/plain"),
                            t;
                            allrows = true,
                            allcols = true,
                            truncate = 0
                        )

                        println()
                    end
                end

                println("\nMOST EXTREME AGENT AGREEMENT AND TIES")

                t = extreme_agreement[
                    (extreme_agreement.comparison .== comparison.name) .&
                    (extreme_agreement.timepoint .== tp),
                    :
                ]

                Base.show(
                    stdout,
                    MIME("text/plain"),
                    t;
                    allrows = true,
                    allcols = true,
                    truncate = 0
                )

                println()
            end
        end
    end

    # ========================================================
    # Publication summary: alternative semantic metrics
    # compared with Mean Pairwise TVD
    # ========================================================

    publication_summary = DataFrames.DataFrame(
        Metric = String[],
        Timepoint = String[],
        Mean_Pearson_r = String[],
        Mean_absolute_Δz = String[],
        Extreme_agent_agreement = String[]
    )

    if correlation_method in (:fisher, :both)

        original_metric = :mean_distance_from_others

        alternative_metrics = [
            (
                :distance_from_mean_network,
                "Global TVD"
            ),
            (
                :column_normalized_distance_from_mean,
                "Column-normalized TVD"
            ),
            (
                :word_degree_distance_from_mean,
                "Word-degree TVD"
            )
        ]

        for (alternative_metric, metric_label) in alternative_metrics

            # The comparison name depends on the order
            # in which the pair was supplied.
            matching_comparison = findfirst(
                c -> Set((c.x, c.y)) ==
                     Set((original_metric, alternative_metric)),
                comparisons
            )

            matching_comparison === nothing &&
                error(
                    "Missing comparison between " *
                    "$original_metric and $alternative_metric. " *
                    "Include this pair in metric_pairs."
                )

            comparison_name = comparisons[matching_comparison].name

            for tp in ("crossing", "final")

                # --------------------------------------------
                # 1. Arithmetic mean of run-level Pearson r
                # --------------------------------------------

                corr_scale = scale == :z ? "z" : "raw"

                corr_rows = run_correlation_summary[
                    (run_correlation_summary.comparison .== comparison_name) .&
                    (run_correlation_summary.timepoint .== tp) .&
                    (run_correlation_summary.scale .== corr_scale),
                    :
                ]

                overall_corr = corr_rows[
                    corr_rows.condition .== "ALL",
                    :
                ]

                condition_corr = corr_rows[
                    in.(corr_rows.condition, Ref(Set(conditions))),
                    :
                ]

                DataFrames.nrow(overall_corr) == 1 ||
                    error("Missing overall correlation summary.")

                DataFrames.nrow(condition_corr) == length(conditions) ||
                    error("Incomplete condition correlation summaries.")

                overall_r = overall_corr.mean_r_arithmetic[1]

                condition_r = Float64.(
                    condition_corr.mean_r_arithmetic
                )

                r_text = @sprintf(
                    "%.3f (%.3f–%.3f)",
                    overall_r,
                    minimum(condition_r),
                    maximum(condition_r)
                )

                # --------------------------------------------
                # 2. Mean absolute difference in z-scores
                # --------------------------------------------

                diff_rows = differences[
                    (differences.comparison .== comparison_name) .&
                    (differences.timepoint .== tp) .&
                    (differences.scale .== "z") .&
                    (differences.difference_type .== "absolute"),
                    :
                ]

                overall_diff = diff_rows[
                    diff_rows.condition .== "ALL",
                    :
                ]

                condition_diff = diff_rows[
                    in.(diff_rows.condition, Ref(Set(conditions))),
                    :
                ]

                DataFrames.nrow(overall_diff) == 1 ||
                    error(
                        "Missing overall absolute z-score differences. " *
                        "Use scale=:z or :both and " *
                        "difference_type=:absolute or :both."
                    )

                DataFrames.nrow(condition_diff) == length(conditions) ||
                    error("Incomplete condition difference summaries.")

                overall_delta = overall_diff.mean[1]

                condition_deltas = Float64.(
                    condition_diff.mean
                )

                delta_text = @sprintf(
                    "%.3f (%.3f–%.3f)",
                    overall_delta,
                    minimum(condition_deltas),
                    maximum(condition_deltas)
                )

                # --------------------------------------------
                # 3. Extreme-agent agreement
                # --------------------------------------------

                agreement_rows = extreme_agreement[
                    (extreme_agreement.comparison .== comparison_name) .&
                    (extreme_agreement.timepoint .== tp),
                    :
                ]

                overall_agreement = agreement_rows[
                    agreement_rows.condition .== "ALL",
                    :
                ]

                condition_agreement = agreement_rows[
                    in.(agreement_rows.condition, Ref(Set(conditions))),
                    :
                ]

                DataFrames.nrow(overall_agreement) == 1 ||
                    error("Missing overall extreme-agent agreement.")

                DataFrames.nrow(condition_agreement) == length(conditions) ||
                    error("Incomplete condition agreement summaries.")

                overall_percentage = overall_agreement.percentage[1]

                condition_percentages = Float64.(
                    condition_agreement.percentage
                )

                agreement_text = @sprintf(
                    "%.1f%% (%.1f–%.1f%%)",
                    overall_percentage,
                    minimum(condition_percentages),
                    maximum(condition_percentages)
                )

                push!(publication_summary, (
                    metric_label,
                    tp,
                    r_text,
                    delta_text,
                    agreement_text
                ))
            end
        end

        println("\n", "="^110)
        println("SUMMARY: ALTERNATIVE SEMANTIC METRICS VS. MEAN PAIRWISE TVD")
        println("="^110)

        Base.show(
            stdout,
            MIME("text/plain"),
            publication_summary;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println("\n")

    end

    return (
        correlations = correlations,
        run_correlation_summary = run_correlation_summary,
        run_correlations = run_correlation_details,
        differences = differences,
        extreme_agreement = extreme_agreement,
        publication_summary = publication_summary,
        plots = plots
    )
end
metric_pairs = [
    # Available metrics:
    # :mean_distance_from_others, :distance_from_mean_network, :column_normalized_distance_from_mean, :word_degree_distance_from_mean
    (:mean_distance_from_others, :distance_from_mean_network),
    (:mean_distance_from_others, :column_normalized_distance_from_mean),
    (:mean_distance_from_others, :word_degree_distance_from_mean)
]
