# )
function summarize_degree_metric(analysis)

    comparison = "word_degree_distance_from_mean vs. mean_distance_from_others"

    corr = analysis.run_correlation_summary
    diff = analysis.differences

    corr_table = corr[
        (corr.comparison .== comparison) .&
        (corr.scale .== "z"),
        [:condition, :timepoint, :mean_r_arithmetic, :sd_r]
    ]

    diff_table = diff[
        (diff.comparison .== comparison) .&
        (diff.scale .== "z") .&
        (diff.difference_type .== "absolute"),
        [:condition, :timepoint, :mean_of_run_means, :sd_of_run_means]
    ]

    DataFrames.rename!(corr_table,
        :mean_r_arithmetic => :correlation_mean,
        :sd_r => :correlation_sd
    )

    DataFrames.rename!(diff_table,
        :mean_of_run_means => :distance_mean,
        :sd_of_run_means => :distance_sd
    )

    result = DataFrames.innerjoin(
        corr_table,
        diff_table;
        on = [:condition, :timepoint]
    )

    DataFrames.sort!(result, [:timepoint, :condition])

    println("\nDEGREE DISTRIBUTION — MEAN AND BETWEEN-RUN SD\n")

    show(stdout, MIME("text/plain"), result;
        allrows = true,
        allcols = true,
        truncate = 0
    )
    println()

    return result
end
