function summarize_bank_success_rates(
    bank_dir::String = "new_semantic_network_bank";
    confidence_level::Real = 0.95)

    log = load_bank_log(bank_dir)

    alpha = 1 - confidence_level

    results = DataFrames.DataFrame(
        condition = String[],
        attempts = Int[],
        valid_runs = Int[],
        success_rate = Float64[],
        ci_lower = Float64[],
        ci_upper = Float64[]
    )

    for (condition, info) in sort(collect(log); by = first)

        n = Int(info.attempts)
        r = Int(info.valid_runs)

        n > 0 || continue
        0 < r <= n || error("Invalid counts for $condition")

        p_hat = r / n

        lower = Distributions.quantile(
            Distributions.Beta(r, n - r + 1),
            alpha / 2
        )

        upper = n == r ?
            1.0 :
            Distributions.quantile(
                Distributions.Beta(r, n - r),
                1 - alpha / 2
            )

        push!(results, (
            condition,
            n,
            r,
            100 * p_hat,
            100 * lower,
            100 * upper
        ))
    end

    println("\nSUCCESS PROBABILITIES AND 95% CONFIDENCE INTERVALS")
    println("="^90)

    show(
        stdout,
        MIME("text/plain"),
        results;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println()

    return results
end
