function plot_extreme_metrics_crossing_vs_final(
    results::DataFrames.DataFrame;
    condition_labels::Vector{<:Pair},
    use_z::Bool = true,
    error_type::Symbol = :sd,
    show_points::Bool = true,
    point_color = :black,
    point_alpha::Real = 0.35,
    point_size::Real = 3,
    legend_position::Tuple{<:Real,<:Real} = (0.5, 0.05),
    crossing_title::String = "Crossing",
    final_title::String = "Final",
    xlabel::String = "Condition",
    ylabel::String = use_z ? "Distance (z)" : "Distance",
    legend_title::String = "",
    threshold_linewidth::Real = 2,
    threshold_alpha::Real = 0.8,
    ylims = nothing,
    fontfamily::String = "Calibri",
    size = (1600, 700),
    legend_labels = nothing,
    xrotation::Real = 0)

    error_type in (:sd, :sem, :none) ||
        Base.error("error_type must be :sd, :sem, or :none.")

    point_color == :by_bar ||
        point_color isa Symbol ||
        point_color isa AbstractString ||
        Base.error("point_color must be a color or :by_bar.")

    conditions = String.(first.(condition_labels))
    labels = String.(last.(condition_labels))

    isempty(conditions) &&
        Base.error("condition_labels cannot be empty.")

    length(unique(conditions)) == length(conditions) ||
        Base.error("Duplicate conditions were supplied.")

    available = Set(String.(results.condition))
    missing = setdiff(conditions, collect(available))

    isempty(missing) ||
        Base.error("Missing conditions: $(join(missing, ", "))")

    metrics = use_z ? SEMANTIC_METRICS_Z : SEMANTIC_METRICS_RAW
    metric_labels = [SEMANTIC_METRIC_LABELS[m] for m in metrics]

    if legend_labels !== nothing
        length(legend_labels) == length(metrics) ||
            Base.error("legend_labels must contain $(length(metrics)) labels.")

        metric_labels = String.(legend_labels)
    end

    n_conditions = length(conditions)
    n_metrics = length(metrics)

    timepoints = [
        ("post_0", crossing_title),
        ("post_100", final_title)
    ]

    panel_data = NamedTuple[]
    all_y = Float64[]

    for (tp, title) in timepoints

        df = results[results.timepoint .== tp, :]

        means = Matrix{Float64}(undef, n_conditions, n_metrics)
        errors = Matrix{Float64}(undef, n_conditions, n_metrics)

        observations = Dict{Tuple{Int,Int},Vector{Float64}}()

        for (ci, condition) in enumerate(conditions)

            condition_df = df[df.condition .== condition, :]

            DataFrames.nrow(condition_df) > 0 ||
                Base.error("No observations for $condition at $tp.")

            for (mi, metric) in enumerate(metrics)

                values = Float64.(condition_df[!, metric])
                values = filter(isfinite, values)

                isempty(values) &&
                    Base.error("No finite values for $condition, $metric, $tp.")

                μ, err = mean_and_error(
                    values;
                    error_type = error_type
                )

                means[ci, mi] = μ
                errors[ci, mi] = err
                observations[(ci, mi)] = values

                push!(all_y, μ - err, μ + err)

                if show_points
                    append!(all_y, values)
                end
            end
        end

        push!(panel_data, (
            timepoint = tp,
            title = title,
            means = means,
            errors = errors,
            observations = observations
        ))
    end

    if use_z
        push!(all_y, 2.5)
    end

    shared_ylims = if ylims === nothing

        ymin = minimum(all_y)
        ymax = maximum(all_y)

        span = ymax - ymin
        margin = span > 0 ? 0.06 * span : 0.5

        (min(0.0, ymin - margin), ymax + margin)

    else
        ylims
    end

    colors = collect(Plots.palette(:default, n_metrics))

    group_width = 0.8
    bar_width = group_width / n_metrics

    offsets = [
        -group_width / 2 + (mi - 0.5) * bar_width
        for mi in 1:n_metrics
    ]

    panels = []

    for (panel_i, panel) in enumerate(panel_data)

        p = Plots.plot(
            title = panel.title,
            xlabel = xlabel,
            ylabel = panel_i == 1 ? ylabel : "",
            xticks = (1:n_conditions, labels),
            xrotation = xrotation,
            xlims = (0.5, n_conditions + 0.5),
            ylims = shared_ylims,
            legend = false,
            grid = false,
            framestyle = :box,
            fontfamily = fontfamily,
            tickfontsize = 11,
            guidefontsize = 13,
            titlefontsize = 16
        )

        if use_z
            Plots.hline!(
                p,
                [2.5];
                color = :red,
                linestyle = :dash,
                linewidth = threshold_linewidth,
                alpha = threshold_alpha,
                label = ""
            )
        end

        for mi in 1:n_metrics

            x_positions = [
                ci + offsets[mi]
                for ci in 1:n_conditions
            ]

            heights = panel.means[:, mi]
            errs = panel.errors[:, mi]

            Plots.bar!(
                p,
                x_positions,
                heights;
                bar_width = bar_width * 0.92,
                color = colors[mi],
                linecolor = colors[mi],
                label = "",
                yerror = error_type == :none ? nothing : errs
            )

            if show_points

                for ci in 1:n_conditions

                    values = panel.observations[(ci, mi)]

                    current_point_color =
                        point_color == :by_bar ?
                        colors[mi] :
                        point_color

                    Plots.scatter!(
                        p,
                        fill(x_positions[ci], length(values)),
                        values;
                        color = current_point_color,
                        markersize = point_size,
                        markeralpha = point_alpha,
                        markerstrokewidth = 0,
                        label = ""
                    )
                end
            end
        end

        push!(panels, p)
    end

    # --------------------------------------------------------
    # Main figure: Crossing and Final
    # --------------------------------------------------------

    combined = Plots.plot(
        panels[1],
        panels[2];
        layout = (1, 2),
        size = size,
        fontfamily = fontfamily
    )

    # --------------------------------------------------------
    # Separate legend figure
    # --------------------------------------------------------

    legend_plot = Plots.plot(
        xlims = (0, 1),
        ylims = (0, 1),
        axis = false,
        grid = false,
        framestyle = :none,
        legend = :topright,
        legendtitle = legend_title,
        fontfamily = fontfamily,
        legendfontsize = 12,
        legend_background_color = :white,
        legend_foreground_color = :black,
        size = (650, 250),
        margin = 5Plots.mm
    )

    for mi in 1:n_metrics

        Plots.bar!(
            legend_plot,
            [2.0 + mi],
            [1.0];
            color = colors[mi],
            linecolor = colors[mi],
            label = metric_labels[mi]
        )

    end

    # --------------------------------------------------------
    # Summary tables: Mean ± SD
    # --------------------------------------------------------

    summary_tables = Dict{String,DataFrames.DataFrame}()

    for panel in panel_data

        table = DataFrames.DataFrame(
            Condition = labels
        )

        for (mi, metric) in enumerate(metrics)

            column_name = metric_labels[mi]

            table[!, column_name] = [
                begin
                    values = panel.observations[(ci, mi)]

                    μ = Statistics.mean(values)
                    σ = length(values) > 1 ?
                        Statistics.std(values) : 0.0

                    string(
                        round(μ; digits = 3),
                        " ± ",
                        round(σ; digits = 3)
                    )
                end
                for ci in 1:n_conditions
            ]
        end

        summary_tables[panel.timepoint] = table

        println()
        println("========================================")
        println(panel.title, " — Mean ± SD")
        println("========================================")

        display(table)
    end

    display(combined)
    display(legend_plot)

    return (
        figure = combined,
        legend = legend_plot,
        crossing_table = summary_tables["post_0"],
        final_table = summary_tables["post_100"]
    )
end
