function analyze_semantic_delta_factorial(
    data_path::String;
    timepoint::Symbol = :final,       # :crossing, :final, :both
    expected_runs::Int = 150,
    plot_size = (1200, 750),
    fontfamily::String = "Calibri",
    titlefontsize::Int = 17,
    guidefontsize::Int = 15,
    tickfontsize::Int = 12,
    point_size::Real = 3,
    point_alpha::Real = 0.25,
    jitter_width::Real = 0.13,
    show_points::Bool = true,
    show_plots::Bool = true,
    verbose::Bool = true)

    # ========================================================
    # 1. Parameters and data
    # ========================================================

    timepoint in (:crossing, :final, :both) ||
        Base.error("timepoint must be :crossing, :final, or :both.")

    requested_timepoints = timepoint == :both ?
        ["post_0", "post_100"] :
        [timepoint == :crossing ? "post_0" : "post_100"]

    conditions = [
        (
            name = "homophily_0_learning1_0_9",
            H = 0,
            L = 0,
            label = "H=0, L=0"
        ),
        (
            name = "homophily_3_learning1_0_9",
            H = 1,
            L = 0,
            label = "H=1, L=0"
        ),
        (
            name = "homophily_0_learning1_0_5",
            H = 0,
            L = 1,
            label = "H=0, L=1"
        ),
        (
            name = "homophily_3_learning1_0_5",
            H = 1,
            L = 1,
            label = "H=1, L=1"
        )
    ]

    isfile(data_path) ||
        Base.error("File not found: $data_path")

    data = DataFrames.DataFrame(
        JLD2.load(data_path, "results")
    )

    required_columns = [
        :condition,
        :run_number,
        :focal_agent,
        :timepoint,
        :column_normalized_distance_from_mean_z,
        :word_degree_distance_from_mean_z
    ]

    missing_columns = setdiff(
        required_columns,
        propertynames(data)
    )

    isempty(missing_columns) ||
        Base.error("Missing columns: $missing_columns")

    condition_names = Set(c.name for c in conditions)

    data = data[
        in.(String.(data.condition), Ref(condition_names)) .&
        in.(String.(data.timepoint), Ref(Set(requested_timepoints))),
        :
    ]

    # ========================================================
    # 2. Select observations and validate completeness
    # ========================================================

    observations = DataFrames.DataFrame(
        condition = String[],
        run_number = Int[],
        focal_agent = Int[],
        timepoint = String[],
        H = Int[],
        L = Int[],
        delta_z = Float64[]
    )

    for tp in requested_timepoints

        for condition in conditions

            subset = data[
                (String.(data.condition) .== condition.name) .&
                (String.(data.timepoint) .== tp),
                :
            ]

            DataFrames.nrow(subset) == expected_runs ||
                Base.error(
                    "Expected $expected_runs rows for " *
                    "$(condition.name), $tp; " *
                    "found $(DataFrames.nrow(subset))."
                )

            run_numbers = Int.(subset.run_number)

            length(unique(run_numbers)) == expected_runs ||
                Base.error(
                    "Duplicate run numbers in $(condition.name), $tp."
                )

            Set(run_numbers) == Set(1:expected_runs) ||
                Base.error(
                    "Unexpected or missing run numbers in " *
                    "$(condition.name), $tp."
                )

            for row in eachrow(subset)

                col_z = Float64(
                    row.column_normalized_distance_from_mean_z
                )

                degree_z = Float64(
                    row.word_degree_distance_from_mean_z
                )

                isfinite(col_z) && isfinite(degree_z) ||
                    Base.error(
                        "Non-finite metric value: " *
                        "$(condition.name), run $(row.run_number), $tp"
                    )

                push!(observations, (
                    condition.name,
                    Int(row.run_number),
                    Int(row.focal_agent),
                    tp,
                    condition.H,
                    condition.L,
                    col_z - degree_z
                ))
            end
        end
    end

    # If both timepoints are selected, verify that the same
    # focal agent was used for each run at both timepoints.

    if timepoint == :both

        for condition in conditions

            for run_number in 1:expected_runs

                subset = observations[
                    (observations.condition .== condition.name) .&
                    (observations.run_number .== run_number),
                    :
                ]

                DataFrames.nrow(subset) == 2 ||
                    Base.error("Missing timepoint for run $run_number.")

                length(unique(subset.focal_agent)) == 1 ||
                    Base.error(
                        "Different focal agents across timepoints: " *
                        "$(condition.name), run $run_number."
                    )
            end
        end
    end

    verbose && println(
        "Validation passed: ",
        length(conditions),
        " conditions × ",
        expected_runs,
        " runs × ",
        length(requested_timepoints),
        " timepoint(s)."
    )

    # ========================================================
    # 3. Output tables
    # ========================================================

    descriptive = DataFrames.DataFrame(
        timepoint = String[],
        condition = String[],
        H = Int[],
        L = Int[],
        N = Int[],
        mean = Float64[],
        SD = Float64[],
        CI_low = Float64[],
        CI_high = Float64[]
    )

    coefficients = DataFrames.DataFrame(
        timepoint = String[],
        term = String[],
        estimate = Float64[],
        HC3_SE = Float64[],
        CI_low = Float64[],
        CI_high = Float64[],
        p_value = Float64[]
    )

    contrasts = DataFrames.DataFrame(
        timepoint = String[],
        hypothesis = String[],
        estimate = Float64[],
        HC3_SE = Float64[],
        CI_low = Float64[],
        CI_high = Float64[],
        p_value = Float64[],
        direction = String[]
    )

    model_fit = DataFrames.DataFrame(
        timepoint = String[],
        N = Int[],
        R_squared = Float64[]
    )

    plots = Dict{String,Any}()

    normal = Distributions.Normal()
    zcrit = Distributions.quantile(normal, 0.975)

    # ========================================================
    # 4. Separate factorial analysis for each timepoint
    # ========================================================

    for tp in requested_timepoints

        df = observations[
            observations.timepoint .== tp,
            :
        ]

        y = Float64.(df.delta_z)

        H = Float64.(df.H)
        L = Float64.(df.L)

        n = length(y)

        # Design matrix:
        # Intercept, H, L, H×L

        X = hcat(
            ones(n),
            H,
            L,
            H .* L
        )

        p = size(X, 2)

        # ----------------------------------------------------
        # OLS
        # ----------------------------------------------------

        beta = X \ y

        fitted = X * beta
        residuals = y - fitted

        XtX_inv = inv(transpose(X) * X)

        # ----------------------------------------------------
        # HC3 heteroskedasticity-robust covariance
        # ----------------------------------------------------

        leverage = vec(
            sum((X * XtX_inv) .* X; dims = 2)
        )

        all(leverage .< 1.0) ||
            Base.error("HC3 cannot be computed: leverage >= 1.")

        hc3_weights = (
            residuals ./ (1.0 .- leverage)
        ) .^ 2

        meat = transpose(X) * (
            X .* reshape(hc3_weights, :, 1)
        )

        V_HC3 = XtX_inv * meat * XtX_inv

        V_HC3 = (
            V_HC3 + transpose(V_HC3)
        ) ./ 2

        # ----------------------------------------------------
        # General linear contrast using HC3
        # ----------------------------------------------------

        function test_contrast(c::Vector{Float64})

            estimate = LinearAlgebra.dot(c, beta)

            variance = LinearAlgebra.dot(
                c,
                V_HC3 * c
            )

            variance >= 0 ||
                Base.error("Negative contrast variance.")

            se = sqrt(variance)

            if se == 0
                Base.error("Zero HC3 standard error.")
            end

            z_stat = estimate / se

            p_value = 2 * Distributions.ccdf(
                normal,
                abs(z_stat)
            )

            return (
                estimate = estimate,
                se = se,
                ci_low = estimate - zcrit * se,
                ci_high = estimate + zcrit * se,
                p_value = p_value
            )
        end

        # ----------------------------------------------------
        # Model coefficients
        # ----------------------------------------------------

        coefficient_names = [
            "Intercept",
            "Homophily (H)",
            "Learning impairment (L)",
            "H × L"
        ]

        for j in 1:p

            c = zeros(Float64, p)
            c[j] = 1.0

            result = test_contrast(c)

            push!(coefficients, (
                tp,
                coefficient_names[j],
                result.estimate,
                result.se,
                result.ci_low,
                result.ci_high,
                result.p_value
            ))
        end

        # ----------------------------------------------------
        # Three preregistered-style hypothesis contrasts
        # ----------------------------------------------------

        hypotheses = [
            (
                "Main effect: Homophily",
                [0.0, 1.0, 0.0, 0.5]
            ),
            (
                "Main effect: Learning impairment",
                [0.0, 0.0, 1.0, 0.5]
            ),
            (
                "Learning impairment | H=0",
                [0.0, 0.0, 1.0, 0.0]
            ),
            (
                "Learning impairment | H=1",
                [0.0, 0.0, 1.0, 1.0]
            ),
            (
                "Interaction: difference of learning effects",
                [0.0, 0.0, 0.0, 1.0]
            )
        ]

        for (hypothesis, c) in hypotheses

            result = test_contrast(c)

            direction = result.estimate > 0 ?
                "Positive" :
                result.estimate < 0 ?
                "Negative" : "Zero"

            push!(contrasts, (
                tp,
                hypothesis,
                result.estimate,
                result.se,
                result.ci_low,
                result.ci_high,
                result.p_value,
                direction
            ))
        end

        # ----------------------------------------------------
        # Model fit
        # ----------------------------------------------------

        sst = sum(
            (y .- Statistics.mean(y)) .^ 2
        )

        r_squared = sst > 0 ?
            1 - sum(residuals .^ 2) / sst :
            NaN

        push!(model_fit, (
            tp,
            n,
            r_squared
        ))

        # ----------------------------------------------------
        # Descriptive statistics and confidence intervals
        # ----------------------------------------------------

        for condition in conditions

            values = df.delta_z[
                df.condition .== condition.name
            ]

            ng = length(values)

            μ = Statistics.mean(values)
            sd = Statistics.std(values)
            sem = sd / sqrt(ng)

            tcrit = Distributions.quantile(
                Distributions.TDist(ng - 1),
                0.975
            )

            push!(descriptive, (
                tp,
                condition.name,
                condition.H,
                condition.L,
                ng,
                μ,
                sd,
                μ - tcrit * sem,
                μ + tcrit * sem
            ))
        end

        # ====================================================
        # 5. Publication plot
        # ====================================================

        title_text = tp == "post_0" ?
            "Crossing" : "Final"

        graph = Plots.plot(
            size = plot_size,
            fontfamily = fontfamily,
            title = title_text,
            titlefontsize = titlefontsize,
            xlabel = "Condition",
            ylabel = "Δz (Column-normalized − Degree-distribution)",
            guidefontsize = guidefontsize,
            tickfontsize = tickfontsize,
            xticks = (
                1:4,
                [c.label for c in conditions]
            ),
            xlims = (0.5, 4.5),
            grid = false,
            framestyle = :box,
            legend = :topright
        )

        Plots.hline!(
            graph,
            [0.0];
            color = :gray,
            linestyle = :dash,
            linewidth = 1.5,
            label = ""
        )

        rng = Random.MersenneTwister(12345)

        for (i, condition) in enumerate(conditions)

            values = df.delta_z[
                df.condition .== condition.name
            ]

            if show_points

                jitter = (
                    rand(rng, length(values)) .- 0.5
                ) .* (2 * jitter_width)

                Plots.scatter!(
                    graph,
                    i .+ jitter,
                    values;
                    color = :gray,
                    markersize = point_size,
                    markeralpha = point_alpha,
                    markerstrokewidth = 0,
                    label = ""
                )
            end

            row = descriptive[
                (descriptive.timepoint .== tp) .&
                (descriptive.condition .== condition.name),
                :
            ]

            μ = row.mean[1]

            lower_error = μ - row.CI_low[1]
            upper_error = row.CI_high[1] - μ

            Plots.scatter!(
                graph,
                [i],
                [μ];
                yerror = (
                    [lower_error],
                    [upper_error]
                ),
                color = :black,
                markersize = 8,
                markerstrokecolor = :white,
                markerstrokewidth = 1,
                linewidth = 2.5,
                capsize = 6,
                label = i == 1 ? "Mean ± 95% CI" : ""
            )
        end

        plots[tp] = graph

        # ====================================================
        # 6. Print results
        # ====================================================

        if verbose

            println()
            println("="^90)
            println("SEMANTIC Δz — ", uppercase(title_text))
            println("="^90)

            println("\nDESCRIPTIVE STATISTICS")

            descriptive_tp = descriptive[
                descriptive.timepoint .== tp,
                :
            ]

            display(descriptive_tp)

            println("\nOLS COEFFICIENTS — HC3")

            coefficients_tp = coefficients[
                coefficients.timepoint .== tp,
                :
            ]

            display(coefficients_tp)

            println("\nHYPOTHESIS TESTS — HC3")

            contrasts_tp = contrasts[
                contrasts.timepoint .== tp,
                :
            ]

            display(contrasts_tp)

            println("\nMODEL FIT")

            display(model_fit[
                model_fit.timepoint .== tp,
                :
            ])

            println(
                "\nInference: two-sided asymptotic normal " *
                "tests and 95% Wald confidence intervals, " *
                "using HC3 standard errors."
            )

            println(
                "Plot intervals: descriptive 95% t " *
                "confidence intervals for condition means."
            )
        end

        # if show_plots
        #     display(graph)
        # end
    end

    combined_plot = plot_semantic_delta_combined(
        observations,
        descriptive;
        plot_size = plot_size,
        fontfamily = fontfamily,
        titlefontsize = titlefontsize,
        guidefontsize = guidefontsize,
        tickfontsize = tickfontsize,
        point_size = point_size,
        point_alpha = point_alpha,
        jitter_width = jitter_width,
        show_points = show_points
    )

    if show_plots
        display(combined_plot)
    end

    
    # ========================================================
    # 7. Automatically generated Results paragraphs
    # ========================================================

    if verbose

        function get_result(tp::String, hypothesis::String)
            rows = contrasts[
                (contrasts.timepoint .== tp) .&
                (contrasts.hypothesis .== hypothesis),
                :
            ]

            DataFrames.nrow(rows) == 1 ||
                Base.error("Missing or duplicate contrast: $hypothesis, $tp")

            return rows[1, :]
        end

        function format_result(row)
            b = string(round(row.estimate; digits = 3))
            low = string(round(row.CI_low; digits = 3))
            high = string(round(row.CI_high; digits = 3))

            p = row.p_value < 0.001 ?
                "p < .001" :
                "p = " * replace(
                    string(round(row.p_value; digits = 3)),
                    r"^0\." => "."
                )

            return "b = $b, 95% CI [$low, $high], $p"
        end

        function result_text(tp, hypothesis)
            return format_result(get_result(tp, hypothesis))
        end

        has_crossing = "post_0" in requested_timepoints
        has_final = "post_100" in requested_timepoints

        main_H = "Main effect: Homophily"
        main_L = "Main effect: Learning impairment"
        interaction = "Interaction: difference of learning effects"
        simple_H0 = "Learning impairment | H=0"
        simple_H1 = "Learning impairment | H=1"

        println()
        println("="^90)
        println("RESULTS PARAGRAPHS — AUTOMATICALLY GENERATED")
        println("="^90)
        println()

        if has_crossing && has_final

            paragraph1 =
                "The analysis revealed main effects of both homophily " *
                "and social learning impairment at both time points. " *
                "Homophily was associated with a smaller difference " *
                "between Column-Normalized TVD and Degree-Distribution TVD, " *
                "both at the crossing step (" *
                result_text("post_0", main_H) *
                ") and at the final simulation step (" *
                result_text("post_100", main_H) *
                "). Conversely, impaired social learning was associated " *
                "with a larger difference between the two measures " *
                "at both the crossing step (" *
                result_text("post_0", main_L) *
                ") and the final simulation step (" *
                result_text("post_100", main_L) *
                ")."

            paragraph2 =
                "An interaction between homophily and social learning " *
                "impairment was also found at both the crossing step (" *
                result_text("post_0", interaction) *
                ") and the final simulation step (" *
                result_text("post_100", interaction) *
                "). Specifically, impaired social learning was " *
                "associated with a larger difference between the two " *
                "measures in the absence of homophily (crossing: " *
                result_text("post_0", simple_H0) *
                "; final: " *
                result_text("post_100", simple_H0) *
                ") than in its presence (crossing: " *
                result_text("post_0", simple_H1) *
                "; final: " *
                result_text("post_100", simple_H1) *
                ")."

        else

            tp = requested_timepoints[1]

            stage = tp == "post_0" ?
                "the crossing step" :
                "the final simulation step"

            paragraph1 =
                "The analysis examined the main effects of homophily " *
                "and social learning impairment at $stage. " *
                "Homophily was associated with a difference between " *
                "Column-Normalized TVD and Degree-Distribution TVD (" *
                result_text(tp, main_H) *
                "). Impaired social learning was also associated " *
                "with a difference between the two measures (" *
                result_text(tp, main_L) *
                ")."

            paragraph2 =
                "The interaction between homophily and social " *
                "learning impairment was estimated at " *
                "$stage (" *
                result_text(tp, interaction) *
                "). The effect of impaired social learning in the " *
                "absence of homophily was " *
                result_text(tp, simple_H0) *
                ", compared with " *
                result_text(tp, simple_H1) *
                " in the presence of homophily."

        end

        println(paragraph1)
        println()
        println(paragraph2)
        println()
    end


    return (
        observations = observations,
        descriptive = descriptive,
        coefficients = coefficients,
        contrasts = contrasts,
        model_fit = model_fit,
        plots = plots,
        combined_plot = combined_plot
    )
end
function plot_semantic_delta_combined(
    observations::DataFrames.DataFrame,
    descriptive::DataFrames.DataFrame;
    plot_size = (1200, 750),
    fontfamily::String = "Calibri",
    titlefontsize::Int = 17,
    guidefontsize::Int = 15,
    tickfontsize::Int = 12,
    legendfontsize::Int = 12,
    point_size::Real = 3,
    point_alpha::Real = 0.25,
    jitter_width::Real = 0.10,
    timepoint_offset::Real = 0.15,
    mean_marker_size::Real = 8,
    show_points::Bool = true,
    crossing_color = :steelblue,
    final_color = :darkorange,
    legend_position = (0.90, 0.97),
    ylims = nothing)

    
    conditions = [
        ("homophily_0_learning1_0_9", "No Homophily<br>No Impairment"),
        ("homophily_0_learning1_0_5", "No Homophily<br>Impairment"),
        ("homophily_3_learning1_0_9", "Homophily<br>No Impairment"),
        ("homophily_3_learning1_0_5", "Homophily<br>Impairment")
    ]


    timepoints = [
        ("post_0", "Crossing", crossing_color, -timepoint_offset),
        ("post_100", "Final", final_color, timepoint_offset)
    ]

    available_timepoints = Set(String.(observations.timepoint))

    selected_timepoints = [
        tp for tp in timepoints
        if tp[1] in available_timepoints
    ]

    isempty(selected_timepoints) &&
        Base.error("No supported timepoints found.")

    graph = Plots.plot(
        size = plot_size,
        fontfamily = fontfamily,
        title = "",
        titlefontsize = titlefontsize,
        xlabel = "Condition",
        ylabel = "Δz (Mean Column TVD − Degree-Distribution TVD)",
        guidefontsize = guidefontsize,
        tickfontsize = tickfontsize,
        legendfontsize = legendfontsize,
        legend = legend_position,
        xticks = (
            1:4,
            last.(conditions)
        ),
        xlims = (0.5, 4.5),
        ylims = ylims,
        grid = false,
        framestyle = :box,
        bottom_margin = 15Plots.mm
    )

    Plots.hline!(
        graph,
        [0.0];
        color = :gray,
        linestyle = :dash,
        linewidth = 1.5,
        label = ""
    )

    rng = Random.MersenneTwister(12345)

    for (tp, label, color, offset) in selected_timepoints

        means = Float64[]
        lower_errors = Float64[]
        upper_errors = Float64[]
        x_positions = Float64[]

        for (i, (condition, condition_label)) in enumerate(conditions)

            x = i + offset

            subset = observations[
                (observations.condition .== condition) .&
                (observations.timepoint .== tp),
                :
            ]

            DataFrames.nrow(subset) > 0 ||
                Base.error("No observations for $condition, $tp.")

            values = Float64.(subset.delta_z)

            if show_points

                jitter = (
                    rand(rng, length(values)) .- 0.5
                ) .* (2 * jitter_width)

                Plots.scatter!(
                    graph,
                    x .+ jitter,
                    values;
                    color = color,
                    markersize = point_size,
                    markeralpha = point_alpha,
                    markerstrokewidth = 0,
                    label = ""
                )
            end

            summary_row = descriptive[
                (descriptive.condition .== condition) .&
                (descriptive.timepoint .== tp),
                :
            ]

            DataFrames.nrow(summary_row) == 1 ||
                Base.error(
                    "Expected one descriptive row for $condition, $tp."
                )

            μ = summary_row.mean[1]

            push!(x_positions, x)
            push!(means, μ)
            push!(
                lower_errors,
                μ - summary_row.CI_low[1]
            )
            push!(
                upper_errors,
                summary_row.CI_high[1] - μ
            )
        end

        Plots.scatter!(
            graph,
            x_positions,
            means;
            yerror = (
                lower_errors,
                upper_errors
            ),
            color = color,
            markersize = mean_marker_size,
            markerstrokecolor = :white,
            markerstrokewidth = 1,
            linewidth = 2.5,
            capsize = 6,
            label = label
        )
    end

    return graph
end
