#         descriptives = descriptives,
#         overlaps = overlaps,
#         correlations = correlations,
#         density_plots = density_plots,
#         scatter_plots = scatter_plots
#     )
# end
# overlap_analysis = analyze_covariate_overlap_and_delta(
#     robustness.observations;
#     timepoint = :both,
#     loess_span = 0.75,
#     density_bins = 60,
#     scatter_size = (1500, 1050),
#     density_size = (1500, 950),
#     show_plots = true
# )

function analyze_delta_z_roc(
    observations::DataFrames.DataFrame;
    timepoint::Symbol = :both,
    expected_runs::Int = 150,
    histogram_bins::Int = 35,

    roc_plot_size = (750, 650),
    distribution_size = (1400, 600),

    fontfamily::String = "Calibri",
    titlefontsize::Int = 16,
    guidefontsize::Int = 13,
    tickfontsize::Int = 11,
    legendfontsize::Int = 11,

    # ROC title and legend controls
    roc_title_margin::Real = 12,
    roc_legend_crossing = (0.98, 0.05),
    roc_legend_final = (0.98, 0.05),
    roc_legend_anchor = :bottomright,

    distribution_legend_position = :topright,

    normal_color = :steelblue,
    impaired_color = :darkorange,
    roc_colors = [:black, :steelblue, :darkorange],

    show_plots::Bool = true,
    show_tables::Bool = true)

    # ========================================================
    # 1. Validation
    # ========================================================

    timepoint in (:crossing, :final, :both) ||
        error("timepoint must be :crossing, :final, or :both.")

    expected_runs > 0 ||
        error("expected_runs must be positive.")

    histogram_bins >= 2 ||
        error("histogram_bins must be at least 2.")

    length(roc_colors) == 3 ||
        error("roc_colors must contain three colors.")

    timepoints = timepoint == :both ?
        ["post_0", "post_100"] :
        [timepoint == :crossing ? "post_0" : "post_100"]

    conditions = [
        ("homophily_0_learning1_0_9", 0, 0),
        ("homophily_0_learning1_0_5", 0, 1),
        ("homophily_3_learning1_0_9", 1, 0),
        ("homophily_3_learning1_0_5", 1, 1)
    ]

    required_columns = [
        :condition,
        :run_number,
        :timepoint,
        :H,
        :L,
        :delta_z
    ]

    missing_columns = setdiff(
        required_columns,
        propertynames(observations)
    )

    isempty(missing_columns) ||
        error("Missing columns: $missing_columns")

    condition_names = Set(first.(conditions))

    data = observations[
        in.(observations.condition, Ref(condition_names)) .&
        in.(observations.timepoint, Ref(Set(timepoints))),
        :
    ]

    for tp in timepoints
        for (condition, H, L) in conditions

            subset = data[
                (data.timepoint .== tp) .&
                (data.condition .== condition),
                :
            ]

            DataFrames.nrow(subset) == expected_runs ||
                error(
                    "Expected $expected_runs runs for " *
                    "$condition at $tp, found $(DataFrames.nrow(subset))."
                )

            any(ismissing, subset.run_number) &&
                error("Missing run numbers in $condition, $tp.")

            runs = Int.(subset.run_number)

            Set(runs) == Set(1:expected_runs) ||
                error("Missing or duplicate runs in $condition, $tp.")

            all(x -> !ismissing(x) && x == H, subset.H) ||
                error("Incorrect H coding in $condition, $tp.")

            all(x -> !ismissing(x) && x == L, subset.L) ||
                error("Incorrect L coding in $condition, $tp.")

            all(
                x -> !ismissing(x) && x isa Real && isfinite(x),
                subset.delta_z
            ) || error("Invalid delta_z values in $condition, $tp.")
        end
    end

    # ========================================================
    # 2. ROC and AUC calculation
    # ========================================================

    function calculate_roc(
        scores::Vector{Float64},
        labels::Vector{Int}
    )

        n_positive = count(==(1), labels)
        n_negative = count(==(0), labels)

        n_positive > 0 && n_negative > 0 ||
            error("Both classes are required.")

        order = sortperm(scores; rev = true)

        sorted_scores = scores[order]
        sorted_labels = labels[order]

        fpr = Float64[0.0]
        tpr = Float64[0.0]
        thresholds = Float64[Inf]

        tp = 0
        fp = 0
        i = 1

        while i <= length(scores)

            j = i

            # Handle tied scores together
            while j <= length(scores) &&
                  sorted_scores[j] == sorted_scores[i]
                j += 1
            end

            for k in i:(j - 1)
                if sorted_labels[k] == 1
                    tp += 1
                else
                    fp += 1
                end
            end

            push!(tpr, tp / n_positive)
            push!(fpr, fp / n_negative)
            push!(thresholds, sorted_scores[i])

            i = j
        end

        auc = sum(
            (fpr[k + 1] - fpr[k]) *
            (tpr[k + 1] + tpr[k]) / 2
            for k in 1:(length(fpr) - 1)
        )

        return (
            auc = auc,
            fpr = fpr,
            tpr = tpr,
            thresholds = thresholds
        )
    end

    # ========================================================
    # 3. Results containers
    # ========================================================

    groups = [
        ("Overall", nothing),
        ("No Homophily", 0),
        ("Homophily", 1)
    ]

    results = DataFrames.DataFrame(
        timepoint = String[],
        group = String[],
        N = Int[],
        N_normal = Int[],
        N_impaired = Int[],
        AUC = Float64[]
    )

    roc_points = DataFrames.DataFrame(
        timepoint = String[],
        group = String[],
        threshold = Float64[],
        FPR = Float64[],
        TPR = Float64[],
        specificity = Float64[],
        sensitivity = Float64[]
    )

    roc_plots = Dict{String,Any}()
    distribution_plots = Dict{String,Any}()

    # ========================================================
    # 4. Calculate ROC and AUC
    # ========================================================

    for tp in timepoints

        tp_data = data[data.timepoint .== tp, :]

        is_crossing = tp == "post_0"

        legend_coordinates = is_crossing ?
            roc_legend_crossing :
            roc_legend_final

        roc_plot = Plots.plot(
            title = is_crossing ? "A. Crossing" : "B. Final",
            xlabel = "False Positive Rate",
            ylabel = is_crossing ? "True Positive Rate" : "",
            xlims = (0.0, 1.0),
            ylims = (0.0, 1.0),
            xticks = 0.0:0.2:1.0,
            yticks = 0.0:0.2:1.0,
            aspect_ratio = :equal,
            size = roc_plot_size,
            fontfamily = fontfamily,
            titlefontsize = titlefontsize,
            guidefontsize = guidefontsize,
            tickfontsize = tickfontsize,
            legendfontsize = legendfontsize,
            legend = legend_coordinates,
            top_margin = roc_title_margin * Plots.mm,
            grid = false,
            framestyle = :box
        )

        # Reference diagonal
        Plots.plot!(
            roc_plot,
            [0.0, 1.0],
            [0.0, 1.0];
            color = :gray,
            linestyle = :dash,
            linewidth = 1.5,
            label = ""
        )

        for (i, (group_name, H_value)) in enumerate(groups)

            subset = H_value === nothing ?
                tp_data :
                tp_data[tp_data.H .== H_value, :]

            scores = Float64.(subset.delta_z)
            labels = Int.(subset.L)

            roc = calculate_roc(scores, labels)

            push!(results, (
                tp,
                group_name,
                length(labels),
                count(==(0), labels),
                count(==(1), labels),
                roc.auc
            ))

            for j in eachindex(roc.fpr)

                push!(roc_points, (
                    tp,
                    group_name,
                    roc.thresholds[j],
                    roc.fpr[j],
                    roc.tpr[j],
                    1.0 - roc.fpr[j],
                    roc.tpr[j]
                ))
            end

            Plots.plot!(
                roc_plot,
                roc.fpr,
                roc.tpr;
                color = roc_colors[i],
                linewidth = 2.5,
                label = string(
                    group_name,
                    " (AUC = ",
                    round(roc.auc; digits = 3),
                    ")"
                )
            )

            println(
                "Completed: ",
                tp,
                " | ",
                group_name,
                " | AUC = ",
                round(roc.auc; digits = 4)
            )
        end

        # Precise legend positioning for Plotly backend.
        # Coordinates are relative to the plot area (0 to 1).
        #
        # The anchor determines which corner of the legend
        # is placed at the requested coordinates.

        Plots.plot!(
            roc_plot;
            legend = legend_coordinates
        )

        roc_plots[tp] = roc_plot

        roc_plots[tp] = roc_plot

        # ====================================================
        # 5. Δz distributions
        # ====================================================

        normal_values = Float64.(
            tp_data.delta_z[tp_data.L .== 0]
        )

        impaired_values = Float64.(
            tp_data.delta_z[tp_data.L .== 1]
        )

        all_values = vcat(normal_values, impaired_values)

        edges = collect(range(
            minimum(all_values) - 1e-6,
            maximum(all_values) + 1e-6;
            length = histogram_bins + 1
        ))

        distribution_plot = Plots.plot(
            title = is_crossing ? "Crossing" : "Final",
            xlabel = "Δz",
            ylabel = "Density",
            fontfamily = fontfamily,
            titlefontsize = titlefontsize,
            guidefontsize = guidefontsize,
            tickfontsize = tickfontsize,
            legendfontsize = legendfontsize,
            legend = distribution_legend_position,
            grid = false,
            framestyle = :box
        )

        Plots.histogram!(
            distribution_plot,
            normal_values;
            bins = edges,
            normalize = :pdf,
            color = normal_color,
            alpha = 0.45,
            label = "Normal Learning"
        )

        Plots.histogram!(
            distribution_plot,
            impaired_values;
            bins = edges,
            normalize = :pdf,
            color = impaired_color,
            alpha = 0.45,
            label = "Impaired Learning"
        )

        distribution_plots[tp] = distribution_plot
    end

    # ========================================================
    # 6. Combined distribution figure
    # ========================================================

    roc_figure = nothing

    distribution_figure = Plots.plot(
        [distribution_plots[tp] for tp in timepoints]...;
        layout = (1, length(timepoints)),
        size = distribution_size,
        fontfamily = fontfamily
    )

    # ========================================================
    # 7. Display
    # ========================================================

    if show_tables

        println("\nROC / AUC RESULTS")

        Base.show(
            stdout,
            MIME("text/plain"),
            results;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    if show_plots

        display(distribution_figure)

        for tp in timepoints
            display(roc_plots[tp])
        end
    end

    return (
        results = results,
        roc_points = roc_points,
        roc_plots = roc_plots,
        distribution_plots = distribution_plots,
        roc_figure = roc_figure,
        distribution_figure = distribution_figure
    )
end
# roc_analysis = analyze_delta_z_roc(
#     robustness.observations;
#     timepoint = :both,
#     expected_runs = 150,
#     histogram_bins = 35,

#     roc_plot_size = (750, 650),
#     distribution_size = (1400, 600),

#     roc_title_margin = 2,

#     roc_legend_crossing = (0.62, 0.20),
#     roc_legend_final = (0.61, 0.20),
#     # roc_legend_anchor = :bottomright,

#     show_plots = true,
#     show_tables = true
# )


function analyze_social_semantic_controlled_models(
    semantic_path::String,
    social_path::String;

    timepoints = ["post_0", "post_100"],

    # :all = all conditions
    # Or specify selected conditions:
    # conditions = [
    #     "homophily_0_learning1_0_5",
    #     "homophily_3_learning1_0_5"
    # ]
    conditions = :all,

    # ========================================================
    # GRAPH SELECTION
    # ========================================================

    # Choose which graphs to DISPLAY:
    # :all = all three metrics
    # Or select any combination of:
    # :degree, :column, :delta
    #
    # Examples:
    # plot_metrics = [:degree, :column]
    # plot_metrics = [:delta]
    # plot_metrics = [:degree, :column, :delta]
    #
    # All statistical models are calculated regardless.
    plot_metrics = [:degree, :column, :delta],

    # ========================================================
    # GRAPH TITLES
    # ========================================================

    # Set show_titles = false to hide all titles.
    show_titles = true,

    # Custom titles by metric and timepoint.
    # Keys: (:degree/:column/:delta, "post_0"/"post_100")
    plot_titles = Dict(
        (:degree, "post_0") => "Crossing — Word-degree distribution",
        (:degree, "post_100") => "Final — Word-degree distribution",
        (:column, "post_0") => "Crossing — Column-normalized distribution",
        (:column, "post_100") => "Final — Column-normalized distribution",
        (:delta, "post_0") => "Crossing — Δz",
        (:delta, "post_100") => "Final — Δz"
    ),

    titlefontsize = 17,
    guidefontsize = 15,
    tickfontsize = 12,
    legendfontsize = 11,

    xlabel = "Social Engagement (z-score)",

    ylabels = Dict(
        :degree => "Adjusted word-degree z-score",
        :column => "Adjusted column-normalized z-score",
        :delta => "Adjusted Δz"
    ),

    # ========================================================
    # LEGEND
    # ========================================================

    show_legend = true,

    # Relative coordinates:
    # (0,0) = bottom-left of plotting area
    # (1,1) = top-right of plotting area
    # Values outside [0,1] can place the legend outside.
    #
    # Examples:
    # (0.98, 0.98) = near top-right
    # (0.02, 0.98) = near top-left
    # (1.05, 0.95) = outside on the right
    legend_position = (0.98, 0.98),

    # Legend anchor: which part of the legend is placed
    # at legend_position.
    # :right, :left, :center
    legend_anchor = :right,

    legend_labels = Dict(
        "homophily_0_learning1_0_9" => "β = 0, Learning = 0.9",
        "homophily_0_learning1_0_5" => "β = 0, Learning = 0.5",
        "homophily_3_learning1_0_9" => "β = 3, Learning = 0.9",
        "homophily_3_learning1_0_5" => "β = 3, Learning = 0.5"
    ),

    regression_label = "Adjusted regression",

    # ========================================================
    # AXES
    # ========================================================

    # true = same X and Y limits across timepoints
    # for each metric separately.
    shared_axes = true,

    # nothing = automatic limits
    # Or set manually, e.g. (-3.0, 3.0)
    xlims_override = nothing,

    # Manual Y limits for individual metrics.
    # nothing = automatic limits
    # Example: :delta => (-2.0, 2.0)
    ylims_override = Dict(
        :degree => nothing,
        :column => nothing,
        :delta => nothing
    ),

    axis_padding = 0.05,

    # ========================================================
    # APPEARANCE
    # ========================================================

    plot_size = (780, 580),
    fontfamily = "Calibri",
    point_size = 3.5,
    point_alpha = 0.35,
    line_width = 3.0,
    show_grid = true,
    show_plots = true)

    # ========================================================
    # 1. Load and merge data
    # ========================================================

    semantic = JLD2.load(semantic_path, "results")
    social = JLD2.load(social_path, "results")

    semantic.delta_z =
        semantic.column_normalized_distance_from_mean_z .-
        semantic.word_degree_distance_from_mean_z

    keys = [
        :condition,
        :run_number,
        :focal_agent,
        :timepoint,
        :saved_step
    ]

    df = DataFrames.innerjoin(
        semantic,
        social;
        on = keys,
        makeunique = true
    )

    DataFrames.nrow(df) == DataFrames.nrow(semantic) ||
        error("Some semantic observations have no matching social data.")

    if conditions !== :all

        selected_conditions =
            conditions isa AbstractString ?
            [conditions] :
            collect(conditions)

        available_conditions = unique(df.condition)

        unknown_conditions = setdiff(
            selected_conditions,
            available_conditions
        )

        isempty(unknown_conditions) ||
            error("Unknown conditions: $(unknown_conditions)")

        df = df[
            in.(df.condition, Ref(selected_conditions)),
            :
        ]
    end

    # ========================================================
    # 2. Metric definitions
    # ========================================================

    metrics = [
        (
            id = :degree,
            column = :word_degree_distance_from_mean_z,
            label = "Word-degree distribution"
        ),
        (
            id = :column,
            column = :column_normalized_distance_from_mean_z,
            label = "Column-normalized distribution"
        ),
        (
            id = :delta,
            column = :delta_z,
            label = "Δz"
        )
    ]

    metric_ids = Set(m.id for m in metrics)

    selected_plot_metrics =
        plot_metrics === :all ?
        collect(metric_ids) :
        plot_metrics isa Symbol ?
        [plot_metrics] :
        collect(plot_metrics)

    unknown_metrics = setdiff(
        selected_plot_metrics,
        collect(metric_ids)
    )

    isempty(unknown_metrics) ||
        error("Unknown plot metrics: $unknown_metrics")

    condition_styles = [
        (
            name = "homophily_0_learning1_0_9",
            color = :royalblue
        ),
        (
            name = "homophily_0_learning1_0_5",
            color = :darkorange
        ),
        (
            name = "homophily_3_learning1_0_9",
            color = :seagreen
        ),
        (
            name = "homophily_3_learning1_0_5",
            color = :firebrick
        )
    ]

    # ========================================================
    # 3. Results
    # ========================================================

    coefficient_results = DataFrames.DataFrame(
        timepoint = String[],
        metric = String[],
        predictor = String[],
        estimate = Float64[],
        HC3_SE = Float64[],
        z_value = Float64[],
        p_value = Float64[],
        ci_lower = Float64[],
        ci_upper = Float64[]
    )

    model_results = DataFrames.DataFrame(
        timepoint = String[],
        metric = String[],
        n = Int[],
        r_squared = Float64[],
        adjusted_r_squared = Float64[],
        social_coefficient = Float64[],
        social_HC3_SE = Float64[],
        social_p_value = Float64[]
    )

    plots = Dict{Tuple{String,String},Any}()
    models = Dict{Tuple{String,String},Any}()
    plot_data = Dict{Tuple{Symbol,String},Any}()

    normal = Distributions.Normal()
    zcrit = Distributions.quantile(normal, 0.975)

    # ========================================================
    # 4. Fit models using OLS + HC3
    # ========================================================

    for tp in timepoints

        tp_label =
            tp == "post_0" ? "Crossing" :
            tp == "post_100" ? "Final" : tp

        for metric in metrics

            sub = df[df.timepoint .== tp, :]

            valid = [
                all(
                    v -> !ismissing(v) && isfinite(v),
                    (
                        row[metric.column],
                        row.conversations_z,
                        row.mean_distance_from_others_z
                    )
                )
                for row in eachrow(sub)
            ]

            sub = sub[valid, :]

            n = DataFrames.nrow(sub)

            n > 3 ||
                error(
                    "Insufficient observations for $tp / $(metric.label)"
                )

            y = Float64.(sub[!, metric.column])
            x_social = Float64.(sub.conversations_z)
            x_original = Float64.(sub.mean_distance_from_others_z)

            X = hcat(
                ones(n),
                x_social,
                x_original
            )

            p = size(X, 2)

            LinearAlgebra.rank(X) == p ||
                error(
                    "Design matrix is rank deficient: " *
                    "$tp / $(metric.label)"
                )

            # OLS
            beta = X \ y

            fitted = X * beta
            residuals = y - fitted

            XtX_inv = inv(transpose(X) * X)

            # HC3
            leverage = vec(
                sum((X * XtX_inv) .* X; dims = 2)
            )

            all(leverage .< 1.0) ||
                error("HC3 cannot be computed: leverage >= 1.")

            hc3_weights = (
                residuals ./ (1.0 .- leverage)
            ) .^ 2

            meat = transpose(X) * (
                X .* reshape(hc3_weights, :, 1)
            )

            V_HC3 = XtX_inv * meat * XtX_inv

            V_HC3 = (
                V_HC3 + transpose(V_HC3)
            ) ./ 2

            variances = LinearAlgebra.diag(V_HC3)

            all(variances .> 0.0) ||
                error(
                    "Non-positive HC3 variance: " *
                    "$tp / $(metric.label)"
                )

            errors = sqrt.(variances)
            zvalues = beta ./ errors

            pvalues = [
                2 * Distributions.ccdf(normal, abs(z))
                for z in zvalues
            ]

            ci_lower = beta .- zcrit .* errors
            ci_upper = beta .+ zcrit .* errors

            key = (tp, string(metric.column))

            models[key] = (
                beta = beta,
                V_HC3 = V_HC3,
                HC3_SE = errors,
                z_values = zvalues,
                p_values = pvalues,
                residuals = residuals,
                fitted = fitted,
                X = X,
                y = y
            )

            coefficient_names = [
                "Intercept",
                "Social z-score",
                "Original semantic atypicality"
            ]

            for i in eachindex(beta)

                push!(coefficient_results, (
                    tp_label,
                    metric.label,
                    coefficient_names[i],
                    beta[i],
                    errors[i],
                    zvalues[i],
                    pvalues[i],
                    ci_lower[i],
                    ci_upper[i]
                ))
            end

            sst = sum(
                (y .- Statistics.mean(y)) .^ 2
            )

            r2 = sst > 0 ?
                1 - sum(residuals .^ 2) / sst :
                NaN

            adjusted_r2 = sst > 0 ?
                1 - (1 - r2) * (n - 1) / (n - p) :
                NaN

            push!(model_results, (
                tp_label,
                metric.label,
                n,
                r2,
                adjusted_r2,
                beta[2],
                errors[2],
                pvalues[2]
            ))

            # ====================================================
            # Prepare adjusted plot data
            # ====================================================

            original_mean = Statistics.mean(x_original)

            adjusted_y =
                y .-
                beta[3] .* (x_original .- original_mean)

            x_line = range(
                minimum(x_social),
                maximum(x_social);
                length = 200
            )

            fitted_line =
                beta[1] .+
                beta[2] .* x_line .+
                beta[3] * original_mean

            plot_data[(metric.id, tp)] = (
                sub = sub,
                x = x_social,
                adjusted_y = adjusted_y,
                x_line = collect(x_line),
                fitted_line = collect(fitted_line)
            )
        end
    end

    # ========================================================
    # 5. Determine common axes
    # ========================================================

    function padded_limits(values, padding)
        lo = minimum(values)
        hi = maximum(values)

        width = hi - lo

        if width == 0
            width = max(abs(lo), 1.0)
        end

        return (
            lo - padding * width,
            hi + padding * width
        )
    end

    common_xlims = nothing

    if shared_axes && xlims_override === nothing

        all_x = Float64[]

        for tp in timepoints
            append!(
                all_x,
                plot_data[(:degree, tp)].x
            )
        end

        common_xlims = padded_limits(all_x, axis_padding)
    end

    common_ylims = Dict{Symbol,Tuple{Float64,Float64}}()

    if shared_axes

        for metric in metrics

            all_y = Float64[]

            for tp in timepoints

                d = plot_data[(metric.id, tp)]

                append!(all_y, d.adjusted_y)
                append!(all_y, d.fitted_line)
            end

            common_ylims[metric.id] =
                padded_limits(all_y, axis_padding)
        end
    end

    # ========================================================
    # 6. Draw selected graphs
    # ========================================================

    for tp in timepoints

        for metric in metrics

            metric.id in selected_plot_metrics || continue

            d = plot_data[(metric.id, tp)]

            title_text = show_titles ?
                get(
                    plot_titles,
                    (metric.id, tp),
                    "$tp — $(metric.label)"
                ) :
                ""

            # X limits
            xlimits =
                xlims_override !== nothing ?
                xlims_override :
                shared_axes ?
                common_xlims :
                padded_limits(d.x, axis_padding)

            # Y limits
            manual_ylim = get(
                ylims_override,
                metric.id,
                nothing
            )

            ylimits =
                manual_ylim !== nothing ?
                manual_ylim :
                shared_axes ?
                common_ylims[metric.id] :
                padded_limits(
                    vcat(d.adjusted_y, d.fitted_line),
                    axis_padding
                )

            graph = Plots.plot(
                ;
                title = title_text,
                titlefontsize = titlefontsize,
                xlabel = xlabel,
                ylabel = get(
                    ylabels,
                    metric.id,
                    "Adjusted semantic z-score"
                ),
                guidefontsize = guidefontsize,
                tickfontsize = tickfontsize,
                legendfontsize = legendfontsize,
                size = plot_size,
                fontfamily = fontfamily,
                xlims = xlimits,
                ylims = ylimits,
                grid = show_grid,
                legend = show_legend ?
                    legend_position :
                    false,
                legend_column = 1
            )

            # Points by condition
            for style in condition_styles

                mask = d.sub.condition .== style.name

                if !any(mask)
                    continue
                end

                Plots.scatter!(
                    graph,
                    d.x[mask],
                    d.adjusted_y[mask];
                    color = style.color,
                    label = get(
                        legend_labels,
                        style.name,
                        style.name
                    ),
                    markersize = point_size,
                    markeralpha = point_alpha,
                    markerstrokewidth = 0
                )
            end

            # Adjusted regression
            Plots.plot!(
                graph,
                d.x_line,
                d.fitted_line;
                color = :black,
                linewidth = line_width,
                label = regression_label
            )

            # Legend anchor adjustment
            # For PlotlyJS-backed Plots, this controls the
            # legend's horizontal alignment.
            if show_legend &&
               Plots.backend() isa Plots.PlotlyJSBackend

                xanchor =
                    legend_anchor == :left ? "left" :
                    legend_anchor == :center ? "center" :
                    "right"

                graph.plotattributes[:legend_anchor] = xanchor
            end

            key = (tp, string(metric.column))
            plots[key] = graph

            if show_plots
                display(graph)
            end
        end
    end

    # ========================================================
    # 7. Print results
    # ========================================================

    println("\n========== MODEL SUMMARY — HC3 ==========")

    Base.show(
        stdout,
        MIME("text/plain"),
        model_results;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println("\n\n========== REGRESSION COEFFICIENTS — HC3 ==========")

    Base.show(
        stdout,
        MIME("text/plain"),
        coefficient_results;
        allrows = true,
        allcols = true,
        truncate = 0
    )

    println(
        "\n\nInference: two-sided asymptotic normal tests " *
        "and 95% Wald confidence intervals using HC3 standard errors."
    )

    return (
        model_summary = model_results,
        coefficients = coefficient_results,
        models = models,
        plots = plots,
        data = df
    )
end
