# הקשר בין דרגות לשכיחות
function conversation_word_tracking!(
    group,
    world::World,
    L::Int,
    word_counts::AbstractMatrix{Int32},
    speaking_steps::AbstractVector{Int32};
    social_impact = 1,
    social_learning_prob = ones(Float32, world.N))
    n = world.n
    members = shuffle(group)
    speakers = Int[]
    sizehint!(speakers, length(members))

    @inbounds for m in members
        if !world.silent[m]
            push!(speakers, m)
        end
    end

    if length(speakers) < 2
        return true
    end

    speaker = 1
    cue = sample(
        1:n,
        Weights(@view world.colsum[:, speakers[1]])
    )

    # Tracks who actually produced at least one word
    # during this conversation step.
    spoke = falses(world.N)

    for _ in 1:L
        if speaker == length(speakers)
            speaker = 1
        else
            speaker += 1
        end

        speaker_id = speakers[speaker]

        association = sample(
            1:n,
            Weights(@view world.agents[:, cue, speaker_id])
        )

        # Count only the word actually produced by the speaker.
        word_counts[association, speaker_id] += 1
        spoke[speaker_id] = true

        @inbounds for member in members
            is_speaker = member == speaker_id

            if is_speaker || rand() < social_learning_prob[member]
                world.agents[association, cue, member] += social_impact
                world.agents[cue, association, member] += social_impact

                world.agent_sum[member] += 2.0f0 * social_impact
                world.colsum[cue, member] += 1.0f0 * social_impact
                world.colsum[association, member] += 1.0f0 * social_impact
            end
        end

        cue = association
    end

    @inbounds for i in speakers
        if spoke[i]
            speaking_steps[i] += 1
        end
    end

    return false
end
function self_conversation_word_tracking!(
    i::Int,
    world::World,
    L::Int,
    word_counts::AbstractMatrix{Int32},
    thinking_steps::AbstractVector{Int32})
    n = world.n

    cue = sample(
        1:n,
        Weights(@view world.colsum[:, i])
    )

    for _ in 1:L
        association = sample(
            1:n,
            Weights(@view world.agents[:, cue, i])
        )

        # Count the word produced in self-conversation.
        word_counts[association, i] += 1

        world.agents[association, cue, i] += 1.0f0
        world.agents[cue, association, i] += 1.0f0

        world.agent_sum[i] += 2.0f0
        world.colsum[cue, i] += 1.0f0
        world.colsum[association, i] += 1.0f0

        cue = association
    end

    # One self-conversation call represents one thinking step.
    thinking_steps[i] += 1

    return nothing
end
function step_word_tracking!(
    world::World,
    conversation_words::AbstractMatrix{Int32},
    self_talk_words::AbstractMatrix{Int32},
    speaking_steps::AbstractVector{Int32},
    thinking_steps::AbstractVector{Int32};
    talk_duration::Int = 5,
    refractory_duration::Int = 10,
    self_talk_threshold::Int = 10,
    L::Int = 10,
    eta::Float32 = 0.5f0,
    beta_for_consent::Real = 10.0,
    gamma::Union{Nothing,Real} = nothing,
    beta::Union{Nothing,Real} = nothing,
    delta::Union{Nothing,Real} = nothing,
    p0::Union{Nothing,Real} = nothing,
    pmin::Real = 0.05,
    record_distances::Bool = false,
    record_every::Int = 100,
    social_impact::Float64 = 1.0,
    join_rule::Symbol = :group_any,
    social_learning_prob = ones(Float32, world.N))
    # Update parameters
    if gamma !== nothing
        world.γ = Float32(gamma)
    end
    if beta !== nothing
        world.β = Float32(beta)
    end
    if delta !== nothing
        world.δ = Float32(delta)
    end
    if p0 !== nothing
        world.p0 = Float32(p0)
    end
    if beta_for_consent !== nothing
        world.beta_for_consent = Float32(beta_for_consent)
    end

    world.t += 1

    # ========================================================
    # 1. Group conversation phase
    # ========================================================

    group_ids = unique(world.talking_group)
    talked_groups = Vector{Vector{Int}}()

    for gid in group_ids
        gid == 0 && continue

        members = [
            i for i in 1:world.N
            if world.talking_group[i] == gid
        ]

        Lm = length(members)

        if Lm < 2
            if Lm == 1
                if world.talk_left[members[1]] > 0
                    mark_abandonment!(world, members[1])
                end

                end_conversation_for_agent!(
                    world,
                    members[1],
                    refractory_duration
                )
            end
            continue
        end

        all_silent = true
        nspeakers = 0

        @inbounds for m in members
            if !world.silent[m]
                nspeakers += 1
                if nspeakers >= 2
                    all_silent = false
                    break
                end
            end
        end

        if all_silent
            @inbounds for m in members
                for other in members
                    if m != other
                        push!(world.agent_seen_partners[m], other)
                    end
                end

                if world.talk_left[m] > 0
                    mark_abandonment!(world, m)
                end

                end_conversation_for_agent!(
                    world,
                    m,
                    refractory_duration
                )
            end
            continue
        end

        push!(talked_groups, members)

        speakers = Int[]
        @inbounds for m in members
            if !world.silent[m]
                push!(speakers, m)
            end
        end

        log_conversation!(
            world;
            gid = gid,
            members = copy(members),
            speakers = copy(speakers)
        )

        conversation_word_tracking!(
            members,
            world,
            L,
            conversation_words,
            speaking_steps;
            social_impact = social_impact,
            social_learning_prob = social_learning_prob
        )

        for i in members
            world.talk_left[i] -= 1
        end
    end

    # End conversations and refractory check
    for i in 1:world.N
        if world.talking_group[i] != 0 &&
           world.talk_left[i] <= 0

            end_conversation_for_agent!(
                world,
                i,
                refractory_duration
            )
        end
    end

    # ========================================================
    # 2. Self-conversation phase
    # ========================================================

    for i in 1:world.N
        if world.talking_group[i] == 0

            if world.self_talk_left[i] > 0

                self_conversation_word_tracking!(
                    i,
                    world,
                    L,
                    self_talk_words,
                    thinking_steps
                )

                world.self_talk_count[i] += 1
                world.self_talk_left[i] -= 1

            else
                world.time_since_last_talk[i] += 1

                if world.time_since_last_talk[i] >=
                   self_talk_threshold

                    world.self_talk_left[i] = 3

                    self_conversation_word_tracking!(
                        i,
                        world,
                        L,
                        self_talk_words,
                        thinking_steps
                    )

                    world.self_talk_count[i] += 1
                    world.self_talk_left[i] -= 1
                    world.time_since_last_talk[i] = 0
                end
            end

        else
            world.time_since_last_talk[i] = 0
        end
    end

    # ========================================================
    # 3. Semantic perception updates
    # ========================================================

    if eta != 0.0f0
        for group in talked_groups
            update_perceived_group!(
                world,
                group;
                eta = eta
            )
        end
    end

    if record_distances &&
       (world.t % record_every == 0)

        world.current_distances .=
            Float32.(differences(world.agents))

        push!(
            world.distances_history,
            copy(world.current_distances)
        )

        push!(
            world.perceived_distance_history,
            copy(world.perceived_distance)
        )
    end

    # ========================================================
    # 4. Movement and adjacency
    # ========================================================

    move_agents!(world)
    update_adjacency!(world.adjacency_count, world)

    # ========================================================
    # 5. Social interaction initiation
    # ========================================================

    form_conversations!(
        world;
        talk_duration = talk_duration,
        pmin = pmin,
        p0 = p0,
        join_rule = join_rule
    )

    update_talk_episodes!(world)

    # ========================================================
    # 6. Refractory period
    # ========================================================

    for i in 1:world.N
        if !isempty(world.refr_partners[i])
            tick_refractory!(
                world.refr_partners,
                world.refr_left,
                i
            )
        end
    end

    # ========================================================
    # 7. Longitudinal logging
    # ========================================================

    push!(world.unique_partners_steps, world.t)

    current_unique_counts = [
        count(
            >(0),
            view(world.talk_episode_count, i, :)
        )
        for i in 1:world.N
    ]

    push!(
        world.unique_partners_history,
        current_unique_counts
    )

    return nothing
end
function run_one_word_frequency_simulation(;
    seed::Int,
    homophily::Real,
    agent1_learning::Real,
    other_agents_learning::Real = 0.9,

    N::Int = 20,
    W::Int = 30,
    H::Int = 30,
    n::Int = 300,
    m::Int = 4,
    change::Float64 = 0.7,

    outliers_count::Int = 0,
    outlier_change::Float64 = 0.71,
    abandonment_threshold::Int = 2_000_000,

    isolated_agent = nothing,
    isolated_agent_interaction_prob = nothing,

    steps::Int = 20_000,
    record_every::Int = 100,
    reset_every::Int = 100,

    talk_duration::Int = 10,
    refractory_duration::Int = 10,
    self_talk_threshold::Int = 10,
    L::Int = 25,
    eta::Float32 = 0.2f0,

    gamma::Real = 0.0,
    beta::Real = 1.0,
    delta::Real = 1.0,
    p0::Real = 0.5,
    pmin::Real = 0.05,
    social_impact::Real = 1.0,
    join_rule::Symbol = :group_any)
    @assert steps > 0
    @assert record_every > 0
    @assert reset_every > 0
    @assert steps % record_every == 0
    @assert N >= 1
    @assert 0 <= agent1_learning <= 1
    @assert 0 <= other_agents_learning <= 1

    Random.seed!(seed)

    world = init_world(
        N, W, H, n, m, change;
        abandonment_threshold = abandonment_threshold,
        outliers_count = outliers_count,
        outlier_change = outlier_change,
        isolated_agent = isolated_agent,
        isolated_agent_interaction_prob =
            isolated_agent_interaction_prob
    )

    social_learning_prob =
        fill(Float32(other_agents_learning), N)

    social_learning_prob[1] = Float32(agent1_learning)

    T = div(steps, record_every)

    # Dimensions: word × agent × time window
    column_sums = Array{Float32}(undef, n, N, T)
    conversation_words = zeros(Int32, n, N, T)
    self_talk_words = zeros(Int32, n, N, T)

    # Dimensions: agent × time window
    speaking_steps = zeros(Int32, N, T)
    thinking_steps = zeros(Int32, N, T)

    window_start_steps = collect(
        0:record_every:(steps - record_every)
    )

    window_end_steps = collect(
        record_every:record_every:steps
    )

    # Save initial column sums, before step 1.
    column_sums[:, :, 1] .= world.colsum

    for t in 1:steps

        # Preserve the original reset timing.
        if t % reset_every == 0
            reset_positions_and_interactions!(world)
        end

        window_idx = cld(t, record_every)

        step_word_tracking!(
            world,
            @view(conversation_words[:, :, window_idx]),
            @view(self_talk_words[:, :, window_idx]),
            @view(speaking_steps[:, window_idx]),
            @view(thinking_steps[:, window_idx]);

            talk_duration = talk_duration,
            refractory_duration = refractory_duration,
            self_talk_threshold = self_talk_threshold,
            L = L,
            eta = eta,
            beta_for_consent = homophily,
            gamma = gamma,
            beta = beta,
            delta = delta,
            p0 = p0,
            pmin = pmin,
            record_distances = false,
            record_every = record_every,
            social_impact = Float64(social_impact),
            join_rule = join_rule,
            social_learning_prob = social_learning_prob
        )

        # At the end of this window, save the network
        # state for the NEXT window.
        if t % record_every == 0 && t < steps
            next_window = window_idx + 1

            column_sums[:, :, next_window] .=
                world.colsum
        end
    end

    # Verify that every produced word is counted.
    # Each conversation or self-talk step produces L words
    # across its participating speakers / agent.
    for window_idx in 1:T

        expected_self_words =
            Int64(L) * sum(
                @view thinking_steps[:, window_idx]
            )

        actual_self_words = sum(
            @view self_talk_words[:, :, window_idx]
        )

        actual_self_words == expected_self_words ||
            error(
                "Self-talk word-count mismatch " *
                "in window $window_idx"
            )
    end

    return (
        column_sums = column_sums,
        conversation_words = conversation_words,
        self_talk_words = self_talk_words,
        speaking_steps = speaking_steps,
        thinking_steps = thinking_steps,
        window_start_steps = window_start_steps,
        window_end_steps = window_end_steps,
        social_learning_prob = social_learning_prob
    )
end
function build_word_frequency_bank(
    conditions;
    target_runs::Int = 50,
    bank_dir::String = "word_frequency_bank",

    other_agents_learning::Real = 0.9,

    N::Int = 20,
    W::Int = 30,
    H::Int = 30,
    n::Int = 300,
    m::Int = 4,
    change::Float64 = 0.7,

    outliers_count::Int = 0,
    outlier_change::Float64 = 0.71,
    abandonment_threshold::Int = 2_000_000,

    isolated_agent = nothing,
    isolated_agent_interaction_prob = nothing,

    steps::Int = 20_000,
    record_every::Int = 100,
    reset_every::Int = 100,

    talk_duration::Int = 10,
    refractory_duration::Int = 10,
    self_talk_threshold::Int = 10,
    L::Int = 25,
    eta::Float32 = 0.2f0,

    gamma::Real = 0.0,
    beta::Real = 1.0,
    delta::Real = 1.0,
    p0::Real = 0.5,
    pmin::Real = 0.05,
    social_impact::Real = 1.0,
    join_rule::Symbol = :group_any,

    verbose::Bool = true)
    @assert target_runs >= 1
    @assert steps > 0
    @assert record_every >= 1
    @assert reset_every >= 1
    @assert steps % record_every == 0

    mkpath(bank_dir)

    # Match the naming convention used in the previous bank.
    condition_name(c) =
        "homophily_$(replace(string(c.homophily), "." => "_"))" *
        "_learning1_$(replace(string(c.agent1_learning), "." => "_"))"

    # Normalize numeric names so 3 and 3.0 are equivalent.
    function format_condition_number(x)
        s = string(Float64(x))
        return replace(s, r"\.0$" => "")
    end

    function make_name(c)
        h = format_condition_number(c.homophily)
        l = replace(string(Float64(c.agent1_learning)), "." => "_")
        return "homophily_$(h)_learning1_$(l)"
    end

    names = [make_name(c) for c in conditions]

    length(unique(names)) == length(names) ||
        error("Duplicate conditions supplied.")

    for (condition_index, condition) in enumerate(conditions)

        homophily = Float64(condition.homophily)
        agent1_learning = Float64(condition.agent1_learning)
        name = make_name(condition)

        # Only exact filenames belonging to this condition.
        pattern = Regex(
            "^" * name * "_run_([0-9]+)\\.jld2\$"
        )

        existing_numbers = Set{Int}()

        for filename in readdir(bank_dir)
            match_result = match(pattern, filename)

            if match_result !== nothing
                push!(
                    existing_numbers,
                    parse(Int, match_result.captures[1])
                )
            end
        end

        missing_numbers = [
            run_number
            for run_number in 1:target_runs
            if !(run_number in existing_numbers)
        ]

        if verbose
            println()
            println("="^65)
            println(
                "CONDITION ",
                condition_index,
                " / ",
                length(conditions),
                ": ",
                name
            )
            println("Homophily: ", homophily)
            println("Agent 1 learning: ", agent1_learning)
            println(
                "Other agents learning: ",
                other_agents_learning
            )
            println(
                "Existing runs within target: ",
                target_runs - length(missing_numbers),
                " / ",
                target_runs
            )
            println(
                "Runs to generate: ",
                length(missing_numbers)
            )
            println("="^65)
        end

        if isempty(missing_numbers)
            verbose && println("Condition already complete.")
            continue
        end

        for (run_index, run_number) in enumerate(missing_numbers)

            filename = string(
                name,
                "_run_",
                lpad(string(run_number), 3, '0'),
                ".jld2"
            )

            path = joinpath(bank_dir, filename)

            isfile(path) &&
                error("Refusing to overwrite existing file: $path")

            seed = rand(1:typemax(Int32))

            if verbose
                println()
                println(
                    "Running ",
                    run_index,
                    " / ",
                    length(missing_numbers),
                    " | run number ",
                    run_number,
                    " | seed ",
                    seed
                )
            end

            elapsed = @elapsed begin

                result = run_one_word_frequency_simulation(
                    seed = seed,
                    homophily = homophily,
                    agent1_learning = agent1_learning,
                    other_agents_learning =
                        other_agents_learning,

                    N = N,
                    W = W,
                    H = H,
                    n = n,
                    m = m,
                    change = change,

                    outliers_count = outliers_count,
                    outlier_change = outlier_change,
                    abandonment_threshold =
                        abandonment_threshold,

                    isolated_agent = isolated_agent,
                    isolated_agent_interaction_prob =
                        isolated_agent_interaction_prob,

                    steps = steps,
                    record_every = record_every,
                    reset_every = reset_every,

                    talk_duration = talk_duration,
                    refractory_duration =
                        refractory_duration,
                    self_talk_threshold =
                        self_talk_threshold,
                    L = L,
                    eta = eta,

                    gamma = gamma,
                    beta = beta,
                    delta = delta,
                    p0 = p0,
                    pmin = pmin,
                    social_impact = social_impact,
                    join_rule = join_rule
                )

                metadata = (
                    condition = name,
                    run_number = run_number,
                    seed = seed,

                    homophily = homophily,
                    agent1_learning = agent1_learning,
                    other_agents_learning =
                        Float64(other_agents_learning),
                    social_learning_prob =
                        result.social_learning_prob,

                    N = N,
                    W = W,
                    H = H,
                    n = n,
                    m = m,
                    change = change,

                    outliers_count = outliers_count,
                    outlier_change = outlier_change,
                    abandonment_threshold =
                        abandonment_threshold,

                    isolated_agent = isolated_agent,
                    isolated_agent_interaction_prob =
                        isolated_agent_interaction_prob,

                    steps = steps,
                    record_every = record_every,
                    reset_every = reset_every,

                    talk_duration = talk_duration,
                    refractory_duration =
                        refractory_duration,
                    self_talk_threshold =
                        self_talk_threshold,
                    L = L,
                    eta = eta,

                    gamma = gamma,
                    beta = beta,
                    delta = delta,
                    p0 = p0,
                    pmin = pmin,
                    social_impact = social_impact,
                    join_rule = join_rule,

                    word_count_definition =
                        "Produced association words only",

                    column_sum_timing =
                        "Beginning of each observation window",

                    activity_count_definition =
                        "Number of steps with actual word production"
                )

                # Save to a temporary file first, then rename.
                # This avoids leaving a partially written final file.
                temp_path = path * ".tmp"

                isfile(temp_path) && rm(temp_path)

                try
                    JLD2.jldopen(
                        temp_path,
                        "w";
                        iotype = IOStream
                    ) do f

                        f["column_sums"] =
                            result.column_sums

                        f["conversation_words"] =
                            result.conversation_words

                        f["self_talk_words"] =
                            result.self_talk_words

                        f["speaking_steps"] =
                            result.speaking_steps

                        f["thinking_steps"] =
                            result.thinking_steps

                        f["window_start_steps"] =
                            result.window_start_steps

                        f["window_end_steps"] =
                            result.window_end_steps

                        f["metadata"] = metadata
                    end

                    mv(temp_path, path; force = false)

                catch
                    isfile(temp_path) && rm(temp_path)
                    rethrow()
                end
            end

            if verbose
                println(
                    "  -> SAVED: ",
                    filename
                )
                println(
                    "     Elapsed: ",
                    round(elapsed; digits = 1),
                    " seconds"
                )
                println(
                    "     File size: ",
                    round(filesize(path) / 1e6; digits = 2),
                    " MB"
                )
            end
        end

        verbose && println(
            "\nCondition complete: ",
            name,
            " (",
            target_runs,
            " / ",
            target_runs,
            " requested runs)"
        )
    end

    println()
    println("All requested conditions are complete.")
    println("Bank folder: ", abspath(bank_dir))

    return nothing
end
# conditions = [
#     (homophily = 0.0, agent1_learning = 0.9),
#     (homophily = 3.0, agent1_learning = 0.9),
#     (homophily = 3.0, agent1_learning = 0.5),
#     (homophily = 0.0, agent1_learning = 0.5)
# ]
# word_frequency_dir = joinpath(
#     bank_dir,
#     "word_frequency_bank"
# )
# build_word_frequency_bank(
#     conditions;
#     target_runs = 50,
#     bank_dir = word_frequency_dir,
#     other_agents_learning = 0.9
# )

function build_word_frequency_correlations(
    bank_dir::String;
    output_path::String = joinpath(
        bank_dir,
        "word_frequency_correlations.jld2"
    ),
    save_every::Int = 10,
    verbose::Bool = true)

    @assert save_every >= 1

    mkpath(dirname(output_path))

    # ========================================================
    # 1. Find simulation files
    # ========================================================

    pattern = r"^(.*)_run_(\d+)\.jld2$"

    simulation_files = NamedTuple[]

    for filename in readdir(bank_dir)

        m = match(pattern, filename)

        m === nothing && continue

        condition = String(m.captures[1])
        run_number = parse(Int, m.captures[2])

        push!(
            simulation_files,
            (
                condition = condition,
                run_number = run_number,
                filename = filename,
                path = joinpath(bank_dir, filename)
            )
        )
    end

    sort!(
        simulation_files;
        by = x -> (x.condition, x.run_number)
    )

    isempty(simulation_files) &&
        error("No simulation files found in: $bank_dir")

    # ========================================================
    # 2. Load existing results or create empty table
    # ========================================================

    function empty_results()

        return DataFrames.DataFrame(
            condition = String[],
            run_number = Int[],
            agent = Int[],
            window = Int[],
            start_step = Int[],
            end_step = Int[],

            # Personal degree vector vs produced words
            personal_conversation_r = Float64[],
            personal_self_talk_r = Float64[],

            # General degree vector vs produced words
            general_conversation_r = Float64[],
            general_self_talk_r = Float64[],

            # Number of active steps in each window
            speaking_steps = Int[],
            thinking_steps = Int[]
        )
    end

    if isfile(output_path)

        results = JLD2.load(output_path, "results")

        verbose && println(
            "Loaded existing summary: ",
            DataFrames.nrow(results),
            " rows."
        )

    else
        results = empty_results()

        verbose && println(
            "No existing summary found. Starting a new one."
        )
    end

    # ========================================================
    # 3. Identify completed runs
    # ========================================================

    completed_runs = Set{Tuple{String,Int}}()

    if DataFrames.nrow(results) > 0

        grouped = DataFrames.groupby(
            results,
            [:condition, :run_number]
        )

        for g in grouped

            condition = String(g.condition[1])
            run_number = Int(g.run_number[1])

            # Count unique agent × window observations.
            # Only complete runs are considered finished.
            expected_agents = maximum(g.agent)
            expected_windows = maximum(g.window)

            expected_rows =
                expected_agents * expected_windows

            unique_rows = length(
                unique(
                    zip(g.agent, g.window)
                )
            )

            if DataFrames.nrow(g) == expected_rows &&
               unique_rows == expected_rows

                push!(
                    completed_runs,
                    (condition, run_number)
                )
            end
        end
    end

    pending_files = [
        file for file in simulation_files
        if !(
            (file.condition, file.run_number)
            in completed_runs
        )
    ]

    if verbose
        println()
        println("========================================")
        println("Total simulation files: ", length(simulation_files))
        println("Completed runs: ", length(simulation_files) - length(pending_files))
        println("Runs to process: ", length(pending_files))
        println("Save every: ", save_every, " new runs")
        println("========================================")
    end

    # ========================================================
    # 4. Pearson correlation helper
    # ========================================================

    # Computes Pearson r without allocating centered vectors.
    # Returns NaN when either vector has zero variance.

    function pearson_r(
        x::AbstractVector,
        y::AbstractVector
    )
        n = length(x)

        length(y) == n ||
            throw(DimensionMismatch("Vectors must have equal length."))

        sx = 0.0
        sy = 0.0
        sxx = 0.0
        syy = 0.0
        sxy = 0.0

        @inbounds for k in eachindex(x, y)

            a = Float64(x[k])
            b = Float64(y[k])

            sx += a
            sy += b

            sxx += a * a
            syy += b * b
            sxy += a * b
        end

        vx = sxx - sx^2 / n
        vy = syy - sy^2 / n

        if vx <= 0.0 || vy <= 0.0
            return NaN
        end

        covariance = sxy - sx * sy / n

        r = covariance / sqrt(vx * vy)

        return clamp(r, -1.0, 1.0)
    end

    # ========================================================
    # 5. Save helper
    # ========================================================

    function save_results!()

        # Write to a temporary file, then replace the summary.
        # Only the summary table is kept in memory.

        temp_path = output_path * ".tmp"

        isfile(temp_path) && rm(temp_path)

        try
            JLD2.jldopen(
                temp_path,
                "w";
                iotype = IOStream
            ) do f

                f["results"] = results

                f["metadata"] = (
                    correlation = "Pearson",
                    degree_measure = "Column sums",
                    general_degree =
                        "Sum of column-sum vectors across all agents, including focal agent",
                    word_measure =
                        "Raw counts of produced association words",
                    invalid_correlation = "NaN",
                    unit = "Agent × time window",
                    source_directory = abspath(bank_dir)
                )
            end

            mv(temp_path, output_path; force = true)

        catch
            isfile(temp_path) && rm(temp_path)
            rethrow()
        end

        return nothing
    end

    # ========================================================
    # 6. Process missing simulations
    # ========================================================

    new_runs = 0

    for (file_index, file) in enumerate(pending_files)

        verbose && println(
            "\n[",
            file_index,
            "/",
            length(pending_files),
            "] ",
            file.filename
        )

        d = JLD2.load(file.path)

        column_sums = d["column_sums"]
        conversation_words = d["conversation_words"]
        self_talk_words = d["self_talk_words"]

        speaking_steps = d["speaking_steps"]
        thinking_steps = d["thinking_steps"]

        start_steps = d["window_start_steps"]
        end_steps = d["window_end_steps"]

        n, N, T = size(column_sums)

        size(conversation_words) == (n, N, T) ||
            error("Invalid conversation_words dimensions: $(file.filename)")

        size(self_talk_words) == (n, N, T) ||
            error("Invalid self_talk_words dimensions: $(file.filename)")

        size(speaking_steps) == (N, T) ||
            error("Invalid speaking_steps dimensions: $(file.filename)")

        size(thinking_steps) == (N, T) ||
            error("Invalid thinking_steps dimensions: $(file.filename)")

        length(start_steps) == T ||
            error("Invalid window_start_steps: $(file.filename)")

        length(end_steps) == T ||
            error("Invalid window_end_steps: $(file.filename)")

        # Prepare one run's rows in memory.
        run_results = empty_results()


        # Preallocated general degree vector
        general_degrees = zeros(Float64, n)

        for t in 1:T

            # =================================================
            # General degree vector for this time window
            # =================================================

            fill!(general_degrees, 0.0)

            @inbounds for agent in 1:N
                for word in 1:n
                    general_degrees[word] +=
                        column_sums[word, agent, t]
                end
            end

            # =================================================
            # Four correlations per agent
            # =================================================

            for agent in 1:N

                personal_degrees =
                    @view column_sums[:, agent, t]

                conversation_frequency =
                    @view conversation_words[:, agent, t]

                self_talk_frequency =
                    @view self_talk_words[:, agent, t]

                personal_conversation_r = pearson_r(
                    personal_degrees,
                    conversation_frequency
                )

                personal_self_talk_r = pearson_r(
                    personal_degrees,
                    self_talk_frequency
                )

                general_conversation_r = pearson_r(
                    general_degrees,
                    conversation_frequency
                )

                general_self_talk_r = pearson_r(
                    general_degrees,
                    self_talk_frequency
                )

                push!(
                    run_results,
                    (
                        file.condition,
                        file.run_number,
                        agent,
                        t,
                        Int(start_steps[t]),
                        Int(end_steps[t]),

                        personal_conversation_r,
                        personal_self_talk_r,

                        general_conversation_r,
                        general_self_talk_r,

                        Int(speaking_steps[agent, t]),
                        Int(thinking_steps[agent, t])
                    )
                )
            end
        end

        # Remove any previous partial results for this run,
        # then append its complete results.

        old_rows = (
            (results.condition .== file.condition) .&
            (results.run_number .== file.run_number)
        )

        if any(old_rows)
            DataFrames.deleteat!(
                results,
                findall(old_rows)
            )
        end

        append!(results, run_results)

        push!(
            completed_runs,
            (file.condition, file.run_number)
        )

        new_runs += 1

        if verbose
            println(
                "  -> ",
                DataFrames.nrow(run_results),
                " rows calculated."
            )
        end

        # Save in batches
        if new_runs % save_every == 0

            save_results!()

            verbose && println(
                "  -> Summary saved (",
                new_runs,
                " new runs processed)."
            )
        end
    end

    # ========================================================
    # 7. Final save
    # ========================================================

    if new_runs > 0 || !isfile(output_path)
        save_results!()
    end

    verbose && println(
        "\n========================================\n",
        "Finished.\n",
        "New runs processed: ", new_runs, "\n",
        "Total rows: ", DataFrames.nrow(results), "\n",
        "Summary: ", output_path, "\n",
        "========================================"
    )

    return results
end
# correlations = build_word_frequency_correlations(
#     word_frequency_dir;
#     save_every = 10
# )

function plot_word_frequency_correlations(
    correlations_path::String;

    # --------------------------------------------------------
    # Conditions
    # --------------------------------------------------------

    conditions = :all,
    combine_conditions::Bool = false,

    # --------------------------------------------------------
    # Graph appearance
    # --------------------------------------------------------

    plot_size = (850, 550),
    fontfamily = "Calibri",

    personal_color = :royalblue,
    general_color = :darkorange,

    # Colors for combined graph
    conversation_color = :royalblue,
    self_talk_color = :darkorange,

    line_width = 2.8,
    ribbon_alpha = 0.18,

    # --------------------------------------------------------
    # Axes
    # --------------------------------------------------------

    xlabel = "Simulation step",
    ylabel = "Mean Pearson correlation",

    xlims = nothing,
    ylims = nothing,

    # --------------------------------------------------------
    # Titles and legend
    # --------------------------------------------------------

    show_titles = true,
    combined_title = "Word frequency correlations — All conditions",

    condition_labels = Dict(
        "homophily_0_learning1_0_9" =>
            "Homophily = 0, Learning = 0.9",

        "homophily_3_learning1_0_9" =>
            "Homophily = 3, Learning = 0.9",

        "homophily_3_learning1_0_5" =>
            "Homophily = 3, Learning = 0.5"
    ),

    personal_label = "Personal degree distribution",
    general_label = "General degree distribution",

    legend_position = :topright,
    legendfontsize = 11,
    titlefontsize = 15,
    guidefontsize = 13,
    tickfontsize = 11,

    show_grid = true,
    show_plots = true)

    # ========================================================
    # 1. Load data
    # ========================================================

    df = JLD2.load(correlations_path, "results")

    required_columns = [
        :condition,
        :run_number,
        :agent,
        :window,
        :start_step,
        :end_step,
        :personal_conversation_r,
        :general_conversation_r,
        :personal_self_talk_r,
        :general_self_talk_r
    ]

    missing_columns = setdiff(
        required_columns,
        DataFrames.propertynames(df)
    )

    isempty(missing_columns) ||
        error("Missing columns: $missing_columns")

    available_conditions = sort(unique(df.condition))

    selected_conditions = if conditions === :all
        available_conditions
    elseif conditions isa AbstractString
        [String(conditions)]
    else
        String.(collect(conditions))
    end

    unknown_conditions = setdiff(
        selected_conditions,
        available_conditions
    )

    isempty(unknown_conditions) ||
        error("Unknown conditions: $unknown_conditions")

    # ========================================================
    # 2. Mean and SD helpers
    # ========================================================

    function mean_sd_valid(values)

        valid = Float64[
            Float64(x)
            for x in values
            if !ismissing(x) && isfinite(x)
        ]

        n = length(valid)

        if n == 0
            return (NaN, NaN, 0)
        end

        μ = Statistics.mean(valid)

        σ = n > 1 ?
            Statistics.std(valid; corrected = true) :
            NaN

        return (μ, σ, n)
    end

    # ========================================================
    # 3. Metric definitions
    # ========================================================

    metric_definitions = [
        (
            type = "Conversation",
            degree_type = "Personal",
            column = :personal_conversation_r
        ),
        (
            type = "Conversation",
            degree_type = "General",
            column = :general_conversation_r
        ),
        (
            type = "Self-talk",
            degree_type = "Personal",
            column = :personal_self_talk_r
        ),
        (
            type = "Self-talk",
            degree_type = "General",
            column = :general_self_talk_r
        )
    ]

    # ========================================================
    # 4. Summarize correlations by time window
    # ========================================================

    summary = DataFrames.DataFrame(
        condition = String[],
        type = String[],
        window = Int[],
        start_step = Int[],
        end_step = Int[],
        degree_type = String[],
        mean_r = Float64[],
        sd_r = Float64[],
        n_valid = Int[]
    )

    # In combined mode, all selected conditions are pooled.
    # Otherwise, each condition is summarized separately.

    condition_groups = if combine_conditions
        [("All conditions", selected_conditions)]
    else
        [
            (condition, [condition])
            for condition in selected_conditions
        ]
    end

    for (group_name, group_conditions) in condition_groups

        condition_df = df[
            in.(df.condition, Ref(group_conditions)),
            :
        ]

        windows = sort(unique(condition_df.window))

        for window in windows

            sub = condition_df[
                condition_df.window .== window,
                :
            ]

            start_step = Int(sub.start_step[1])
            end_step = Int(sub.end_step[1])

            for metric in metric_definitions

                μ, σ, n_valid = mean_sd_valid(
                    sub[!, metric.column]
                )

                push!(
                    summary,
                    (
                        String(group_name),
                        metric.type,
                        Int(window),
                        start_step,
                        end_step,
                        metric.degree_type,
                        μ,
                        σ,
                        n_valid
                    )
                )
            end
        end
    end

    # ========================================================
    # 5. Combined graph: four lines
    # ========================================================

    if combine_conditions

        p = Plots.plot(
            ;
            title = show_titles ? combined_title : "",
            xlabel = xlabel,
            ylabel = ylabel,
            size = plot_size,
            fontfamily = fontfamily,
            titlefontsize = titlefontsize,
            guidefontsize = guidefontsize,
            tickfontsize = tickfontsize,
            legendfontsize = legendfontsize,
            legend = legend_position,
            grid = show_grid
        )

        line_definitions = [
            (
                type = "Conversation",
                degree_type = "Personal",
                color = conversation_color,
                linestyle = :solid,
                label = "Conversations — Personal"
            ),
            (
                type = "Conversation",
                degree_type = "General",
                color = conversation_color,
                linestyle = :dash,
                label = "Conversations — General"
            ),
            (
                type = "Self-talk",
                degree_type = "Personal",
                color = self_talk_color,
                linestyle = :solid,
                label = "Self-talk — Personal"
            ),
            (
                type = "Self-talk",
                degree_type = "General",
                color = self_talk_color,
                linestyle = :dash,
                label = "Self-talk — General"
            )
        ]

        for line in line_definitions

            sub = summary[
                (summary.type .== line.type) .&
                (summary.degree_type .== line.degree_type),
                :
            ]

            DataFrames.sort!(sub, :window)

            Plots.plot!(
                p,
                sub.end_step,
                sub.mean_r;
                ribbon = sub.sd_r,
                fillalpha = ribbon_alpha,
                color = line.color,
                linestyle = line.linestyle,
                linewidth = line_width,
                label = line.label
            )
        end

        if xlims !== nothing
            Plots.xlims!(p, xlims)
        end

        if ylims !== nothing
            Plots.ylims!(p, ylims)
        end

        if show_plots
            display(p)
        end

        return (
            summary = summary,
            plots = Dict(
                ("All conditions", "Combined") => p
            )
        )
    end

    # ========================================================
    # 6. Original mode: two graphs per condition
    # ========================================================

    plots = Dict{Tuple{String,String},Any}()

    for condition in selected_conditions

        condition_title = get(
            condition_labels,
            condition,
            condition
        )

        for type in ("Conversation", "Self-talk")

            sub = summary[
                (summary.condition .== condition) .&
                (summary.type .== type),
                :
            ]

            personal = sub[
                sub.degree_type .== "Personal",
                :
            ]

            general = sub[
                sub.degree_type .== "General",
                :
            ]

            DataFrames.sort!(personal, :window)
            DataFrames.sort!(general, :window)

            graph_title = if show_titles
                type == "Conversation" ?
                    "$condition_title — Conversations" :
                    "$condition_title — Self-talk"
            else
                ""
            end

            p = Plots.plot(
                ;
                title = graph_title,
                xlabel = xlabel,
                ylabel = ylabel,
                size = plot_size,
                fontfamily = fontfamily,
                titlefontsize = titlefontsize,
                guidefontsize = guidefontsize,
                tickfontsize = tickfontsize,
                legendfontsize = legendfontsize,
                legend = legend_position,
                grid = show_grid
            )

            Plots.plot!(
                p,
                personal.end_step,
                personal.mean_r;
                ribbon = personal.sd_r,
                fillalpha = ribbon_alpha,
                color = personal_color,
                linewidth = line_width,
                label = personal_label
            )

            Plots.plot!(
                p,
                general.end_step,
                general.mean_r;
                ribbon = general.sd_r,
                fillalpha = ribbon_alpha,
                color = general_color,
                linewidth = line_width,
                label = general_label
            )

            if xlims !== nothing
                Plots.xlims!(p, xlims)
            end

            if ylims !== nothing
                Plots.ylims!(p, ylims)
            end

            plots[(String(condition), type)] = p

            if show_plots
                display(p)
            end
        end
    end

    return (
        summary = summary,
        plots = plots
    )
end
# correlation_plots = plot_word_frequency_correlations(
#     joinpath(
#         word_frequency_dir,
#         "word_frequency_correlations.jld2"
#     );

#     conditions = :all,
#     ylims = (-0.2, 1.0),
#     show_plots = true
# )
# correlation_plots = plot_word_frequency_correlations(
#     joinpath(
#         word_frequency_dir,
#         "word_frequency_correlations.jld2"
#     );

#     combine_conditions = true,
#     plot_size = (950, 600),
#     ylims = (-0.2, 1.0),
#     legend_position = :topright
# )
function summarize_word_frequency_correlations(summary::DataFrames.DataFrame)

    result = DataFrames.combine(
        DataFrames.groupby(
            summary,
            [:condition, :type, :degree_type]
        ),

        :mean_r => (
            x -> begin
                valid = filter(isfinite, x)
                isempty(valid) ? NaN : Statistics.mean(valid)
            end
        ) => :mean_r,

        :mean_r => (
            x -> begin
                valid = filter(isfinite, x)
                length(valid) < 2 ? NaN : Statistics.std(valid)
            end
        ) => :sd_across_windows,

        :mean_r => (
            x -> count(isfinite, x)
        ) => :n_valid_windows
    )

    DataFrames.sort!(
        result,
        [:condition, :type, :degree_type]
    )

    return result
end
# overall_summary = summarize_word_frequency_correlations(
#     correlation_plots.summary
# )
# show(overall_summary; allrows=true, allcols=true)

function plot_word_frequency_correlation_bars(
    correlations_path::String;

    # ========================================================
    # Conditions
    # ========================================================

    conditions = :all,

    # :combined  = one graph pooling all selected conditions
    # :separate  = one graph per condition
    # :both      = combined + separate graphs
    mode::Symbol = :combined,

    condition_labels = Dict(
        "homophily_0_learning1_0_9" =>
            "Homophily = 0, Learning = 0.9",

        "homophily_3_learning1_0_9" =>
            "Homophily = 3, Learning = 0.9",

        "homophily_3_learning1_0_5" =>
            "Homophily = 3, Learning = 0.5"
    ),

    # ========================================================
    # Bar order and labels
    # ========================================================

    bar_order = [
        :personal_conversation_r,
        :general_conversation_r,
        :personal_self_talk_r,
        :general_self_talk_r
    ],

    bar_labels = Dict(
        :personal_conversation_r => "Conversations\nPersonal",
        :general_conversation_r => "Conversations\nGeneral",
        :personal_self_talk_r => "Self-talk\nPersonal",
        :general_self_talk_r => "Self-talk\nGeneral"
    ),

    # ========================================================
    # Colors
    # ========================================================

    bar_colors = Dict(
        :personal_conversation_r => :royalblue,
        :general_conversation_r => :lightskyblue,
        :personal_self_talk_r => :darkorange,
        :general_self_talk_r => :sandybrown
    ),

    # ========================================================
    # Appearance
    # ========================================================

    plot_size = (850, 550),
    fontfamily = "Calibri",

    bar_width = 0.65,
    bar_alpha = 0.9,

    error_linewidth = 2.0,
    error_color = :black,

    show_grid = true,
    show_legend = false,

    # ========================================================
    # Axes
    # ========================================================

    ylabel = "Mean Pearson correlation",
    xlabel = "",

    xlims = nothing,
    ylims = nothing,

    # ========================================================
    # Titles
    # ========================================================

    show_titles = true,
    combined_title = "Word frequency correlations — All conditions",

    titlefontsize = 15,
    guidefontsize = 13,
    tickfontsize = 11,

    # ========================================================
    # Optional annotations
    # ========================================================

    show_values = false,
    value_digits = 3,
    value_offset = 0.02,

    # ========================================================
    # Display
    # ========================================================

    show_plots = true)

    @assert mode in (:combined, :separate, :both)

    # ========================================================
    # 1. Load data
    # ========================================================

    df = JLD2.load(correlations_path, "results")

    available_metrics = [
        :personal_conversation_r,
        :general_conversation_r,
        :personal_self_talk_r,
        :general_self_talk_r
    ]

    @assert length(unique(bar_order)) == length(bar_order)
    @assert all(x -> x in available_metrics, bar_order)

    available_conditions = sort(unique(df.condition))

    selected_conditions = if conditions === :all
        available_conditions
    elseif conditions isa AbstractString
        [String(conditions)]
    else
        String.(collect(conditions))
    end

    unknown_conditions = setdiff(
        selected_conditions,
        available_conditions
    )

    isempty(unknown_conditions) ||
        error("Unknown conditions: $unknown_conditions")

    isempty(selected_conditions) &&
        error("No conditions selected.")

    # ========================================================
    # 2. Mean and SD helper
    # ========================================================

    function mean_sd_valid(values)

        valid = Float64[
            Float64(x)
            for x in values
            if !ismissing(x) && isfinite(x)
        ]

        n = length(valid)

        if n == 0
            return (NaN, NaN, 0)
        end

        μ = Statistics.mean(valid)

        σ = n > 1 ?
            Statistics.std(valid; corrected = true) :
            NaN

        return (μ, σ, n)
    end

    # ========================================================
    # 3. Calculate one mean per run and metric
    # ========================================================

    per_run = DataFrames.DataFrame(
        condition = String[],
        run_number = Int[],
        metric = Symbol[],
        mean_r = Float64[],
        n_valid = Int[]
    )

    selected_df = df[
        in.(df.condition, Ref(selected_conditions)),
        :
    ]

    grouped_runs = DataFrames.groupby(
        selected_df,
        [:condition, :run_number]
    )

    for g in grouped_runs

        condition = String(g.condition[1])
        run_number = Int(g.run_number[1])

        for metric in available_metrics

            μ, _, n = mean_sd_valid(g[!, metric])

            push!(
                per_run,
                (
                    condition,
                    run_number,
                    metric,
                    μ,
                    n
                )
            )
        end
    end

    # ========================================================
    # 4. Create summary table
    # ========================================================

    summary = DataFrames.DataFrame(
        condition = String[],
        metric = Symbol[],
        mean_r = Float64[],
        sd_between_runs = Float64[],
        n_runs = Int[]
    )

    condition_groups = if mode === :combined
        [("All conditions", selected_conditions)]
    elseif mode === :separate
        [(c, [c]) for c in selected_conditions]
    else
        vcat(
            [("All conditions", selected_conditions)],
            [(c, [c]) for c in selected_conditions]
        )
    end

    for (group_name, group_conditions) in condition_groups

        group_df = per_run[
            in.(per_run.condition, Ref(group_conditions)),
            :
        ]

        for metric in bar_order

            metric_df = group_df[
                group_df.metric .== metric,
                :
            ]

            μ, σ, n = mean_sd_valid(metric_df.mean_r)

            push!(
                summary,
                (
                    String(group_name),
                    metric,
                    μ,
                    σ,
                    n
                )
            )
        end
    end

    # ========================================================
    # 5. Create bar graphs
    # ========================================================

    plots = Dict{String,Any}()

    for (group_name, _) in condition_groups

        sub = summary[
            summary.condition .== group_name,
            :
        ]

        # Preserve requested bar order
        order_index = Dict(
            metric => i
            for (i, metric) in enumerate(bar_order)
        )

        DataFrames.sort!(
            sub,
            :metric;
            by = x -> order_index[x]
        )

        means = sub.mean_r
        sds = sub.sd_between_runs

        colors = [
            get(bar_colors, metric, :gray)
            for metric in sub.metric
        ]

        labels = [
            get(bar_labels, metric, string(metric))
            for metric in sub.metric
        ]

        title_text = if !show_titles
            ""
        elseif group_name == "All conditions"
            combined_title
        else
            get(
                condition_labels,
                group_name,
                group_name
            )
        end

        x_positions = collect(1:length(means))

        p = Plots.bar(
            x_positions,
            means;

            yerror = sds,

            color = colors,
            alpha = bar_alpha,

            bar_width = bar_width,

            linecolor = :transparent,

            errorbar_color = error_color,
            errorbar_linewidth = error_linewidth,

            xticks = (x_positions, labels),

            title = title_text,
            xlabel = xlabel,
            ylabel = ylabel,

            size = plot_size,
            fontfamily = fontfamily,

            titlefontsize = titlefontsize,
            guidefontsize = guidefontsize,
            tickfontsize = tickfontsize,

            legend = show_legend,
            grid = show_grid
        )

        if xlims !== nothing
            Plots.xlims!(p, xlims)
        end

        if ylims !== nothing
            Plots.ylims!(p, ylims)
        end

        if show_values

            for i in eachindex(means)

                if isfinite(means[i])

                    offset = isfinite(sds[i]) ?
                        sds[i] + value_offset :
                        value_offset

                    Plots.annotate!(
                        p,
                        x_positions[i],
                        means[i] + offset,
                        Plots.text(
                            string(round(means[i]; digits=value_digits)),
                            tickfontsize,
                            :black
                        )
                    )
                end
            end
        end

        plots[String(group_name)] = p

        if show_plots
            display(p)
        end
    end

    return (
        per_run = per_run,
        summary = summary,
        plots = plots
    )
end
# bar_results = plot_word_frequency_correlation_bars(
#     joinpath(
#         word_frequency_dir,
#         "word_frequency_correlations.jld2"
#     );

#     mode = :combined,
#     ylims = (0, 1),
#     show_values = true
# )

function summarize_word_frequency_correlations_direct(
    correlation_path::String;
    activity::Symbol = :conversation,
    degree::Symbol = :personal,
    sd_types = [:overall, :agents, :time])

    activity in (:conversation, :self_talk) ||
        error("activity must be :conversation or :self_talk")

    degree in (:personal, :general) ||
        error("degree must be :personal or :general")

    selected_sd_types = sd_types isa Symbol ?
        [sd_types] : collect(sd_types)

    all(t -> t in (:overall, :agents, :time), selected_sd_types) ||
        error("sd_types must contain only :overall, :agents, :time")

    # ========================================================
    # 1. Load and select correlations
    # ========================================================

    df = JLD2.load(correlation_path, "results")

    required_ids = [:condition, :run_number, :agent, :window]

    missing_ids = setdiff(
        required_ids,
        DataFrames.propertynames(df)
    )

    isempty(missing_ids) ||
        error("Missing columns: $missing_ids")

    activity_names = activity == :conversation ?
        ["conversation", "conversations"] :
        ["self_talk", "selftalk", "thinking", "thoughts"]

    degree_names = degree == :personal ?
        ["personal"] : ["general"]

    columns = DataFrames.propertynames(df)

    if :correlation_type in columns || :correlation_kind in columns

        type_column = :correlation_type in columns ?
            :correlation_type : :correlation_kind

        selected = [
            any(occursin(a, lowercase(string(s))) for a in activity_names) &&
            any(occursin(d, lowercase(string(s))) for d in degree_names)
            for s in df[!, type_column]
        ]

        df = df[selected, :]

        r_column = if :pearson_r in columns
            :pearson_r
        elseif :correlation in columns
            :correlation
        elseif :r in columns
            :r
        else
            error("Cannot identify correlation-value column.")
        end

    else

        candidates = Symbol[]

        for col in columns
            s = lowercase(string(col))

            if any(occursin(a, s) for a in activity_names) &&
               any(occursin(d, s) for d in degree_names)

                push!(candidates, col)
            end
        end

        length(candidates) == 1 ||
            error(
                "Cannot identify correlation column. " *
                "Candidates: $candidates. Columns: $columns"
            )

        r_column = only(candidates)
    end

    DataFrames.nrow(df) > 0 ||
        error("No data for selected activity and degree.")

    valid = [
        !ismissing(r) &&
        isfinite(r) &&
        -1 <= r <= 1
        for r in df[!, r_column]
    ]

    df = df[valid, :]
    df.r_value = Float64.(df[!, r_column])

    DataFrames.nrow(df) > 0 ||
        error("No valid correlations found.")

    # ========================================================
    # 2. Helpers
    # ========================================================

    function safe_sd(x)
        return length(x) >= 2 ?
            Statistics.std(x; corrected=true) : NaN
    end

    function mean_sd_valid(x)

        values = Float64[
            Float64(v) for v in x
            if !ismissing(v) && isfinite(v)
        ]

        isempty(values) && return (NaN, NaN)

        return (
            Statistics.mean(values),
            safe_sd(values)
        )
    end

    # ========================================================
    # 3. Calculate statistics separately for each run
    # ========================================================

    per_run = DataFrames.DataFrame(
        condition = String[],
        run_number = Int[],
        n_correlations = Int[],
        mean_r = Float64[],
        overall_sd = Float64[],
        q25 = Float64[],
        q75 = Float64[],
        agent_sd = Float64[],
        time_sd = Float64[]
    )

    for run in DataFrames.groupby(
        df,
        [:condition, :run_number]
    )

        r = run.r_value

        # Mean of all correlations in this run
        mean_r = Statistics.mean(r)

        # Overall SD and quartiles
        overall_sd = :overall in selected_sd_types ?
            safe_sd(r) : NaN

        q25 = :overall in selected_sd_types ?
            Statistics.quantile(r, 0.25) : NaN

        q75 = :overall in selected_sd_types ?
            Statistics.quantile(r, 0.75) : NaN

        # SD between agents after averaging across time
        agent_sd = NaN

        if :agents in selected_sd_types

            agent_means = [
                Statistics.mean(g.r_value)
                for g in DataFrames.groupby(run, :agent)
            ]

            agent_sd = safe_sd(agent_means)
        end

        # SD across time after averaging across agents
        time_sd = NaN

        if :time in selected_sd_types

            window_means = [
                Statistics.mean(g.r_value)
                for g in DataFrames.groupby(run, :window)
            ]

            time_sd = safe_sd(window_means)
        end

        push!(per_run, (
            String(run.condition[1]),
            Int(run.run_number[1]),
            length(r),
            mean_r,
            overall_sd,
            q25,
            q75,
            agent_sd,
            time_sd
        ))
    end

    DataFrames.sort!(
        per_run,
        [:condition, :run_number]
    )

    # ========================================================
    # 4. Summarize across runs
    # ========================================================

    function summarize_group(sub, condition_name)

        mean_r, sd_of_mean_r =
            mean_sd_valid(sub.mean_r)

        result = (
            condition = String(condition_name),
            n_runs = DataFrames.nrow(sub),
            mean_r = mean_r,
            sd_of_mean_r = sd_of_mean_r
        )

        if :overall in selected_sd_types

            mean_overall_sd, sd_of_overall_sd =
                mean_sd_valid(sub.overall_sd)

            mean_q25, sd_q25 =
                mean_sd_valid(sub.q25)

            mean_q75, sd_q75 =
                mean_sd_valid(sub.q75)

            result = merge(result, (
                mean_overall_sd = mean_overall_sd,
                sd_of_overall_sd = sd_of_overall_sd,
                mean_q25 = mean_q25,
                sd_q25 = sd_q25,
                mean_q75 = mean_q75,
                sd_q75 = sd_q75
            ))
        end

        if :agents in selected_sd_types

            mean_agent_sd, sd_of_agent_sd =
                mean_sd_valid(sub.agent_sd)

            result = merge(result, (
                mean_agent_sd = mean_agent_sd,
                sd_of_agent_sd = sd_of_agent_sd
            ))
        end

        if :time in selected_sd_types

            mean_time_sd, sd_of_time_sd =
                mean_sd_valid(sub.time_sd)

            result = merge(result, (
                mean_time_sd = mean_time_sd,
                sd_of_time_sd = sd_of_time_sd
            ))
        end

        return result
    end

    rows = NamedTuple[]

    for condition in sort(unique(per_run.condition))

        sub = per_run[
            per_run.condition .== condition,
            :
        ]

        push!(
            rows,
            summarize_group(sub, condition)
        )
    end

    push!(
        rows,
        summarize_group(per_run, "All conditions")
    )

    summary = DataFrames.DataFrame(rows)

    return (
        summary = summary,
        per_run = per_run
    )
end
