# ============================================================
# Tasks
# ============================================================


function simple_association_task(
    network::AbstractMatrix{<:Real},
    cues::AbstractVector{<:Integer};
    gamma_edge::Real = 1.0,
    gamma_degree::Real = 1.0,
    activation::Real = 0.0,
    rng::AbstractRNG = Random.default_rng())

    n = size(network, 1)

    @assert size(network, 2) == n "network must be square"
    @assert all(1 .<= cues .<= n) "All cues must be valid word indices"
    @assert gamma_edge >= 0
    @assert gamma_degree >= 0
    @assert 0.0 <= activation <= 1.0

    # Subjective global frequency / weighted degree
    word_degree =
        vec(
            Statistics.sum(
                network;
                dims = 2
            )
        )

    normalized_degree =
        word_degree ./ sum(word_degree)

    # Reconstructed network
    reconstructed_network =
        zeros(Int, n, n)

    # Observed responses
    results =
        DataFrames.DataFrame(
            cue = Int[],
            response = Int[]
        )

    for cue in cues

        edge_weights =
            Float64.(network[:, cue])

        edge_sum =
            sum(edge_weights)

        if edge_sum == 0
            error("Cue $cue has no possible responses.")
        end

        normalized_edges =
            edge_weights ./ edge_sum

        scores =
            normalized_edges .^ gamma_edge .*
            normalized_degree .^ gamma_degree

        probabilities =
            scores ./ sum(scores)

        # Sample response
        r =
            Random.rand(rng)

        cumulative =
            0.0

        chosen_response =
            1

        for response in 1:n

            cumulative +=
                probabilities[response]

            if r <= cumulative
                chosen_response =
                    response
                break
            end
        end

        # Optional additional activation
        if Random.rand(rng) < activation

            activation_cue =
                chosen_response

            edge_weights =
                Float64.(network[:, activation_cue])

            edge_sum =
                sum(edge_weights)

            if edge_sum == 0
                error("Cue $activation_cue has no possible responses.")
            end

            normalized_edges =
                edge_weights ./ edge_sum

            scores =
                normalized_edges .^ gamma_edge .*
                normalized_degree .^ gamma_degree

            probabilities =
                scores ./ sum(scores)

            r =
                Random.rand(rng)

            cumulative =
                0.0

            chosen_response =
                1

            for response in 1:n

                cumulative +=
                    probabilities[response]

                if r <= cumulative
                    chosen_response =
                        response
                    break
                end
            end
        end


        # Save task response
        push!(
            results,
            (
                cue,
                chosen_response
            )
        )

        # Add association to reconstructed network
        reconstructed_network[
            chosen_response,
            cue
        ] += 1

        reconstructed_network[
            cue,
            chosen_response
        ] += 1
    end

    return results, reconstructed_network
end
function create_normative_association_network(
    agents::Array{Float32,3},
    cues::AbstractVector{<:Integer};
    gamma_edge::Real = 1.0,
    gamma_degree::Real = 1.0,
    activation::Real = 0.0,
    rng::AbstractRNG = Random.default_rng())

    n = size(agents, 1)
    N = size(agents, 3)

    @assert size(agents, 2) == n

    normative_network =
        zeros(Int, n, n)

    for agent in 1:N

        network =
            @view agents[:, :, agent]

        _, reconstructed_network =
            simple_association_task(
                network,
                cues;
                gamma_edge = gamma_edge,
                gamma_degree = gamma_degree,
                activation = activation,
                rng = rng
            )

        normative_network .+=
            reconstructed_network
    end

    return normative_network
end



function run_cue_selection_comparison_bank(
    bank_dir::String;
    selected_conditions,
    selection_methods::Vector{Symbol} = [:top, :bottom, :random],
    cue_counts::Vector{Int},
    output_path::String = joinpath(
        bank_dir,
        "cue_selection_comparison_results.jld2"
    ),
    normative_cue_repetitions::Int = 5,
    n_responses::Int = 300,
    gamma_edge::Real = 1.0,
    gamma_degree::Real = 0.0,
    seed::Int = 12345,
    resume::Bool = true)

    # ============================================================
    # VALIDATION
    # ============================================================

    isempty(cue_counts) &&
        error("cue_counts cannot be empty")

    isempty(selection_methods) &&
        error("selection_methods cannot be empty")

    all(m -> m in (:top, :bottom, :random), selection_methods) ||
        error("Invalid selection method")

    length(unique(selection_methods)) == length(selection_methods) ||
        error("Duplicate selection methods")

    length(unique(cue_counts)) == length(cue_counts) ||
        error("Duplicate cue counts")

    any(k -> k < 1 || k > n_responses, cue_counts) &&
        error("Cue counts must be between 1 and n_responses")

    requested_k = Set(cue_counts)

    rng = Random.MersenneTwister(seed)

    # ============================================================
    # HELPERS
    # ============================================================

    function filename_number(x::Real)
        isinteger(x) ?
            string(Int(x)) :
            replace(string(Float64(x)), "." => "_")
    end

    function filename_matches_condition(file, h, l)
        occursin("homophily_$(filename_number(h))_", file) &&
        occursin("learning1_$(filename_number(l))_", file)
    end

    function extract_run_number(file)
        m = match(r"_run_(\d+)\.jld2$", file)

        isnothing(m) &&
            error("Could not extract run number from $file")

        parse(Int, m.captures[1])
    end

    function run_key(file)
        replace(file, r"\.jld2$" => "")
    end

    function storage_key(method, file)
        "runs/$(String(method))/$(run_key(file))"
    end

    function original_metrics(network, norm)
        (
            network = tvd_matrix(network, norm),
            column = column_normalized_tvd(network, norm),
            degree = tvd_counts(
                vec(Statistics.sum(network; dims=2)),
                vec(Statistics.sum(norm; dims=2))
            )
        )
    end

    function behavioral_metrics(reconstructed, reconstructed_norm)
        (
            network = tvd_matrix(reconstructed, reconstructed_norm),
            column = column_normalized_tvd(reconstructed, reconstructed_norm),
            degree_reconstructed = tvd_counts(
                vec(Statistics.sum(reconstructed; dims=2)),
                vec(Statistics.sum(reconstructed_norm; dims=2))
            )
        )
    end

    function extract_metric(v, field)
        Float64[getproperty(x, field) for x in v]
    end

    function format_duration(seconds::Real)
        s = max(0, round(Int, seconds))

        h = div(s, 3600)
        m = div(mod(s, 3600), 60)
        sec = mod(s, 60)

        return string(
            lpad(h, 2, '0'), ":",
            lpad(m, 2, '0'), ":",
            lpad(sec, 2, '0')
        )
    end

    # ============================================================
    # PARAMETERS
    # ============================================================

    params = (
        selected_conditions = selected_conditions,
        selection_methods = copy(selection_methods),
        cue_counts = copy(cue_counts),
        normative_cue_repetitions = normative_cue_repetitions,
        n_responses = n_responses,
        timepoints = ["post_0", "post_100"],
        gamma_edge = Float64(gamma_edge),
        gamma_degree = Float64(gamma_degree),
        seed = seed
    )

    # ============================================================
    # SELECT SIMULATION FILES
    # ============================================================

    all_files = filter(
        f -> endswith(f, ".jld2"),
        readdir(bank_dir)
    )

    selected_files = Tuple{String,Float64,Float64}[]

    for c in selected_conditions
        for file in all_files
            if filename_matches_condition(
                file,
                c.homophily,
                c.learning
            )
                push!(
                    selected_files,
                    (
                        file,
                        Float64(c.homophily),
                        Float64(c.learning)
                    )
                )
            end
        end
    end

    sort!(
        selected_files;
        by = x -> (
            x[2],
            x[3],
            extract_run_number(x[1])
        )
    )

    isempty(selected_files) &&
        error("No matching simulation files found")

    total_files = length(selected_files)

    # ============================================================
    # INITIAL CHECK — ONLY ONCE
    # ============================================================

    completed_files = Set{String}()
    incomplete_files = Set{String}()

    println()
    println("============================================================")
    println("CUE SELECTION COMPARISON")
    println("============================================================")
    println("Simulation files: $total_files")
    println("Methods: $(join(string.(selection_methods), ", "))")
    println("Cue counts: $(length(cue_counts))")
    println("Output: $output_path")
    println("============================================================")

    if resume && isfile(output_path)

        println("\nChecking existing results...")

        check_start = time()

        JLD2.jldopen(output_path, "r") do f

            # ----------------------------------------------------
            # Validate fixed parameters
            # cue_counts is intentionally allowed to change
            # ----------------------------------------------------

            if haskey(f, "params")

                old_params = f["params"]

                for field in (
                    :normative_cue_repetitions,
                    :n_responses,
                    :gamma_edge,
                    :gamma_degree,
                    :seed
                )

                    if hasproperty(old_params, field)

                        old_value = getproperty(old_params, field)
                        new_value = getproperty(params, field)

                        isequal(old_value, new_value) ||
                            error(
                                "Parameter mismatch: $field " *
                                "(saved=$old_value, new=$new_value)"
                            )
                    end
                end
            end

            # ----------------------------------------------------
            # Check each simulation run
            # ----------------------------------------------------

            for (file, _, _) in selected_files

                all_methods_complete = true

                for method in selection_methods

                    key = storage_key(method, file)

                    if !haskey(f, key)
                        all_methods_complete = false
                        break
                    end

                    df = f[key]

                    if !(
                        :n_top_cues in propertynames(df) &&
                        :timepoint in propertynames(df)
                    )
                        all_methods_complete = false
                        break
                    end

                    # Check only the unique K values at each
                    # timepoint, not individual agents.

                    for tp in ("post_0", "post_100")

                        mask = df.timepoint .== tp

                        existing_k = Set(
                            Int.(unique(df.n_top_cues[mask]))
                        )

                        if !issubset(requested_k, existing_k)
                            all_methods_complete = false
                            break
                        end
                    end

                    all_methods_complete || break
                end

                if all_methods_complete
                    push!(completed_files, file)
                else
                    push!(incomplete_files, file)
                end
            end
        end

        check_elapsed = time() - check_start

        println(
            "Check completed in ",
            round(check_elapsed; digits=2),
            " seconds"
        )

    elseif !isfile(output_path)

        println("\nNo existing output file. Creating a new one.")

        JLD2.jldopen(output_path, "w") do f
            f["params"] = params
        end

    else

        error(
            "Output file already exists. " *
            "Use resume=true to continue without overwriting it."
        )
    end

    # ============================================================
    # UPDATE PARAMETERS
    # ============================================================

    # Existing results may have been calculated with a larger
    # cue_counts set. The stored params will describe the new
    # requested set after successful completion of the run.

    files_to_process = [
        info for info in selected_files
        if !(info[1] in completed_files)
    ]

    n_to_process = length(files_to_process)

    println()
    println("Complete runs: $(length(completed_files))")
    println("Runs to calculate: $n_to_process")
    println("============================================================")

    if n_to_process == 0

        println("All requested results already exist.")
        return output_path
    end

    # ============================================================
    # ETA TRACKING
    # ============================================================

    completed_run_times = Float64[]
    completed_unit_times = Float64[]

    units_per_run = 2 * length(selection_methods)
    total_units = n_to_process * units_per_run

    units_completed = 0
    runs_completed = 0

    function estimate_remaining()

        remaining_units = total_units - units_completed

        if isempty(completed_unit_times)
            return "Calculating..."
        end

        # Use the average time of all completed method-timepoint
        # units, including the current run.

        mean_unit_time =
            Statistics.mean(completed_unit_times)

        estimated_seconds =
            remaining_units * mean_unit_time

        return format_duration(estimated_seconds)
    end

    # ============================================================
    # MAIN LOOP
    # ============================================================

    for (process_index, (file, homophily, learning)) in
        enumerate(files_to_process)

        run_start = time()

        run_number = extract_run_number(file)

        condition =
            "homophily_$(homophily)_learning_$(learning)"

        original_index = findfirst(
            x -> x[1] == file,
            selected_files
        )

        println()
        println(
            "Run $original_index/$total_files | ",
            condition,
            " | run $run_number"
        )

        if file in incomplete_files
            println("  Recomputing incomplete run")
        end

        # --------------------------------------------------------
        # LOAD SIMULATION
        # --------------------------------------------------------

        d = JLD2.load(joinpath(bank_dir, file))

        networks = d["networks"]
        saved_steps = Int.(d["saved_steps"])
        metadata = d["metadata"]

        target_agent = Int(metadata.crossing_agent)
        crossing_step = Int(metadata.crossing_step)

        recorded_steps = collect(
            0:100:maximum(saved_steps)
        )

        crossing_idx = findfirst(
            x -> x >= crossing_step,
            recorded_steps
        )

        crossing_idx === nothing &&
            error("Could not locate crossing step in $file")

        post_steps = recorded_steps[crossing_idx:end]

        timepoint_labels = ["post_0", "post_100"]

        anchor_steps = [
            first(post_steps),
            last(post_steps)
        ]

        snapshot_indices = Int[]

        for step in anchor_steps

            idx = findfirst(==(step), saved_steps)

            idx === nothing &&
                error("Step $step not found in $file")

            push!(snapshot_indices, idx)
        end

        # One DataFrame per selection method.
        # All results for this run remain in memory until
        # the entire run has been successfully calculated.

        run_results = Dict(
            method => DataFrames.DataFrame()
            for method in selection_methods
        )

        # --------------------------------------------------------
        # TWO TIMEPOINTS
        # --------------------------------------------------------

        for tp_index in eachindex(timepoint_labels)

            timepoint = timepoint_labels[tp_index]
            actual_step = anchor_steps[tp_index]
            snapshot_idx = snapshot_indices[tp_index]

            agents = networks[:, :, :, snapshot_idx]

            n = size(agents, 1)
            N = size(agents, 3)

            maximum(cue_counts) <= n ||
                error(
                    "Cue count exceeds number of words in $file"
                )

            # ----------------------------------------------------
            # NORMATIVE NETWORKS
            # ----------------------------------------------------

            mean_original_network = dropdims(
                Statistics.mean(agents; dims=3);
                dims=3
            )

            normative_cues = repeat(
                collect(1:n);
                inner=normative_cue_repetitions
            )

            normative_reconstructed =
                create_normative_association_network(
                    agents,
                    normative_cues;
                    gamma_edge=gamma_edge,
                    gamma_degree=gamma_degree,
                    activation=0.0,
                    rng=rng
                )

            normative_degree = Float64.(
                vec(
                    Statistics.sum(
                        normative_reconstructed;
                        dims=2
                    )
                )
            )

            # ----------------------------------------------------
            # ORIGINAL METRICS
            # ----------------------------------------------------

            original = [
                original_metrics(
                    agents[:, :, a],
                    mean_original_network
                )
                for a in 1:N
            ]

            original_network =
                extract_metric(original, :network)

            original_column =
                extract_metric(original, :column)

            original_degree =
                extract_metric(original, :degree)

            original_network_z =
                zscore_across_agents(original_network)

            original_column_z =
                zscore_across_agents(original_column)

            original_degree_z =
                zscore_across_agents(original_degree)

            # ----------------------------------------------------
            # SELECTION METHODS
            # ----------------------------------------------------

            for method in selection_methods

                method_start = time()

                ranked_cues =
                    if method == :top

                        sortperm(
                            normative_degree;
                            rev=true
                        )

                    elseif method == :bottom

                        sortperm(
                            normative_degree;
                            rev=false
                        )

                    else

                        Random.randperm(rng, n)
                    end

                # ------------------------------------------------
                # CUE COUNTS
                # ------------------------------------------------

                for k in cue_counts

                    selected_cues = ranked_cues[1:k]

                    repetitions, remainder =
                        divrem(n_responses, k)

                    cue_trials = repeat(
                        selected_cues;
                        inner=repetitions
                    )

                    if remainder > 0

                        extra_cues = Random.shuffle(
                            rng,
                            copy(selected_cues)
                        )[1:remainder]

                        append!(cue_trials, extra_cues)
                    end

                    Random.shuffle!(rng, cue_trials)

                    task_data = Vector{Any}(undef, N)

                    restricted_columns =
                        Vector{Float64}(undef, N)

                    # --------------------------------------------
                    # ASSOCIATION TASK — ALL AGENTS
                    # --------------------------------------------

                    for agent in 1:N

                        network = agents[:, :, agent]

                        _, reconstructed =
                            simple_association_task(
                                network,
                                cue_trials;
                                gamma_edge=gamma_edge,
                                gamma_degree=gamma_degree,
                                activation=0.0,
                                rng=rng
                            )

                        task_data[agent] =
                            behavioral_metrics(
                                reconstructed,
                                normative_reconstructed
                            )

                        restricted_columns[agent] =
                            column_normalized_tvd(
                                reconstructed[:, selected_cues],
                                normative_reconstructed[:, selected_cues]
                            )
                    end

                    # --------------------------------------------
                    # METRICS AND Z-SCORES
                    # --------------------------------------------

                    network_values =
                        extract_metric(task_data, :network)

                    column_values =
                        extract_metric(task_data, :column)

                    degree_values =
                        extract_metric(
                            task_data,
                            :degree_reconstructed
                        )

                    network_z =
                        zscore_across_agents(network_values)

                    column_z =
                        zscore_across_agents(column_values)

                    degree_z =
                        zscore_across_agents(degree_values)

                    restricted_columns_z =
                        zscore_across_agents(restricted_columns)

                    # --------------------------------------------
                    # SAVE ROWS IN MEMORY
                    # --------------------------------------------

                    for agent in 1:N

                        row = (
                            file = file,
                            condition = condition,
                            homophily = homophily,
                            learning = learning,
                            run_number = run_number,
                            timepoint = timepoint,
                            actual_step = actual_step,
                            selection_method = String(method),
                            n_top_cues = k,
                            agent = agent,
                            target_agent = target_agent,
                            is_target_agent = agent == target_agent,

                            original_network =
                                original_network[agent],

                            original_network_z =
                                original_network_z[agent],

                            original_column =
                                original_column[agent],

                            original_column_z =
                                original_column_z[agent],

                            original_degree =
                                original_degree[agent],

                            original_degree_z =
                                original_degree_z[agent],

                            top_cues_network =
                                network_values[agent],

                            top_cues_network_z =
                                network_z[agent],

                            top_cues_column =
                                column_values[agent],

                            top_cues_column_z =
                                column_z[agent],

                            top_cues_column_topK =
                                restricted_columns[agent],

                            top_cues_column_topK_z =
                                restricted_columns_z[agent],

                            top_cues_degree_reconstructed =
                                degree_values[agent],

                            top_cues_degree_reconstructed_z =
                                degree_z[agent]
                        )

                        push!(
                            run_results[method],
                            row;
                            cols=:union
                        )
                    end
                end

                # ------------------------------------------------
                # PROGRESS + ETA
                # ------------------------------------------------

                method_elapsed = time() - method_start

                push!(
                    completed_unit_times,
                    method_elapsed
                )

                units_completed += 1

                println(
                    "  ",
                    rpad(timepoint, 9),
                    " | ",
                    rpad(String(method), 7),
                    " | ETA: ",
                    estimate_remaining()
                )
            end
        end

        # ========================================================
        # SAVE COMPLETE RUN
        # ========================================================

        # All three methods and both timepoints have now been
        # calculated successfully.
        #
        # Existing datasets are replaced only at this stage.

        JLD2.jldopen(output_path, "a+") do f

            for method in selection_methods

                key = storage_key(method, file)

                f[key] = run_results[method]
            end

        end

        run_elapsed = time() - run_start

        push!(completed_run_times, run_elapsed)

        runs_completed += 1

        # Account for loading and saving overhead in the ETA
        # after the first complete run.

        mean_run_time =
            Statistics.mean(completed_run_times)

        remaining_runs =
            n_to_process - runs_completed

        final_eta =
            remaining_runs * mean_run_time

        println(
            "  Saved | ",
            runs_completed,
            "/",
            n_to_process,
            " new runs | ETA: ",
            format_duration(final_eta)
        )
    end

    # ============================================================
    # UPDATE PARAMETERS AFTER SUCCESSFUL COMPLETION
    # ============================================================

    JLD2.jldopen(output_path, "a+") do f
        f["params"] = params
    end

    # ============================================================
    # FINISHED
    # ============================================================

    println()
    println("============================================================")
    println("FINISHED")
    println("============================================================")
    println("Total simulation files: $total_files")
    println("Previously complete: $(length(completed_files))")
    println("Calculated: $runs_completed")

    if !isempty(completed_run_times)
        println(
            "Mean run time: ",
            format_duration(
                Statistics.mean(completed_run_times)
            )
        )
    end

    println("Saved to: $(abspath(output_path))")
    println("============================================================")

    return output_path
end
cue_counts = vcat(
