#     gamma_edge = 1.0,
#     gamma_degree = 0.0,

#     seed = 12345,
#     resume = true
# )
function load_cue_selection_results(
    path::String;
    selection_methods=[:top, :bottom, :random],
    cue_counts::Vector{Int})

    results = DataFrames.DataFrame()
    requested_cues = Set(cue_counts)

    JLD2.jldopen(path, "r") do f

        for method in selection_methods

            group_path = "runs/$(String(method))"

            if !haskey(f, group_path)
                println("No results for method: ", method)
                continue
            end

            group = f[group_path]
            run_names = sort!(collect(keys(group)))

            println(
                "Loading ",
                method,
                ": ",
                length(run_names),
                " runs"
            )

            for (i, run_name) in enumerate(run_names)

                df = group[run_name]

                # Keep only the requested cue counts
                mask = in.(df.n_top_cues, Ref(requested_cues))

                append!(
                    results,
                    df[mask, :];
                    cols=:union
                )

                if i % 25 == 0 || i == length(run_names)
                    println(
                        "    [$i/$(length(run_names))]"
                    )
                end
            end
        end
    end

    println("Total rows: ", DataFrames.nrow(results))

    return results
end
