#     );
#     selection_methods=[:top, :bottom, :random],
#     cue_counts=cue_counts
# )
function calculate_cue_selection_correlations(
    results::DataFrames.DataFrame)

    metric_pairs = [
        ("Network", :original_network, :top_cues_network),
        ("Column", :original_column, :top_cues_column),
        ("Column top K", :original_column, :top_cues_column_topK),
        (
            "Degree reconstructed",
            :original_degree,
            :top_cues_degree_reconstructed
        )
    ]

    required_columns = [
        :selection_method,
        :condition,
        :run_number,
        :timepoint,
        :n_top_cues
    ]

    for col in required_columns
        col in DataFrames.propertynames(results) ||
            error("Missing column: $col")
    end

    for (_, original_col, reconstructed_col) in metric_pairs
        original_col in DataFrames.propertynames(results) ||
            error("Missing column: $original_col")

        reconstructed_col in DataFrames.propertynames(results) ||
            error("Missing column: $reconstructed_col")
    end

    grouped = DataFrames.groupby(
        results,
        [
            :selection_method,
            :condition,
            :run_number,
            :timepoint,
            :n_top_cues
        ];
        sort=true
    )

    correlations = DataFrames.DataFrame(
        selection_method=String[],
        condition=String[],
        run_number=Int[],
        timepoint=String[],
        n_top_cues=Int[],
        metric=String[],
        r=Float64[]
    )

    total_groups = length(grouped)

    println("============================================================")
    println("CALCULATING CUE SELECTION CORRELATIONS")
    println("Groups: ", total_groups)
    println("============================================================")

    for (group_index, g) in enumerate(grouped)

        for (metric_name, original_col, reconstructed_col) in metric_pairs

            x = Float64.(g[!, original_col])
            y = Float64.(g[!, reconstructed_col])

            valid = isfinite.(x) .& isfinite.(y)

            x_valid = x[valid]
            y_valid = y[valid]

            r = if length(x_valid) < 3 ||
                   Statistics.std(x_valid) == 0 ||
                   Statistics.std(y_valid) == 0

                NaN

            else

                Statistics.cor(x_valid, y_valid)

            end

            push!(
                correlations,
                (
                    String(g.selection_method[1]),
                    String(g.condition[1]),
                    Int(g.run_number[1]),
                    String(g.timepoint[1]),
                    Int(g.n_top_cues[1]),
                    metric_name,
                    r
                )
            )
        end

        if group_index % 500 == 0 || group_index == total_groups
            println(
                "[$group_index/$total_groups] groups completed"
            )
        end
    end

    println("============================================================")
    println("FINISHED")
    println("Correlations: ", DataFrames.nrow(correlations))
    println("============================================================")

    return correlations
end
# cue_correlations = calculate_cue_selection_correlations(results)
function plot_cue_selection_correlations(
    correlations::DataFrames.DataFrame;
    mode::Symbol=:all,
    timepoint=(:post, 0),
    error_type::Symbol=:sd,
    size=(1200, 650),
    ylim=(-1.0, 1.0),
    linewidth::Real=2.5,
    fillalpha::Real=0.18,
    fontfamily::String="Calibri")

    mode in (:all, :by_condition) ||
        error("mode must be :all or :by_condition")

    error_type in (:sd, :sem, :ci95, :none) ||
        error("error_type must be :sd, :sem, :ci95, or :none")

    tp_selected = if timepoint isa Tuple
        "$(timepoint[1])_$(timepoint[2])"
    else
        String(timepoint)
    end

    metric_names = [
        "Network",
        "Column",
        "Column top K",
        "Degree reconstructed"
    ]

    metric_colors = [
        :steelblue,
        :darkorange,
        :seagreen,
        :mediumpurple
    ]

    methods = [
        m for m in ["top", "bottom", "random"]
        if m in unique(correlations.selection_method)
    ]

    conditions = sort(unique(String.(correlations.condition)))

    # ------------------------------------------------------------
    # Fisher mean and error
    # ------------------------------------------------------------

    function summarize_group(g)

        values = Float64[
            r for r in g.r if isfinite(r)
        ]

        n = length(values)

        if n == 0
            return (
                mean_r=NaN,
                sd_r=NaN,
                sem_r=NaN,
                ci95_r=NaN,
                n=0
            )
        end

        z_values = atanh.(
            clamp.(values, -0.999999, 0.999999)
        )

        mean_r = tanh(Statistics.mean(z_values))

        sd_r = n > 1 ? Statistics.std(values) : 0.0
        sem_r = sd_r / sqrt(n)
        ci95_r = 1.96 * sem_r

        return (
            mean_r=mean_r,
            sd_r=sd_r,
            sem_r=sem_r,
            ci95_r=ci95_r,
            n=n
        )
    end

    function selected_error(row)

        if error_type == :sd
            return row.sd_r
        elseif error_type == :sem
            return row.sem_r
        elseif error_type == :ci95
            return row.ci95_r
        else
            return 0.0
        end
    end

    # ------------------------------------------------------------
    # Build summary for one plotting scope
    # ------------------------------------------------------------

    function build_summary(subset)

        if DataFrames.nrow(subset) == 0
            return DataFrames.DataFrame()
        end

        grouped = DataFrames.groupby(
            subset,
            [:selection_method, :n_top_cues, :metric];
            sort=true
        )

        rows = NamedTuple[]

        for g in grouped

            s = summarize_group(g)

            push!(
                rows,
                (
                    selection_method=String(g.selection_method[1]),
                    n_top_cues=Int(g.n_top_cues[1]),
                    metric=String(g.metric[1]),
                    mean_r=s.mean_r,
                    sd_r=s.sd_r,
                    sem_r=s.sem_r,
                    ci95_r=s.ci95_r,
                    n=s.n
                )
            )
        end

        return DataFrames.DataFrame(rows)
    end

    # ------------------------------------------------------------
    # Wide summary table
    # ------------------------------------------------------------

    function make_wide_table(summary)

        if DataFrames.nrow(summary) == 0
            return DataFrames.DataFrame()
        end

        table = DataFrames.DataFrame(
            n_top_cues=Int[],
            metric=String[]
        )

        available_methods = [
            m for m in methods
            if m in summary.selection_method
        ]

        for method in available_methods
            table[!, Symbol(method)] = String[]
        end

        ks = sort(unique(summary.n_top_cues))

        for metric in metric_names
            for k in ks

                row_values = Dict{Symbol,Any}(
                    :n_top_cues => k,
                    :metric => metric
                )

                for method in available_methods

                    matching = summary[
                        (summary.selection_method .== method) .&
                        (summary.n_top_cues .== k) .&
                        (summary.metric .== metric),
                        :
                    ]

                    if DataFrames.nrow(matching) == 0

                        row_values[Symbol(method)] = "—"

                    else

                        r = matching[1, :]

                        mean_text = string(
                            round(r.mean_r; digits=3)
                        )

                        error_text = string(
                            round(selected_error(r); digits=3)
                        )

                        row_values[Symbol(method)] =
                            error_type == :none ?
                            mean_text :
                            "$mean_text ± $error_text"
                    end
                end

                push!(
                    table,
                    row_values;
                    cols=:setequal
                )
            end
        end

        return table
    end

    # ------------------------------------------------------------
    # Draw one plot for one method
    # ------------------------------------------------------------

    function draw_plot(summary, method, title_text)

        p = Plots.plot(
            size=size,
            xlabel="Number of cue words",
            ylabel="Pearson correlation (r)",
            title=title_text,
            ylim=ylim,
            legend=:bottomright,
            linewidth=linewidth,
            fontfamily=fontfamily,
            grid=true,
            framestyle=:box
        )

        method_data = summary[
            summary.selection_method .== method,
            :
        ]

        for (metric_index, metric) in enumerate(metric_names)

            g = method_data[
                method_data.metric .== metric,
                :
            ]

            DataFrames.nrow(g) == 0 && continue

            DataFrames.sort!(g, :n_top_cues)

            x = Int.(g.n_top_cues)
            y = Float64.(g.mean_r)

            errors = Float64[
                selected_error(row)
                for row in eachrow(g)
            ]

            if error_type == :none

                Plots.plot!(
                    p,
                    x,
                    y;
                    label=metric,
                    color=metric_colors[metric_index],
                    linewidth=linewidth
                )

            else

                Plots.plot!(
                    p,
                    x,
                    y;
                    label=metric,
                    color=metric_colors[metric_index],
                    linewidth=linewidth,
                    ribbon=errors,
                    fillalpha=fillalpha
                )
            end
        end

        return p
    end

    # ------------------------------------------------------------
    # Main plotting
    # ------------------------------------------------------------

    plots = Dict{Tuple{String,String,String},Any}()
    summaries = Dict{Tuple{String,String},DataFrames.DataFrame}()
    tables = Dict{Tuple{String,String},DataFrames.DataFrame}()

    scopes = Tuple{String,String}[]

    if mode == :all

        for tp in ["post_0", "post_100"]
            push!(scopes, (tp, "all"))
        end

    else

        tp_selected in unique(correlations.timepoint) ||
            error("Timepoint $tp_selected not found")

        for condition in conditions
            push!(scopes, (tp_selected, condition))
        end
    end

    for (tp, condition) in scopes

        subset = if condition == "all"

            correlations[
                correlations.timepoint .== tp,
                :
            ]

        else

            correlations[
                (correlations.timepoint .== tp) .&
                (correlations.condition .== condition),
                :
            ]
        end

        summary = build_summary(subset)

        DataFrames.nrow(summary) == 0 && continue

        key = (tp, condition)

        summaries[key] = summary
        tables[key] = make_wide_table(summary)

        println()
        println("============================================================")
        println(
            condition == "all" ?
            "All conditions — $tp" :
            "$condition — $tp"
        )
        println("Error: ", error_type)
        println("============================================================")

        # Separate plot for each selection method.
        for method in methods

            method in summary.selection_method || continue

            title_text = if condition == "all"

                "$(uppercasefirst(method)) cues — $tp — All conditions"

            else

                "$(uppercasefirst(method)) cues — $tp — $condition"

            end

            p = draw_plot(
                summary,
                method,
                title_text
            )

            plots[(tp, condition, method)] = p

            display(p)
        end

        println()
        println("SUMMARY TABLE")
        println(
            "Values: Fisher mean r",
            error_type == :none ?
            "" :
            " ± $(uppercase(String(error_type)))"
        )

        show(
            stdout,
            MIME("text/plain"),
            tables[key];
            allrows=true,
            allcols=true
        )

        println()
    end

    return (
        plots=plots,
        summaries=summaries,
        tables=tables
    )
end
# output = plot_cue_selection_correlations(
#     cue_correlations;
#     mode=:all,
#     error_type=:sd,
#     size=(1200, 650),
#     ylim=(-1, 1),
#     linewidth=2.5,
#     fillalpha=0.18
# )

# 1
function plot_cue_selection_six_panel(
    cue_correlations::DataFrames.AbstractDataFrame;

    # ============================================================
    # PANEL ORGANIZATION
    # ============================================================

    rows_by::Symbol = :metric,
    cols_by::Symbol = :timepoint,

    metrics::Vector{String} = [
        "Network",
        "Column",
        "Degree reconstructed"
    ],

    timepoints::Vector{String} = [
        "post_0",
        "post_100"
    ],

    methods::Vector{String} = [
        "top",
        "bottom",
        "random"
    ],

    # ============================================================
    # LABELS
    # ============================================================

    metric_labels::Dict = Dict(
        "Network" => "Network distance",
        "Column" => "Column distance",
        "Degree reconstructed" => "Degree distance"
    ),

    timepoint_labels::Dict = Dict(
        "post_0" => "At crossing",
        "post_100" => "Final"
    ),

    method_labels::Dict = Dict(
        "top" => "Top degree",
        "bottom" => "Bottom degree",
        "random" => "Random"
    ),

    show_row_titles::Bool = true,
    show_column_titles::Bool = true,

    row_title_size::Int = 13,
    column_title_size::Int = 14,

    xlabel::String = "Number of cues (K)",
    ylabel::String = "Mean Pearson correlation",

    xlabel_size::Int = 11,
    ylabel_size::Int = 11,
    tickfontsize::Int = 9,

    show_xlabel_only_bottom::Bool = true,
    show_ylabel_only_left::Bool = true,

    # ============================================================
    # AXES
    # ============================================================

    xlims = nothing,

    # :row    = same Y limits within each row
    # :all    = same Y limits across all panels
    # :manual = use manual_ylims
    y_scale::Symbol = :row,

    manual_ylims = nothing,
    y_padding::Real = 0.05,

    # ============================================================
    # ZERO LINE
    # ============================================================

    show_zero_line::Bool = true,
    zero_line_color = :black,
    zero_line_width::Real = 2.0,
    zero_line_style::Symbol = :solid,
    zero_line_alpha::Real = 0.9,

    # ============================================================
    # LEGEND
    # ============================================================

    # :separate = dedicated legend panel
    # :first    = legend in first graph
    # :all      = legend in all graphs
    # :none     = no legend
    legend_in::Symbol = :separate,

    legend_position = :topright,
    legend_fontsize::Int = 11,
    legend_title::String = "Cue selection",

    # ============================================================
    # APPEARANCE
    # ============================================================

    method_colors::Dict = Dict(
        "top" => :steelblue,
        "bottom" => :darkorange,
        "random" => :forestgreen
    ),

    linewidth::Real = 2.5,

    show_ribbon::Bool = true,
    ribbon_alpha::Real = 0.18,

    show_markers::Bool = false,
    markersize::Real = 2.5,

    fontfamily::String = "Calibri",
    grid::Bool = true,

    plot_size::Tuple{Int,Int} = (1500, 1100),
    dpi::Int = 150,

    panel_title::String = "",
    panel_title_size::Int = 15)

    # ============================================================
    # VALIDATION
    # ============================================================

    rows_by in (:metric, :timepoint) ||
        error("rows_by must be :metric or :timepoint")

    cols_by in (:metric, :timepoint) ||
        error("cols_by must be :metric or :timepoint")

    rows_by != cols_by ||
        error("rows_by and cols_by must be different")

    y_scale in (:row, :all, :manual) ||
        error("y_scale must be :row, :all or :manual")

    legend_in in (:separate, :first, :all, :none) ||
        error("Invalid legend_in")

    if y_scale == :manual && manual_ylims === nothing
        error("manual_ylims must be provided for y_scale=:manual")
    end

    # ============================================================
    # PREPARE DATA
    # ============================================================

    df = DataFrames.DataFrame(cue_correlations)

    required_columns = [
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues,
        :r
    ]

    for col in required_columns
        col in propertynames(df) ||
            error("Missing column: $col")
    end

    for col in (:timepoint, :metric, :selection_method)
        df[!, col] = string.(df[!, col])
    end

    filter!(
        row ->
            row.timepoint in timepoints &&
            row.metric in metrics &&
            row.selection_method in methods &&
            !ismissing(row.r) &&
            isfinite(row.r),
        df
    )

    isempty(df) && error("No matching data found")

    # ============================================================
    # SUMMARY
    # ============================================================

    summary = DataFrames.combine(
        DataFrames.groupby(
            df,
            [
                :timepoint,
                :metric,
                :selection_method,
                :n_top_cues
            ]
        ),

        :r => Statistics.mean => :mean_r,

        :r => (
            x -> length(x) > 1 ?
                Statistics.std(x) : 0.0
        ) => :sd,

        :r => length => :n
    )

    DataFrames.sort!(
        summary,
        [
            :timepoint,
            :metric,
            :selection_method,
            :n_top_cues
        ]
    )

    # ============================================================
    # PANEL ORGANIZATION
    # ============================================================

    row_values = rows_by == :metric ?
        metrics : timepoints

    col_values = cols_by == :metric ?
        metrics : timepoints

    nrows = length(row_values)
    ncols = length(col_values)

    # ============================================================
    # Y LIMITS
    # ============================================================

    function data_limits(sub)

        isempty(sub) && error("Cannot calculate Y limits")

        errors = show_ribbon ?
            sub.sd : zeros(DataFrames.nrow(sub))

        lo = minimum(sub.mean_r .- errors)
        hi = maximum(sub.mean_r .+ errors)

        if show_zero_line
            lo = min(lo, 0.0)
            hi = max(hi, 0.0)
        end

        span = hi - lo
        pad = span > 0 ? span * y_padding : 0.05

        return (lo - pad, hi + pad)
    end

    row_limits = Tuple{Float64,Float64}[]

    if y_scale == :all

        lim = data_limits(summary)

        row_limits = fill(lim, nrows)

    elseif y_scale == :row

        for row_value in row_values

            sub = if rows_by == :metric
                summary[summary.metric .== row_value, :]
            else
                summary[summary.timepoint .== row_value, :]
            end

            push!(row_limits, data_limits(sub))
        end

    else

        if manual_ylims isa Tuple

            row_limits = fill(
                (
                    Float64(manual_ylims[1]),
                    Float64(manual_ylims[2])
                ),
                nrows
            )

        elseif manual_ylims isa AbstractVector

            length(manual_ylims) == nrows ||
                error("manual_ylims must have one tuple per row")

            row_limits = [
                (Float64(v[1]), Float64(v[2]))
                for v in manual_ylims
            ]

        else
            error("Invalid manual_ylims")
        end
    end

    # ============================================================
    # BUILD PANELS
    # ============================================================

    panels = Any[]

    for (row_i, row_value) in enumerate(row_values)

        for (col_i, col_value) in enumerate(col_values)

            metric = rows_by == :metric ?
                row_value : col_value

            tp = rows_by == :timepoint ?
                row_value : col_value

            col_label = cols_by == :metric ?
                get(metric_labels, col_value, col_value) :
                get(timepoint_labels, col_value, col_value)

            row_label = rows_by == :metric ?
                get(metric_labels, row_value, row_value) :
                get(timepoint_labels, row_value, row_value)

            title_text = (
                show_column_titles && row_i == 1
            ) ? col_label : ""

            ylabel_text = if !show_ylabel_only_left || col_i == 1
                ylabel
            else
                ""
            end

            xlabel_text = (
                !show_xlabel_only_bottom || row_i == nrows
            ) ? xlabel : ""

            show_legend = (
                legend_in == :all ||
                (legend_in == :first &&
                 row_i == 1 && col_i == 1)
            )

            p = Plots.plot(
                title = title_text,
                titlefontsize = column_title_size,
                xlabel = xlabel_text,
                ylabel = ylabel_text,
                xguidefontsize = xlabel_size,
                yguidefontsize = show_row_titles ?
                    row_title_size : ylabel_size,
                tickfontsize = tickfontsize,
                fontfamily = fontfamily,
                legend = show_legend ?
                    legend_position : false,
                legendfontsize = legend_fontsize,
                grid = grid,
                ylims = row_limits[row_i],
                dpi = dpi
            )

            for method in methods

                sub = summary[
                    (summary.metric .== metric) .&
                    (summary.timepoint .== tp) .&
                    (summary.selection_method .== method),
                    :
                ]

                isempty(sub) && continue

                DataFrames.sort!(sub, :n_top_cues)

                Plots.plot!(
                    p,
                    sub.n_top_cues,
                    sub.mean_r;
                    label = get(method_labels, method, method),
                    color = get(method_colors, method, :black),
                    linewidth = linewidth,
                    ribbon = show_ribbon ? sub.sd : nothing,
                    fillalpha = ribbon_alpha,
                    marker = show_markers ? :circle : :none,
                    markersize = markersize
                )
            end

            if show_zero_line
                Plots.hline!(
                    p,
                    [0.0];
                    color = zero_line_color,
                    linewidth = zero_line_width,
                    linestyle = zero_line_style,
                    alpha = zero_line_alpha,
                    label = ""
                )
            end

            if xlims !== nothing
                Plots.xlims!(p, xlims)
            end

            push!(panels, p)
        end
    end

    
    # ============================================================
    # FINAL SIX-PANEL FIGURE
    # ============================================================

    final_plot = Plots.plot(
        panels...;
        layout = (nrows, ncols),
        size = plot_size,
        plot_title = panel_title,
        plot_titlefontsize = panel_title_size,
        fontfamily = fontfamily,
        dpi = dpi
    )

    display(final_plot)

    # ============================================================
    # COMPLETELY SEPARATE LEGEND FIGURE
    # ============================================================

    legend_plot = nothing

    if legend_in == :separate

        legend_plot = Plots.plot(
            xlims = (0, 1),
            ylims = (0, 1),
            framestyle = :none,
            showaxis = false,
            grid = false,
            legend = :top,
            legendfontsize = legend_fontsize,
            legendtitle = legend_title,
            fontfamily = fontfamily,
            size = (550, 220),
            dpi = dpi
        )

        for method in methods

            Plots.plot!(
                legend_plot,
                [2.0, 3.0],
                [2.0, 3.0];
                label = get(method_labels, method, method),
                color = get(method_colors, method, :black),
                linewidth = linewidth
            )
        end

        display(legend_plot)
    end

    return (
        plot = final_plot,
        legend_plot = legend_plot,
        summary = summary
    )
end
