#     # ============================================================

#     plot_size = (1500, 1100),
#     dpi = 300,

#     panel_title = "",
#     panel_title_size = 15
# )

function cue_correlation_sd_table(
    cue_correlations::DataFrames.AbstractDataFrame;

    # Data selection
    timepoints = ["post_0", "post_100"],
    methods = ["top", "bottom", "random"],
    metrics = [
        "Network",
        "Column",
        "Degree reconstructed"
    ],

    timepoint_labels = Dict(
        "post_0" => "Crossing",
        "post_100" => "Final"
    ),

    method_labels = Dict(
        "top" => "Highest-degree",
        "bottom" => "Lowest-degree",
        "random" => "Random"
    ),

    metric_labels = Dict(
        "Network" => "Network",
        "Column" => "Column",
        "Degree reconstructed" => "Degree"
    ),

    # Number formatting
    digits::Int = 3,
    sd_format::Symbol = :plusminus,
    missing_text::String = "—",

    # Column layout
    column_headers = ["Timepoint", "Selection method"],
    column_widths = [1.5, 2.4, 1.8, 1.8, 1.8],

    method_alignment::Symbol = :center,
    method_text_padding::Real = 0.05,

    # Row layout
    row_height::Real = 1.0,
    header_height::Real = 1.1,
    top_padding::Real = 0.15,
    bottom_padding::Real = 0.15,

    # Text
    fontfamily::String = "Calibri",
    header_fontsize::Int = 12,
    body_fontsize::Int = 11,
    group_fontsize::Int = 11,
    header_bold::Bool = true,
    header_line_spacing::Real = 0.25,

    # Lines
    show_horizontal_lines::Bool = true,
    show_vertical_lines::Bool = false,
    show_outer_border::Bool = false,
    show_group_separators::Bool = true,

    show_header_separator::Bool = true,
    show_method_separators::Bool = true,

    line_color = :black,
    line_width::Real = 0.8,
    outer_line_width::Real = 1.3,
    group_line_width::Real = 1.1,
    header_line_width::Real = 1.0,
    method_line_width::Real = 0.6,

    # Figure
    figure_size::Tuple{Int,Int} = (1300, 500),
    dpi::Int = 300,
    background_color = :white,

    # Output
    print_table::Bool = true,
    display_plot::Bool = true)

    # ============================================================
    # VALIDATION
    # ============================================================

    sd_format in (:plusminus, :parentheses) ||
        error("sd_format must be :plusminus or :parentheses")

    method_alignment in (:left, :center, :right) ||
        error("method_alignment must be :left, :center or :right")

    digits >= 0 ||
        error("digits must be nonnegative")

    length(column_headers) == 2 ||
        error("column_headers must contain two labels")

    length(column_widths) == 2 + length(metrics) ||
        error("column_widths must contain one width per column")

    all(w -> w > 0, column_widths) ||
        error("All column widths must be positive")

    row_height > 0 || error("row_height must be positive")
    header_height > 0 || error("header_height must be positive")

    # ============================================================
    # PREPARE DATA
    # ============================================================

    df = DataFrames.DataFrame(cue_correlations)

    required_columns = [
        :condition,
        :run_number,
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues,
        :r
    ]

    for col in required_columns
        col in propertynames(df) ||
            error("Missing column: $col")
    end

    for col in (
        :condition,
        :timepoint,
        :metric,
        :selection_method
    )
        df[!, col] = string.(df[!, col])
    end

    filter!(
        row ->
            row.timepoint in timepoints &&
            row.metric in metrics &&
            row.selection_method in methods &&
            !ismissing(row.r) &&
            isfinite(row.r),
        df
    )

    isempty(df) && error("No matching data found")

    # ============================================================
    # STAGE 1: SD ACROSS RUNS FOR EACH K
    # ============================================================

    run_keys = [
        :condition,
        :run_number,
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues
    ]

    counts = DataFrames.combine(
        DataFrames.groupby(df, run_keys),
        DataFrames.nrow => :count
    )

    any(counts.count .> 1) &&
        error("Duplicate run observations found")

    sd_by_k = DataFrames.combine(
        DataFrames.groupby(
            df,
            [
                :timepoint,
                :metric,
                :selection_method,
                :n_top_cues
            ]
        ),

        :r => (
            x -> length(x) >= 2 ?
                Statistics.std(x) : NaN
        ) => :sd_across_runs,

        :r => length => :n_runs
    )

    # ============================================================
    # STAGE 2: MEAN AND SD ACROSS K
    # ============================================================

    DataFrames.filter!(
        row -> isfinite(row.sd_across_runs),
        sd_by_k
    )

    isempty(sd_by_k) &&
        error("No K values with at least two valid runs")

    summary = DataFrames.combine(
        DataFrames.groupby(
            sd_by_k,
            [:timepoint, :metric, :selection_method]
        ),

        :sd_across_runs =>
            Statistics.mean =>
            :mean_sd_across_runs,

        :sd_across_runs => (
            x -> length(x) >= 2 ?
                Statistics.std(x) : NaN
        ) => :sd_across_k,

        :n_top_cues => length => :n_k,

        :n_runs => minimum => :min_runs_per_k,
        :n_runs => maximum => :max_runs_per_k
    )

    # ============================================================
    # FORMAT VALUES
    # ============================================================

    function format_number(x)

        if ismissing(x) || !isfinite(x)
            return missing_text
        end

        return Printf.@sprintf("%.*f", digits, Float64(x))
    end

    function format_cell(mean_value, sd_value)

        m = format_number(mean_value)
        s = format_number(sd_value)

        if sd_format == :plusminus
            return "$m ± $s"
        else
            return "$m ($s)"
        end
    end

    # ============================================================
    # BUILD WIDE TABLE
    # ============================================================

    wide_table = DataFrames.DataFrame(
        Timepoint = String[],
        Method = String[]
    )

    for metric in metrics
        wide_table[!, metric] = String[]
    end

    for tp in timepoints

        for (method_i, method) in enumerate(methods)

            values = String[]

            for metric in metrics

                sub = summary[
                    (summary.timepoint .== tp) .&
                    (summary.metric .== metric) .&
                    (summary.selection_method .== method),
                    :
                ]

                if DataFrames.nrow(sub) == 0
                    push!(values, missing_text)
                else
                    push!(
                        values,
                        format_cell(
                            sub.mean_sd_across_runs[1],
                            sub.sd_across_k[1]
                        )
                    )
                end
            end

            push!(
                wide_table,
                (
                    method_i == 1 ?
                        get(timepoint_labels, tp, tp) : "",
                    get(method_labels, method, method),
                    values...
                )
            )
        end
    end

    # ============================================================
    # PRINT TABLE
    # ============================================================

    if print_table

        println("\n", "="^95)
        println("VARIABILITY OF CORRELATIONS ACROSS RUNS")
        println("="^95)

        show(
            stdout,
            MIME("text/plain"),
            wide_table;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    # ============================================================
    # TABLE GEOMETRY
    # ============================================================

    n_groups = length(timepoints)
    n_methods = length(methods)
    n_data_rows = n_groups * n_methods
    n_columns = 2 + length(metrics)

    total_width = sum(column_widths)

    total_height =
        top_padding +
        header_height +
        n_data_rows * row_height +
        bottom_padding

    x_edges = vcat(
        0.0,
        cumsum(Float64.(column_widths))
    )

    x_centers = [
        (x_edges[i] + x_edges[i+1]) / 2
        for i in 1:n_columns
    ]

    table_top = total_height - top_padding
    header_bottom = table_top - header_height

    row_centers = [
        header_bottom - (i - 0.5) * row_height
        for i in 1:n_data_rows
    ]

    table_bottom = header_bottom - n_data_rows * row_height

    # ============================================================
    # CREATE FIGURE
    # ============================================================

    p = Plots.plot(
        xlims = (0, total_width),
        ylims = (0, total_height),
        size = figure_size,
        dpi = dpi,
        legend = false,
        framestyle = :none,
        showaxis = false,
        grid = false,
        fontfamily = fontfamily,
        background_color = background_color,
        margin = 0Plots.mm
    )

    # ============================================================
    # HEADER
    # ============================================================

    headers = vcat(
        column_headers,
        [
            get(metric_labels, metric, metric)
            for metric in metrics
        ]
    )

    header_y = (table_top + header_bottom) / 2

    for (i, header) in enumerate(headers)

        lines = split(header, '\n')
        n_lines = length(lines)

        line_spacing = header_line_spacing

        for (j, line) in enumerate(lines)

            y = header_y +
                ((n_lines + 1) / 2 - j) * line_spacing

            Plots.annotate!(
                p,
                x_centers[i],
                y,
                Plots.text(
                    line,
                    header_fontsize,
                    :black,
                    :center,
                    fontfamily;
                    bold = header_bold
                )
            )
        end
    end

    # ============================================================
    # BODY
    # ============================================================

    for (group_i, tp) in enumerate(timepoints)

        group_start = (group_i - 1) * n_methods + 1
        group_end = group_i * n_methods

        group_center = Statistics.mean(
            row_centers[group_start:group_end]
        )

        Plots.annotate!(
            p,
            x_centers[1],
            group_center,
            Plots.text(
                get(timepoint_labels, tp, tp),
                group_fontsize,
                :black,
                :center,
                fontfamily
            )
        )

        for (method_i, method) in enumerate(methods)

            row_i = group_start + method_i - 1
            y = row_centers[row_i]

            # Method alignment
            method_x = if method_alignment == :left
                x_edges[2] + method_text_padding
            elseif method_alignment == :right
                x_edges[3] - method_text_padding
            else
                x_centers[2]
            end

            Plots.annotate!(
                p,
                method_x,
                y,
                Plots.text(
                    get(method_labels, method, method),
                    body_fontsize,
                    :black,
                    method_alignment,
                    fontfamily
                )
            )

            for (metric_i, metric) in enumerate(metrics)

                value_text = wide_table[
                    row_i,
                    Symbol(metric)
                ]

                Plots.annotate!(
                    p,
                    x_centers[metric_i + 2],
                    y,
                    Plots.text(
                        value_text,
                        body_fontsize,
                        :black,
                        :center,
                        fontfamily
                    )
                )
            end
        end
    end

    # ============================================================
    # LINES
    # ============================================================

    function draw_horizontal(y, width; x_start=0.0)

        Plots.plot!(
            p,
            [x_start, total_width],
            [y, y];
            color = line_color,
            linewidth = width,
            label = ""
        )
    end

    function draw_vertical(x, width)

        Plots.plot!(
            p,
            [x, x],
            [table_bottom, table_top];
            color = line_color,
            linewidth = width,
            label = ""
        )
    end

    # Header separator
    if show_header_separator
        draw_horizontal(header_bottom, header_line_width)
    end

    # Method separators
    if show_method_separators && show_horizontal_lines

        for group_i in 1:n_groups

            for method_i in 1:(n_methods - 1)

                row_i =
                    (group_i - 1) * n_methods + method_i

                y = header_bottom - row_i * row_height

                draw_horizontal(
                    y,
                    method_line_width;
                    x_start = x_edges[2]
                )
            end
        end
    end

    # Group separators
    if show_group_separators

        for group_i in 1:(n_groups - 1)

            y = header_bottom -
                group_i * n_methods * row_height

            draw_horizontal(y, group_line_width)
        end
    end

    # Vertical lines
    if show_vertical_lines

        for x in x_edges[2:end-1]
            draw_vertical(x, line_width)
        end
    end

    # Outer border
    if show_outer_border

        draw_horizontal(table_top, outer_line_width)
        draw_horizontal(table_bottom, outer_line_width)

        draw_vertical(0.0, outer_line_width)
        draw_vertical(total_width, outer_line_width)

    else

        draw_horizontal(table_top, outer_line_width)
        draw_horizontal(table_bottom, outer_line_width)
    end

    if display_plot
        display(p)
    end

    return (
        summary = summary,
        sd_by_k = sd_by_k,
        table = wide_table,
        plot = p
    )
end
