# 2
function cue_selection_difference_table(
    cue_correlations::DataFrames.AbstractDataFrame;

    # Data
    timepoints = ["post_0", "post_100"],
    metrics = ["Network", "Column", "Degree reconstructed"],

    timepoint_labels = Dict(
        "post_0" => "Crossing Step",
        "post_100" => "Final Step"
    ),

    difference_labels = Dict(
        "bottom - random" => "Lowest − Random",
        "bottom - top" => "Lowest − Highest",
        "random - top" => "Random − Highest"
    ),

    metric_labels = Dict(
        "Network" => "TVD from the\nMean Network",
        "Column" => "Mean Column-\nNormalized TVD",
        "Degree reconstructed" => "Degree-Distribution\nTVD"
    ),

    # Statistical tests
    n_permutations::Int = 10000,
    n_bootstrap::Int = 10000,
    confidence_level::Float64 = 0.95,
    random_seed::Int = 12345,

    # Number formatting
    digits::Int = 3,
    sd_format::Symbol = :parentheses,
    missing_text::String = "—",

    # Columns
    column_headers = ["Time\nPoint", "Difference"],
    column_widths = [1.5, 2.4, 1.8, 1.8, 1.8],
    method_alignment::Symbol = :left,
    method_text_padding::Real = 0.05,

    # Rows
    row_height::Real = 1.0,
    header_height::Real = 1.5,
    header_line_spacing::Real = 0.3,
    top_padding::Real = 0.15,
    bottom_padding::Real = 0.15,

    # Text
    fontfamily::String = "Calibri",
    header_fontsize::Int = 12,
    body_fontsize::Int = 11,
    group_fontsize::Int = 15,
    header_bold::Bool = true,

    # Lines
    show_horizontal_lines::Bool = true,
    show_vertical_lines::Bool = true,
    show_outer_border::Bool = true,
    show_group_separators::Bool = true,
    show_header_separator::Bool = true,
    show_method_separators::Bool = false,

    line_color = :black,
    line_width::Real = 0.8,
    outer_line_width::Real = 1.3,
    group_line_width::Real = 1.1,
    header_line_width::Real = 1.0,
    method_line_width::Real = 0.6,

    # Figure
    figure_size::Tuple{Int,Int} = (1100, 400),
    dpi::Int = 300,
    background_color = :white,

    # Output
    print_table::Bool = true,
    print_statistics::Bool = true,
    display_plot::Bool = true)

    # ============================================================
    # VALIDATION
    # ============================================================

    sd_format in (:plusminus, :parentheses) ||
        error("Invalid sd_format")

    method_alignment in (:left, :center, :right) ||
        error("Invalid method_alignment")

    n_permutations > 0 || error("n_permutations must be positive")
    n_bootstrap > 0 || error("n_bootstrap must be positive")

    0 < confidence_level < 1 ||
        error("confidence_level must be between 0 and 1")

    digits >= 0 || error("digits must be nonnegative")

    length(column_headers) == 2 ||
        error("column_headers must have two entries")

    length(column_widths) == length(metrics) + 2 ||
        error("Incorrect number of column widths")

    all(>(0), column_widths) ||
        error("Column widths must be positive")

    row_height > 0 || error("row_height must be positive")
    header_height > 0 || error("header_height must be positive")

    # ============================================================
    # PREPARE DATA
    # ============================================================

    df = DataFrames.DataFrame(cue_correlations)

    required = [
        :condition,
        :run_number,
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues,
        :r
    ]

    for col in required
        col in propertynames(df) ||
            error("Missing column: $col")
    end

    for col in (
        :condition,
        :timepoint,
        :metric,
        :selection_method
    )
        df[!, col] = string.(df[!, col])
    end

    methods = ["bottom", "random", "top"]

    filter!(
        row ->
            row.timepoint in timepoints &&
            row.metric in metrics &&
            row.selection_method in methods &&
            !ismissing(row.r) &&
            isfinite(row.r),
        df
    )

    isempty(df) && error("No matching data found")

    # ============================================================
    # CHECK DUPLICATES
    # ============================================================

    run_keys = [
        :condition,
        :run_number,
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues
    ]

    counts = DataFrames.combine(
        DataFrames.groupby(df, run_keys),
        DataFrames.nrow => :n
    )

    any(counts.n .> 1) &&
        error("Duplicate observations found")

    # ============================================================
    # WITHIN-RUN PAIRED DIFFERENCES
    # ============================================================

    pairs = [
        ("bottom", "random"),
        ("bottom", "top"),
        ("random", "top")
    ]

    comparisons = [
        "$a - $b" for (a, b) in pairs
    ]

    run_rows = NamedTuple[]

    grouped = DataFrames.groupby(
        df,
        [:condition, :run_number, :timepoint, :metric]
    )

    for g in grouped

        method_tables = DataFrames.DataFrame[]

        for method in methods

            sub = g[
                g.selection_method .== method,
                [:n_top_cues, :r]
            ]

            DataFrames.rename!(
                sub,
                :r => Symbol(method)
            )

            push!(method_tables, sub)
        end

        # Same K values for all three methods
        aligned = reduce(
            (a, b) -> DataFrames.innerjoin(
                a, b;
                on = :n_top_cues
            ),
            method_tables
        )

        DataFrames.nrow(aligned) == 0 && continue

        for (a, b) in pairs

            differences =
                aligned[!, Symbol(a)] .-
                aligned[!, Symbol(b)]

            push!(
                run_rows,
                (
                    condition = g.condition[1],
                    run_number = g.run_number[1],
                    timepoint = g.timepoint[1],
                    metric = g.metric[1],
                    comparison = "$a - $b",
                    n_k = length(differences),
                    difference = Statistics.mean(differences)
                )
            )
        end
    end

    isempty(run_rows) &&
        error("No complete paired observations found")

    run_results = DataFrames.DataFrame(run_rows)

    # ============================================================
    # PERMUTATION AND BOOTSTRAP
    # ============================================================

    rng = Random.MersenneTwister(random_seed)

    summary_rows = NamedTuple[]

    statistical_groups = DataFrames.groupby(
        run_results,
        [:timepoint, :metric, :comparison]
    )

    for (group_i, g) in enumerate(statistical_groups)

        x = Float64.(g.difference)
        n = length(x)

        observed_mean = Statistics.mean(x)
        observed_sd = n > 1 ? Statistics.std(x) : NaN

        # Sign-flipping permutation test
        extreme_count = 0

        for perm_i in 1:n_permutations

            perm_sum = 0.0

            for value in x
                perm_sum += Random.rand(rng, Bool) ?
                    value : -value
            end

            perm_mean = perm_sum / n

            if abs(perm_mean) >= abs(observed_mean) - 1e-12
                extreme_count += 1
            end
        end

        p_raw = (extreme_count + 1) /
                (n_permutations + 1)

        # Bootstrap over runs
        bootstrap_means = Vector{Float64}(
            undef,
            n_bootstrap
        )

        for b in 1:n_bootstrap

            total = 0.0

            for j in 1:n
                idx = Random.rand(rng, 1:n)
                total += x[idx]
            end

            bootstrap_means[b] = total / n
        end

        alpha = 1 - confidence_level

        ci_lower = Statistics.quantile(
            bootstrap_means,
            alpha / 2
        )

        ci_upper = Statistics.quantile(
            bootstrap_means,
            1 - alpha / 2
        )

        push!(
            summary_rows,
            (
                timepoint = g.timepoint[1],
                metric = g.metric[1],
                comparison = g.comparison[1],
                n_runs = n,
                mean = observed_mean,
                sd = observed_sd,
                ci_lower = ci_lower,
                ci_upper = ci_upper,
                p_raw = p_raw
            )
        )

        println(
            "Statistical tests: ",
            group_i, "/", length(statistical_groups),
            " | ", g.timepoint[1],
            " | ", g.metric[1],
            " | ", g.comparison[1]
        )
    end

    summary = DataFrames.DataFrame(summary_rows)

    # ============================================================
    # HOLM CORRECTION
    # ============================================================

    m = length(timepoints) * length(metrics) * length(pairs)

    # Include all 18 planned tests in the correction
    DataFrames.nrow(summary) == m ||
        error(
            "Expected $m comparisons, found " *
            "$(DataFrames.nrow(summary)). " *
            "Check missing data."
        )

    order = sortperm(summary.p_raw)

    adjusted = zeros(Float64, m)
    running_max = 0.0

    for (rank, idx) in enumerate(order)

        candidate = min(
            1.0,
            (m - rank + 1) * summary.p_raw[idx]
        )

        running_max = max(running_max, candidate)
        adjusted[idx] = running_max
    end

    summary[!, :p_holm] = adjusted

    # ============================================================
    # SORT RESULTS
    # ============================================================

    tp_order = Dict(
        x => i for (i, x) in enumerate(timepoints)
    )

    metric_order = Dict(
        x => i for (i, x) in enumerate(metrics)
    )

    comparison_order = Dict(
        x => i for (i, x) in enumerate(comparisons)
    )

    DataFrames.sort!(
        summary,
        [
            DataFrames.order(
                :timepoint,
                by = x -> tp_order[x]
            ),
            DataFrames.order(
                :metric,
                by = x -> metric_order[x]
            ),
            DataFrames.order(
                :comparison,
                by = x -> comparison_order[x]
            )
        ]
    )

    # ============================================================
    # NUMBER FORMATTING
    # ============================================================

    function format_number(x)

        if ismissing(x) || !isfinite(x)
            return missing_text
        end

        return Printf.@sprintf(
            "%.*f",
            digits,
            Float64(x)
        )
    end

    function format_cell(m, s)

        a = format_number(m)
        b = format_number(s)

        return sd_format == :parentheses ?
            "$a ($b)" : "$a ± $b"
    end

    # ============================================================
    # BUILD WIDE TABLE
    # ============================================================

    wide_table = DataFrames.DataFrame(
        Timepoint = String[],
        Difference = String[]
    )

    for metric in metrics
        wide_table[!, metric] = String[]
    end

    for tp in timepoints

        for (comparison_i, comparison) in enumerate(comparisons)

            values = String[]

            for metric in metrics

                sub = summary[
                    (summary.timepoint .== tp) .&
                    (summary.metric .== metric) .&
                    (summary.comparison .== comparison),
                    :
                ]

                if DataFrames.nrow(sub) == 0

                    push!(values, missing_text)

                else

                    push!(
                        values,
                        format_cell(
                            sub.mean[1],
                            sub.sd[1]
                        )
                    )
                end
            end

            push!(
                wide_table,
                (
                    comparison_i == 1 ?
                        get(timepoint_labels, tp, tp) : "",
                    get(
                        difference_labels,
                        comparison,
                        comparison
                    ),
                    values...
                )
            )
        end
    end

    # ============================================================
    # PRINT TABLES
    # ============================================================

    if print_table

        println("\n", "="^90)
        println("MEAN PAIRED DIFFERENCES (SD)")
        println("="^90)

        show(
            stdout,
            MIME("text/plain"),
            wide_table;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    if print_statistics

        println("\n", "="^90)
        println("PERMUTATION TESTS, HOLM CORRECTION AND BOOTSTRAP CIs")
        println("="^90)

        stats_table = DataFrames.select(
            summary,
            :timepoint,
            :metric,
            :comparison,
            :n_runs,
            :mean,
            :sd,
            :ci_lower,
            :ci_upper,
            :p_raw,
            :p_holm
        )

        show(
            stdout,
            MIME("text/plain"),
            stats_table;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    # ============================================================
    # TABLE GEOMETRY
    # ============================================================

    n_groups = length(timepoints)
    n_comparisons = length(comparisons)
    n_rows = n_groups * n_comparisons
    n_columns = length(metrics) + 2

    total_width = sum(column_widths)

    total_height =
        top_padding +
        header_height +
        n_rows * row_height +
        bottom_padding

    x_edges = vcat(
        0.0,
        cumsum(Float64.(column_widths))
    )

    x_centers = [
        (x_edges[i] + x_edges[i+1]) / 2
        for i in 1:n_columns
    ]

    table_top = total_height - top_padding
    header_bottom = table_top - header_height

    row_centers = [
        header_bottom - (i - 0.5) * row_height
        for i in 1:n_rows
    ]

    table_bottom =
        header_bottom - n_rows * row_height

    # ============================================================
    # CREATE FIGURE
    # ============================================================

    p = Plots.plot(
        xlims = (0, total_width),
        ylims = (0, total_height),
        size = figure_size,
        dpi = dpi,
        legend = false,
        framestyle = :none,
        showaxis = false,
        grid = false,
        fontfamily = fontfamily,
        background_color = background_color,
        margin = 0Plots.mm
    )

    # ============================================================
    # HEADERS WITH MULTIPLE LINES
    # ============================================================

    headers = vcat(
        column_headers,
        [
            get(metric_labels, metric, metric)
            for metric in metrics
        ]
    )

    header_y = (table_top + header_bottom) / 2

    for (i, header) in enumerate(headers)

        lines = split(header, '\n')
        n_lines = length(lines)

        for (j, line) in enumerate(lines)

            y = header_y +
                ((n_lines + 1) / 2 - j) *
                header_line_spacing

            Plots.annotate!(
                p,
                x_centers[i],
                y,
                Plots.text(
                    line,
                    header_fontsize,
                    :black,
                    :center,
                    fontfamily;
                    bold = header_bold
                )
            )
        end
    end

    # ============================================================
    # BODY
    # ============================================================

    for (group_i, tp) in enumerate(timepoints)

        group_start =
            (group_i - 1) * n_comparisons + 1

        group_end = group_i * n_comparisons

        group_center = Statistics.mean(
            row_centers[group_start:group_end]
        )

        Plots.annotate!(
            p,
            x_centers[1],
            group_center,
            Plots.text(
                get(timepoint_labels, tp, tp),
                group_fontsize,
                :black,
                :center,
                fontfamily
            )
        )

        for comparison_i in 1:n_comparisons

            row_i = group_start + comparison_i - 1
            y = row_centers[row_i]

            method_x = if method_alignment == :left
                x_edges[2] + method_text_padding
            elseif method_alignment == :right
                x_edges[3] - method_text_padding
            else
                x_centers[2]
            end

            comparison = comparisons[comparison_i]

            Plots.annotate!(
                p,
                method_x,
                y,
                Plots.text(
                    get(
                        difference_labels,
                        comparison,
                        comparison
                    ),
                    body_fontsize,
                    :black,
                    method_alignment,
                    fontfamily
                )
            )

            for (metric_i, metric) in enumerate(metrics)

                value_text = wide_table[
                    row_i,
                    Symbol(metric)
                ]

                Plots.annotate!(
                    p,
                    x_centers[metric_i + 2],
                    y,
                    Plots.text(
                        value_text,
                        body_fontsize,
                        :black,
                        :center,
                        fontfamily
                    )
                )
            end
        end
    end

    # ============================================================
    # LINES
    # ============================================================

    function draw_horizontal(
        y,
        width;
        x_start = 0.0
    )

        Plots.plot!(
            p,
            [x_start, total_width],
            [y, y];
            color = line_color,
            linewidth = width,
            label = ""
        )
    end

    function draw_vertical(x, width)

        Plots.plot!(
            p,
            [x, x],
            [table_bottom, table_top];
            color = line_color,
            linewidth = width,
            label = ""
        )
    end

    if show_header_separator
        draw_horizontal(
            header_bottom,
            header_line_width
        )
    end

    if show_method_separators && show_horizontal_lines

        for group_i in 1:n_groups

            for comparison_i in 1:(n_comparisons - 1)

                row_i =
                    (group_i - 1) * n_comparisons +
                    comparison_i

                y = header_bottom - row_i * row_height

                draw_horizontal(
                    y,
                    method_line_width;
                    x_start = x_edges[2]
                )
            end
        end
    end

    if show_group_separators

        for group_i in 1:(n_groups - 1)

            y = header_bottom -
                group_i * n_comparisons * row_height

            draw_horizontal(
                y,
                group_line_width
            )
        end
    end

    if show_vertical_lines

        for x in x_edges[2:end-1]
            draw_vertical(x, line_width)
        end
    end

    draw_horizontal(
        table_top,
        outer_line_width
    )

    draw_horizontal(
        table_bottom,
        outer_line_width
    )

    if show_outer_border

        draw_vertical(
            0.0,
            outer_line_width
        )

        draw_vertical(
            total_width,
            outer_line_width
        )
    end

    if display_plot
        display(p)
    end

    return (
        summary = summary,
        run_results = run_results,
        table = wide_table,
        plot = p
    )
end
# result = cue_selection_difference_table(
#     cue_correlations;

#     timepoint_labels = Dict(
#         "post_0" => "Crossing Step",
#         "post_100" => "Final Step"
#     ),

#     difference_labels = Dict(
#         "bottom - random" => "Lowest − Random",
#         "bottom - top" => "Lowest − Highest",
#         "random - top" => "Random − Highest"
#     ),

#     metric_labels = Dict(
#         "Network" => "TVD from the\nMean Network",
#         "Column" => "Mean Column-\nNormalized TVD",
#         "Degree reconstructed" => "Degree-Distribution\nTVD"
#     ),

#     # ============================================================
#     # STATISTICAL TESTS
#     # ============================================================

#     n_permutations = 100000,
#     n_bootstrap = 1,
#     confidence_level = 0.95,
#     random_seed = 12345,

#     # ============================================================
#     # NUMBER FORMATTING
#     # ============================================================

#     digits = 3,

#     sd_format = :parentheses,  # :plusminus / :parentheses

#     missing_text = "—",

#     # ============================================================
#     # COLUMN WIDTHS
#     # ============================================================

#     column_headers = [
#         "Time\nPoint",
#         "Difference"
#     ],

#     column_widths = [
#         1.5,  # Timepoint
#         2.4,  # Difference
#         1.8,  # Network
#         1.8,  # Column
#         1.8   # Degree
#     ],

#     method_alignment = :left,  # :left / :center / :right
#     method_text_padding = 0.05,

#     # ============================================================
#     # ROW HEIGHTS
#     # ============================================================

#     row_height = 1.0,
#     header_height = 1.5,
#     header_line_spacing = 0.3,

#     top_padding = 0.15,
#     bottom_padding = 0.15,

#     # ============================================================
#     # TEXT
#     # ============================================================

#     fontfamily = "Calibri",

#     header_fontsize = 12,
#     body_fontsize = 11,
#     group_fontsize = 15,

#     header_bold = true,

#     # ============================================================
#     # LINES
#     # ============================================================

#     show_horizontal_lines = true,
#     show_vertical_lines = true,
#     show_outer_border = true,
#     show_group_separators = true,

#     show_header_separator = true,
#     show_method_separators = false,

#     line_color = :black,

#     line_width = 0.8,
#     outer_line_width = 1.3,
#     group_line_width = 1.1,
#     header_line_width = 1.0,
#     method_line_width = 0.6,

#     # ============================================================
#     # FIGURE
#     # ============================================================

#     figure_size = (1100, 400),
#     dpi = 300,
#     background_color = :white,

#     # ============================================================
#     # OUTPUT
#     # ============================================================

#     print_table = true,
#     print_statistics = true,
#     display_plot = true
# )

function test_maximum_mean_cue_correlations(
    cue_correlations::DataFrames.AbstractDataFrame;

    timepoints = ["post_0", "post_100"],
    metrics = ["Network", "Column", "Degree reconstructed"],

    methods = ["bottom", "random", "top"],

    n_permutations::Int = 100_000,
    expected_runs::Int = 600,
    expected_k::Int = 33,

    random_seed::Int = 12345,
    progress_every::Int = 10_000,

    digits::Int = 4,
    print_results::Bool = true)

    # ============================================================
    # VALIDATION
    # ============================================================

    n_permutations > 0 ||
        error("n_permutations must be positive")

    expected_runs > 0 ||
        error("expected_runs must be positive")

    expected_k > 0 ||
        error("expected_k must be positive")

    length(methods) == 3 &&
    Set(methods) == Set(["bottom", "random", "top"]) ||
        error("methods must contain bottom, random and top")

    comparisons = [
        ("bottom", "random"),
        ("bottom", "top")
    ]

    # ============================================================
    # PREPARE DATA
    # ============================================================

    df = DataFrames.DataFrame(cue_correlations)

    required = [
        :condition,
        :run_number,
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues,
        :r
    ]

    for col in required
        col in propertynames(df) ||
            error("Missing column: $col")
    end

    for col in (
        :condition,
        :timepoint,
        :metric,
        :selection_method
    )
        df[!, col] = string.(df[!, col])
    end

    filter!(
        row ->
            row.timepoint in timepoints &&
            row.metric in metrics &&
            row.selection_method in methods,
        df
    )

    isempty(df) &&
        error("No matching observations found")

    # ============================================================
    # CHECK RUNS AND K VALUES
    # ============================================================

    runs = DataFrames.unique(
        df[:, [:condition, :run_number]]
    )

    DataFrames.sort!(
        runs,
        [:condition, :run_number]
    )

    n_runs = DataFrames.nrow(runs)

    n_runs == expected_runs ||
        error(
            "Expected $expected_runs runs, found $n_runs"
        )

    any(ismissing, df.n_top_cues) &&
        error("Missing K values found")

    any(
        r -> ismissing(r) ||
             !(r isa Real) ||
             !isfinite(r) ||
             abs(r) > 1 + 1e-10,
        df.r
    ) && error("Invalid correlations found")

    k_values = sort(unique(df.n_top_cues))

    length(k_values) == expected_k ||
        error(
            "Expected $expected_k distinct K values, " *
            "found $(length(k_values))"
        )

    n_expected =
        expected_runs *
        length(timepoints) *
        length(metrics) *
        length(methods) *
        expected_k

    DataFrames.nrow(df) == n_expected ||
        error(
            "Expected $n_expected observations, " *
            "found $(DataFrames.nrow(df))"
        )

    # ============================================================
    # BUILD MATRICES ONCE
    # ============================================================

    run_index = Dict(
        (row.condition, row.run_number) => i
        for (i, row) in enumerate(eachrow(runs))
    )

    k_index = Dict(
        k => i for (i, k) in enumerate(k_values)
    )

    matrices = Dict{Tuple{String,String,String},Matrix{Float64}}()

    for tp in timepoints
        for metric in metrics
            for method in methods

                matrices[(tp, metric, method)] =
                    fill(NaN, n_runs, expected_k)

            end
        end
    end

    for row in eachrow(df)

        key = (
            row.timepoint,
            row.metric,
            row.selection_method
        )

        i = run_index[
            (row.condition, row.run_number)
        ]

        j = k_index[row.n_top_cues]

        M = matrices[key]

        isnan(M[i, j]) ||
            error(
                "Duplicate observation: " *
                "run=$i, K=$(row.n_top_cues), " *
                "timepoint=$(row.timepoint), " *
                "metric=$(row.metric), " *
                "method=$(row.selection_method)"
            )

        M[i, j] = Float64(row.r)
    end

    for (key, M) in matrices

        all(isfinite, M) ||
            error(
                "Incomplete data for $key"
            )
    end

    println("\n", "="^75)
    println("DATA INTEGRITY: PASS")
    println("Runs:                $n_runs")
    println("K values:            $(length(k_values))")
    println("Timepoints:          $(length(timepoints))")
    println("Metrics:             $(length(metrics))")
    println("Selection methods:   $(length(methods))")
    println("Observations:        $(DataFrames.nrow(df))")
    println("="^75)

    # ============================================================
    # OBSERVED MAXIMA
    # ============================================================

    maxima_rows = NamedTuple[]
    test_rows = NamedTuple[]

    # Independent random streams for each test
    master_rng = Random.MersenneTwister(random_seed)

    test_seeds = Random.rand(
        master_rng,
        UInt64,
        length(timepoints) *
        length(metrics) *
        length(comparisons)
    )

    test_counter = 0

    # ============================================================
    # ANALYZE EACH TIMEPOINT AND METRIC
    # ============================================================

    for tp in timepoints
        for metric in metrics

            println("\n", "-"^75)
            println("TIMEPOINT: $tp | METRIC: $metric")
            println("-"^75)

            observed = Dict{String,NamedTuple}()

            for method in methods

                M = matrices[(tp, metric, method)]

                mean_by_k = vec(
                    Statistics.mean(M; dims = 1)
                )

                best_index = argmax(mean_by_k)

                best_k = k_values[best_index]
                best_mean = mean_by_k[best_index]

                observed[method] = (
                    best_k = best_k,
                    max_mean = best_mean
                )

                push!(
                    maxima_rows,
                    (
                        timepoint = tp,
                        metric = metric,
                        method = method,
                        best_k = best_k,
                        max_mean = best_mean
                    )
                )
            end

            # ====================================================
            # PERMUTATION TESTS
            # ====================================================

            for (method_a, method_b) in comparisons

                test_counter += 1

                A = matrices[(tp, metric, method_a)]
                B = matrices[(tp, metric, method_b)]

                observed_difference =
                    observed[method_a].max_mean -
                    observed[method_b].max_mean

                rng = Random.MersenneTwister(
                    test_seeds[test_counter]
                )

                # For each run and K:
                # S = A + B
                # D = A - B
                #
                # Swapping method labels within a run
                # corresponds to changing the sign of
                # the entire row of D.

                S = A .+ B
                D = A .- B

                sum_S = vec(sum(S; dims = 1))

                n_k = size(A, 2)

                # Preallocated working vectors
                perm_diff_sum = zeros(Float64, n_k)
                perm_mean_a = zeros(Float64, n_k)
                perm_mean_b = zeros(Float64, n_k)

                signs = Vector{Float64}(undef, n_runs)

                extreme_count = 0

                for permutation in 1:n_permutations

                    # One sign per run, shared across all K
                    for i in 1:n_runs
                        signs[i] =
                            Random.rand(rng, Bool) ?
                            1.0 : -1.0
                    end

                    # D' = signs .* D
                    # Efficient matrix-vector multiplication
                    LinearAlgebra.mul!(
                        perm_diff_sum,
                        transpose(D),
                        signs
                    )

                    # Reconstruct both method means
                    for j in 1:n_k

                        perm_mean_a[j] =
                            (sum_S[j] + perm_diff_sum[j]) /
                            (2 * n_runs)

                        perm_mean_b[j] =
                            (sum_S[j] - perm_diff_sum[j]) /
                            (2 * n_runs)
                    end

                    perm_statistic =
                        maximum(perm_mean_a) -
                        maximum(perm_mean_b)

                    if abs(perm_statistic) >=
                       abs(observed_difference) - 1e-12

                        extreme_count += 1
                    end

                    if progress_every > 0 &&
                       (
                           permutation % progress_every == 0 ||
                           permutation == n_permutations
                       )

                        println(
                            "Test $test_counter/12 | ",
                            "$method_a - $method_b | ",
                            "Permutation ",
                            permutation, "/", n_permutations
                        )
                    end
                end

                p_raw =
                    (extreme_count + 1) /
                    (n_permutations + 1)

                push!(
                    test_rows,
                    (
                        timepoint = tp,
                        metric = metric,
                        comparison = "$method_a - $method_b",
                        observed_difference = observed_difference,
                        p_raw = p_raw,
                        extreme_count = extreme_count,
                        n_permutations = n_permutations
                    )
                )
            end
        end
    end

    maxima = DataFrames.DataFrame(maxima_rows)
    tests = DataFrames.DataFrame(test_rows)

    # ============================================================
    # HOLM CORRECTION ACROSS ALL 12 TESTS
    # ============================================================

    m = DataFrames.nrow(tests)

    m == 12 ||
        error("Expected 12 tests, found $m")

    order = sortperm(tests.p_raw)

    p_holm = zeros(Float64, m)

    running_max = 0.0

    for (rank, idx) in enumerate(order)

        adjusted = min(
            1.0,
            (m - rank + 1) * tests.p_raw[idx]
        )

        running_max = max(
            running_max,
            adjusted
        )

        p_holm[idx] = running_max
    end

    tests[!, :p_holm] = p_holm

    # ============================================================
    # BUILD SIX-ROW SUMMARY TABLE
    # ============================================================

    summary_rows = NamedTuple[]

    for tp in timepoints
        for metric in metrics

            get_max(method) = maxima[
                (maxima.timepoint .== tp) .&
                (maxima.metric .== metric) .&
                (maxima.method .== method),
                :
            ]

            get_test(comparison) = tests[
                (tests.timepoint .== tp) .&
                (tests.metric .== metric) .&
                (tests.comparison .== comparison),
                :
            ]

            bottom = get_max("bottom")
            random = get_max("random")
            top = get_max("top")

            br = get_test("bottom - random")
            bt = get_test("bottom - top")

            push!(
                summary_rows,
                (
                    timepoint = tp,
                    metric = metric,

                    bottom_best_k = bottom.best_k[1],
                    bottom_max_r = bottom.max_mean[1],

                    random_best_k = random.best_k[1],
                    random_max_r = random.max_mean[1],

                    top_best_k = top.best_k[1],
                    top_max_r = top.max_mean[1],

                    bottom_minus_random =
                        br.observed_difference[1],

                    p_raw_bottom_random =
                        br.p_raw[1],

                    p_holm_bottom_random =
                        br.p_holm[1],

                    bottom_minus_top =
                        bt.observed_difference[1],

                    p_raw_bottom_top =
                        bt.p_raw[1],

                    p_holm_bottom_top =
                        bt.p_holm[1]
                )
            )
        end
    end

    summary = DataFrames.DataFrame(summary_rows)

    # ============================================================
    # PRINT RESULTS
    # ============================================================

    if print_results

        println("\n", "="^100)
        println("MAXIMUM MEAN CORRELATIONS AND PERMUTATION TESTS")
        println("="^100)

        # Fixed decimal formatting for console display
        formatted = DataFrames.DataFrame()

        for col in propertynames(summary)

            if eltype(summary[!, col]) <: AbstractFloat

                formatted[!, col] = [
                    Printf.@sprintf(
                        "%.*f",
                        digits,
                        x
                    )
                    for x in summary[!, col]
                ]

            else
                formatted[!, col] = summary[!, col]
            end
        end

        show(
            stdout,
            MIME("text/plain"),
            formatted;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    return (
        summary = summary,
        maxima = maxima,
        tests = tests,
        k_values = k_values
    )
end
# result = test_maximum_mean_cue_correlations(
#     cue_correlations;

#     timepoints = ["post_0", "post_100"],

#     metrics = [
#         "Network",
#         "Column",
#         "Degree reconstructed"
#     ],

#     n_permutations = 100_000,

#     expected_runs = 600,
#     expected_k = 33,

#     random_seed = 12345,

#     progress_every = 10_000,

#     digits = 4,
#     print_results = true
# )


# 3
function test_bottom_peak_up_down(
    cue_correlations::DataFrames.AbstractDataFrame;

    timepoints = ["post_0", "post_100"],
    metrics = ["Network", "Column", "Degree reconstructed"],

    expected_runs::Int = 600,
    expected_k::Int = 33,
    min_points::Int = 3,

    n_permutations::Int = 10_000,
    random_seed::Int = 12345,
    progress_every::Int = 1_000,

    print_results::Bool = true,
    show_plots::Bool = true,

    null_bins::Int = 40,
    figure_size::Tuple{Int,Int} = (1200, 450),
    fontfamily::String = "Calibri",
    dpi::Int = 200)

    # ============================================================
    # VALIDATION
    # ============================================================

    expected_runs > 0 || error("expected_runs must be positive")
    min_points >= 3 || error("min_points must be at least 3")
    expected_k >= min_points ||
        error("expected_k must be >= min_points")
    n_permutations > 0 ||
        error("n_permutations must be positive")
    progress_every >= 0 ||
        error("progress_every must be nonnegative")

    required = [
        :condition, :run_number, :timepoint,
        :metric, :selection_method, :n_top_cues, :r
    ]

    for col in required
        col in propertynames(cue_correlations) ||
            error("Missing column: $col")
    end

    # ============================================================
    # PREPARE DATA
    # ============================================================

    df = DataFrames.DataFrame(
        cue_correlations[
            string.(cue_correlations.selection_method) .== "bottom",
            :
        ]
    )

    df[!, :timepoint] = string.(df.timepoint)
    df[!, :metric] = string.(df.metric)
    df[!, :condition] = string.(df.condition)

    filter!(
        row -> row.timepoint in timepoints &&
               row.metric in metrics,
        df
    )

    isempty(df) && error("No matching Bottom data")

    any(ismissing, df.n_top_cues) &&
        error("Missing K values")

    any(
        r -> ismissing(r) ||
             !(r isa Real) ||
             !isfinite(r) ||
             abs(r) > 1 + 1e-10,
        df.r
    ) && error("Invalid correlations found")

    k_values = sort(unique(df.n_top_cues))

    length(k_values) == expected_k ||
        error("Expected $expected_k K values")

    runs = DataFrames.unique(
        df[:, [:condition, :run_number]]
    )

    DataFrames.sort!(
        runs,
        [:condition, :run_number]
    )

    n_runs = DataFrames.nrow(runs)

    n_runs == expected_runs ||
        error("Expected $expected_runs runs, found $n_runs")

    expected_rows =
        n_runs * expected_k *
        length(timepoints) * length(metrics)

    DataFrames.nrow(df) == expected_rows ||
        error(
            "Expected $expected_rows rows, " *
            "found $(DataFrames.nrow(df))"
        )

    run_index = Dict(
        (row.condition, row.run_number) => i
        for (i, row) in enumerate(eachrow(runs))
    )

    k_index = Dict(
        k => j for (j, k) in enumerate(k_values)
    )

    matrices = Dict{Tuple{String,String},Matrix{Float64}}()

    for tp in timepoints, metric in metrics
        matrices[(tp, metric)] =
            fill(NaN, n_runs, expected_k)
    end

    for row in eachrow(df)

        i = run_index[(row.condition, row.run_number)]
        j = k_index[row.n_top_cues]

        M = matrices[(row.timepoint, row.metric)]

        isnan(M[i, j]) ||
            error("Duplicate observation found")

        M[i, j] = Float64(row.r)
    end

    for (key, M) in matrices
        all(isfinite, M) ||
            error("Incomplete data for $key")
    end

    # ============================================================
    # PEARSON CORRELATION ON A RANGE
    # ============================================================

    x = Float64.(k_values)
    n_k = length(x)

    prefix_x = cumsum(x)
    prefix_x2 = cumsum(x .^ 2)

    function pearson_range(y, first_idx, last_idx)

        n = last_idx - first_idx + 1

        n >= min_points || return missing

        sx = prefix_x[last_idx] -
             (first_idx > 1 ? prefix_x[first_idx-1] : 0.0)

        sx2 = prefix_x2[last_idx] -
              (first_idx > 1 ? prefix_x2[first_idx-1] : 0.0)

        sy = 0.0
        sy2 = 0.0
        sxy = 0.0

        @inbounds for j in first_idx:last_idx
            v = y[j]
            sy += v
            sy2 += v*v
            sxy += x[j]*v
        end

        vx = n*sx2 - sx*sx
        vy = n*sy2 - sy*sy

        if vx <= 0 || vy <= 1e-14
            return missing
        end

        r = (n*sxy - sx*sy) / sqrt(vx*vy)

        return clamp(r, -1.0, 1.0)
    end

    function run_statistics(y)

        peak_idx = argmax(y)

        # ========================================================
        # UPWARD CORRELATION
        # ========================================================

        if peak_idx == 1

            # Peak at the first K:
            # no upward segment
            up = missing
            up_contribution = 0.0

        elseif peak_idx == 2

            # Two points, ending at the maximum:
            # Pearson correlation is exactly +1
            up = 1.0
            up_contribution = 1.0

        else

            # Three or more points
            up = pearson_range(y, 1, peak_idx)
            up_contribution = ismissing(up) ? 0.0 : up

        end

        # ========================================================
        # DOWNWARD CORRELATION
        # ========================================================

        if peak_idx == n_k

            # Peak at the last K:
            # no downward segment
            down = missing
            down_contribution = 0.0

        elseif peak_idx == n_k - 1

            # Two points, starting at the maximum:
            # Pearson correlation is exactly -1
            down = -1.0
            down_contribution = 1.0

        else

            # Three or more points
            down = pearson_range(y, peak_idx, n_k)
            down_contribution = ismissing(down) ? 0.0 : -down

        end

        return (
            peak_k = k_values[peak_idx],
            r_up = up,
            r_down = down,
            up_contribution = up_contribution,
            down_contribution = down_contribution
        )
    end

    # ============================================================
    # RESULT CONTAINERS
    # ============================================================

    test_rows = NamedTuple[]
    observed_rows = NamedTuple[]

    null_distributions =
        Dict{Tuple{String,String,String},Vector{Float64}}()

    plots = Dict{Tuple{String,String},Any}()

    master_rng = Random.MersenneTwister(random_seed)

    seeds = Random.rand(
        master_rng,
        UInt64,
        length(timepoints) * length(metrics)
    )

    analysis_index = 0

    # ============================================================
    # SIX ANALYSES
    # ============================================================

    for tp in timepoints, metric in metrics

        analysis_index += 1

        println("\n", "="^75)
        println(
            "ANALYSIS $analysis_index/6: ",
            "$tp | $metric"
        )
        println("="^75)

        M = matrices[(tp, metric)]

        observed_up = 0.0
        observed_down = 0.0

        missing_up = 0
        missing_down = 0

        for i in 1:n_runs

            s = run_statistics(@view M[i, :])

            observed_up += s.up_contribution
            observed_down += s.down_contribution

            missing_up += ismissing(s.r_up)
            missing_down += ismissing(s.r_down)

            push!(
                observed_rows,
                (
                    timepoint = tp,
                    metric = metric,
                    condition = runs.condition[i],
                    run_number = runs.run_number[i],
                    peak_k = s.peak_k,
                    r_up = s.r_up,
                    r_down = s.r_down
                )
            )
        end

        T_up = observed_up / n_runs
        T_down = observed_down / n_runs

        # ========================================================
        # PERMUTATIONS
        # ========================================================

        rng = Random.MersenneTwister(
            seeds[analysis_index]
        )

        null_up = Vector{Float64}(undef, n_permutations)
        null_down = Vector{Float64}(undef, n_permutations)

        permuted_y = Vector{Float64}(undef, n_k)

        extreme_up = 0
        extreme_down = 0

        for permutation in 1:n_permutations

            sum_up = 0.0
            sum_down = 0.0

            for i in 1:n_runs

                copyto!(permuted_y, @view M[i, :])

                Random.shuffle!(rng, permuted_y)

                s = run_statistics(permuted_y)

                sum_up += s.up_contribution
                sum_down += s.down_contribution
            end

            perm_up = sum_up / n_runs
            perm_down = sum_down / n_runs

            null_up[permutation] = perm_up
            null_down[permutation] = perm_down

            extreme_up += perm_up >= T_up - 1e-12
            extreme_down += perm_down >= T_down - 1e-12

            if progress_every > 0 &&
               (
                   permutation % progress_every == 0 ||
                   permutation == n_permutations
               )

                println(
                    "  Permutation ",
                    permutation, "/", n_permutations
                )
            end
        end

        p_up =
            (extreme_up + 1) / (n_permutations + 1)

        p_down =
            (extreme_down + 1) / (n_permutations + 1)

        null_distributions[(tp, metric, "up")] = null_up
        null_distributions[(tp, metric, "down")] = null_down

        push!(
            test_rows,
            (
                timepoint = tp,
                metric = metric,
                hypothesis = "up",
                direction = "positive",
                observed_statistic = T_up,
                n_runs = n_runs,
                n_valid = n_runs - missing_up,
                n_missing = missing_up,
                null_mean = Statistics.mean(null_up),
                null_sd = Statistics.std(null_up),
                p_raw = p_up
            )
        )

        push!(
            test_rows,
            (
                timepoint = tp,
                metric = metric,
                hypothesis = "down",
                direction = "negative",
                observed_statistic = T_down,
                n_runs = n_runs,
                n_valid = n_runs - missing_down,
                n_missing = missing_down,
                null_mean = Statistics.mean(null_down),
                null_sd = Statistics.std(null_down),
                p_raw = p_down
            )
        )

        # ========================================================
        # NULL DISTRIBUTION PLOTS
        # ========================================================

        p1 = Plots.histogram(
            null_up;
            bins = null_bins,
            normalize = :pdf,
            label = "Permutation null",
            xlabel = "Mean upward correlation",
            ylabel = "Density",
            title = "Upward trend",
            fontfamily = fontfamily
        )

        Plots.vline!(
            p1, [T_up];
            color = :red,
            linestyle = :dash,
            linewidth = 2,
            label = "Observed"
        )

        p2 = Plots.histogram(
            null_down;
            bins = null_bins,
            normalize = :pdf,
            label = "Permutation null",
            xlabel = "Mean negative downward correlation",
            ylabel = "Density",
            title = "Downward trend",
            fontfamily = fontfamily
        )

        Plots.vline!(
            p2, [T_down];
            color = :red,
            linestyle = :dash,
            linewidth = 2,
            label = "Observed"
        )

        combined = Plots.plot(
            p1, p2;
            layout = (1, 2),
            size = figure_size,
            dpi = dpi,
            fontfamily = fontfamily,
            plot_title = "$tp | $metric"
        )

        plots[(tp, metric)] = combined

        if show_plots
            display(combined)
        end

        println(
            "  UP:   T = $(round(T_up, digits=5)), ",
            "valid = $(n_runs-missing_up)/$n_runs, ",
            "p = $(round(p_up, digits=6))"
        )

        println(
            "  DOWN: T = $(round(T_down, digits=5)), ",
            "valid = $(n_runs-missing_down)/$n_runs, ",
            "p = $(round(p_down, digits=6))"
        )
    end

    # ============================================================
    # HOLM CORRECTION ACROSS ALL 12 TESTS
    # ============================================================

    tests = DataFrames.DataFrame(test_rows)

    m = DataFrames.nrow(tests)

    m == 12 ||
        error("Expected 12 tests, found $m")

    order = sortperm(tests.p_raw)

    p_holm = zeros(Float64, m)

    running_max = 0.0

    for (rank, idx) in enumerate(order)

        adjusted = min(
            1.0,
            (m - rank + 1) * tests.p_raw[idx]
        )

        running_max = max(running_max, adjusted)

        p_holm[idx] = running_max
    end

    tests[!, :p_holm] = p_holm

    observed = DataFrames.DataFrame(observed_rows)

    # ============================================================
    # REPORT
    # ============================================================

    if print_results

        println("\n", "="^100)
        println("BOTTOM PEAK — 12 ONE-SIDED PERMUTATION TESTS")
        println("Holm correction across all 12 tests")
        println("="^100)

        show(
            stdout,
            MIME("text/plain"),
            tests;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    return (
        tests = tests,
        observed = observed,
        null_distributions = null_distributions,
        plots = plots,
        k_values = k_values
    )
end
# result_up_down = test_bottom_peak_up_down(
#     cue_correlations;

#     n_permutations = 100_000,
#     random_seed = 12345,
#     progress_every = 1_000,

#     min_points = 3,

#     print_results = true,
#     show_plots = true
# )

function analyze_bottom_peak_k_bootstrap(
    cue_correlations::DataFrames.AbstractDataFrame;

    timepoints = ["post_0", "post_100"],
    metrics = ["Network", "Column", "Degree reconstructed"],

    timepoint_labels = Dict(
        "post_0" => "Crossing",
        "post_100" => "Final"
    ),

    metric_labels = Dict(
        "Network" => "Network",
        "Column" => "Column-normalized",
        "Degree reconstructed" => "Degree distribution"
    ),

    expected_runs::Int = 600,
    expected_k::Int = 33,

    n_bootstrap::Int = 10_000,
    confidence_level::Float64 = 0.95,
    random_seed::Int = 12345,
    progress_every::Int = 1_000,

    # Figure
    figure_size::Tuple{Int,Int} = (1800, 1000),
    dpi::Int = 300,
    fontfamily::String = "Calibri",

    bar_color = :steelblue,
    bar_alpha::Real = 0.85,
    bar_width::Real = 0.85,

    same_y_scale::Bool = true,
    y_max = nothing,

    show_mean::Bool = false,
    show_median::Bool = false,

    show_plot::Bool = true,
    print_tables::Bool = true)

    # ============================================================
    # VALIDATION
    # ============================================================

    n_bootstrap > 0 ||
        error("n_bootstrap must be positive")

    expected_runs >= 2 ||
        error("expected_runs must be at least 2")

    expected_k > 0 ||
        error("expected_k must be positive")

    0.0 < confidence_level < 1.0 ||
        error("confidence_level must be between 0 and 1")

    progress_every >= 0 ||
        error("progress_every must be nonnegative")

    required = [
        :condition,
        :run_number,
        :timepoint,
        :metric,
        :selection_method,
        :n_top_cues,
        :r
    ]

    for col in required
        col in propertynames(cue_correlations) ||
            error("Missing column: $col")
    end

    # ============================================================
    # FILTER BOTTOM DATA
    # ============================================================

    df = DataFrames.DataFrame(
        cue_correlations[
            string.(cue_correlations.selection_method) .== "bottom",
            :
        ]
    )

    df[!, :timepoint] = string.(df.timepoint)
    df[!, :metric] = string.(df.metric)
    df[!, :condition] = string.(df.condition)

    filter!(
        row ->
            row.timepoint in timepoints &&
            row.metric in metrics,
        df
    )

    isempty(df) &&
        error("No matching Bottom observations")

    any(ismissing, df.n_top_cues) &&
        error("Missing K values found")

    any(
        r -> ismissing(r) ||
             !(r isa Real) ||
             !isfinite(r) ||
             abs(r) > 1 + 1e-10,
        df.r
    ) && error("Invalid correlation values found")

    k_values = sort(unique(df.n_top_cues))

    length(k_values) == expected_k ||
        error(
            "Expected $expected_k K values, " *
            "found $(length(k_values))"
        )

    # ============================================================
    # RUN IDENTIFIERS
    # ============================================================

    runs = DataFrames.unique(
        df[:, [:condition, :run_number]]
    )

    DataFrames.sort!(
        runs,
        [:condition, :run_number]
    )

    n_runs = DataFrames.nrow(runs)

    n_runs == expected_runs ||
        error(
            "Expected $expected_runs runs, found $n_runs"
        )

    expected_rows =
        n_runs *
        expected_k *
        length(timepoints) *
        length(metrics)

    DataFrames.nrow(df) == expected_rows ||
        error(
            "Expected $expected_rows observations, " *
            "found $(DataFrames.nrow(df))"
        )

    run_index = Dict(
        (row.condition, row.run_number) => i
        for (i, row) in enumerate(eachrow(runs))
    )

    k_index = Dict(
        k => j
        for (j, k) in enumerate(k_values)
    )

    # ============================================================
    # BUILD MATRICES
    # ============================================================

    matrices = Dict{Tuple{String,String},Matrix{Float64}}()

    for tp in timepoints, metric in metrics
        matrices[(tp, metric)] =
            fill(NaN, n_runs, expected_k)
    end

    for row in eachrow(df)

        i = run_index[
            (row.condition, row.run_number)
        ]

        j = k_index[row.n_top_cues]

        M = matrices[(row.timepoint, row.metric)]

        isnan(M[i, j]) ||
            error(
                "Duplicate observation: " *
                "$(row.condition), $(row.run_number), " *
                "$(row.timepoint), $(row.metric), " *
                "K=$(row.n_top_cues)"
            )

        M[i, j] = Float64(row.r)
    end

    for (key, M) in matrices
        all(isfinite, M) ||
            error("Incomplete data for $key")
    end

    # ============================================================
    # STATISTICS
    # ============================================================

    function calculate_statistics(values)

        q25 = Statistics.quantile(values, 0.25)
        q75 = Statistics.quantile(values, 0.75)

        return (
            mean = Statistics.mean(values),
            median = Statistics.median(values),
            sd = Statistics.std(values),
            q25 = q25,
            q75 = q75,
            iqr = q75 - q25
        )
    end

    # ============================================================
    # RESULTS
    # ============================================================

    summary_rows = NamedTuple[]
    peak_rows = NamedTuple[]
    count_rows = NamedTuple[]

    bootstrap_distributions =
        Dict{Tuple{String,String},Any}()

    peak_distributions =
        Dict{Tuple{String,String},Vector{Float64}}()

    counts =
        Dict{Tuple{String,String},Vector{Int}}()

    alpha = 1.0 - confidence_level

    master_rng = Random.MersenneTwister(random_seed)

    seeds = Random.rand(
        master_rng,
        UInt64,
        length(timepoints) * length(metrics)
    )

    # ============================================================
    # ANALYSIS
    # ============================================================

    analysis_index = 0
    total_analyses = length(timepoints) * length(metrics)

    for tp in timepoints, metric in metrics

        analysis_index += 1

        println("\n", "="^75)
        println(
            "ANALYSIS $analysis_index/$total_analyses: ",
            "$tp | $metric"
        )
        println("="^75)

        M = matrices[(tp, metric)]

        # --------------------------------------------------------
        # PEAK K FOR EACH RUN
        # --------------------------------------------------------

        peak_k = Vector{Float64}(undef, n_runs)

        frequencies = zeros(Int, expected_k)

        for i in 1:n_runs

            peak_idx = argmax(@view M[i, :])

            peak_k[i] = Float64(k_values[peak_idx])

            frequencies[peak_idx] += 1

            push!(
                peak_rows,
                (
                    timepoint = tp,
                    metric = metric,
                    condition = runs.condition[i],
                    run_number = runs.run_number[i],
                    peak_k = k_values[peak_idx],
                    peak_r = M[i, peak_idx]
                )
            )
        end

        peak_distributions[(tp, metric)] = peak_k
        counts[(tp, metric)] = frequencies

        for j in eachindex(k_values)

            push!(
                count_rows,
                (
                    timepoint = tp,
                    metric = metric,
                    K = k_values[j],
                    count = frequencies[j],
                    proportion = frequencies[j] / n_runs
                )
            )
        end

        observed = calculate_statistics(peak_k)

        # --------------------------------------------------------
        # BOOTSTRAP
        # --------------------------------------------------------

        rng = Random.MersenneTwister(
            seeds[analysis_index]
        )

        boot_mean = Vector{Float64}(undef, n_bootstrap)
        boot_median = Vector{Float64}(undef, n_bootstrap)
        boot_sd = Vector{Float64}(undef, n_bootstrap)
        boot_q25 = Vector{Float64}(undef, n_bootstrap)
        boot_q75 = Vector{Float64}(undef, n_bootstrap)
        boot_iqr = Vector{Float64}(undef, n_bootstrap)

        sample = Vector{Float64}(undef, n_runs)

        for b in 1:n_bootstrap

            # Resample runs with replacement
            for i in 1:n_runs

                idx = Random.rand(rng, 1:n_runs)

                sample[i] = peak_k[idx]
            end

            stats = calculate_statistics(sample)

            boot_mean[b] = stats.mean
            boot_median[b] = stats.median
            boot_sd[b] = stats.sd
            boot_q25[b] = stats.q25
            boot_q75[b] = stats.q75
            boot_iqr[b] = stats.iqr

            if progress_every > 0 &&
               (
                   b % progress_every == 0 ||
                   b == n_bootstrap
               )

                println(
                    "  Bootstrap ",
                    b, "/", n_bootstrap
                )
            end
        end

        # --------------------------------------------------------
        # CONFIDENCE INTERVALS
        # --------------------------------------------------------

        function bootstrap_ci(values)

            return (
                Statistics.quantile(values, alpha / 2),
                Statistics.quantile(values, 1 - alpha / 2)
            )
        end

        bootstrap_distributions[(tp, metric)] = (
            mean = boot_mean,
            median = boot_median,
            sd = boot_sd,
            q25 = boot_q25,
            q75 = boot_q75,
            iqr = boot_iqr
        )

        for (name, estimate, boot_values) in [
            ("Mean", observed.mean, boot_mean),
            ("Median", observed.median, boot_median),
            ("SD", observed.sd, boot_sd),
            ("Q25", observed.q25, boot_q25),
            ("Q75", observed.q75, boot_q75),
            ("IQR", observed.iqr, boot_iqr)
        ]

            ci = bootstrap_ci(boot_values)

            push!(
                summary_rows,
                (
                    timepoint = tp,
                    metric = metric,
                    statistic = name,
                    estimate = estimate,
                    ci_lower = ci[1],
                    ci_upper = ci[2],
                    confidence_level = confidence_level,
                    n_runs = n_runs,
                    n_bootstrap = n_bootstrap
                )
            )
        end

        println(
            "  Mean = ",
            round(observed.mean, digits=3),
            " | Median = ",
            round(observed.median, digits=3)
        )

        println(
            "  SD = ",
            round(observed.sd, digits=3),
            " | Q25 = ",
            round(observed.q25, digits=3),
            " | Q75 = ",
            round(observed.q75, digits=3),
            " | IQR = ",
            round(observed.iqr, digits=3)
        )
    end

    # ============================================================
    # PANEL FIGURE
    # ============================================================

    n_rows = length(timepoints)
    n_cols = length(metrics)

    global_ymax = maximum(
        maximum(v) for v in values(counts)
    )

    if y_max !== nothing
        global_ymax = Float64(y_max)
    else
        global_ymax = max(1, ceil(Int, global_ymax * 1.10))
    end

    # Convert K to its location on the categorical axis.
    function k_to_position(k)

        if k <= k_values[1]
            return 1.0
        elseif k >= k_values[end]
            return Float64(length(k_values))
        end

        j = searchsortedlast(k_values, k)

        return j +
            (k - k_values[j]) /
            (k_values[j+1] - k_values[j])
    end

    panels = Any[]

    for (row_idx, tp) in enumerate(timepoints)
        for (col_idx, metric) in enumerate(metrics)

            frequencies = counts[(tp, metric)]
            peak_k = peak_distributions[(tp, metric)]

            positions = 1:length(k_values)

            title_text =
                get(timepoint_labels, tp, tp) *
                " — " *
                get(metric_labels, metric, metric)

            p = Plots.bar(
                positions,
                frequencies;

                bar_width = bar_width,
                color = bar_color,
                alpha = bar_alpha,
                linecolor = :transparent,

                label = "",
                title = title_text,

                xlabel = row_idx == n_rows ?
                    "Number of cues (K)" : "",

                ylabel = col_idx == 1 ?
                    "Number of runs" : "",

                xticks = (
                    collect(positions),
                    string.(k_values)
                ),

                xrotation = 90,
                xlims = (0.3, length(k_values) + 0.7),

                grid = :y,
                fontfamily = fontfamily,
                legend = false
            )

            if same_y_scale
                Plots.ylims!(p, (0, global_ymax))
            elseif y_max !== nothing
                Plots.ylims!(p, (0, Float64(y_max)))
            end

            if show_mean

                mean_k = Statistics.mean(peak_k)

                Plots.vline!(
                    p,
                    [k_to_position(mean_k)];
                    color = :red,
                    linewidth = 2,
                    label = ""
                )
            end

            if show_median

                median_k = Statistics.median(peak_k)

                Plots.vline!(
                    p,
                    [k_to_position(median_k)];
                    color = :darkgreen,
                    linestyle = :dash,
                    linewidth = 2,
                    label = ""
                )
            end

            push!(panels, p)
        end
    end

    combined_plot = Plots.plot(
        panels...;

        layout = (n_rows, n_cols),
        size = figure_size,
        dpi = dpi,
        fontfamily = fontfamily,

        left_margin = 6Plots.mm,
        bottom_margin = 9Plots.mm,
        top_margin = 4Plots.mm
    )

    if show_plot
        display(combined_plot)
    end

    # ============================================================
    # OUTPUT TABLES
    # ============================================================

    summary = DataFrames.DataFrame(summary_rows)
    peaks = DataFrames.DataFrame(peak_rows)
    peak_counts = DataFrames.DataFrame(count_rows)

    if print_tables

        println("\n", "="^100)
        println("BOTTOM PEAK K — BOOTSTRAP CONFIDENCE INTERVALS")
        println("="^100)

        show(
            stdout,
            MIME("text/plain"),
            summary;
            allrows = true,
            allcols = true,
            truncate = 0
        )

        println()
    end

    return (
        summary = summary,
        peaks = peaks,
        peak_counts = peak_counts,
        peak_distributions = peak_distributions,
        bootstrap_distributions = bootstrap_distributions,
        plot = combined_plot,
        k_values = k_values
    )
end
