#region Appendix A


function analyze_steyvers_networks(;
    num_networks::Int = 50,
    n::Int = 5018,
    m::Int = 11,
    change::Float64 = 0.0,
    gamma_bins::Int = 20)

    @assert num_networks > 0
    @assert n > m >= 2
    @assert gamma_bins >= 2

    # Store the degree of every node in every network
    all_degrees = Matrix{Int}(
        undef, num_networks, n
    )

    # Store network-level metrics
    metrics = DataFrames.DataFrame(
        network = Int[],
        mean_degree = Float64[],
        L = Float64[],
        C = Float64[],
        D = Int[],
        gamma = Float64[]
    )

    # Estimate the power-law exponent using
    # logarithmically spaced degree bins and
    # linear regression in log-log space.
    function estimate_gamma(degrees::AbstractVector{<:Integer})

        positive_degrees = degrees[degrees .> 0]

        k_min = minimum(positive_degrees)
        k_max = maximum(positive_degrees)

        if k_min == k_max
            return NaN
        end

        edges = exp.(
            range(
                log(Float64(k_min)),
                log(Float64(k_max) + 1.0);
                length = gamma_bins + 1
            )
        )

        x = Float64[]
        y = Float64[]

        for b in 1:gamma_bins

            lower = edges[b]
            upper = edges[b + 1]

            count = sum(
                (positive_degrees .>= lower) .&
                (positive_degrees .< upper)
            )

            if count == 0
                continue
            end

            # Density adjusted for logarithmic bin width
            density = count / (
                length(positive_degrees) * (upper - lower)
            )

            midpoint = sqrt(lower * upper)

            push!(x, log(midpoint))
            push!(y, log(density))
        end

        if length(x) < 2
            return NaN
        end

        # Ordinary least-squares slope
        slope = sum(
            (x .- Statistics.mean(x)) .*
            (y .- Statistics.mean(y))
        ) / sum(
            (x .- Statistics.mean(x)) .^ 2
        )

        return -slope
    end

    # Analyze one graph
    function calculate_metrics(g::Graphs.AbstractGraph)

        degrees = Int.(Graphs.degree(g))

        mean_degree = Statistics.mean(degrees)

        # Mean local clustering coefficient
        local_C = Graphs.local_clustering_coefficient(
            g,
            collect(Graphs.vertices(g))
        )
        C = Statistics.mean(local_C)

        # Compute shortest paths from every vertex.
        # Accumulate distances without storing an n×n matrix.
        total_distance = 0.0
        diameter = 0

        for source in Graphs.vertices(g)

            distances = Graphs.gdistances(g, source)

            if any(d -> d == typemax(eltype(distances)), distances)
                error("Network is disconnected.")
            end

            total_distance += sum(distances)
            diameter = max(diameter, maximum(distances))
        end

        nv = Graphs.nv(g)

        L = total_distance / (nv * (nv - 1))
        gamma = estimate_gamma(degrees)

        return (
            degrees = degrees,
            mean_degree = mean_degree,
            L = L,
            C = C,
            D = diameter,
            gamma = gamma
        )
    end

    println("Starting Steyvers-Tenenbaum network analysis")
    println("Networks: $num_networks | n = $n | m = $m")
    println("--------------------------------------------")

    for run in 1:num_networks

        start_time = time()

        println("Network $run / $num_networks: generating...")

        # A new base network is generated independently
        # in every call. With change=0, the returned
        # participant network is identical to that base.
        networks = make_agents_with_outliers(
            1, n, m, change;
            outliers_count = 0
        )

        network = @view networks[:, :, 1]

        # Convert adjacency matrix to an undirected graph
        g = Graphs.SimpleGraph(network)

        println("Network $run / $num_networks: calculating metrics...")

        result = calculate_metrics(g)

        all_degrees[run, :] .= result.degrees

        push!(
            metrics,
            (
                run,
                result.mean_degree,
                result.L,
                result.C,
                result.D,
                result.gamma
            )
        )

        elapsed = round(time() - start_time; digits = 1)

        println(
            "Completed $run / $num_networks | " *
            "L=$(round(result.L, digits=3)) | " *
            "C=$(round(result.C, digits=3)) | " *
            "D=$(result.D) | " *
            "gamma=$(round(result.gamma, digits=3)) | " *
            "$(elapsed)s"
        )
    end

    # Summary table
    summary = DataFrames.DataFrame(
        metric = String[],
        mean = Float64[],
        sd = Float64[]
    )

    for (column, label) in [
        (:mean_degree, "Mean degree"),
        (:L, "Average shortest path (L)"),
        (:C, "Clustering coefficient (C)"),
        (:D, "Diameter (D)"),
        (:gamma, "Power-law exponent (gamma)")
    ]

        values = Float64.(metrics[!, column])
        valid = filter(isfinite, values)

        push!(
            summary,
            (
                label,
                isempty(valid) ? NaN : Statistics.mean(valid),
                length(valid) > 1 ? Statistics.std(valid) : NaN
            )
        )
    end

    println()
    println("============================================")
    println("Analysis completed")
    println("============================================")
    println(summary)

    return (
        metrics = metrics,
        degrees = all_degrees,
        summary = summary
    )
end
