function analyze_random_networks(;
    num_networks::Int = 50,
    n::Int = 5018,
    m::Int = 11,
    gamma_bins::Int = 20)

    @assert num_networks > 0
    @assert n > m >= 2
    @assert gamma_bins >= 2

    # Exact number of edges in the semantic growth model
    E = (m * (m - 1)) ÷ 2 + m * (n - m)

    all_degrees = Matrix{Int}(undef, num_networks, n)

    metrics = DataFrames.DataFrame(
        network = Int[],
        mean_degree = Float64[],
        L = Float64[],
        C = Float64[],
        D = Int[],
        gamma = Float64[]
    )

    function estimate_gamma(degrees::AbstractVector{<:Integer})

        positive_degrees = degrees[degrees .> 0]

        if isempty(positive_degrees)
            return NaN
        end

        k_min = minimum(positive_degrees)
        k_max = maximum(positive_degrees)

        if k_min == k_max
            return NaN
        end

        edges = exp.(
            range(
                log(Float64(k_min)),
                log(Float64(k_max) + 1.0);
                length = gamma_bins + 1
            )
        )

        x = Float64[]
        y = Float64[]

        for b in 1:gamma_bins

            lower = edges[b]
            upper = edges[b + 1]

            count = sum(
                (positive_degrees .>= lower) .&
                (positive_degrees .< upper)
            )

            if count == 0
                continue
            end

            density = count / (
                length(positive_degrees) * (upper - lower)
            )

            midpoint = sqrt(lower * upper)

            push!(x, log(midpoint))
            push!(y, log(density))
        end

        if length(x) < 2
            return NaN
        end

        mean_x = Statistics.mean(x)
        mean_y = Statistics.mean(y)

        slope = sum(
            (x .- mean_x) .* (y .- mean_y)
        ) / sum(
            (x .- mean_x) .^ 2
        )

        return -slope
    end

    function calculate_metrics(g::Graphs.AbstractGraph)

        degrees = Int.(Graphs.degree(g))
        mean_degree = Statistics.mean(degrees)

        local_C = Graphs.local_clustering_coefficient(
            g,
            collect(Graphs.vertices(g))
        )

        C = Statistics.mean(local_C)

        total_distance = 0.0
        diameter = 0
        nv = Graphs.nv(g)

        for source in Graphs.vertices(g)

            distances = Graphs.gdistances(g, source)

            if any(d -> d == typemax(eltype(distances)), distances)
                error("Network is disconnected.")
            end

            total_distance += sum(distances)
            diameter = max(diameter, maximum(distances))
        end

        L = total_distance / (nv * (nv - 1))
        gamma = estimate_gamma(degrees)

        return (
            degrees = degrees,
            mean_degree = mean_degree,
            L = L,
            C = C,
            D = diameter,
            gamma = gamma
        )
    end

    println("Starting Erdős–Rényi network analysis")
    println("Networks: $num_networks | n = $n | m = $m | E = $E")
    println("--------------------------------------------")

    for run in 1:num_networks

        start_time = time()

        println("Network $run / $num_networks: generating...")

        # G(n,E): exactly E edges, placed randomly
        attempt = 0
        g = Graphs.SimpleGraph(n)

        while true
            attempt += 1

            g = Graphs.erdos_renyi(n, E; is_directed = false)

            if Graphs.is_connected(g)
                break
            end

            println(
                "Network $run / $num_networks: " *
                "attempt $attempt was disconnected. Regenerating..."
            )
        end

        println("Network $run / $num_networks: calculating metrics...")

        result = calculate_metrics(g)

        all_degrees[run, :] .= result.degrees

        push!(
            metrics,
            (
                run,
                result.mean_degree,
                result.L,
                result.C,
                result.D,
                result.gamma
            )
        )

        elapsed = round(time() - start_time; digits = 1)

        println(
            "Completed $run / $num_networks | " *
            "L=$(round(result.L, digits=3)) | " *
            "C=$(round(result.C, digits=3)) | " *
            "D=$(result.D) | " *
            "gamma=$(round(result.gamma, digits=3)) | " *
            "$(elapsed)s"
        )
    end

    summary = DataFrames.DataFrame(
        metric = String[],
        mean = Float64[],
        sd = Float64[]
    )

    for (column, label) in [
        (:mean_degree, "Mean degree"),
        (:L, "Average shortest path (L)"),
        (:C, "Clustering coefficient (C)"),
        (:D, "Diameter (D)"),
        (:gamma, "Power-law exponent (gamma)")
    ]

        values = Float64.(metrics[!, column])
        valid = filter(isfinite, values)

        push!(
            summary,
            (
                label,
                isempty(valid) ? NaN : Statistics.mean(valid),
                length(valid) > 1 ? Statistics.std(valid) : NaN
            )
        )
    end

    println()
    println("============================================")
    println("Random network analysis completed")
    println("============================================")
    println(summary)

    return (
        metrics = metrics,
        degrees = all_degrees,
        summary = summary
    )
end
